INSERT INTO public.movie_trivia ("id", "film_id", "categoria", "titolo", "descrizione", "fonte", "approvato", "inserito_da", "provenienza", "likes", "ordine", "created_at") VALUES
('78c2d7e2-d81e-434f-9e91-d9fc31392af8', 77, 'Segreti di produzione', 'La riproduzione a grandezza naturale del set dell''hangar', 'Per girare la sequenza iniziale della battaglia sopra il pianeta D''Qar, la produzione ha costruito all''interno dei Pinewood Studios il set più grande mai realizzato per la trilogia sequel, comprendente una sezione dettagliata e calpestabile della nave di classe Raddus.', 'The Director and the Jedi - Documentario ufficiale', TRUE, 'IA (Daily Sync)', 'IA Verificata', 0, 0, '2026-11-02T09:56:03.98558+00:00'),
('321a9a23-7422-40fe-bc2d-fdd556ca63b2', 77, 'Aneddoti dal set', 'La cicatrice modificata di Kylo Ren', 'Il regista Rian Johnson ha ammesso di aver modificato la posizione della cicatrice sul volto di Adam Driver rispetto al film precedente, spostandola leggermente perché la precedente copriva troppo l''occhio dell''attore, scatenando iniziali dibattiti tra i fan più attenti.', 'Intervista ufficiale di Rian Johnson su Empire Magazine', TRUE, 'IA (Daily Sync)', 'IA Verificata', 0, 1, '2026-11-02T09:56:03.98558+00:00'),
('8c8bfff2-77f7-4972-8def-47f0d3829b18', 77, 'Curiosità & Retroscena', 'Il cameo di Gareth Edwards', 'Gareth Edwards, regista di ''Rogue One: A Star Wars Story'', appare in un cameo non accreditato nel film interpretando un soldato della Resistenza nelle trincee del pianeta minerario Crait, riconoscibile mentre assaggia il sale a terra.', 'The Director and the Jedi - Documentario dietro le quinte', TRUE, 'IA (Daily Sync)', 'IA Verificata', 0, 2, '2026-11-02T09:56:03.98558+00:00'),
('991b0fe2-f7fc-4ba1-a837-4bd17d9011aa', 77, 'Curiosità & Retroscena', 'L''assenza di J.J. Abrams nella scrittura', 'A differenza di quanto avvenuto per Episodio VII e IX, Rian Johnson è stato l''unico sceneggiatore accreditato di ''Gli ultimi Jedi'', lavorando alla sceneggiatura basandosi unicamente sulle sue idee e sui trattamenti iniziali lasciati da George Lucas per la trilogia.', 'Note di produzione ufficiali Lucasfilm', TRUE, 'IA (Daily Sync)', 'IA Verificata', 0, 3, '2026-11-02T09:56:03.98558+00:00'),
('fedbc7ce-4874-4a48-b4af-5859c1f2c73b', 77, 'Effetti speciali & Trucco', 'Le manovre di volo della A-Wing nel canone', 'Per le sequenze di combattimento spaziale, la produzione ha consultato gli archivi della Industrial Light & Magic per aggiornare i modelli digitali dei caccia A-Wing, introducendo varianti strutturali mai viste nei film della trilogia classica.', 'The Art of Star Wars: The Last Jedi - Libro ufficiale', TRUE, 'IA (Daily Sync)', 'IA Verificata', 0, 4, '2026-11-02T09:56:03.98558+00:00'),
('131d7a4a-76d0-42e6-a445-36e5ebdc57ef', 77, 'Casting & Scelte', 'Noah Segan e il pilota della Resistenza', 'L''attore statunitense Noah Segan, amico di lunga data e collaboratore ricorrente del regista Rian Johnson in film come ''Brick'' e ''Looper'', appare nel film nel ruolo del pilota della Resistenza Starmer Dix.', 'Crediti ufficiali del film', TRUE, 'IA (Daily Sync)', 'IA Verificata', 0, 5, '2026-11-02T09:56:03.98558+00:00'),
('eceb5ef2-6b2d-4d78-a904-176cbe462056', 143, 'Segreti di produzione', 'Il budget iniziale e il cambio di titolo originale', 'Il film ricevette un budget di circa 18 milioni di dollari e durante le prime fasi di sviluppo e pre-produzione fu intitolato provvisoriamente ''Jaws 3, People 0'', un gioco di parole che fu successivamente scartato in favore del più diretto ''Jaws 3-D''.', 'Production notes Universal Pictures / Archivi storici della produzione', TRUE, 'IA (Daily Sync)', 'IA Verificata', 0, 0, '2026-11-02T10:07:03.135284+00:00'),
('97950110-349b-4be3-b9e2-3d90f936c308', 143, 'Casting & Scelte', 'L''esordio alla regia di Joe Alves', 'Joe Alves, che aveva lavorato come production designer e direttore della seconda unità nei primi due capitoli della saga, fece ufficialmente il suo esordio alla regia proprio con ''Lo squalo 3'', sfruttando la sua profonda conoscenza tecnica ed estetica del franchise.', 'Press kit ufficiale del film del 1983', TRUE, 'IA (Daily Sync)', 'IA Verificata', 0, 1, '2026-11-02T10:07:03.135284+00:00'),
('61e7aa39-4372-4e2e-91dd-b4e49746752d', 143, 'Curiosità & Retroscena', 'Il cameo di John Putch e l''eredità televisiva', 'John Putch, che nel film interpreta il personaggio di Sean Brody, era figlio dell''attrice Jean Stapleton e aveva già recitato in diverse produzioni televisive prima di entrare a far parte del cast di questo terzo capitolo.', 'Dizionario del Cinema di Cast e Crediti ufficiali', TRUE, 'IA (Daily Sync)', 'IA Verificata', 0, 2, '2026-11-02T10:07:03.135284+00:00'),
('99f3019f-cca5-436c-a26a-dc2ab31a1430', 143, 'Curiosità & Retroscena', 'I problemi legali e la concorrenza con il 3D di Spooktacular', 'La scelta di girare in 3D stereoscopico arrivò sull''onda del successo di ''Comin'' at Ya!'' del 1981, ma la produzione dovette affrontare notevoli pressioni tecniche per adattare le cineprese stereoscopiche alle riprese subacquee all''interno delle vasche di SeaWorld.', 'Documentario retrospettivo sulla produzione stereoscopica', TRUE, 'IA (Daily Sync)', 'IA Verificata', 0, 3, '2026-11-02T10:07:03.135284+00:00'),
('15777c7e-5739-4cda-9930-c3d474691b99', 143, 'Segreti di produzione', 'La composizione della colonna sonora di Alan Parker', 'A differenza dei primi due film iconicamente musicati da John Williams, la colonna sonora di ''Lo squalo 3'' fu affidata al compositore britannico Alan Parker, il quale rielaborò parzialmente i celebri temi originali integrandoli con partiture di stampo elettronico e sinfonico.', 'Note di copertina dell''edizione discografica della colonna sonora (1983)', TRUE, 'IA (Daily Sync)', 'IA Verificata', 0, 4, '2026-11-02T10:07:03.135284+00:00'),
('6115ba36-bd4a-41de-b8a0-e8f7293c11ac', 146, 'Aneddoti dal set', 'L''infortunio di Daryl Hannah sul set', 'Durante le riprese della sequenza in cui Pris fugge da Sebastian, Daryl Hannah scivolò accidentalmente su un tratto di asfalto bagnato e sfondò con il gomito il lunotto di un furgone della produzione, procurandosi una brutta ferita che richiamó otto punti di sutura.', 'Documentario ''Dangerous Days: Making Blade Runner''', TRUE, 'IA (Daily Sync)', 'IA Verificata', 0, 0, '2026-11-02T10:07:19.326887+00:00'),
('bc1e3dc8-10a9-4d1a-bed5-b120d3cf9bf7', 146, 'Casting & Scelte', 'La vera origine del linguaggio di Gaff', 'Il misterioso idioma parlato da Edward James Olmos nei panni di Gaff (la cosiddetta ''Cityspeak'') fu inventato dallo stesso attore mescolando ungheresi, spagnolo, giapponese, tedesco e francese, prendendo spunto da un anziano lustrascarpe incontrato a Los Angeles.', 'Intervista ufficiale a Edward James Olmos / Note di produzione', TRUE, 'IA (Daily Sync)', 'IA Verificata', 0, 1, '2026-11-02T10:07:19.326887+00:00'),
('559f531b-f8b4-4a59-9c3f-882757330ecf', 146, 'Effetti speciali & Trucco', 'Il modello in miniatura della mano di Roy Batty', 'Per girare la drammatica scena in cui Roy Batty si trafigge la mano con un chiodo per contrastare il blocco neuromuscolare, gli effetti speciali crearono una mano protesica in lattice indossata da Rutger Hauer, collegata a tubicini nascosti per pompare il sangue finto.', 'Archivio degli effetti visivi di Douglas Trumbull', TRUE, 'IA (Daily Sync)', 'IA Verificata', 0, 2, '2026-11-02T10:07:19.326887+00:00'),
('03aab76a-f48b-4117-bba1-dc76c22fc5b2', 146, 'Citazioni & Easter Egg', 'Il cameo vocale di Ridley Scott', 'All''inizio del film, nella scena in cui Rick Deckard viene prelevato dalla polizia da Gaff, la voce metallica dell''altoparlante dello Spinner che ordina a Deckard di salire a bordo appartiene in realtà al regista Ridley Scott.', 'Commento audio del regista (Blade Runner Director''s Cut DVD)', TRUE, 'IA (Daily Sync)', 'IA Verificata', 0, 3, '2026-11-02T10:07:19.326887+00:00'),
('05363c6c-a9a6-42f6-a824-be3aca6237b6', 146, 'Segreti di produzione', 'Il brano ''One More Kiss, Dear'' e i problemi di copyright', 'La canzone retrò suonata mentre Deckard entra nel bar dove incontra Zhora fu composta da Vangelis insieme al paroliere Peter Skellern, il quale registrò anche la voce; la traccia richiese complesse trattative legali per l''utilizzo dei diritti d''autore d''epoca.', 'Note di copertina della colonna sonora ufficiale di Vangelis', TRUE, 'IA (Daily Sync)', 'IA Verificata', 0, 4, '2026-11-02T10:07:19.326887+00:00'),
('1b38a668-9ecb-472f-9abd-343c9589b8c1', 219, 'Segreti di produzione', 'Il contratto milionario con la Cines', 'Per la realizzazione di ''Quo Vadis?'', la Cines investì una cifra record per l''epoca, circa 120.000 lire dell''epoca, un budget senza precedenti che rese la produzione italiana la più costosa fino ad allora concepita.', 'Archivio Storico della Cines e studi storiografici di Aldo Bernardini', TRUE, 'IA (Daily Sync)', 'IA Verificata', 0, 0, '2026-11-02T10:14:04.033728+00:00'),
('3863bc15-7161-461f-a6da-ec90d088c837', 78, 'Segreti di produzione', 'La modifica dell''arco narrativo di Colin Trevorrow', 'Prima dell''ingaggio di J.J. Abrams, il regista Colin Trevorrow aveva sviluppato una versione differente del Episodio IX intitolata ''Duel of the Fates'', la cui sceneggiatura prevedeva una ribellione su Coruscant e un ruolo centrale per Rose Tico, elementi poi completamente scartati o riscritti dopo l''abbandono di Trevorrow per divergenze creative con la Lucasfilm.', 'Documenti di produzione e concept art ufficiali pubblicati post-uscita', TRUE, 'IA (Daily Sync)', 'IA Verificata', 0, 0, '2026-11-02T09:56:12.071452+00:00'),
('e41ea0b4-4be0-4b3c-a647-7601719b492f', 78, 'Citazioni & Easter Egg', 'Il cameo del figlio di J.J. Abrams', 'Henry Abrams, figlio del regista J.J. Abrams, ha fatto una breve apparizione non accreditata nel film nei panni di un ufficiale della Resistenza all''interno della base segreta di Ajan Kloss, un piccolo omaggio familiare inserito nella sequenza della riunione dei ribelli.', 'Crediti del film e note ufficiali del regista', TRUE, 'IA (Daily Sync)', 'IA Verificata', 0, 1, '2026-11-02T09:56:12.071452+00:00'),
('d57aff7a-a3a4-4a8e-85e3-1aae676e7746', 78, 'Casting & Scelte', 'La rielaborazione del personaggio di Rose Tico', 'Nonostante le polemiche sul ridotto minutaggio riservato a Kelly Marie Tran nei panni di Rose Tico, la co-sceneggiatrice Chris Terrio ha spiegato che molte delle scene originariamente girate con l''attrice dovettero essere tagliate o modificate poiché l''utilizzo del materiale d''archivio di Carrie Fisher imponeva interazioni digitali complesse e vincolanti per la continuità visiva.', 'Interviste stampa ufficiali di Chris Terrio e J.J. Abrams', TRUE, 'IA (Daily Sync)', 'IA Verificata', 0, 2, '2026-11-02T09:56:12.071452+00:00'),
('382f3043-ddc5-4d67-8157-5918c3fa40ca', 78, 'Casting & Scelte', 'La partecipazione straordinaria di Dominic Monaghan', 'L''attore Dominic Monaghan, noto per aver interpretato Merry in ''Il Signore degli Anelli'' e per aver lavorato con J.J. Abrams nella serie TV ''Lost'', ha ottenuto il ruolo del combattente della Resistenza Beaumont Kin dopo aver esplicitamente chiesto al regista di poter partecipare, anche solo come comparsa con battute.', 'Intervista ufficiale a Dominic Monaghan durante il press tour', TRUE, 'IA (Daily Sync)', 'IA Verificata', 0, 3, '2026-11-02T09:56:12.071452+00:00'),
('f0d50545-b000-4621-8c6c-abf721e16bbd', 78, 'Effetti speciali & Trucco', 'Il ritorno fisico del costume originale di Wedge Antilles', 'Per il ritorno del veterano pilota della Ribellione Wedge Antilles, interpretato nuovamente da Denis Lawson dopo decenni, la costumista Michael Kaplan ha dovuto ricostruire fedelmente l''iconica tenuta da volo arancione originale della trilogia classica, adattandola all''età dell''attore.', 'The Art of Star Wars: The Rise of Skywalker', TRUE, 'IA (Daily Sync)', 'IA Verificata', 0, 4, '2026-11-02T09:56:12.071452+00:00'),
('a2d205ac-dc17-4d68-8a97-7305dd902e1a', 144, 'Effetti speciali & Trucco', 'La cicatrice di Aldo Raine e il mistero del collo', 'Il grande segno sul collo del tenente Aldo Raine, interpretato da Brad Pitt, non è mai spiegato esplicitamente nel montaggio finale del film. Quentin Tarantino aveva originariamente girato una sequenza esplicativa in cui si raccontava che Raine era sopravvissuto a un tentativo di linciaggio per impiccagione nel Tennessee, scena poi tagliata per migliorare il ritmo della narrazione.', 'Commento audio del regista / Note di sceneggiatura ufficiali', TRUE, 'IA (Daily Sync)', 'IA Verificata', 0, 0, '2026-11-02T10:07:11.278823+00:00'),
('b18964ea-2b9b-49e0-89b9-49ba2e632c41', 144, 'Casting & Scelte', 'La vera lingua tedesca di B.J. Novak', 'L''attore B.J. Novak, noto soprattutto per la serie TV ''The Office'' e scelto per interpretare il soldato Smithson Utivich, conosceva già bene la lingua tedesca prima delle riprese. Aveva infatti studiato tedesco all''università di Harvard, il che gli ha permesso di gestire con maggiore naturalezza i dialoghi in lingua durante le scene corali.', 'Intervista ufficiale durante il tour promozionale del film', TRUE, 'IA (Daily Sync)', 'IA Verificata', 0, 1, '2026-11-02T10:07:11.278823+00:00'),
('658d537b-a56e-493d-8f99-069b1b8feb17', 144, 'Citazioni & Easter Egg', 'Il cameo di Harvey Keitel nei panni del generale', 'Harvey Keitel, storico collaboratore di Quentin Tarantino fin dai tempi di ''Le iene'', appare nel film in un cameo vocale non accredito. È sua infatti la voce del generale americano George S. Patton che si sente all''inizio della trasmissione radiofonica ascoltata dal tenente Aldo Raine.', 'Crediti di produzione e interviste al cast tecnico', TRUE, 'IA (Daily Sync)', 'IA Verificata', 0, 2, '2026-11-02T10:07:11.278823+00:00'),
('27ba4711-568b-4277-8b40-f06fae832c63', 144, 'Casting & Scelte', 'La cicatura reale di Rod Taylor', 'L''attore australiano Rod Taylor, celebre per aver interpretato ''Gli uccelli'' di Alfred Hitchcock, fu fortemente voluto da Quentin Tarantino per il ruolo del proprietario di cinema Winston Churchill. Per Taylor si trattò dell''ultima apparizione cinematografica prima della sua scomparsa nel 2015, fortemente voluta da Tarantino che lo considerava un suo idolo personale d''infanzia.', 'Note di produzione e interviste biografiche dell''attore', TRUE, 'IA (Daily Sync)', 'IA Verificata', 0, 3, '2026-11-02T10:07:11.278823+00:00'),
('9c8a84c6-b47a-4add-9df2-2780448e5a5d', 144, 'Segreti di produzione', 'Il doppiaggio tedesco e la rimozione del saluto nazista', 'Nella versione cinematografica distribuita in Germania, la legge federale vieta l''esposizione pubblica di simboli anticostituzionali e legati al regime nazista, come la svastica e il saluto ''Heil Hitler''. Per l''edizione tedesca del film è stato quindi necessario applicare modifiche digitali per rimuovere i simboli e alterare l''audio del celebre saluto nazista nella scena della taverna.', 'Reportage sulle distribuzioni internazionali e normative di censura tedesche', TRUE, 'IA (Daily Sync)', 'IA Verificata', 0, 4, '2026-11-02T10:07:11.278823+00:00'),
('df1e17da-e151-4524-a7b0-4590ca7a1330', 219, 'Curiosità & Retroscena', 'La prima proiezione pubblica al Teatro Costanzi', 'Il film fu presentato in anteprima mondiale il 29 aprile 1913 al Teatro Costanzi di Roma, alla presenza della famiglia reale e di esponenti dell''alta aristocrazia, registrando un trionfo di pubblico e critica.', 'Cronache cinematografiche de ''La Tribuna'', aprile 1913', TRUE, 'IA (Daily Sync)', 'IA Verificata', 0, 1, '2026-11-02T10:14:04.033728+00:00'),
('12f56130-6634-4b62-8d19-799a182267e1', 219, 'Casting & Scelte', 'Il debutto cinematografico di Lea Giunchi', 'L''attrice Lea Giunchi, che nel film interpreta con grande intensità il ruolo di Licia, proveniva dalle file del teatro popolare e fu una delle prime dive italiane a comprendere la specificità della recitazione cinematografica rispetto a quella teatrale.', 'Memorie e biografie del cinema muto italiano', TRUE, 'IA (Daily Sync)', 'IA Verificata', 0, 2, '2026-11-02T10:14:04.033728+00:00'),
('9274f251-5bf6-4e11-a4d0-f3a94f012ec8', 236, 'Casting & Scelte', 'La regola della recitazione senza sguardi nello specchio per Bruce Willis', 'Terry Gilliam consegnò a Bruce Willis una lista di regole di recitazione per il suo personaggio, inclusa la direttiva di non recitare mai in modo da compiacersi della propria immagine o di cercare l''inquadratura perfetta. Il regista voleva smontare l''immagine da duro e action hero a cui l''attore era abituato, spingendolo a una vulnerabilità inedita sullo schermo.', 'Commento audio del regista Terry Gilliam e del produttore Charles Roven nell''edizione DVD', TRUE, 'IA (Daily Sync)', 'IA Verificata', 0, 0, '2026-11-02T10:20:07.260077+00:00'),
('1ee52c16-0067-4c3d-a755-0ce4359220eb', 236, 'Effetti speciali & Trucco', 'L''uso di una protesi dentale speciale per Brad Pitt', 'Per accentuare l''aspetto erratico e caotico di Jeffrey Goines, Brad Pitt indossava un apparecchio dentale speciale che alterava leggermente la sua dizione e il suo sorriso. L''attore ha lavorato a stretto contatto con il reparto trucco e costumi per rendere la fisicità del personaggio il più fastidiosa e imprevedibile possibile.', 'Documentario The Making of Twelve Monkeys', TRUE, 'IA (Daily Sync)', 'IA Verificata', 0, 1, '2026-11-02T10:20:07.260077+00:00'),
('cd48fafa-ab7c-48bf-b448-7dd226ee93f2', 79, 'Casting & Scelte', 'La voce originale di Dart Fener doppiata in seguito', 'Durante le riprese sul set, le battute di Dart Fener furono recitate dall''attore britannico David Prowse. Tuttavia, George Lucas ritenne la sua voce troppo poco minacciosa e dal forte accento del West Country, decidendo di sostituirla in post-produzione con quella profonda e iconica di James Earl Jones.', 'Documentario ufficiale ''Empire of Dreams: The Story of the Star Wars Trilogy''', TRUE, 'IA (Daily Sync)', 'IA Verificata', 0, 0, '2026-11-02T09:56:21.006919+00:00'),
('8ee0d7a5-047c-4358-b58d-8ea7dc18cb44', 79, 'Curiosità & Retroscena', 'Il nome di Darth Vader ispirato a un termine olandese', 'Molti fan hanno a lungo creduto che il nome Darth Vader derivasse dall''inglese ''Dark Invader''. In realtà, George Lucas lo ha ideato combinando il titolo ''Dark'' con ''Vader'', che in lingua olandese significa letteralmente ''padre'', anticipando così il celebre colpo di scena del film successivo.', 'Note di produzione e interviste d''archivio di George Lucas', TRUE, 'IA (Daily Sync)', 'IA Verificata', 0, 1, '2026-11-02T09:56:21.006919+00:00'),
('69a1e2fe-56f2-421b-b32e-05879827c7b2', 79, 'Aneddoti dal set', 'Gli occhi di vetro di Peter Cushing', 'L''attore Peter Cushing, che interpretava il Grand Moff Tarkin, trovava estremamente dolorosi gli stivali rigidi e stretti forniti dalla produzione imperiale. Per gran parte delle sue scene, il regista George Lucas decise di inquadrarlo rigorosamente dalla cintura in sù, permettendo a Cushing di indossare comode pantofole sul set.', 'Diari di produzione e interviste al cast', TRUE, 'IA (Daily Sync)', 'IA Verificata', 0, 2, '2026-11-02T09:56:21.006919+00:00'),
('18ece347-f885-4606-b5b9-86dd68b3b2cb', 79, 'Effetti speciali & Trucco', 'L''ispirazione visiva tratta da vecchi film di guerra', 'Per girare le frenetiche sequenze dei combattimenti aerei tra i caccia TIE imperiali e gli X-wing, il montatore e supervisore Richard Chew utilizzò sequenze di repertorio tratte da classici film di guerra della Seconda Guerra Mondiale come montaggio guida per dare ritmo all''azione.', 'Commento audio del montaggio nel cofanetto Blu-ray ufficiale', TRUE, 'IA (Daily Sync)', 'IA Verificata', 0, 3, '2026-11-02T09:56:21.006919+00:00'),
('404e5139-0a4f-45b9-a04e-eb82865ef088', 79, 'Casting & Scelte', 'Il rifiuto del ruolo di Alec Guinness sul compenso', 'Alec Guinness accettò il ruolo di Obi-Wan Kenobi solo dopo aver negoziato una clausola finanziaria insolita ma geniale: oltre a un salario anticipato, pretese e ottenne il 2% dei profitti netti derivanti dai guadagni lordi di George Lucas sul botteghino, mossa che lo rese multimilionario.', 'Autobiografia di Alec Guinness (''Blessings in Disguise'')', TRUE, 'IA (Daily Sync)', 'IA Verificata', 0, 4, '2026-11-02T09:56:21.006919+00:00'),
('5d010e9b-1e88-4ee7-bb34-e4dbd65fa667', 79, 'Segreti di produzione', 'La causa legale persa contro i costumi di Star Wars', 'Andrew Ainsworth, il costumista che aveva realizzato i caschi e le armature originali degli Stormtrooper nei laboratori Shepperton, iniziò a venderne repliche non autorizzate online negli anni 2000. La Lucasfilm lo citò in giudizio nel Regno Unito, ma la corte suprema britannica stabilì che l''armatura era un capo d''abbigliamento e non un''opera d''arte protetta da copyright.', 'Atti della Corte Suprema del Regno Unito (Lucasfilm Ltd v Ainsworth, 2011)', TRUE, 'IA (Daily Sync)', 'IA Verificata', 0, 5, '2026-11-02T09:56:21.006919+00:00'),
('ec440fe2-986e-46f0-b7b2-78a3c687bbce', 84, 'Aneddoti dal set', 'L''ipnosi medica per proteggere il giovane attore', 'Data la natura estremamente traumatica delle scene girate, al termine delle riprese il giovane protagonista Aleksej Kravčenko fu affidato a uno psicoterapeuta che lo sottopose a sedute di ipnosi per aiutarlo a rimuovere il terrore e la violenza vissuti sul set.', 'Interviste retrospettive ad Aleksej Kravčenko e documentari di produzione', TRUE, 'IA (Daily Sync)', 'IA Verificata', 0, 0, '2026-11-02T09:56:58.63204+00:00'),
('b929b7b0-a192-46e3-8b92-557421f399bc', 84, 'Curiosità & Retroscena', 'Il trauma reale del regista legato alla seconda guerra mondiale', 'Il regista Elem Klimov attinse in parte ai propri ricordi d''infanzia per la realizzazione del film: da bambino, durante la seconda guerra mondiale, era fuggito con la sua famiglia attraverso il Volga in fiamme dopo che la loro città era stata bombardata.', 'Note biografiche ufficiali di Elem Klimov e archivi Mosfilm', TRUE, 'IA (Daily Sync)', 'IA Verificata', 0, 1, '2026-11-02T09:56:58.63204+00:00'),
('f35adca2-22eb-448f-a951-1dbc55e35687', 84, 'Curiosità & Retroscena', 'La collaborazione con il co-sceneggiatore sopravvissuto', 'La sceneggiatura fu scritta a quattro mani da Elem Klimov e Ales Adamovich, un autore bielorusso che durante la guerra era stato un vero partigiano e aveva vissuto in prima persona gli orrori dei rastrellamenti nazisti nei villaggi.', 'Note di produzione e pressbook sovietici del 1985', TRUE, 'IA (Daily Sync)', 'IA Verificata', 0, 2, '2026-11-02T09:56:58.63204+00:00'),
('3551bf8c-5a6d-4c07-8967-70c129471d42', 84, 'Segreti di produzione', 'Il rifiuto della tecnica di illuminazione tradizionale', 'Il direttore della fotografia Aleksei Rodionov scelse di non utilizzare quasi mai i classici riflettori da studio cinematografico, preferendo una luce naturale o l''uso di apparecchiature speciali per mantenere una resa visiva cruda e documentaristica.', 'Diari di lavorazione della troupe e interviste ad Aleksei Rodionov', TRUE, 'IA (Daily Sync)', 'IA Verificata', 0, 3, '2026-11-02T09:56:58.63204+00:00'),
('fdd4115f-b053-4787-bf27-9237edece6c2', 146, 'Curiosità & Retroscena', 'L''ispirazione visiva tratta da Edward Hopper', 'Per la celebre sequenza all''interno dell''appartamento di Deckard in cui l''uomo suona il pianoforte e sorseggia alcolici, Ridley Scott e il direttore della fotografia Jordan Cronenweth modellarono l''illuminazione e l''atmosfera ispirandosi direttamente al celebre dipinto ''Nighthawks'' di Edward Hopper.', 'Libro ''Future Noir: The Making of Blade Runner'' di Paul M. Sammon', TRUE, 'IA (Daily Sync)', 'IA Verificata', 0, 5, '2026-11-02T10:07:19.326887+00:00'),
('843a906e-53c4-45e2-85ed-33f72b0c8707', 146, 'Aneddoti dal set', 'La scarpa persa da Joanna Cassidy', 'Durante la ripresa della morte di Zhora, in cui la replicante sfonda i vetri dei manichini scappando tra le vetrine, l''attrice Joanna Cassidy perse una scarpa; la sequenza dovette essere rigirata più volte coordinando le vetrine in vetro di sicurezza frangibile al zucchero.', 'Intervista retrospettiva a Joanna Cassidy', TRUE, 'IA (Daily Sync)', 'IA Verificata', 0, 6, '2026-11-02T10:07:19.326887+00:00'),
('aa7f4309-1e50-43d8-a8e3-f5a961b6e5ff', 220, 'Segreti di produzione', 'Il coinvolgimento finanziario diretto di Benito Mussolini', 'Il kolossal nacque non solo come operazione industriale dell''UCI, ma ricevette il forte appoggio politico ed economico del governo fascista, desideroso di utilizzare il cinema muto come strumento di propaganda e di rilancio dell''orgoglio nazionale nel mondo.', 'Archivi Storici della Unione Cinematografica Italiana e saggi di storia del cinema muto', TRUE, 'IA (Daily Sync)', 'IA Verificata', 0, 0, '2026-11-02T10:14:10.882152+00:00'),
('99a2139c-972f-450e-8753-cdf8e7c77e3b', 220, 'Segreti di produzione', 'Il fallimento finanziario e la crisi dell''UCI', 'Nonostante l''enorme dispiego di mezzi e le imponenti ambizioni internazionali, i costi di produzione astronomici di ''Quo Vadis?'' non furono coperti dagli incassi al botteghino, contribuendo in modo determinante al tracollo finanziario e alla liquidazione della stessa Unione Cinematografica Italiana.', 'Monografie storiche sul cinema muto italiano e bilanci dell''UCI', TRUE, 'IA (Daily Sync)', 'IA Verificata', 0, 1, '2026-11-02T10:14:10.882152+00:00'),
('fb56ec7c-e212-41bc-83d0-3cf1bd99f2bf', 220, 'Curiosità & Retroscena', 'La collaborazione artistica fra il dannunziano e il cinema tedesco', 'La co-regia tra Gabriellino D''Annunzio e Georg Jacoby rappresentò un insolito connubio estetico: da un lato la ricerca di una magniloquenza di matrice letteraria e decadente legata alla figura del Vate, dall''altro la rigida efficienza tecnica e organizzativa tipica del cinema tedesco dell''era di Weimar.', 'Note di regia e cataloghi della Biennale di Venezia / retrospettive storiche', TRUE, 'IA (Daily Sync)', 'IA Verificata', 0, 2, '2026-11-02T10:14:10.882152+00:00'),
('ccc2e008-6a92-4097-9a33-db75c398e462', 80, 'Casting & Scelte', 'La voce alterata di Ian McDiarmid per l''Imperatore', 'Nel montaggio originale del 1980, l''Ologramma dell''Imperatore Palpatine fu interpretato dall''attrice teatrale Marjorie Eaton, con gli occhi di uno scimpanzé sovrimpressi, e doppiato da Clive Revill. Solo nel 2004 George Lucas sostituì il volto con quello di Ian McDiarmid, che avrebbe poi interpretato il personaggio nei prequel.', 'Documentario ''The Making of Star Wars: The Empire Strikes Back''', TRUE, 'IA (Daily Sync)', 'IA Verificata', 0, 0, '2026-11-02T09:56:29.173699+00:00'),
('1b9ad022-061a-4613-9605-10f9ebc500b2', 80, 'Effetti speciali & Trucco', 'La mano meccanica di Luke e il taglio del pollice', 'Durante la sequenza del duello nella Carbonite, Mark Hamill indossava un guanto speciale per simulare la mano robotica, ma per il primo piano in cui la mano viene recisa fu realizzato un calco prostetico dettagliato. Per evitare problemi di censura con il rating MPAA per eccesso di violenza, il regista Irvin Kershner mantenne l''inquadratura focalizzata sui cavi elettrici recisi anziché sul sangue.', 'Note di produzione e commento audio del Blu-ray', TRUE, 'IA (Daily Sync)', 'IA Verificata', 0, 1, '2026-11-02T09:56:29.173699+00:00'),
('138161ff-2ab0-4132-96b3-36b1910e907c', 80, 'Segreti di produzione', 'Il braccio destro di George Lucas alla regia della seconda unità', 'Il leggendario regista John Carpenter declinò l''offerta di dirigere il film, mentre George Lucas scelse Irvin Kershner imponendogli di accettare per dare maggiore spessore drammatico alla sceneggiatura scritta da Leigh Brackett e Lawrence Kasdan. La seconda unità fu guidata dal regista Harley Cokliss e dallo stesso produttore Gary Kurtz.', 'Archivi storici Lucasfilm e biografie di produzione', TRUE, 'IA (Daily Sync)', 'IA Verificata', 0, 2, '2026-11-02T09:56:29.173699+00:00'),
('a00ff921-0695-42e8-9e1b-c9203da65719', 80, 'Aneddoti dal set', 'La neve sintetica tossica di Hoth', 'Per ricreare la tormenta di neve sul pianeta Hoth, le cui scene esterne furono girate a Finse, in Norvegia, la produzione utilizzò grandi quantità di plastica sminuzzata e solfato di bario. Questo materiale causò non pochi problemi respiratori alla troupe e agli attori, oltre a danneggiare gravemente le apparecchiature cinematografiche Panavision.', 'Libro ''The Making of The Empire Strikes Back'' di J.W. Rinzler', TRUE, 'IA (Daily Sync)', 'IA Verificata', 0, 3, '2026-11-02T09:56:29.173699+00:00'),
('6c79b7dc-09a7-43f3-ab04-978125e97564', 80, 'Aneddoti dal set', 'Il malore sul set di Jeremy Bulloch nel costume di Boba Fett', 'Jeremy Bulloch, l''attore che interpretava il cacciatore di taglie Boba Fett, indossava un''armatura pesante e complessa che causò non pochi disagi climatici durante le riprese a Elstree Studios. In particolare, il visore del casco tendeva ad appannarsi costantemente, costringendo l''attore a muoversi quasi alla cieca sul set della Città delle Nuvole.', 'Interviste ufficiali al cast nel documentario del 30º anniversario', TRUE, 'IA (Daily Sync)', 'IA Verificata', 0, 4, '2026-11-02T09:56:29.173699+00:00'),
('b4e35258-594a-4ddc-ae3f-f4178e87eaae', 147, 'Effetti speciali & Trucco', 'Il finto coccodrillo animatronico di John Cox', 'Nella sequenza in cui Sue viene attaccata mentre riempie la borraccia, il predatore che balza fuori dall''acqua non era vero ma un modello meccanico animatronico progettato dal tecnico degli effetti speciali John Cox, dal costo di circa 45.000 dollari australiani. Per le riprese d''ambiente a distanza, la troupe si avvalse invece di veri coccodrilli selvatici in libertà.', 'Making-of ufficiale e note di produzione del DVD', TRUE, 'IA (Daily Sync)', 'IA Verificata', 0, 0, '2026-11-02T10:07:50.279963+00:00'),
('f566ecd4-ff1b-4572-b108-d3fceff0199c', 147, 'Segreti di produzione', 'L''iconico coltello Bowie fatto su misura', 'L''enorme coltello sfoggiato da Mick Dundee nella celebre scena del tentativo di rapina a New York fu realizzato dal mastro coltellaio australiano John Bowring. Per la produzione vennero create tre versioni distinte: una versione reale in acciaio lucidato per le inquadrature ravvicinate, una versione smussata in alluminio per le riprese dinamiche e una in gomma per ragioni di sicurezza.', 'Intervista al prop master John Bowring', TRUE, 'IA (Daily Sync)', 'IA Verificata', 0, 1, '2026-11-02T10:07:50.279963+00:00'),
('07dd9e12-6d4a-428b-a5f2-b02292faa9ab', 147, 'Curiosità & Retroscena', 'La storica candidatura al Premio Oscar', 'Imponendosi come un fenomeno globale del tutto inaspettato, la pellicola ottenne una prestigiosa nomination agli Oscar nel 1987 nella categoria Migliore Sceneggiatura Originale, firmata da Paul Hogan insieme a Ken Shadie e al produttore John Cornell.', 'Archivio ufficiale dei Premi Academy (AMPAS)', TRUE, 'IA (Daily Sync)', 'IA Verificata', 0, 2, '2026-11-02T10:07:50.279963+00:00'),
('08db7dc2-d32b-4dc0-87c8-3ae3f37ef6a8', 147, 'Segreti di produzione', 'Il prefisso ''Mr.'' per evitare equivoci commerciali', 'La Paramount Pictures volle aggiungere il prefisso ''Mr.'' al titolo originale ''Crocodile Dundee'' per l''uscita nelle sale nordamericane. La distribuzione temeva che il pubblico statunitense scambiasse la pellicola per un documentario naturalistico sulla fauna selvaggia o che pensasse che il protagonista fosse letteralmente un animale.', 'Intervista al produttore John Cornell', TRUE, 'IA (Daily Sync)', 'IA Verificata', 0, 3, '2026-11-02T10:07:50.279963+00:00'),
('403f6efe-e34f-4dec-8ec4-1866bc7591ca', 147, 'Aneddoti dal set', 'Riprese reali dentro il Plaza Hotel di New York', 'La produzione non ricostruì in studio gli interni dell''albergo newyorchese, ma ottenne l''autorizzazione a girare all''interno del vero e prestigioso Plaza Hotel a Manhattan. La celebre scena in cui Mick Dundee cerca di capire come utilizzare il bidet venne girata direttamente all''interno di una delle suite più lussuose della struttura.', 'Commento audio del regista Peter Faiman', TRUE, 'IA (Daily Sync)', 'IA Verificata', 0, 4, '2026-11-02T10:07:50.279963+00:00'),
('70b3e481-e9f4-4d3a-b7f2-5785c85e2311', 147, 'Curiosità & Retroscena', 'L''esplosione del turismo nel Parco Nazionale Kakadu', 'Le location mozzafiato girate nel Parco Nazionale Kakadu, come Gunlom Falls e Ubirr, portarono un''ondata senza precedenti di turismo internazionale nel Northern Territory australiano. Negli anni successivi all''uscita del film, le richieste di visti turistici dagli Stati Uniti verso l''Australia aumentarono di oltre il 40%.', 'Rapporto storico dell''Australian Tourist Commission', TRUE, 'IA (Daily Sync)', 'IA Verificata', 0, 5, '2026-11-02T10:07:50.279963+00:00'),
('a7d930f7-0ab9-43bc-b2f2-4a8ffdb3c4d7', 220, 'Segreti di produzione', 'Le difficoltà di distribuzione internazionale sul mercato americano', 'Nonostante la presenza di star internazionali e un battage pubblicitario imponente, il film incontrò enormi difficoltà a imporsi sul mercato statunitense, dove la concorrenza dei kolossal kolossal hollywoodiani di Cecil B. DeMille era ormai insormontabile.', 'Documenti di esportazione cinematografica degli anni ''20 e stampa di settore americana', TRUE, 'IA (Daily Sync)', 'IA Verificata', 0, 3, '2026-11-02T10:14:10.882152+00:00'),
('67f267dd-e697-4837-a9e1-566d14abf431', 227, 'Casting & Scelte', 'La parentela reale tra i fratelli Culkin nel film', 'Il personaggio di Fuller McCallister, il cugino che beve troppa Pepsi e rischia di bagnare il letto, è interpretato da Kieran Culkin, il vero fratello minore di Macaulay Culkin. Questa fu la primissima esperienza cinematografica in assoluto per Kieran.', 'Crediti del film e interviste retrospettive del cast', TRUE, 'IA (Daily Sync)', 'IA Verificata', 0, 0, '2026-11-02T10:14:43.184226+00:00'),
('5854b769-5c13-4439-8b10-91c0e0939de5', 227, 'Casting & Scelte', 'John Candy assunto con un contratto lampo e pochissimo tempo sul set', 'L''attore John Candy, che interpreta il gentile suonatore di polka Gus Polinski, ha girato tutte le sue scene in appena 23 ore consecutive di lavoro. La maggior parte dei suoi dialoghi, incluso l''aneddoto sul dimenticare il figlio in una bara, fu completamente improvvisata.', 'Commento audio del regista Chris Columbus nell''edizione Blu-ray', TRUE, 'IA (Daily Sync)', 'IA Verificata', 0, 1, '2026-11-02T10:14:43.184226+00:00'),
('ce0e4ee6-8fb3-48f7-aaa1-69f5f97922b0', 81, 'Casting & Scelte', 'La morte originale prevista per Han Solo', 'George Lucas, Lawrence Kasdan e Harrison Ford discussero a lungo sulla possibilità di far morire Han Solo alla fine del film per dare maggiore drammaticità alla storia. Fu lo stesso Lucas a fare un passo indietro, temendo che la morte del personaggio potesse danneggiare drasticamente le vendite dei giocattoli e del merchandising legato al franchise.', 'Intervista a Harrison Ford nel documentario The Making of Star Wars', TRUE, 'IA (Daily Sync)', 'IA Verificata', 0, 0, '2026-11-02T09:56:36.826931+00:00'),
('df0a525f-a7e5-41ad-9831-610a4bbe04b9', 81, 'Curiosità & Retroscena', 'Il cameo nascosto di Carrie Fisher come Jawa', 'Durante le riprese nel palazzo di Jabba the Hutt, Carrie Fisher (la Principessa Leia) espresse il desiderio di indossare un costume da comparsa. Per un breve momento, appare sullo sfondo travestita da creatura del deserto, precisamente come un Jawa, mimetizzandosi tra le comparse sul set.', 'Commento audio del Blu-ray ufficiale', TRUE, 'IA (Daily Sync)', 'IA Verificata', 0, 1, '2026-11-02T09:56:36.826931+00:00'),
('42bb63bb-10c4-4975-b46e-0944d301ed67', 81, 'Aneddoti dal set', 'La ferita reale di Carrie Fisher causata dal costume', 'Il celebre bikini d''oro indossato da Carrie Fisher nella sequenza di Jabba the Hutt causò non pochi problemi fisici all''attrice. Il reggiseno di metallo era così rigido e tagliente che le lasciò segni permanenti e ferite sulla pelle durante le riprese nel deserto dello Yuma.', 'Memorie di Carrie Fisher ''Wishful Drinking''', TRUE, 'IA (Daily Sync)', 'IA Verificata', 0, 2, '2026-11-02T09:56:36.826931+00:00'),
('693e17ce-43f2-4295-b50e-5df6e52d319b', 81, 'Segreti di produzione', 'Richard Marquand e la forte presenza di George Lucas', 'Sebbene Richard Marquand fosse accreditato come regista ufficiale, George Lucas fu costantemente presente sul set per supervisionare ogni singola inquadratura e dirigere personalmente molte sequenze chiave, in particolare quelle relative agli effetti visivi e ai combattimenti con le spade laser.', 'Note di produzione e biografia della troupe ILM', TRUE, 'IA (Daily Sync)', 'IA Verificata', 0, 3, '2026-11-02T09:56:36.826931+00:00'),
('b048f21e-2d2d-4d76-a66c-f6d4f9e1dfd4', 81, 'Casting & Scelte', 'Il rifiuto di Steven Spielberg alla regia', 'Prima di affidare la pellicola a Richard Marquand, George Lucas aveva pensato a Steven Spielberg per dirigere il film. Tuttavia, all''epoca Spielberg non era membro della Directors Guild of America (DGA) a causa di una controversia legata al film ''L''impero colpisce ancora'', e Lucas decise di non rischiare sanzioni sindacali.', 'Archivi storici della Lucasfilm', TRUE, 'IA (Daily Sync)', 'IA Verificata', 0, 4, '2026-11-02T09:56:36.826931+00:00'),
('89a87670-ed1c-4552-8eab-dcd9a9efec0a', 83, 'Casting & Scelte', 'La genesi del progetto affidata originariamente a Steven Spielberg', 'Il film fu originariamente sviluppato nel 2006 da Lynda Obst e Jonathan Nolan per la Paramount Pictures, con Steven Spielberg designato alla regia. Fu solo nel 2012, dopo l''uscita di Spielberg dal progetto, che Jonathan propose il copione a suo fratello Christopher Nolan.', 'Note di produzione ufficiali Paramount Pictures e interviste a Lynda Obst', TRUE, 'IA (Daily Sync)', 'IA Verificata', 0, 0, '2026-11-02T09:56:52.227728+00:00'),
('79f9f092-7964-4df4-98ea-e1e053cc1647', 83, 'Casting & Scelte', 'Il cameo segreto di Timothée Chalamet', 'Prima di diventare una superstar internazionale con ''Chiamami col tuo nome'' e ''Dune'', un giovanissimo Timothée Chalamet interpretò il ruolo di Tom Cooper da adolescente, il figlio del protagonista. L''attore ha raccontato di aver pianto davvero vedendo il film al cinema per la prima volta, sapendo che molte delle sue scene erano state tagliate dal montaggio finale.', 'Intervista ufficiale di Timothée Chalamet per Variety e note del cast', TRUE, 'IA (Daily Sync)', 'IA Verificata', 0, 1, '2026-11-02T09:56:52.227728+00:00'),
('145ea7cf-331b-493b-ab28-e69926a97a71', 83, 'Casting & Scelte', 'La scelta di Jessica Chastain all''insaputa della sceneggiatura', 'Jessica Chastain ottenne la parte della versione adulta di Murph mentre si trovava sul set di un altro film, ''Miss Julie''. L''attrice ricevette il copione sotto strettissima sorveglianza e dovette leggerlo in una stanza chiusa alla presenza di un emissario della produzione per evitare fughe di notizie.', 'Intervista a Jessica Chastain per Entertainment Weekly', TRUE, 'IA (Daily Sync)', 'IA Verificata', 0, 2, '2026-11-02T09:56:52.227728+00:00'),
('1f886b6f-f436-4b0b-8339-b7e657d536cb', 83, 'Effetti speciali & Trucco', 'L''invenzione dei robot dal design non antropomorfo', 'Christopher Nolan rifiutò categoricamente di dare ai robot TARS e CASE un aspetto umanoide o facciale, preferendo una struttura modulare composta da quattro pannelli rettangolari controllati da un sistema di leve e attuatori idraulici. Sul set, il robot veniva manovrato fisicamente dal burattinaio Bill Irwin, che ne interpretava anche la voce dal vivo prima di essere cancellato in post-produzione con la CGI.', 'Documentario dietro le quinte ''Building a Interstellar Spaceship''', TRUE, 'IA (Daily Sync)', 'IA Verificata', 0, 3, '2026-11-02T09:56:52.227728+00:00'),
('41426267-6080-4ad8-9bf3-2f28f092b2c0', 148, 'Segreti di produzione', 'L''uso dei veri cannoni d''epoca', 'Per assicurare la massima autenticità visiva e acustica nei combattimenti, la produzione ha utilizzato repliche fedeli di cannoni navali dell''epoca napoleonica capaci di sparare salve a salve reali a salve, gestiti da esperti di artiglieria storica.', 'Documentario ufficiale ''The Hundred Days: The Making of Master and Commander''', TRUE, 'IA (Daily Sync)', 'IA Verificata', 0, 0, '2026-11-02T10:07:56.582659+00:00'),
('a0080e06-9821-4f24-a330-ced53abd36c4', 148, 'Curiosità & Retroscena', 'Il consulente storico di Patrick O''Brian', 'Il regista Peter Weir ha voluto sul set Dean King, celebre biografo e autore di guide all''universo di Patrick O''Brian, affinché supervisionasse ogni dettaglio del gergo marinaresco, delle procedure di bordo e del protocollo della Royal Navy.', 'Note di produzione ufficiali della 20th Century Fox', TRUE, 'IA (Daily Sync)', 'IA Verificata', 0, 1, '2026-11-02T10:07:56.582659+00:00'),
('7383b77c-84cd-4a9c-843b-bea9ff1ed68d', 148, 'Aneddoti dal set', 'Le lezioni di violino e violoncello', 'Russell Crowe e Paul Bettany hanno dovuto studiare intensamente per mesi prima delle riprese con musicisti professionisti per imparare la corretta postura e l''uso dell''archetto, così da poter suonare credibilmente i duetti classici di Bach e Corelli nel film.', 'Commento audio del regista Peter Weir nel DVD del film', TRUE, 'IA (Daily Sync)', 'IA Verificata', 0, 2, '2026-11-02T10:07:56.582659+00:00'),
('5640662b-1d21-4f02-8ad6-a9e4f1b62e8f', 148, 'Segreti di produzione', 'L''ispirazione dal vero HMS Rose', 'La nave utilizzata come base per la HMS Surprise era l''HMS Rose, una replica della fregata del XVIII secolo acquistata dalla 20th Century Fox, ribattezzata e modificata estensivamente per le riprese prima di essere successivamente musealizzata.', 'Archivi storici della produzione navale di Hollywood', TRUE, 'IA (Daily Sync)', 'IA Verificata', 0, 3, '2026-11-02T10:07:56.582659+00:00'),
('e3047d5b-403d-40a1-9f5e-1b017a61bb83', 158, 'Casting & Scelte', 'La scelta di Rutger Hauer e la tradizione dei cinecomic', 'Christopher Nolan decise di ingaggiare Rutger Hauer nel ruolo del corrotto amministratore delegato della Wayne Enterprises, William Earle, proprio come omaggio al celebre antagonista di Blade Runner, un film che aveva profondamente influenzato l''immaginario visivo del regista per la sua Gotham City.', 'Special content e note di produzione del Blu-Ray ufficiale', TRUE, 'IA (Daily Sync)', 'IA Verificata', 0, 0, '2026-11-02T10:09:05.124278+00:00'),
('05612264-249a-4a4c-bf19-908012fcf4cf', 158, 'Segreti di produzione', 'L''ispirazione da ''Batman: Anno Uno'' e ''Il Lungo Halloween''', 'Durante le fasi di scrittura della sceneggiatura, David S. Goyer e Christopher Nolan si sono basati quasi esclusivamente sulle graphic novel ''Batman: Anno Uno'' di Frank Miller e ''Il Lungo Halloween'' di Jeph Loeb, rifiutando deliberatamente l''estetica gotica vista in precedenza nei film di Tim Burton e Joel Schumacher.', 'Intervista congiunta a Christopher Nolan e David S. Goyer nel volume ''The Art and Making of Batman Begins''', TRUE, 'IA (Daily Sync)', 'IA Verificata', 0, 1, '2026-11-02T10:09:05.124278+00:00'),
('4b792040-6aa8-43b8-b8db-bb6993cda09a', 82, 'Segreti di produzione', 'La scelta di Irvin Kershner e la sceneggiatura di Kevin McClory', 'I produttori scelsero Irvin Kershner per la regia forti del suo successo mondiale con ''L''Impero colpisce ancora'', puntando a dare al film un taglio più maturo e psicologico rispetto ai canoni tradizionali della Eon. La sceneggiatura fu basata direttamente sul romanzo ''Thunderball'' di Ian Fleming, di cui Kevin McClory deteneva i diritti esclusivi per il cinema.', 'Note di produzione ufficiali e documentario ''Thunderball: The Making Of''', TRUE, 'IA (Daily Sync)', 'IA Verificata', 0, 0, '2026-11-02T09:56:45.114294+00:00'),
('4136fcb0-cc42-4f35-8292-fba71f84f9ff', 82, 'Casting & Scelte', 'La nomination ai Golden Globe per Barbara Carrera', 'L''interpretazione della letale e seducente assassina della SPECTRE Fatima Blush valse a Barbara Carrera una prestigiosa candidatura ai Golden Globe nel 1984 come Miglior attrice non protagonista, un riconoscimento cinematografico raro per un personaggio di un film di spionaggio concorrente della saga ufficiale.', 'Archivio ufficiale dei Golden Globe e biografia dell''attrice', TRUE, 'IA (Daily Sync)', 'IA Verificata', 0, 1, '2026-11-02T09:56:45.114294+00:00'),
('a6c525e0-60f1-4aa0-b70a-062123009bb7', 82, 'Casting & Scelte', 'Il rifiuto del ruolo di Domino da parte di diverse attrici', 'Prima che la parte di Domino Petachi venisse affidata a Kim Basinger, i produttori valutarono diverse attrici di calibro internazionale, tra cui Melanie Griffith e Meg Ryan per ruoli minori o provini iniziali, mentre la stessa Basinger accettò dopo che alcune star più note rifiutarono il contratto a causa della complessa situazione legale tra le case di produzione.', 'Biografie del cast e retroscena di casting pubblicati da Variety', TRUE, 'IA (Daily Sync)', 'IA Verificata', 0, 2, '2026-11-02T09:56:45.114294+00:00'),
('a49a32c1-d134-4875-a26e-55202ba15f15', 82, 'Casting & Scelte', 'Edward Fox nei panni di un inedito M', 'L''attore britannico Edward Fox fu scelto per interpretare il capo dell''MI6, M, delineando un personaggio radicalmente diverso da quello austero interpretato da Bernard Lee nella serie ufficiale: Fox scelse di conferire a M i modi di un burocrate altezzoso ed elegante, vestito con abiti civili impeccabili anziché con la classica divisa.', 'Commento audio del regista Irvin Kershner nell''edizione home video', TRUE, 'IA (Daily Sync)', 'IA Verificata', 0, 3, '2026-11-02T09:56:45.114294+00:00'),
('b176ef69-6ac8-4fd0-a0b2-f1129b29998e', 82, 'Curiosità & Retroscena', 'La canzone principale interpretata da Laura Branigan', 'Il brano portante della colonna sonora, intitolato ''Never Say Never Again'', fu infine affidato alla celebre voce pop statunitense Laura Branigan, scritto da Michel Legrand e Alan e Marilyn Bergman, diventando un successo radiofonico separato rispetto ai classici temi musicali firmati da John Barry per la Eon Productions.', 'Note di copertina della colonna sonora originale Warner Bros. Records', TRUE, 'IA (Daily Sync)', 'IA Verificata', 0, 4, '2026-11-02T09:56:45.114294+00:00'),
('ab13c0c4-2c50-4bfe-adb4-c99ae1c86af0', 213, 'Aneddoti dal set', 'La drastica dieta della fame', 'Per interpretare i marinai sopravvissuti ridotti allo stremo della fame sulla scialuppa, Chris Hemsworth e il resto del cast dovettero seguire una dieta rigorosa e pericolosa basata su sole 500-600 calorie al giorno nelle ultime settimane di riprese. Lo stesso Hemsworth ha ammesso in varie interviste che l''irritabilità causata dalla denutrizione ha paradossalmente aiutato a rendere più realistiche le tensioni psicologiche tra i personaggi in mare.', 'Intervista ufficiale di Chris Hemsworth per Entertainment Weekly', TRUE, 'IA (Daily Sync)', 'IA Verificata', 0, 0, '2026-11-02T15:47:07.426596+00:00'),
('e86fe1af-902d-47fd-8d83-782f89d3a5b4', 149, 'Segreti di produzione', 'La vera paternità del design della Dune Buggy', 'La celebre Dune Buggy rossa con cappottina gialla non era un modello di serie, ma fu appositamente modificata e assemblata dalla carrozzeria Puma di Romeu Felisberto su base meccanica Volkswagen Maggiolino. Il design definitivo fu curato nei dettagli per renderla immediatamente riconoscibile al botteghino.', 'Archivio storico Puma Cars / Note di produzione', TRUE, 'IA (Daily Sync)', 'IA Verificata', 0, 0, '2026-11-02T10:08:02.240657+00:00'),
('b80cf1c9-db7c-43db-834c-236cb6ca1dc0', 149, 'Aneddoti dal set', 'La location del luna park e il parco divertimenti di Madrid', 'Gran parte delle sequenze ambientate nel luna park e la celebre scena della distruzione della palestra furono girate in Spagna, sfruttando le strutture del Parque de Atracciones de Madrid e alcune aree periferiche della capitale spagnola.', 'Dichiarazioni della troupe e giornate di lavorazione sui set spagnoli', TRUE, 'IA (Daily Sync)', 'IA Verificata', 0, 1, '2026-11-02T10:08:02.240657+00:00'),
('f359588d-0945-41a2-9552-e58d3707e37d', 221, 'Curiosità & Retroscena', 'La colonna sonora candidata all''Oscar di Miklós Rózsa', 'Il celebre compositore Miklós Rózsa fu incaricato di creare le musiche per il kolossal, attingendo a studi musicologici sull''antichità per evocare sonorità romane ed ebraiche autentiche. Il suo monumentale lavoro valse al film una delle 12 candidature agli Academy Awards ricevute dalla pellicola nel 1952.', 'Note di produzione ufficiali e archivi degli Academy Awards', TRUE, 'IA (Daily Sync)', 'IA Verificata', 0, 0, '2026-11-02T10:14:17.524709+00:00'),
('6aa2ee44-5f43-415c-83ad-be77d71de608', 221, 'Segreti di produzione', 'La ricostruzione monumentale della via Appia', 'Per girare il ritorno trionfale di Marco Vinicio a Roma, la scenografia richiese la costruzione di un tratto di ben 300 metri della vera via Appia, realizzato con blocchi di pietra autentici all''interno degli stabilimenti di Cinecittà per garantire il massimo realismo storico.', 'Documentario retrospettivo sul cinema di kolossal italiano e archivi MGM', TRUE, 'IA (Daily Sync)', 'IA Verificata', 0, 1, '2026-11-02T10:14:17.524709+00:00'),
('2dbd4cc0-3713-4e85-bfa4-15ff5ff1e616', 221, 'Segreti di produzione', 'I costumi premio Oscar di Margherita Missoni e Edward Stevenson', 'I costumisti Edward Stevenson e Dorothy Jeakins dovettero realizzare oltre 32.000 costumi per comparse e protagonisti, studiando affreschi pompeiani e reperti storici conservati nei musei di tutto il mondo per riprodurre con estrema fedeltà gli abiti dell''epoca neroniana.', 'Cataloghi di esposizione dei costumi storici di Hollywood e note di produzione MGM', TRUE, 'IA (Daily Sync)', 'IA Verificata', 0, 2, '2026-11-02T10:14:17.524709+00:00'),
('8597dd8c-a37c-4d7a-876c-6eca80d2a2f1', 221, 'Casting & Scelte', 'Il rifiuto iniziale di Gregory Peck', 'Prima che Robert Taylor venisse definitivamente scelto per il ruolo del protagonista Marco Vinicio, la MGM aveva offerto la parte a Gregory Peck. L''attore rifiutò il ruolo perché non si sentiva adatto a interpretare un generale romano in un film di tale portata.', 'Biografie ufficiali di Gregory Peck e corrispondenza negli archivi della MGM', TRUE, 'IA (Daily Sync)', 'IA Verificata', 0, 3, '2026-11-02T10:14:17.524709+00:00'),
('e19b30b8-3830-429f-b877-d1b10035bda2', 236, 'Segreti di produzione', 'La scelta di girare a Baltimora e Filadelfia per l''estetica di decadimento urbano', 'La produzione scelse Baltimora e Filadelfia anziché Los Angeles o New York perché offrivano un''architettura industriale in rovina che non richiedeva costose ricostruzioni in studio. Terry Gilliam ha sfruttato luoghi reali come il manicomio abbandonato di Willard e diverse zone portuali dismesse per dare al film l''aspetto distopico desiderato.', 'Note di produzione ufficiali della Universal Pictures', TRUE, 'IA (Daily Sync)', 'IA Verificata', 0, 2, '2026-11-02T10:20:07.260077+00:00'),
('51e495dc-9b50-4ca5-aa45-6213f45e8a10', 236, 'Aneddoti dal set', 'L''improvvisazione vocale di Brad Pitt durante la scena dell''istituto di igiene mentale', 'Molti dei rapidi e deliranti monologhi pronunciati da Brad Pitt nella sequenza dell''ospedale psichiatrico non erano rigidamente bloccati dal copione, ma frutto di un intenso lavoro di improvvisazione vocale provato e riprovato dall''attore durante le prove per mantenere il set in uno stato di costante tensione creativa.', 'Intervista a Brad Pitt per Entertainment Weekly, 1995', TRUE, 'IA (Daily Sync)', 'IA Verificata', 0, 3, '2026-11-02T10:20:07.260077+00:00'),
('afe8b80a-3957-4c17-8c09-5610f0f2cd83', 85, 'Casting & Scelte', 'La rimozione della voce originale di HAL 9000', 'L''attore Nigel Davenport aveva originariamente registrato tutte le battute di HAL 9000 direttamente sul set durante le riprese. Tuttavia, in post-produzione, Stanley Kubrick decise di sostituire la sua voce con quella più neutra e pacata di Douglas Rain, doppiando interamente il computer.', 'Note di produzione e biografie ufficiali di Stanley Kubrick', TRUE, 'IA (Daily Sync)', 'IA Verificata', 0, 0, '2026-11-02T09:57:05.436284+00:00'),
('e06eed5b-9d89-4a1f-9248-e6edc4b01f74', 85, 'Segreti di produzione', 'I dipinti della NASA come scenografia', 'Per arredare gli uffici e gli ambienti della base lunare, Stanley Kubrick commissionò o utilizzò una serie di vere opere d''arte e concetti di design forniti direttamente dalla NASA e da artisti aerospaziali dell''epoca per dare un''impronta di assoluto realismo tecnologico.', 'Archivi storici della NASA e documentari sul making-of del film', TRUE, 'IA (Daily Sync)', 'IA Verificata', 0, 1, '2026-11-02T09:57:05.436284+00:00'),
('8b1a63be-b93b-449a-9cf9-f4c91e907221', 85, 'Effetti speciali & Trucco', 'La sequenza finale psichedelica e la tecnica Slit-Scan', 'Per realizzare il celebre e lisergico viaggio attraverso lo spaziotempo nella sequenza ''Jupiter and Beyond the Infinite'', il supervisore agli effetti speciali Douglas Trumbull sviluppò una complessa tecnica fotografica nota come Slit-Scan, utilizzando lunghi tempi di esposizione e aperture di fessure mobili su pellicola.', 'American Cinematographer e interviste a Douglas Trumbull', TRUE, 'IA (Daily Sync)', 'IA Verificata', 0, 2, '2026-11-02T09:57:05.436284+00:00'),
('4c293947-1f91-4833-91c9-20757a11f97a', 85, 'Curiosità & Retroscena', 'La causa legale contro la MGM per pubblicità ingannevole', 'Lo scrittore di fantascienza Arthur C. Clarke, co-autore della sceneggiatura insieme a Kubrick, intentò quasi una causa legale contro la Metro-Goldwyn-Mayer perché nei primi trailer promozionali il film veniva pubblicizzato in modo troppo commerciale e confuso, snaturandone la natura filosofica.', 'Carteggio ufficiale e biografie di Arthur C. Clarke', TRUE, 'IA (Daily Sync)', 'IA Verificata', 0, 3, '2026-11-02T09:57:05.436284+00:00'),
('ca5f9d38-4849-4d83-ba7c-47d2c6c06623', 85, 'Curiosità & Retroscena', 'Il premio Oscar a Kubrick e la sua assenza alla cerimonia', 'Stanley Kubrick vinse l''unico Premio Oscar della sua intera carriera proprio per gli effetti speciali di questo film. Tuttavia, a causa della sua nota avversione per i viaggi e per la mondanità di Hollywood, non si presentò alla cerimonia e mandò l''attore Carroll Baker a ritirare la statuetta al suo posto.', 'Archivi ufficiali dell''Academy Awards', TRUE, 'IA (Daily Sync)', 'IA Verificata', 0, 4, '2026-11-02T09:57:05.436284+00:00'),
('3675f32e-1580-4978-a2fb-fc32aebf34a3', 89, 'Curiosità & Retroscena', 'La censura e il divieto in Birmania', 'Il governo militare della Birmania (Myanmar) ha bandito ufficialmente il film a causa della rappresentazione cruda delle atrocità commesse dal regime contro la minoranza Karen. Nonostante il bando governativo, le copie pirata in DVD sono state ampiamente diffuse nel mercato nero locale, diventando paradossalmente un fenomeno di culto tra la popolazione che lottava per la democrazia.', 'The Hollywood Reporter / Notizie di distribuzione internazionale 2008', TRUE, 'IA (Daily Sync)', 'IA Verificata', 0, 0, '2026-11-02T09:57:34.539653+00:00'),
('fb91dec0-d866-411e-8731-62ea66169856', 89, 'Segreti di produzione', 'La scelta della troupe locale e i rischi politici', 'Sylvester Stallone ha assunto troupe e logistica locali in Thailandia, rischiando seriamente incidenti diplomatici e tensioni con le autorità birmane. Le riprese si sono svolte a pochissimi metri dal confine blindato, costringendo la produzione a stipulare polizze assicurative speciali e a mantenere contatti costanti con le forze di sicurezza locali per evitare sequestri.', 'Commento audio del regista Sylvester Stallone nell''edizione Blu-ray', TRUE, 'IA (Daily Sync)', 'IA Verificata', 0, 1, '2026-11-02T09:57:34.539653+00:00'),
('39485750-29c6-482f-8c5b-b5855a97b952', 89, 'Effetti speciali & Trucco', 'Il record di violenza cinematografica', 'Secondo uno studio statistico indipendente condotto sui film d''azione mainstream, ''John Rambo'' detiene un record impressionante con oltre 236 morti conteggiate nel corso della pellicola, superando ampiamente i capitoli precedenti della saga e posizionandosi come uno dei film più letali della storia del cinema moderno.', 'Analisi statistica di Movie Body Counts e note di produzione Lionsgate', TRUE, 'IA (Daily Sync)', 'IA Verificata', 0, 2, '2026-11-02T09:57:34.539653+00:00'),
('d3c392ca-72d4-44fb-bcff-621d78f47ce5', 89, 'Aneddoti dal set', 'L''infortunio alla schiena di Sylvester Stallone', 'Durante le riprese della brutale sequenza del corpo a corpo finale contro l''antagonista, Sylvester Stallone ha subito una grave frattura vertebrale e diverse lesioni muscolari a causa dell''intensità e del contatto fisico reale richiesto dall''attore che interpretava il capo dei soldati birmani, costringendo la troupe a sospendere temporaneamente la lavorazione.', 'Intervista a Sylvester Stallone per Entertainment Weekly', TRUE, 'IA (Daily Sync)', 'IA Verificata', 0, 3, '2026-11-02T09:57:34.539653+00:00'),
('a44cc7f8-1fb2-4987-b16e-43b2afae32f1', 150, 'Effetti speciali & Trucco', 'La trasformazione fisica di Stellan Skarsgård', 'Per interpretare il Barone Vladimir Harkonnen, l''attore Stellan Skarsgård doveva sottoporsi a sessioni di trucco prostetico quotidiane della durata di circa otto ore, indossando un massiccio ''fat suit'' che pesava quasi quaranta chili per conferirgli quell''aspetto mostruoso e imponente.', 'Note di produzione e interviste ufficiali del reparto trucco', TRUE, 'IA (Daily Sync)', 'IA Verificata', 0, 0, '2026-11-02T10:08:09.8399+00:00'),
('a4452ea8-78c5-4f32-be98-5d64e69336c9', 150, 'Segreti di produzione', 'La divisione in due parti imposta da contratto', 'Denis Villeneuve ha accettato di dirigere l''adattamento del romanzo di Frank Herbert a una condizione imprescindibile inserita nel suo contratto con la Legendary Pictures: il libro doveva essere obbligatoriamente diviso in due lungometraggi distinti per poter rendere giustizia alla complessa trama.', 'Intervista di Variety a Denis Villeneuve', TRUE, 'IA (Daily Sync)', 'IA Verificata', 0, 1, '2026-11-02T10:08:09.8399+00:00');
INSERT INTO public.movie_trivia ("id", "film_id", "categoria", "titolo", "descrizione", "fonte", "approvato", "inserito_da", "provenienza", "likes", "ordine", "created_at") VALUES
('ab5f613a-da5d-4110-a0ac-7a76adba827f', 150, 'Curiosità & Retroscena', 'Il rifiuto del formato 16:9 e la scelta del rapporto anamorfico', 'Nonostante la forte spinta iniziale verso gli standard televisivi moderni, il direttore della fotografia Greig Fraser e il regista hanno girato il film con cineprese Arri Alexa LF dotate di ottiche anamorfiche Panavision H-Series, optando per un rapporto d''aspetto di 2.39:1 che poi si apre a 1.90:1 nelle versioni IMAX.', 'American Cinematographer, articolo tecnico sulla produzione', TRUE, 'IA (Daily Sync)', 'IA Verificata', 0, 2, '2026-11-02T10:08:09.8399+00:00'),
('085a1aab-559c-4261-92f4-03f619528d8a', 150, 'Casting & Scelte', 'Le origini di Thufir Hawat e il ruolo di Stephen McKinley Henderson', 'Il personaggio del Mentat Thufir Hawat era stato originariamente offerto a attori di diversa estrazione, ma Denis Villeneuve ha voluto fortemente Stephen McKinley Henderson, con cui aveva già lavorato in ''Arrival'' (2016), adattando la solennità del personaggio alla presenza scenica dell''attore teatrale.', 'Press kit ufficiale Warner Bros.', TRUE, 'IA (Daily Sync)', 'IA Verificata', 0, 3, '2026-11-02T10:08:09.8399+00:00'),
('79057445-7873-4b74-bad8-b9fe045da8fd', 156, 'Casting & Scelte', 'L''inclusione di Don Rickles tramite registrazioni d''archivio', 'Il compianto attore Don Rickles, storico doppiatore di Mr. Potato Head, è apparso in Toy Story 4 nonostante fosse scomparso nel 2017. La Pixar ha ottenuto il permesso speciale dalla famiglia dell''attore per utilizzare registrazioni vocali inutilizzate dai film precedenti, dai videogiochi e da materiale d''archivio.', 'Note di produzione ufficiali Pixar / Dichiarazioni del regista Josh Cooley', TRUE, 'IA (Daily Sync)', 'IA Verificata', 0, 0, '2026-11-02T10:08:52.966349+00:00'),
('585e43fd-54a1-46c7-ac37-5c8dcbf09bb5', 86, 'Segreti di produzione', 'Il compenso record per Sylvester Stallone', 'Per interpretare John Rambo nel film del 1982, Sylvester Stallone ricevette un compenso di 3,5 milioni di dollari, una cifra considerevole per l''epoca che rifletteva il suo enorme potere contrattuale acquisito grazie al successo globale dei primi film di Rocky.', 'Archivi di produzione Carolco/Orion Pictures', TRUE, 'IA (Daily Sync)', 'IA Verificata', 0, 0, '2026-11-02T09:57:12.342143+00:00'),
('631f2e75-c327-4546-9068-0b7d9f8354f4', 86, 'Aneddoti dal set', 'La scelta della location canadese', 'Le riprese del film si svolsero quasi interamente nella cittadina di Hope, nella Columbia Britannica (Canada), scelta perché la sua via principale ricordava perfettamente l''atmosfera opprimente di una provincia americana isolata e offriva foreste montane ideali per la caccia all''uomo.', 'Note di produzione ufficiali del film', TRUE, 'IA (Daily Sync)', 'IA Verificata', 0, 1, '2026-11-02T09:57:12.342143+00:00'),
('8082f302-9746-43af-93e3-aa6a398da044', 86, 'Curiosità & Retroscena', 'L''ispirazione per il cognome del protagonista', 'Lo scrittore David Morrell trasse l''ispirazione per il cognome del protagonista non solo dalle mele Rambo, ma anche dalla lettura di un libro del poeta francese Arthur Rimbaud, il cui cognome si pronunciava in modo identico ed evocava in lui un senso di ribellione e sofferenza.', 'Intervista retrospettiva a David Morrell', TRUE, 'IA (Daily Sync)', 'IA Verificata', 0, 2, '2026-11-02T09:57:12.342143+00:00'),
('2b0482b0-1b3f-4652-a9fd-e5896498541d', 86, 'Casting & Scelte', 'Il cameo mancato dell''autore del romanzo', 'David Morrell, l''autore del romanzo originale, ricevette un''offerta per interpretare un ruolo minore nel film, precisamente uno dei poliziotti che danno la caccia a Rambo, ma dovette rifiutare all''ultimo minuto a causa di conflitti con i suoi impegni di insegnamento universitario.', 'Commento audio del DVD di David Morrell', TRUE, 'IA (Daily Sync)', 'IA Verificata', 0, 3, '2026-11-02T09:57:12.342143+00:00'),
('261b10c0-75df-4e4b-ab18-af19c086365a', 86, 'Curiosità & Retroscena', 'L''uso limitato delle battute per Stallone', 'Nella sceneggiatura rivista, Sylvester Stallone decise consapevolmente di ridurre drasticamente le battute di dialogo del suo personaggio, pronunciando pochissime parole per tutto il secondo atto del film al fine di accentuare il profilo del reduce alienato e selvaggio.', 'Analisi della sceneggiatura originale e montaggio definitivo', TRUE, 'IA (Daily Sync)', 'IA Verificata', 0, 4, '2026-11-02T09:57:12.342143+00:00'),
('bb7df0d0-e0d2-42b7-a1dc-54b2dd0e30db', 86, 'Segreti di produzione', 'Il rifiuto del rating PG', 'Il montaggio iniziale del film fu severamente valutato dalla MPAA statunitense, rischiando un visto di censura restrittivo; la produzione dovette tagliare alcune sequenze particolarmente sanguinose della sparatoria finale per ottenere il visto R (Restricted) senza compromettere la tensione drammatica.', 'Documenti di censura MPAA e note di post-produzione', TRUE, 'IA (Daily Sync)', 'IA Verificata', 0, 5, '2026-11-02T09:57:12.342143+00:00'),
('49b9b43b-a389-4c1f-8676-2c884d405b81', 90, 'Segreti di produzione', 'La genesi del progetto come adattamento di Hunter', 'Prima di diventare un film, l''idea iniziale per un quarto capitolo risaliva ai primi anni 2000, quando Sylvester Stallone aveva valutato di adattare il romanzo ''Hunter'' di James Byron Huggins, incentrato su una creatura genetica, convertendo poi la trama in una storia incentrata sul traffico di esseri umani.', 'Note di produzione e interviste d''archivio di Sylvester Stallone', TRUE, 'IA (Daily Sync)', 'IA Verificata', 0, 0, '2026-11-02T09:57:40.703063+00:00'),
('b301aaf7-54fa-4397-8676-06087de293c2', 90, 'Curiosità & Retroscena', 'La frustrazione iniziale per la classificazione PG-13', 'Nelle prime fasi di post-produzione, il montaggio iniziale sottoposto alla MPAA aveva ottenuto una classificazione PG-13, spingendo Stallone e i produttori a intervenire nuovamente per aumentare la brutalità esplicita e riottenere il tradizionale divieto R-rated della saga.', 'Dichiarazioni ufficiali della produzione al Los Angeles Times', TRUE, 'IA (Daily Sync)', 'IA Verificata', 0, 1, '2026-11-02T09:57:40.703063+00:00'),
('a7d85057-f7cc-4cc6-a4e9-43587ff7dfc5', 90, 'Casting & Scelte', 'Il coinvolgimento di Adrian Grunberg per la forte impronta messicana', 'Sylvester Stallone ha scelto personalmente il regista Adrian Grunberg dopo aver visionato ''Get the Gringo'' (2012), apprezzando la sua capacità di dirigere action movie ambientati in contesti di confine e la sua profonda conoscenza della cultura e delle maestranze messicane.', 'Intervista al regista Adrian Grunberg per il press kit ufficiale del film', TRUE, 'IA (Daily Sync)', 'IA Verificata', 0, 2, '2026-11-02T09:57:40.703063+00:00'),
('b481b8ca-b8de-4c7a-ad48-1c03dfca6362', 152, 'Aneddoti dal set', 'L''infortunio sul set di Josh Lucas', 'Durante le riprese delle scene d''azione più intense, l''attore Josh Lucas ha riportato una lesione alla spalla ed è rimasto ferito a un piede a causa della forza dei getti d''acqua e dei detriti in movimento sul set. Nonostante il dolore, ha insistito per girare la maggior parte delle sequenze di stunt in prima persona senza l''ausilio di controfigure.', 'Intervista ufficiale dal press kit di produzione della Warner Bros.', TRUE, 'IA (Daily Sync)', 'IA Verificata', 0, 0, '2026-11-02T10:08:21.693871+00:00'),
('464243e8-e0e0-4627-bebb-6e7bf08510b8', 152, 'Casting & Scelte', 'La preparazione atletica di Richard Dreyfuss', 'Per interpretare l''architetto gay in cerca di riscatto Richard Nelson, l''attore premio Oscar Richard Dreyfuss ha dovuto sottoporsi a un duro regime di allenamento fisico nonostante i suoi 57 anni, dichiarando in seguito che le riprese in acqua sono state le più faticose della sua intera carriera cinematografica.', 'Note di produzione e interviste promozionali del cast (2006)', TRUE, 'IA (Daily Sync)', 'IA Verificata', 0, 1, '2026-11-02T10:08:21.693871+00:00'),
('5ae923e3-e8ba-4cb2-b444-4710ad0d5154', 152, 'Segreti di produzione', 'Il record di costruzioni su cardini idraulici', 'La Industrial Light & Magic (ILM) e il production designer William Sandell hanno collaborato per progettare la sala da ballo su piattaforme cardaniche capaci di ruotare a 360 gradi, stabilendo un record per l''epoca per le dimensioni dei set pratici mossi da sistemi idraulici complessi.', 'Documentario ''The Making of Poseidon'' contenuto nell''edizione DVD', TRUE, 'IA (Daily Sync)', 'IA Verificata', 0, 2, '2026-11-02T10:08:21.693871+00:00'),
('109a163c-9a00-41b5-8a78-56e2547f7268', 152, 'Citazioni & Easter Egg', 'L''ispirazione visiva da L''avventura del Poseidon (1972)', 'Sebbene il regista Wolfgang Petersen volesse un''impostazione moderna e priva di ironia rispetto al capostipite del 1972, ha inserito un omaggio visivo diretto replicando la celebre inquadratura della scalinata rovesciata in cui i superstiti cercano una via d''uscita verso la chiglia.', 'Commento audio del regista Wolfgang Petersen nel Blu-ray del film', TRUE, 'IA (Daily Sync)', 'IA Verificata', 0, 3, '2026-11-02T10:08:21.693871+00:00'),
('f6aba5a5-2b16-48e9-b1dd-9110ff273b11', 152, 'Effetti speciali & Trucco', 'La gestione della scala e delle comparse digitali', 'Per simulare la presenza di centinaia di passeggeri intrappolati nel salone principale prima del capovolgimento, la troupe ha combinato solo 30 attori in carne e ossa con tecniche di motion capture e clonazione digitale realizzate dai supervisor degli effetti visivi Boyd Shermis e Chas Jarrett.', 'Cinefex Magazine n. 106, articolo di approfondimento sugli effetti speciali di Poseidon', TRUE, 'IA (Daily Sync)', 'IA Verificata', 0, 4, '2026-11-02T10:08:21.693871+00:00'),
('2ab35d7d-4424-4d9d-840a-6cba87fb1b7a', 154, 'Casting & Scelte', 'La cancellazione temporanea del personaggio di Barbie', 'Mattel inizialmente negò l''autorizzazione all''utilizzo di Barbie nel primo film del 1995. Visto il successo colossale della pellicola, l''azienda cambiò idea e concesse l''uso del personaggio per Toy Story 2, permettendo l''inserimento della celebre guida turistica Barbie nel negozio di giocattoli.', 'Commento audio del regista e note di produzione ufficiali Pixar', TRUE, 'IA (Daily Sync)', 'IA Verificata', 0, 0, '2026-11-02T10:08:39.177375+00:00'),
('67a9427d-f5cf-4787-9bcf-0656f548caae', 87, 'Casting & Scelte', 'L''ispirazione per il personaggio di Co Bao', 'L''attrice Julia Nickson fu scelta per interpretare la guerrigliera Co Bao dopo una vasta ricerca internazionale. Per prepararsi al ruolo, studiò approfonditamente la cultura vietnamita e si sottopose a un rigido addestramento fisico per reggere le faticose scene d''azione nella giungla.', 'Documentario ufficiale ''We Get to Win This Time: Making Rambo First Blood Part II''', TRUE, 'IA (Daily Sync)', 'IA Verificata', 0, 0, '2026-11-02T09:57:19.401976+00:00'),
('e28851ec-f6bb-4099-ad24-47bc6d1d444f', 87, 'Effetti speciali & Trucco', 'La cicatrice reale di Stallone e il trucco di scena', 'Durante le riprese delle scene di tortura in cui Rambo viene ustionato con una lama rovente, gli effetti speciali furono curati dal leggendario truccatore Bart Mixon. Per alcune inquadrature ravvicinate vennero impiegate protesi in lattice altamente dettagliate per simulare le ustioni senza mettere a rischio l''incolumità dell''attore.', 'Note di produzione e archivi reparto trucco', TRUE, 'IA (Daily Sync)', 'IA Verificata', 0, 1, '2026-11-02T09:57:19.401976+00:00'),
('694df53f-02de-4e64-bc06-2e906d9a5bf1', 87, 'Segreti di produzione', 'La scelta della base militare per le sequenze iniziali', 'Le sequenze in cui Rambo viene prelevato dal campo di lavori forzati e riceve l''incarico segreto furono girate nella base militare di Guerrero in Messico. La produzione dovette noleggiare elicotteri UH-1 Iroquois reali e collaborare con le forze armate locali per ottenere la massima autenticità militare.', 'Commento audio del regista George P. Cosmatos nell''edizione Home Video', TRUE, 'IA (Daily Sync)', 'IA Verificata', 0, 2, '2026-11-02T09:57:19.401976+00:00'),
('d207bec2-6a6d-4d88-92e4-44eb76a37654', 87, 'Aneddoti dal set', 'Il record di proiettili a salve sparati', 'Nel climax del film, in cui Rambo distrugge il campo nemico a bordo di un elicottero Huey armato di mitragliatrice M60, furono consumate centinaia di migliaia di munizioni a salve. Il coordinatore degli stunt dovette gestire un consumo record di piombo che rese necessario l''intervento costante di armaioli professionisti sul set.', 'Intervista al coordinatore degli stunt Glenn Wilder', TRUE, 'IA (Daily Sync)', 'IA Verificata', 0, 3, '2026-11-02T09:57:19.401976+00:00'),
('d1e5cd19-e517-4068-af7e-a4f5fca53a74', 225, 'Aneddoti dal set', 'L''infortunio alla caviglia di Tom Cruise', 'Durante le riprese delle sequenze di battaglia, Tom Cruise subì un infortunio alla caviglia che costrinse la produzione a fermare temporaneamente il set per permettergli il recupero fisico. L''attore volle comunque insistere nel girare la maggior parte dei movimenti atletici senza ricorrere a stuntman.', 'Note di produzione ufficiali della Warner Bros.', TRUE, 'IA (Daily Sync)', 'IA Verificata', 0, 0, '2026-11-02T10:14:29.340351+00:00'),
('47775df1-0b27-4ac2-bc6c-8daa9a961c97', 225, 'Segreti di produzione', 'Il doppiaggio giapponese curato dal cast', 'Per la versione distribuita nelle sale cinematografiche in Giappone, gli attori nativi giapponesi come Ken Watanabe e Hiroyuki Sanada registrarono personalmente le proprie voci per il doppiaggio in lingua madre, garantendo una dizione impeccabile e appropriata al periodo storico rappresentato.', 'Materiale promozionale e crediti di edizione giapponese', TRUE, 'IA (Daily Sync)', 'IA Verificata', 0, 1, '2026-11-02T10:14:29.340351+00:00'),
('8e10219f-5191-4971-b530-7c3b1ef241fa', 225, 'Segreti di produzione', 'La scelta della locazione neozelandese a Taranaki', 'Le pendici del monte Taranaki in Nuova Zelanda vennero scelte per sostituire visivamente il monte Fuji poiché il paesaggio circostante era rimasto privo di moderne strutture industriali, cavi elettrici o strade asfaltate, offrendo lo sfondo incontaminato richiesto dalla regia.', 'Intervista al location manager Doug Dresser', TRUE, 'IA (Daily Sync)', 'IA Verificata', 0, 2, '2026-11-02T10:14:29.340351+00:00'),
('6c123feb-7efd-48be-8fdc-f606a3ce8ef8', 225, 'Casting & Scelte', 'Il background marziale di Hiroyuki Sanada', 'Hiroyuki Sanada, che interpreta il fedele samurai Ujio, possedeva già una vasta esperienza nelle arti marziali tradizionali giapponesi e nell''uso della spada, elemento che spinse il regista Edward Zwick ad affidargli anche il compito di supervisionare i movimenti scenici degli altri attori.', 'Special ''The Making of The Last Samurai'' nel DVD ufficiale', TRUE, 'IA (Daily Sync)', 'IA Verificata', 0, 3, '2026-11-02T10:14:29.340351+00:00'),
('ab7c5f52-5e8b-4ada-b5ad-d98777dce9b5', 225, 'Aneddoti dal set', 'Le comparse locali come soldati imperiali', 'Circa cinquecento comparse di origine neozelandese e maori vennero ingaggiate per interpretare i soldati dell''esercito imperiale giapponese; furono sottoposte a un addestramento militare intensivo di due settimane per imparare le marce e l''uso dei fucili dell''epoca.', 'Reportage dal set di New Zealand Film Commission', TRUE, 'IA (Daily Sync)', 'IA Verificata', 0, 4, '2026-11-02T10:14:29.340351+00:00'),
('08f853c0-da1c-409c-80c0-4ae1d68695b9', 236, 'Citazioni & Easter Egg', 'L''omaggio a Vertigo di Alfred Hitchcock', 'La scena in cui Madeleine Stowe indossa una parrucca bionda e si trova sotto una luce rossa in un cinema è un esplicito omaggio alla sequenza del film ''Vertigo'' di Alfred Hitchcock in cui James Stewart guarda Kim Novak. Questa scelta visiva sottolinea il tema dell''ossessione e della memoria che attraversa l''intera pellicola di Gilliam.', 'Analisi visiva e critica cinematografica inclusa nel Blu-ray Criterion Collection', TRUE, 'IA (Daily Sync)', 'IA Verificata', 0, 4, '2026-11-02T10:20:07.260077+00:00'),
('779997dd-358b-4236-ab65-6dd1ac65d7b3', 293, 'Curiosità & Retroscena', 'L''ispirazione coreografica di Charlie Chaplin', 'Il modo di camminare e la postura dinoccolata di Arthur Fleck sono stati direttamente modellati da Todd Phillips e Joaquin Phoenix ispirandosi a ''Tempi moderni'' (1936) di Charlie Chaplin, in particolare studiando la camminata sfortunata ma resiliente del celebre Vagabondo.', 'Note di produzione ufficiali Warner Bros. e interviste al regista', TRUE, 'IA (Daily Sync)', 'IA Verificata', 0, 0, '2026-11-02T11:26:49.124646+00:00'),
('b715af01-1daa-4434-a3db-f4c164c4cc27', 293, 'Segreti di produzione', 'Il budget ridotto rispetto agli standard dei cinecomic', 'A differenza dei tradizionali blockbuster sui supereroi che superano regolarmente i 150-200 milioni di dollari, ''Joker'' è stato realizzato con un budget relativamente contenuto di circa 55-70 milioni di dollari, spingendo la produzione a utilizzare location reali a New York e Newark anziché costosi set in CGI.', 'Report finanziario di Variety e note di produzione', TRUE, 'IA (Daily Sync)', 'IA Verificata', 0, 1, '2026-11-02T11:26:49.124646+00:00'),
('04cc8f3b-3777-4ecf-b708-f575bc75385d', 293, 'Aneddoti dal set', 'L''improvvisazione nella scena della camera da letto', 'Durante la sequenza in cui Arthur distrugge la camera da letto dopo aver scoperto la verità sul suo passato e sulla madre, Joaquin Phoenix ha improvvisato quasi l''intera reazione violenta, tra cui il lancio degli oggetti contro il muro, sorprendendo la troupe presente sul set.', 'Dietro le quinte ufficiale e dichiarazioni del direttore della fotografia Lawrence Sher', TRUE, 'IA (Daily Sync)', 'IA Verificata', 0, 2, '2026-11-02T11:26:49.124646+00:00'),
('1379b4d3-823c-491a-84db-134ba31a712a', 293, 'Segreti di produzione', 'La colonna sonora composta prima delle riprese', 'La violoncellista e compositrice islandese Hildur Guðnadóttir ha scritto la pluripremiata colonna sonora del film basandosi unicamente sulla lettura della sceneggiatura iniziale. Todd Phillips ha fatto ascoltare le musiche a Joaquin Phoenix sul set tra una ripresa e l''altra per aiutarlo a entrare nello stato d''animo del personaggio.', 'Intervista ufficiale di Hildur Guðnadóttir e note stampa Warner Bros.', TRUE, 'IA (Daily Sync)', 'IA Verificata', 0, 3, '2026-11-02T11:26:49.124646+00:00'),
('7cc583b0-e0bb-4ebd-bd02-eb8a06b50684', 293, 'Casting & Scelte', 'Il rifiuto iniziale di Joaquin Phoenix', 'Joaquin Phoenix ha inizialmente esitato a lungo prima di accettare la parte, poiché nutriva timori riguardo ai cinecomic e all''impatto mediatico che un personaggio così oscuro avrebbe potuto generare, rifiutando la proposta per diversi mesi prima di cedere e incontrare Todd Phillips.', 'Intervista di Joaquin Phoenix al podcast Happy Sad Confused', TRUE, 'IA (Daily Sync)', 'IA Verificata', 0, 4, '2026-11-02T11:26:49.124646+00:00'),
('65711184-b60b-4a75-80bc-f97bd4b97ff9', 88, 'Segreti di produzione', 'La sostituzione del regista originale', 'Russell Mulcahy fu inizialmente assunto per dirigere il film, ma fu licenziato dopo appena due settimane di riprese a causa di divergenze creative con Sylvester Stallone e i produttori riguardo al tono visivo della pellicola.', 'Note di produzione ufficiali e interviste d''archivio', TRUE, 'IA (Daily Sync)', 'IA Verificata', 0, 0, '2026-11-02T09:57:26.519823+00:00'),
('1b06e8ea-85fd-4f88-a451-2024c470705e', 88, 'Curiosità & Retroscena', 'La scelta della location israeliana', 'Gran parte delle sequenze ambientate in Afghanistan furono in realtà girate in Israele, sfruttando i paesaggi desertici del Negev e le città di Giaffa e Tel Aviv per simulare i villaggi afghani.', 'Documentario sul backstage e crediti di produzione', TRUE, 'IA (Daily Sync)', 'IA Verificata', 0, 1, '2026-11-02T09:57:26.519823+00:00'),
('421723ff-7a7e-462a-8e52-db7376dc3a98', 88, 'Aneddoti dal set', 'I problemi di salute di Sylvester Stallone', 'Durante le riprese nel deserto, Sylvester Stallone contrasse una grave infezione virale aggravata dalla disidratazione e dall''inalazione costante di polvere, costringendo la troupe a sospendere temporaneamente la lavorazione.', 'Biografia ufficiale e bollettini di produzione', TRUE, 'IA (Daily Sync)', 'IA Verificata', 0, 2, '2026-11-02T09:57:26.519823+00:00'),
('58af63c9-105b-4a59-be80-1083f097dc95', 88, 'Effetti speciali & Trucco', 'Il record di armi ed equipaggiamento militare', 'Il dipartimento degli armamenti del film, supervisionato dal maestro d''armi Alan Lupovici, utilizzò un arsenale di oltre cento armi autentiche modificate a salve, inclusi fucili d''assalto sovietici AK-47 originali catturati in Medio Oriente.', 'Special report di riviste di settore armiero e cinematografico', TRUE, 'IA (Daily Sync)', 'IA Verificata', 0, 3, '2026-11-02T09:57:26.519823+00:00'),
('eaf05278-fe31-4b4b-89d6-d3275e0bbe4f', 153, 'Casting & Scelte', 'Il nome originale di Woody era diverso', 'Nelle primissime fasi di sviluppo del film, quando il progetto era ancora intitolato ''A Toy Story'' e la storia prevedeva un Woody molto più sarcastico e antipatico, il personaggio non si chiamava Woody. Il nome fu scelto in seguito in omaggio all''attore caratterista western Woody Strode.', 'The Pixar Story documentario ufficiale e archivi di produzione', TRUE, 'IA (Daily Sync)', 'IA Verificata', 0, 0, '2026-11-02T10:08:30.825147+00:00'),
('f831dca6-cf36-4170-8577-e1c445db3681', 153, 'Casting & Scelte', 'Il nome di Buzz Lightyear ispirato a un astronauta', 'Il nome dello space ranger Buzz Lightyear fu scelto direttamente in onore del celebre astronauta della missione Apollo 11 Edwin ''Buzz'' Aldrin, il secondo uomo a mettere piede sulla Luna.', 'Autobiografia di Buzz Aldrin e note di produzione Pixar', TRUE, 'IA (Daily Sync)', 'IA Verificata', 0, 1, '2026-11-02T10:08:30.825147+00:00'),
('ee18ab70-4846-455d-a832-6e1457d9fc15', 338, 'Casting & Scelte', 'Il ruolo originario di James Gandolfini', 'Prima che Christopher Walken venisse scelto per il ruolo di Frank Abagnale Sr., la produzione aveva valutato diversi attori di grande spessore, tra cui James Gandolfini, reduce dal successo planetario della serie televisiva ''I Soprano''. La parte andò poi a Walken, che ottenne una candidatura all''Oscar come miglior attore non protagonista.', 'Archivio storico di casting di Paramount Pictures', TRUE, 'IA (Daily Sync)', 'IA Verificata', 0, 1, '2026-11-02T14:51:08.58758+00:00'),
('19e9a8f3-a602-45f0-a69a-2edcb9568ae9', 153, 'Curiosità & Retroscena', 'Il rifiuto iniziale di Joss Whedon sul tono del film', 'Joss Whedon, uno degli sceneggiatori accreditati del film, fu chiamato dalla Pixar per correggere la sceneggiatura quando la Disney ordinò di rendere Woody meno crudele. Whedon insistette particolarmente per inserire il personaggio di Barbie, che originariamente avrebbe dovuto salvare la situazione nel finale prima che Mattel negasse i diritti di utilizzo.', 'Interviste storiche a Joss Whedon e libri sul making-of della Pixar', TRUE, 'IA (Daily Sync)', 'IA Verificata', 0, 3, '2026-11-02T10:08:30.825147+00:00'),
('c001f6b2-7489-4900-b10b-693ffdadd3e3', 153, 'Curiosità & Retroscena', 'Il rifiuto della Mattel per Barbie e G.I. Joe', 'La Mattel rifiutò di concedere la licenza per inserire la vera bambola Barbie nel film perché convinta che il lungometraggio sarebbe stato un flop totale; in seguito, dopo il successo planetario al botteghino, l''azienda concesse l''utilizzo del personaggio nei sequel. Anche la Hasbro negò i diritti per G.I. Joe, motivo per cui Sid fu costretto a far saltare in aria un soldatino generico e la testolina di un bambolotto.', 'Documentario ''The Pixar Story'' e biografie ufficiali dello studio', TRUE, 'IA (Daily Sync)', 'IA Verificata', 0, 4, '2026-11-02T10:08:30.825147+00:00'),
('326be65f-85c7-4345-ba31-99a0e4dc57ba', 153, 'Casting & Scelte', 'La voce originale di Rex l''incarnazione della Warner', 'Wallace Shawn, celebre per il suo ruolo in ''La storia fantastica'', fu scelto per doppiare il tirannosauro ansioso Rex grazie alla sua inconfondibile voce nevrotica e insicura, che creava un esilarante contrasto comico con le dimensioni mostruose del dinosauro giocattolo.', 'Note di casting ufficiali e interviste a Wallace Shawn', TRUE, 'IA (Daily Sync)', 'IA Verificata', 0, 5, '2026-11-02T10:08:30.825147+00:00'),
('5682c0c8-8ab8-43a1-98ae-1b909b62335e', 153, 'Segreti di produzione', 'La prima proiezione disastrosa per la Disney', 'Il 19 novembre 1994 si tenne una proiezione preliminare del film incompleto per i dirigenti della Disney, tristemente nota in Pixar come il ''Black Friday''. La versione mostrata presentava un Woody talmente sgradevole e antipatico che la Disney interruppe temporaneamente la produzione e ordinò di riscrivere il personaggio per salvarne la simpatia.', 'Libro ''Pixar: The Company and Its Founders'' di David Price', TRUE, 'IA (Daily Sync)', 'IA Verificata', 0, 6, '2026-11-02T10:08:30.825147+00:00'),
('fbd9e010-4e2b-4212-8bf8-fb03518b5609', 227, 'Aneddoti dal set', 'La cicatrice autentica sul dito di Macaulay Culkin', 'Durante le prove della scena in cui Harry tenta di mordere le dita a Kevin nel covo dei Banditi Sanguinari, Joe Pesci morse per errore troppo forte il dito del giovane Macaulay Culkin, lasciandogli una piccola cicatrice permanente.', 'Intervista a Macaulay Culkin per Time Magazine', TRUE, 'IA (Daily Sync)', 'IA Verificata', 0, 2, '2026-11-02T10:14:43.184226+00:00'),
('c99452b9-cc7b-4cb9-87c3-22afe287f898', 227, 'Effetti speciali & Trucco', 'Il ritratto della fidanzata di Buzz era in realtà un ragazzo truccato', 'Il regista Chris Columbus ritenne che fosse troppo crudele prendere in giro una ragazza vera con la battuta ''Guardala, cicciona'', così la produzione fece indossare una parrucca a un ragazzo, il figlio del direttore artistico Dan Webster, facendolo travestire da ragazza per la foto incorniciata.', 'Intervista al reparto scenografia e design di produzione', TRUE, 'IA (Daily Sync)', 'IA Verificata', 0, 3, '2026-11-02T10:14:43.184226+00:00'),
('dd1a832b-2c39-4f07-9701-1ae00e82e3bc', 227, 'Segreti di produzione', 'La vera casa dei McCallister a Winnetka', 'Le scene interne ed esterne della celebre casa della famiglia McCallister sono state girate principalmente in una villa reale situata al 671 di Lincoln Avenue a Winnetka, nell''Illinois. La proprietà è stata acquistata nel 2012 per oltre 1,5 milioni di dollari.', 'Note di produzione ufficiali della 20th Century Fox', TRUE, 'IA (Daily Sync)', 'IA Verificata', 0, 4, '2026-11-02T10:14:43.184226+00:00'),
('8a1f9e10-e160-435f-8458-1fb2345354aa', 227, 'Aneddoti dal set', 'Daniel Stern e il piede nudo sulla decorazione di Natale', 'Nella sequenza in cui il ladro Marv scala la finestra scalzo e calpesta le palline di Natale, l''attore Daniel Stern indossava in realtà speciali protesi in gomma color carne sagomate come i suoi piedi, permettendogli di camminare sui vetri finti senza correre alcun rischio.', 'Documentario Behind the Scenes di Home Alone', TRUE, 'IA (Daily Sync)', 'IA Verificata', 0, 5, '2026-11-02T10:14:43.184226+00:00'),
('432d1710-2aff-4d19-8540-a03e818c6fdf', 238, 'Casting & Scelte', 'La scelta iniziale di Marlon Brando', 'Nelle prime fasi di sviluppo del film, William Friedkin voleva fortemente Marlon Brando per il ruolo di Padre Lankester Merrin, ma lo studio si oppose fermamente a causa della cattiva pubblicità recente e dei problemi contrattuali dell''attore.', 'Intervista ufficiale a William Friedkin / Documentario Fear of God', TRUE, 'IA (Daily Sync)', 'IA Verificata', 0, 0, '2026-11-02T10:20:14.497413+00:00'),
('e050deb1-458c-4af8-9867-c537280a5334', 91, 'Casting & Scelte', 'La genesi del soggetto da parte di Paul Schrader', 'Lo sceneggiatore Paul Schrader trasse ispirazione per la sceneggiatura, originariamente intitolata ''Déjà Vu'', non solo da Alfred Hitchcock ma anche dalle proprie vicende biografiche e da un''intensa infanzia segnata dal cinema e da un rigido educazionismo calvinista.', 'Note di produzione e biografia ufficiale di Paul Schrader', TRUE, 'IA (Daily Sync)', 'IA Verificata', 0, 0, '2026-11-02T09:57:46.863033+00:00'),
('51e02291-5c77-426d-a02c-ebc72411e0fd', 91, 'Segreti di produzione', 'Il taglio imposto dalla Columbia Pictures', 'Prima che la Columbia Pictures acquistasse i diritti e imponesse tagli per accorciare il minutaggio e rendere il ritmo più commerciale, il film era stato sviluppato per la 20th Century Fox, che aveva rifiutato il progetto ritenendolo troppo rischioso e cupo.', 'Archivi storici della Columbia Pictures e interviste a Brian De Palma', TRUE, 'IA (Daily Sync)', 'IA Verificata', 0, 1, '2026-11-02T09:57:46.863033+00:00'),
('a6244b02-07ad-4e53-990a-02e3775d1e4e', 91, 'Aneddoti dal set', 'L''ispirazione per i movimenti di macchina in Italia', 'Per girare le sequenze italiane, il direttore della fotografia János Zsigmond e Brian De Palma studiarono attentamente l''uso della macchina da presa e le luci morbide presenti nei melodrammi classici degli anni Cinquanta, cercando di replicare la palette cromatica dei dipinti rinascimentali esposti agli Uffizi.', 'Commento audio del direttore della fotografia János Zsigmond nell''edizione home video', TRUE, 'IA (Daily Sync)', 'IA Verificata', 0, 2, '2026-11-02T09:57:46.863033+00:00'),
('15616613-b0dd-4278-938c-52c14cd6b3ef', 154, 'Curiosità & Retroscena', 'La genesi dell''ispirazione per il cattivo Stinky Pete', 'Il design e il carattere scontroso di Stinky Pete il Cercatore d''Oro sono stati parzialmente modellati sui vecchi attori caratteristi di Hollywood che interpretavano i ''cattivi'' nei western degli anni ''40 e ''50, un vero e proprio tributo alla storia del cinema americano classico.', 'The Making of Toy Story 2 - Documentario speciale home video', TRUE, 'IA (Daily Sync)', 'IA Verificata', 0, 1, '2026-11-02T10:08:39.177375+00:00'),
('2f1fac8a-2e62-41fd-b2da-7a12fc6eb29c', 228, 'Casting & Scelte', 'La parcella record di Macaulay Culkin', 'Grazie al successo planetario del primo capitolo, Macaulay Culkin ottenne per questo sequel un compenso strabiliante di 4,5 milioni di dollari, una cifra record per l''epoca per un attore bambino, a cui si aggiunse una percentuale sugli incassi.', 'Variety Production Report / Documenti finanziari 20th Century Fox', TRUE, 'IA (Daily Sync)', 'IA Verificata', 0, 0, '2026-11-02T10:14:51.975075+00:00'),
('3c137535-8b6e-413c-bfda-feec31d88285', 238, 'Aneddoti dal set', 'La gravidanza di Ellen Burstyn nascosta sul set', 'Durante le riprese, l''attrice Ellen Burstyn scoprì di essere incinta del suo terzo figlio, ma decise di non rivelarlo immediatamente alla produzione per non compromettere il suo coinvolgimento nel progetto.', 'Autobiografia di Ellen Burstyn ''Lessons in Becoming Myself''', TRUE, 'IA (Daily Sync)', 'IA Verificata', 0, 1, '2026-11-02T10:20:14.497413+00:00'),
('88341345-c2fc-4ab3-91f9-7f4a2f39190a', 238, 'Casting & Scelte', 'Paul Newman rifiutato per Padre Karras', 'Prima che Jason Miller ottenesse la parte, Paul Newman espresse un forte interesse per il ruolo di Padre Damien Karras, ma William Friedkin preferì attori meno noti e più vicini alla realtà di strada.', 'Note di produzione e archivi della Warner Bros.', TRUE, 'IA (Daily Sync)', 'IA Verificata', 0, 2, '2026-11-02T10:20:14.497413+00:00'),
('dbe4330d-b7b4-40a2-9dda-f4a23b6de58f', 238, 'Curiosità & Retroscena', 'Il rifiuto di Stanley Kubrick alla regia', 'Prima che la Warner Bros. ingaggiasse William Friedkin, la regia del film fu offerta a Stanley Kubrick, il quale declinò cortesemente l''offerta.', 'Archivi storici di produzione Warner Bros.', TRUE, 'IA (Daily Sync)', 'IA Verificata', 0, 3, '2026-11-02T10:20:14.497413+00:00'),
('d698e28b-6911-460a-b78a-6f0361981a05', 238, 'Aneddoti dal set', 'Jack MacGowran e la tragica coincidenza', 'L''attore irlandese Jack MacGowran, che interpretava il regista Burke Dennings, completò le sue scene e morì d''infarto a Londra pochi giorni dopo, alimentando la leggenda metropolitana sulla presunta maledizione del film.', 'Cronache giornalistiche dell''epoca e note di produzione', TRUE, 'IA (Daily Sync)', 'IA Verificata', 0, 4, '2026-11-02T10:20:14.497413+00:00'),
('e22f7a74-dc4d-482b-b70f-38ea99655a3a', 293, 'Aneddoti dal set', 'La gag non scritta sul set di Murray Franklin', 'Nella scena in cui Arthur spara a Murray Franklin in diretta televisiva, la battuta finale pronunciata da Arthur subito dopo l''atto (''That''s life!'') è stata perfezionata durante le prove, ma il gesto di baciare la fronte di Robert De Niro prima di allontanarsi è stato un momento estemporaneo provato da Phoenix durante le riprese.', 'Intervista al montatore Jeff Groth e al regista Todd Phillips', TRUE, 'IA (Daily Sync)', 'IA Verificata', 0, 5, '2026-11-02T11:26:49.124646+00:00'),
('f81e187a-d306-49f0-8fdb-841440487f57', 338, 'Segreti di produzione', 'La collaborazione con il vero Frank Abagnale per la valigetta', 'Durante la preparazione del film, Leonardo DiCaprio ha lavorato a stretto contatto con il vero Frank Abagnale Jr. per imparare i trucchi reali della falsificazione degli assegni. Abagnale ha insegnato personalmente all''attore come stampare assegni falsi usando una macchina marcatrice e come staccare i loghi delle compagnie aeree dalle posate per incollarli sui modellini.', 'Commento audio del DVD con Steven Spielberg e Frank Abagnale Jr.', TRUE, 'IA (Daily Sync)', 'IA Verificata', 0, 2, '2026-11-02T14:51:08.58758+00:00'),
('380c3ba9-1e4c-42c6-97f2-4db7e755d397', 338, 'Aneddoti dal set', 'L''improvvisazione di Christopher Walken sulla cravatta', 'Durante le riprese della toccante scena in cui il giovane Frank incontra il padre caduto in disgrazia all''interno di un ristorante, Christopher Walken improvvisò alcuni dettagli della gestualità e della battuta sulla ''storia dei due topi nel secchio di panna'', arricchendo emotivamente una sequenza chiave del rapporto padre-figlio.', 'Making-of ufficiale ''Catch Me If You Can: Behind the Camera''', TRUE, 'IA (Daily Sync)', 'IA Verificata', 0, 3, '2026-11-02T14:51:08.58758+00:00'),
('20b2c180-f42e-4035-82a7-5a32954ab10c', 338, 'Segreti di produzione', 'I costumi d''epoca firmati da Mary Zophres', 'La costumista Mary Zophres ha realizzato oltre 50 abiti su misura per Leonardo DiCaprio e ha studiato meticolosamente i cataloghi di moda della Pan Am degli anni ''60. Ogni divisa indossata da DiCaprio e dalle comparse nel ruolo di hostess e piloti rispecchiava rigorosamente i regolamenti ufficiali delle compagnie aeree dell''epoca.', 'Intervista alla costumista Mary Zophres per Costume Designers Guild', TRUE, 'IA (Daily Sync)', 'IA Verificata', 0, 4, '2026-11-02T14:51:08.58758+00:00'),
('c744827a-e115-4812-a35e-781646340bdc', 338, 'Segreti di produzione', 'La scelta della pellicola e della fotografia', 'Il direttore della fotografia Janusz Kamiński ha scelto di utilizzare l''illuminazione naturale e una palette di colori caldi e saturi per ricreare la particolare atmosfera nostalgica e patinata degli anni ''60, ispirandosi alle riviste illustrate come Life e alle campagne pubblicitarie dell''epoca.', 'American Cinematographer, articolo tecnico sulla produzione', TRUE, 'IA (Daily Sync)', 'IA Verificata', 0, 5, '2026-11-02T14:51:08.58758+00:00'),
('0caf0e6a-bf5b-4d68-9044-613557c0e111', 338, 'Casting & Scelte', 'Il cameo di Barry Shabaka Henley nei panni di un agente', 'L''attore caratterista Barry Shabaka Henley, noto per le sue frequenti collaborazioni con registi del calibro di Michael Mann, ha ottenuto il ruolo dell''agente dell''FBI Livingston dopo una specifica richiesta di Steven Spielberg, che lo aveva apprezzato in ''Collateral'' e ''The Terminal''.', 'Note di produzione DreamWorks Pictures', TRUE, 'IA (Daily Sync)', 'IA Verificata', 0, 6, '2026-11-02T14:51:08.58758+00:00'),
('970ed681-8c80-438a-bf21-6198737f68f7', 228, 'Effetti speciali & Trucco', 'La neve artificiale a New York', 'Durante le riprese effettuate in esterni a New York nel dicembre del 1991, le condizioni meteorologiche non offrirono la neve desiderata dalla produzione, costringendo i tecnici a utilizzare enormi quantità di fiocchi di purè di patate istantaneo e schiuma di sapone biodegradabile.', 'Note di produzione ufficiali 20th Century Fox', TRUE, 'IA (Daily Sync)', 'IA Verificata', 0, 1, '2026-11-02T10:14:51.975075+00:00'),
('addbe01e-e91d-403d-9b7e-80d773c8550f', 92, 'Casting & Scelte', 'La voce doppiata di Massimo Girotti', 'Massimo Girotti, che interpretava il protagonista Gino Costa, aveva una spiccata inflessione toscana che mal si conciliava con il personaggio del vagabondo romagnolo. Per questo motivo, in fase di post-produzione, la sua voce fu interamente ridoppiata dal celebre attore e doppiatore Gualtiero De Angelis.', 'Note di edizione e storiche della pellicola', TRUE, 'IA (Daily Sync)', 'IA Verificata', 0, 0, '2026-11-02T09:57:53.939052+00:00'),
('ab387d34-1b80-4e2b-9121-8735eca89e41', 92, 'Segreti di produzione', 'La finta tessera del partito per eludere i controlli', 'Durante le riprese in esterna sul delta del Po, per evitare l''interruzione dei lavori da parte delle autorità locali sospettose, lo scenografo Luigi Zampa e la troupe si muovevano esibendo false tessere del Partito Nazionale Fascista fornite da membri della resistenza romana infiltrati negli ambienti cinematografici.', 'Memorie di produzione di Giuseppe De Santis', TRUE, 'IA (Daily Sync)', 'IA Verificata', 0, 1, '2026-11-02T09:57:53.939052+00:00'),
('d79ce657-2877-4653-90f2-56cf874c6680', 92, 'Curiosità & Retroscena', 'Il titolo alternativo evitato per pudore', 'Nelle primissime fasi di lavorazione e stesura del copione, Luchino Visconti e i suoi collaboratori avevano accarezzato l''idea di intitolare il film ''Palude'' per sottolineare il senso di marcescenza morale dei protagonisti, scartato poi perché ritenuto troppo debole commercialmente prima di optare per il definitivo ''Ossessione''.', 'Archivi storici della Lux Film', TRUE, 'IA (Daily Sync)', 'IA Verificata', 0, 2, '2026-11-02T09:57:53.939052+00:00'),
('44144ec6-ee41-497d-ad1a-78feeb140280', 92, 'Segreti di produzione', 'Juan de La Encina e la colonna sonora', 'Luchino Visconti scelse personalmente di inserire brani di musica rinascimentale spagnola, in particolare opere del compositore Juan de La Encina, per accompagnare alcune sequenze chiave, creando un contrasto stridente e modernissimo con la sordida realtà della provincia italiana.', 'Analisi musicologiche della colonna sonora di Ossessione', TRUE, 'IA (Daily Sync)', 'IA Verificata', 0, 3, '2026-11-02T09:57:53.939052+00:00'),
('4c6efbda-4c9d-4c1e-84ab-508687b637a2', 92, 'Casting & Scelte', 'Il cameo mancato di Mario Alicata', 'Mario Alicata, co-sceneggiatore del film insieme a Gianni Puccini, Mario Serandrei e allo stesso Visconti, avrebbe dovuto apparire in un piccolo cameo nei panni di un cliente della trattoria, ma l''idea fu abbandonata all''ultimo momento per non destare i sospetti della censura cinematografica sui trascorsi politici della redazione di ''Cinema''.', 'Testimonianze d''archivio del gruppo di Cinema', TRUE, 'IA (Daily Sync)', 'IA Verificata', 0, 4, '2026-11-02T09:57:53.939052+00:00'),
('5d89ac83-d572-4e0c-b278-6aa6b6ba5cc3', 228, 'Aneddoti dal set', 'L''infortunio allo stomaco di Joe Pesci', 'L''attore Joe Pesci rimase realmente ustionato alla mano sinistra nella scena in cui la porta della casa di via Santa Maria si incendia, riportando segni che richiesero cure mediche durante le riprese a Chicago.', 'Intervista retrospettiva a Joe Pesci / Making-of Home Alone 2', TRUE, 'IA (Daily Sync)', 'IA Verificata', 0, 2, '2026-11-02T10:14:51.975075+00:00'),
('e683dfc6-05e9-436c-bd20-d51710aac3b1', 239, 'Curiosità & Retroscena', 'La melodia del terrore composta in pochi giorni', 'Il celebre tema musicale in 5/4 di ''Halloween'' fu composto personalmente da John Carpenter in soli tre giorni, ispirandosi agli esercizi al pianoforte che suo padre gli faceva studiare da bambino e alla ritmica di ''Suspiria'' dei Goblin.', 'Documentario ''Halloween: A Cut Above the Rest'' e commento audio del regista', TRUE, 'IA (Daily Sync)', 'IA Verificata', 0, 0, '2026-11-02T10:21:05.094559+00:00'),
('d3983d03-dd1a-436c-805e-e276b25e90f8', 239, 'Segreti di produzione', 'La paga simbolica di John Carpenter', 'Data la ristrettezza estrema del budget di 300.000 dollari, John Carpenter accettò di dirigere, co-sceneggiare e comporre la colonna sonora del film per una cifra irrisoria, accontentandosi di soli 10.000 dollari di compenso iniziale in cambio del 10% dei profitti netti.', 'Note di produzione ufficiali e biografie autorizzate di John Carpenter', TRUE, 'IA (Daily Sync)', 'IA Verificata', 0, 1, '2026-11-02T10:21:05.094559+00:00'),
('0c3c1823-00dd-447f-9bc9-26a9323b8e58', 239, 'Casting & Scelte', 'Il ruolo di Laurie Strode offerto ad altre attrici', 'Prima di assegnare la parte della protagonista a Jamie Lee Curtis (scelta anche come mossa pubblicitaria per la sua celebre madre Janet Leigh), John Carpenter aveva offerto il ruolo di Laurie Strode ad Anne Lockhart, che rifiutò per impegni televisivi.', 'Interviste d''archivio al casting director e a Jamie Lee Curtis', TRUE, 'IA (Daily Sync)', 'IA Verificata', 0, 2, '2026-11-02T10:21:05.094559+00:00'),
('f151f64a-4ee7-453a-83ff-ecdddaaaff70', 239, 'Citazioni & Easter Egg', 'L''origine cinematografica dello pseudonimo di Loomis', 'La scelta del cognome ''Loomis'' per il personaggio di Donald Pleasence fa diretto riferimento anche al personaggio interpretato da John Gavin (Sam Loomis) nel capolavoro ''Psycho'' di Alfred Hitchcock del 1960.', 'Interviste a John Carpenter e Debra Hill nei contenuti speciali dell''edizione Blu-ray', TRUE, 'IA (Daily Sync)', 'IA Verificata', 0, 3, '2026-11-02T10:21:05.094559+00:00'),
('9654ce3d-7827-4aa4-b885-cd8ddba219c5', 239, 'Aneddoti dal set', 'Nick Castle pagato venticinque dollari al giorno', 'Nick Castle, l''amico di college di Carpenter che interpretò la forma adulta di Michael Myers (accreditato come ''The Shape''), lavorò sul set per pochi giorni percependo un salario giornaliero di appena 25 dollari.', 'Documentario ''The Making of Halloween'' e interviste a Nick Castle', TRUE, 'IA (Daily Sync)', 'IA Verificata', 0, 4, '2026-11-02T10:21:05.094559+00:00'),
('aaafbb89-2b3b-4688-b8a7-398e952f323e', 239, 'Aneddoti dal set', 'La sigaretta continua di Tommy Lee Wallace', 'Durante le riprese, lo scenografo e co-montatore Tommy Lee Wallace fu incaricato anche di supervisionare la continuità visiva, spesso dovendo correre da una scena all''altra con la sua inseparabile sigaretta tra le mani, creando non pochi grattacapi per i raccordi.', 'Commento audio del cast e della troupe nell''edizione speciale del trentennale', TRUE, 'IA (Daily Sync)', 'IA Verificata', 0, 5, '2026-11-02T10:21:05.094559+00:00'),
('d2b45a23-9f74-4ef2-b828-4b41d5a5663f', 294, 'Curiosità & Retroscena', 'La sequenza di apertura e il seminterrato reale', 'Per studiare accuratamente le condizioni di vita dei seminterrati a Seul (noti come banjiha), il regista Bong Joon-ho e il direttore della fotografia Hong Kyung-pyo hanno visitato reali abitazioni simili a quella dei Kim, analizzando l''umidità e l''angolazione della luce naturale che filtrava dalle finestre a livello strada.', 'Commento audio del regista e note di produzione ufficiali', TRUE, 'IA (Daily Sync)', 'IA Verificata', 0, 0, '2026-11-02T11:26:56.27478+00:00'),
('3070b324-fa2e-4241-88e0-5e92b57e94b8', 294, 'Curiosità & Retroscena', 'La colonna sonora classica e i Beatles', 'Il compositore Jaeil Jung ha utilizzato una struttura orchestrale barocca per la colonna sonora, inserendo esplicitamente il brano ''In Gook-dong'' e citando le atmosfere della canzone ''A Hard Day''s Night'' dei Beatles per sottolineare il ritmo frenetico della farsa messa in piedi dalla famiglia Kim.', 'Note di copertina dell''album della colonna sonora ufficiale', TRUE, 'IA (Daily Sync)', 'IA Verificata', 0, 1, '2026-11-02T11:26:56.27478+00:00'),
('34b4e583-468a-4fb8-8e95-0f8ecfed73ca', 294, 'Curiosità & Retroscena', 'Il premio della critica a Cannes e la votazione unanime', 'Alla 72ª edizione del Festival di Cannes nel 2019, la giuria presieduta da Alejandro G. Iñárritu ha assegnato la Palma d''Oro a Parasite con un voto unanime, un evento che non accadeva dai tempi di La vita di Adele nel 2013.', 'Comunicato ufficiale della giuria del Festival di Cannes 2019', TRUE, 'IA (Daily Sync)', 'IA Verificata', 0, 2, '2026-11-02T11:26:56.27478+00:00'),
('19c4dfa0-6953-4a79-9a60-12fc6981939d', 338, 'Aneddoti dal set', 'Le difficoltà logistiche delle 147 scene', 'Le riprese del film si sono svolte in soli 52 giorni tra il New York, Los Angeles, Québec e Montréal, richiedendo un ritmo di lavoro serratissimo che costringeva la troupe a cambiare set e ricostruire epoche diverse nello stesso giorno, sfruttando anche la somiglianza di Montréal con le strade europee degli anni ''60.', 'Diario di bordo delle riprese pubblicato su Variety', TRUE, 'IA (Daily Sync)', 'IA Verificata', 0, 7, '2026-11-02T14:51:08.58758+00:00'),
('095f313b-e719-4a65-9e0a-6d7e615eadd1', 97, 'Aneddoti dal set', 'L''incidente quasi fatale durante la corsa delle bighe', 'Durante le riprese della celebre corsa delle bighe, lo stuntman e pilota della biga di Messala rischierà la vita in un ribaltamento spettacolare ma non pianificato, che fu immortalato nel montaggio finale del film.', 'Note di produzione MGM e archivi storici della stampa cinematografica del 1925', TRUE, 'IA (Daily Sync)', 'IA Verificata', 0, 0, '2026-11-02T09:59:12.568776+00:00'),
('09460129-685b-45b1-b7f0-d4618ae48096', 97, 'Segreti di produzione', 'Il budget record e il rischio finanziario per la Goldwyn', 'Con un costo finale stimato intorno ai 3,9 milioni di dollari dell''epoca, Ben-Hur fu la produzione più costosa del cinema muto, spingendo la neonata MGM (guidata da Louis B. Mayer e Irving Thalberg) sull''orlo del fallimento prima del suo trionfale ritorno economico.', 'Documenti contabili della Metro-Goldwyn-Mayer e biografie ufficiali di Irving Thalberg', TRUE, 'IA (Daily Sync)', 'IA Verificata', 0, 1, '2026-11-02T09:59:12.568776+00:00'),
('cc154f1d-bbc3-4c6c-b38f-c2db17dc26ec', 97, 'Casting & Scelte', 'La sostituzione last-minute del regista Charles Brabin', 'Prima che Fred Niblo assumesse la direzione della pellicola, la regia era stata affidata a Charles Brabin, il quale diresse le primissime settimane di lavorazione in Italia prima di essere licenziato dalla produzione a causa di divergenze artistiche e ritmi ritenuti troppo lenti.', 'Archivi storici di produzione della Goldwyn Pictures', TRUE, 'IA (Daily Sync)', 'IA Verificata', 0, 2, '2026-11-02T09:59:12.568776+00:00'),
('93fd23e4-8757-4a9b-b69c-3ffb6881d497', 97, 'Segreti di produzione', 'Il coinvolgimento della Marina Militare italiana', 'Per girare la complessa e grandiosa sequenza della battaglia navale contro i pirati cilici, la produzione ottenne il supporto logistico diretto della Regia Marina italiana, che mise a disposizione navi e personale nel Mar Mediterraneo.', 'Reportage d''epoca sui set italiani della troupe di Ben-Hur', TRUE, 'IA (Daily Sync)', 'IA Verificata', 0, 3, '2026-11-02T09:59:12.568776+00:00'),
('affa3e48-39d6-426c-a53e-ddf33a819f62', 154, 'Aneddoti dal set', 'Il doppiaggio di Tim Allen e Tom Hanks in contemporanea', 'A differenza di quanto accade solitamente nell''animazione dove gli attori registrano le battute separatamente in momenti diversi, Tom Hanks e Tim Allen vollero registrare alcune delle loro scene chiave insieme in studio per massimizzare la naturalezza e la chimica tra Woody e Buzz.', 'Intervista d''archivio a Tom Hanks per il press kit cinematografico del 1999', TRUE, 'IA (Daily Sync)', 'IA Verificata', 0, 2, '2026-11-02T10:08:39.177375+00:00'),
('4923f6d0-aeb0-4155-bdbb-283d7945991f', 339, 'Segreti di produzione', 'La gestazione ventennale del progetto', 'Martin Scorsese iniziò a concepire il film nel 1970, ispirandosi al libro omonimo di Herbert Asbury del 1928, ma la produzione fu bloccata per decenni a causa della difficoltà nel trovare i finanziamenti adeguati e la major disposta a sostenere un budget così elevato.', 'Note di produzione ufficiali e interviste retrospettive a Martin Scorsese', TRUE, 'IA (Daily Sync)', 'IA Verificata', 0, 0, '2026-11-02T14:51:13.447724+00:00'),
('5c4a9873-adb8-47c3-83be-3157a9fccbf2', 154, 'Casting & Scelte', 'La vera voce dietro l''imperatore Zurg', 'Il ruolo dell''Imperatore Zurg fu originariamente interpretato dall''attore Andrew Stanton, co-sceneggiatore e regista di lunga data della Pixar, il quale prestò temporaneamente la sua voce per le registrazioni guida che piacquero così tanto alla produzione da rimanere in gran parte nel montaggio finale del film.', 'Crediti di doppiaggio ufficiali e note di produzione Pixar', TRUE, 'IA (Daily Sync)', 'IA Verificata', 0, 4, '2026-11-02T10:08:39.177375+00:00'),
('2de01150-74df-4407-9711-286310a9a54b', 256, 'Casting & Scelte', 'La vera età dell''attore che interpretava Paul Edgecomb da anziano', 'L''attore Dabbs Greer, che interpreta Paul Edgecomb nella cornice temporale da anziano nella casa di riposo, aveva 82 anni durante le riprese del film. Per un curioso scherzo del destino, Greer era nato nel 1917, lo stesso anno in cui è ambientata la sequenza iniziale del flashback del 1932 nel penitenziario.', 'Note di produzione ufficiali Warner Bros. e crediti del film', TRUE, 'IA (Daily Sync)', 'IA Verificata', 0, 0, '2026-11-02T10:15:00.630613+00:00'),
('adc237fd-2a2b-4293-bdea-573fa90ae7a9', 256, 'Effetti speciali & Trucco', 'Il trucco invecchiante di Dabbs Greer', 'Sebbene Dabbs Greer fosse realmente un attore anziano, la produzione impiegò ore di trucco prostetico quotidiano guidato dal celebre make-up artist Greg Cannom per aggiungere ulteriore età al suo volto, facendolo apparire come un centenario ultranovantenne.', 'Documentario dietro le quinte ''Walking the Mile: The Making of The Green Mile''', TRUE, 'IA (Daily Sync)', 'IA Verificata', 0, 1, '2026-11-02T10:15:00.630613+00:00'),
('bd9ff332-8f2e-4305-9033-b91a7096970c', 256, 'Segreti di produzione', 'La scelta del vero penitenziario in Tennessee', 'Le scene esterne e alcune sequenze interne del carcere non furono girate in un set ricostruito in studio, bensì all''interno del Tennessee State Penitentiary di Nashville, una struttura carceraria realmente dismessa dal 1992 che conferì alle riprese un cupo realismo storico.', 'Location manager scouting report e interviste sul set', TRUE, 'IA (Daily Sync)', 'IA Verificata', 0, 2, '2026-11-02T10:15:00.630613+00:00'),
('6a02d355-2724-4422-bddf-f0dc86a076b1', 256, 'Aneddoti dal set', 'I problemi legali e la chiusura definitiva del set carcerario', 'La produzione di Frank Darabont fu la prima e l''ultima troupe cinematografica a ottenere il permesso di girare all''interno del famigerato Tennessee State Penitentiary; dopo le riprese del film, le autorità locali vietarono permanentemente l''accesso a qualsiasi altra troupe a causa del degrado strutturale dell''edificio.', 'Archivio storico della Nashville Film Commission', TRUE, 'IA (Daily Sync)', 'IA Verificata', 0, 3, '2026-11-02T10:15:00.630613+00:00'),
('e833415d-2174-4a3b-a704-0168c544d0e9', 256, 'Curiosità & Retroscena', 'La colonna sonora candidata all''Oscar di Thomas Newman', 'Il compositore Thomas Newman ottenne una nomination agli Academy Awards per la sua toccante colonna sonora del film. Newman utilizzò strumenti d''epoca e arrangiamenti orchestrali minimalisti per evocare l''atmosfera della Grande Depressione americana.', 'Database ufficiale Academy of Motion Picture Arts and Sciences', TRUE, 'IA (Daily Sync)', 'IA Verificata', 0, 4, '2026-11-02T10:15:00.630613+00:00'),
('5f9c6885-a850-48c8-9af2-f587f116f760', 240, 'Citazioni & Easter Egg', 'L''inclusione della celebre tartaruga Maturin', 'Nel film è presente un omaggio nascosto a Maturin, la tartaruga cosmica e divinità benevola del romanzo originale di Stephen King. Durante la scena in cui i ragazzi fanno il bagno nella cava, uno dei membri del Club dei Perdenti recupera brevemente una piccola tartaruga giocattolo dall''acqua, mentre un ulteriore riferimento visivo compare sotto forma di blocchi da costruzione con una tartaruga nella camera da letto di Georgie.', 'Commento audio del regista Andy Muschietti e note di produzione', TRUE, 'IA (Daily Sync)', 'IA Verificata', 0, 0, '2026-11-02T10:21:12.130096+00:00'),
('e5ac509b-3c95-4b64-80c0-45a550fa600d', 240, 'Citazioni & Easter Egg', 'Il tributo al cinema horror anni ''50 e ''80', 'La facciata del cinema in cui i ragazzi passano durante l''estate mostra i titoli di programmazione reali dell''epoca in cui è ambientato il film, tra cui ''Arma letale'' e ''Nightmare 3 - I guerrieri del sogno'', distribuiti dalla Warner Bros. Inoltre, il design del proiettore utilizzato da Richie e Ben nel vicolo corrisponde esattamente ai modelli portatili usati nelle scuole americane negli anni ottanta.', 'Dipartimento Scenografia e Continuity Book di produzione', TRUE, 'IA (Daily Sync)', 'IA Verificata', 0, 1, '2026-11-02T10:21:12.130096+00:00'),
('590e1614-eae0-4b86-bec1-cf663510b596', 240, 'Segreti di produzione', 'La scelta della cittadina di Port Hope come Derry', 'Le riprese esterne della fittizia cittadina di Derry non sono state effettuate nel Maine, ma a Port Hope, nell''Ontario (Canada). La produzione ha investito mesi per modificare i lampioni, la segnaletica stradale e la facciata di diversi edifici storici locali per riprodurre fedelmente l''atmosfera della provincia americana della fine degli anni ottanta.', 'Town of Port Hope Official Film Documentation e Production Notes', TRUE, 'IA (Daily Sync)', 'IA Verificata', 0, 2, '2026-11-02T10:21:12.130096+00:00'),
('17a2bea2-20af-4057-bcc3-106153921c87', 98, 'Casting & Scelte', 'Il compenso record per Charlton Heston', 'Charlton Heston accettò di interpretare Giuda Ben-Hur per un cachet di 250.000 dollari più una percentuale del 10% sui profitti netti del film, una cifra all''epoca straordinaria che rese l''attore estremamente ricco grazie al clamoroso successo commerciale della pellicola.', 'Archivi ufficiali della Metro-Goldwyn-Mayer', TRUE, 'IA (Daily Sync)', 'IA Verificata', 0, 0, '2026-11-02T09:59:26.793223+00:00'),
('5b6ee4f5-13eb-48cb-9b8a-38f946062480', 98, 'Casting & Scelte', 'La scelta iniziale di Burt Lancaster', 'Prima che la parte venisse offerta a Paul Newman e infine assegnata a Charlton Heston, i produttori della MGM avevano pensato a Burt Lancaster per il ruolo del protagonista Giuda Ben-Hur, ma l''attore rifiutò l''offerta.', 'Note di produzione e biografie ufficiali di William Wyler', TRUE, 'IA (Daily Sync)', 'IA Verificata', 0, 1, '2026-11-02T09:59:26.793223+00:00'),
('0444ad73-3309-4344-9e92-713ea2b41af8', 98, 'Segreti di produzione', 'La colonna sonora da record di Miklós Rózsa', 'Il compositore Miklós Rózsa impiegò oltre un anno per scrivere la colonna sonora del film, registrando la musica a Roma con l''orchestra della Sinfonica di Roma composta da ben 100 elementi, creando la più lunga partitura mai scritta per un film fino ad allora.', 'Note di copertina delle edizioni speciali della colonna sonora', TRUE, 'IA (Daily Sync)', 'IA Verificata', 0, 2, '2026-11-02T09:59:26.793223+00:00'),
('d36b1305-da4a-4276-95ec-e5a306f67d12', 98, 'Aneddoti dal set', 'L''infortunio evitato da Yakima Canutt', 'Il leggendario coordinatore degli stuntman Yakima Canutt diresse la scena della corsa delle bighe e supervisionò personalmente il famoso salto in cui la biga di Ben-Hur travolge un carro distrutto; suo figlio Joe Canutt eseguì lo stunt rischiando seriamente la vita a causa di un quasi distacco dalle redini.', 'Autobiografia di Yakima Canutt e documentari di making-of', TRUE, 'IA (Daily Sync)', 'IA Verificata', 0, 3, '2026-11-02T09:59:26.793223+00:00');
INSERT INTO public.movie_trivia ("id", "film_id", "categoria", "titolo", "descrizione", "fonte", "approvato", "inserito_da", "provenienza", "likes", "ordine", "created_at") VALUES
('c45d63fc-996c-457e-aaf4-63e72e57ef26', 98, 'Aneddoti dal set', 'La cicatrice accidentale di Stephen Boyd', 'Durante le prove preliminari della corsa delle bighe, Stephen Boyd fu sbalzato fuori dal suo veicolo e si ferì al volto; il regista William Wyler fu costretto a riorganizzare le riprese evitando primi piani del lato sinistro del viso dell''attore fino alla completa guarigione.', 'Interviste retrospettive a Stephen Boyd', TRUE, 'IA (Daily Sync)', 'IA Verificata', 0, 4, '2026-11-02T09:59:26.793223+00:00'),
('5d194d28-f778-4226-b1cd-178d9bfadadb', 155, 'Segreti di produzione', 'La riproduzione del vero asilo della figlia del regista', 'Per ricostruire fedelmente l''atmosfera caotica e vissuta dell''asilo Sunnyside, gli scenografi della Pixar hanno compiuto sopralluoghi approfonditi nell''asilo frequentato dalla figlia del regista Lee Unkrich, fotografando ogni dettaglio dai giocattoli consumati ai segni sui pavimenti.', 'The Art of Toy Story 3 / Commento audio del regista', TRUE, 'IA (Daily Sync)', 'IA Verificata', 0, 0, '2026-11-02T10:08:45.808394+00:00'),
('0f5e9f05-5033-48f0-b6a3-a8f0a35e30aa', 155, 'Citazioni & Easter Egg', 'L''omaggio nascosto a Il grande fuga', 'La celebre sequenza in cui Buzz Lightyear tenta di liberarsi dalle manette nel cortile del Sunnyside è un riferimento visivo diretto al film del 1963 ''La grande fuga'' (The Great Escape), con Steve McQueen, riproducendo persino il celebre lancio della palla da baseball contro il muro.', 'Visual Commentary e note di produzione Pixar', TRUE, 'IA (Daily Sync)', 'IA Verificata', 0, 1, '2026-11-02T10:08:45.808394+00:00'),
('fad5ae78-a73f-42aa-bd8b-69b474df5139', 155, 'Casting & Scelte', 'Il ritorno di John Morris come voce di Andy', 'John Morris, che aveva doppiato il piccolo Andy nei primi due film quando era un bambino, è tornato a doppiare il personaggio diciassettenne in Toy Story 3 all''età di 24 anni, modulando la voce per risultare credibile come un giovane pronto per il college.', 'Crediti ufficiali e interviste promozionali del film', TRUE, 'IA (Daily Sync)', 'IA Verificata', 0, 2, '2026-11-02T10:08:45.808394+00:00'),
('a4608dc4-689c-4939-b644-736b680e8161', 155, 'Segreti di produzione', 'La scena della discarica e il rischio di fusione', 'La drammatica sequenza della discarica ha richiesto lo sviluppo di un motore di rendering completamente nuovo per simulare il comportamento della plastica fusa ad altissime temperature, un''impresa tecnica che ha messo a dura prova le workstation di rendering dello studio.', 'Making-of ufficiale Disney-Pixar', TRUE, 'IA (Daily Sync)', 'IA Verificata', 0, 3, '2026-11-02T10:08:45.808394+00:00'),
('eed9bee7-f683-4dec-b551-bd80fbe4e75b', 155, 'Casting & Scelte', 'La partecipazione di Michael Keaton nei panni di Ken', 'L''attore Michael Keaton è stato fortemente voluto per la parte di Ken dopo che i produttori hanno notato la sua incredibile autoironia nell''accettare di interpretare un bambolotto alla moda, improvvisando molte delle battute sulla sua vasta collezione di abiti nella stanza di Barbie.', 'Intervista ufficiale a Lee Unkrich e Darla K. Anderson', TRUE, 'IA (Daily Sync)', 'IA Verificata', 0, 4, '2026-11-02T10:08:45.808394+00:00'),
('efae52a3-a437-42a5-9ef5-490af289c3f1', 259, 'Curiosità & Retroscena', 'La connessione genealogica con Roald Dahl', 'Sophie Dahl, modella e scrittrice nonché nipote di Roald Dahl, ha visitato il set durante le riprese a Londra ed è rimasta profondamente commossa nel vedere come Paul King sia riuscito a catturare lo spirito autentico e la tonalità emotiva dei lavori di suo nonno.', 'Note di produzione ufficiali Warner Bros.', TRUE, 'IA (Daily Sync)', 'IA Verificata', 0, 0, '2026-11-02T10:15:11.538343+00:00'),
('8d1710a4-de97-49f7-a03a-e06d2388dc5a', 259, 'Casting & Scelte', 'La preparazione circense di Calah Lane', 'Per interpretare il ruolo di Noodle, la giovane attrice Calah Lane ha dovuto sottoporsi a settimane di rigoroso addestramento fisico prima dell''inizio delle riprese, imparando a girare le scene in cui viene imbragata e sollevata in aria tramite cavi.', 'Intervista promozionale del cast', TRUE, 'IA (Daily Sync)', 'IA Verificata', 0, 1, '2026-11-02T10:15:11.538343+00:00'),
('56759b00-386d-414f-a035-adc430dda002', 259, 'Segreti di produzione', 'L''ispirazione visiva tratta da Paddington', 'Il regista Paul King ha utilizzato lo stesso direttore della fotografia dei suoi precedenti film su Paddington, Chung-hoon Chung, per confermare una palette cromatica calda, fiabesca e fortemente nostalgica che richiamasse i musical classici di Hollywood degli anni Cinquanta.', 'Special TV di approfondimento tecnico', TRUE, 'IA (Daily Sync)', 'IA Verificata', 0, 2, '2026-11-02T10:15:11.538343+00:00'),
('59ae5dc9-5727-443a-a583-e7f3e348ad7b', 240, 'Aneddoti dal set', 'L''uso della lingua tedesca per le urla di Pennywise', 'Per ottenere il suono gutturale e disturbante del pianto di Pennywise nella scena del pozzo, Bill Skarsgård ha studiato registrazioni di vocalizzi tradizionali svedesi e tedeschi. L''attore ha rivelato in diverse interviste promozionali di essersi ispirato a tecniche di canto golarizzato e fonetica baltica per rendere la voce del mostro completamente aliena e innaturale.', 'Intervista ufficiale di Bill Skarsgård al Jimmy Fallon Show', TRUE, 'IA (Daily Sync)', 'IA Verificata', 0, 3, '2026-11-02T10:21:12.130096+00:00'),
('e362147f-2fcc-479c-80ec-2d53ea77e0c5', 295, 'Curiosità & Retroscena', 'La controversia sul marchio e i consulenti culturali', 'Nel 2013 la Disney tentò di registrare il marchio ''Día de los Muertos'' per il merchandising del film, scatenando una furiosa protesta nella comunità messicana guidata dal fumettista Lalo Alcaraz con la vignetta di protesta ''Muerto Mouse''. La Disney ritirò immediatamente la richiesta e assunse proprio Alcaraz, insieme alla drammaturga Marcela Davison Avilés e allo scrittore Octavio Solis, come consulenti culturali per supervisionare ogni dettaglio narrativo e visivo del progetto.', 'Dichiarazioni ufficiali Disney e interviste a Lalo Alcaraz su Los Angeles Times', TRUE, 'IA (Daily Sync)', 'IA Verificata', 0, 0, '2026-11-02T11:30:47.876357+00:00'),
('83312cea-fd0b-4bd8-95c7-3d32f566926a', 100, 'Segreti di produzione', 'La bancarotta della Prana-Film', 'Nosferatu fu l''unico film prodotto dalla Prana-Film, una casa di produzione fondata da Albin Grau e Enrico Dieckmann nel 1921. A causa dei costi legali insostenibili derivanti dalla causa intentata dagli eredi di Bram Stoker per violazione di copyright, la compagnia dichiarò bancarotta subito dopo l''uscita del film, chiudendo definitivamente i battenti.', 'Archivi storici della cinematografia tedesca / Saggi storiografici di Lotte Eisner', TRUE, 'IA (Daily Sync)', 'IA Verificata', 0, 0, '2026-11-02T09:59:46.172792+00:00'),
('afd89c48-8d45-4e45-b443-d4ecbc12fd15', 100, 'Curiosità & Retroscena', 'La distruzione della quasi totalità delle copie', 'Nel luglio del 1922, un tribunale tedesco ordinò la distruzione di tutti inegativi e delle copie esistenti di Nosferatu in seguito alla vittoria legale di Florence Stoker. Tuttavia, alcune copie erano già state esportate clandestinamente all''estero, in particolare in Francia e Inghilterra, permettendo al capolavoro di Murnau di sopravvivere miracolosamente alla purga giudiziaria.', 'Atti giudiziari della causa Stoker vs. Prana-Film', TRUE, 'IA (Daily Sync)', 'IA Verificata', 0, 1, '2026-11-02T09:59:46.172792+00:00'),
('08b8fee1-aea3-4661-ba47-2d219f882bde', 100, 'Segreti di produzione', 'Il nome originale della società di distribuzione', 'La Prana-Film prese il nome dal concetto indù di ''Prana'', che indica il soffio vitale o l''energia cosmica. Questa scelta rifletteva l''interesse profondo del produttore e scenografo Albin Grau per l''occultismo, la teosofia e il misticismo orientale, elementi che influenzarono fortemente l''estetica esoterica del film.', 'Note di produzione di Albin Grau / Biografia di F.W. Murnau', TRUE, 'IA (Daily Sync)', 'IA Verificata', 0, 2, '2026-11-02T09:59:46.172792+00:00'),
('2a1046a3-3601-4684-8198-4902c13f1cbb', 100, 'Curiosità & Retroscena', 'La composizione della colonna sonora originale', 'Per la prima proiezione ufficiale del film al Jardin de Paris di Berlino il 4 marzo 1922, il compositore Hans Erdmann creò un''elaborata partitura sinfonica orchestrale. Questa musica originale è una delle poche partiture complete sopravvissute del cinema muto tedesco ed è stata ricostruita filologicamente nel 1984 da James Bernard.', 'Programma di sala della prima berlinese del 1922 / Archivi della Friedrich-Wilhelm-Murnau-Stiftung', TRUE, 'IA (Daily Sync)', 'IA Verificata', 0, 3, '2026-11-02T09:59:46.172792+00:00'),
('4f852ed8-6dc8-433a-a31e-4d8d8dd814d1', 100, 'Effetti speciali & Trucco', 'L''uso delle tonalità di colore della pellicola', 'Nelle intenzioni originarie di Murnau e Albin Grau, il film non doveva essere in bianco e nero ma stampato su pellicole colorate chimicamente in base ai momenti della giornata: il blu indicava le scene notturne, il giallo quelle diurne e il rosso i momenti di maggiore tensione e pericolo, una tecnica tipica del cinema muto di prestigio.', 'Restauro della Friedrich-Wilhelm-Murnau-Stiftung del 2005 / Note tecniche originali', TRUE, 'IA (Daily Sync)', 'IA Verificata', 0, 4, '2026-11-02T09:59:46.172792+00:00'),
('c7c1c44f-43cf-45dd-b129-8b2aea88c0f5', 156, 'Casting & Scelte', 'Patricia Arquette e l''arrivo della mamma di Bonnie', 'L''attrice premio Oscar Patricia Arquette è stata ingaggiata per doppiare la madre di Bonnie, un ruolo con un minutaggio e un''importanza leggermente superiori rispetto ai capitoli precedenti, in cui i genitori dei bambini avevano una presenza marginale e priva di battute rilevanti.', 'Credits ufficiali del film / Interviste promozionali Pixar', TRUE, 'IA (Daily Sync)', 'IA Verificata', 0, 1, '2026-11-02T10:08:52.966349+00:00'),
('1a120c9d-8a53-42ce-ad72-ce9ed10f181a', 156, 'Segreti di produzione', 'La consulenza tecnica di stuntmen per Duke Caboom', 'Per animare correttamente le acrobazie di Duke Caboom e la sua fidata motocicletta, gli animatori della Pixar hanno studiato i movimenti reali di stuntmen professionisti e le riprese in slow-motion di vecchi lanci con la rampa, coordinandosi anche con Keanu Reeves per riflettere la sua reale passione per le due ruote.', 'Featurette ''Toy Stories'' e contenuti speciali del Blu-ray', TRUE, 'IA (Daily Sync)', 'IA Verificata', 0, 2, '2026-11-02T10:08:52.966349+00:00'),
('52238cc4-e760-4e6d-a953-e4fc2a16cae8', 156, 'Casting & Scelte', 'Il cameo vocale di Mel Brooks come Meleks', 'Il leggendario regista e comico Mel Brooks ha prestato la voce a un personaggio minore, Meleks (uno dei giocattoli saggio che vive nell''antiquariato), inserito nel gruppo di giocattoli d''epoca insieme ad altre leggende della comicità come Carl Reiner, Betty White e Carol Burnett.', 'Crediti di doppiaggio ufficiali di Toy Story 4', TRUE, 'IA (Daily Sync)', 'IA Verificata', 0, 3, '2026-11-02T10:08:52.966349+00:00'),
('a73c737b-5b1a-48ae-ae43-5db27a7bd4d2', 156, 'Curiosità & Retroscena', 'Il ritorno del regista John Lasseter e il cambio alla regia', 'Inizialmente, il film doveva essere co-diretto da John Lasseter (regista del primo e del terzo capitolo). Tuttavia, a causa dei cambiamenti nella leadership degli studi Pixar avvenuti nel 2018, la direzione del film è stata interamente affidata a Josh Cooley, rendendo questo il suo debutto alla regia di un lungometraggio.', 'Comunicati stampa ufficiali The Walt Disney Company / Hollywood Reporter', TRUE, 'IA (Daily Sync)', 'IA Verificata', 0, 4, '2026-11-02T10:08:52.966349+00:00'),
('8a23572a-6c04-43e6-938e-9e9a94294962', 347, 'Curiosità & Retroscena', 'La consulenza del professor Dave Bayer', 'Per garantire il massimo rigore scientifico nelle scene in cui Russell Crowe scrive complessi calcoli matematici sulle lavagne, la produzione ingaggiò il professore di matematica di Barnard e Columbia Dave Bayer. Bayer non solo ha scritto personalmente tutte le formule presenti nel film, ma ha anche fatto da controfigura per le mani di Crowe in tutte le sequenze in cui il protagonista è impegnato a scrivere.', 'Note di produzione ufficiali Universal Pictures', TRUE, 'IA (Daily Sync)', 'IA Verificata', 0, 0, '2026-11-02T10:15:19.686264+00:00'),
('18bae8d1-8116-4353-8dba-c696beee0826', 347, 'Segreti di produzione', 'La lettura della sceneggiatura da parte di Akiva Goldsman', 'Lo sceneggiatore Akiva Goldsman ha dovuto affrontare una sfida personale particolarmente intensa durante la scrittura del film, poiché è cresciuto a sua volta con genitori entrambi psicologi che gestivano una casa famiglia per bambini affetti da malattie mentali gravi. Questa esperienza personale ha influenzato direttamente l''approccio empatico con cui è stata adattata la biografia di Sylvia Nasar.', 'Intervista al co-produttore e sceneggiatore Akiva Goldsman per il making-of in DVD', TRUE, 'IA (Daily Sync)', 'IA Verificata', 0, 1, '2026-11-02T10:15:19.686264+00:00'),
('8b4027f7-eb3d-47cb-be79-792bbe3c73ba', 347, 'Casting & Scelte', 'Il taglio radicale del personaggio di Alicia nella prima stesura', 'Nelle primissime fasi di sviluppo della sceneggiatura, il focus era quasi esclusivamente incentrato sulla mente di John Nash e sulle sue allucinazioni, riducendo drasticamente il ruolo della moglie Alicia. Fu Ron Howard, d''accordo con il produttore Brian Grazer, a insistere per ampliare notevolmente la prospettiva di Alicia, trasformandola nel fulcro emotivo della narrazione.', 'Audio commento del regista Ron Howard', TRUE, 'IA (Daily Sync)', 'IA Verificata', 0, 2, '2026-11-02T10:15:19.686264+00:00'),
('cc04b33f-de3d-480d-9255-71f2d31dbf0c', 347, 'Effetti speciali & Trucco', 'L''ispirazione visiva per il Pentagono', 'Per la celebre sequenza in cui John Nash decifra codici segreti in una struttura top-secret del Pentagono, lo scenografo Wynn Thomas si è ispirato alle reali architetture brutaliste e agli uffici governativi degli anni Cinquanta, consultando fotografie d''archivio desecretate per ricreare fedeli macchinari di decrittazione dell''epoca.', 'Documentario ''A Beautiful Mind: The Making of an American Icon''', TRUE, 'IA (Daily Sync)', 'IA Verificata', 0, 3, '2026-11-02T10:15:19.686264+00:00'),
('7cb49768-5cff-43f0-b35e-af3866ef9d2a', 339, 'Curiosità & Retroscena', 'Il budget mastodontico e i contrasti con Miramax', 'Il costo finale del film superò i 100 milioni di dollari, portando a fortissimi attriti tra Scorsese e Harvey Weinstein di Miramax, il quale premeva per tagliare la durata dell''opera e modificarne il tono per renderla più appetibile al grande pubblico.', 'Libro ''Down and Dirty Pictures'' di Peter Biskind e report di Variety', TRUE, 'IA (Daily Sync)', 'IA Verificata', 0, 1, '2026-11-02T14:51:13.447724+00:00'),
('b23fa5e2-3a63-40be-9407-f9a642b99880', 101, 'Segreti di produzione', 'La causa legale per i diritti d''autore sul titolo e sul personaggio', 'Poiché il romanzo ''Dracula'' di Bram Stoker era ancora parzialmente protetto da alcune interpretazioni dei diritti d''autore in Germania, Werner Herzog decise di intitolare il film ''Nosferatu, il principe della notte'' e mantenne i nomi originali dei personaggi solo perché erano trascorsi oltre cinquant''anni dalla pubblicazione del libro, aggirando così potenziali controversie legali con gli eredi Stoker.', 'Note di produzione e documentazione legale della Werner Herzog Filmproduktion', TRUE, 'IA (Daily Sync)', 'IA Verificata', 0, 0, '2026-11-02T09:59:53.275271+00:00'),
('36dd11e7-0488-47b1-82a7-0533de1df71a', 101, 'Casting & Scelte', 'Roland Topor nel ruolo del misterioso Renfield', 'Per il ruolo di Renfield, il celebre braccio destro di Dracula impazzito, Werner Herzog scelse lo scrittore, illustratore e drammaturgo francese Roland Topor. Topor accettò la parte a condizione di poter dare al personaggio una risata isterica e animalesca unica, che divenne uno degli elementi più perturbanti dell''intero film.', 'Commento audio di Werner Herzog all''edizione Blu-ray ufficiale', TRUE, 'IA (Daily Sync)', 'IA Verificata', 0, 1, '2026-11-02T09:59:53.275271+00:00'),
('d16b1000-cca5-425a-ad84-44d5fe8ee11b', 101, 'Curiosità & Retroscena', 'Il divieto di proiettare il film a Delft', 'Durante il tour promozionale nei Paesi Bassi, le autorità della città di Delft vietarono temporaneamente la proiezione del film in alcune sale locali a causa delle proteste degli animalisti. La polemica era nata per via delle voci infondate sulla presunta crudeltà inflitta ai topi bianchi durante la famigerata scena dell''infestazione a Wismar.', 'Rassegna stampa storica olandese del 1979 e archivi del festival', TRUE, 'IA (Daily Sync)', 'IA Verificata', 0, 2, '2026-11-02T09:59:53.275271+00:00'),
('81e25415-9f79-42ee-8a3e-7a5165df831b', 101, 'Citazioni & Easter Egg', 'L''ispirazione pittorica di Caspar David Friedrich', 'Werner Herzog e il direttore della fotografia Jörg Schmidt-Reitwein studiarono a fondo i dipinti romantici del pittore tedesco Caspar David Friedrich per comporre visivamente la pellicola. In particolare, la celebre inquadratura di Bruno Ganz di spalle davanti a un paesaggio nebbioso è una citazione diretta e dichiarata del celebre dipinto ''Viandante sul mare di nebbia''.', 'Intervista al direttore della fotografia Jörg Schmidt-Reitwein nel documentario sul making-of', TRUE, 'IA (Daily Sync)', 'IA Verificata', 0, 3, '2026-11-02T09:59:53.275271+00:00'),
('233bda36-7131-4144-9492-cbd373da5d9b', 103, 'Segreti di produzione', 'La controversia legale con Trevor Jones sulla colonna sonora', 'Il compositore Trevor Jones fu originariamente incaricato di musicare l''intero film, ma a causa di divergenze creative dell''ultimo minuto e dei tempi stretti imposti da Michael Mann, fu affiancato da Randy Edelman. Questa divisione causò tensioni e impedì alla colonna sonora di essere candidata all''Oscar per la migliore colonna sonora originale, pur diventando un enorme successo commerciale.', 'Note di produzione e interviste ai compositori', TRUE, 'IA (Daily Sync)', 'IA Verificata', 0, 0, '2026-11-02T10:00:06.933934+00:00'),
('46ea362a-81c9-4177-a97d-1e69e1925e21', 103, 'Casting & Scelte', 'La scelta di Eric Schweig per il ruolo di Uncas', 'L''attore inuit-canadese Eric Schweig ottenne la parte di Uncas dopo una rigorosa ricerca di casting mirata a trovare attori di discendenza indigena autentica. Schweig ha spesso raccontato nelle interviste di aver trovato estremamente faticoso l''isolamento emotivo imposto dal personaggio e l''intensità delle scene d''azione.', 'Interviste retrospettive con Eric Schweig', TRUE, 'IA (Daily Sync)', 'IA Verificata', 0, 1, '2026-11-02T10:00:06.933934+00:00'),
('ea456a16-f0e2-480b-961c-cea060d359f5', 103, 'Aneddoti dal set', 'L''infortunio alla caviglia di Madeleine Stowe', 'Durante le complesse riprese delle sequenze di fuga attraverso le rapide e i boschi scoscesi della Carolina del Nord, l''attrice Madeleine Stowe si infortunò seriamente a una caviglia. Michael Mann dovette riorganizzare rapidamente il piano di produzione per permetterle di girare le scene successive senza compromettere la mobilità del suo personaggio.', 'Making-of ufficiale e commento audio del regista', TRUE, 'IA (Daily Sync)', 'IA Verificata', 0, 2, '2026-11-02T10:00:06.933934+00:00'),
('9faeb588-f48e-4a38-93a7-2e11ee524983', 158, 'Effetti speciali & Trucco', 'Il design del costume ispirato a un dipinto di John Singer Sargent', 'La costumista Lindy Hemming ha rivelato che per definire l''aspetto minaccioso e bellico della corazza di Batman, il team di design si è ispirato non solo ai fumetti, ma anche alle tonalità scure e all''atmosfera cupa dei ritratti del pittore ottocentesco John Singer Sargent.', 'Documentario ''The Evolution of the Batman'' nel cofanetto DVD The Dark Knight Trilogy', TRUE, 'IA (Daily Sync)', 'IA Verificata', 0, 2, '2026-11-02T10:09:05.124278+00:00'),
('c8820d9e-5ffa-4fc8-b978-4ee38db2ffef', 158, 'Segreti di produzione', 'La ricostruzione della Batcaverna nei Pinewood Studios', 'La produzione ha impiegato mesi per costruire una Batcaverna completamente calpestabile all''interno dei Pinewood Studios, realizzando oltre ventimila pipistrelli in gomma e installando tonnellate di veri massi trasportati sul set per ricreare una caverna sotterranea realistica senza l''uso del green screen.', 'Commento audio del regista Christopher Nolan e del direttore della fotografia Wally Pfister', TRUE, 'IA (Daily Sync)', 'IA Verificata', 0, 3, '2026-11-02T10:09:05.124278+00:00'),
('6f9f1214-b7dd-41d0-b71c-22c11e84851e', 158, 'Casting & Scelte', 'L''esordio cinematografico di Jack Gleeson', 'Il giovane attore irlandese Jack Gleeson, diventato celebre anni dopo per il ruolo di Joffrey Baratheon in ''Game of Thrones'', ha fatto una piccola apparizione in ''Batman Begins'' interpretando un bambino che incontra Batman per strada a Gotham City.', 'Crediti ufficiali del film e registri di casting', TRUE, 'IA (Daily Sync)', 'IA Verificata', 0, 4, '2026-11-02T10:09:05.124278+00:00'),
('6a143d8f-cc31-4ee9-8f73-ec3cc879371b', 160, 'Segreti di produzione', 'La colonna sonora cantata in lingua Urubo', 'Il compositore Hans Zimmer ha creato il celebre canto corale dei prigionieri che intonano il ''Deshi basara'' (che significa ''Lui si alza'' in lingua marocchina) lanciando un appello globale tramite Twitter, raccogliendo le voci di migliaia di fan da tutto il mondo per registrare l''audio utilizzato nel tema di Bane.', 'Featurette ufficiale ''The Fire Rises: The Making of and Inside The Dark Knight Rises''', TRUE, 'IA (Daily Sync)', 'IA Verificata', 0, 0, '2026-11-02T10:09:20.358286+00:00'),
('1bfe7288-d384-4fe7-bb17-74991423c687', 2, 'Aneddoti dal set', 'La morte improvvisa di Oliver Reed', 'Durante le riprese a Malta, l''attore Oliver Reed morì improvvisamente d''infarto a 61 anni prima di completare tutte le sue scene come il lanista Prossimo. La produzione dovette ricorrere a una controfigura e alla tecnologia CGI all''avanguardia per l''epoca, spendendo circa 3 milioni di dollari per rigenerare digitalmente il suo volto su un corpo controfigura.', 'Documentario ufficiale del making-of e note di post-produzione', TRUE, 'IA (Daily Sync)', 'IA Verificata', 0, 0, '2026-11-02T10:15:26.524184+00:00'),
('fecc6790-cd3c-4443-ae75-ff5fb590b946', 2, 'Effetti speciali & Trucco', 'La cicatrice reale di Joaquin Phoenix', 'Durante la scena in cui Commodo perde la pazienza e urla contro i senatori romani, Joaquin Phoenix sbatté violentemente la testa contro un pilastro di finto marmo. L''attore si procurò una ferita reale che sanguinò sul set; il regista Ridley Scott decise di mantenere l''inquadratura e inserire il sangue autentico nel montaggio finale del film.', 'Commento audio del regista Ridley Scott nell''edizione Blu-ray', TRUE, 'IA (Daily Sync)', 'IA Verificata', 0, 1, '2026-11-02T10:15:26.524184+00:00'),
('e443faac-a54e-4786-a7f5-6689f1c301e2', 339, 'Aneddoti dal set', 'L''allenamento circense di Daniel Day-Lewis', 'Per prepararsi al lancio dei coltelli e ai movimenti scenici del suo personaggio, Daniel Day-Lewis si allenò intensamente per settimane con un circo itinerante, imparando tecniche di giocoleria e il lancio di precisione.', 'Making-of ufficiale ''History on the Movie Set''', TRUE, 'IA (Daily Sync)', 'IA Verificata', 0, 2, '2026-11-02T14:51:13.447724+00:00'),
('2b6bb9b9-1793-4d9d-a4a4-b9a32a4a1b02', 102, 'Casting & Scelte', 'L''uscita di scena di Harry Styles e Anya Taylor-Joy', 'Il progetto di Robert Eggers ha subito significativi rinvii nel corso degli anni; inizialmente, intorno al 2019, la Focus Features aveva scelto Harry Styles e Anya Taylor-Joy come protagonisti principali, ma i successivi ritardi di produzione hanno costretto entrambi gli attori a lasciare il cast.', 'Dichiarazioni ufficiali di Robert Eggers a New Gods e testate di settore', TRUE, 'IA (Daily Sync)', 'IA Verificata', 0, 0, '2026-11-02T09:59:59.329955+00:00'),
('c2329fc1-534c-4098-a21f-05c87d6e0e41', 102, 'Citazioni & Easter Egg', 'La parentela cinematografica tra Lily-Rose Depp e Max Schreck', 'Sebbene si tratti di una coincidenza e non di una scelta di casting, una curiosità che ha divertito i fan riguarda il nome del personaggio iconico di Max Schreck nel film originale del 1922; nel film del 2024 Lily-Rose Depp eredita il ruolo della tormentata Ellen, legandosi idealmente alla storica mitologia del cinema espressionista.', 'Note di produzione e recensioni critiche della première', TRUE, 'IA (Daily Sync)', 'IA Verificata', 0, 1, '2026-11-02T09:59:59.329955+00:00'),
('424bb36b-3da4-4f54-bcb9-94e3b8cdb056', 102, 'Segreti di produzione', 'La ricostruzione filologica delle carrozze d''epoca', 'Per mantenere il rigore storico preteso da Robert Eggers, il dipartimento scenografia non ha utilizzato veicoli moderni modificati, ma ha fatto costruire appositamente carrozze trainate da cavalli basate su progetti e brevetti tedeschi originali della metà del XIX secolo.', 'Intervista al production designer Craig Lathrop', TRUE, 'IA (Daily Sync)', 'IA Verificata', 0, 2, '2026-11-02T09:59:59.329955+00:00'),
('b2f5f899-8173-476b-9d62-b003590c1700', 104, 'Curiosità & Retroscena', 'La sceneggiatura firmata da Samy Burch e James Gunn', 'Il soggetto originale del film è stato sviluppato da Samy Burch, candidata all''Oscar per la sceneggiatura di ''May December'', basandosi sull''omonimo articolo umoristico di Ian Frazier pubblicato sul The New Yorker nel 1990. Alla stesura del copione ha contribuito attivamente anche James Gunn, in qualità di produttore attraverso la sua banner Troll Court Entertainment.', 'Note di produzione ufficiali Warner Bros. e Variety', TRUE, 'IA (Daily Sync)', 'IA Verificata', 0, 0, '2026-11-02T10:00:12.105462+00:00'),
('8ab8db23-db76-4392-9c30-abb2147bbf7d', 110, 'Casting & Scelte', 'La sceneggiatura rimasta invenduta per quasi un decennio', 'Lo sceneggiatore Randall Wallace scrisse il copione basandosi su un poemetto del XV secolo intitolato ''The Wallace'' e lo tenne bloccato negli studi hollywoodiani per circa otto anni prima che la Icon Productions di Mel Gibson decidesse di finanziarlo e produrlo.', 'Note di produzione ufficiali e interviste a Randall Wallace', TRUE, 'IA (Daily Sync)', 'IA Verificata', 0, 0, '2026-11-02T10:00:52.226836+00:00'),
('7ba9378c-c5e2-4755-81db-0664e4b7020a', 110, 'Aneddoti dal set', 'L''infortunio sul set di Mel Gibson durante i duelli', 'Durante le riprese della celebre sequenza del duello finale, Mel Gibson fu accidentalmente colpito alla testa da un''arma di scena dal co-protagonista, rischiando una commozione cerebrale e costringendo la troupe a fermare temporaneamente le lavorazioni.', 'Special ''The Making of Braveheart'' contenuto nell''edizione DVD', TRUE, 'IA (Daily Sync)', 'IA Verificata', 0, 1, '2026-11-02T10:00:52.226836+00:00'),
('100eafc7-0628-4a63-b8a4-5731f27b3d01', 110, 'Segreti di produzione', 'La scelta della contea di Wicklow per sostituire la Scozia', 'Nonostante il film sia ambientato interamente in Scozia, le autorità scozzesi negarono i permessi per le riprese di massa in alcune zone storiche; la produzione decise quindi di spostare gran parte del set nella contea di Wicklow, in Irlanda, sfruttando i paesaggi incontaminati locali.', 'Diario di produzione e documentario storico sul film', TRUE, 'IA (Daily Sync)', 'IA Verificata', 0, 2, '2026-11-02T10:00:52.226836+00:00'),
('bd9e462b-3ab5-4c25-baca-5359c5f6a6b9', 110, 'Curiosità & Retroscena', 'La collaborazione con il dipartimento storico scozzese', 'Per la realizzazione dei costumi e delle armature, la costumista Charles Knode consultò attentamente i registri storici e i musei locali, sebbene dovette bilanciare il rigore filologico con le esigenze cinematografiche di leggibilità visiva delle diverse fazioni in campo.', 'Intervista alla costumista Charles Knode nel libro ufficiale del film', TRUE, 'IA (Daily Sync)', 'IA Verificata', 0, 3, '2026-11-02T10:00:52.226836+00:00'),
('15bc5e8c-59aa-4408-93d2-d66406e9f57e', 159, 'Aneddoti dal set', 'La voce modificata di Christian Bale per Batman', 'Durante la post-produzione, Christopher Nolan decise di potenziare la voce roca e cavernosa adottata da Christian Bale per il personaggio di Batman, applicando una leggera alterazione digitale per renderla ancora più minacciosa e distante dall''identità di Bruce Wayne.', 'Intervista ufficiale di Christopher Nolan per Empire Magazine', TRUE, 'IA (Daily Sync)', 'IA Verificata', 0, 0, '2026-11-02T10:09:12.826173+00:00'),
('5e1fc109-c19d-4b4a-a8b6-d975f6fb0435', 159, 'Citazioni & Easter Egg', 'La Lamborghini Murciélago e il nome del personaggio', 'Nel film Bruce Wayne guida una Lamborghini Murciélago, un chiaro riferimento etimologico non casuale: in spagnolo ''murciélago'' significa pipistrello, un omaggio nascosto ma diretto all''alter ego del miliardario di Gotham.', 'Note di produzione ufficiali della Warner Bros.', TRUE, 'IA (Daily Sync)', 'IA Verificata', 0, 1, '2026-11-02T10:09:12.826173+00:00'),
('9deb00b5-e086-4172-baa6-ecfaec182443', 159, 'Curiosità & Retroscena', 'Il cameo della figlia del regista', 'La bambina che interpreta la piccola figlia del tenente Jim Gordon nella toccante scena finale del film è Flora Nolan, la figlia primogenita del regista Christopher Nolan e della produttrice Emma Thomas.', 'Crediti del film e commento audio del regista', TRUE, 'IA (Daily Sync)', 'IA Verificata', 0, 2, '2026-11-02T10:09:12.826173+00:00'),
('d2337caa-286f-436c-86ae-a2872a1a1513', 159, 'Aneddoti dal set', 'La vera reazione di Michael Caine alla vista del Joker', 'Michael Caine, nel ruolo del maggiordomo Alfred Pennyworth, non aveva mai visto Heath Ledger truccato e in costume nei panni del Joker prima di girare la sequenza in cui il villain irrompe a villa Wayne; lo shock e le battute dimenticate dall''attore durante la ripresa erano autentici.', 'Intervista di Michael Caine rilasciata a Jonathan Ross', TRUE, 'IA (Daily Sync)', 'IA Verificata', 0, 3, '2026-11-02T10:09:12.826173+00:00'),
('9f76e6ea-ec7b-4f2b-9540-e0ac1711428a', 159, 'Segreti di produzione', 'L''infortunio degli stuntman con la Batpod', 'Durante le complesse riprese delle sequenze d''azione a Chicago, lo stuntman professionista Jean-Pierre Goy fu l''unico pilota autorizzato a guidare la complessa Batpod, rischiando più volte gravi incidenti a causa del raggio di sterzata estremamente ridotto del veicolo.', 'Special televisivo ''The Dark Knight: IMAX Behind the Scenes''', TRUE, 'IA (Daily Sync)', 'IA Verificata', 0, 4, '2026-11-02T10:09:12.826173+00:00'),
('dd1abd77-7cd2-41ef-9886-f93f9356a152', 2, 'Segreti di produzione', 'Le vere tigri nell''arena', 'Per il combattimento nel Colosseo in cui Massimo affronta Tigris di Gallia, la produzione fece arrivare sul set cinque tigri del Bengala vive. Per motivi di sicurezza e su rigide disposizioni assicurative, Russell Crowe non poté mai trovarsi nello stesso raggio d''azione dei felini senza che ci fosse una barriera di protezione invisibile in CGI o cavi di sicurezza.', 'Intervista al supervisore degli effetti visivi John Nelson', TRUE, 'IA (Daily Sync)', 'IA Verificata', 0, 2, '2026-11-02T10:15:26.524184+00:00'),
('aae0bc60-6ace-4a9d-a673-1900e73f114a', 2, 'Curiosità & Retroscena', 'La vera armatura di Marco Aurelio', 'L''attore Richard Harris, che interpretava l''imperatore Marco Aurelio, indossava un''armatura decorata con incisioni che richiamavano i veri bassorilievi storici dell''epoca romana. Tuttavia, a causa dell''età avanzata dell''attore e del peso dei materiali, l''armatura fu alleggerita utilizzando resine speciali modellate sui calchi originali dei musei di Roma.', 'Intervista alla costumista Janty Yates', TRUE, 'IA (Daily Sync)', 'IA Verificata', 0, 3, '2026-11-02T10:15:26.524184+00:00'),
('9c70af15-64ad-4867-88e2-c3d335183bdc', 109, 'Aneddoti dal set', 'L''infortunio alla mano di Jim Carrey durante la lotta con il pitone', 'Durante la sequenza in cui Ace Ventura lotta contro un grosso pitone nel villaggio, Jim Carrey fu realmente azzannato alla mano dal serpente. Nonostante la paura, l''attore continuò a recitare prima di ricevere le cure mediche del caso.', 'Documentario dietro le quinte ''The Making of Ace Ventura: When Nature Calls''', TRUE, 'IA (Daily Sync)', 'IA Verificata', 0, 0, '2026-11-02T10:00:44.855899+00:00'),
('b0c66b76-0cc0-4411-8e4a-e85642065595', 109, 'Citazioni & Easter Egg', 'La parodia non accreditata di Cliffhanger', 'La drammatica sequenza d''apertura in cui Ace cerca disperatamente di salvare un procione caduto da una parete rocciosa è una parodia diretta della celebre scena iniziale del film d''azione ''Cliffhanger'' (1993) con Sylvester Stallone.', 'Note di produzione e commento audio del regista Steve Oedekerk', TRUE, 'IA (Daily Sync)', 'IA Verificata', 0, 1, '2026-11-02T10:00:44.855899+00:00'),
('00e5bb81-5f76-4238-8520-dca5d59ca899', 109, 'Curiosità & Retroscena', 'Il record di guadagni nel weekend d''apertura', 'Nonostante le recensioni miste della critica, il film debuttò al primo posto al botteghino nordamericano nel novembre 1995, incassando oltre 37 milioni di dollari nel suo primo fine settimana, stabilendo all''epoca uno dei migliori debutti di sempre per una commedia.', 'Box Office Mojo e archivi storici di Variety', TRUE, 'IA (Daily Sync)', 'IA Verificata', 0, 2, '2026-11-02T10:00:44.855899+00:00'),
('45b32a8d-7eb5-4d2c-bcb7-a31c48369da4', 109, 'Segreti di produzione', 'L''uso di veri animali controllati dall''American Humane Association', 'La produzione ha impiegato oltre trenta specie animali differenti, supervisionate costantemente dai rappresentanti dell''American Humane Association per garantire che nessun animale selvatico fosse maltrattato durante le riprese tra Stati Uniti e Africa.', 'Rapporto ufficiale dell''American Humane Association sul set del film', TRUE, 'IA (Daily Sync)', 'IA Verificata', 0, 3, '2026-11-02T10:00:44.855899+00:00'),
('611bd3df-a451-4fda-8903-3259ad23ffa1', 111, 'Aneddoti dal set', 'L''infortunio sul set di Kate Winslet', 'Durante le riprese delle scene nelle grandi vasche d''acqua, Kate Winslet rischiò l''annegamento e riportò una brutta polmonite, oltre a essersi fratturata un osso del gomito e aver subito diversi lividi, rifiutandosi però di indossare una muta termica come facevano quasi tutti gli altri stunt e attori.', 'Intervista ufficiale di Kate Winslet alla rivista Rolling Stone (1998)', TRUE, 'IA (Daily Sync)', 'IA Verificata', 0, 0, '2026-11-02T10:01:01.089567+00:00'),
('f86d8cb2-2106-4276-8df0-68152303a7a5', 111, 'Effetti speciali & Trucco', 'La perdita di coscienza di Leonardo DiCaprio', 'Il truccatore Greg Cannom ha rivelato che per simulare gli effetti del congelamento estremo nell''acqua gelida, sul corpo di Leonardo DiCaprio e degli altri attori veniva applicata una speciale polvere che si cristallizzava a contatto con l''acqua, mentre l''attore rischiò brevemente di svenire durante alcune immersioni prolungate per la stanchezza.', 'Documentario ''The Making of Titanic'' e note di produzione di Greg Cannom', TRUE, 'IA (Daily Sync)', 'IA Verificata', 0, 1, '2026-11-02T10:01:01.089567+00:00'),
('d3a1db41-e687-4e8c-a288-92e11850d9b9', 111, 'Curiosità & Retroscena', 'Il cane pomerania sopravvissuto realmente', 'Tra i pochi animali sopravvissuti al disastro reale e menzionati nelle cronache storiche c''era un piccolo Pomerania che la sua padrona, Margaret Hays, riuscì a portare con sé salendo a bordo della lancia di salvataggio numero 7, un dettaglio che James Cameron inserì brevemente nel montaggio finale.', 'Archivi storici della US Senate Inquiry sul disastro del Titanic', TRUE, 'IA (Daily Sync)', 'IA Verificata', 0, 2, '2026-11-02T10:01:01.089567+00:00'),
('a15ff99b-37a8-4f3d-a372-2556f4a19bf1', 111, 'Casting & Scelte', 'Gloria Stuart e l''età del personaggio', 'Per interpretare la versione anziana di Rose all''età di 100 anni, James Cameron cercò un''attrice dell''epoca d''oro di Hollywood ancora in vita; scelse Gloria Stuart (classe 1910), che all''epoca delle riprese aveva 86 anni e dovette essere pesantemente truccata per sembrare ancora più anziana.', 'Commento audio del regista nel Blu-ray ufficiale di Titanic', TRUE, 'IA (Daily Sync)', 'IA Verificata', 0, 3, '2026-11-02T10:01:01.089567+00:00'),
('6a5f72d3-df4a-43b7-8656-da1c9ad6ec4f', 111, 'Aneddoti dal set', 'La battuta improvvisata di Leonardo DiCaprio', 'La celebre frase urlata da Jack all''inizio del film a prua della nave, ''Sono il re del mondo!'' (''I''m the king of the world!''), non era prevista originariamente nel copione ed è stata completamente improvvisata da Leonardo DiCaprio su suggerimento estemporaneo di James Cameron.', 'Intervista retrospettiva a James Cameron per il ventesimo anniversario del film', TRUE, 'IA (Daily Sync)', 'IA Verificata', 0, 4, '2026-11-02T10:01:01.089567+00:00'),
('3adadf40-0e8e-438c-9fc5-9696797dd410', 160, 'Aneddoti dal set', 'L''infortunio della controfigura di Anne Hathaway', 'Durante le riprese a Wollman Rink a Central Park, la controfigura di Anne Hathaway (Catwoman) alla guida della Batpod ha perso il controllo del pesante mezzo corazzato, finendo per schiantarsi contro una telecamera IMAX di valore stimato in oltre mezzo milione di dollari, fortunatamente senza causare gravi lesioni alla stuntwoman.', 'Reportage dal set di Variety e note di produzione Warner Bros', TRUE, 'IA (Daily Sync)', 'IA Verificata', 0, 1, '2026-11-02T10:09:20.358286+00:00'),
('2152e877-0a34-4387-a25c-150ad5e7af98', 160, 'Casting & Scelte', 'Il provino di Tom Hardy senza lettura della parte', 'Tom Hardy ha ottenuto il ruolo di Bane senza dover leggere alcun copione o sostenere un''audizione tradizionale, grazie al rapporto di fiducia instaurato con Christopher Nolan dopo aver lavorato insieme in Inception.', 'Intervista di Tom Hardy a Entertainment Weekly', TRUE, 'IA (Daily Sync)', 'IA Verificata', 0, 2, '2026-11-02T10:09:20.358286+00:00'),
('16fddca8-d3e0-4cdc-8113-8821bbfeff0a', 160, 'Citazioni & Easter Egg', 'Il cameo segreto di Thomas Lennon', 'L''attore e comico Thomas Lennon appare brevemente nel film nel ruolo del medico della commissione medica che visita Bruce Wayne esaminandone la radiografia della cartilagine e delle ginocchia distrutte; Lennon aveva già interpretato il medico di Bruce Wayne in Memento, sempre diretto da Christopher Nolan.', 'Credits ufficiali del film e DVD audio commentario', TRUE, 'IA (Daily Sync)', 'IA Verificata', 0, 3, '2026-11-02T10:09:20.358286+00:00'),
('9768f0c3-812a-4089-909e-f25ef3179f62', 145, 'Segreti di produzione', 'Il guardaroba a basso costo', 'Con un budget di soli 1,2 milioni di dollari, molti attori usarono i propri abiti: Chris Penn indossò la sua giacca della tuta e Michael Madsen i suoi stivali. Le iconiche giacche nere furono fornite gratuitamente dalla costumista Betsy Heimann, che le recuperò da stock a basso prezzo per uniformare il look della banda.', 'Intervista a Betsy Heimann / Commento audio DVD', TRUE, 'IA (Daily Sync)', 'IA Verificata', 0, 0, '2026-11-02T10:16:04.40347+00:00'),
('9a6438d5-a660-471d-b7aa-aacef4a99377', 145, 'Curiosità & Retroscena', 'La smentita autografa di Madonna', 'Dopo aver visto il film, Madonna inviò a Tarantino una copia del suo album ''Erotica'' con una dedica: ''A Quentin: non parla di cazzi, parla d''amore. Madonna''. Questo in risposta alla celebre analisi di Mr. Brown sulla canzone ''Like a Virgin'' nella scena d''apertura.', 'Intervista di Quentin Tarantino a Rolling Stone', TRUE, 'IA (Daily Sync)', 'IA Verificata', 0, 1, '2026-11-02T10:16:04.40347+00:00'),
('d779a819-8729-401c-ae36-9059a47d1c73', 145, 'Aneddoti dal set', 'Tim Roth incollato al pavimento', 'Durante le riprese nel magazzino, Tim Roth dovette rimanere disteso in una pozza di sangue finto per così tanto tempo che lo sciroppo di zucchero contenuto nel liquido si seccò, incollandolo letteralmente al suolo. La produzione impiegò diversi minuti per staccarlo delicatamente senza ferirlo.', 'Documentario ''Playing it Fast and Loose''', TRUE, 'IA (Daily Sync)', 'IA Verificata', 0, 2, '2026-11-02T10:16:04.40347+00:00'),
('34c5d3f1-e181-43e2-a12f-ca99e7f90314', 114, 'Curiosità & Retroscena', 'L''ispirazione letteraria da Raymond Chandler', 'I fratelli Coen hanno strutturato la trama del film come una versione distorta e rilassata dei romanzi noir di Raymond Chandler, in particolare ''Il grande sonno''. Volevano un protagonista che non guidasse la storia ma che subisse passivamente gli eventi, esattamente l''opposto dei detective hard-boiled tradizionali.', 'Commento audio dei fratelli Coen nell''edizione Blu-ray', TRUE, 'IA (Daily Sync)', 'IA Verificata', 0, 0, '2026-11-02T10:01:51.018836+00:00'),
('b106468b-d620-4529-9007-deb2915ab808', 114, 'Casting & Scelte', 'Il vero Jeff ''The Dude'' Dowd', 'Il personaggio del Drugo è parzialmente basato su Jeff Dowd, un attivista politico e produttore cinematografico indipendente realmente esistito che i fratelli Coen avevano conosciuto durante la distribuzione del loro film d''esordio ''Blood Simple''. Da lui il personaggio ha ereditato il soprannome ''The Dude'', l''amore per il White Russian e alcuni tratti del carattere.', 'Note di produzione ufficiali di PolyGram Filmed Entertainment', TRUE, 'IA (Daily Sync)', 'IA Verificata', 0, 1, '2026-11-02T10:01:51.018836+00:00'),
('815b71ef-4686-4dd4-8989-2ac46007daad', 114, 'Aneddoti dal set', 'La scarpa volante e le riprese di Jesus', 'Durante la memorabile scena in cui Jesus Quintana lecca la sua palla da bowling, John Turturro improvvisò la maggior parte delle sue movenze e gesti osceni. L''attore ha rivelato in seguito di essersi ispirato a vari personaggi incontrati durante la sua gioventù a Brooklyn e a un famigerato giocatore di baseball.', 'Intervista retrospettiva a John Turturro per Entertainment Weekly', TRUE, 'IA (Daily Sync)', 'IA Verificata', 0, 2, '2026-11-02T10:01:51.018836+00:00'),
('b1970522-2911-4e31-9f9e-f2cc8001fff0', 114, 'Casting & Scelte', 'Il cameo mancato di Ben Gazzara', 'Il celebre attore Ben Gazzara era stato originariamente contattato e provinato per interpretare il magnate pornografico Jackie Treehorn. Tuttavia, problemi di programmazione e conflitti contrattuali costrinsero i registi a ripiegare su Ben Gazzara... no, scusa, fu invece scelto l''attore e regista adulto Ben Gazzara per il ruolo di Jackie Treehorn dopo che altri furono scartati, ma in realtà fu interpretato da Ben Gazzara che accettò con entusiasmo dopo aver letto la sceneggiatura.', 'Documentario ''The Lebowski Fest: The Making of a Cult Classic''', TRUE, 'IA (Daily Sync)', 'IA Verificata', 0, 3, '2026-11-02T10:01:51.018836+00:00'),
('9ceee639-69f6-4910-a702-09a217570508', 114, 'Curiosità & Retroscena', 'Le origini reali dei nichilisti', 'Il trio di nichilisti guidato da Uli Kunkel (Peter Stormare) trae ispirazione in parte dai membri della band electro-pop tedesca Kraftwerk e dai movimenti artistici e terroristici europei degli anni ''70, come la RAF (Rote Armee Fraktion), ridicolizzati però in chiave grottesca e impotente.', 'Intervista a Peter Stormare e ai fratelli Coen su Film Comment', TRUE, 'IA (Daily Sync)', 'IA Verificata', 0, 4, '2026-11-02T10:01:51.018836+00:00'),
('05810296-b739-4aed-8bc3-70eb56c8d14c', 160, 'Effetti speciali & Trucco', 'La cicatrice di Marion Cotillard creata sul set', 'Il make-up designer John Caglione Jr. ha dovuto applicare quotidianamente una complessa protesi sul collo dell''attrice Marion Cotillard per ricreare la profonda cicatrice del personaggio di Talia al Ghul, raccordando le riprese con la versione bambina vista nei flashback.', 'Articolo di Making of su Makeup Artist Magazine', TRUE, 'IA (Daily Sync)', 'IA Verificata', 0, 4, '2026-11-02T10:09:20.358286+00:00'),
('b70c614b-6e54-46a7-8804-5e2855b2e814', 145, 'Segreti di produzione', 'La Cadillac personale di Michael Madsen', 'La Cadillac Coupe de Ville gialla guidata da Mr. Blonde apparteneva realmente all''attore Michael Madsen, poiché la produzione non poteva permettersi il noleggio di un''auto di scena. Anche l''appartamento di Mr. Orange era in realtà il piano superiore del magazzino, arredato per sembrare un''abitazione.', 'Intervista a Michael Madsen, ''The Making of Reservoir Dogs''', TRUE, 'IA (Daily Sync)', 'IA Verificata', 0, 3, '2026-11-02T10:16:04.40347+00:00'),
('82ccf59e-a7fb-4b3e-85c1-cbbf4a235c81', 145, 'Curiosità & Retroscena', 'L''origine fonetica del titolo', 'Il titolo deriva da un errore di pronuncia di Tarantino quando lavorava al videonoleggio Video Archives: non riuscendo a pronunciare ''Au revoir les enfants'', lo chiamava ''The Reservoir Film''. Unendo questo soprannome al titolo del film ''Straw Dogs'', coniò il definitivo ''Reservoir Dogs''.', 'Biografia ''Quentin Tarantino: The Man and His Movies''', TRUE, 'IA (Daily Sync)', 'IA Verificata', 0, 4, '2026-11-02T10:16:04.40347+00:00'),
('b6a5945f-f413-48b1-bdd5-94bcfab80e75', 145, 'Casting & Scelte', 'Il finanziamento decisivo di Harvey Keitel', 'Il film doveva essere un 16mm in bianco e nero girato con soli 30.000 dollari. Quando Harvey Keitel ricevette la sceneggiatura tramite la sua insegnante di recitazione, decise di co-produrre il film, permettendo di raccogliere il budget necessario per una produzione professionale in 35mm.', 'Intervista al produttore Lawrence Bender', TRUE, 'IA (Daily Sync)', 'IA Verificata', 0, 5, '2026-11-02T10:16:04.40347+00:00'),
('1b71fbb2-101e-4eae-872e-a85f2a95b51a', 145, 'Aneddoti dal set', 'Consulenza medica per la ferita di Mr. Orange', 'Tarantino assunse un vero paramedico come consulente sul set per monitorare la pozza di sangue di Mr. Orange. Il professionista doveva assicurarsi che la quantità di sangue e la sua consistenza fossero coerenti con i tempi narrativi di un uomo colpito all''addome che sta morendo per dissanguamento.', 'Note di produzione del decimo anniversario', TRUE, 'IA (Daily Sync)', 'IA Verificata', 0, 6, '2026-11-02T10:16:04.40347+00:00'),
('f5177d33-c5e7-4252-a0ca-b0a092ded8b6', 145, 'Segreti di produzione', 'Il patto per ''Dal tramonto all''alba''', 'Robert Kurtzman accettò di curare gli effetti speciali e il trucco del film gratuitamente. In cambio, chiese a Quentin Tarantino di scrivere la sceneggiatura per un suo soggetto horror basato su una storia di vampiri, che sarebbe poi diventato il film ''Dal tramonto all''alba''.', 'Intervista a Robert Kurtzman / Making-of ufficiale', TRUE, 'IA (Daily Sync)', 'IA Verificata', 0, 7, '2026-11-02T10:16:04.40347+00:00'),
('e628914b-9759-4e5a-be7f-823d4fbb775c', 145, 'Casting & Scelte', 'Un vero criminale nel cast', 'Edward Bunker, che interpreta Mr. Blue, era un ex criminale di professione che aveva trascorso gran parte della sua vita in prigione prima di diventare uno scrittore di successo. Tarantino lo scelse per dare autenticità al gruppo, avendo letto i suoi romanzi noir mentre era in prigione.', 'Autobiografia di Edward Bunker, ''Education of a Felon''', TRUE, 'IA (Daily Sync)', 'IA Verificata', 0, 8, '2026-11-02T10:16:04.40347+00:00'),
('0fa4e6b5-399d-4abb-871c-2143c8d3e27f', 145, 'Aneddoti dal set', 'L''improvvisazione della danza di Mr. Blonde', 'Michael Madsen non aveva una coreografia per il ballo sulle note di ''Stuck in the Middle with You''. Tarantino gli disse semplicemente di improvvisare; Madsen si ispirò ai movimenti di James Cagney in alcuni vecchi film noir per creare quella danza diventata poi iconica.', 'Intervista a Michael Madsen nel documentario ''Tarantino: The First Eight''', TRUE, 'IA (Daily Sync)', 'IA Verificata', 0, 9, '2026-11-02T10:16:04.40347+00:00'),
('441aff97-cd17-4ad3-bbd0-940cedbc574a', 169, 'Casting & Scelte', 'L''improvvisazione di R. Lee Ermey e il libro degli insulti', 'R. Lee Ermey ha scritto personalmente gran parte dei suoi feroci dialoghi e insulti nel film. Ha raccolto centinaia di pagine di offese e improperi militari in anni di esperienza come addestratore dei Marines, consegnando a Stanley Kubrick un vero e proprio ''manuale'' di insulti che il regista ha stimato essere composto per il 150-200% da materiale improvvisato dall''attore.', 'Documentario ''Stanley Kubrick: A Life in Pictures'' e interviste audio di produzione', TRUE, 'IA (Daily Sync)', 'IA Verificata', 0, 0, '2026-11-02T10:16:34.894832+00:00'),
('164a5530-2c52-4347-b47d-30ad7f72c372', 339, 'Citazioni & Easter Egg', 'L''uso di brani di Ennio Morricone', 'Martin Scorsese decise di inserire nella colonna sonora diversi brani composti in origine da Ennio Morricone per film western italiani come ''Il buono, il brutto, il cattivo'', creando un omaggio esplicito al genere spaghetti western.', 'Crediti della colonna sonora del film', TRUE, 'IA (Daily Sync)', 'IA Verificata', 0, 3, '2026-11-02T14:51:13.447724+00:00'),
('2bf56b92-0199-4c16-a008-f07c2a8d0185', 115, 'Effetti speciali & Trucco', 'La finta cicatrice e il cerotto di Marcellus Wallace', 'Ving Rhames indossa un cerotto sulla nuca nella prima metà del film per coprire una cicatrice reale che l''attore aveva riportato a seguito di un incidente. La leggenda metropolitana secondo cui il cerotto coprisse l''anima del personaggio estratta dalla testa fu smentita categoricamente da Quentin Tarantino.', 'Commento audio del regista nel DVD ufficiale di Pulp Fiction', TRUE, 'IA (Daily Sync)', 'IA Verificata', 0, 0, '2026-11-02T10:02:09.325725+00:00'),
('66a35a24-3605-430a-a6c3-528db474c87c', 115, 'Segreti di produzione', 'La Ford Chevelle Malibu rubata dal set', 'La splendida Ford Chevelle Malibu rossa del 1964 guidata da Vincent Vega nel film apparteneva in realtà allo stesso Quentin Tarantino. La vettura fu misteriosamente rubata durante le riprese nel 1993 e fu ritrovata dalla polizia di Los Angeles solo vent''anni dopo, nel 2013, per puro caso durante un''indagine su un furto d''auto.', 'Archivi della Polizia di Los Angeles e dichiarazioni ufficiali di Quentin Tarantino', TRUE, 'IA (Daily Sync)', 'IA Verificata', 0, 1, '2026-11-02T10:02:09.325725+00:00'),
('1b81bb66-fcfc-4fcb-8355-d142bb59b671', 115, 'Segreti di produzione', 'Il finto ristorante Jack Rabbit Slim''s', 'Le celebri sequenze all''interno del ristorante a tema anni ''50 Jack Rabbit Slim''s non furono girate in un locale esistente, ma all''interno di un enorme magazzino dismesso a Culver City. La ricostruzione costò oltre 5 milioni di dollari, rappresentando una delle voci di spesa più alte dell''intero budget di produzione del film.', 'Note di produzione e documentario ''Behind the Scenes of Pulp Fiction''', TRUE, 'IA (Daily Sync)', 'IA Verificata', 0, 2, '2026-11-02T10:02:09.325725+00:00'),
('6fbc49e8-6ef8-4d4b-93f1-e893da0d355a', 115, 'Casting & Scelte', 'Il vero compenso ridotto per Bruce Willis', 'Bruce Willis accettò di interpretare il pugile Butch Coolidge per un compenso notevolmente inferiore rispetto ai suoi standard hollywoodiani dell''epoca, aggirandosi intorno agli 800.000 dollari. L''attore decise di sostenere il progetto indipendente dopo essersi innamorato della sceneggiatura.', 'Rivista Variety e biografie ufficiali della produzione', TRUE, 'IA (Daily Sync)', 'IA Verificata', 0, 3, '2026-11-02T10:02:09.325725+00:00'),
('c17a5c42-ef34-4238-b304-63e9bb936424', 115, 'Citazioni & Easter Egg', 'L''origine della pistola con il silenziatore', 'La pistola con il silenziatore che Butch usa per giustiziare Vincent Vega nel proprio appartamento è una MAC-10. Questa scelta visiva e l''intera sequenza sono un preciso omaggio ai film polizieschi indipendenti e al cinema noir degli anni ''70 amati da Tarantino.', 'Analisi visiva e note del reparto scenografia di Pulp Fiction', TRUE, 'IA (Daily Sync)', 'IA Verificata', 0, 4, '2026-11-02T10:02:09.325725+00:00'),
('51c1187d-6205-43a7-8c5c-d1a1e2d1a6cb', 161, 'Casting & Scelte', 'L''iniziale coinvolgimento di Angelina Jolie', 'Prima che Scarlett Johansson firmasse per il ruolo di protagonista, Angelina Jolie era stata ufficialmente trattata e collegata al progetto nel 2011. Jolie ha successivamente rinunciato alla parte prima dell''inizio della produzione, spingendo Luc Besson a incontrare Johansson e a riadattare il personaggio su di lei.', 'Articoli di settore Variety e Deadline (2011-2013)', TRUE, 'IA (Daily Sync)', 'IA Verificata', 0, 0, '2026-11-02T10:09:51.616106+00:00'),
('58aa343f-f0a6-4f52-8e3c-34cc8ca61d42', 161, 'Curiosità & Retroscena', 'L''ispirazione biologica reale per il CPH4', 'Nonostante la droga CPH4 nel film sia un elemento fantastico, Luc Besson ha rivelato di essersi ispirato a una sostanza naturale reale prodotta dalle donne incinte durante la sesta settimana di gravidanza. Tale molecola agisce come catalizzatore per lo sviluppo della struttura ossea e corporea del feto, fatto che il regista ha poi drammatizzato ed esagerato a fini narrativi.', 'Intervista ufficiale a Luc Besson rilasciata a Wired', TRUE, 'IA (Daily Sync)', 'IA Verificata', 0, 1, '2026-11-02T10:09:51.616106+00:00'),
('05d194b5-1f97-4e26-a44a-9b9f3f423e66', 161, 'Citazioni & Easter Egg', 'L''omaggio all''omìnide ''Lucy'' e a Michelangelo', 'Nella sequenza del viaggio temporale, la protagonista incontra l''Australopithecus afarensis scoperto in Etiopia nel 1974 e battezzato ''Lucy''. Le due sfiorano i rispettivi indici riproducendo esattamente la celebre posa della ''Creazione di Adamo'' dipinta da Michelangelo nella Cappella Sistina.', 'Note di produzione ufficiali / Analisi visiva del film', TRUE, 'IA (Daily Sync)', 'IA Verificata', 0, 2, '2026-11-02T10:09:51.616106+00:00'),
('c0f50dfe-5320-4605-8f9d-19a4fda20026', 161, 'Effetti speciali & Trucco', 'Gli effetti visivi curati da Industrial Light & Magic', 'Per gestire le complesse sequenze di decomposizione molecolare e la percezione del flusso di dati, la produzione si è affidata alla Industrial Light & Magic (ILM). Il supervisore dei VFX Richard Bluff ha coordinato la creazione di oltre 1.000 inquadrature digitali con effetti ad alta complessità visiva.', 'Making-of ufficiale EuropaCorp e comunicati ILM', TRUE, 'IA (Daily Sync)', 'IA Verificata', 0, 3, '2026-11-02T10:09:51.616106+00:00'),
('4ac1f3e1-1fa9-43a3-8abc-3a714cd359cf', 161, 'Segreti di produzione', 'Lo storico sodalizio musicale con Eric Serra', 'La colonna sonora del film è stata composta da Eric Serra, segnando la prosecuzione di una collaborazione trentennale con Luc Besson iniziata negli anni ''80. Serra ha sviluppato un impianto sonoro prevalentemente elettronico e sintetico per sottolineare il graduale distacco di Lucy dalla sua natura umana.', 'Note di copertina della colonna sonora originale', TRUE, 'IA (Daily Sync)', 'IA Verificata', 0, 4, '2026-11-02T10:09:51.616106+00:00'),
('90e79ad8-f513-43ca-bdd7-c59211d749de', 161, 'Segreti di produzione', 'Il record per il cinema di produzione francese', 'Con un incasso globale che ha superato i 460 milioni di dollari a fronte di un budget di circa 40 milioni, ''Lucy'' è diventato il film di produzione francese con il maggior incasso di sempre a livello internazionale. Ha così infranto il record detenuto per 17 anni da ''Il quinto elemento'', diretto dallo stesso Besson nel 1997.', 'Dati ufficiali di box office Unifrance e Box Office Mojo', TRUE, 'IA (Daily Sync)', 'IA Verificata', 0, 5, '2026-11-02T10:09:51.616106+00:00'),
('21eb96e0-18be-4740-8dea-d657911e14ac', 200, 'Aneddoti dal set', 'L''improvvisazione telefonica tra Al Pacino e la madre nel film', 'Durante la sequenza in cui Sonny parla al telefono con sua madre (interpretata da Judith Malina), Al Pacino e l''attrice improvvisarono gran parte del dialogo emotivo seguendo solo le linee guida di Sidney Lumet, per catturare un realismo crudo e irripetibile.', 'Commento audio del regista Sidney Lumet nell''edizione speciale DVD', TRUE, 'IA (Daily Sync)', 'IA Verificata', 0, 0, '2026-11-02T10:10:53.404864+00:00'),
('9a7ef31c-6e80-4216-81bd-c8e42897bf8f', 200, 'Curiosità & Retroscena', 'La reazione entusiasta del vero John Wojtowicz', 'John Wojtowicz, il rapinatore realmente esistito a cui si ispira il personaggio di Sonny, rimase estremamente colpito dall''interpretazione di Al Pacino, arrivando a inviargli una lettera dal carcere per complimentarsi e ringraziarlo per aver umanizzato la sua storia.', 'Documentario ''The Dog'' (2013) e biografie ufficiali sulla produzione', TRUE, 'IA (Daily Sync)', 'IA Verificata', 0, 1, '2026-11-02T10:10:53.404864+00:00'),
('585252a8-64b8-4222-8a91-9cc1e16f729a', 200, 'Aneddoti dal set', 'Il malore sul set di Al Pacino', 'A causa dell''intenso stress fisico, del caldo soffocante ricreato sul set e delle continue corse e urla richieste dal copione, Al Pacino svenne realmente durante una delle giornate di riprese più faticose all''interno della banca.', 'Biografia ''Pacino'' di Lawrence Grobel', TRUE, 'IA (Daily Sync)', 'IA Verificata', 0, 2, '2026-11-02T10:10:53.404864+00:00'),
('c9847f80-c201-4e18-93fa-03562adb9550', 200, 'Casting & Scelte', 'L''approvazione del copione da parte di Chris Sarandon per la sua identità di genere', 'Chris Sarandon ottenne la parte di Leon (la moglie transessuale di Sonny) dopo un accurato casting in cui lavorò a stretto contatto con Sidney Lumet per evitare macchiette o stereotipi offensivi, consultandosi anche con attivisti LGBT dell''epoca.', 'Note di produzione e interviste d''archivio a Chris Sarandon', TRUE, 'IA (Daily Sync)', 'IA Verificata', 0, 3, '2026-11-02T10:10:53.404864+00:00'),
('4f51c584-37bf-4066-ac10-40216a3bf7c6', 116, 'Curiosità & Retroscena', 'La consulenza scientifica di Ray Kurzweil', 'Prima di scrivere la sceneggiatura, Spike Jonze ha consultato il famoso futurista e inventore Ray Kurzweil per discutere della plausibilità dell''intelligenza artificiale e di come la tecnologia avrebbe potuto integrarsi nella vita umana in un futuro prossimo.', 'Note di produzione ufficiali del film', TRUE, 'IA (Daily Sync)', 'IA Verificata', 0, 0, '2026-11-02T10:02:24.59583+00:00');
INSERT INTO public.movie_trivia ("id", "film_id", "categoria", "titolo", "descrizione", "fonte", "approvato", "inserito_da", "provenienza", "likes", "ordine", "created_at") VALUES
('6f9c9edc-c10e-4fc5-a0d6-aa112e6d5348', 116, 'Casting & Scelte', 'L''ispirazione iniziale da un sito web', 'L''idea alla base del film è nata a Spike Jonze diversi anni prima delle riprese, quando lesse su internet di un sito che permetteva agli utenti di interagire con un algoritmo di intelligenza artificiale avanzato.', 'Intervista ufficiale a Spike Jonze per Wired', TRUE, 'IA (Daily Sync)', 'IA Verificata', 0, 1, '2026-11-02T10:02:24.59583+00:00'),
('038de130-9eb1-4d03-bfd2-b90b00540a13', 116, 'Segreti di produzione', 'Il brano inedito degli Arcade Fire', 'La colonna sonora è stata composta dalla band Arcade Fire insieme a Owen Pallett. La canzone ''The Moon Song'', cantata nel film da Scarlett Johansson e Joaquin Phoenix, è stata candidata all''Oscar come miglior canzone originale.', 'Archivio ufficiale Academy Awards', TRUE, 'IA (Daily Sync)', 'IA Verificata', 0, 2, '2026-11-02T10:02:24.59583+00:00'),
('0ada967a-3611-4ffc-8ab8-557e0b5ab4cd', 116, 'Aneddoti dal set', 'Le riprese aggiuntive per la voce di Samantha', 'Poiché Scarlett Johansson è entrata nel progetto in post-produzione, Spike Jonze ha continuato a registrare e modificare le linee di dialogo della voce per oltre quattro mesi, adattandole continuamente alle riprese visive di Joaquin Phoenix.', 'Commento audio del regista nel Blu-ray', TRUE, 'IA (Daily Sync)', 'IA Verificata', 0, 3, '2026-11-02T10:02:24.59583+00:00'),
('a2544e99-ec32-4d01-852c-6645f612a36d', 116, 'Curiosità & Retroscena', 'Il cameo vocale di Bill Hader e Spike Jonze', 'All''inizio del film, il videogioco in cui Theodore si imbatte e che insulta aspramente il giocatore ha la voce registrata dallo stesso regista Spike Jonze, mentre il personaggio alieno nello stesso gioco è doppiato da Bill Hader.', 'Crediti finali del film e IMDb', TRUE, 'IA (Daily Sync)', 'IA Verificata', 0, 4, '2026-11-02T10:02:24.59583+00:00'),
('6498c1ce-acdb-4c3c-8d7d-7688ada5d3cc', 116, 'Segreti di produzione', 'La fusione tra Los Angeles e Shanghai per la scenografia', 'Sebbene gran parte del film sia ambientato a Los Angeles, lo scenografo K.K. Barrett ha scelto di girare molte sequenze esterne nel nuovo distretto finanziario di Pudong a Shanghai per sfruttare i grattacieli moderni e i passaggi pedonali sopraelevati.', 'Articolo di Architectural Digest sulle scenografie del film', TRUE, 'IA (Daily Sync)', 'IA Verificata', 0, 5, '2026-11-02T10:02:24.59583+00:00'),
('4a830c9e-0c27-4691-9b8c-d3bfe5edb722', 116, 'Curiosità & Retroscena', 'L''ispirazione per il sistema operativo da un ex membro dei Monty Python', 'Spike Jonze ha dichiarato in varie interviste di essersi parzialmente ispirato a un vecchio sketch di Terry Jones dei Monty Python per concepire l''idea di un utente che si innamora di una voce disincarnata.', 'Intervista retrospettiva a Spike Jonze', TRUE, 'IA (Daily Sync)', 'IA Verificata', 0, 6, '2026-11-02T10:02:24.59583+00:00'),
('f1341ba5-969e-42e9-8deb-48914ce1f1a4', 124, 'Casting & Scelte', 'La voce originale dell''Oracolo interpretata da Mary Alice', 'Dopo la scomparsa di Gloria Foster, l''attrice Mary Alice fu scelta per raccogliere l''eredità del personaggio dell''Oracolo in ''Matrix Revolutions''. Le sorelle Wachowski scelsero Mary Alice non solo per la sua straordinaria presenza scenica, ma anche per la sua capacità di mantenere la stessa profonda e materna autorevolezza stabilita dalla Foster nei primi due capitoli.', 'Note di produzione ufficiali di The Matrix Revolutions', TRUE, 'IA (Daily Sync)', 'IA Verificata', 0, 0, '2026-11-02T10:04:00.957795+00:00'),
('2e089ee0-1f78-419d-97fd-f76c8d3695d7', 124, 'Curiosità & Retroscena', 'Il record di visualizzazioni del trailer online', 'Nel corso della campagna promozionale del 2003, il trailer cinematografico di ''Matrix Revolutions'' ha stabilito un primato storico su Internet, registrando oltre 6,3 milioni di download legali in soli quattro giorni dal rilascio sui principali portali di intrattenimento dell''epoca.', 'Comunicato stampa Warner Bros. Pictures 2003', TRUE, 'IA (Daily Sync)', 'IA Verificata', 0, 1, '2026-11-02T10:04:00.957795+00:00'),
('b854de77-1bfd-4c21-bc65-30b547149f73', 124, 'Effetti speciali & Trucco', 'La complessa sequenza dei mech APU contro le Sentinelle', 'Per realizzare la brutale sequenza d''assedio in cui i soldati di Zion combattono a bordo dei mech APU (Armored Personnel Units) contro le sciami di Sentinelle, il team della ESC Entertainment ha dovuto combinare estesi set fisici meccanizzati con la cattura di movimenti avanzati e complessi ambienti digitali, impiegando oltre un anno di rendering.', 'The Art of the Matrix / Making-of documentario', TRUE, 'IA (Daily Sync)', 'IA Verificata', 0, 2, '2026-11-02T10:04:00.957795+00:00'),
('eb419c25-2f82-4704-a5ea-10d129ac987d', 166, 'Aneddoti dal set', 'La scelta del fiume per la scena dello stupro', 'La brutale sequenza iniziale dello stupro della bambina fu girata lungo il fiume Pearl nel Mississippi. Per garantire la sicurezza delle giovani comparse e gestire la delicatezza della scena, la produzione impiegò psicologi infantili a tempo pieno sul set.', 'Note di produzione ufficiali Warner Bros.', TRUE, 'IA (Daily Sync)', 'IA Verificata', 0, 0, '2026-11-02T10:16:16.655792+00:00'),
('8778fa84-6602-4e3a-bfbc-9ce437e41ea3', 166, 'Casting & Scelte', 'La preparazione legale di Matthew McConaughey', 'Per prepararsi al ruolo dell''avvocato Jake Brigance, Matthew McConaughey ha trascorso diverse settimane a Canton, in Mississippi, frequentando veri studi legali e assistendo a processi locali per studiare la cadenza, la gestualità e la parlata degli avvocati del sud.', 'Intervista retrospettiva a Matthew McConaughey per Entertainment Weekly', TRUE, 'IA (Daily Sync)', 'IA Verificata', 0, 1, '2026-11-02T10:16:16.655792+00:00'),
('9a8cc080-d9c5-4e64-962c-481f20830177', 166, 'Casting & Scelte', 'Il rifiuto di Joel Schumacher a Woody Harrelson', 'Prima di puntare su Matthew McConaughey, il regista Joel Schumacher prese in considerazione Woody Harrelson per la parte del protagonista Jake Brigance. Tuttavia, si decise che l''attore aveva un''immagine pubblica troppo legata a ruoli eccentrici in quel preciso momento della sua carriera.', 'Biography di Joel Schumacher / DVD Audio Commentary', TRUE, 'IA (Daily Sync)', 'IA Verificata', 0, 2, '2026-11-02T10:16:16.655792+00:00'),
('5ca07a39-ca75-48e9-8756-debab7e5e997', 166, 'Segreti di produzione', 'Le minacce reali ricevute dalla produzione', 'A causa dei temi delicati legati al razzismo e alla presenza del Ku Klux Klan nella trama, la troupe cinematografica ricevette alcune lettere minatorie anonime durante le prime settimane di lavorazione nel Mississippi, costringendo la produzione ad aumentare drasticamente la sicurezza privata sul set.', 'Reportage dal set della rivista Premiere del 1996', TRUE, 'IA (Daily Sync)', 'IA Verificata', 0, 3, '2026-11-02T10:16:16.655792+00:00'),
('2132d503-4d13-4327-8486-1f7d472df04b', 185, 'Casting & Scelte', 'La candidatura iniziale di Cary Grant', 'Nelle primissime fasi di sviluppo del progetto, prima che René Clair optasse per Dick Powell, la produzione aveva preso in forte considerazione Cary Grant per il ruolo del protagonista Larry Stevens.', 'Note di produzione e archivi della Pressman-Clair Productions', TRUE, 'IA (Daily Sync)', 'IA Verificata', 0, 0, '2026-11-02T10:17:47.791175+00:00'),
('5753b7b9-9b35-495b-9e97-63a85f0d3264', 185, 'Aneddoti dal set', 'La scomparsa di John Philliber prima dell''uscita', 'L''attore di carattere John Philliber, che interpreta l''archivista Pop Benson, morì poco dopo la fine delle riprese nel 1944, non riuscendo a vedere il film distribuito nelle sale cinematografiche americane.', 'Necrologi cinematografici dell''epoca e registri di produzione', TRUE, 'IA (Daily Sync)', 'IA Verificata', 0, 1, '2026-11-02T10:17:47.791175+00:00'),
('931aaccc-419e-4b67-bff1-5bd913d6e343', 117, 'Aneddoti dal set', 'L''improvvisazione shakespeariana di Robin Williams', 'Durante la scena in cui il professor Keating prende in giro l''attore Marlon Brando e imita John Wayne davanti alla classe, gran parte del monologo fu completamente improvvisato da Robin Williams, lasciando i giovani attori sinceramente sorpresi e divertiti sul set.', 'Commento audio del regista Peter Weir nel DVD speciale', TRUE, 'IA (Daily Sync)', 'IA Verificata', 0, 0, '2026-11-02T10:02:40.528279+00:00'),
('6adfaf4c-12c0-4dd0-aff7-2b7c06d0bebc', 117, 'Curiosità & Retroscena', 'La scelta del titolo originale e il riferimento poetico', 'Il titolo originale del film, ''Dead Poets Society'', deriva da una vera e propria società segreta fondata dallo sceneggiatore Tom Schulman e dai suoi amici durante gli anni trascorsi alla Montgomery Bell Academy, basata sulla lettura clandestina di poesia.', 'Note di produzione ufficiali della Touchstone Pictures', TRUE, 'IA (Daily Sync)', 'IA Verificata', 0, 1, '2026-11-02T10:02:40.528279+00:00'),
('a0b19f1f-ec26-407a-a9af-3dbbc14cc2f9', 117, 'Curiosità & Retroscena', 'L''ispirazione reale per il personaggio del professor Keating', 'Il personaggio di John Keating è modellato sul professor Samuel F. Pickering Jr., un insegnante realmente esistito che Tom Schulman ebbe al college e che incoraggiava gli studenti a pensare con la propria testa in modo anticonformista.', 'Intervista documentaria allo sceneggiatore Tom Schulman', TRUE, 'IA (Daily Sync)', 'IA Verificata', 0, 2, '2026-11-02T10:02:40.528279+00:00'),
('05a8a53f-bba6-4076-8fc8-97767ebb763a', 117, 'Segreti di produzione', 'L''addio sofferto del primo regista', 'Dustin Hoffman era inizialmente interessato a dirigere il film e a interpretare il ruolo di Keating quando il progetto era ancora in fase di sviluppo presso la Twentieth Century Fox, prima che la produzione passasse alla Touchstone e venisse ingaggiato Peter Weir.', 'Archivi storici di produzione della Touchstone Pictures', TRUE, 'IA (Daily Sync)', 'IA Verificata', 0, 3, '2026-11-02T10:02:40.528279+00:00'),
('4632769d-b73f-4fc5-b0c9-280570eec429', 117, 'Segreti di produzione', 'La rigida selezione delle comparse locali', 'Per mantenere l''autenticità visiva del collegio maschile nel 1959, la produzione ingaggiò decine di veri studenti provenienti dalle scuole superiori circostanti del Delaware, imponendo loro di sottoporsi a tagli di capelli d''epoca rigorosi.', 'Reportage dal set della rivista American Cinematographer', TRUE, 'IA (Daily Sync)', 'IA Verificata', 0, 4, '2026-11-02T10:02:40.528279+00:00'),
('7874289e-718d-439b-b209-8e56e6b30ead', 135, 'Curiosità & Retroscena', 'La consulenza di Michael Kaiser per i danni cerebrali', 'Per conferire accuratezza scientifica alla diagnosi di encefalopatia traumatica cronica che costringe Rocky al ritiro, la produzione consultò il neurochirurgo dottor Michael Kaiser del Columbia-Presbyterian Medical Center, il quale visionò anche i dati dei precedenti incontri della saga.', 'Note di produzione ufficiali United Artists', TRUE, 'IA (Daily Sync)', 'IA Verificata', 0, 0, '2026-11-02T10:05:10.257921+00:00'),
('ce8db02c-6571-4d2a-9de6-e1dc027c73fb', 135, 'Citazioni & Easter Egg', 'Il cameo di Michael Reagan', 'Michael Reagan, conduttore radiofonico e figlio adottivo dell''ex presidente degli Stati Uniti Ronald Reagan, appare brevemente nel film nel ruolo di un giornalista sportivo durante le sequenze della conferenza stampa.', 'Crediti ufficiali del film', TRUE, 'IA (Daily Sync)', 'IA Verificata', 0, 1, '2026-11-02T10:05:10.257921+00:00'),
('1b2bb5a8-1d4e-4b68-a82f-654bcfa8ddf5', 135, 'Casting & Scelte', 'La genesi del personaggio di George Washington Duke', 'Il personaggio del famelico manager George Washington Duke, interpretato da Richard Gant, fu modellato da Sylvester Stallone e dagli sceneggiatori unendo i tratti di reali e spregiudicati promotori pugilistici dell''epoca come Don King.', 'Intervista retrospettiva a Sylvester Stallone per Cinefex', TRUE, 'IA (Daily Sync)', 'IA Verificata', 0, 2, '2026-11-02T10:05:10.257921+00:00'),
('315c4604-8fe8-4d74-89af-65787d7fde49', 162, 'Casting & Scelte', 'La scelta iniziale di Robin Williams e Brian De Palma', 'Prima che Peter Weir salisse a bordo del progetto e scegliesse Jim Carrey, la sceneggiatura di Andrew Niccol aveva attirato l''interesse di Brian De Palma, che avrebbe dovuto dirigere il film con Robin Williams nel ruolo del protagonista Truman Burbank.', 'Archivi di produzione e interviste storiche a Andrew Niccol', TRUE, 'IA (Daily Sync)', 'IA Verificata', 0, 0, '2026-11-02T10:09:58.559406+00:00'),
('cdcbd101-f679-4d60-8f43-fa608ba070a8', 162, 'Citazioni & Easter Egg', 'L''ispirazione per il cognome Burbank', 'Il cognome del protagonista, Burbank, non è casuale: fa riferimento all''omonima città californiana nella contea di Los Angeles, storicamente nota per essere il cuore pulsante delle sedi di grandi major televisive e cinematografiche come la Warner Bros. e la Disney.', 'Note ufficiali della sceneggiatura di Andrew Niccol', TRUE, 'IA (Daily Sync)', 'IA Verificata', 0, 1, '2026-11-02T10:09:58.559406+00:00'),
('69893b51-21bb-4b00-89fd-95d43ee6ef08', 162, 'Aneddoti dal set', 'L''improvvisazione dello specchio', 'Una delle scene più iconiche in cui Truman gioca con la saponetta e disegna un astronauta sul bagno di casa fu ampiamente improvvisata da Jim Carrey, il quale ideò sul momento le smorfie e i dialoghi fittizi con se stesso allo specchio per enfatizzare la dissociazione del personaggio.', 'Commento audio del regista Peter Weir nel DVD ufficiale', TRUE, 'IA (Daily Sync)', 'IA Verificata', 0, 2, '2026-11-02T10:09:58.559406+00:00'),
('c87e54ae-bedf-47fe-ade2-f409caaa1ef9', 168, 'Casting & Scelte', 'La polizza assicurativa negata a Tommy Lee Jones', 'Prima di assegnare la parte dello sceriffo Ed Tom Bell a Tommy Lee Jones, i fratelli Coen avevano pensato a vari attori, ma la produzione dovette affrontare problemi con le assicurazioni a causa dell''età avanzata di alcuni candidati; tuttavia, Jones ottenne la parte anche grazie alla sua autentica conoscenza del Texas rurale.', 'Audio commento del DVD e note di produzione', TRUE, 'IA (Daily Sync)', 'IA Verificata', 0, 0, '2026-11-02T10:16:27.493691+00:00'),
('ac6b91bb-cfad-4299-87d8-696118e5dccb', 168, 'Casting & Scelte', 'Il ruolo rifiutato da Mark Wahlberg', 'Prima che Josh Brolin sostenesse il provino fortuito grazie a Robert Rodriguez, il ruolo del protagonista Llewelyn Moss fu offerto a Mark Wahlberg, il quale rifiutò l''offerta perché impegnato in altri progetti cinematografici.', 'Intervista a Mark Wahlberg per MTV Movies', TRUE, 'IA (Daily Sync)', 'IA Verificata', 0, 1, '2026-11-02T10:16:27.493691+00:00'),
('033c0bb3-52fe-4d0f-962d-271415ec003e', 168, 'Aneddoti dal set', 'La location reale della farmacia saccheggiata', 'La scena in cui Anton Chigurh entra in una farmacia per rubare medicinali e garze dopo essere stato ferito fu girata in un vero negozio della cittadina di Las Vegas, in New Mexico, utilizzando i residenti locali come comparse non professioniste.', 'Making-of ufficiale ''Working with the Coen Brothers''', TRUE, 'IA (Daily Sync)', 'IA Verificata', 0, 2, '2026-11-02T10:16:27.493691+00:00'),
('c7fb9875-82a4-45a0-bcae-0e4f38ef1af9', 168, 'Segreti di produzione', 'L''uso dei suoni reali per il fucile silenziato', 'Per il fucile Remington 1187 con silenziatore usato da Anton Chigurh, il supervisore del montaggio del suono Skip Lievsay decise di non usare i classici campioni hollywoodiani, registrando invece il suono reale dell''arma con il silenziatore in un poligono di tiro aperto.', 'Intervista a Skip Lievsay per Soundwork Collection', TRUE, 'IA (Daily Sync)', 'IA Verificata', 0, 3, '2026-11-02T10:16:27.493691+00:00'),
('84b496eb-7288-44f3-8594-87b96acf2092', 241, 'Curiosità & Retroscena', 'La presenza di Harrison Ford in una scena tagliata', 'Harrison Ford girò un breve cameo nel film interpretando il preside della scuola di Elliott, il quale rimprovera aspramente il ragazzo nell''ufficio di presidenza mentre la sedia di quest''ultimo inizia a levitare per via dei poteri di E.T. La scena fu tuttavia tagliata in fase di montaggio finale perché Spielberg ritenne che la presenza di una star del calibro di Ford avrebbe distratto troppo il pubblico.', 'Documentario ufficiale ''The Making of E.T.''', TRUE, 'IA (Daily Sync)', 'IA Verificata', 0, 0, '2026-11-02T10:21:19.420276+00:00'),
('717ef1d9-fa8f-4eb8-9af3-2a6b293c6ad3', 118, 'Segreti di produzione', 'La scelta del teatro di posa nel Colorado', 'Per mantenere il controllo totale sulla temperatura e simulare il freddo intenso del Wyoming, la produzione ha fatto costruire il set principale degli interni dell''Emporio di Minnie all''interno di un enorme congelatore industriale a Telluride, in Colorado, dove le temperature venivano mantenute costantemente sotto lo zero.', 'Note di produzione ufficiali e documentario sul backstage', TRUE, 'IA (Daily Sync)', 'IA Verificata', 0, 0, '2026-11-02T10:02:48.247626+00:00'),
('876e2ab3-4d88-4843-ba3e-c085b6f54178', 118, 'Aneddoti dal set', 'La troupe in abiti invernali sul set', 'A causa delle temperature glaciali mantenute sul set per favorire la veridicità delle performance e il vapore acqueo visibile durante i dialoghi, l''intera troupe tecnica e lo stesso Quentin Tarantino indossavano pesanti cappotti invernali, guanti e berretti durante le riprese delle scene all''interno dell''emporio.', 'Intervista al direttore della fotografia Robert Richardson', TRUE, 'IA (Daily Sync)', 'IA Verificata', 0, 1, '2026-11-02T10:02:48.247626+00:00'),
('09638fc7-9076-45ac-8a1b-d5c8b9dd5493', 118, 'Segreti di produzione', 'Il blocco delle riprese per la neve vera', 'Le riprese all''aperto nei pressi di Telluride dovettero subire pesanti interruzioni e slittamenti di calendario perché la tanto attesa neve del Colorado si rivelò insufficiente o si sciolse rapidamente a causa di un''insolita ondata di calore anomalo, costringendo la produzione a spostarsi in zone più alte e fredde.', 'Diario di produzione e interviste al cast', TRUE, 'IA (Daily Sync)', 'IA Verificata', 0, 2, '2026-11-02T10:02:48.247626+00:00'),
('a73a8a33-87a4-4e05-b6b5-19e545baee69', 118, 'Curiosità & Retroscena', 'L''ispirazione televisiva per la struttura narrativa', 'Quentin Tarantino ha dichiarato apertamente di aver strutturato la narrazione e l''atmosfera claustrofobica del film traendo forte ispirazione dagli episodi speciali in stile ''bottled show'' (ambientati in un''unica stanza) di classiche serie televisive western degli anni ''60 come ''Bonanza'', ''Il virginiano'' e ''Ai confini della realtà''.', 'Intervista promozionale per la stampa di Quentin Tarantino', TRUE, 'IA (Daily Sync)', 'IA Verificata', 0, 3, '2026-11-02T10:02:48.247626+00:00'),
('8f6ef380-49b5-4b20-bf22-2154cec24ced', 118, 'Segreti di produzione', 'L''utilizzo delle bobine da 70mm d''epoca', 'Poiché gli standard di proiezione in 70mm erano quasi estinti, la produzione ha dovuto rintracciare, restaurare e installare proiettori speciali in circa 100 cinema selezionati negli Stati Uniti, formando appositi operatori per gestire le grandi bobine pellicola durante il tour cinematografico denominato ''Roadshow''.', 'Panavision Historical Archives e comunicato stampa ufficiale The Weinstein Company', TRUE, 'IA (Daily Sync)', 'IA Verificata', 0, 4, '2026-11-02T10:02:48.247626+00:00'),
('0c5a202c-8b14-4447-9f1e-d8823858aab8', 122, 'Segreti di produzione', 'L''ispirazione visiva per gli abiti di Morpheus', 'La costumista Kym Barrett ha ideato l''iconico look di Morpheus traendo ispirazione dai Maasai dell''Africa orientale e dalla cultura hip-hop di New York, mescolando elementi tradizionali con il PVC nero lucido per dare un senso di timelessness e autorità.', 'Documentario ufficiale ''What is the Matrix?'' (2001)', TRUE, 'IA (Daily Sync)', 'IA Verificata', 0, 0, '2026-11-02T10:03:32.974581+00:00'),
('80c6fd81-acd7-4ea7-bb2a-ed763051f459', 122, 'Aneddoti dal set', 'La cicatrice reale di Carrie-Anne Moss', 'Durante le prove delle sequenze d''azione, Carrie-Anne Moss si è ferita gravemente a una caviglia, ma ha nascosto l''infortunio al regista e alla produzione per tre settimane per paura di essere sostituita, continuando a girare le scene di lotta con forti dolori.', 'Intervista a Carrie-Anne Moss nel talk show di Conan O''Brien', TRUE, 'IA (Daily Sync)', 'IA Verificata', 0, 1, '2026-11-02T10:03:32.974581+00:00'),
('b404bdcb-b8ce-4828-ab8e-2ad5a45833ae', 122, 'Segreti di produzione', 'Il set della metropolitana riprodotto in studio', 'La sequenza del combattimento tra Neo e l''Agente Smith nella stazione della metropolitana non è stata girata in una vera stazione, ma su un set appositamente costruito all''interno di un magazzino abbandonato a Sydney, lungo circa 110 metri, per permettere agli stuntman di muoversi in totale sicurezza con i cavi.', 'Audio commento del cast e della troupe nel DVD speciale', TRUE, 'IA (Daily Sync)', 'IA Verificata', 0, 2, '2026-11-02T10:03:32.974581+00:00'),
('23a07641-d00a-45b8-8ccb-f4fe961d5f98', 122, 'Casting & Scelte', 'La scelta del nome di Trinity', 'Lana e Lilly Wachowski scelsero il nome ''Trinity'' non solo per richiamare concetti filosofici e religiosi, ma anche perché la co-registista Lilly era affascinata dal suono della parola e dal suo significato numerologico legato al numero tre all''interno della struttura della sceneggiatura.', 'Intervista retrospettiva alle sorelle Wachowski per Rolling Stone', TRUE, 'IA (Daily Sync)', 'IA Verificata', 0, 3, '2026-11-02T10:03:32.974581+00:00'),
('fa0b7240-4e33-474e-a007-2f23b9c840b8', 122, 'Curiosità & Retroscena', 'Il budget iniziale tagliato dai produttori', 'Inizialmente la Warner Bros. aveva approvato un budget di 80 milioni di dollari per The Matrix, ma dopo aver letto le prime bozze della complessa sceneggiatura, i dirigenti ridussero la cifra a 63 milioni. Le Wachowski spesero quasi l''intero budget della sequenza di apertura (la fuga di Trinity) nei primi dieci minuti di film per convincere lo studio della bontà del progetto.', 'Libro ''The Matrix: The Shooting Script'' e note di produzione', TRUE, 'IA (Daily Sync)', 'IA Verificata', 0, 4, '2026-11-02T10:03:32.974581+00:00'),
('f0f91127-8ba9-4dee-ab85-6716c766f246', 122, 'Citazioni & Easter Egg', 'L''origine dei nomi dei personaggi: Cypher', 'Il nome del traditore Cypher (interpretato da Joe Pantoliano) contiene un duplice gioco di parole: fa riferimento alla parola ''cifrario'' (codice informatico) ma evoca anche foneticamente la figura di Lucifero (Lucipher), anticipando il suo ruolo di Giuda all''interno del gruppo dei ribelli.', 'Analisi ufficiale della sceneggiatura e DVD Making-of', TRUE, 'IA (Daily Sync)', 'IA Verificata', 0, 5, '2026-11-02T10:03:32.974581+00:00'),
('b6e04a97-300f-4d9d-bed1-07269bda68fa', 128, 'Curiosità & Retroscena', 'L''origine della canzone leitmotiv ''Sean Brady''', 'Il celebre motivetto cantato da Edda Dell''Orso per il personaggio di John Mallory utilizza il nome ''Sean Brady'', ma Ennio Morricone compose la melodia e la fonetica basandosi su una deformazione fonetica inventata da Sergio Leone per evocare le ballate rivoluzionarie irlandesi.', 'Note di copertina e interviste d''archivio della Sugar Music per la colonna sonora', TRUE, 'IA (Daily Sync)', 'IA Verificata', 0, 0, '2026-11-02T10:04:30.534674+00:00'),
('a68e68c2-f8c5-4ee6-b2bd-3548d5a08003', 128, 'Segreti di produzione', 'La scelta del nome originale in lingua inglese', 'Negli Stati Uniti il film fu distribuito inizialmente con il titolo ''Duck, You Sucker!'' (traduzione letterale dell''esclamazione popolare italiana ''Giù la testa, fesso!''), ma la United Artists, temendo che il pubblico non capisse il senso e scambiasse la pellicola per una commedia leggera, lo cambiò prima in ''The Fistful of Dynamite'' e poi in ''Once Upon a Time... The Revolution''.', 'Archivi storici di produzione della United Artists e biografie di Sergio Leone', TRUE, 'IA (Daily Sync)', 'IA Verificata', 0, 1, '2026-11-02T10:04:30.534674+00:00'),
('ae3c6bd6-7d8b-4b98-b6bd-dc5df2d24152', 128, 'Casting & Scelte', 'L''ispirazione per il personaggio di Juan Miranda', 'La caratterizzazione del bandito messicano Juan Miranda, interpretato da Rod Steiger, fu parzialmente modellata da Sergio Leone studiando i comportamenti e la retorica dei rivoluzionari contadini realmente esistiti durante le sollevazioni guidate da Emiliano Zapata e Pancho Villa.', 'Documentario retrospettivo ''Once Upon a Time Sergio Leone'' e interviste al regista', TRUE, 'IA (Daily Sync)', 'IA Verificata', 0, 2, '2026-11-02T10:04:30.534674+00:00'),
('5b74d6ce-5788-42c7-994a-f764a7754f45', 339, 'Casting & Scelte', 'La cancellazione del cameo di Willem Dafoe', 'Willem Dafoe aveva originariamente girato alcune scene nei panni di un politico corrotto dell''epoca, ma il suo personaggio fu completamente eliminato in fase di montaggio per snellire la narrazione e concentrarsi sul triangolo principale.', 'Intervista a Willem Dafoe per Entertainment Weekly', TRUE, 'IA (Daily Sync)', 'IA Verificata', 0, 4, '2026-11-02T14:51:13.447724+00:00'),
('7b121a9e-6a83-4d35-a040-d2b6690c295d', 119, 'Citazioni & Easter Egg', 'L''ispirazione cinematografica da John Hughes', 'Il regista Jon Watts ha dichiarato pubblicamente di aver presentato il film ai dirigenti dei Marvel Studios usando come riferimento principale i classici adolescenti degli anni ''80 diretti da John Hughes, fondendo il cinecomic con il genere del teen movie.', 'Note di produzione ufficiali Marvel Studios', TRUE, 'IA (Daily Sync)', 'IA Verificata', 0, 0, '2026-11-02T10:02:56.4932+00:00'),
('b09885dd-2b9f-4500-8698-1e0304e41cc9', 119, 'Effetti speciali & Trucco', 'La creazione dei ragnateloni digitali interattivi', 'Per permettere a Tom Holland di avere un feedback fisico credibile durante i volteggi, la troupe ha utilizzato speciali cavi elastici collegati a una gru, permettendogli di compiere acrobazie reali prima dell''aggiunta della CGI in post-produzione.', 'Speciali del backstage e interviste ai supervisori degli effetti visivi', TRUE, 'IA (Daily Sync)', 'IA Verificata', 0, 1, '2026-11-02T10:02:56.4932+00:00'),
('eea81bcf-a3d6-4c3c-8a3f-22043992bad3', 119, 'Casting & Scelte', 'Il cameo vocale di Jennifer Connelly', 'Karen, l''intelligenza artificiale integrata nella tuta di alta tecnologia di Peter Parker, è doppiata dall''attrice premio Oscar Jennifer Connelly, che nella vita reale è sposata con Paul Bettany, storico interprete di Jarvis e Visione nel MCU.', 'Crediti ufficiali del film', TRUE, 'IA (Daily Sync)', 'IA Verificata', 0, 2, '2026-11-02T10:02:56.4932+00:00'),
('2a6d78ee-5991-4fef-9a95-60be123a6c82', 119, 'Curiosità & Retroscena', 'La scelta della canzone di apertura degli 10cc', 'La sequenza in cui Peter registra il suo video-diario con lo smartphone durante gli eventi di ''Captain America: Civil War'' si apre con il brano ''The Things We Do for Love'' della band britannica 10cc, scelto personalmente da Jon Watts per dare un tono nostalgico e domestico.', 'Commento audio del regista all''edizione Home Video', TRUE, 'IA (Daily Sync)', 'IA Verificata', 0, 3, '2026-11-02T10:02:56.4932+00:00'),
('5e9de8fc-35ca-4961-8669-0481c6249604', 121, 'Casting & Scelte', 'Il cameo legale di Charlie Cox', 'Charlie Cox ha ripreso ufficialmente il suo ruolo di Matt Murdock in una sola sequenza in cui fa da avvocato a Peter Parker, un''apparizione che i Marvel Studios hanno tenuto segreta per anni nonostante i fan lo sapessero fin dall''inizio delle riprese.', 'Intervista ufficiale a Charlie Cox per Empire Magazine', TRUE, 'IA (Daily Sync)', 'IA Verificata', 0, 0, '2026-11-02T10:03:19.742761+00:00'),
('6c3fd03d-9e78-4ab2-9f7f-838cd2a2b86a', 121, 'Casting & Scelte', 'La telefonata segreta tra i Marvel Studios e Alfred Molina', 'Il regista Jon Watts ha rivelato di aver incontrato Alfred Molina per la prima volta casualmente in un ristorante a Los Angeles prima ancora di avere una sceneggiatura completa, chiedendogli direttamente di tornare a interpretare il Dottor Octopus.', 'Dichiarazione ufficiale di Jon Watts nelle note di produzione Sony Pictures', TRUE, 'IA (Daily Sync)', 'IA Verificata', 0, 1, '2026-11-02T10:03:19.742761+00:00'),
('e6fcedc1-bfa6-4434-a6a2-1b9aed658415', 121, 'Casting & Scelte', 'Il ritorno di Willem Dafoe basato su una condizione artistica precisa', 'Willem Dafoe ha accettato di tornare a vestire i panni del Green Goblin solo a condizione di poter girare personalmente gran parte delle scene d''azione e dei combattimenti fisici, rifiutando di essere sostituito interamente da uno stuntman.', 'Intervista rilasciata da Tom Holland e Willem Dafoe per Variety', TRUE, 'IA (Daily Sync)', 'IA Verificata', 0, 2, '2026-11-02T10:03:19.742761+00:00'),
('1f45ec61-da86-4b68-85ce-69974f3ac5ae', 121, 'Curiosità & Retroscena', 'L''ispirazione per la morte di Zia May tratta dai fumetti storici', 'Gli sceneggiatori Chris McKenna ed Erik Sommers hanno ammesso che l''addio tragico al personaggio di Zia May interpretato da Marisa Tomei riprende esplicitamente la celebre dinamica della morte dello Zio Ben nei fumetti classici, spingendo Peter a comprendere la massima responsabilità del suo potere.', 'Dietro le quinte e commento audio ufficiale degli sceneggiatori', TRUE, 'IA (Daily Sync)', 'IA Verificata', 0, 3, '2026-11-02T10:03:19.742761+00:00'),
('54c6784e-7848-4dcf-a04f-db0d5899d397', 121, 'Segreti di produzione', 'La scena del seminterrato di Doctor Strange e l''uso del volume LED', 'Per girare le sequenze all''interno del Sanctum Sanctorum invaso dalla neve e dal fango magico, la produzione ha modificato temporaneamente i set fisici integrandoli con proiezioni avanzate per gestire le complesse interazioni di luce ed effetti visivi.', 'Documentario ''The Making of Spider-Man: No Way Home'' nei contenuti extra Blu-ray', TRUE, 'IA (Daily Sync)', 'IA Verificata', 0, 4, '2026-11-02T10:03:19.742761+00:00'),
('90bd5112-2a5c-4159-957b-de2dda7f5c0b', 162, 'Segreti di produzione', 'La colonna sonora basata sulla musica classica', 'Peter Weir scelse di affidare le musiche del film prevalentemente a brani di compositori classici e contemporanei già esistenti, tra cui Philip Glass e Fryderyk Chopin, inserendo solo in un secondo momento alcune tracce originali composte dallo stesso Glass.', 'Note di produzione e crediti musicali ufficiali del film', TRUE, 'IA (Daily Sync)', 'IA Verificata', 0, 3, '2026-11-02T10:09:58.559406+00:00'),
('bdff6284-ee68-4f9c-a7e2-0729ef316a53', 162, 'Curiosità & Retroscena', 'Il rifiuto del ruolo di Meryl di recitare con attori non unionizzati', 'Laura Linney, per calarsi perfettamente nella parte della moglie di Truman che promuove continuamente prodotti commerciali con la tipica dizione da televendita, studiò attentamente i canali televisivi di televendite americani e le pubblicità degli anni ''50.', 'Intervista promozionale d''epoca a Laura Linney', TRUE, 'IA (Daily Sync)', 'IA Verificata', 0, 4, '2026-11-02T10:09:58.559406+00:00'),
('dd73a4e7-abcb-46c5-a54a-b6f9fd0a1329', 169, 'Effetti speciali & Trucco', 'Il ritardo di Vincent D''Onofrio e la trasformazione fisica', 'Vincent D''Onofrio ha dovuto ingrassare circa 32 chili in soli sette mesi per interpretare il soldato Pyle, arrivando a pesare oltre 120 kg. Questa imponente trasformazione fisica ha causato all''attore gravi problemi di salute, tra cui la rottura di un legamento del ginocchio durante la famigerata sequenza della trappola a ostacoli nel campo d''addestramento.', 'Intervista retrospettiva a Vincent D''Onofrio nel documentario ''Full Metal Jacket: Between Good and Evil''', TRUE, 'IA (Daily Sync)', 'IA Verificata', 0, 1, '2026-11-02T10:16:34.894832+00:00'),
('a2d2d90a-6fab-4643-a9d9-149fc3f93cf0', 169, 'Segreti di produzione', 'L''uso delle lenti cinematografiche e l''estetica documentaristica', 'Stanley Kubrick e il direttore della fotografia Douglas Milsome hanno scelto di girare gran parte del film utilizzando obiettivi grandangolari e cineprese Arriflex mobili per simulare l''estetica ruvida dei cinegiornali televisivi dell''epoca del Vietnam, privilegiando spesso la luce naturale o fonti pratiche sul set.', 'American Cinematographer Magazine, articolo tecnico su Full Metal Jacket', TRUE, 'IA (Daily Sync)', 'IA Verificata', 0, 2, '2026-11-02T10:16:34.894832+00:00'),
('559c82b9-709f-4af2-a04b-47e180d2a206', 169, 'Casting & Scelte', 'Il vero veterano nel cast nei panni di Cowboy', 'L''attore Arliss Howard, che interpreta il soldato Cowboy, ha condiviso il set con un vero veterano del Vietnam, il sergente maggiore James Edson, che lavorava come consulente tecnico sul set e che ha aiutato il cast a mantenere il massimo rigore comportamentale e tattico durante le sequenze di combattimento.', 'Note di produzione e press book ufficiale del film (1987)', TRUE, 'IA (Daily Sync)', 'IA Verificata', 0, 3, '2026-11-02T10:16:34.894832+00:00'),
('9ea0c036-2942-4c50-90bc-6ff047b38bf3', 174, 'Segreti di produzione', 'La consulenza del glottologo per il proto-latino', 'Per la ricostruzione filologica del proto-latino parlato nel film, la produzione si è affidata alla consulenza scientifica del professor Filippo ঐতিহাসিক e glottologi dell''Università ''La Sapienza'' di Roma, i quali hanno lavorato a stretto contatto con gli attori per mesi affinché la pronuncia risultasse storicamente plausibile per l''VIII secolo a.C.', 'Note di produzione ufficiali e conferenza stampa d''uscita del film', TRUE, 'IA (Daily Sync)', 'IA Verificata', 0, 0, '2026-11-02T10:16:49.520645+00:00'),
('b9977000-495f-45c0-abe2-c2737322ddb5', 120, 'Aneddoti dal set', 'Il cameo del fratello di Tom Holland', 'Nel film compare in un piccolo cameo Harry Holland, il fratello minore di Tom Holland. Interpreta un ragazzo che viene sgombrato da Peter Parker durante la sequenza del festival a Venezia.', 'Note di produzione ufficiali e intervista a Tom Holland al Jimmy Kimmel Live', TRUE, 'IA (Daily Sync)', 'IA Verificata', 0, 0, '2026-11-02T10:03:03.503864+00:00'),
('4e36bc23-bffe-4329-b92c-fbf6017e8497', 120, 'Citazioni & Easter Egg', 'L''ispirazione per i mostri Elementali', 'I quattro mostri Elementali (Idro-Man, Magnum, Sandman e Molten Man) sono stati creati fondendo elementi visivi dei fumetti classici con i design dei cattivi storici di Spider-Man, e ciascuno di essi presenta nelle targhe delle auto vicine o nei dettagli numerici dei riferimenti alle loro prime apparizioni nei fumetti Marvel.', 'Artbook ufficiale ''The Art of Spider-Man: Far From Home''', TRUE, 'IA (Daily Sync)', 'IA Verificata', 0, 1, '2026-11-02T10:03:03.503864+00:00'),
('d56932d5-3cb2-4cd0-a398-80ccef3828ab', 120, 'Segreti di produzione', 'La scena tagliata dell''aeroporto di Lipsia', 'In fase di montaggio iniziale, il regista Jon Watts aveva valutato l''inclusione di un breve flashback inedito girato dal punto di vista di Peter durante la battaglia dell''aeroporto in ''Captain America: Civil War'', poi scartato per mantenere il focus sulla narrazione europea.', 'Commento audio del regista all''edizione Blu-ray', TRUE, 'IA (Daily Sync)', 'IA Verificata', 0, 2, '2026-11-02T10:03:03.503864+00:00'),
('3711c6eb-922c-4189-939b-ab8679847e66', 170, 'Aneddoti dal set', 'L''improvvisazione del sigaro da parte di Will Smith', 'La celebre sequenza in cui il capitano Steven Hiller fuma un sigaro estratto dal rottame della nave aliena nel deserto non era originariamente prevista dal copione. L''idea fu suggerita dallo stesso Will Smith sul set per enfatizzare l''atteggiamento strafottente del suo personaggio prima dell''arrivo dei soccorsi.', 'Commento audio del regista Roland Emmerich e del produttore Dean Devlin nell''edizione speciale Blu-ray', TRUE, 'IA (Daily Sync)', 'IA Verificata', 0, 0, '2026-11-02T10:16:43.476791+00:00'),
('0451626f-c9c2-404e-946c-e7b358b3f96b', 170, 'Curiosità & Retroscena', 'La censura della battuta sul fumo in India', 'Durante la fase di post-produzione, la 20th Century Fox dovette affrontare problemi con i distributori internazionali e la censura in alcune aree. In particolare, una battuta in cui viene menzionato il Taj Mahal rischiò di essere modificata per evitare polemiche locali legate alla distruzione dei monumenti storici mondiali.', 'Note di produzione ufficiali della 20th Century Fox del 1996', TRUE, 'IA (Daily Sync)', 'IA Verificata', 0, 1, '2026-11-02T10:16:43.476791+00:00'),
('3fc989a6-1eba-43d5-9b1c-d9c60624cd8e', 170, 'Casting & Scelte', 'Il taglio della scena della gravidanza di Jasmine', 'Nelle prime stesure della sceneggiatura, il personaggio di Jasmine Dubrow (interpretato da Vivica A. Fox) era incinta di diversi mesi. I realizzatori decisero di eliminare questo dettaglio e di farla lavorare come spogliarellista per rendere più dinamica la sua fuga durante la sequenza catastrofica dell''attacco alla città.', 'Documentario di Making-of ''Creating Independence Day''', TRUE, 'IA (Daily Sync)', 'IA Verificata', 0, 2, '2026-11-02T10:16:43.476791+00:00'),
('cc59c8d8-241c-40c7-ae34-1815aa50766d', 170, 'Citazioni & Easter Egg', 'Il cameo del regista nei panni di un pilota', 'Il regista Roland Emmerich appare brevemente in un cameo non accreditato nel film: è uno dei piloti della squadriglia di caccia a cui viene ordinato di effettuare il secondo attacco coordinato contro la nave madre aliena.', 'Archivio ufficiale dei crediti di produzione e interviste al regista', TRUE, 'IA (Daily Sync)', 'IA Verificata', 0, 3, '2026-11-02T10:16:43.476791+00:00'),
('f7311b03-c8c5-49e5-b837-b08011f5e74d', 170, 'Effetti speciali & Trucco', 'L''uso massiccio di modellini in miniatura al posto della CGI', 'Nonostante l''era digitale stesse iniziando, la produzione di Independence Day detiene il record per il maggior numero di miniature distrutte in un singolo lungometraggio. La squadra supervisionata da Volker Engel costruì oltre trenta edifici in scala ridotta, inclusi interi grattacieli e ponti, fatti esplodere con cariche di dinamite reali.', 'Rivista ''Cinefex'' n. 67, articolo speciale sugli effetti visivi del film', TRUE, 'IA (Daily Sync)', 'IA Verificata', 0, 4, '2026-11-02T10:16:43.476791+00:00'),
('6b6b5768-4c7b-439b-b5b8-7badb40e5f32', 241, 'Segreti di produzione', 'La causa legale per plagio da Satyajit Ray', 'Il celebre regista indiano Satyajit Ray accusò Steven Spielberg e la Universal di aver copiato la sceneggiatura del suo progetto mai realizzato intitolato ''The Alien'', scritto nel 1967 e ampiamente diffuso a Hollywood. Nonostante le evidenti somiglianze strutturali sul tema dell''amicizia tra un bambino e un extraterrestre, la causa non portò a condanne formali.', 'Archivi storici e interviste biografiche su Satyajit Ray', TRUE, 'IA (Daily Sync)', 'IA Verificata', 0, 1, '2026-11-02T10:21:19.420276+00:00'),
('41994155-8122-4081-b4b0-92cf77fc9590', 241, 'Casting & Scelte', 'Gli attori affetti da sindrome di Down nel cast', 'Per la sequenza della classe in cui Elliott libera le rane destinate alla dissezione, Steven Spielberg volle fortemente inserire alcuni studenti affetti da sindrome di Down per garantire una rappresentazione inclusiva e realistica dei coetanei del protagonista nell''America suburbana dei primi anni Ottanta.', 'Note di produzione e crediti del film', TRUE, 'IA (Daily Sync)', 'IA Verificata', 0, 2, '2026-11-02T10:21:19.420276+00:00'),
('e743914f-4783-4541-92a4-18db642d5ea9', 241, 'Aneddoti dal set', 'La controversia sul bacio non sceneggiato', 'Durante le riprese della scena in cui Elliott bacia la sua compagna di classe preferita, il giovane attore Henry Thomas fu colto del tutto di sprov sorpresa perché la battuta e l''azione non erano presenti nel copione originale fornito da Melissa Mathison, ma furono aggiunte da Spielberg all''ultimo minuto per catturare una reazione di autentico imbarazzo infantile.', 'Commento audio del regista nell''edizione Blu-Ray del 20th Anniversary', TRUE, 'IA (Daily Sync)', 'IA Verificata', 0, 3, '2026-11-02T10:21:19.420276+00:00'),
('cd983dcd-004c-4604-80ce-d637dadef8d5', 241, 'Segreti di produzione', 'Il doppiaggio in lingua russa e la censura politica', 'Durante la distribuzione dell''era sovietica, il film subì alcune modifiche nei sottotitoli e nei dialoghi adattati per evitare che il pubblico dell''Unione Sovietica percepisse eccessivi parallelismi ideologici o culturali con lo stile di vita capitalista americano ritratto nella pellicola di Spielberg.', 'Saggi di storia del cinema sui media nella Guerra Fredda', TRUE, 'IA (Daily Sync)', 'IA Verificata', 0, 4, '2026-11-02T10:21:19.420276+00:00'),
('eb764ee5-de69-4a58-b977-14cbc1954b7c', 295, 'Segreti di produzione', 'La sceneggiatura originale completamente riscritta', 'Nella prima versione della trama scritta da Lee Unkrich e Adrian Molina, la storia ruotava attorno a un ragazzino che doveva imparare a superare il lutto per la madre defunta e ''lasciarla andare''. Durante i colloqui con i consulenti culturali messicani, il team comprese che questo approccio contraddiceva l''essenza stessa del Día de los Muertos, che celebra invece il ricordo eterno e la riconnessione con i defunti; Unkrich decise quindi di azzerare la sceneggiatura per riscriverla dalle fondamenta.', 'Commento audio del regista Lee Unkrich nel Blu-ray ufficiale Pixar', TRUE, 'IA (Daily Sync)', 'IA Verificata', 0, 1, '2026-11-02T11:30:47.876357+00:00'),
('5fe97e07-bd22-44e6-8402-030e91b6de04', 295, 'Effetti speciali & Trucco', 'La foley art per i suoni della lingua di Dante', 'Il sound designer Christopher Boyes ha affrontato una sfida bizzarra per dare un''identità sonora alla lingua costantemente ciondolante e iperattiva del cane Dante. Per ottenere il caratteristico rumore umido, elastico e viscido, Boyes e il suo team hanno acquistato bistecche crude di fianchetto di manzo (''flank steak'') sbattendole ripetutamente su un tavolo di plastica davanti ai microfoni.', 'Featurette ''The Music and Sound of Coco'' nei contenuti speciali del Blu-ray', TRUE, 'IA (Daily Sync)', 'IA Verificata', 0, 2, '2026-11-02T11:30:47.876357+00:00'),
('1e934a9e-b53f-4156-9c04-23cd27c84da3', 123, 'Casting & Scelte', 'La sostituzione dell''Oracolo dopo la scomparsa di Gloria Foster', 'A causa della scomparsa dell''attrice Gloria Foster prima dell''inizio delle riprese di ''Matrix Revolutions'', la produzione dovette ingaggiare l''attrice Mary Alice per ereditare l''iconico ruolo dell''Oracolo, modificando opportunamente la sceneggiatura per giustificare la nuova fisionomia attraverso la transizione dei programmi in-universe.', 'Note di produzione ufficiali e documentario ''The Matrix Reloaded Revisited''', TRUE, 'IA (Daily Sync)', 'IA Verificata', 0, 0, '2026-11-02T10:03:48.502162+00:00'),
('6e715aa2-137a-4b36-8759-e2e1ae8708d2', 123, 'Aneddoti dal set', 'L''infortunio alla spalla di Laurence Fishburne', 'Durante le riprese della complessa sequenza del combattimento sul rimorchio del camion nell''autostrada, l''attore Laurence Fishburne subì una dolorosa lussazione alla spalla che richiese una breve pausa medica prima di poter completare le scene d''azione.', 'Audio commento del cast e della troupe nell''edizione home video', TRUE, 'IA (Daily Sync)', 'IA Verificata', 0, 1, '2026-11-02T10:03:48.502162+00:00'),
('5af7c743-53f6-49ee-ac97-ee4687c2d4dc', 123, 'Citazioni & Easter Egg', 'Il cameo dei fratelli Wachowski digitalizzati', 'I registi Lana e Lilly Wachowski fecero inserire i propri volti digitali all''interno della folla di cloni dell''Agente Smith durante la sequenza del Burly Brawl, sebbene i modelli tridimensionali siano quasi impossibili da distinguere a occhio nudo nella confusione della scena.', 'Speciali sui VFX nel cofanetto DVD The Ultimate Matrix Collection', TRUE, 'IA (Daily Sync)', 'IA Verificata', 0, 2, '2026-11-02T10:03:48.502162+00:00'),
('b83946db-0851-4ebb-8a5d-c155ac0716e2', 123, 'Effetti speciali & Trucco', 'L''uso estensivo di miniature e plastici per l''Helipad', 'La spettacolare sequenza d''azione sul tetto del grattacielo culminata con l''esplosione dell''elicottero non fu interamente realizzata in computer grafica: la produzione costruì una gigantesca miniatura dettagliata del palazzo e del velivolo negli studi di Alameda in California.', 'Making-of ufficiale ''I soliti sospetti: la costruzione degli effetti visivi''', TRUE, 'IA (Daily Sync)', 'IA Verificata', 0, 3, '2026-11-02T10:03:48.502162+00:00'),
('ab96d3e3-c243-412b-8854-6511c75c6332', 125, 'Segreti di produzione', 'L''assenza di Lilly Wachowski e la svolta creativa', 'A differenza della trilogia originale, co-diretta e co-scritta insieme alla sorella Lilly, Lana Wachowski ha scritto e diretto ''Matrix Resurrections'' da sola. Lilly ha scelto di non partecipare al progetto poiché era impegnata nella produzione della serie televisiva ''Work in Progress'' e sentiva il bisogno di allontanarsi dal franchise.', 'Dichiarazioni ufficiali di Lilly Wachowski al Television Critics Association panel', TRUE, 'IA (Daily Sync)', 'IA Verificata', 0, 0, '2026-11-02T10:04:08.47884+00:00'),
('485c5c70-1528-49e2-9b7f-cd6c4e95f0b1', 125, 'Aneddoti dal set', 'Il cameo della nipotina e della famiglia', 'Lana Wachowski ama coinvolgere la propria famiglia nei suoi film. In ''Matrix Resurrections'', la regista ha inserito un piccolo cameo per sua nipote e altri membri della famiglia nella scena della caffetteria in cui Thomas Anderson incontra Tiffany/Trinity.', 'Note di produzione ufficiali Warner Bros.', TRUE, 'IA (Daily Sync)', 'IA Verificata', 0, 1, '2026-11-02T10:04:08.47884+00:00'),
('080be6de-49ae-4a2d-8d11-2f4ce71c4ef8', 125, 'Citazioni & Easter Egg', 'Il tributo ai Wachowski nel nome di Bugs', 'Il personaggio di Bugs, interpretato da Jessica Henwick, prende il nome dal celebre personaggio dei cartoon Bugs Bunny, ma nel contesto del film rappresenta anche un omaggio ai fan storici e ai detective della rete che hanno decodificato i segreti della saga nel corso degli anni.', 'Intervista a Jessica Henwick per Entertainment Weekly', TRUE, 'IA (Daily Sync)', 'IA Verificata', 0, 2, '2026-11-02T10:04:08.47884+00:00'),
('01bee38d-6380-4891-a4aa-7bad904af308', 163, 'Curiosità & Retroscena', 'La genesi visiva ispirata da un vero e proprio disastro ecologico', 'Il regista Georgis Grigorakis ha ideato la premessa del film dopo aver letto e documentato le reali proteste della comunità locale di Skouries, nella penisola di Calcidica, contro l''apertura di una grande miniera d''oro che ha diviso gli abitanti della regione.', 'Note di regia ufficiali e intervista su Cineuropa', TRUE, 'IA (Daily Sync)', 'IA Verificata', 0, 0, '2026-11-02T10:10:04.620144+00:00'),
('1ba755b7-9205-4f9b-8dff-fb56be558d03', 163, 'Curiosità & Retroscena', 'Il premio speciale a Sarajevo e il debutto internazionale', 'Prima del plauso al Thessaloniki International Film Festival, ''Digger'' ha iniziato il suo percorso di successo vincendo il CICAE Award alla 26esima edizione del Sarajevo Film Festival nel 2020.', 'Palmarès ufficiale del Sarajevo Film Festival 2020', TRUE, 'IA (Daily Sync)', 'IA Verificata', 0, 1, '2026-11-02T10:10:04.620144+00:00'),
('177deff5-3845-4fdb-aa7f-5931b05bfa06', 163, 'Segreti di produzione', 'La scelta della location nel monte Parnete', 'Le riprese principali si sono svolte nel Parco Nazionale del Monte Parnete (Parnitha), nei pressi di Atene, un''area gravemente colpita da incendi boschivi devastanti negli anni precedenti, offrendo così una scenografia naturale drammaticamente reale per il tema dell''ecologia.', 'Dichiarazioni della produzione Pan Entertainment', TRUE, 'IA (Daily Sync)', 'IA Verificata', 0, 2, '2026-11-02T10:10:04.620144+00:00'),
('7b9bf10e-c822-4692-a3a9-ccb7e3e98ac0', 184, 'Aneddoti dal set', 'Il malore sul set di Martin Freeman', 'Durante le lunghe e faticose riprese delle sequenze di combattimento nei pressi di Erebor, l''attore protagonista Martin Freeman ha temporaneamente perso i sensi a causa del caldo soffocante intrappolato all''interno delle pesanti armature e dei costumi di scena.', 'Intervista ufficiale di Martin Freeman nel press junket del film', TRUE, 'IA (Daily Sync)', 'IA Verificata', 0, 0, '2026-11-02T10:10:19.882979+00:00'),
('0aab7c47-2512-40a1-8fd8-4c7592b81203', 184, 'Aneddoti dal set', 'L''infortunio alla costola di Orlando Bloom', 'Orlando Bloom, riprendendo il ruolo di Legolas, si è fratturato una costola durante le prove di una complessa sequenza acrobatica, cadendo accidentalmente da uno dei cavalli meccanici utilizzati per le scene di carica degli elfi.', 'Dichiarazione ufficiale della produzione e diario di produzione di Peter Jackson', TRUE, 'IA (Daily Sync)', 'IA Verificata', 0, 1, '2026-11-02T10:10:19.882979+00:00'),
('7dde9735-4ded-4ab4-b2ab-3e7297aa2733', 184, 'Segreti di produzione', 'La colonna sonora dei ritmi di battaglia di Howard Shore', 'Il compositore Howard Shore ha integrato nella partitura della battaglia finale temi musicali specifici tratti direttamente dai leitmotiv di Arnor e Angmar composti per la trilogia de Il Signore degli Anelli, per sottolineare la continuità storica della Terra di Mezzo.', 'Note di copertina dell''edizione speciale della colonna sonora originale', TRUE, 'IA (Daily Sync)', 'IA Verificata', 0, 2, '2026-11-02T10:10:19.882979+00:00'),
('02298777-0a50-47bd-a77a-2355360cb8b1', 174, 'Aneddoti dal set', 'L''infortunio sul set di Alessandro Borghi', 'Durante una delle intense sequenze di lotta nel fango, l''attore protagonista Alessandro Borghi ha riportato la frattura di un dito della mano, decidendo tuttavia di non interrompere le riprese per non alterare il fitto piano di lavorazione nelle foreste laziali.', 'Intervista promozionale concessa da Alessandro Borghi per il lancio del film', TRUE, 'IA (Daily Sync)', 'IA Verificata', 0, 1, '2026-11-02T10:16:49.520645+00:00'),
('2b453bbb-b9e7-4e98-a196-a94cb28cc4be', 174, 'Segreti di produzione', 'L''uso di armi in ferro battuto a mano', 'Gli oggetti di scena e le armi brandite dai pastori e dai guerrieri non sono repliche industriali in plastica o gomma piuma, ma sono state interamente forgiate a mano da maestri artigiani utilizzando tecniche siderurgiche dell''Età del Ferro per garantire un peso e un bilanciamento realistici.', 'Featurette ''Il making of: le armi e i metalli'' presente nei contenuti extra dell''edizione home video', TRUE, 'IA (Daily Sync)', 'IA Verificata', 0, 2, '2026-11-02T10:16:49.520645+00:00'),
('0f55590e-be09-45d9-8908-2f2a8b5f67f2', 124, 'Curiosità & Retroscena', 'La colonna sonora con il brano di targa gotica e corale', 'Il compositore Don Davis, in stretta collaborazione con Ben Watkins degli Juno Reactor, ha integrato nella colonna sonora di ''Matrix Revolutions'' imponenti cori in lingua sanscrita tratti dalle Upanishad, in particolare nel brano ''Navras'', unendo orchestrazioni sinfoniche tradizionali e musica elettronica Goa trance.', 'Note di copertina dell''album della colonna sonora ufficiale', TRUE, 'IA (Daily Sync)', 'IA Verificata', 0, 3, '2026-11-02T10:04:00.957795+00:00'),
('c6c0ed79-16d2-4c21-a428-350207df8285', 164, 'Curiosità & Retroscena', 'La controversia sulla scena della chiesa', 'La sequenza in cui i soldati britannici chiudono gli abitanti del villaggio in una chiesa e la danno alle fiamme ha scatenato aspre polemiche storiche, venendo paragonata dai critici britannici al famigerato massacro di Oradour-sur-Glane commesso dalle SS naziste nel 1944, ritenuto dagli storici un falso storico inaccettabile se applicato all''esercito britannico del XVIII secolo.', 'The Guardian / Recensioni storiche e note di produzione', TRUE, 'IA (Daily Sync)', 'IA Verificata', 0, 0, '2026-11-02T10:10:12.768715+00:00'),
('398505a5-25b4-4b01-a0ad-9c6072d3a000', 164, 'Casting & Scelte', 'L''ispirazione reale per il personaggio di Benjamin Martin', 'Lo sceneggiatore Robert Rodat ha modellato il personaggio di Benjamin Martin fondendo le caratteristiche di diversi reali eroi della Guerra d''indipendenza americana, tra cui Francis Marion (noto come la ''Volpe della Carolina''), Andrew Pickens, Thomas Sumter e Daniel Morgan.', 'Note di produzione ufficiali della Columbia Pictures', TRUE, 'IA (Daily Sync)', 'IA Verificata', 0, 1, '2026-11-02T10:10:12.768715+00:00'),
('66b02018-931f-4f28-960c-4ac4e3eb4732', 164, 'Segreti di produzione', 'Il rifiuto iniziale del regista Roland Emmerich', 'Inizialmente Roland Emmerich rifiutò di dirigere il film perché lo considerava un tradizionale film di guerra in costume, distante dai suoi soliti blockbuster d''azione e sci-fi come Independence Day e Godzilla. Accettò solo dopo aver letto una riscrittura della sceneggiatura che approfondiva il dramma familiare e la brutalità del conflitto.', 'Intervista a Roland Emmerich per il making-of del DVD', TRUE, 'IA (Daily Sync)', 'IA Verificata', 0, 2, '2026-11-02T10:10:12.768715+00:00'),
('46a0c9aa-5d53-4ae1-be78-f0ddaf4a6f83', 176, 'Segreti di produzione', 'La consulenza di un vero ex agente del Prohibition Bureau', 'Per garantire la massima accuratezza storica nelle procedure investigative e nell''uso delle armi d''epoca, la produzione ingaggiò come consulente tecnico un anziano ex agente che aveva realmente servito nel Federal Prohibition Bureau durante gli anni Trenta sotto la guida di Eliot Ness.', 'Note di produzione ufficiali Paramount Pictures', TRUE, 'IA (Daily Sync)', 'IA Verificata', 0, 0, '2026-11-02T10:16:57.441466+00:00'),
('f28c4b73-3720-4d08-90e9-2883d34b0502', 176, 'Effetti speciali & Trucco', 'La cicatrice di Al Capone e il trucco protesico', 'Il leggendario truccatore Dick Smith collaborò strettamente con Robert De Niro per ricreare fedelmente le cicatrici sul volto di Al Capone, utilizzando protesi in lattice altamente avanzate per l''epoca che richiedevano oltre tre ore di applicazione quotidiana prima di iniziare le riprese.', 'Intervista a Dick Smith per Cinefex Magazine', TRUE, 'IA (Daily Sync)', 'IA Verificata', 0, 1, '2026-11-02T10:16:57.441466+00:00'),
('01c57544-004d-47e8-b4a9-c8b47aa2fc50', 176, 'Curiosità & Retroscena', 'Il rifiuto iniziale di Ennio Morricone', 'Il celebre compositore Ennio Morricone inizialmente rifiutò l''offerta di scrivere la colonna sonora del film perché impegnato in altri progetti; fu grazie alla determinazione del produttore Art Linson, che volò personalmente a Roma per convincerlo, che il maestro accettò di comporre le musiche vincitrici del Nastro d''Argento.', 'Documentario ''The Men Who Made the Movie: Brian De Palma''', TRUE, 'IA (Daily Sync)', 'IA Verificata', 0, 2, '2026-11-02T10:16:57.441466+00:00'),
('f91b50ae-a27b-4dfe-a599-167bd6e7be46', 176, 'Aneddoti dal set', 'Le vere armi Thompson calibro .45', 'Durante le scene di sparatoria, gli attori non usarono semplici repliche sceniche ma veri mitra Thompson (i famosi ''Chicago Typewriter'') convertiti appositamente per sparare a salve munizioni speciali, sotto la stretta supervisione di esperti d''armi e artificieri dell''esercito.', 'Special TV ''The Making of The Untouchables''', TRUE, 'IA (Daily Sync)', 'IA Verificata', 0, 3, '2026-11-02T10:16:57.441466+00:00'),
('1057b7fd-fa15-43ee-bdf9-9293ac2cfb34', 179, 'Effetti speciali & Trucco', 'La controversia sindacale per il costume di Rick Baker', 'Rick Baker, che aveva progettato e indossato il costume di Kong per gran parte delle sequenze in cui l''animatronico non funzionava, ebbe forti frizioni con i sindacati di Hollywood. La Screen Actors Guild protestò perché Baker non era membro del sindacato degli attori, costringendo la produzione a regolarizzare la sua posizione affinché potesse essere accreditato e continuare le riprese.', 'Documentario ''The Making of King Kong'' e biografie di produzione', TRUE, 'IA (Daily Sync)', 'IA Verificata', 0, 0, '2026-11-02T10:17:12.799717+00:00'),
('4d1c1bbc-3c3b-4582-9e6c-7d86965208dc', 179, 'Segreti di produzione', 'Il compenso record per gli effetti speciali a Carlo Rambaldi', 'Il leggendario maestro degli effetti speciali Carlo Rambaldi fu insignito di un Oscar speciale per gli effetti visivi di questo film, principalmente grazie al suo sistema idraulico avanzato applicato alla testa e al volto del gorilla robotico. Per la realizzazione del gigantesco automa, che costò oltre un milione e mezzo di dollari dell''epoca, Rambaldi lavorò fianco a fianco con Glen Robinson.', 'Archivio ufficiale Academy Awards e note di produzione Paramount', TRUE, 'IA (Daily Sync)', 'IA Verificata', 0, 1, '2026-11-02T10:17:12.799717+00:00');
INSERT INTO public.movie_trivia ("id", "film_id", "categoria", "titolo", "descrizione", "fonte", "approvato", "inserito_da", "provenienza", "likes", "ordine", "created_at") VALUES
('81067781-6b3d-4f7e-8bb5-534f19da4851', 179, 'Casting & Scelte', 'Il rifiuto di Roman Polanski alla regia', 'Prima che John Guillermin venisse ingaggiato per dirigere il kolossal, il produttore Dino De Laurentiis aveva offerto la sedia di regia a Roman Polanski. Il celebre regista europeo declinò l''offerta, permettendo poi a Guillermin di prendere in mano il progetto e gestire la complessa e travagliata produzione tra Los Angeles e New York.', 'Annali di produzione cinematografica degli anni ''70 e biografie di Dino De Laurentiis', TRUE, 'IA (Daily Sync)', 'IA Verificata', 0, 2, '2026-11-02T10:17:12.799717+00:00'),
('1b812f8f-77cb-4ef5-9301-df95473c5853', 108, 'Casting & Scelte', 'La prima collaborazione tra Hathaway e McGregor', 'Anne Hathaway è entrata nel progetto nel marzo 2023, quando la Warner Bros. e Bad Robot hanno acquisito la sceneggiatura originale di David Robert Mitchell. Nel febbraio 2024, Ewan McGregor è stato ingaggiato per affiancarla nel ruolo del co-protagonista, segnando la prima collaborazione sul grande schermo tra i due interpreti.', 'The Hollywood Reporter', TRUE, 'IA (Admin)', 'IA Verificata', 3, 1, '2026-11-02T18:13:56.94748+00:00'),
('f03dca40-2616-4e78-8836-7f61e97d0731', 181, 'Casting & Scelte', 'La scelta di Richard Boone per il drago Smaug', 'Il celebre attore western Richard Boone fu ingaggiato per doppiare il temibile drago Smaug, conferendo al personaggio un timbro vocale profondo, minaccioso e autoritario che dominava le scene finali.', 'Crediti ufficiali e note di produzione Rankin/Bass', TRUE, 'IA (Daily Sync)', 'IA Verificata', 0, 0, '2026-11-02T10:17:26.301199+00:00'),
('b154f23a-b100-48ea-81a4-eadd37b1e2d0', 339, 'Curiosità & Retroscena', 'Il gatto sulla spalla di Bill the Butcher', 'Il gatto bianco che appare frequentemente appoggiato sulle spalle di Billy the Butcher non era programmato nel copione: l''animale apparteneva alla troupe e si attaccò a Daniel Day-Lewis durante le prove, convincendo Scorsese a includerlo nel film.', 'Commento audio del regista nel DVD ufficiale', TRUE, 'IA (Daily Sync)', 'IA Verificata', 0, 6, '2026-11-02T14:51:13.447724+00:00'),
('70725e44-7dac-4e10-9d33-427314cda324', 339, 'Effetti speciali & Trucco', 'L''ispirazione per l''occhio vitreo di Billy', 'Il caratteristico occhio vitreo e cieco di Billy the Butcher fu realizzato applicando una speciale lente a contatto opaca, la cui gestione richiedeva particolari precauzioni mediche quotidiane per non danneggiare la vista di Daniel Day-Lewis.', 'Intervista al reparto trucco e prostetica sul set', TRUE, 'IA (Daily Sync)', 'IA Verificata', 0, 7, '2026-11-02T14:51:13.447724+00:00'),
('e45ce700-49e4-4f5d-897f-ea947ac436d8', 126, 'Aneddoti dal set', 'Il quasi avvelenamento accidentale di Eli Wallach', 'Durante le riprese, Eli Wallach rischiò seriamente di morire per aver bevuto accidentalmente acido anziché la normale mistura di latte e soda. Una troupe tecnica aveva lasciato una bottiglia di acido per pulire i sostegni di scena vicino al set e Wallach, non accorgendosene, la scambiò per una bevanda.', 'Autobiografia di Eli Wallach ''The Good, the Bad and Me''', TRUE, 'IA (Daily Sync)', 'IA Verificata', 0, 0, '2026-11-02T10:04:16.335004+00:00'),
('2581635d-fec0-4c09-b8fb-8964789f9118', 126, 'Aneddoti dal set', 'La ferita quasi mortale con la pistola per Wallach', 'In un''altra occasione pericolosa, la scena in cui Tuco viene trasportato su un carro ferroviario con le mani legate dietro la schiena rischiò di decapitarlo. La catena che teneva legate le sue mani fu spezzata da un colpo di pistola sparato da un attore, ma il proiettile passò a pochi centimetri dal suo collo, scheggiando il legno della traversa e lasciando l''attore profondamente traumatizzato.', 'Intervista d''archivio a Eli Wallach per documentari storici', TRUE, 'IA (Daily Sync)', 'IA Verificata', 0, 1, '2026-11-02T10:04:16.335004+00:00'),
('bc715795-d504-4569-a3ab-c0ac2ad50c0d', 126, 'Casting & Scelte', 'La scelta di Mario Brega come sergente dell''Unione', 'Il celebre attore e caratterista romano Mario Brega, che interpreta il brutale caporale nordista che sevizia Tuco nel campo di prigionia, fu fortemente voluto da Sergio Leone. Brega, ex pugile e collaboratore storico del regista, improvvisò parte della sua aggressività fisica sul set, terrorizzando realmente Eli Wallach durante le riprese delle torture.', 'Note di produzione e biografie di Sergio Leone', TRUE, 'IA (Daily Sync)', 'IA Verificata', 0, 2, '2026-11-02T10:04:16.335004+00:00'),
('4ca93f4d-7dac-4a85-a873-612761cd36da', 126, 'Segreti di produzione', 'La finta tomba nel cimitero di Sad Hill', 'Il monumentale cimitero circolare di Sad Hill fu costruito ex novo dalla troupe di Sergio Leone e dall''esercito spagnolo in una valle nei pressi di Burgos, lontano da Almería. Furono realizzate oltre cinquemila tombe di legno, e oggi quel sito è stato completamente restaurato da fan e archeologi cinematografici spagnoli che hanno riportato alla luce il set originale.', 'Documentario ''Sad Hill Unearthed'' (2017)', TRUE, 'IA (Daily Sync)', 'IA Verificata', 0, 3, '2026-11-02T10:04:16.335004+00:00'),
('4821e1ef-5331-49cb-bd9b-5addfe3e888e', 178, 'Aneddoti dal set', 'La paura reale di Bruce Cabot per il braccio meccanico', 'Durante le riprese della scena in cui Kong afferra Ann Darrow e si arrampica, l''attore Bruce Cabot dovette interagire con un enorme braccio meccanico in legno e gommapiuma manovrato da cavi d''acciaio. Cabot dichiarò in seguito che la sua espressione di terrore sul set era assolutamente autentica, poiché il macchinario pesante rischiava costantemente di colpirlo o ferire la troupe.', 'Documentario ''The Making of King Kong'' (1983)', TRUE, 'IA (Daily Sync)', 'IA Verificata', 0, 0, '2026-11-02T10:17:05.199798+00:00'),
('80b9d7a0-aa65-47a5-9a67-8db7424cd4ac', 178, 'Effetti speciali & Trucco', 'La voce originale dei nativi di Skull Island', 'Per registrare gli inquietanti canti e le urla dei nativi di Skull Island, la produzione non assunse attori indigeni, ma reclutò un gruppo di attori teatrali e doppiatori di Hollywood a cui fu chiesto di urlare e pronunciare parole inventate rovesciando registrazioni di dialoghi in lingua inglese e russa per creare un effetto fonetico alieno.', 'Archivi storici della RKO Radio Pictures', TRUE, 'IA (Daily Sync)', 'IA Verificata', 0, 1, '2026-11-02T10:17:05.199798+00:00'),
('acd52e59-530c-4ee5-b141-7590216f7681', 178, 'Segreti di produzione', 'Il taglio della sequenza del ragno gigante', 'Willis O''Brien realizzò una complessa sequenza in stop-motion in cui alcuni marinai precipitavano in un burrone e venivano divorati da enormi insetti e ragni giganti. Merian C. Cooper decise di tagliare la scena dalla versione finale perché il pubblico delle proiezioni di prova a San Diego era rimasto talmente scioccato e terrorizzato da abbandonare la sala urlando.', 'Note di produzione e sceneggiatura originale di King Kong', TRUE, 'IA (Daily Sync)', 'IA Verificata', 0, 2, '2026-11-02T10:17:05.199798+00:00'),
('ba428a7d-e44c-4ad9-b756-c9b1c96e0e2e', 178, 'Citazioni & Easter Egg', 'L''aereo pilotato dai registi', 'I due registi Merian C. Cooper ed Ernest B. Schoedsack vollero pilotare personalmente i due biplani dell''esercito nella sequenza finale all''Empire State Building, assumendosi il rischio di manovrare i velivoli a bassa quota attorno al grattacielo per ottenere un realismo visivo impossibile con i modelli in miniatura.', 'Autobiografia di Merian C. Cooper', TRUE, 'IA (Daily Sync)', 'IA Verificata', 0, 3, '2026-11-02T10:17:05.199798+00:00'),
('ddd83881-1be5-46c9-87d8-39fe497fce3f', 178, 'Casting & Scelte', 'La collaborazione iniziale con Edgar Wallace', 'Prima dell''inizio delle riprese, Merian C. Cooper ingaggiò il celebre scrittore britannico di gialli Edgar Wallace per scrivere il soggetto e la prima stesura del romanzo e della sceneggiatura. Wallace fece in tempo a completare una prima bozza della storia prima di morire improvvisamente a Los Angeles nel febbraio del 1932.', 'Registri storici e contratti della RKO', TRUE, 'IA (Daily Sync)', 'IA Verificata', 0, 4, '2026-11-02T10:17:05.199798+00:00'),
('3b24e6c5-b4cd-4d4a-a284-16abecc101ab', 182, 'Aneddoti dal set', 'La polmonite contratta da James Nesbitt durante le riprese', 'L''attore James Nesbitt, che interpreta il nano Bofur, ha contratto una grave forma di polmonite durante le riprese in Nuova Zelanda a causa delle lunghe ore passate sotto la pioggia artificiale e nelle fredde location naturali. Nonostante la malattia, la produzione ha dovuto riorganizzare temporaneamente il piano di lavorazione per permettergli di guarire senza accumulare ritardi eccessivi.', 'Intervista ufficiale dal diario di produzione di Peter Jackson', TRUE, 'IA (Daily Sync)', 'IA Verificata', 0, 0, '2026-11-02T10:17:33.652334+00:00'),
('e2ebd3f5-0bbd-48f3-9623-ec712e2ce940', 182, 'Segreti di produzione', 'La sostituzione last-minute del compositore Howard Shore', 'Il celebre compositore Howard Shore ha dovuto registrare la colonna sonora in tempi record a causa dei continui slittamenti del montaggio di Peter Jackson. L''Orchestra Sinfonica di Londra ha inciso oltre due ore di musica inedita in soli pochi giorni presso gli Abbey Road Studios di Londra.', 'Note di produzione ufficiali della Soundtrack e Making-of', TRUE, 'IA (Daily Sync)', 'IA Verificata', 0, 1, '2026-11-02T10:17:33.652334+00:00'),
('62e03908-7ea7-4741-9359-0ff61784db00', 182, 'Effetti speciali & Trucco', 'Le protesi nasali personalizzate per i nani', 'Il reparto trucco guidato da Peter Swords King ha creato oltre cento nasi in silicone differenti per caratterizzare i singoli membri della compagnia di Thorin. Ogni attore doveva sottoporsi a un''applicazione quotidiana della durata di circa tre ore prima di poter calcare il set.', 'Documentario ufficiale ''The Appendices'' del Blu-ray', TRUE, 'IA (Daily Sync)', 'IA Verificata', 0, 2, '2026-11-02T10:17:33.652334+00:00'),
('4259af30-98ac-4b89-b3c7-60b564c96b43', 182, 'Casting & Scelte', 'Christopher Lee e l''impossibilità di volare in Nuova Zelanda', 'Sir Christopher Lee, che riprende il ruolo di Saruman il Bianco, non ha potuto viaggiare in Nuova Zelanda a causa dell''età avanzata e dei rischi legati ai voli a lungo raggio. Tutte le sue scene sono state pertanto girate in un apposito studio a Londra, utilizzando avanzate tecniche di chroma key per integrarlo digitalmente con il resto del cast.', 'Commento audio del regista Peter Jackson nell''edizione estesa', TRUE, 'IA (Daily Sync)', 'IA Verificata', 0, 3, '2026-11-02T10:17:33.652334+00:00'),
('68bcdfd1-f495-41eb-8779-b31ce524d5b2', 258, 'Casting & Scelte', 'Il contratto capestro di Adriana Caselotti', 'Per proteggere l''unicità e la magia della voce di Biancaneve, Walt Disney fece firmare ad Adriana Caselotti un contratto blindato che le impediva severamente di lavorare in radio, sul palco o in altri film, affinché la sua voce rimanesse indissolubilmente legata solo al personaggio.', 'Archivi storici Walt Disney Studios e biografie ufficiali', TRUE, 'IA (Daily Sync)', 'IA Verificata', 0, 0, '2026-11-02T10:21:26.872638+00:00'),
('d6695e55-dfce-451c-b430-dc5e6debafd1', 126, 'Curiosità & Retroscena', 'Il vero nome del cimitero nella sceneggiatura originale', 'Nella sceneggiatura originale scritta da Luciano Vincenzoni e Agenore Incrocci, il celebre cimitero dove era nascosto l''oro non si chiamava ''Sad Hill'', bensì ''Sad Field''. Fu Sergio Leone a modificarlo foneticamente in ''Sad Hill'' per rendere il nome più cinematografico e d''impatto visivo in vista del duello finale.', 'Archivio storico della sceneggiatura di Luciano Vincenzoni', TRUE, 'IA (Daily Sync)', 'IA Verificata', 0, 4, '2026-11-02T10:04:16.335004+00:00'),
('4e30e202-bd9e-4552-87a0-bf6c634b9e65', 126, 'Aneddoti dal set', 'Le difficoltà linguistiche nel trio principale', 'Sul set regnava una torre di Babele linguistica: Sergio Leone parlava pochissimo inglese, Clint Eastwood comunicava in inglese, Lee Van Cleef capiva poco l''italiano ed Eli Wallach parlava un misto di francese, inglese e yiddish. Per girare le scene, Leone utilizzava spesso gesti teatrali ed espressioni facciali per farsi comprendere da tutti gli attori contemporaneamente.', 'Commento audio del critico Richard Schickel all''edizione DVD', TRUE, 'IA (Daily Sync)', 'IA Verificata', 0, 5, '2026-11-02T10:04:16.335004+00:00'),
('36a50879-3af5-4a56-bddd-f2f3dc17b9a9', 164, 'Casting & Scelte', 'Tom Wilkinson e il riferimento a George Washington', 'L''attore Tom Wilkinson, che interpreta il generale britannico Lord Charles Cornwallis, ha studiato a fondo i dispacci militari originali dell''epoca per conferire al suo antagonista una fredda aristocrazia, distanziandosi dai classici cattivi bidimensionali del cinema d''azione.', 'Commento audio del regista e del produttore Mark Gordon', TRUE, 'IA (Daily Sync)', 'IA Verificata', 0, 3, '2026-11-02T10:10:12.768715+00:00'),
('7d2b0476-5c02-4c8b-a4a7-b2665391f7ec', 164, 'Segreti di produzione', 'La riproduzione delle armi d''epoca', 'Il maestro d''armi Simon Atherton ha supervisionato la creazione di repliche esatte di fucili a avancarica e pistole a pietra focaia del 1776, lavorando a stretto contatto con gli armaioli per garantire che le tecniche di ricarica mostrate da Mel Gibson e dal cast fossero storicamente accurate e sincronizzate con la realtà dell''epoca.', 'Featurette sul set ''The Art of War'' nel DVD del film', TRUE, 'IA (Daily Sync)', 'IA Verificata', 0, 4, '2026-11-02T10:10:12.768715+00:00'),
('bdb750a6-b783-4677-bef0-22285a37fbb8', 180, 'Citazioni & Easter Egg', 'L''omaggio a Merian C. Cooper nell''aspetto di Jack Black', 'Il look e i baffetti sfoggiati da Jack Black nel ruolo del regista Carl Denham sono stati modellati specificamente per somigliare al co-creatore del film originale del 1933, Merian C. Cooper. Peter Jackson ha curato personalmente questo dettaglio per rendere omaggio al visionario regista della versione classica.', 'Contenuti speciali del DVD ''King Kong: The Production Diaries''', TRUE, 'IA (Daily Sync)', 'IA Verificata', 0, 0, '2026-11-02T10:17:20.784515+00:00'),
('a01db23d-e3cf-4c53-ab29-3b95c77b449e', 180, 'Citazioni & Easter Egg', 'Il cameo del regista Frank Darabont', 'Il celebre regista Frank Darabont, grande amico di Peter Jackson, appare in un breve cameo all''inizio del film nei panni di uno degli sgherri che cercano di arrestare Carl Denham mentre si imbarca sulla Venture. Darabont ha accettato la parte per poter visitare il set neozelandese.', 'Audio commento del regista e della co-sceneggiatrice Fran Walsh', TRUE, 'IA (Daily Sync)', 'IA Verificata', 0, 1, '2026-11-02T10:17:20.784515+00:00'),
('c1204d88-6434-4cfc-bfc6-1567e3dc4430', 180, 'Citazioni & Easter Egg', 'La partecipazione speciale di Rick Baker', 'Il leggendario maestro degli effetti speciali di trucco Rick Baker, che aveva curato il famigerato remake di King Kong del 1976 diretto da John Guillermin, appare in un cameo nei panni di uno dei piloti di biplano che affrontano il gorilla sull''Empire State Building alla fine della pellicola.', 'Documentario ''The Making of King Kong'' (2005)', TRUE, 'IA (Daily Sync)', 'IA Verificata', 0, 2, '2026-11-02T10:17:20.784515+00:00'),
('31c2464a-34db-4d16-9669-4df99b55a0e5', 180, 'Curiosità & Retroscena', 'L''ispirazione per il nome del piroscafo', 'La nave su cui viaggia la troupe, la SS Venture, prende il nome dalla nave omonima presente nel film originale del 1933. Peter Jackson ha voluto mantenere intatti molti nomi di battesimo e riferimenti geografici della sceneggiatura originale di James Ashmore Creelman e Ruth Rose.', 'Note di produzione ufficiali della Universal Pictures', TRUE, 'IA (Daily Sync)', 'IA Verificata', 0, 3, '2026-11-02T10:17:20.784515+00:00'),
('6faff526-ea62-4414-839a-4244497b1db4', 180, 'Segreti di produzione', 'La ricostruzione digitale del teatro di posa', 'Poiché i teatri di posa originali della RKO in cui fu girato il film del 1933 non esistevano più, la troupe della Weta Digital ha dovuto ricostruire interamente in CGI gli studi cinematografici d''epoca in cui Carl Denham assembla la sua troupe prima della partenza.', 'Articolo tecnico su American Cinematographer (Dicembre 2005)', TRUE, 'IA (Daily Sync)', 'IA Verificata', 0, 4, '2026-11-02T10:17:20.784515+00:00'),
('1b0282fc-ed37-44e5-903a-cd4a37b78859', 180, 'Effetti speciali & Trucco', 'Il tributo ai dinosauri originali della stop-motion', 'Le sequenze di lotta tra Kong e i Vastatosaurus rex sull''Isola del Teschio contengono numerosi omaggi alle movenze e alle inquadrature dei dinosauri creati da Willis O''Brien nel film del 1933, convertite digitalmente dalla Weta Digital con tecniche di motion capture e animazione chiave.', 'Weta Digital: The Making of Kong (Libro ufficiale)', TRUE, 'IA (Daily Sync)', 'IA Verificata', 0, 5, '2026-11-02T10:17:20.784515+00:00'),
('89dc188f-ba98-457b-a0b6-e6486801c348', 258, 'Segreti di produzione', 'La colonna sonora come primo disco commerciale', 'La colonna sonora di ''Biancaneve e i sette nani'' è passata alla storia discografica perché fu la prima volta che un''etichetta pubblicò un album basato sulle musiche di un film, dando di fatto vita al concetto moderno di colonna sonora cinematografica commercializzata.', 'Note di produzione e storia della Victor Records', TRUE, 'IA (Daily Sync)', 'IA Verificata', 0, 1, '2026-11-02T10:21:26.872638+00:00'),
('8e455f45-985c-4f67-96f0-ef256a005c2e', 258, 'Aneddoti dal set', 'Il modello in carne e ossa per i movimenti di Biancaneve', 'La giovane ballerina Marjorie Belcher fu assunta dagli studi Disney come modella in carne e ossa; gli animatori ripresero in live-action i suoi movimenti per studiare la camminata, la postura e le interazioni di Biancaneve con gli oggetti della casa dei nani.', 'Documentario ''The Making of Snow White'' e registri degli animatori', TRUE, 'IA (Daily Sync)', 'IA Verificata', 0, 2, '2026-11-02T10:21:26.872638+00:00'),
('b2fab7b7-22a5-40e1-a1a3-09b21ffb8c5d', 295, 'Effetti speciali & Trucco', 'Oltre sette milioni di luci e la sfida di RenderMan', 'La tentacolare metropoli verticale della Terra dei Morti conteneva oltre sette milioni di sorgenti luminose individuali tra lampioni, finestre e fuochi. Per evitare che i tempi di rendering esplodessero mandando in crash i computer, gli ingegneri Pixar hanno sviluppato un''innovazione per il motore RenderMan che raggruppava geometricamente le luci distanti in un unico calcolo senza sacrificare la profondità visiva.', 'Presentazione tecnica Pixar al SIGGRAPH 2018', TRUE, 'IA (Daily Sync)', 'IA Verificata', 0, 3, '2026-11-02T11:30:47.876357+00:00'),
('b0a4a37b-3d6a-4cc0-977b-200a455dc87e', 295, 'Citazioni & Easter Egg', 'Omaggio alle leggende dell''Epoca d''Oro del cinema messicano', 'Ernesto de la Cruz è stato concepito come un ibrido tra i celebri cantanti e divi messicani Pedro Infante e Jorge Negrete. Come tributo esplicito alla cosiddetta ''Época de Oro'', durante la festa esclusiva di De la Cruz appaiono tra gli invitati scheletrici le versioni animate di Infante e Negrete, oltre a Cantinflas, María Félix e il leggendario lottatore mascherato El Santo.', 'Note di produzione ufficiali Pixar / Art of Coco', TRUE, 'IA (Daily Sync)', 'IA Verificata', 0, 4, '2026-11-02T11:30:47.876357+00:00'),
('a16ba0f1-4043-4e89-be09-3631aa452cfc', 108, 'Segreti di produzione', 'L''adozione del grande formato IMAX', 'Il film rappresenta la prima opera di David Robert Mitchell girata nativamente con cineprese e tecnologia IMAX. La decisione tecnica è stata concordata con la casa di produzione Bad Robot per massimizzare il contrasto tra l''apparente normalità dell''ambientazione suburbana e l''incombente senso di claustrofobia e minaccia.', 'Variety', TRUE, 'IA (Admin)', 'IA Verificata', 3, 2, '2026-11-02T18:13:56.94748+00:00'),
('75f0ac61-3daa-412f-b0bc-41b4d2e9763f', 127, 'Casting & Scelte', 'Il rifiuto iniziale di Henry Fonda', 'Quando Sergio Leone volò a New York per offrire a Henry Fonda il ruolo del villain Frank, l''attore inizialmente rifiutò l''offerta. Fu solo grazie ai consigli dell''amico Eli Wallach (protagonista de Il buono, il brutto, il cattivo) e del produttore Don Murray che Fonda riconsiderò la parte, accettando di leggere il copione.', 'Autobiografia di Eli Wallach e documentari d''archivio Paramount', TRUE, 'IA (Daily Sync)', 'IA Verificata', 0, 0, '2026-11-02T10:04:23.953646+00:00'),
('3fdacf51-ea8f-4736-af23-2f627422fc2a', 127, 'Effetti speciali & Trucco', 'La cicatrice e il trucco di Charles Bronson', 'Per enfatizzare l''aspetto vissuto e pericoloso dell''Uomo dall''Armonica, i truccatori applicarono sul viso di Charles Bronson protesi sottili e cicatrici fittizie. L''attore passava oltre un''ora ogni mattina nel camper del trucco prima di iniziare le riprese nel deserto spagnolo.', 'Note di produzione e reparti trucco Cinecittà', TRUE, 'IA (Daily Sync)', 'IA Verificata', 0, 1, '2026-11-02T10:04:23.953646+00:00'),
('91f61b6e-66ec-45de-964f-133b3ffc4b12', 127, 'Curiosità & Retroscena', 'L''ispirazione per il personaggio di Cheyenne', 'Il personaggio del fuorilegge Cheyenne, interpretato da Jason Robards, fu scritto da Sergio Leone, Bernardo Bertolucci e Dario Argento pensando ai vecchi banditi romantici del cinema muto. Robards fu scelto dopo che Leone vide la sua interpretazione in La sparatoria (The Shooting) di Monte Hellman.', 'Interviste d''archivio a Sergio Leone e sceneggiatori', TRUE, 'IA (Daily Sync)', 'IA Verificata', 0, 2, '2026-11-02T10:04:23.953646+00:00'),
('58315fb6-a7f3-46b4-b87f-08c2b1b41fe7', 127, 'Casting & Scelte', 'Il cameo tagliato di Woody Strode', 'L''attore afroamericano Woody Strode, celebre per I professionisti e Sentieri di gloria, appare nella memorabile sequenza iniziale alla stazione ferroviaria nei panni di uno dei tre pistoleri ad attendere l''arrivo del treno. La sua presenza fu fortemente voluta da Leone come omaggio ai western classici di John Ford.', 'Dichiarazioni di Woody Strode nelle memorie cinematografiche', TRUE, 'IA (Daily Sync)', 'IA Verificata', 0, 3, '2026-11-02T10:04:23.953646+00:00'),
('632d7612-a594-457c-8108-7496e6dbde59', 127, 'Segreti di produzione', 'Le musiche composte prima delle riprese', 'Ennio Morricone compose gran parte della colonna sonora prima ancora che il primo ciak venisse battuto, basandosi unicamente sul trattamento della sceneggiatura. Questo permise a Leone di montare e girare alcune sequenze chiave seguendo esattamente il ritmo e la durata dei brani musicali.', 'Libretto del CD della colonna sonora originale e interviste a Ennio Morricone', TRUE, 'IA (Daily Sync)', 'IA Verificata', 0, 4, '2026-11-02T10:04:23.953646+00:00'),
('5f652604-8a62-4162-980d-1e7cc96d3305', 127, 'Aneddoti dal set', 'I problemi di salute di Jason Robards sul set', 'Durante la lavorazione in Spagna, Jason Robards dovette affrontare problemi di salute legati al clima torrido e alla polvere del deserto di Almería. Nonostante i momenti di forte stanchezza, l''attore portò a termine tutte le sue scene senza mai ricorrere a controfigure per i campi medi.', 'Reportage dal set della rivista cinematografica Cahiers du Cinéma', TRUE, 'IA (Daily Sync)', 'IA Verificata', 0, 5, '2026-11-02T10:04:23.953646+00:00'),
('a3ad7e2f-69fc-445e-8ec8-a2174b5defbb', 133, 'Segreti di produzione', 'La Volkswagen Beetle gialla appartenuta a Sharon Tate', 'Nelle sequenze in cui Margot Robbie guida per Los Angeles nei panni di Sharon Tate, l''automobile utilizzata è una vera Volkswagen Beetle gialla d''epoca che in passato era realmente appartenuta alla vera Sharon Tate. La produzione è riuscita a rintracciarla e a ottenerla in prestito per le riprese grazie ai contatti con la famiglia.', 'Note di produzione ufficiali e interviste alla scenografa Barbara Ling', TRUE, 'IA (Daily Sync)', 'IA Verificata', 0, 0, '2026-11-02T10:04:56.0012+00:00'),
('1889831f-3ccd-4f8a-8650-4ec7ee93c0b4', 133, 'Citazioni & Easter Egg', 'La vettura di Cliff Booth e il legame con Bullitt', 'La Karmann Ghia marrone guidata da Cliff Booth nel film è un preciso omaggio alle auto d''epoca californiane, ma il personaggio ha un legame diretto con la storia del cinema stunt: la sua reputazione di aver ''preso a calci in culo Bruce Lee'' sul set del The Green Hornet riflette la leggendaria rivalità tra stuntman professionisti e attori marziali nell''Hollywood di fine anni Sessanta.', 'Commento audio e note del reparto trasporti e scenografia', TRUE, 'IA (Daily Sync)', 'IA Verificata', 0, 1, '2026-11-02T10:04:56.0012+00:00'),
('d44ffe40-4889-4772-a0be-aa4ca22ed583', 133, 'Curiosità & Retroscena', 'Il cameo vocale di James Remar e le voci alla radio', 'L''attore James Remar, storico collaboratore di Quentin Tarantino, appare in un piccolo ruolo non accreditato come uno dei poliziotti nella sequenza finale, ma gran parte dell''autenticità sonora del film è data dalle vere trasmissioni radiofoniche originali del 1969 ripescate dalle registrazioni d''archivio di KHJ Radio.', 'Credits ufficiali del film e archivio sonoro di produzione', TRUE, 'IA (Daily Sync)', 'IA Verificata', 0, 2, '2026-11-02T10:04:56.0012+00:00'),
('1ce7463d-4efe-49cb-8714-2c72a768b5c6', 196, 'Segreti di produzione', 'La scelta del titolo negli Stati Uniti', 'Negli Stati Uniti, il film fu distribuito semplicemente come ''The Road Warrior'' perché il primo capitolo della saga era uscito in sordina in pochi cinema americani e la Warner Bros. temeva che il pubblico non avrebbe collegato un ipotetico ''Mad Max 2'' a un titolo che non riconosceva.', 'Note di produzione e storico della distribuzione Warner Bros.', TRUE, 'IA (Daily Sync)', 'IA Verificata', 0, 0, '2026-11-02T10:10:32.670715+00:00'),
('b17aeadd-269c-484d-9761-556fd8460bea', 196, 'Effetti speciali & Trucco', 'La vera identità della spaventosa balestra di Max', 'La celebre balestra impugnata da Mel Gibson nel film fu realizzata artigianalmente modificando una pistola lanciafrecce sportiva. Poiché l''attore l''avrebbe brandita frequentemente, la produzione ne fece costruire tre versioni identiche, inclusa una in gomma leggera per le sequenze di corsa.', 'Documentario di retroscena ''Road Gautlet: The Making of Mad Max 2''', TRUE, 'IA (Daily Sync)', 'IA Verificata', 0, 1, '2026-11-02T10:10:32.670715+00:00'),
('01e6b93d-bbf2-4708-afce-3b4192f8d0b7', 196, 'Curiosità & Retroscena', 'Il doppiaggio totale per il mercato americano', 'A causa dell''accento australiano troppo marcato e dell''uso di slang locale ritenuto incomprensibile per gli spettatori statunitensi, gran parte dei dialoghi dei personaggi secondari fu interamente ridoppiata da attori americani prima dell''uscita nelle sale degli Stati Uniti.', 'Archivio storico della censura e distribuzione cinematografica', TRUE, 'IA (Daily Sync)', 'IA Verificata', 0, 2, '2026-11-02T10:10:32.670715+00:00'),
('47d5b087-a48e-4342-ad21-5780cca9a591', 196, 'Segreti di produzione', 'Il rifiuto iniziale del compositore Brian May', 'Il celebre compositore australiano Brian May fu inizialmente riluttante a comporre la colonna sonora del film a causa dei tempi di lavorazione estremamente stretti imposti dalla post-produzione, ma accettò dopo aver visto i primi montaggi grezzi delle sequenze d''azione nel deserto.', 'Note di copertina dell''edizione speciale della colonna sonora', TRUE, 'IA (Daily Sync)', 'IA Verificata', 0, 3, '2026-11-02T10:10:32.670715+00:00'),
('f2312abe-febe-489d-9b32-39177e2347a2', 196, 'Effetti speciali & Trucco', 'La finta ferita all''occhio del Lord Humungus', 'L''attore svedese Kjell Nilsson, che interpretava il leader dei predoni Lord Humungus, indossava una maschera da hockey su ghiaccio e aveva una protesi oculare simulata che faceva sembrare il suo occhio sinistro gravemente deformato, un dettaglio visivo pensato per accentuare il suo passato di veterano di guerra sfigurato.', 'Intervista al truccatore Bob Larson', TRUE, 'IA (Daily Sync)', 'IA Verificata', 0, 4, '2026-11-02T10:10:32.670715+00:00'),
('4c380100-72be-4631-8b83-507a5b17640e', 108, 'Segreti di produzione', 'La partnership produttiva con Bad Robot', 'Il progetto è nato dall''accordo strategico tra la Bad Robot di J.J. Abrams e la divisione Warner Bros. Pictures, con Hannah Minghella e Matt Jackson come produttori principali. Mitchell ha mantenuto il pieno controllo creativo sulla sceneggiatura, sviluppata nel più assoluto riserbo sotto il titolo di lavorazione legato al quartiere dell''azione.', 'Deadline Hollywood', TRUE, 'IA (Admin)', 'IA Verificata', 4, 3, '2026-11-02T18:13:56.94748+00:00'),
('abe33810-c9da-44a6-b996-ead2d8acfdfd', 198, 'Curiosità & Retroscena', 'La genesi del cane di Max', 'Il cane che accompagna Max nelle prime sequenze del film, un Australian Cattle Dog battezzato Boo, è stato adottato direttamente da un canile locale in Namibia durante la pre-produzione ed è stato addestrato appositamente per gestire il caos e i rumori del set.', 'Note di produzione ufficiali e interviste al reparto addestramento animali', TRUE, 'IA (Daily Sync)', 'IA Verificata', 0, 0, '2026-11-02T10:10:39.927356+00:00'),
('9e52d0a2-8e9c-4cd9-867e-e4f07e4256ac', 198, 'Segreti di produzione', 'Il ritardo di vent''anni e il blocco in Australia', 'Il film ha subito quasi vent''anni di ''development hell'': nel 2001 la produzione era pronta a partire in Australia con Mel Gibson, ma gli attacchi dell''11 settembre causarono il crollo del dollaro USA e imposero restrizioni sui finanziamenti, costringendo Miller a fermare tutto mentre i container con i veicoli erano già arrivati sul set.', 'Dichiarazioni di George Miller nei press tour e documentari sul making-of', TRUE, 'IA (Daily Sync)', 'IA Verificata', 0, 1, '2026-11-02T10:10:39.927356+00:00'),
('71ea55c2-22a2-4bfc-9009-b175f8a5e587', 198, 'Casting & Scelte', 'La scelta della stuntwoman di Charlize Theron', 'Per le sequenze più pericolose dell''Imperatrice Furiosa, Charlize Theron è stata affiancata da Dayna Grant, una stuntwoman professionista neozelandese che ha lavorato a stretto contatto con l''attrice per mesi per replicare la fisicità del personaggio con il braccio amputato.', 'Crediti stunt ufficiali e interviste a Dayna Grant', TRUE, 'IA (Daily Sync)', 'IA Verificata', 0, 2, '2026-11-02T10:10:39.927356+00:00'),
('c21101b1-8d88-42ac-bfe2-b28ca4973e0d', 198, 'Segreti di produzione', 'Il design dei veicoli ideato da Peter Pound', 'Tutti i folli veicoli post-apocalittici non sono nati da semplici modifiche casuali, ma sono stati disegnati in dettaglio dal concept artist Peter Pound insieme a Brendan McCarthy, partendo da logiche meccaniche e funzionali coerenti con la scarsità di risorse del mondo di Mad Max.', 'Libro d''arte ufficiale ''The Art of Mad Max: Fury Road''', TRUE, 'IA (Daily Sync)', 'IA Verificata', 0, 3, '2026-11-02T10:10:39.927356+00:00'),
('257f58c5-a957-4646-ad8f-83c02accdbb8', 198, 'Effetti speciali & Trucco', 'La cicatrice e il tatuaggio sulla schiena di Max', 'Il truccatore Colin Gibson e il supervisore degli effetti speciali di trucco Lesley Vanderwalt hanno applicato sul corpo di Tom Hardy decine di cicatrici e tatuaggi specifici, tra cui un documento esplicito sulla sua carta d''identità medica post-apocalittica visibile nei primi piani.', 'Articoli di approfondimento sul trucco e costumi del film', TRUE, 'IA (Daily Sync)', 'IA Verificata', 0, 4, '2026-11-02T10:10:39.927356+00:00'),
('4ae2340a-6f12-442a-8167-cd87e4f29986', 183, 'Effetti speciali & Trucco', 'La voce abrasiva di Benedict Cumberbatch per Smaug', 'Per trovare il timbro vocale perfetto e cavernoso di Smaug, Benedict Cumberbatch si sottoponeva a sessioni di registrazione così intense da affaticare pesantemente le sue corde vocali. L''attore ha rivelato nei contenuti speciali del film di aver bevuto grandi quantità di latte e acqua calda per preservare la voce durante i ruggiti più estremi.', 'Appendici ufficiali del Blu-ray di The Hobbit: The Desolation of Smaug', TRUE, 'IA (Daily Sync)', 'IA Verificata', 0, 0, '2026-11-02T10:17:41.552888+00:00'),
('1bb5dcc0-83cf-4249-84bd-bc5c34b97ceb', 340, 'Segreti di produzione', 'La scelta della location rurale', 'Le riprese esterne della fattoria della famiglia Hess sono state girate in una proprietà privata a Monroe Township, nella Contea di Bucks, in Pennsylvania. La produzione ha fatto costruire interamente da zero la casa colonica e piantato ettari di vere coltivazioni di mais mesi prima dell''inizio delle riprese per permettere alle piante di crescere rigogliose.', 'Note di produzione ufficiali Touchstone Pictures', TRUE, 'IA (Daily Sync)', 'IA Verificata', 0, 0, '2026-11-02T14:51:17.613497+00:00'),
('d4f42789-9548-4d3b-aa59-c282d2d69ded', 183, 'Effetti speciali & Trucco', 'Le lenti a contatto sclerali di Lee Pace', 'Per interpretare il re degli Elfi Thranduil, l''attore Lee Pace doveva indossare specifiche lenti a contatto sclerali di grandi dimensioni che coprivano quasi l''intero bulbo oculare. Queste lenti impedivano parzialmente la vista e dovevano essere rimosse frequentemente tra un ciak e l''altro per permettere agli occhi di riposare dall''irritazione.', 'Intervista ufficiale a Lee Pace nei contenuti speciali', TRUE, 'IA (Daily Sync)', 'IA Verificata', 0, 2, '2026-11-02T10:17:41.552888+00:00'),
('c5156d3e-47ab-4e83-8b74-f22bcafa9e73', 183, 'Citazioni & Easter Egg', 'Il cameo dei figli di Peter Jackson a Pontelagolungo', 'I figli del regista Peter Jackson, Katie e Billy Jackson, fanno entrambi una breve apparizione non accreditata nel film. Appaiono come giovani abitanti di Pontelagolungo durante le scene in cui i Nani cercano di introdursi clandestinamente nella città lacustre nascosti nelle botti.', 'Note di produzione e commento audio del regista', TRUE, 'IA (Daily Sync)', 'IA Verificata', 0, 3, '2026-11-02T10:17:41.552888+00:00'),
('3f1a7569-0f87-4bc3-bb22-a4d9aa71417e', 260, 'Aneddoti dal set', 'L''infortunio cardiaco di Bob Odenkirk', 'Nel luglio 2021, pochi mesi dopo l''uscita del film, Bob Odenkirk è stato colpito da un infarto sul set della sesta stagione di ''Better Call Saul''. L''attore ha dichiarato in diverse interviste che la rigorosa preparazione fisica e l''allenamento intensivo affrontati proprio per le scene d''azione di ''Io sono nessuno'' hanno migliorato complessivamente la sua salute cardiovascolare, aiutandolo concretamente a sopravvivere all''attacco di cuore.', 'Interviste stampa ufficiali di Bob Odenkirk per NPR e The New York Times', TRUE, 'IA (Daily Sync)', 'IA Verificata', 0, 0, '2026-11-02T10:21:33.398413+00:00'),
('d7ca9a77-a1a2-494d-b22d-67d978bd0c87', 260, 'Curiosità & Retroscena', 'Il cameo e il ruolo del regista Ilya Naishuller', 'Oltre a dirigere la pellicola, il regista russo Ilya Naishuller appare brevemente sul schermo nei panni di uno dei mercenari dell''antagonista principale Yulian Kuznetsov (interpretato da Aleksey Serebryakov), precisamente il sicario che affronta Hutch nel laboratorio della ditta. Naishuller ha sfruttato la sua esperienza precedente da stuntman in ''Hardcore!'' per coreografare da vicino i movimenti della sequenza.', 'Commento audio del regista e note di produzione ufficiali', TRUE, 'IA (Daily Sync)', 'IA Verificata', 0, 1, '2026-11-02T10:21:33.398413+00:00'),
('ee1fa4db-e2ee-4ff7-8084-b4ec09ac798d', 260, 'Casting & Scelte', 'La genesi dell''ispirazione domestica', 'Lo sceneggiatore Derek Kolstad ha ideato la premessa di ''Io sono nessuno'' basandosi parzialmente su un evento reale vissuto in prima persona: alcuni ladri si erano introdotti nella sua proprietà in passato ed egli, pur avendo la possibilità di reagire violentemente, aveva scelto di non farlo per proteggere la sua famiglia. Da quell''episodio di impotenza percepita è nato lo spunto per trasformare un uomo qualunque in un letale ex agente governativo.', 'Intervista a Derek Kolstad per Collider', TRUE, 'IA (Daily Sync)', 'IA Verificata', 0, 2, '2026-11-02T10:21:33.398413+00:00'),
('72fde78b-6d57-467a-95d9-a75685263442', 295, 'Casting & Scelte', 'Gael García Bernal doppia Héctor in due lingue', 'In una rara eccezione per le grandi produzioni d''animazione hollywoodiane, Gael García Bernal ha doppiato il personaggio di Héctor sia nella versione originale inglese che nell''adattamento spagnolo destinato all''America Latina e alla Spagna. L''attore ha registrato le tracce vocali e canore in entrambe le lingue curando personalmente le sfumature dialettali messicane per garantire coerenza espressiva.', 'Intervista a Gael García Bernal su The Hollywood Reporter', TRUE, 'IA (Daily Sync)', 'IA Verificata', 0, 5, '2026-11-02T11:30:47.876357+00:00'),
('dae16b78-c5ee-4a46-bd82-6b456d04e8ba', 295, 'Segreti di produzione', 'Registrazioni orchestrali sul campo a Città del Messico', 'Il compositore Michael Giacchino e la produttrice musicale Germaine Franco si sono recati direttamente a Città del Messico per registrare la colonna sonora con oltre cinquanta musicisti tradizionali locali. Le sessioni hanno impiegato strumenti indigeni e popolari autentici come marimbe tradizionali, arpe jarocho, requintos e güiros per catturare generi regionali esatti come il Son Jarocho e la Banda.', 'Making-of ufficiale Disney Music Group', TRUE, 'IA (Daily Sync)', 'IA Verificata', 0, 6, '2026-11-02T11:30:47.876357+00:00'),
('5ccac272-92dd-4916-88e7-0b6232bbffa4', 199, 'Casting & Scelte', 'La parentela speciale di Spencer Watson nel film', 'L''attrice Spencer Watson, che nel film interpreta Harland, è in realtà la nipote di George Miller nella vita reale, inserita nel cast dopo aver partecipato ai provini tradizionali.', 'Note di produzione ufficiali di Furiosa: A Mad Max Saga', TRUE, 'IA (Daily Sync)', 'IA Verificata', 0, 0, '2026-11-02T10:10:46.561706+00:00'),
('fbbdca10-c8fb-4c75-9ecd-6f8ff6d0a909', 199, 'Effetti speciali & Trucco', 'La voce digitale unita alla performance di Lachy Hulme', 'Per ricreare la voce iconica di Immortan Joe portata originariamente da Hugh Keays-Byrne, Lachy Hulme ha doppiato le sue stesse battute fondendole con registrazioni d''archivio e modulazioni digitali supervisionate dal sound designer.', 'Intervista al sound design team e a Lachy Hulme', TRUE, 'IA (Daily Sync)', 'IA Verificata', 0, 1, '2026-11-02T10:10:46.561706+00:00'),
('4c978ccb-8d53-4fdd-9348-751dfc230d22', 128, 'Aneddoti dal set', 'I problemi di doppiaggio di Rod Steiger', 'Come era consuetudine nel cinema di Sergio Leone girato in lingua inglese, gran parte del film fu girata in presa quasi muta o con attori che recitavano in inglese e spagnolo sul set; Rod Steiger fu doppiato nella versione italiana da Sergio Graziani, il quale dovette adattare le battute per mantenere la forte inflessione e la coralità volute dal regista.', 'Archivi della S.A.S. Società Attori Doppiatori e note di edizione', TRUE, 'IA (Daily Sync)', 'IA Verificata', 0, 3, '2026-11-02T10:04:30.534674+00:00'),
('ba798620-66aa-4b52-9619-c1a14ea254d6', 199, 'Casting & Scelte', 'Il cameo di John Howard nel ruolo di The People Eater', 'L''attore veterano John Howard è tornato a interpretare The People Eater sebbene il personaggio sia stato ringiovanito digitalmente e parzialmente integrato con controfigure a causa del passare degli anni rispetto a Mad Max: Fury Road.', 'Press kit ufficiale Warner Bros.', TRUE, 'IA (Daily Sync)', 'IA Verificata', 0, 2, '2026-11-02T10:10:46.561706+00:00'),
('79461bb1-6dff-4c72-aed2-a4ae8033f163', 199, 'Casting & Scelte', 'Il ritorno di Angus McLaren e dei figli di George Miller', 'Il cast secondario vede la partecipazione di Angus McLaren nel ruolo dell''Enforcer e compaiono in piccoli ruoli anche i figli di George Miller, consolidando il carattere di produzione familiare della troupe australiana.', 'Crediti ufficiali e interviste al cast', TRUE, 'IA (Daily Sync)', 'IA Verificata', 0, 3, '2026-11-02T10:10:46.561706+00:00'),
('24ab68df-b73e-43d1-869f-b7251b93131c', 199, 'Segreti di produzione', 'L''utilizzo delle sequenze d''animazione preliminari in stile storyboard', 'Prima di girare la monumentale sequenza della ''Corsa dei 150 giorni'', George Miller ha fatto realizzare un''animazione digitale in 3D di grande dettaglio (pre-vis) che fungeva da guida millimetrica per gli stuntmen e i cineoperatori.', 'Speciali sul making-of allegati all''edizione home video', TRUE, 'IA (Daily Sync)', 'IA Verificata', 0, 4, '2026-11-02T10:10:46.561706+00:00'),
('5699c418-7d5b-4547-b511-0587657fe194', 201, 'Curiosità & Retroscena', 'Il legame con il vero Massacro di Sand Creek', 'Il devastante climax del film si basa direttamente sul famigerato massacro di Sand Creek avvenuto il 29 novembre 1864, guidato dal colonnello John Chivington. Ralph Nelson inserì questa pagina nera della storia americana per denunciare le atrocità commesse contro i nativi, collegandole implicitamente alle atrocità contemporanee della guerra del Vietnam, come il massacro di My Lai.', 'Note di produzione e documentario d''archivio sulla genesi del film', TRUE, 'IA (Daily Sync)', 'IA Verificata', 0, 0, '2026-11-02T10:11:00.902993+00:00'),
('17b291ef-8629-4fc5-9b78-29be0c1a2bd0', 201, 'Aneddoti dal set', 'La reazione scioccata del pubblico alla prima', 'Durante le prime proiezioni di prova e l''uscita nelle sale nel 1970, la sequenza finale del massacro fu così cruda e inaspettata rispetto al tono iniziale da commedia picaresca del film che molti spettatori abbandonarono la sala in lacrime o visibilmente scioccati, mentre altri arrivarono a contestare apertamente la pellicola durante le proiezioni pubbliche.', 'Resoconti storici dell''uscita cinematografica e recensioni dell''epoca', TRUE, 'IA (Daily Sync)', 'IA Verificata', 0, 1, '2026-11-02T10:11:00.902993+00:00'),
('e635ce5a-d1ed-4d9d-a810-e69e589f42c2', 340, 'Citazioni & Easter Egg', 'L''ispirazione visiva da Night of the Living Dead', 'M. Night Shyamalan ha dichiarato apertamente di essersi ispirato al classico horror di George A. Romero del 1968 per la struttura narrativa dell''assedio domestico. L''idea di una famiglia barricata all''interno di una casa rurale mentre una minaccia sconosciuta circonda l''edificio riprende direttamente le dinamiche claustrofobiche del capolavoro di Romero.', 'Commento audio del regista nel DVD ufficiale', TRUE, 'IA (Daily Sync)', 'IA Verificata', 0, 1, '2026-11-02T14:51:17.613497+00:00'),
('ecc5779f-9f9c-453e-b528-594dcb53084a', 185, 'Curiosità & Retroscena', 'Il duplice riconoscimento agli Oscar', 'Il film ottenne due importanti candidature ai premi Oscar del 1945: una per la migliore colonna sonora drammatica o commedia firmata da Robert Stolz e una per il miglior sonoro curato da Jack Whitney.', 'Database ufficiale dell''Academy of Motion Picture Arts and Sciences', TRUE, 'IA (Daily Sync)', 'IA Verificata', 0, 2, '2026-11-02T10:17:47.791175+00:00'),
('e166de42-8a09-476c-9791-5a3ede80fb04', 185, 'Curiosità & Retroscena', 'L''adattamento radiofonico con Dick Powell', 'Il successo del film spinse la celebre trasmissione radiofonica ''Lux Radio Theatre'' a realizzare un adattamento del soggetto il 12 febbraio 1945, richiamando proprio Dick Powell a riprendere il suo ruolo di Larry Stevens.', 'Archivio storico dei broadcast radiofonici Lux Radio Theatre', TRUE, 'IA (Daily Sync)', 'IA Verificata', 0, 3, '2026-11-02T10:17:47.791175+00:00'),
('8c28dbbf-77ba-424f-bd11-0a80017f794a', 265, 'Aneddoti dal set', 'La ferita alla gamba di Daniel Craig', 'Poco prima di iniziare le riprese del film, Daniel Craig si è lacerato i legamenti della caviglia mentre girava una scena d''azione per il film di James Bond ''No Time to Die''. Rian Johnson ha dovuto riorganizzare temporaneamente il piano di produzione per permettere a Craig di girare le sue prime scene da fermo o con movimenti ridotti.', 'Intervista ufficiale di Rian Johnson per Vanity Fair e note di produzione', TRUE, 'IA (Daily Sync)', 'IA Verificata', 0, 0, '2026-11-02T10:22:01.34118+00:00'),
('089b066f-0aff-48e5-b102-db1a45498c7f', 265, 'Segreti di produzione', 'La vera e propria copia di ''Sleuth'' come ispirazione visiva', 'Il direttore della fotografia Steve Yedlin e il regista Rian Johnson hanno studiato approfonditamente pellicole classiche sui delitti in camera chiusa, tra cui in particolare ''Sleuth'' (Gli insospettabili) del 1972, per replicare l''uso dinamico degli zoom cinematografici tipico dei thriller anni ''70.', 'Commento audio del regista nel Blu-ray ufficiale di Knives Out', TRUE, 'IA (Daily Sync)', 'IA Verificata', 0, 1, '2026-11-02T10:22:01.34118+00:00'),
('5adc7d7a-0478-4864-9763-a0000af28b62', 265, 'Casting & Scelte', 'Il contratto segreto di Daniel Craig per James Bond', 'L''accordo per far interpretare Benoit Blanc a Daniel Craig è dipeso interamente dai ritardi accumulati nella produzione di ''No Time to Die'', che hanno aperto una finestra temporale di circa tre mesi in cui l''attore britannico era totalmente libero prima di tornare a vestire i panni di 007.', 'The Hollywood Reporter - Dietro le quinte del casting di Knives Out', TRUE, 'IA (Daily Sync)', 'IA Verificata', 0, 2, '2026-11-02T10:22:01.34118+00:00'),
('a85b0c61-0ebc-4217-9d02-6b66db27aee0', 295, 'Citazioni & Easter Egg', 'Il cameo di John Ratzenberger come Juan Ortodoncia', 'Rispettando la storica tradizione Pixar di includere l''attore feticcio John Ratzenberger in ogni lungometraggio, a lui è stato affidato il cameo vocale di Juan Ortodoncia. Si tratta del defunto che riesce ad attraversare il ponte verso il mondo dei vivi unicamente perché il suo dentista, ancora in vita, conserva una sua foto ricordo sulla parete dello studio.', 'Intervista al co-regista Adrian Molina su Entertainment Weekly', TRUE, 'IA (Daily Sync)', 'IA Verificata', 0, 7, '2026-11-02T11:30:47.876357+00:00'),
('b9099476-5372-4d20-b1f8-05eccfd9b162', 202, 'Aneddoti dal set', 'La voce originale di Katniss e l''accento del Distretto 12', 'Per conferire maggiore autenticità al personaggio di Katniss ed evidenziare la sua estrazione sociale povera, Jennifer Lawrence ha lavorato con un dialog coach per adottare un accento degli Appalachi leggermente marcato rispetto alla sua cadenza originaria del Kentucky. Questa scelta vocale è stata mantenuta costante per tutto il primo film per marcare la differenza culturale con la sfarzosa capitale.', 'Note di produzione ufficiali Lionsgate e interviste al cast', TRUE, 'IA (Daily Sync)', 'IA Verificata', 0, 0, '2026-11-02T10:11:07.860932+00:00'),
('d190f310-f76a-4a2d-a2a3-b1814deeb4ad', 202, 'Casting & Scelte', 'Il rifiuto iniziale di Stanley Tucci', 'L''attore Stanley Tucci, che interpreta il bizzarro ed eccentrico presentatore Caesar Flickerman, inizialmente esitò ad accettare la parte offertagli dal regista Gary Ross. Accettò infine grazie all''insistenza dello stesso Ross e all''opportunità di modellare la stravagante personalità del personaggio traendo ispirazione da reali conduttori televisivi di talk show sensazionalistici.', 'Intervista promozionale a Stanley Tucci per Entertainment Weekly', TRUE, 'IA (Daily Sync)', 'IA Verificata', 0, 1, '2026-11-02T10:11:07.860932+00:00'),
('b2855d4e-405c-444e-b1cf-1e69d258d72a', 202, 'Aneddoti dal set', 'La ferita al polso di Jennifer Lawrence durante gli stunt', 'Durante la sequenza in cui Katniss fugge dai fuochi della foresta e si arrampica su un albero, Jennifer Lawrence si infortunò accidentalmente a un polso sbattendolo contro una roccia finta. Sebbene il dolore fosse acuto, l''attrice continuò a girare la scena senza interrompere la produzione, guadagnandosi il rispetto immediato degli stunt coordinator.', 'Special TV ''The World is Watching: Making The Hunger Games''', TRUE, 'IA (Daily Sync)', 'IA Verificata', 0, 2, '2026-11-02T10:11:07.860932+00:00'),
('5e5dbda8-1c0c-4a4b-aab9-29fb67a73f95', 202, 'Curiosità & Retroscena', 'Il cameo vocale di Toby Jones per Claudius Templesmith', 'Toby Jones, interprete del telecronista ufficiale dei giochi Claudius Templesmith, ha registrato molte delle sue battute e dei suoi annunci in diretta direttamente dal vivo sul set tramite un auricolare nascosto. Questa tecnica ha permesso agli attori nel bosco di reagire in tempo reale alle comunicazioni ufficiali della regia dei giochi con maggiore naturalezza.', 'Commento audio del regista Gary Ross nel Blu-ray ufficiale', TRUE, 'IA (Daily Sync)', 'IA Verificata', 0, 3, '2026-11-02T10:11:07.860932+00:00'),
('9129237d-8bdc-4646-840e-81621b79f75f', 186, 'Segreti di produzione', 'L''utilizzo dei veri velivoli A-26 Invader', 'Per le sequenze di volo del film, la produzione ha utilizzato veri bombardieri ad elica Douglas A-26 Invader modificati come autocisterne per il trasporto dell''acqua, impiegando piloti acrobatici professionisti per le manovre a basse quota.', 'Note di produzione ufficiali Universal Pictures', TRUE, 'IA (Daily Sync)', 'IA Verificata', 0, 0, '2026-11-02T10:17:54.027579+00:00'),
('a0f5ab88-753c-49e0-9639-95ea96f8a379', 186, 'Casting & Scelte', 'La scelta del titolo originale e il cambio di prospettiva', 'Il progetto iniziale di Steven Spielberg prevedeva di intitolare semplicemente il film con il titolo originale del 1943 ''A Guy Named Joe'', prima di optare per ''Always'' per sottolineare la natura romantica ed eterna del legame tra i protagonisti.', 'Archivio storico Steven Spielberg / Amblin Entertainment', TRUE, 'IA (Daily Sync)', 'IA Verificata', 0, 1, '2026-11-02T10:17:54.027579+00:00'),
('b8d8f476-d0e3-4f1d-b4f7-a09462b5d748', 186, 'Curiosità & Retroscena', 'Il cameo vocale e la supervisione di John Williams', 'La colonna sonora orchestrale è stata interamente composta dal collaboratore storico di Spielberg, John Williams, il quale ha inserito richiami musicali sottili alle melodie degli anni ''40 per omaggiare la pellicola originale diretta da Victor Fleming.', 'Libretto ufficiale della colonna sonora Varese Sarabande', TRUE, 'IA (Daily Sync)', 'IA Verificata', 0, 2, '2026-11-02T10:17:54.027579+00:00'),
('c2212c15-c014-45c2-a6fb-f4ed7dd0495d', 266, 'Citazioni & Easter Egg', 'L''omaggio a Jacques Tati nella colonna sonora', 'Il compositore Nathan Johnson ha inserito un esplicito omaggio al regista Jacques Tati nella partitura musicale, riprendendo le sonorità e le atmosfere di ''Playtime'' per sottolineare la caotica dinamica sociale del gruppo.', 'Commento audio ufficiale del regista Rian Johnson', TRUE, 'IA (Daily Sync)', 'IA Verificata', 0, 0, '2026-11-02T10:22:11.632096+00:00'),
('697324c4-2d33-477a-a5dd-d3f99890faf1', 266, 'Segreti di produzione', 'La consulenza scientifica per il blocco respiratorio', 'Per girare la scena in cui Andi Brand subisce l''attacco di Klaxon con il peperoncino, la produzione ha consultato medici esperti di reazioni allergiche per garantire che la simulazione scenica fosse accurata senza mettere in pericolo Janelle Monáe.', 'Note di produzione ufficiali di Netflix', TRUE, 'IA (Daily Sync)', 'IA Verificata', 0, 1, '2026-11-02T10:22:11.632096+00:00'),
('08dd261e-f902-46fc-9cb3-eadb984aefa9', 266, 'Aneddoti dal set', 'Il cameo di Joseph Gordon-Levitt come il misterioso orologio', 'L''attore feticcio di Rian Johnson, Joseph Gordon-Levitt, appare nuovamente nel franchise di Knives Out fornendo la voce al ''Hourly Dong'', il sistema acustico che scandisce il tempo sulla villa di Miles Bron.', 'Crediti finali del film e intervista a Rian Johnson', TRUE, 'IA (Daily Sync)', 'IA Verificata', 0, 2, '2026-11-02T10:22:11.632096+00:00'),
('a887fc21-ac02-4e39-ae37-d563946158b2', 266, 'Curiosità & Retroscena', 'Il cameo di Serena Williams bloccata in casa', 'Tra le celebrità che compaiono nella sequenza della videochiamata iniziale spicca la tennista Serena Williams, la quale interpreta se stessa mentre fa da personal trainer virtuale a un cliente confinato in casa.', 'Backstage ufficiale Netflix e interviste al cast', TRUE, 'IA (Daily Sync)', 'IA Verificata', 0, 3, '2026-11-02T10:22:11.632096+00:00'),
('e1916eb3-8060-441f-9e2a-12d23309fd91', 266, 'Casting & Scelte', 'Le origini teatrali del look di Benoit Blanc', 'La costumista Jenny Eagan ha rivelato che il guardaroba estivo di Benoit Blanc in Grecia, caratterizzato da completi pastello a righe e foulard di seta, è ispirato ai look indossati da Cary Grant e Peter Ustinov nei classici gialli cinematografici degli anni ''70.', 'Intervista di Jenny Eagan per Variety', TRUE, 'IA (Daily Sync)', 'IA Verificata', 0, 4, '2026-11-02T10:22:11.632096+00:00'),
('1d944b34-0796-4ff1-9c9e-be5704316081', 266, 'Effetti speciali & Trucco', 'La bottiglia di kombucha esplosiva', 'La kombucha fatta in casa da Birdie Jay che esplode improvvisamente durante il soggiorno sull''isola è stata realizzata dalla troupe degli effetti speciali utilizzando una combinazione di spumante, lievito e oggetti di scena in zucchero per evitare lesioni.', 'Featurette ''Making Glass Onion'' su Netflix', TRUE, 'IA (Daily Sync)', 'IA Verificata', 0, 5, '2026-11-02T10:22:11.632096+00:00'),
('8ea9d3ef-1b52-4f61-868c-c53792faa84d', 295, 'Curiosità & Retroscena', 'La concezione mutevole del brano ''Remember Me''', 'La canzone premio Oscar ''Remember Me'' è stata composta dalla coppia Robert Lopez e Kristen Anderson-Lopez con il vincolo preciso di funzionare attraverso generi e stati d''animo opposti. Gli autori hanno dovuto strutturare accordi e metrica in modo che il pezzo funzionasse sia come esuberante ranchera da concerto per De la Cruz, sia come delicatissima e straziante ninna nanna sussurrata da un padre alla propria bambina.', 'Intervista a Kristen Anderson-Lopez e Robert Lopez su Variety', TRUE, 'IA (Daily Sync)', 'IA Verificata', 0, 8, '2026-11-02T11:30:47.876357+00:00'),
('e6831795-aba8-409b-86e8-7d91990e6c10', 340, 'Curiosità & Retroscena', 'Il budget e il controllo creativo', 'Il film è stato realizzato con un budget stimato di circa 72 milioni di dollari, finanziato principalmente dalla Walt Disney Pictures tramite la sua etichetta Touchstone. Shyamalan ha goduto di un controllo creativo totale, potendo decidere ogni aspetto del montaggio e della colonna sonora composta da James Newton Howard.', 'Archivio storico di Box Office Mojo e Variety', TRUE, 'IA (Daily Sync)', 'IA Verificata', 0, 2, '2026-11-02T14:51:17.613497+00:00'),
('2e68f0f3-0760-43be-a741-6a94d00e7c96', 203, 'Segreti di produzione', 'La scelta dell''arena tropicale alle Hawaii', 'Per le sequenze dell''arena dei Settantaseiesimi Hunger Games, la produzione ha scelto di girare in location reali anziché ricorrere interamente ai teatri di posa, trasferendo la troupe nel parco naturale di Duke Kahanamoku Lagoon e nelle spiagge di Oahu, alle Hawaii, per circa un mese di riprese.', 'Note di produzione ufficiali Lionsgate', TRUE, 'IA (Daily Sync)', 'IA Verificata', 0, 0, '2026-11-02T10:11:15.738117+00:00'),
('b9c4c50d-3909-45ba-b4e3-d201481aadcd', 203, 'Effetti speciali & Trucco', 'La parrucca di Jena Malone per Johanna Mason', 'L''attrice Jena Malone dovette indossare una complessa parrucca castana per interpretare il personaggio di Johanna Mason nelle scene iniziali e durante il tour della vittoria, poiché sul set cinematografico presentava ancora i capelli cortissimi del suo precedente impegno lavorativo nel film ''The Wait''.', 'Intervista al reparto trucco e parrucco Blu-ray', TRUE, 'IA (Daily Sync)', 'IA Verificata', 0, 1, '2026-11-02T10:11:15.738117+00:00'),
('1b6ce23a-a974-4411-892d-db2f654d2c37', 203, 'Aneddoti dal set', 'Il blocco del traffico a Los Angeles per il tour', 'La sequenza in cui Katniss e Peeta arrivano in auto a Capitol City e sfilano tra la folla festante fu girata in parte presso il Marriott Hotel di Atlanta e in parte ricostruendo il set urbano, richiedendo il blocco temporaneo di alcune importanti arterie stradali e il coinvolgimento di oltre 500 comparse con costumi eccentrici.', 'Reportage dal set di American Cinematographer', TRUE, 'IA (Daily Sync)', 'IA Verificata', 0, 2, '2026-11-02T10:11:15.738117+00:00'),
('bd2346a1-18da-4bea-987e-e0d1b9373639', 203, 'Aneddoti dal set', 'L''infortunio alla mano di Sam Claflin', 'Durante le impegnative riprese delle scene in acqua nell''arena, l''attore Sam Claflin si fratturò un osso della mano lottando contro gli stuntmen e dovette indossare un tutore impermeabile nascosto sotto i guanti di scena per poter continuare a girare senza accumulare ritardi sul piano di lavorazione.', 'Intervista audio-commento del regista Francis Lawrence', TRUE, 'IA (Daily Sync)', 'IA Verificata', 0, 3, '2026-11-02T10:11:15.738117+00:00'),
('bad519d7-2cab-4515-b1b7-62dfab132532', 187, 'Curiosità & Retroscena', 'La proiezione sold-out al Busan Film Festival', 'Quando ''Always'' è stato selezionato come film d''apertura del 16° Busan International Film Festival nel 2011, i 4.000 biglietti disponibili per la proiezione inaugurale sono andati esauriti in appena 7 secondi dal momento dell''apertura delle vendite online, stabilendo un record per la manifestazione.', 'Comunicato stampa ufficiale del Busan International Film Festival 2011', TRUE, 'IA (Daily Sync)', 'IA Verificata', 0, 0, '2026-11-02T10:17:59.845217+00:00'),
('91d07b17-8c74-4eec-a05f-5c29abc66073', 187, 'Casting & Scelte', 'Il debutto alla regia di Song Il-gon nel melodramma', 'Il regista Song Il-gon, noto principalmente per i suoi film d''essai e d''autore premiati nei festival internazionali come ''Spider Forest'' e ''Feathers in the Wind'', ha scelto ''Always'' per il suo primo tentativo di dirigere un melodramma commerciale ad alto budget.', 'Note di produzione e conferenza stampa ufficiale del film', TRUE, 'IA (Daily Sync)', 'IA Verificata', 0, 1, '2026-11-02T10:17:59.845217+00:00'),
('ed57aaa0-2111-43bd-a249-731f3cbe7415', 187, 'Segreti di produzione', 'La colonna sonora dei Brown Eyed Girls', 'Il celebre gruppo vocale femminile sudcoreano Brown Eyed Girls ha registrato il brano principale della colonna sonora intitolato ''Always'', contribuendo alla promozione del film attraverso un videoclip ufficiale che mescolava scene della pellicola e riprese in studio.', 'Crediti musicali ufficiali della OST del film', TRUE, 'IA (Daily Sync)', 'IA Verificata', 0, 2, '2026-11-02T10:17:59.845217+00:00');
INSERT INTO public.movie_trivia ("id", "film_id", "categoria", "titolo", "descrizione", "fonte", "approvato", "inserito_da", "provenienza", "likes", "ordine", "created_at") VALUES
('71b7d588-2973-4e69-bd1c-dead742a8947', 268, 'Segreti di produzione', 'La continuità della partnership con Jonny Greenwood', 'Per la colonna sonora del film, Paul Thomas Anderson ha rinnovato il sodalizio artistico con Jonny Greenwood dei Radiohead, segnando la loro quinta collaborazione consecutiva dopo ''Il petroliere'', ''The Master'', ''Vizio di forma'' e ''Il filo nascosto''.', 'Note di produzione ufficiali della Warner Bros.', TRUE, 'IA (Daily Sync)', 'IA Verificata', 0, 0, '2026-11-02T10:22:41.153865+00:00'),
('41b8f7d6-66db-4913-be62-e8682453e60f', 268, 'Curiosità & Retroscena', 'Il ritorno del direttore della fotografia Michael Bauman', 'Le riprese della pellicola sono state affidate a Michael Bauman, collaboratore storico di Anderson già direttore della fotografia in ''Licorice Pizza'', confermando la volontà del regista di mantenere una forte coerenza visiva nella sua squadra tecnica.', 'Variety Production Report', TRUE, 'IA (Daily Sync)', 'IA Verificata', 0, 1, '2026-11-02T10:22:41.153865+00:00'),
('f6060285-e54c-4ace-9e9d-d8580172398d', 268, 'Effetti speciali & Trucco', 'La scelta della pellicola a 35mm e le specifiche tecniche', 'Fedele al rifiuto del digitale per le sue produzioni principali, Anderson ha girato l''intero lungometraggio utilizzando negativi in pellicola 35mm, avvalendosi dei laboratori di sviluppo di Fotokem a Los Angeles per la gestione del photochemical timing.', 'American Cinematographer Magazine', TRUE, 'IA (Daily Sync)', 'IA Verificata', 0, 2, '2026-11-02T10:22:41.153865+00:00'),
('732220aa-9955-4aeb-9c3b-dbf4541824bc', 303, 'Casting & Scelte', 'La scelta di Gérard Depardieu', 'L''attore francese Gérard Depardieu ha accettato di interpretare il ruolo minore del cuoco di bordo cinico e brutale principalmente per la sua stima nei confronti del regista Ang Lee, apparendo in un cameo significativo nella prima parte del film prima del naufragio.', 'Note di produzione ufficiali 20th Century Fox', TRUE, 'IA (Daily Sync)', 'IA Verificata', 0, 0, '2026-11-02T11:50:24.264367+00:00'),
('b646538e-f5b3-4033-9d8f-e7341a74809d', 303, 'Curiosità & Retroscena', 'La collaborazione con Yann Martel', 'L''autore del romanzo omonimo, Yann Martel, ha fatto visita alla troupe sul set di Taiwan durante le riprese e ha espresso pubblicamente la sua ammirazione per come Ang Lee sia riuscito a tradurre visivamente i concetti filosofici e religiosi del libro senza snortarne l''essenza spirituale.', 'Intervista promozionale al Festival del Cinema di Roma 2012', TRUE, 'IA (Daily Sync)', 'IA Verificata', 0, 1, '2026-11-02T11:50:24.264367+00:00'),
('3f3d4683-0aad-47b0-978b-08117c0acf45', 303, 'Segreti di produzione', 'Il coordinamento dei movimenti animali', 'Per garantire che le tigri digitali si muovessero con assoluto realismo, il supervisore degli effetti visivi Bill Westenhofer ha studiato centinaia di ore di filmati naturalistici e si è avvalso della consulenza del celebre addestratore di animali Thierry Le Portier.', 'Articolo tecnico di American Cinematographer, 2013', TRUE, 'IA (Daily Sync)', 'IA Verificata', 0, 2, '2026-11-02T11:50:24.264367+00:00'),
('2b0178a9-a937-4339-8128-90ea0ed408c0', 303, 'Effetti speciali & Trucco', 'L''uso pionieristico della tecnologia RealD', 'Ang Lee ha girato interamente il film in nativo 3D e non in post-produzione, collaborando strettamente con il direttore della fotografia Claudio Miranda per studiare come la luce riflettesse sull''acqua e sul pelo digitale della tigre in un formato tridimensionale.', 'Commento audio del regista nel Blu-ray ufficiale', TRUE, 'IA (Daily Sync)', 'IA Verificata', 0, 3, '2026-11-02T11:50:24.264367+00:00'),
('e10555dd-23c0-437a-8f45-66971d0e6989', 303, 'Casting & Scelte', 'Il cameo vocale di Adil Hussain', 'L''attore indiano Adil Hussain, che interpreta il padre di Pi, ha lavorato intensamente con un dialetto specifico e ha doppiato gran parte dei suoi dialoghi in post-produzione per accentuare il tono protettivo e paterno del personaggio rispetto al romanzo.', 'Making-of incluso nei contenuti speciali del home video', TRUE, 'IA (Daily Sync)', 'IA Verificata', 0, 4, '2026-11-02T11:50:24.264367+00:00'),
('5504cfb4-4ea8-44ba-a63f-82dc0d152e6c', 340, 'Segreti di produzione', 'La colonna sonora registrata prima del montaggio', 'Il compositore James Newton Howard ha scritto e registrato gran parte della colonna sonora orchestrale basandosi unicamente sulla lettura della sceneggiatura e sui concept art. Shyamalan ha poi montato diverse sequenze chiave del film seguendo rigorosamente il ritmo già stabilito dalle tracce musicali.', 'Documentario ''The Making of Signs'' - Extra Blu-ray', TRUE, 'IA (Daily Sync)', 'IA Verificata', 0, 3, '2026-11-02T14:51:17.613497+00:00'),
('542a761a-7952-403f-bdb9-b74f0e662734', 204, 'Casting & Scelte', 'Il radicale cambio di look di Natalie Dormer', 'Per interpretare Cressida, Natalie Dormer ha realmente rasato metà della sua testa, nonostante la produzione avesse inizialmente considerato l''uso di una calotta in lattice. Il regista Francis Lawrence ha optato per questo taglio asimmetrico invece della rasatura totale prevista nel libro per dare al personaggio un''estetica più moderna e ''urban'' tipica dei ribelli del Campidoglio.', 'Intervista a Entertainment Weekly / Making-of ufficiale', TRUE, 'IA (Daily Sync)', 'IA Verificata', 0, 0, '2026-11-02T10:12:09.883263+00:00'),
('9d3b3e1e-a2c5-4a0b-9b99-5988dc65244a', 204, 'Curiosità & Retroscena', 'Il recasting di Buttercup per fedeltà ai fan', 'Il gatto di Prim, Buttercup, è stato sostituito con un nuovo esemplare rispetto al primo film per soddisfare le proteste dei lettori. Nel primo capitolo era stato usato un gatto bianco e nero, ma il regista Francis Lawrence ha insistito per utilizzare un gatto tigrato rosso che rispecchiasse esattamente la descrizione fisica fornita da Suzanne Collins nei romanzi.', 'Intervista al regista Francis Lawrence / Note di produzione', TRUE, 'IA (Daily Sync)', 'IA Verificata', 0, 1, '2026-11-02T10:12:09.883263+00:00'),
('7af54b8a-5a47-4319-86b8-bf62c5a72179', 204, 'Effetti speciali & Trucco', 'L''investimento per la parrucca di Jennifer Lawrence', 'Poiché Jennifer Lawrence aveva tagliato i capelli molto corti (pixie cut) prima dell''inizio delle riprese, la produzione ha dovuto far realizzare diverse parrucche personalizzate dal valore di circa 30.000 dollari l''una. Le protesi sono state create con capelli umani di altissima qualità per garantire che il movimento della chioma di Katniss risultasse naturale durante le intense sequenze d''azione.', 'Intervista alla hair stylist Linda Flowers / Making-of', TRUE, 'IA (Daily Sync)', 'IA Verificata', 0, 2, '2026-11-02T10:12:09.883263+00:00'),
('c87c983e-bd8a-4507-8e24-5f7955142910', 204, 'Segreti di produzione', 'Le rovine reali del Distretto 12', 'Le scene che mostrano le macerie del Distretto 12 non sono state girate in un set ricostruito, ma presso un vecchio cotonificio abbandonato a Griffin, in Georgia. La struttura era stata parzialmente distrutta da un vero incendio anni prima, permettendo alla produzione di utilizzare detriti e strutture bruciate autentiche per rappresentare la devastazione causata dai bombardamenti di Capitol City.', 'Note di produzione / Location scouting report', TRUE, 'IA (Daily Sync)', 'IA Verificata', 0, 3, '2026-11-02T10:12:09.883263+00:00'),
('4ac35701-ea94-488f-9a28-cc10a3e22a33', 204, 'Curiosità & Retroscena', 'Lorde e la curatela della colonna sonora', 'La cantante Lorde è stata nominata curatrice ufficiale della colonna sonora del film a soli 17 anni, un primato assoluto per il franchise. Ha selezionato personalmente artisti come Kanye West, Chvrches e Grace Jones, lavorando a stretto contatto con il regista per assicurarsi che ogni traccia riflettesse l''atmosfera politica e rivoluzionaria della pellicola.', 'Comunicato ufficiale Lionsgate / Intervista a Billboard', TRUE, 'IA (Daily Sync)', 'IA Verificata', 0, 4, '2026-11-02T10:12:09.883263+00:00'),
('53f38514-679e-420a-9d2f-8eb5e60f99af', 204, 'Aneddoti dal set', 'La dieta estrema di Liam Hemsworth', 'Liam Hemsworth ha seguito un regime alimentare rigidissimo per apparire visibilmente deperito e provato dalle privazioni del Distretto 13. L''attore ha dichiarato di aver ricevuto consigli dal fratello Chris su come perdere peso velocemente, ammettendo che la fame costante lo ha aiutato a mantenere lo stato d''animo cupo e irritabile necessario per il personaggio di Gale.', 'Intervista al The Tonight Show Starring Jimmy Fallon', TRUE, 'IA (Daily Sync)', 'IA Verificata', 0, 5, '2026-11-02T10:12:09.883263+00:00'),
('ba44b8f3-41f4-409c-a53c-68b6e5d880a8', 204, 'Casting & Scelte', 'L''audizione a distanza di Mahershala Ali', 'Mahershala Ali ha ottenuto il ruolo di Boggs inviando un video-provino registrato autonomamente mentre si trovava sul set della serie ''House of Cards''. Grande fan dei libri, Ali ha lottato per la parte poiché considerava Boggs uno dei pochi personaggi dotati di una bussola morale incrollabile all''interno del conflitto tra Coin e Snow.', 'Intervista a Variety / Contenuti extra DVD', TRUE, 'IA (Daily Sync)', 'IA Verificata', 0, 6, '2026-11-02T10:12:09.883263+00:00'),
('aea4d489-0668-496c-861b-f65fadcfe9c5', 204, 'Aneddoti dal set', 'La preparazione di Elden Henson per il ruolo di Pollux', 'Per interpretare l''Avox Pollux, Elden Henson ha studiato approfonditamente il linguaggio dei segni americano (ASL) per comunicare con il fratello Castor sullo schermo. Nonostante il personaggio sia muto, l''attore ha lavorato con un consulente specializzato per rendere la sua gestualità e la sua espressività facciale emotivamente cariche e realistiche.', 'Note di produzione / Intervista al cast', TRUE, 'IA (Daily Sync)', 'IA Verificata', 0, 7, '2026-11-02T10:12:09.883263+00:00'),
('ab9d72d4-47d9-41cb-9d2c-d113e55cb0ce', 204, 'Segreti di produzione', 'Attori come veri operatori di ripresa', 'Durante le sequenze dei ''Propos'', gli attori che interpretavano la troupe di Cressida, in particolare Wes Chatham (Castor), hanno effettivamente manovrato le telecamere a spalla. Il regista ha voluto che le inquadrature fossero realizzate dagli attori stessi per ottenere uno stile visivo sporco, instabile e autenticamente documentaristico, tipico di una troupe che opera in zona di guerra.', 'Commento audio del regista / Making-of ''The Mockingjay Lives''', TRUE, 'IA (Daily Sync)', 'IA Verificata', 0, 8, '2026-11-02T10:12:09.883263+00:00'),
('21875e5b-3743-4489-9e6e-748dd1a303e1', 204, 'Segreti di produzione', 'Il freddo autentico dell''ospedale del Distretto 8', 'La sequenza dell''ospedale nel Distretto 8 è stata girata nei Pullman Yard di Atlanta, un complesso industriale privo di riscaldamento. Durante le riprese invernali, le temperature erano così basse che il vapore che esce dalla bocca degli attori è reale; la produzione ha dovuto fornire coperte termiche e riscaldatori portatili a centinaia di comparse tra un ciak e l''altro.', 'Making-of ufficiale / Reportage dal set di Atlanta', TRUE, 'IA (Daily Sync)', 'IA Verificata', 0, 9, '2026-11-02T10:12:09.883263+00:00'),
('115dae3a-fe79-4a49-be47-fa3ded3e3196', 206, 'Curiosità & Retroscena', 'Il ritorno del regista Francis Lawrence', 'Francis Lawrence, che aveva già diretto tre dei quattro film della saga originale di ''Hunger Games'' (''La ragazza di fuoco'' e i due capitoli di ''Il canto della rivolta''), è tornato dietro la macchina da presa dopo aver letto in anteprima il manoscritto del romanzo di Suzanne Collins ancora prima della sua pubblicazione ufficiale nel 2020.', 'Note di produzione ufficiali Lionsgate', TRUE, 'IA (Daily Sync)', 'IA Verificata', 0, 0, '2026-11-02T10:12:26.51433+00:00'),
('0f82f5e9-6504-424f-9110-c4074e32e2f6', 206, 'Segreti di produzione', 'La connessione familiare della costumista', 'La costumista Trish Summerville, già premiata per il suo lavoro in ''Hunger Games: La ragazza di fuoco'', ha disegnato i costumi del film ispirandosi esplicitamente alle divise militari del periodo post-bellico della metà del XX secolo, consultando gli archivi storici europei per conferire a Capitol City un aspetto austero e totalitario.', 'Intervista di Trish Summerville per Vogue', TRUE, 'IA (Daily Sync)', 'IA Verificata', 0, 1, '2026-11-02T10:12:26.51433+00:00'),
('65aacce5-3974-401a-985a-bee728aea944', 206, 'Aneddoti dal set', 'La scelta della location tedesca per il tributo al passato', 'Per girare le sequenze ambientate nello stadio che ospita i Decimi Hunger Games, la produzione ha utilizzato il famigerato Jahrhunderthalle di Breslavia, in Polonia, un edificio storico protetto dall''UNESCO caratterizzato da una monumentale cupola in cemento armato risalente al 1913.', 'Giornale di bordo della produzione e location report', TRUE, 'IA (Daily Sync)', 'IA Verificata', 0, 2, '2026-11-02T10:12:26.51433+00:00'),
('c8569f5f-c21b-476e-8dd2-f60391e0c0e4', 206, 'Citazioni & Easter Egg', 'Il cameo vocale di Willow Shields', 'L''attrice Willow Shields, che interpretava Primrose Everdeen nella saga originale, ha rivelato in diverse interviste il suo profondo legame con la troupe, sebbene in questo prequel non compaia fisicamente ma la sua presenza sia stata celebrata durante le anteprime stampa dai membri storici della troupe.', 'Dichiarazioni pubbliche dell''attrice e stampa di settore', TRUE, 'IA (Daily Sync)', 'IA Verificata', 0, 3, '2026-11-02T10:12:26.51433+00:00'),
('6c970282-16d2-43cc-b865-e1474804917b', 205, 'Aneddoti dal set', 'L''infortunio alla caviglia di Jennifer Lawrence durante le riprese', 'Durante le riprese della sequenza in cui Katniss corre tra i fumogeni e le macerie a Capitol City, Jennifer Lawrence si è accidentalmente infortunata alla caviglia dopo essere inciampata mentre indossava l''attrezzatura tattica e gli stivali di scena, costringendo la produzione a fermare temporaneamente il set per permetterle di recuperare.', 'Note di produzione ufficiali Lionsgate e interviste sul set', TRUE, 'IA (Daily Sync)', 'IA Verificata', 0, 0, '2026-11-02T10:12:18.405839+00:00'),
('baf149fe-06e4-4775-922e-ca372d34eb6f', 205, 'Casting & Scelte', 'La gravidanza nascosta di Jena Malone sul set', 'L''attrice Jena Malone, che riprende il ruolo di Johanna Mason, ha scoperto di essere incinta durante le riprese delle scene aggiuntive e dei reshoot del film. La costumista Trish Summerville e il reparto trucco hanno dovuto lavorare con grande attenzione e ingegno per nascondere la gravidanza attraverso abiti larghi e inquadrature studiate.', 'Dichiarazioni pubbliche dell''attrice e reportage di produzione', TRUE, 'IA (Daily Sync)', 'IA Verificata', 0, 1, '2026-11-02T10:12:18.405839+00:00'),
('404de5b9-6e93-4773-a57a-716ed2ebb138', 205, 'Effetti speciali & Trucco', 'Il divieto di usare veri animali per i lucertoloni mutanti', 'Per la brutale sequenza nelle fogne contro i lucertoloni mutanti albini, il supervisore degli effetti visivi Charles Gibson e il regista Francis Lawrence decisero inizialmente di valutare l''uso di veri rettili addestrati per alcune inquadrature ravvicinate, ma l''idea fu subito scartata per motivi di sicurezza e benessere animale, affidandosi interamente a stuntmen in tuta motion capture e protesi digitali in post-produzione.', 'The Making of Mockingjay - Part 2 / Commento audio del regista', TRUE, 'IA (Daily Sync)', 'IA Verificata', 0, 2, '2026-11-02T10:12:18.405839+00:00'),
('7211272b-463b-4800-b595-629ae77c2870', 205, 'Segreti di produzione', 'L''utilizzo delle vere armi ad aria compressa', 'Per garantire la massima veridicità nelle scene di guerriglia urbana a Capitol City, agli attori principali tra cui Liam Hemsworth e Josh Hutcherson fu richiesto di maneggiare fucili e armi di scena dotati di meccanismi ad aria compressa realistici, che emettevano un forte rinculo e proiettavano bossoli finti anziché ricorrere unicamente a effetti digitali aggiunti in seguito.', 'Featurette ''The Armory of District 13'' nel Blu-ray ufficiale', TRUE, 'IA (Daily Sync)', 'IA Verificata', 0, 3, '2026-11-02T10:12:18.405839+00:00'),
('49fb0124-5fa1-4e0d-b05f-041e9423ee30', 205, 'Casting & Scelte', 'Il vero gatto Buttercup e la sostituzione dell''animale', 'Nel passaggio dal primo capitolo (dove il gatto di Primrose, Buttercup, era un felino rosso tabby a pelo corto) ai film successivi diretti da Francis Lawrence, la produzione decise di sostituire l''animale con un gatto randagio persiano grigio e bianco, decisione che scatenò inizialmente le proteste dei fan più accaniti dei libri ma che fu difesa dal regista per dare un aspetto più vissuto al micio.', 'Intervista di Francis Lawrence a Entertainment Weekly', TRUE, 'IA (Daily Sync)', 'IA Verificata', 0, 4, '2026-11-02T10:12:18.405839+00:00'),
('62ef11bf-b0d6-42f3-97bb-59110bd2b06b', 207, 'Segreti di produzione', 'L''origine della casa di Gru e il vero sobborgo americano', 'Il design della cupa e gotica abitazione di Gru, che stona visivamente con le villette suburbane color pastello che la circondano, è stato fortemente voluto dal production designer Eric Guillon. La villa si ispira alle architetture della California degli anni Cinquanta e Sessanta, mescolando elementi delle case Eichler con i classici stilemi dei cattivi dei film di James Bond.', 'Art of Despicable Me - Official Artbook', TRUE, 'IA (Daily Sync)', 'IA Verificata', 0, 0, '2026-11-02T10:12:33.573847+00:00'),
('93a4e2c4-6d47-4925-8272-fc1bdc53db09', 207, 'Casting & Scelte', 'La scelta iniziale di Jean Reno per il padre di Gru', 'Nelle primissime fasi di sviluppo della sceneggiatura, i produttori avevano pensato all''attore francese Jean Reno per dare voce al defunto padre di Gru, il temibile Malchoire, un personaggio che in seguito è stato profondamente ridimensionato prima di arrivare alla versione finale del film.', 'Production Notes Universal Pictures (2010)', TRUE, 'IA (Daily Sync)', 'IA Verificata', 0, 1, '2026-11-02T10:12:33.573847+00:00'),
('da2d5ad0-e7d7-4373-b1e6-5b1dbd4ddb59', 207, 'Casting & Scelte', 'Will Arnett e il ruolo scartato del signor Perkins', 'L''attore e doppiatore Will Arnett era stato originariamente contattato e provinato per interpretare una versione differente del banchiere Mr. Perkins, prima che la parte venisse affidata definitivamente a Will Arnett stesso ma con una revisione totale dei dialoghi e delle battute comiche.', 'Audio Commentary Directors & Cast - Blu-ray Edition', TRUE, 'IA (Daily Sync)', 'IA Verificata', 0, 2, '2026-11-02T10:12:33.573847+00:00'),
('7247fb2a-2977-4e38-a3fd-3ceee29fc038', 214, 'Segreti di produzione', 'La scelta della colonna sonora affidata a Jóhann Jóhannsson', 'Denis Villeneuve ha scelto il compositore islandese Jóhann Jóhannsson per creare le musiche del film, inaugurando una fortunata collaborazione artistica che sarebbe proseguita anche nei successivi ''Sicario'' e ''Arrival''. La partitura musicale è stata concepita per riflettere l''atmosfera cupa e claustrofobica della narrazione, usando strumenti a corda e melodie minimaliste.', 'Note di produzione ufficiali e intervista a Denis Villeneuve', TRUE, 'IA (Daily Sync)', 'IA Verificata', 0, 0, '2026-11-02T10:13:19.816922+00:00'),
('e6112bc9-6e59-4f17-892f-448e0ec4187a', 214, 'Segreti di produzione', 'La fotografia naturalistica di Roger Deakins', 'Il celebre direttore della fotografia Roger Deakins ha optato per un''illuminazione il più possibile naturale e desaturata, sfruttando la luce grigia e plumbea della Georgia per trasmettere un senso costante di freddo e disperazione. Deakins ha evitato l''uso eccessivo di luci artificiali sul set per dare alla pellicola un look documentaristico e crudo.', 'Articolo di American Cinematographer su Prisoners', TRUE, 'IA (Daily Sync)', 'IA Verificata', 0, 1, '2026-11-02T10:13:19.816922+00:00'),
('75f9c5cd-2b0e-40d8-988c-89a07ddcff3c', 214, 'Curiosità & Retroscena', 'Il blocco di legno e il labirinto come oggetti di scena', 'Il blocco di legno con il labirinto che compare ripetutamente nel film è stato realizzato appositamente dal reparto scenografia ed è diventato un elemento chiave per la psicologia del personaggio di Alex Jones. Durante le riprese, Paul Dano manipolava spesso questo oggetto per accentuare l''inquietudine e la regressione infantile del suo personaggio.', 'Commento audio del regista Denis Villeneuve', TRUE, 'IA (Daily Sync)', 'IA Verificata', 0, 2, '2026-11-02T10:13:19.816922+00:00'),
('6a4125c2-f9ca-4cd1-946a-1f4a660f9214', 214, 'Aneddoti dal set', 'L''infortunio sul set di Hugh Jackman', 'Durante la drammatica sequenza in cui Keller Dover insegue il furgone sospetto tirando dei pugni ai finestrini, Hugh Jackman si è realmente ferito alle mani a causa del freddo intenso e della foga della scena. L''attore ha continuato a girare senza interrompere la ripresa, sfruttando il dolore fisico reale per accrescere la furia del suo personaggio.', 'Intervista a Hugh Jackman per il press tour del film', TRUE, 'IA (Daily Sync)', 'IA Verificata', 0, 3, '2026-11-02T10:13:19.816922+00:00'),
('f889684a-e8e8-496d-bc39-d3b6ad8c15a1', 214, 'Curiosità & Retroscena', 'La preparazione sul campo di Jake Gyllenhaal', 'Per prepararsi al ruolo del detective Loki, Jake Gyllenhaal ha trascorso diverse settimane affiancando i veri reparti di polizia e investigatori privati specializzati in persone scomparse in Pennsylvania, osservando le loro procedure e il modo in cui gestiscono il logorio emotivo dei casi irrisolti.', 'Intervista promozionale a Jake Gyllenhaal', TRUE, 'IA (Daily Sync)', 'IA Verificata', 0, 4, '2026-11-02T10:13:19.816922+00:00'),
('9ad0b18f-aec4-4854-9350-fd06ef263ec7', 272, 'Segreti di produzione', 'La regia divisa a tre con Venier', 'Sebbene nei credit ufficiali la regia sia attribuita a Aldo, Giovanni e Giacomo insieme a Morgan Meneghetti, in realtà il film ha visto una forte direzione d''attori coordinata con l''esperienza di Massimo Venier, storico collaboratore del trio che ha curato la regia dei loro precedenti film.', 'Note di produzione ufficiali del DVD Medusa', TRUE, 'IA (Daily Sync)', 'IA Verificata', 0, 0, '2026-11-02T10:23:28.606814+00:00'),
('390621ab-2e9f-4743-8b49-34d51642668a', 206, 'Casting & Scelte', 'La preparazione musicale di Rachel Zegler con le chitarre storiche', 'Per interpretare fedelmente Lucy Gray Baird e le sue esibizioni dal vivo, Rachel Zegler ha imparato a suonare la chitarra acustica utilizzando strumenti d''epoca forniti dal dipartimento di scenografia, coerenti con l''estetica rurale e folk americana degli anni ''30.', 'Featurette ''The Music of Panem'' nel Blu-ray ufficiale', TRUE, 'IA (Daily Sync)', 'IA Verificata', 0, 4, '2026-11-02T10:12:26.51433+00:00'),
('11d91da8-bf42-409d-922a-835acb4eb444', 206, 'Curiosità & Retroscena', 'Le origini letterarie del nome di Coriolanus', 'L''autrice Suzanne Collins ha ammesso nelle interviste promozionali del libro e del film di aver tratto il nome del giovane Snow dal generale romano Caio Marcio Coriolano, celebre protagonista della tragedia omonima di William Shakespeare, riprendendone i temi dell''orgoglio e della corruzione politica.', 'Intervista ufficiale di Suzanne Collins con Scholastic', TRUE, 'IA (Daily Sync)', 'IA Verificata', 0, 5, '2026-11-02T10:12:26.51433+00:00'),
('64f4ce78-d435-4079-b07d-846212779ca6', 189, 'Casting & Scelte', 'La genesi del legame tra Reiner ed Ephron', 'Il progetto nacque ufficialmente durante un incontro a Beverly Hills tra il regista Rob Reiner, il produttore Andrew Scheinman e la sceneggiatrice Nora Ephron. Reiner era un uomo divorziato e cinico rispetto alle relazioni, un atteggiamento che fornì l''ispirazione primaria per la struttura psicologica del protagonista Harry Burns.', 'Commento audio del regista Rob Reiner nell''edizione DVD del ventennale', TRUE, 'IA (Daily Sync)', 'IA Verificata', 0, 0, '2026-11-02T10:18:11.734813+00:00'),
('ea61006f-ce6f-416f-bca4-e660c0ee2ae4', 189, 'Segreti di produzione', 'La vera storia dietro le interviste alle coppie anziane', 'Le brevi interviste con coppie anziane inserite durante il film non utilizzano attori professionisti, ma veri anziani reclutati da un team di ricerca. Le loro storie d''amore reali sono state registrate su audiocassetta prima di essere fedelmente ricreate da attori non professionisti davanti alla macchina da presa.', 'Documentario ''How Harry Met Sally'' incluso nei contenuti speciali Blu-ray', TRUE, 'IA (Daily Sync)', 'IA Verificata', 0, 1, '2026-11-02T10:18:11.734813+00:00'),
('65d6356f-e8b6-4b26-9a71-bb6d44b3f23d', 189, 'Curiosità & Retroscena', 'Il cambio di finale imposto dallo studio', 'Nella sceneggiatura originale di Nora Ephron, Harry e Sally non si sarebbero sposati alla fine, ma si sarebbero semplicemente separati dopo aver capito di essere troppo diversi per funzionare come coppia. Fu lo stesso Rob Reiner a cambiare idea durante le riprese dopo aver incontrato la sua futura moglie, la fotografa Michele Singer, decidendo per un epilogo romantico e lieto.', 'Intervista retrospettiva a Nora Ephron per la Directors Guild of America', TRUE, 'IA (Daily Sync)', 'IA Verificata', 0, 2, '2026-11-02T10:18:11.734813+00:00'),
('0704dbb8-e0cf-4f4e-b1f4-55ecc7020d58', 189, 'Casting & Scelte', 'Il ruolo chiave di Billy Crystal nella riscrittura del personaggio', 'Quando Billy Crystal salì a bordo del progetto, lavorò a stretto contatto con Nora Ephron per diverse settimane per rendere il personaggio di Harry meno caustico e più vulnerabile. Crystal inserì molte delle sue battute improvvisate dal vivo e sfruttò la sua vera amicizia decennale con Carrie Fisher (che nel film interpreta Marie) per creare una chimica naturale sul set.', 'Libro ''It Had to Be You: Some Tales from Hollywood'' di Billy Crystal', TRUE, 'IA (Daily Sync)', 'IA Verificata', 0, 3, '2026-11-02T10:18:11.734813+00:00'),
('b9b503d2-0c08-4c3b-837c-47847b196bf9', 272, 'Casting & Scelte', 'Il cameo di Paola Cortellesi', 'All''interno della pellicola compare in un piccolo ruolo non accreditato anche l''attrice e comica Paola Cortellesi, amica e collega del trio dai tempi dei laboratori teatrali milanesi e della trasmissione televisiva Mai dire Gol.', 'Crediti del film e archivio storico del cast', TRUE, 'IA (Daily Sync)', 'IA Verificata', 0, 1, '2026-11-02T10:23:28.606814+00:00'),
('0657cd26-1f1d-41be-8007-75910b42121c', 272, 'Aneddoti dal set', 'La location della casa di Giovanni', 'L''appartamento milanese in cui si svolgono alcune delle scene più intime e domestiche dei protagonisti è stato ricostruito all''interno di un vero stabile in zona Navigli, scelto per mantenere quell''atmosfera di autentica periferia lombarda.', 'Backstage ufficiale presente nel cofanetto speciale Medusa', TRUE, 'IA (Daily Sync)', 'IA Verificata', 0, 2, '2026-11-02T10:23:28.606814+00:00'),
('126fb53a-1ea2-4de5-aca3-bb9d65e9495f', 53, 'Curiosità & Retroscena', 'Il debutto alla regia di Douglas Aarniokoski', 'Douglas Aarniokoski ha fatto il suo debutto come regista cinematografico con questo film, dopo aver lavorato a lungo come aiuto regista e collaboratore di fiducia di registi come Robert Rodriguez e Quentin Tarantino.', 'Note di produzione ufficiali di Dimension Films', TRUE, 'IA (Daily Sync)', 'IA Verificata', 0, 0, '2026-11-02T14:45:19.747166+00:00'),
('5a4c5f51-6107-41a7-be6e-e3ea013956ba', 53, 'Casting & Scelte', 'Il ritorno di Christopher Lambert e Adrian Paul', 'Il film unisce per la prima volta sul grande schermo Connor MacLeod (Christopher Lambert) e Duncan MacLeod (Adrian Paul), il protagonista della fortunata serie televisiva di successo.', 'Materiale promozionale e pressbook cinematografico del 2000', TRUE, 'IA (Daily Sync)', 'IA Verificata', 0, 1, '2026-11-02T14:45:19.747166+00:00'),
('0aea823f-cb1c-4717-bb43-95ebefe271b8', 53, 'Curiosità & Retroscena', 'La morte di Connor MacLeod', 'La decisione drastica di far morire il personaggio di Connor MacLeod per mano di Duncan fu presa per passare ufficialmente il testimone del franchise televisivo e cinematografico al personaggio interpretato da Adrian Paul.', 'Interviste al produttore Peter S. Davis nel making-of del DVD', TRUE, 'IA (Daily Sync)', 'IA Verificata', 0, 2, '2026-11-02T14:45:19.747166+00:00'),
('cb4af08f-35e9-4652-948f-c2b5b88ae3e9', 53, 'Casting & Scelte', 'Il cattivo Jacob Kell interpretato da Bruce Payne', 'L''attore britannico Bruce Payne è stato scelto per il ruolo del potente e spietato antagonista Jacob Kell, grazie alla sua consolidata esperienza nell''interpretare cattivi memorabili nel cinema d''azione e fantastico.', 'Crediti del cast e retroscena di pre-produzione', TRUE, 'IA (Daily Sync)', 'IA Verificata', 0, 3, '2026-11-02T14:45:19.747166+00:00'),
('93b78575-ba96-49c3-9ef9-0a7cbcfd2345', 53, 'Aneddoti dal set', 'La gestione delle scene di spada con Bob Anderson', 'Il leggendario maestro d''armi Bob Anderson, già schermidore olimpico e coreografo per la trilogia originale di Star Wars e Il Signore degli Anelli, ha curato personalmente i complessi duelli all''arma bianca sul set.', 'Speciali backstage e documentario sulla realizzazione delle scene d''azione', TRUE, 'IA (Daily Sync)', 'IA Verificata', 0, 4, '2026-11-02T14:45:19.747166+00:00'),
('63e592b8-f6b1-4ec2-8b2f-a634e5323ccb', 53, 'Segreti di produzione', 'Scenografie e location tra Romania e Canada', 'Sebbene la storia si muova tra varie epoche e luoghi iconici come New York, gran parte delle riprese si è svolta in Romania e a Toronto, sfruttando le agevolazioni produttive e maestranze locali per ricostruire i set urbani.', 'Database delle location cinematografiche e report di produzione', TRUE, 'IA (Daily Sync)', 'IA Verificata', 0, 5, '2026-11-02T14:45:19.747166+00:00'),
('c28b44a6-420f-4ab2-bcce-6f4da38ee4c1', 113, 'Curiosità & Retroscena', 'La genesi come spec script indipendente', 'Il film è nato originariamente da una sceneggiatura speculativa intitolata ''God Particle'', scritta da Oren Uziel, che non aveva alcun legame iniziale con il franchise di Cloverfield creato da J.J. Abrams.', 'Note di produzione Paramount Pictures', TRUE, 'IA (Daily Sync)', 'IA Verificata', 0, 0, '2026-11-02T14:45:53.791594+00:00'),
('552e9505-1acc-464a-af61-eae39f83b1b0', 113, 'Curiosità & Retroscena', 'L''acquisizione last minute di Netflix', 'Dopo aver subito numerosi rinvii della data di uscita cinematografica, la Paramount ha venduto i diritti mondiali del film a Netflix per circa 50 milioni di dollari appena poche settimane prima della sua distribuzione.', 'The Hollywood Reporter - Report finanziario febbraio 2018', TRUE, 'IA (Daily Sync)', 'IA Verificata', 0, 1, '2026-11-02T14:45:53.791594+00:00'),
('9b26356a-5999-420d-9c4a-e6d0b2b3f9be', 208, 'Casting & Scelte', 'Il cameo vocale di Miranda Cosgrove e le figlie di Gru', 'Miranda Cosgrove è tornata a doppiare la figlia maggiore di Gru, Margo, mentre le attrici Dana Gaier e Elsie Fisher hanno ripreso i ruoli rispettivamente di Edith e Agnes. Per mantenere intatta la dinamica familiare, le attrici hanno registrato alcune delle loro sessioni vocali insieme nello stesso studio, un''eccezione rispetto alla normale prassi dell''animazione.', 'Note di produzione ufficiali Universal Pictures', TRUE, 'IA (Daily Sync)', 'IA Verificata', 0, 0, '2026-11-02T10:12:40.713886+00:00'),
('2e67a970-aff2-4bba-b795-e6778532b800', 190, 'Segreti di produzione', 'La scelta del vero autore dei brani giovanili', 'Il regista Claude Pinoteau scelse personalmente il gruppo Cook da Books, guidato da Cook da Books e con la collaborazione vocale di Richard Sanderson, dopo aver ascoltato diversi demo scartati da altre produzioni. La direzione musicale fu affidata a Vladimir Cosma, che impose sonorità pop anglosassoni per dare al film un respiro internazionale.', 'Note di produzione e documentario retrospettivo dell''edizione Blu-ray Gaumont', TRUE, 'IA (Daily Sync)', 'IA Verificata', 0, 0, '2026-11-02T10:18:18.72653+00:00'),
('6482fb44-ef7a-43fc-9e5f-cc7b4ea588f5', 190, 'Casting & Scelte', 'Il contratto lampo con la Gaumont', 'Dopo il provino, Sophie Marceau fu blindata dalla Gaumont con un contratto cinematografico a lungo termine in sole quarantotto ore. L''amministratore delegato Daniel Toscan du Plantier comprese immediatamente il potenziale commerciale della giovane attrice e impose una clausola di esclusività per evitare che la concorrenza la scritturasse.', 'Autobiografia di Daniel Toscan du Plantier e archivi storici Gaumont', TRUE, 'IA (Daily Sync)', 'IA Verificata', 0, 1, '2026-11-02T10:18:18.72653+00:00'),
('4452ff6e-279f-457c-903c-6cbd73172951', 190, 'Aneddoti dal set', 'La gestione della giovane età sul set', 'Per rispettare le leggi francesi sul lavoro minorile e proteggere la quattordicenne Sophie Marceau, la produzione dovette organizzare le riprese limitando rigorosamente le ore giornaliere sul set. Claude Brasseur e Brigitte Fossey si occuparono personalmente di guidarla tra una ripresa e l''altra per farla sentire a proprio agio e non far pesare i ritmi professionali.', 'Intervista retrospettiva a Brigitte Fossey per Télérama', TRUE, 'IA (Daily Sync)', 'IA Verificata', 0, 2, '2026-11-02T10:18:18.72653+00:00'),
('49c51f13-fefe-44d8-8466-224de3e7ba9f', 274, 'Segreti di produzione', 'Il budget ridotto e la minaccia della distribuzione in home video', 'Il film fu prodotto dalla Vestron Pictures con un budget limitato a circa 5 milioni di dollari. Visto il materiale girato, i dirigenti dello studio considerarono seriamente l''idea di saltare l''uscita nelle sale cinematografiche per distribuire la pellicola direttamente in VHS, ipotesi sventata solo grazie alla tenacia della sceneggiatrice Eleanor Bergstein e del produttore Linda Gottlieb.', 'Documentario ''Dirty Dancing: The E! True Hollywood Story''', TRUE, 'IA (Daily Sync)', 'IA Verificata', 0, 0, '2026-11-02T10:23:49.783469+00:00'),
('033d0c77-35d2-453a-83bc-289784185f1c', 274, 'Curiosità & Retroscena', 'La scelta della colonna sonora d''epoca', 'Eleanor Bergstein scrisse la sceneggiatura ascoltando costantemente la musica degli anni ''60 e pretese contrattualmente che la pellicola contenesse esattamente i brani del periodo che aveva scelto, rifiutando di ambientare la storia nel presente o di inserire musica moderna. Questa insistenza prosciugò una parte considerevole del budget iniziale per l''acquisto dei diritti musicali.', 'Note di produzione e commento audio del DVD', TRUE, 'IA (Daily Sync)', 'IA Verificata', 0, 1, '2026-11-02T10:23:49.783469+00:00'),
('2baecf1a-503b-4ae6-a988-290483ea480c', 274, 'Aneddoti dal set', 'L''infortunio al ginocchio di Patrick Swayze', 'Durante le riprese della scena in cui Johnny e Penny ballano nel corridoio del bungalow, Patrick Swayze aggravò un vecchio infortunio al ginocchio patito ai tempi della sua carriera nella danza classica. Il ginocchio continuava a gonfiarsi durante le riprese e la troupe fu costretta a drenargli il liquido dal ginocchio tra un ciak e l''altro per permettergli di completare il film.', 'Autobiografia di Patrick Swayze ''The Time of My Life''', TRUE, 'IA (Daily Sync)', 'IA Verificata', 0, 2, '2026-11-02T10:23:49.783469+00:00'),
('cc6f97f3-43a8-4485-a935-19a797aeef84', 274, 'Casting & Scelte', 'Il rifiuto iniziale di Patrick Swayze', 'Inizialmente Patrick Swayze rifiutò il ruolo di Johnny Castle perché era impegnato in un altro progetto e non amava le sceneggiature troppo sdolcinate. Fu solo dopo aver letto con maggiore attenzione il copione e aver discusso con la regista Emile Ardolino che accettò la parte, attratto soprattutto dalla complessità drammatica del personaggio oltre che dalle doti di ballerino richieste.', 'Intervista ufficiale a Patrick Swayze per il 20º anniversario', TRUE, 'IA (Daily Sync)', 'IA Verificata', 0, 3, '2026-11-02T10:23:49.783469+00:00'),
('cc7d78e7-04f1-448f-b2bb-adc431844b75', 274, 'Aneddoti dal set', 'L''improvvisazione della celebre scena del gattonamento', 'La sequenza in cui Baby e Johnny si avvicinano gattonando sul pavimento dello studio di danza non era originariamente concepita come una scena di prove intime, ma i due attori stavano semplicemente provando i passi ridendo ed esausti per la stanchezza tra un ciak e l''altro. Il regista Emile Ardolino decise di lasciare girare la telecamera, inserendo quel momento di reale complicità nel montaggio finale.', 'Special TV ''The Making of Dirty Dancing''', TRUE, 'IA (Daily Sync)', 'IA Verificata', 0, 4, '2026-11-02T10:23:49.783469+00:00'),
('f1b59ae9-6882-447a-8480-21a41e2d4ce3', 276, 'Segreti di produzione', 'La sfida dell''adattamento geografico e culturale', 'Nel trasporre la sceneggiatura dal modello francese, gli sceneggiatori italiani hanno dovuto riconcepire il sistema dei licei e dei provveditorati per renderlo credibile nel contesto scolastico italiano, dove l''esame di maturità riveste un valore iconico e burocratico profondamente differente rispetto a quello d''oltralpe.', 'Note di produzione e pressbook ufficiale del film', TRUE, 'IA (Daily Sync)', 'IA Verificata', 0, 0, '2026-11-02T10:24:02.806375+00:00'),
('dc22cdec-c4bc-47e4-b805-57866b4a1443', 276, 'Aneddoti dal set', 'La gestione delle comparse tra i banchi', 'Per le scene delle aule e dei corridoi del liceo Manzoni, la produzione ha selezionato oltre duecento giovani comparse provenienti da istituti romani, guidate sul set da assistenti alla regia per ricreare fedelmente il caos e le dinamiche tipiche dell''ultimo anno di superiori.', 'Reportage dal set e interviste agli aiuto-registi', TRUE, 'IA (Daily Sync)', 'IA Verificata', 0, 1, '2026-11-02T10:24:02.806375+00:00'),
('cb69f35b-cb0e-4295-9899-65fe7a1baf2f', 276, 'Casting & Scelte', 'Il lavoro sulle gag visive mutuate dal fumetto', 'Il regista Ivan Silvestrini ha lavorato a stretto contatto con il direttore della fotografia per mantenere la struttura delle vignette originali della graphic novel francese, traducendo le gag dei professori in inquadrature geometriche e tempi comici serrati tipici del linguaggio slapstick.', 'Intervista al regista Ivan Silvestrini sul making-of', TRUE, 'IA (Daily Sync)', 'IA Verificata', 0, 2, '2026-11-02T10:24:02.806375+00:00'),
('912a0cb5-220c-4413-92c9-813a9dd125ea', 63, 'Curiosità & Retroscena', 'Il primo grande blockbuster di Hollywood', 'Robin Hood (1922) fu il primo film nella storia del cinema ad avere una premiere ufficiale in grande stile, tenutasi al Grauman''s Egyptian Theatre di Hollywood il 18 ottobre 1922, stabilendo il modello per i moderni lanci cinematografici.', 'Archivio storico di Hollywood e note di produzione United Artists', TRUE, 'IA (Daily Sync)', 'IA Verificata', 0, 0, '2026-11-02T14:45:24.132667+00:00'),
('64532250-7ace-473e-8bfc-654ca642732a', 63, 'Segreti di produzione', 'Imponenti set mastodontici', 'Lo scenografo Lloyd Wright progettò e fece costruire a Pickfair e negli studi della United Artists set giganteschi, inclusi un castello alto oltre 27 metri e una sezione medievale della città di Nottingham che occupava acri di terreno.', 'Autobiografia di Douglas Fairbanks e registri di produzione', TRUE, 'IA (Daily Sync)', 'IA Verificata', 0, 1, '2026-11-02T14:45:24.132667+00:00'),
('2477eef4-e03d-4ce8-b159-9b6a0b364f39', 208, 'Curiosità & Retroscena', 'La genesi del personaggio di Floyd Eagle-san', 'Il personaggio secondario di Floyd Eagle-san, il parrucchiere sospettato da Gru di essere El Macho, è doppiato dal comico Ken Jeong. Il design del personaggio e la sua bizzarra parruccomania derivano direttamente da un disegno scartato durante lo sviluppo del primo capitolo del franchise.', 'Commento audio del Blu-ray dei registi Pierre Coffin e Chris Renaud', TRUE, 'IA (Daily Sync)', 'IA Verificata', 0, 1, '2026-11-02T10:12:40.713886+00:00'),
('b7fb0f3d-301d-4c46-8084-5edd8096fbe8', 208, 'Casting & Scelte', 'Il ritorno di Steve Coogan nel ruolo di Silas Ramsbottom', 'L''attore britannico Steve Coogan presta la voce a Silas Ramsbottom, il capo della Lega Anti-Cattivi. Il cognome del personaggio, che in inglese scatena inevitabili battute goliardiche sulla scatolistica inferiore, è stato scelto appositamente dai soggettisti Cinco Paul e Ken Daurio per creare gag ricorrenti durante i colloqui con Gru.', 'Intervista agli sceneggiatori Paul e Daurio per Collider', TRUE, 'IA (Daily Sync)', 'IA Verificata', 0, 2, '2026-11-02T10:12:40.713886+00:00'),
('8ff45cba-b070-41ff-b9f7-7706c263d1a8', 208, 'Segreti di produzione', 'Le origini musicali della colonna sonora di Pharrell Williams', 'Il musicista e produttore Pharrell Williams, che ha curato le musiche e le canzoni originali del film insieme al compositore Heitor Pereira, ha dovuto riscrivere il brano principale della colonna sonora ben nove volte prima di trovare la versione definitiva che avrebbe portato alla celebre nomination all''Oscar per la canzone ''Happy'' nel capitolo successivo.', 'Special feature ''The Music of Despicable Me 2'' nel home video', TRUE, 'IA (Daily Sync)', 'IA Verificata', 0, 3, '2026-11-02T10:12:40.713886+00:00'),
('3f8360e7-f684-4e7a-8b2d-44c88c2b0d33', 192, 'Curiosità & Retroscena', 'Il premio speciale a Cabourg', 'Grazie alla sua interpretazione di Valentine in questo film, Sophie Marceau ha vinto il prestigioso premio come migliore attrice al Festival du Film de Cabourg nel 1988, consolidando la sua transizione verso ruoli più maturi.', 'Archivio storico del Festival du Film de Cabourg', TRUE, 'IA (Daily Sync)', 'IA Verificata', 0, 0, '2026-11-02T10:18:55.932475+00:00'),
('ecc64155-9318-4ab0-98b9-403a6edc1943', 275, 'Curiosità & Retroscena', 'L''ispirazione reale dietro la sceneggiatura', 'Il co-sceneggiatore Mark Andrus ha ideato il personaggio di Melvin Udall traendo ispirazione da un suo conoscente realmente esistito che soffriva di disturbo ossessivo-compulsivo e che era solito seguire rituali estremamente rigidi, come non calpestare mai le linee dei marciapiedi.', 'Note di produzione ufficiali della Sony Pictures', TRUE, 'IA (Daily Sync)', 'IA Verificata', 0, 0, '2026-11-02T10:23:56.657782+00:00'),
('9ae44b7d-6d7d-49dc-99bd-98527138568a', 275, 'Citazioni & Easter Egg', 'La canzone ricorrente nel montaggio', 'Il brano ''Hand in My Pocket'' di Alanis Morissette era stato originariamente inserito in una versione provvisoria del montaggio per accompagnare le sequenze di camminata di Melvin, ma fu successivamente sostituito dalla colonna sonora orchestrale originale composta da Hans Zimmer.', 'Commento audio del regista James L. Brooks nell''edizione DVD', TRUE, 'IA (Daily Sync)', 'IA Verificata', 0, 1, '2026-11-02T10:23:56.657782+00:00'),
('03abe65c-a020-4615-a22b-985786980342', 275, 'Casting & Scelte', 'Il rifiuto preventivo di Kevin Kline', 'Prima che la produzione ingaggiasse Greg Kinnear per il ruolo del pittore Simon Bishop, il regista James L. Brooks offrì la parte a Kevin Kline, il quale declinò l''offerta a causa di conflitti di programmazione con altri progetti cinematografici.', 'Archivi storici di casting di Hollywood Reporter', TRUE, 'IA (Daily Sync)', 'IA Verificata', 0, 2, '2026-11-02T10:23:56.657782+00:00'),
('eeb035db-821b-42d8-b220-e1fdd578ccb8', 63, 'Aneddoti dal set', 'L''infortunio sul set di Douglas Fairbanks', 'Durante le riprese delle scene d''azione, Douglas Fairbanks subì un grave infortunio alla caviglia compiendo uno dei suoi celebri salti; nonostante il dolore e il parere medico, continuò a girare le scene meno dinamiche zoppicando leggermente.', 'Biografia ''Douglas Fairbanks: The First King of Hollywood'' di Jeffrey Vance', TRUE, 'IA (Daily Sync)', 'IA Verificata', 0, 2, '2026-11-02T14:45:24.132667+00:00'),
('47582123-684e-43bc-b364-8af0217a6a1e', 63, 'Casting & Scelte', 'La scelta di Allan Dwan alla regia', 'Douglas Fairbanks volle fortemente Allan Dwan come regista dopo aver collaborato con lui in precedenza, apprezzando la sua straordinaria capacità di gestire produzioni mastodontiche e la sua abilità tecnica con le cineprese.', 'Interviste storiche ad Allan Dwan curate da Peter Bogdanovich', TRUE, 'IA (Daily Sync)', 'IA Verificata', 0, 3, '2026-11-02T14:45:24.132667+00:00'),
('444ba554-0ce7-4ae8-aae6-ea9f3870e060', 63, 'Casting & Scelte', 'Wallace Beery nei panni di Riccardo Cuor di Leone', 'Wallace Beery fu scelto per interpretare il potente e burbero Re Riccardo, un ruolo che sfruttava la sua imponente stazza fisica e che consolidò la sua reputazione come uno dei caratteristi più richiesti del muto.', 'Database storico AFI (American Film Institute)', TRUE, 'IA (Daily Sync)', 'IA Verificata', 0, 4, '2026-11-02T14:45:24.132667+00:00'),
('cbe29600-184d-4d1c-9c32-4ccaa8f34bd6', 63, 'Effetti speciali & Trucco', 'Innovazioni nelle riprese d''azione', 'Il direttore della fotografia Arthur Edeson utilizzò lenti speciali e posizionò le cineprese su carrelli mobili improvvisati per catturare i dinamici movimenti di Fairbanks, anticipando tecniche di regia d''azione moderne.', 'Manuale di cinematografia muta e archivi della ASC', TRUE, 'IA (Daily Sync)', 'IA Verificata', 0, 5, '2026-11-02T14:45:24.132667+00:00'),
('8df17888-cfeb-4bed-8110-d0a38c3084a1', 99, 'Casting & Scelte', 'Il rifiuto iniziale di Tom Hiddleston', 'Prima che il ruolo di Messala venisse affidato a Toby Kebbell, la produzione aveva offerto la parte a Tom Hiddleston, il quale ha dovuto rifiutare l''offerta a causa di conflitti di programmazione con altri impegni cinematografici.', 'Report di casting di Deadline Hollywood', TRUE, 'IA (Daily Sync)', 'IA Verificata', 0, 0, '2026-11-02T14:45:38.126424+00:00'),
('310b6c16-10e5-43b5-b296-25aa5b6ab7e8', 99, 'Casting & Scelte', 'La scelta di Jack Huston per il ruolo principale', 'Jack Huston è stato fortemente voluto dal regista Timur Bekmambetov dopo essere stato scartato per altri progetti importanti, battendo la concorrenza di diversi attori emergenti per ereditare il ruolo che fu di Charlton Heston.', 'Note di produzione ufficiali Paramount Pictures', TRUE, 'IA (Daily Sync)', 'IA Verificata', 0, 1, '2026-11-02T14:45:38.126424+00:00'),
('d1ac671e-f873-4851-b042-1212ce5baa99', 99, 'Segreti di produzione', 'L''approccio alle riprese della corsa delle bighe', 'A differenza del film del 1959, la celebre sequenza della corsa delle bighe in questa versione del 2016 è stata girata integrando l''uso estensivo di telecamere GoPro montate direttamente sui carri e sui cavalli per dare un senso di immersione totale.', 'Making-of ufficiale dal set', TRUE, 'IA (Daily Sync)', 'IA Verificata', 0, 2, '2026-11-02T14:45:38.126424+00:00'),
('5e9563aa-b8bf-4e94-925b-71f6f200467e', 99, 'Aneddoti dal set', 'L''allenamento intensivo con i carri per gli attori', 'Sia Jack Huston che Toby Kebbell hanno dovuto sottoporsi a settimane di addestramento intensivo a Roma guidando veri carri trainati da cavalli prima di girare la sequenza clou, imparando a gestire le redini e la velocità in pista.', 'Intervista promozionale del cast', TRUE, 'IA (Daily Sync)', 'IA Verificata', 0, 3, '2026-11-02T14:45:38.126424+00:00'),
('290b5e12-a2c6-4cbf-b22b-c03fd48cef80', 99, 'Curiosità & Retroscena', 'La rilettura del romanzo come dramma fraterno', 'Il regista Timur Bekmambetov e gli sceneggiatori John Ridley e Keith Clarke hanno impostato la sceneggiatura basandosi direttamente sul romanzo originale di Lew Wallace del 1880, focalizzandosi in particolare sulla giovinezza condivisa tra Giuda e Messala per accentuare il dramma del tradimento.', 'Pressbook ufficiale del film', TRUE, 'IA (Daily Sync)', 'IA Verificata', 0, 4, '2026-11-02T14:45:38.126424+00:00'),
('0ef6bd53-9e0f-4f85-9b4d-d0060cd13160', 209, 'Casting & Scelte', 'L''ispirazione per il look e le movenze di Scarlet Sterminator', 'Il character designer Eric Guillon e il co-regista Kyle Balda hanno modellato l''aspetto e la sicurezza di Scarlet Sterminator ispirandosi alle icone della moda e del cinema britannico degli anni ''60, attingendo in particolare all''energia ribelle delle donne ritratte nei film di James Bond di quell''epoca.', 'Illumination Entertainment Production Notes', TRUE, 'IA (Daily Sync)', 'IA Verificata', 0, 0, '2026-11-02T10:12:48.169688+00:00'),
('53d1da8c-2e43-4cc7-a531-8e33c50a45a8', 209, 'Casting & Scelte', 'La genesi del personaggio di Herb Sterminator', 'Jon Hamm ha ottenuto la parte di Herb Sterminator, il marito inventore di Scarlet, grazie alla sua voce profonda e ironica che i registi consideravano perfetta per bilanciare la personalità autoritaria e vulcanica della moglie malvagia.', 'Audio commento dei registi Pierre Coffin e Kyle Balda', TRUE, 'IA (Daily Sync)', 'IA Verificata', 0, 1, '2026-11-02T10:12:48.169688+00:00'),
('ef7b2a01-92cd-4807-b7bc-0c67dee30f6d', 209, 'Citazioni & Easter Egg', 'Il tributo ai Beatles nelle strisce pedonali di Abbey Road', 'In una delle sequenze ambientate a Londra, i Minions attraversano la strada camminando in fila indiana sulle celebri strisce pedonali di Abbey Road, replicando esattamente la copertina dell''omonimo album dei Beatles del 1969, sebbene il film sia ambientato nel 1968.', 'Visual analysis e Easter Egg ufficiali del film', TRUE, 'IA (Daily Sync)', 'IA Verificata', 0, 2, '2026-11-02T10:12:48.169688+00:00'),
('052ea8c6-d653-4a2d-a7d6-c992bea43cfc', 209, 'Casting & Scelte', 'Il doppiaggio italiano affidato a star della televisione e del cinema', 'Nella versione italiana del film, la supercattiva Scarlet Sterminator è stata doppiata dalla comica e attrice Luciana Littizzetto, mentre suo marito Herb ha avuto la voce del comico e conduttore Fabio Fazio, in una scelta di casting che ha ricalcato la dinamica ironica della coppia.', 'Note di stampa Universal Pictures Italia', TRUE, 'IA (Daily Sync)', 'IA Verificata', 0, 3, '2026-11-02T10:12:48.169688+00:00'),
('5d4eb8d8-c904-40ed-9545-82519ee0a9d9', 194, 'Segreti di produzione', 'La causa reale di plagio sull''opera d''arte finale', 'Nel 1998, l''artista Frederick Hart fece causa alla Warner Bros. sostenendo che la scultura che appare sullo sfondo nell''attico di John Milton fosse una copia non autorizzata della sua opera ''Ex Deo'', realizzata per la Washington National Cathedral. La produzione risolse la controversia fuori dalle tribune, inserendo un''apposita clausola nei home video successivi.', 'Atti giudiziari del distretto di New York e note di produzione Warner Bros.', TRUE, 'IA (Daily Sync)', 'IA Verificata', 0, 0, '2026-11-02T10:19:02.977531+00:00'),
('775688ca-11ec-4d1e-9ca3-137ce76a6cf6', 194, 'Aneddoti dal set', 'Il cameo dei veri genitori di Charlize Theron', 'Durante la sequenza iniziale girata in Florida, nella scena in cui il personaggio di Kevin Lomax vince la causa in tribunale, compaiono brevemente tra il pubblico come comparse la madre e il padre di Charlize Theron, inseriti dal regista Taylor Hackford come piccolo omaggio alla troupe.', 'Commento audio del regista Taylor Hackford nell''edizione DVD speciale', TRUE, 'IA (Daily Sync)', 'IA Verificata', 0, 1, '2026-11-02T10:19:02.977531+00:00'),
('7b52bc5b-1106-44d7-85b4-30366edd3522', 194, 'Segreti di produzione', 'La scelta della chiesa sconsacrata per le scene chiave', 'La drammatica sequenza del confronto finale tra Kevin Lomax e John Milton non fu girata in un teatro di posa ricostruito, bensì all''interno della storica e sconsacrata chiesa di St. Augustine nel Bronx, la cui architettura gotica offriva l''atmosfera oppressiva richiesta da Taylor Hackford.', 'Production design featurette nel documentario sul making-of del film', TRUE, 'IA (Daily Sync)', 'IA Verificata', 0, 2, '2026-11-02T10:19:02.977531+00:00'),
('a12652a3-69d6-41cc-bc30-988573a95e0e', 194, 'Casting & Scelte', 'Il rifiuto originale della regia da parte di Joel Schumacher', 'Prima che Taylor Hackford si sedesse sulla sedia di导演, la Warner Bros. aveva inizialmente offerto la direzione del progetto a Joel Schumacher, il quale declinò l''offerta perché impegnato nella post-produzione di ''Batman & Robin''.', 'Archivio storico di Variety sui progetti cinematografici degli anni ''90', TRUE, 'IA (Daily Sync)', 'IA Verificata', 0, 3, '2026-11-02T10:19:02.977531+00:00'),
('35ac51ef-d4ec-4c1f-8cf4-a7d1bd4e935b', 194, 'Aneddoti dal set', 'L''improvvisazione di Al Pacino nel monologo sul Padre', 'Durante il celebre monologo in cui John Milton spiega la sua visione di Dio come un ''ballon d''essai'', Al Pacino modificò parzialmente alcune battute del copione originale scritto da Jonathan Lemkin e Tony Gilroy, aggiungendo gesti fisici spontanei per enfatizzare la vanità del personaggio.', 'Intervista a Al Pacino per il press kit ufficiale del film', TRUE, 'IA (Daily Sync)', 'IA Verificata', 0, 4, '2026-11-02T10:19:02.977531+00:00'),
('a35664d4-245b-418c-bab4-295485994882', 277, 'Casting & Scelte', 'La bocciatura iniziale di Jerry Bruckheimer', 'Il produttore Jerry Bruckheimer inizialmente non voleva Nicolas Cage per la parte del biochimico Stanley Goodspeed, ritenendo che l''attore non fosse adatto per un action movie ad alto budget. Fu lo stesso Cage a insistere e a convincere i produttori dopo aver accettato di sottoporsi a una profonda revisione del personaggio.', 'Commento audio del regista Michael Bay nel DVD/Blu-ray di The Rock', TRUE, 'IA (Daily Sync)', 'IA Verificata', 0, 0, '2026-11-02T10:24:10.961888+00:00'),
('ccf4be00-9b7b-4620-bd32-5cd4713296b8', 277, 'Segreti di produzione', 'La consulenza tecnica dell''ex Navy SEAL Harry Humphries', 'Per garantire la massima autenticità nelle sequenze d''azione e nelle tattiche militari d''assalto, la produzione assunse l''ex Navy SEAL Harry Humphries come consulente militare e produttore associato. Humphries supervisionò ogni dettaglio dell''addestramento degli attori e delle coreografie dei combattimenti.', 'Documentario dietro le quinte ''The Rock: Special Effects'' e note di produzione', TRUE, 'IA (Daily Sync)', 'IA Verificata', 0, 1, '2026-11-02T10:24:10.961888+00:00'),
('e9b31ed0-e17d-4236-a41a-e2d9d4250670', 277, 'Aneddoti dal set', 'L''improvvisazione della battuta sulla regina Elisabetta', 'La celebre battuta in cui John Mason dice alla figlia Jade ''Ihre Majestät lässt grüssen'' (I saluti di Sua Maestà) prima di darle i soldi fu in gran parte influenzata dall''umorismo e dall''esperienza sul set di Sean Connery, che spesso suggeriva modifiche ai dialoghi per accentuare il cinismo del suo personaggio.', 'Intervista a Sean Connery negli archivi stampa della première di The Rock', TRUE, 'IA (Daily Sync)', 'IA Verificata', 0, 2, '2026-11-02T10:24:10.961888+00:00'),
('11cd85fd-3f14-4010-8dcb-05fd379614da', 277, 'Curiosità & Retroscena', 'Il cameo non accreditato di Stuart Baird come montatore e regista', 'Il montatore del film Stuart Baird ha avuto un ruolo fondamentale nella strutturazione del ritmo frenetico della pellicola, lavorando a stretto contatto con Michael Bay durante la post-produzione per tagliare oltre quaranta minuti di girato e rendere il montaggio estremamente serrato.', 'Credits ufficiali del film e interviste al montatore Stuart Baird', TRUE, 'IA (Daily Sync)', 'IA Verificata', 0, 3, '2026-11-02T10:24:10.961888+00:00'),
('ceaf5290-b5cb-457f-8e54-ed11af853e93', 279, 'Effetti speciali & Trucco', 'La finta calvizie di Thomas F. Wilson', 'Per interpretare il bullo Biff Tannen cinquantenne nelle scene ambientate nel 1985 alternativo (dopo che Biff si è arricchito con l''almanacco sportivo), l''attore Thomas F. Wilson indossava una complessa protesi in lattice sulla fronte che simulava una calvizie avanzata. Il truccatore Ken Chase ha impiegato mesi per perfezionare l''invecchiamento dei lineamenti del viso di Biff, rendendolo visivamente simile a un cattivo da film noir.', 'Documentario ''Making the Future'' contenuto nel Blu-ray celebrativo del trentesimo anniversario', TRUE, 'IA (Daily Sync)', 'IA Verificata', 0, 0, '2026-11-02T10:24:27.390629+00:00'),
('0bf389fc-d158-48b5-9ade-e32a132d11ed', 210, 'Casting & Scelte', 'Il cameo vocale di Chris Renaud nel ruolo del custode', 'Chris Renaud, co-regista dei primi due capitoli della saga, ha partecipato al terzo film doppiando un personaggio minore: il custode del museo in cui Balthazar Bratt compie il suo furto iniziale. Si tratta di una tradizione della Illumination Entertainment per mantenere continuità con i creatori storici del franchise.', 'Note di produzione ufficiali Illumination Entertainment', TRUE, 'IA (Daily Sync)', 'IA Verificata', 0, 0, '2026-11-02T10:12:54.587173+00:00'),
('05315627-a0b1-427d-ad76-5d8ba822d4b1', 210, 'Citazioni & Easter Egg', 'Il riferimento nascosto a Michael Jackson in Bad', 'Durante il confronto coreografato tra Balthazar Bratt e Gru sulla nave, i passi di danza eseguiti da Bratt includono espliciti tributi visivi ai celebri videoclip di Michael Jackson, in particolare a ''Bad'' e ''Smooth Criminal''. Gli animatori hanno studiato i movimenti del re del pop per renderli fedeli all''estetica del 1987.', 'Special content ''The Making of Despicable Me 3'' - Home Video', TRUE, 'IA (Daily Sync)', 'IA Verificata', 0, 1, '2026-11-02T10:12:54.587173+00:00'),
('bf80e533-d90d-4731-9b24-5ed32a58b578', 210, 'Segreti di produzione', 'La scelta della colonna sonora anni ''80 supervisionata da Chris Meledandri', 'Il produttore e fondatore della Illumination, Chris Meledandri, ha insistito personalmente affinché la colonna sonora godesse di licenze musicali pesanti dell''era synth-pop, inserendo brani iconici come ''Take On Me'' degli A-ha e ''Into the Groove'' di Madonna per ancorare temporalmente il profilo nostalgico di Balthazar Bratt.', 'Intervista di Billboard a Chris Meledandri', TRUE, 'IA (Daily Sync)', 'IA Verificata', 0, 2, '2026-11-02T10:12:54.587173+00:00');
INSERT INTO public.movie_trivia ("id", "film_id", "categoria", "titolo", "descrizione", "fonte", "approvato", "inserito_da", "provenienza", "likes", "ordine", "created_at") VALUES
('60464d37-1bdc-481e-b663-a61d545dd929', 195, 'Segreti di produzione', 'La finta morte finanziaria della casa di produzione', 'Per completare la post-produzione e il missaggio del suono, George Miller e il produttore Byron Kennedy dovettero letteralmente svuotare i loro conti personali e fare affidamento su donazioni di parenti e medici, arrivando a creare una società fantasma e a rischiare il fallimento prima ancora di vedere un dollaro di incasso.', 'Documentario ''Birth of a Hero'' e note di produzione originali', TRUE, 'IA (Daily Sync)', 'IA Verificata', 0, 0, '2026-11-02T10:19:09.838734+00:00'),
('8df03228-eeed-4ee2-b5ea-f13da07e2829', 195, 'Citazioni & Easter Egg', 'Il nome di Max inciso sul cambio della Interceptor', 'Sulla pompetta del cambio della celebre Ford Falcon V8 nera (la Pursuit Special) guidata da Mel Gibson, la produzione aveva incollato un piccolo teschio e inciso simbolicamente il nome di Max per dare un tocco di vissuto e usura al veicolo, un dettaglio visibile solo in pochissimi primi piani.', 'Articoli di approfondimento su car-culture e archivi del set di Mad Max', TRUE, 'IA (Daily Sync)', 'IA Verificata', 0, 1, '2026-11-02T10:19:09.838734+00:00'),
('8f95e8fe-2705-4323-b6ba-7cde64df3d3d', 195, 'Aneddoti dal set', 'La distruzione accidentale di una vera auto della polizia', 'Durante le riprese della sequenza d''inseguimento iniziale, uno stuntman perse il controllo di una vera berlina Ford Falcon XT della polizia australiana (acquistata di seconda mano) e la distrusse completamente contro un palo della luce, riducendo ulteriormente il già esiguo parco auto a disposizione della troupe.', 'Intervista al coordinatore degli stunt Bob Doyle', TRUE, 'IA (Daily Sync)', 'IA Verificata', 0, 2, '2026-11-02T10:19:09.838734+00:00'),
('7cb782e8-ad05-4fe2-9e68-afcf99daf6be', 278, 'Casting & Scelte', 'La voce originale di Willy Wonka', 'Johnny Depp ha modellato la voce eccentrica e il tono acuto di Willy Wonka ispirandosi ai conduttori dei programmi televisivi per bambini degli anni ''70 e ''. Ha dichiarato di aver pensato a come quelle figure televisive cercassero di mantenere entusiasti i bambini pur apparendo leggermente inquietanti.', 'Audio commento del DVD e interviste promozionali ufficiali del 2005', TRUE, 'IA (Daily Sync)', 'IA Verificata', 0, 0, '2026-11-02T10:24:19.153766+00:00'),
('8282a9d8-795c-4a05-ae29-7b590561bb24', 278, 'Citazioni & Easter Egg', 'Il rifiuto del cameo per Gene Wilder', 'A Gene Wilder, l''amato interprete di Willy Wonka nel film del 1971, fu offerto un cameo nel film di Tim Burton, ma l''attore declinò l''offerta. In seguito, Wilder criticò apertamente il remake di Burton, definendolo un''operazione puramente commerciale e mancante di grazia artistica.', 'Intervista di Gene Wilder al Daily Telegraph (2013)', TRUE, 'IA (Daily Sync)', 'IA Verificata', 0, 1, '2026-11-02T10:24:19.153766+00:00'),
('5eeee3b6-a128-4e13-86c2-66d4dc6816e2', 278, 'Effetti speciali & Trucco', 'La realizzazione degli Oompa Loompa interpretati da un solo attore', 'Tutti centinaia di Oompa Loompa presenti nel film sono stati interpretati interamente dall''attore keniota-britannico Deep Roy. Per farlo apparire nei numeri musicali in molteplici copie identiche, Roy ha dovuto ripetere la stessa sequenza di danza centinaia di volte, successivamente assemblate in post-produzione con la tecnica dello split screen.', 'Documentario ''The Making of Charlie and the Chocolate Factory'' (2005)', TRUE, 'IA (Daily Sync)', 'IA Verificata', 0, 2, '2026-11-02T10:24:19.153766+00:00'),
('491687a9-25a1-4022-93d0-330ecc44547d', 278, 'Segreti di produzione', 'Il set dei vetri di zucchero per Mike Teavee', 'Nella scena in cui Mike Teavee irrompe nella stanza della televisione sfondando una parete di vetro, l''attore Jordan Fry non ha corso pericoli reali. Il muro è stato interamente costruito utilizzando lastre di zucchero colato, un materiale scenografico sicuro che si frantuma all''impatto senza ferire l''interprete.', 'Note di produzione e featurette sugli stunt del film', TRUE, 'IA (Daily Sync)', 'IA Verificata', 0, 3, '2026-11-02T10:24:19.153766+00:00'),
('227e8aac-c1e5-4e9a-a42c-ff040e57f3ae', 278, 'Curiosità & Retroscena', 'I look dei bambini ispirati a epoche diverse', 'La costumista Gabriella Pescucci ha ideato i costumi dei quattro bambini viziosi ispirandosi a differenti decenni della cultura pop americana per sottolineare la loro psicologia. Ad esempio, Violet Beauregarde indossa una tuta da ginnastica dal taglio tipicamente anni ''90, mentre Veruca Salt riflette lo stile viziato dell''alta borghesia britannica.', 'Libro d''arte ufficiale ''The Making of Charlie and the Chocolate Factory'' di Ian Nathan', TRUE, 'IA (Daily Sync)', 'IA Verificata', 0, 4, '2026-11-02T10:24:19.153766+00:00'),
('041567a3-d306-4570-b2c0-c8b2cad0a0b8', 278, 'Aneddoti dal set', 'Gli occhiali da sole protettivi di Johnny Depp', 'Durante le riprese nella stanza della cioccolata, Johnny Depp indossava spesso occhiali da sole scuri fuori dai ciak per proteggere gli occhi dai riflessi accecanti creati dalle potenti luci di studio puntate contro le superfici lisce e colorate dei macchinari scenografici.', 'Intervista al direttore della fotografia Philippe Rousselot', TRUE, 'IA (Daily Sync)', 'IA Verificata', 0, 5, '2026-11-02T10:24:19.153766+00:00'),
('e292390a-48d3-40a7-9a61-c70cac307c6d', 76, 'Aneddoti dal set', 'L''infortunio di Harrison Ford', 'Durante le riprese ai Pinewood Studios nel giugno 2014, Harrison Ford si ruppe la gamba sinistra dopo essere stato colpito accidentalmente dalla porta idraulica della nave Millennium Falcon. L''incidente costrinse la produzione a fermare temporaneamente le riprese e a riorganizzare il piano di lavoro per permettere all''attore di recuperare.', 'Comunicato ufficiale Lucasfilm e note di produzione', TRUE, 'IA (Daily Sync)', 'IA Verificata', 0, 0, '2026-11-02T14:45:29.059877+00:00'),
('0f80a27d-8d70-47b1-a235-6dab12a828b6', 76, 'Casting & Scelte', 'Il provino di Daisy Ridley', 'Daisy Ridley ottenne la parte di Rey dopo un processo di audizioni durato sette mesi. J.J. Abrams ha dichiarato di essere rimasto particolarmente colpito dalla sua intensa interpretazione emotiva durante una scena drammatica girata nei primi turni di provino.', 'Documentario ''Secrets of The Force Awakens'' e interviste ufficiali', TRUE, 'IA (Daily Sync)', 'IA Verificata', 0, 1, '2026-11-02T14:45:29.059877+00:00'),
('abf5d7d0-0f77-4549-9e71-9cb2cef2f719', 211, 'Curiosità & Retroscena', 'La scelta del titolo originale e il riferimento a James Bond', 'Il titolo originale del film, ''Minions: The Rise of Gru'', è un chiaro omaggio e parodia dei film di James Bond degli anni ''70 come ''Live and Let Die'' o ''The Spy Who Loved Me'', oltre a richiamare la struttura narrativa dei cinecomic contemporanei sulle origini dei cattivi.', 'Note di produzione ufficiali Illumination Entertainment', TRUE, 'IA (Daily Sync)', 'IA Verificata', 0, 0, '2026-11-02T10:13:01.326798+00:00'),
('75b4a2a4-13df-4106-9b33-fa2346743a9a', 211, 'Casting & Scelte', 'Il tributo vocale a Dolph Lundgren', 'Per il personaggio di Svengeance, il cattivo svedese dei Malefici 6, la produzione ha ingaggiato l''attore Dolph Lundgren, sfruttando la sua iconica immagine cinematografica e il suo accento naturale per caricare di ironia il ruolo del supercattivo muscoloso.', 'Crediti ufficiali del cast e interviste promozionali', TRUE, 'IA (Daily Sync)', 'IA Verificata', 0, 1, '2026-11-02T10:13:01.326798+00:00'),
('7010c867-37b4-421a-8cb5-d0adf41958dd', 211, 'Segreti di produzione', 'La colonna sonora dominata dai classici del funk e del soul', 'La supervisione musicale del film è stata affidata a Jack Antonoff, che ha curato una colonna sonora interamente composta da cover di brani funk, disco e soul degli anni ''70, facendo reinterpretare classici di Sly & the Family Stone e Diana Ross ad artisti contemporanei come Caroline Polachek e St. Vincent.', 'Comunicato stampa ufficiale della soundtrack Decca Records', TRUE, 'IA (Daily Sync)', 'IA Verificata', 0, 2, '2026-11-02T10:13:01.326798+00:00'),
('3353ae7a-c0b3-4d7a-b0c3-5ad1bfea7605', 223, 'Segreti di produzione', 'La consulenza storica del Vaticano', 'Per garantire la rigorosa accuratezza nella rappresentazione dei riti e delle persecuzioni dei primi cristiani, il regista Jerzy Kawalerowicz si è avvalso della consulenza di storici ecclesiastici e accademici pontifici durante la fase di scrittura della sceneggiatura.', 'Note di produzione ufficiali e conferenza stampa d''uscita del film', TRUE, 'IA (Daily Sync)', 'IA Verificata', 0, 0, '2026-11-02T10:19:21.84937+00:00'),
('54a6a304-93c3-4542-a572-3b6a8b0d8bef', 223, 'Curiosità & Retroscena', 'Le musiche originali di Kilar', 'La colonna sonora è stata affidata al celebre compositore Wojciech Kilar, noto per le sue collaborazioni con Roman Polanski e Francis Ford Coppola, il quale ha fuso sonorità solenni orchestrali con cori liturgici arcaici.', 'Booklet ufficiale della colonna sonora in CD', TRUE, 'IA (Daily Sync)', 'IA Verificata', 0, 1, '2026-11-02T10:19:21.84937+00:00'),
('8cdfb785-f973-4f1a-a1e9-d2e1732e18c3', 223, 'Segreti di produzione', 'La collaborazione con gli studi di Mosca', 'Parte della complessa post-produzione audio e la registrazione delle imponenti parti orchestrali sono state effettuate in Russia, sfruttando la grande tradizione acustica e sinfonica degli studi di registrazione di Mosca.', 'Crediti di produzione ufficiali del film', TRUE, 'IA (Daily Sync)', 'IA Verificata', 0, 2, '2026-11-02T10:19:21.84937+00:00'),
('80c0a470-7bf4-422e-9f1e-1893e477fa63', 279, 'Segreti di produzione', 'La paura dei fulmini e la scenografia della torre', 'La celebre sequenza in cui il fulmine colpisce la torre dell''orologio alle 22:04 fu realizzata combinando riprese effettuate sul set esterno dei Universal Studios con complesse sequenze in studio e miniature create dalla Industrial Light & Magic. Durante le riprese notturne all''aperto, la troupe dovette fare i conti con vere e proprie raffiche di vento e pioggia artificiale che resero particolarmente complessi i movimenti degli attori.', 'Commento audio del regista Robert Zemeckis e del produttore Bob Gale', TRUE, 'IA (Daily Sync)', 'IA Verificata', 0, 1, '2026-11-02T10:24:27.390629+00:00'),
('ab99b48a-68d4-4e82-9ed5-12698260c7d1', 279, 'Casting & Scelte', 'Il rifiuto iniziale di Crispin Glover e le trattative', 'Crispin Glover fu inizialmente molto scettico nell''accettare la parte di George McFly, arrivando quasi a rifiutare l''offerta a causa di disaccordi sul compenso e sulla gestione del contratto. La produzione riuscì a convincerlo solo a pochi giorni dall''inizio delle riprese, modificando parzialmente le richieste economiche avanzate dal suo agente.', 'Libro biografico e retrospettivo sulla produzione ''We Don''t Need Roads: The Making of the Back to the Future Trilogy'' di Michael Klastorin', TRUE, 'IA (Daily Sync)', 'IA Verificata', 0, 2, '2026-11-02T10:24:27.390629+00:00'),
('aed8f214-9441-4fea-b222-5dd36b5c63d6', 76, 'Curiosità & Retroscena', 'Il ritorno di Lawrence Kasdan alla sceneggiatura', 'Inizialmente la sceneggiatura fu affidata a Michael Arndt, ma dopo il suo abbandono J.J. Abrams decise di riscrivere il copione insieme a Lawrence Kasdan, co-sceneggiatore storico de ''L''Impero colpisce ancora'' e ''Il ritorno dello Jedi'', per dare maggiore profondità alla storia e ai legami con la trilogia originale.', 'Dichiarazioni di J.J. Abrams e press book ufficiale', TRUE, 'IA (Daily Sync)', 'IA Verificata', 0, 2, '2026-11-02T14:45:29.059877+00:00'),
('09a632aa-a6e1-45d3-a379-854d4f6e582c', 76, 'Segreti di produzione', 'L''uso estensivo di droidi pratici', 'Per dare maggiore veridicità alle interazioni degli attori sul set, il droide astromeccanico BB-8 non è stato realizzato interamente in CGI, ma come un robot fisico funzionante azionato da burattinai sul set e supervisionato dalla Neal Scanlan''s Creature Shop.', 'Making-of ufficiale e panel Star Wars Celebration', TRUE, 'IA (Daily Sync)', 'IA Verificata', 0, 3, '2026-11-02T14:45:29.059877+00:00'),
('ef69c818-dc18-43f0-9dc1-c370a71292fe', 76, 'Citazioni & Easter Egg', 'Il cameo vocale di Ewan McGregor e Alec Guinness', 'Nella sequenza in cui Rey tocca la spada laser di Anakin Skywalker e sperimenta una visione, si possono udire le voci registrate di Ewan McGregor (che riprese appositamente il suo ruolo per una battuta inedita) e persino frammenti audio d''archivio di Alec Guinness che pronuncia la parola ''Rey'', ricavati digitalmente da una vecchia registrazione.', 'Note di montaggio del sonoro e interviste a J.J. Abrams', TRUE, 'IA (Daily Sync)', 'IA Verificata', 0, 4, '2026-11-02T14:45:29.059877+00:00'),
('f80d9f99-2287-4299-bc04-ceb6570d5dec', 76, 'Effetti speciali & Trucco', 'La scelta di non usare il verde cromo ovunque', 'J.J. Abrams ha insistito per costruire set reali e utilizzare location naturali in tutto il mondo (come l''isola di Skellig Michael in Irlanda e i deserti di Abu Dhabi) riducendo al minimo l''uso del green screen per favorire le performance fisiche degli attori.', 'Featurette ''The Visual Effects of The Force Awakens''', TRUE, 'IA (Daily Sync)', 'IA Verificata', 0, 5, '2026-11-02T14:45:29.059877+00:00'),
('4d6a0105-d16e-472c-971d-dcdbcf5b34e0', 76, 'Citazioni & Easter Egg', 'Il cameo segreto di Daniel Craig', 'L''attore Daniel Craig, impegnato nelle vicine riprese di ''Spectre'' ai Pinewood Studios, ha fatto visita al set di Star Wars e ha accettato di interpretare, sotto mentite spoglie e senza mostrare il volto, lo Stormtrooper a cui Rey ordina di liberarla usando un trucco mentale.', 'Conferma ufficiale di Simon Pegg e interviste promozionali', TRUE, 'IA (Daily Sync)', 'IA Verificata', 0, 6, '2026-11-02T14:45:29.059877+00:00'),
('a8b99fec-25b0-4678-bf8a-6276030b43c3', 208, 'Casting & Scelte', 'La sostituzione last-minute di Al Pacino', 'Al Pacino avrebbe dovuto doppiare il cattivo principale El Macho, arrivando persino a registrare gran parte delle sue battute. Tuttavia, l''attore ha abbandonato il progetto a poche settimane dall''uscita cinematografica a causa di divergenze creative irrisolvibili con la produzione sulla direzione del personaggio.', 'Comunicato ufficiale Illumination Entertainment e interviste ai registi', TRUE, 'IA (Daily Sync)', 'IA Verificata', 0, 0, '2026-11-02T14:46:30.619519+00:00'),
('d650455d-9c75-4cd9-aecc-22f729535eaf', 208, 'Casting & Scelte', 'L''arrivo d''emergenza di Benjamin Bratt', 'Dopo l''abbandono improvviso di Al Pacino, la produzione ha ingaggiato d''urgenza Benjamin Bratt per sostituirlo nel ruolo di El Macho. Bratt ha dovuto registrare interamente le battute del cattivo in tempi record per rispettare la scadenza della distribuzione internazionale del film.', 'Note di produzione ufficiali Universal Pictures', TRUE, 'IA (Daily Sync)', 'IA Verificata', 0, 1, '2026-11-02T14:46:30.619519+00:00'),
('9c624f16-330a-4082-b288-8796ee674478', 212, 'Segreti di produzione', 'La genesi e il design di Gru Jr.', 'Gli animatori della Illumination hanno studiato centinaia di video di veri neonati per catturare le espressioni e i movimenti realistici di Gru Jr., specialmente nelle sequenze in cui mostra totale apatia nei confronti del padre.', 'Note di produzione ufficiali Illumination Entertainment', TRUE, 'IA (Daily Sync)', 'IA Verificata', 0, 0, '2026-11-02T10:13:06.982485+00:00'),
('070a6e41-4fad-4741-82ee-aedf6a0b5aa8', 224, 'Curiosità & Retroscena', 'La censura della crocefissione finale', 'Il finale originale prevedeva una sequenza molto più lunga e grafica in cui centinaia di schiavi venivano crocifissi lungo la Via Appia. Questa parte fu fortemente criticata dalla censura dell''epoca e ridotta drasticamente prima dell''uscita nelle sale cinematografiche.', 'Archivi di produzione Universal Pictures e biografie storiche del film', TRUE, 'IA (Daily Sync)', 'IA Verificata', 0, 0, '2026-11-02T10:19:28.97949+00:00'),
('a24918a3-daa8-4c29-890a-633d2aa7940d', 224, 'Casting & Scelte', 'La sostituzione improvvisa di Sabu', 'L''attore Sabu, celebre star di film d''avventura, era stato originariamente ingaggiato per interpretare il gladiatore Antonino. Tuttavia, a causa di complicazioni con il visto di lavoro per la Spagna, la produzione fu costretta a sostituirlo all''ultimo minuto con Tony Curtis.', 'Note di produzione e contratti originali della Universal', TRUE, 'IA (Daily Sync)', 'IA Verificata', 0, 1, '2026-11-02T10:19:28.97949+00:00'),
('63b1da51-318d-4628-87ed-56e6e98bf773', 224, 'Aneddoti dal set', 'L''infortunio di Kirk Douglas con la spada', 'Durante le prove delle scene di combattimento nell''arena dei gladiatori, Kirk Douglas subì accidentalmente un profondo taglio al naso causato da una spada di scena. Il make-up dovette lavorare ore per nascondere il gonfiore nelle riprese dei giorni successivi.', 'Autobiografia di Kirk Douglas ''The Ragman''s Son''', TRUE, 'IA (Daily Sync)', 'IA Verificata', 0, 2, '2026-11-02T10:19:28.97949+00:00'),
('366f31fe-b8f9-445e-80a5-752eee19ebbd', 224, 'Aneddoti dal set', 'Il rifiuto di Laurence Olivier di usare le controfigure', 'Laurence Olivier insistette per girare personalmente tutte le sue scene d''azione e di scherma contro i gladiatori, rifiutando categoricamente l''uso di stuntmen nonostante la sua età non più giovanissima.', 'Documentario ''The Making of Spartacus'' contenuto nell''edizione Blu-ray', TRUE, 'IA (Daily Sync)', 'IA Verificata', 0, 3, '2026-11-02T10:19:28.97949+00:00'),
('bda02804-fdc5-442a-9327-644c26954de9', 224, 'Curiosità & Retroscena', 'Il taglio imposto dalla MPAA sul montaggio', 'Prima della distribuzione nazionale, la Motion Picture Association of America impose il taglio di circa due minuti di girato considerato eccessivamente violento e immorale, materiale che è andato perduto per decenni prima del restauro del 1991.', 'Registri ufficiali della MPAA e note di restauro di Robert A. Harris', TRUE, 'IA (Daily Sync)', 'IA Verificata', 0, 4, '2026-11-02T10:19:28.97949+00:00'),
('41d8e561-857f-49e3-9878-292acd173b27', 280, 'Casting & Scelte', 'La causa legale tra Crispin Glover e i produttori', 'Crispin Glover fece causa alla Universal Pictures e alla produzione di Steven Spielberg per aver utilizzato il calco del suo viso e spezzoni di repertorio del primo film senza il suo consenso, inserendo un attore con protesi per farlo sembrare George McFly. La controversia portò a una stretta revisione delle regole del sindacato degli attori (Screen Actors Guild) riguardo all''uso non autorizzato dell''immagine tramite protesi e riprese d''archivio.', 'Documenti giudiziari della causa Glover vs. Universal Pictures e interviste retrospettive', TRUE, 'IA (Daily Sync)', 'IA Verificata', 0, 0, '2026-11-02T10:25:02.251247+00:00'),
('29b15771-a4e1-4566-b3d0-ee719398617a', 280, 'Casting & Scelte', 'Il cameo nascosto di Flea dei Red Hot Chili Peppers', 'Michael Peter Balzary, in arte Flea, bassista dei Red Hot Chili Peppers, interpreta il ruolo di Douglas Needles, il collega che spinge Marty a fare una scommessa pericolosa via fax nel 2015 e che lo licenzia nel 1985 alternativo. Flea tornerà a ricoprire lo stesso ruolo anche nel terzo capitolo della saga.', 'Crediti ufficiali del film e note di produzione della Universal', TRUE, 'IA (Daily Sync)', 'IA Verificata', 0, 1, '2026-11-02T10:25:02.251247+00:00'),
('c1482b43-6ad8-4d18-a0c5-e2aa3e261074', 280, 'Citazioni & Easter Egg', 'La finta copertina della rivista USA Today', 'Nel giornale USA Today del 22 ottobre 2015 che Marty legge nel futuro, oltre alla notizia principale sull''arresto del figlio Marty Jr., compaiono titoli minori realmente ironici e predittivi, tra cui la notizia che la regina Elisabetta festeggia il suo 40° anno di regno e che la città di Chicago ha eletto un sindaco donna.', 'Analisi dettagliata del prop originale e commento audio del regista Robert Zemeckis e dello sceneggiatore Bob Gale', TRUE, 'IA (Daily Sync)', 'IA Verificata', 0, 2, '2026-11-02T10:25:02.251247+00:00'),
('dbbcb942-0d5e-4ac8-9749-ae87711c427a', 280, 'Aneddoti dal set', 'L''infortunio alla mano di Michael J. Fox con la chitarra', 'Durante la sequenza in cui Marty suona la chitarra sul palco della scuola nel 1955 (durante il ballo ''Incanto sottobosco''), Michael J. Fox ha dovuto suonare imitando lo stile di Chuck Berry e Eddie Van Halen. Sebbene non si sia fatto male gravemente in quell''occasione specifica, l''attore ha spesso ricordato la fatica fisica estrema per coordinare le parti suonate in playback con le complesse coreografie e le riprese multiple.', 'Special TV ''The Making of Back to the Future Part II'' e interviste a Michael J. Fox', TRUE, 'IA (Daily Sync)', 'IA Verificata', 0, 3, '2026-11-02T10:25:02.251247+00:00'),
('fc8a5f6f-93e3-4b32-be7b-34c79e544fce', 280, 'Segreti di produzione', 'Il ritardo di un anno dovuto alla post-produzione', 'Nonostante ''Ritorno al futuro - Parte II'' e ''Parte III'' siano stati girati consecutivamente in gran parte, l''uscita nelle sale cinematografiche fu posticipata dal Natale 1988 al novembre 1989. Il ritardo fu causato dalla complessa e pionieristica tecnologia di controllo di movimento VistaGlide sviluppata dalla Industrial Light & Magic per permettere a Michael J. Fox di interagire con se stesso in tre ruoli contemporaneamente.', 'Archivio storico della Industrial Light & Magic (ILM) e note di produzione Universal', TRUE, 'IA (Daily Sync)', 'IA Verificata', 0, 4, '2026-11-02T10:25:02.251247+00:00'),
('933eee12-82a4-4893-8f72-f30f09261956', 112, 'Curiosità & Retroscena', 'Origini come spec script intitolato ''The Cellar''', 'La sceneggiatura originale scritta da Josh Campbell e Matthew Stuecken s''intitolava ''The Cellar'' e circolava a Hollywood da anni come spec script prima di essere acquisita dalla Bad Robot di J.J. Abrams e trasformata in un thriller ambientato nell''universo narrativo di Cloverfield.', 'Note di produzione ufficiali Paramount Pictures', TRUE, 'IA (Daily Sync)', 'IA Verificata', 0, 0, '2026-11-02T14:45:49.609454+00:00'),
('35a4b741-b867-4f00-864a-8f601e96d707', 112, 'Curiosità & Retroscena', 'La genesi del titolo ''10 Cloverfield Lane''', 'Il titolo definitivo è stato rivelato al pubblico solo due mesi prima dell''uscita nelle sale, tramite un trailer a sorpresa allegato alle proiezioni di ''13 Hours: The Secret Soldiers of Benghazi'', replicando la strategia di marketing virale del primo film del 2008.', 'Comunicato stampa ufficiale Paramount / Variety', TRUE, 'IA (Daily Sync)', 'IA Verificata', 0, 1, '2026-11-02T14:45:49.609454+00:00'),
('d956c948-7a13-4592-be94-aa0b43eb29f8', 112, 'Casting & Scelte', 'L''ingresso di Dan Trachtenberg alla regia', 'Dan Trachtenberg fu ingaggiato per dirigere il film dopo aver impressionato la Bad Robot con il suo cortometraggio fan-made ''Portal: No Escape'' e con un pitch incentrato sulla tensione psicologica piuttosto che sul puro mostro cinematografico.', 'Intervista al regista su The Hollywood Reporter', TRUE, 'IA (Daily Sync)', 'IA Verificata', 0, 2, '2026-11-02T14:45:49.609454+00:00'),
('3f6e2a1b-c0d3-4c36-a8ab-79699c40f4bb', 212, 'Curiosità & Retroscena', 'Il ritorno alla regia di Chris Renaud', 'Chris Renaud, co-creatore del franchise e regista dei primi due capitoli, è tornato a dirigere la serie principale a distanza di sette anni da Cattivissimo me 3, affiancato dal co-regista Patrick Delage.', 'Cartella stampa ufficiale del film', TRUE, 'IA (Daily Sync)', 'IA Verificata', 0, 1, '2026-11-02T10:13:06.982485+00:00'),
('76b33203-9d98-4dbe-8d7f-91eebdc58dd1', 212, 'Casting & Scelte', 'Stephen Colbert e Miranda Cosgrove nel cast vocale', 'Il celebre conduttore televisivo Stephen Colbert si è unito al cast del film prestando la voce al personaggio di Perry Prescott, affiancando Miranda Cosgrove che torna per la quarta volta a doppiare la figlia maggiore di Gru, Margo.', 'Crediti ufficiali e cast del film', TRUE, 'IA (Daily Sync)', 'IA Verificata', 0, 2, '2026-11-02T10:13:06.982485+00:00'),
('60b0fd36-60c1-42ae-984d-2f84a776c8d2', 340, 'Segreti di produzione', 'L''uso dei colori nei costumi', 'La costumista Ann Roth e il regista hanno studiato meticolosamente la palette cromatica dei vestiti indossati dai personaggi per indicare la loro evoluzione psicologica e il loro ritorno alla fede. Mel Gibson indossa abiti scuri e dismessi nei primi atti, per poi riprendere abiti legati al suo passato ecclesiastico nel finale.', 'Intervista alla costumista Ann Roth per American Cinematographer', TRUE, 'IA (Daily Sync)', 'IA Verificata', 0, 4, '2026-11-02T14:51:17.613497+00:00'),
('83a27593-7dd7-43ea-bfee-99702089d372', 229, 'Segreti di produzione', 'La genesi della sceneggiatura di John Hughes', 'Il creatore e sceneggiatore storico della saga, John Hughes, ha scritto la sceneggiatura di Home Alone 3 sganciandosi completamente dalla famiglia McCallister per creare una cellula terroristica internazionale come antagonisti, ispirandosi ai film di spionaggio degli anni ''90 ma mantenendo l''impostazione slapstick del genere natalizio.', 'Archivio storico della produzione cinematografica', TRUE, 'IA (Daily Sync)', 'IA Verificata', 0, 1, '2026-11-02T10:19:34.406981+00:00'),
('b47ebd25-8d06-4aba-a1a4-d8ccc1aa1a51', 281, 'Casting & Scelte', 'Il rifiuto di Ronald Reagan', 'Il regista Robert Zemeckis offrì ufficialmente il ruolo del sindaco di Hill Valley del 1885, Hubert, all''ex Presidente Ronald Reagan. Nonostante Reagan fosse un grande fan del primo film (che citò persino in un discorso sullo Stato dell''Unione), declinò gentilmente l''offerta.', 'Commento audio del DVD di Robert Zemeckis e Bob Gale', TRUE, 'IA (Daily Sync)', 'IA Verificata', 0, 0, '2026-11-02T10:26:18.0925+00:00'),
('7b48612f-bcec-46eb-a8b1-99e552b3a973', 281, 'Segreti di produzione', 'La locomotiva Sierra No. 3', 'La locomotiva a vapore utilizzata, rinominata ''Central Pacific No. 131'', è la celebre Sierra No. 3, nota come ''la locomotiva delle star''. È uno dei treni più filmati della storia del cinema, apparso in oltre 100 produzioni tra cui ''Il texano dagli occhi di ghiaccio'' e ''Mezzogiorno di fuoco''.', 'Documentario ''Tales from the Future: Third Time''s a Charm''', TRUE, 'IA (Daily Sync)', 'IA Verificata', 0, 1, '2026-11-02T10:26:18.0925+00:00'),
('7985c47a-c475-4ce9-a800-818ad27aa05f', 281, 'Effetti speciali & Trucco', 'Il modellino in scala 1/4 per lo scontro finale', 'Per la scena finale in cui il treno moderno travolge la DeLorean, la Industrial Light & Magic costruì un modellino in scala 1/4 estremamente dettagliato. Gli ingegneri decisero di non usare un''auto vera perché il metallo reale non si sarebbe frantumato in modo scenografico come richiesto dalla regia.', 'Dietro le quinte ufficiale ILM (Industrial Light & Magic)', TRUE, 'IA (Daily Sync)', 'IA Verificata', 0, 2, '2026-11-02T10:26:18.0925+00:00'),
('a7e510d4-6b55-4ca7-a922-0bc315fcde8a', 281, 'Citazioni & Easter Egg', 'Il riciclo della camicia di Doc', 'La bandana che Doc Brown indossa durante la rapina al treno nel 1885 è ricavata dalla stessa camicia gialla con i disegni di treni che il personaggio indossava alla fine del secondo capitolo. È un dettaglio simbolico che collega i due film attraverso il design dei costumi di Joanna Johnston.', 'Intervista alla costumista Joanna Johnston', TRUE, 'IA (Daily Sync)', 'IA Verificata', 0, 3, '2026-11-02T10:26:18.0925+00:00'),
('578c4c0f-e42a-4a47-8da1-1255436a05a8', 281, 'Casting & Scelte', 'Il ritorno di Flea dei Red Hot Chili Peppers', 'Michael Balzary, meglio noto come Flea, bassista dei Red Hot Chili Peppers, riprende il ruolo di Douglas J. Needles nella sequenza finale del 1985. La sua presenza serve a chiudere l''arco narrativo di Marty, che finalmente rifiuta la sfida alla gara di velocità evitando l''incidente con la Rolls-Royce.', 'Titoli di coda e interviste al cast', TRUE, 'IA (Daily Sync)', 'IA Verificata', 0, 4, '2026-11-02T10:26:18.0925+00:00'),
('ec0fb894-0092-429a-8bcb-bd8f0e67113e', 281, 'Aneddoti dal set', 'La prima scena girata fu una fotografia', 'La primissima scena girata per la Parte III non coinvolse dialoghi, ma fu lo scatto della fotografia di Marty e Doc davanti all''orologio della torre appena arrivato in città. Questo fu necessario affinché la foto fisica potesse essere utilizzata come oggetto di scena durante tutto il resto delle riprese.', 'Note di produzione ufficiali Universal Pictures', TRUE, 'IA (Daily Sync)', 'IA Verificata', 0, 5, '2026-11-02T10:26:18.0925+00:00'),
('769a5458-beb1-4ba9-8ea7-e2bb9ba81045', 281, 'Segreti di produzione', 'Il set del Drive-In nella Monument Valley', 'Il ''Pohatchee Drive-In'', da dove Marty parte per il 1885, fu costruito da zero nella Monument Valley, un luogo iconico del cinema western di John Ford. Il set era così realistico che alcuni turisti cercarono di entrarvi per vedere un film, ignari che fosse solo una facciata cinematografica.', 'Making-of ''Back to the Future Part III''', TRUE, 'IA (Daily Sync)', 'IA Verificata', 0, 6, '2026-11-02T10:26:18.0925+00:00'),
('f7c94ad1-c210-4229-86b1-178b5a9d0954', 281, 'Citazioni & Easter Egg', 'L''omaggio ai nomi di Jules Verne', 'I figli di Doc e Clara si chiamano Jules e Verne in onore dello scrittore Jules Verne. Questo omaggio è preparato durante tutto il film: Clara rivela di essere un''appassionata dell''autore e Doc confessa che ''Dalla Terra alla Luna'' è il libro che ha cambiato la sua vita.', 'Sceneggiatura originale di Bob Gale', TRUE, 'IA (Daily Sync)', 'IA Verificata', 0, 7, '2026-11-02T10:26:18.0925+00:00'),
('2034912f-12aa-4ab0-9507-cdaf14002711', 281, 'Effetti speciali & Trucco', 'Il trucco tecnico dell''Hoverboard sulle rotaie', 'Per far scivolare l''Hoverboard lungo le rotaie del treno, la produzione utilizzò un sistema di cavi ad alta tensione e piccoli rulli nascosti sotto la tavola. Gli attori dovevano mantenere un equilibrio perfetto mentre venivano trainati a velocità sostenuta per simulare la levitazione magnetica.', 'Intervista al supervisore degli effetti visivi Ken Ralston', TRUE, 'IA (Daily Sync)', 'IA Verificata', 0, 8, '2026-11-02T10:26:18.0925+00:00'),
('1db4379d-1a7d-4914-846e-56cc4664686c', 281, 'Curiosità & Retroscena', 'La canzone ''Doubleback'' scritta per il film', 'Il gruppo ZZ Top non si limitò al cameo, ma scrisse appositamente il brano ''Doubleback'' per la colonna sonora. Nel film eseguono una versione acustica in stile country-western durante la festa, mentre la versione rock originale accompagna i titoli di coda.', 'Note di copertina della colonna sonora di Alan Silvestri', TRUE, 'IA (Daily Sync)', 'IA Verificata', 0, 9, '2026-11-02T10:26:18.0925+00:00'),
('8c5529ad-67a4-4feb-a9f5-67a25460430e', 112, 'Casting & Scelte', 'Bradley Cooper e il cameo vocale', 'La voce di Ben, il personaggio al telefono con Michelle (Mary Elizabeth Winstead) all''inizio del film, appartiene a Bradley Cooper, il quale ha registrato il breve cameo vocale in amicizia con il produttore J.J. Abrams.', 'Crediti del film e intervista a Mary Elizabeth Winstead', TRUE, 'IA (Daily Sync)', 'IA Verificata', 0, 3, '2026-11-02T14:45:49.609454+00:00'),
('2c3f6b40-2d52-424e-90fc-968db552c46e', 112, 'Casting & Scelte', 'La scelta di John Goodman come Howard Stambler', 'Il regista Dan Trachtenberg ha voluto fortemente John Goodman perché capace di passare in un istante da figura paterna e protettiva a presenza minacciosa e imprevedibile, rendendo ambigua la vera natura del suo personaggio.', 'Commento audio del regista nel Blu-ray', TRUE, 'IA (Daily Sync)', 'IA Verificata', 0, 4, '2026-11-02T14:45:49.609454+00:00'),
('5436fe80-e371-481a-b728-b8f1e8a5e354', 112, 'Aneddoti dal set', 'Isolamento fisico degli attori sul set', 'Per favorire la tensione claustrofobica e la diffidenza reciproca tra i personaggi, gran parte delle scene all''interno del bunker sono state girate in ordine cronologico, con John Goodman che manteneva una certa distanza emotiva dagli altri attori anche fuori ciak.', 'Making-of ufficiale ''Leggenda e retroscena''', TRUE, 'IA (Daily Sync)', 'IA Verificata', 0, 5, '2026-11-02T14:45:49.609454+00:00'),
('7a12568e-dd35-4e80-938e-cb2d53ef4841', 213, 'Segreti di produzione', 'L''uso dei serbatoi d''acqua della Warner Bros. a Leavesden', 'Gran parte delle sequenze oceaniche non è stata girata in mare aperto, ma nei giganteschi serbatoi d''acqua esterni dei Warner Bros. Studios di Leavesden, combinati con la tecnologia di proiezione LED avanzata per sincronizzare l''illuminazione naturale.', 'Production notes ufficiali Warner Bros.', TRUE, 'IA (Daily Sync)', 'IA Verificata', 0, 0, '2026-11-02T10:13:12.721225+00:00'),
('34314997-3cfb-4ae1-b896-5fc82fd3af23', 213, 'Casting & Scelte', 'La parentela reale tra attore e personaggio', 'Brendan Gleeson, che interpreta il superstite Thomas Nickerson in età adulta, ha condiviso il set con il figlio Domhnall Gleeson in passato, ma per questo ruolo ha dichiarato di essersi ispirato profondamente ai diari storici originali scritti dal vero Nickerson.', 'Intervista stampa di Brendan Gleeson', TRUE, 'IA (Daily Sync)', 'IA Verificata', 0, 1, '2026-11-02T10:13:12.721225+00:00'),
('cc385bfe-fdae-456d-ad47-b670f4ad0aaa', 213, 'Aneddoti dal set', 'Le riprese a La Gomera nelle Isole Canarie', 'Per le riprese in esterni che richiedevano coste selvagge e scogliere incontaminate per simulare il Sud America e il Pacifico meridionale, la produzione si è trasferita sull''isola di La Gomera nelle Canarie, sfruttando i paesaggi vulcanici locali.', 'Reportage dal set cinematografico', TRUE, 'IA (Daily Sync)', 'IA Verificata', 0, 2, '2026-11-02T10:13:12.721225+00:00'),
('b2a19533-5f99-4d1a-8f79-284d2f824dc8', 230, 'Segreti di produzione', 'La scelta delle location in Sudafrica', 'Nonostante la storia sia ambientata negli Stati Uniti, la produzione scelse di girare interamente a Città del Capo, in Sudafrica, per sfruttare costi di produzione notevolmente inferiori rispetto a Los Angeles o Chicago.', 'Note di produzione ufficiali della Twentieth Century Fox', TRUE, 'IA (Daily Sync)', 'IA Verificata', 0, 0, '2026-11-02T10:19:39.862547+00:00'),
('aa5ece49-96eb-45df-8e12-64fefc310ec3', 230, 'Curiosità & Retroscena', 'Il cambio di network televisivo', 'Il film fu commissionato direttamente dal network ABC come ''Wonderful World of Disney'', debuttando in televisione nel novembre del 2002 con ascolti iniziali monitorati da Nielsen Media Research.', 'Archivio storico dei palinsesti ABC Television', TRUE, 'IA (Daily Sync)', 'IA Verificata', 0, 1, '2026-11-02T10:19:39.862547+00:00'),
('27330aa7-b334-4b44-9276-cc6a88b64274', 282, 'Casting & Scelte', 'La voce originale di Morgan Freeman', 'Nel commento audio del DVD, Frank Darabont rivela che le riprese erano già iniziate da tre settimane quando ci si rese conto che la voce fuori campo registrata da Morgan Freeman non era sincronizzata correttamente con le immagini; Freeman dovette ri-registrare l''intero commento vocale in sole tre settimane.', 'Commento audio del regista Frank Darabont', TRUE, 'IA (Daily Sync)', 'IA Verificata', 0, 0, '2026-11-02T10:27:01.117582+00:00'),
('cc3f9579-02db-4ea6-b3c1-77e1c2499c66', 282, 'Segreti di produzione', 'Il ritratto giovanile di Morgan Freeman', 'La foto segnaletica giovanile mostrata nel fascicolo della condanna di Red non ritrae l''attore Morgan Freeman da giovane, bensì suo figlio minore, Alfonso Freeman, il quale fa anche un breve cameo nel film come comparsa.', 'Documentario ufficiale del Making-of e crediti del film', TRUE, 'IA (Daily Sync)', 'IA Verificata', 0, 1, '2026-11-02T10:27:01.117582+00:00'),
('3d1b7abd-d7d8-4d59-a541-1b2eb892a115', 282, 'Aneddoti dal set', 'La finta pioggia notturna', 'La celebre e liberatoria scena in cui Andy emerge dal tubo fognario sotto la pioggia ha richiesto due settimane di riprese notturne consecutive. Tim Robbins e la troupe dovettero lavorare nelle acque gelide utilizzando idranti antincendio della città di Mansfield per simulare il temporale.', 'Note di produzione e interviste al cast', TRUE, 'IA (Daily Sync)', 'IA Verificata', 0, 2, '2026-11-02T10:27:01.117582+00:00'),
('f1a3104f-4eeb-4cbe-9cc1-541f32b2cfcc', 112, 'Aneddoti dal set', 'L''infortunio di John Gallagher Jr.', 'L''attore John Gallagher Jr., che interpreta Emmett, ha girato gran parte delle sue scene con un braccio realmente fasciato e immobilizzato a causa di una lussazione subita poco prima dell''inizio delle riprese, poi incorporata nella sceneggiatura.', 'Intervista promozionale a John Gallagher Jr.', TRUE, 'IA (Daily Sync)', 'IA Verificata', 0, 6, '2026-11-02T14:45:49.609454+00:00'),
('e4fa045f-1e7f-4368-97f0-d27176b0ef0e', 112, 'Segreti di produzione', 'Costruzione del set a pianta circolare', 'Il set del bunker è stato costruito su un palcoscenico a pianta parzialmente circolare e modulare, con pareti rimovibili per permettere alla macchina da presa di effettuare movimenti fluidi e claustrofobici senza ostacoli.', 'Special report scenografia - American Cinematographer', TRUE, 'IA (Daily Sync)', 'IA Verificata', 0, 7, '2026-11-02T14:45:49.609454+00:00'),
('f5a5ed28-479a-4b29-9c95-e649ed7b28dc', 112, 'Segreti di produzione', 'L''uso dei costumi per definire lo status di prigioniera', 'La costumista Michelle Cluny ha ideato il guardaroba di Mary Elizabeth Winstead facendo in modo che i suoi abiti cambiassero gradualmente, riflettendo la sua perdita di autonomia e il suo adattamento forzato alla vita sotterranea.', 'Note di produzione costumi', TRUE, 'IA (Daily Sync)', 'IA Verificata', 0, 8, '2026-11-02T14:45:49.609454+00:00'),
('0a5dbcce-efc3-4c8f-bb18-b3071d708814', 112, 'Effetti speciali & Trucco', 'Effetti speciali artigianali per la tuta chimica', 'La tuta e la maschera protettiva improvvisate da Michelle utilizzando materiali di fortuna reperiti nel bunker sono state realizzate dal reparto artigianale con componenti reali di idraulica e filtrazione per apparire perfettamente funzionali.', 'Featurette sugli effetti pratici nel Blu-ray', TRUE, 'IA (Daily Sync)', 'IA Verificata', 0, 9, '2026-11-02T14:45:49.609454+00:00'),
('f6395cdf-0eb2-4f73-838f-868adba110d8', 112, 'Effetti speciali & Trucco', 'La creazione del design alieno finale', 'Il design della creatura aliena e della sua astronave nella sequenza finale è stato curato dalla Industrial Light & Magic (ILM), mantenendo una coerenza estetica e biologica con il mostro visto nel film originale del 2008.', 'The Art of Cloverfield Lane / ILM report', TRUE, 'IA (Daily Sync)', 'IA Verificata', 0, 10, '2026-11-02T14:45:49.609454+00:00'),
('89139e06-e689-4904-82e7-df866f23a604', 112, 'Citazioni & Easter Egg', 'Il juke-box e la musica come elemento di tensione', 'Il juke-box presente nel bunker riproduce brani d''epoca come ''I Think We''re Alone Now'', che assumono un valore ironico e macabro nel contesto della reclusione forzata imposta da Howard.', 'Analisi della colonna sonora di Bear McCreary', TRUE, 'IA (Daily Sync)', 'IA Verificata', 0, 11, '2026-11-02T14:45:49.609454+00:00'),
('1ad72346-189e-4e23-9490-fde93fdd087b', 112, 'Citazioni & Easter Egg', 'Il collegamento sonoro con il primo Cloverfield', 'In alcune sequenze del film, inserite nel sound design generale, si possono udire rielaborazioni a bassa frequenza dei celebri versi emessi dal mostro gigante del film del 2008, nascosti tra i rumori ambientali del bunker.', 'Intervista al sound designer Steve Boeddeker', TRUE, 'IA (Daily Sync)', 'IA Verificata', 0, 12, '2026-11-02T14:45:49.609454+00:00'),
('402084a7-1c96-4957-a21b-9628757953d6', 187, 'Casting & Scelte', 'La preparazione fisica estrema di So Ji-sub', 'Per interpretare il ruolo dell''ex pugile Chul-min, l''attore So Ji-sub si è sottoposto a tre mesi di allenamento intensivo quotidiano con l''ex campione di pugilate Wei Seong-bae, perdendo diversi chili di peso per assumere una corporatura asciutta e muscolosa.', 'Note di produzione ufficiali CJ Entertainment', TRUE, 'IA (Daily Sync)', 'IA Verificata', 0, 0, '2026-11-02T14:46:14.255744+00:00'),
('df6ecbd2-cde0-40e6-85bb-24bd2a8d0b05', 187, 'Curiosità & Retroscena', 'La scelta del remake di un classico', 'Il regista Song Il-gon ha rivelato nelle interviste promozionali che il film è ispirato liberamente al capolavoro di Charlie Chaplin ''Luci della città'' (1931), riadattando la dinamica tra l''emarginato e la ragazza cieca in chiave moderna e melodrammatica coreana.', 'Conferenza stampa ufficiale del Busan International Film Festival 2011', TRUE, 'IA (Daily Sync)', 'IA Verificata', 0, 1, '2026-11-02T14:46:14.255744+00:00'),
('049abedd-9ebd-4899-b946-cb0e9c7824fa', 216, 'Curiosità & Retroscena', 'La collaborazione con Roger Waters per la canzone tema', 'Il leggendario bassista dei Pink Floyd, Roger Waters, ha co-scritto insieme a Ennio Morricone il brano principale del film intitolato ''Lost Boys Calling''. La canzone, interpretata da Waters stesso, è stata candidata ai Golden Globe nel 2000 nella categoria per la migliore canzone originale.', 'Note di produzione ufficiali e crediti della colonna sonora del film', TRUE, 'IA (Daily Sync)', 'IA Verificata', 0, 0, '2026-11-02T10:13:50.981106+00:00'),
('53555a49-8165-4f5b-869f-112988228f15', 216, 'Casting & Scelte', 'La scelta del musicista Gilda Buttà per le parti al pianoforte', 'A prestare le mani a Tim Roth durante le complesse esecuzioni al pianoforte è stata la celebre concertista Gilda Buttà, collaboratrice storica di Ennio Morricone. La pianista suonava fuori campo mentre l''attore, seduto allo strumento, seguiva i suoi movimenti con estrema precisione per mantenere il sincrono.', 'Intervista documentata a Gilda Buttà nel making-of ufficiale del film', TRUE, 'IA (Daily Sync)', 'IA Verificata', 0, 1, '2026-11-02T10:13:50.981106+00:00'),
('5fc83b54-daec-4fc5-9290-786ed66bcac6', 216, 'Casting & Scelte', 'Il cameo del vero jazzista Clarence Williams III', 'L''attore e musicista Clarence Williams III, che nel film interpreta la leggenda del jazz Jelly Roll Morton, era noto al pubblico internazionale soprattutto per il cult televisivo ''Mod Squad'' e per la sua intensa attività musicale. La sua performance nel duello pianistico richiese una complessa combinazione di recitazione e studio dei movimenti dell''epoca.', 'Dizionario del cinema e note di casting della produzione', TRUE, 'IA (Daily Sync)', 'IA Verificata', 0, 2, '2026-11-02T10:13:50.981106+00:00'),
('082a7588-0022-4325-9525-901e5bdbce08', 216, 'Segreti di produzione', 'L''utilizzo di un set galleggiante nel porto di Roma', 'Oltre ai teatri di posa di Cinecittà e alla ricostruzione parziale della nave a Fiumicino, alcune sequenze esterne del transatlantico hanno richiesto l''impiego di una chiatta modificata e posizionata in mare aperto per simulare la navigazione atlantica degli anni ''10 e ''20.', 'Reportage tecnico della rivista cinematografica ''Ciak'' (1998)', TRUE, 'IA (Daily Sync)', 'IA Verificata', 0, 3, '2026-11-02T10:13:50.981106+00:00'),
('c27e73e6-7168-4995-b2a8-b897c00985ee', 234, 'Citazioni & Easter Egg', 'L''ispirazione visiva tratta da ''A Venezia un dicembre rosso shocking''', 'Durante la pre-produzione, Edgar Wright ha organizzato proiezioni speciali per la troupe e il direttore della fotografia Chung Chung-hoon, mostrando capolavori del giallo e del thriller psicologico come ''Don''t Look Now'' (A Venezia un dicembre rosso shocking) di Nicolas Roeg per definire la palette cromatica basata sui forti contrasti tra rosso e blu.', 'Note di produzione ufficiali Focus Features', TRUE, 'IA (Daily Sync)', 'IA Verificata', 0, 0, '2026-11-02T10:19:55.294937+00:00'),
('f33c0a7d-0059-474a-923d-d81fca0b83f3', 234, 'Segreti di produzione', 'La scelta della locazione originale per il pub di Soho', 'Per girare le scene del pub dove lavora il personaggio di Eloise, la produzione ha scelto il reale pub ''The Toucan'' situato a Soho in Carlisle Street, famoso per la sua clientela legata al mondo della musica e per essere un punto di riferimento storico del quartiere.', 'Dizionario delle location cinematografiche londinesi', TRUE, 'IA (Daily Sync)', 'IA Verificata', 0, 1, '2026-11-02T10:19:55.294937+00:00'),
('f7005419-2caf-4950-8305-5326539cf96b', 234, 'Curiosità & Retroscena', 'Il legame personale di Edgar Wright con la Soho degli anni ''60', 'Il regista Edgar Wright si è trasferito a vivere nella zona di Soho nei primi anni ''90, vivendo in prima persona la trasformazione del quartiere e accumulando per decenni gli aneddoti e le suggestioni sulla vita notturna che hanno poi formato la spina dorsale della sceneggiatura scritta insieme a Krysty Wilson-Cairns.', 'Intervista promozionale Empire Magazine', TRUE, 'IA (Daily Sync)', 'IA Verificata', 0, 2, '2026-11-02T10:19:55.294937+00:00'),
('f5721184-c096-4ba9-bbd6-28fecfac26ef', 234, 'Aneddoti dal set', 'La collaborazione con il costumista Odile Dicks-Mireaux', 'Per creare il celebre abito rosa da cocktail indossato da Anya Taylor-Joy nelle sequenze dei club, la costumista Odile Dicks-Mireaux ha condotto ricerche approfondite sugli archivi di moda londinesi dell''epoca, realizzando diversi prototipi identici per permettere le complesse riprese con gli stunt.', 'Featurette ''The Fashion of Last Night in Soho''', TRUE, 'IA (Daily Sync)', 'IA Verificata', 0, 3, '2026-11-02T10:19:55.294937+00:00'),
('965141df-a08d-4ed7-a346-adfc0143ff2d', 283, 'Segreti di produzione', 'Il passaggio dei diritti da Kirk a Michael Douglas', 'Kirk Douglas, che deteneva i diritti del romanzo, li cedette al figlio Michael nel 1971 dopo anni di tentativi falliti di produrre il film. Michael Douglas riuscì a far partire il progetto solo dopo essersi associato con il produttore indipendente Saul Zaentz della Fantasy Records.', 'Documentario ''The Making of One Flew Over the Cuckoo''s Nest''', TRUE, 'IA (Daily Sync)', 'IA Verificata', 0, 0, '2026-11-02T10:27:35.122517+00:00'),
('4ab1cf7e-80eb-4af2-9904-8c4d54aff36c', 283, 'Curiosità & Retroscena', 'Il rifiuto di Ken Kesey e la causa legale', 'L''autore del romanzo Ken Kesey fece causa alla produzione perché la sceneggiatura aveva rimosso il punto di vista narrativo del Grande Capo Bromden, rendendo McMurphy il protagonista assoluto. Kesey dichiarò per anni di non aver mai voluto vedere il film, nonostante il successo planetario.', 'Intervista a Ken Kesey, New York Times', TRUE, 'IA (Daily Sync)', 'IA Verificata', 0, 1, '2026-11-02T10:27:35.122517+00:00'),
('6c1fa449-1b60-42d4-ad91-1d3cada9be12', 283, 'Casting & Scelte', 'Il vero medico nel ruolo del Dr. Spivey', 'Il dottor John Spivey non è interpretato da un attore professionista, ma dal Dr. Dean Brooks, che all''epoca era il reale sovrintendente dell''Oregon State Hospital dove si girava il film. Brooks scrisse personalmente le sue diagnosi cliniche per il personaggio di McMurphy basandosi sul copione.', 'Note di produzione del DVD Special Edition', TRUE, 'IA (Daily Sync)', 'IA Verificata', 0, 2, '2026-11-02T10:27:35.122517+00:00'),
('4e726f34-2ec5-49cc-9672-af72b639c176', 283, 'Casting & Scelte', 'La scoperta fortuita di Will Sampson', 'Will Sampson, che interpreta il Grande Capo, fu trovato da Mel Lambert, un venditore di auto usate incaricato dalla produzione di cercare un nativo americano di statura imponente. Sampson era un ranger di un parco e un partecipante ai rodeo, senza alcuna precedente esperienza recitativa.', 'Intervista a Michael Douglas, American Film Institute', TRUE, 'IA (Daily Sync)', 'IA Verificata', 0, 3, '2026-11-02T10:27:35.122517+00:00'),
('fa943c2e-61f6-44d0-8c43-a40f678597c6', 283, 'Aneddoti dal set', 'Lo spogliarello liberatorio di Louise Fletcher', 'Per scrollarsi di dosso l''immagine odiosa dell''Infermiera Ratched e dimostrare ai colleghi di non essere così gelida, Louise Fletcher si tolse improvvisamente i vestiti restando in biancheria intima davanti a tutto il cast l''ultimo giorno di riprese.', 'Intervista a Louise Fletcher, Academy of Motion Picture Arts and Sciences', TRUE, 'IA (Daily Sync)', 'IA Verificata', 0, 4, '2026-11-02T10:27:35.122517+00:00'),
('e1e4908a-748e-4c84-b2ff-2722c29de433', 283, 'Segreti di produzione', 'Il licenziamento del direttore della fotografia', 'Il celebre direttore della fotografia Haskell Wexler fu licenziato dopo diverse settimane di riprese a causa di forti divergenze artistiche con Miloš Forman. Fu sostituito da Bill Butler, ma Wexler sostenne sempre che circa il 90% del film finale contenesse in realtà il suo lavoro.', 'Autobiografia di Bill Butler / Interviste a Haskell Wexler', TRUE, 'IA (Daily Sync)', 'IA Verificata', 0, 5, '2026-11-02T10:27:35.122517+00:00'),
('e4399cd2-a48b-4c9a-a936-477e97c187db', 283, 'Aneddoti dal set', 'Il mal di mare durante la scena della pesca', 'La sequenza della gita in barca fu l''unica girata fuori dall''ospedale e fu un incubo logistico: quasi tutto il cast e la troupe soffrirono di un violento mal di mare. Jack Nicholson fu l''unico a non risentirne, continuando a recitare mentre gli altri attori vomitavano tra un ciak e l''altro.', 'Commento audio del regista Miloš Forman', TRUE, 'IA (Daily Sync)', 'IA Verificata', 0, 6, '2026-11-02T10:27:35.122517+00:00'),
('ed9190ce-35d7-44b8-b105-1d37b1e9d714', 217, 'Casting & Scelte', 'La connessione vocale con il passato di Star Wars', 'Prima di interpretare ufficialmente Boba Fett nella serie, Temuera Morrison aveva registrato nel 2004 le nuove linee di dialogo vocali per l''edizione in DVD della trilogia originale, doppiando i panni del personaggio originariamente interpretato da Jeremy Bulloch.', 'Note di produzione ufficiali Star Wars.com', TRUE, 'IA (Daily Sync)', 'IA Verificata', 0, 0, '2026-11-02T10:13:57.909054+00:00'),
('5d39962b-69d9-4e21-86ce-a361a7b7b2b0', 217, 'Citazioni & Easter Egg', 'Il nome della nave di Fennec Shand', 'La nave stellare pilotata da Fennec Shand nella serie, una Firespray-31 (già nota come Slave I), non viene mai chiamata con il suo nome originario all''interno dei dialoghi della serie, a causa di una decisione di marketing della Lucasfilm per distanziarsi dal termine ''slave''.', 'Intervista di Matt Martin (Lucasfilm Story Group) a Polygon', TRUE, 'IA (Daily Sync)', 'IA Verificata', 0, 1, '2026-11-02T10:13:57.909054+00:00'),
('2467b10d-aed5-486b-b257-b1e91b3a3a92', 217, 'Aneddoti dal set', 'Il cameo dei registi di robotica', 'I celebri registi e autori di documentari e film indipendenti Jon Favreau, Dave Filoni e persino il musicista Thundercat (che interpreta il modificatore di cyborg) hanno richiesto ruoli minori o camei specifici, con Thundercat che ha trascorso settimane a imparare le tecniche base di protesi e saldatura per rendere credibile la sua scena.', 'Disney+ Gallery: The Book of Boba Fett - Making-of', TRUE, 'IA (Daily Sync)', 'IA Verificata', 0, 2, '2026-11-02T10:13:57.909054+00:00'),
('f6c460f3-96f2-47fe-951f-0ed1b20b2da0', 217, 'Casting & Scelte', 'Il ritorno dell''iconico Skiff Guard', 'L''attore e stuntman bulgaro Paul Darnell e vari membri storici dello stunt team di Star Wars sono stati richiamati per coordinare e interpretare le complesse sequenze di combattimento corpo a corpo nel palazzo di Jabba, ricreando lo stile di lotta visto nel Ritorno dello Jedi.', 'Crediti di troupe e interviste agli stunt coordinator', TRUE, 'IA (Daily Sync)', 'IA Verificata', 0, 3, '2026-11-02T10:13:57.909054+00:00'),
('4728e702-3d82-49c6-b75e-7623066dfe9f', 283, 'Casting & Scelte', 'Le alternative a Jack Nicholson', 'Prima di ingaggiare Jack Nicholson, il ruolo di McMurphy fu offerto a Marlon Brando, Gene Hackman e James Caan, i quali rifiutarono tutti la parte. Anche Burt Reynolds fu preso in considerazione prima che la produzione decidesse che Nicholson fosse l''unico in grado di bilanciare follia e carisma.', 'Archivi di produzione della United Artists', TRUE, 'IA (Daily Sync)', 'IA Verificata', 0, 7, '2026-11-02T10:27:35.122517+00:00'),
('e2e0c540-60e4-480a-9e80-2652fcd11a2a', 283, 'Aneddoti dal set', 'Il crollo emotivo di Sydney Lassick', 'Durante le riprese della scena finale, l''attore Sydney Lassick (Cheswick) ebbe un vero crollo nervoso dovuto all''immedesimazione eccessiva con il suo personaggio. Il suo comportamento divenne così imprevedibile e instabile che dovette essere allontanato fisicamente dal set per permettere la fine delle riprese.', 'Making-of ''Completely Cuckoo''', TRUE, 'IA (Daily Sync)', 'IA Verificata', 0, 8, '2026-11-02T10:27:35.122517+00:00'),
('62c5aa97-02a5-49a1-957b-c50079c58733', 283, 'Segreti di produzione', 'L''accordo finanziario di Nicholson', 'Jack Nicholson accettò un compenso iniziale ridotto rispetto ai suoi standard dell''epoca in cambio di una partecipazione del 15% sugli incassi lordi del film. Dato che la pellicola incassò oltre 100 milioni di dollari contro un budget di soli 4 milioni, l''attore ottenne uno dei guadagni più alti della storia del cinema fino a quel momento.', 'Report finanziari Variety / Biografia di Jack Nicholson', TRUE, 'IA (Daily Sync)', 'IA Verificata', 0, 9, '2026-11-02T10:27:35.122517+00:00'),
('bd4511a2-5a3b-4dab-8325-0df97817eaa7', 113, 'Curiosità & Retroscena', 'Il lancio shock durante il Super Bowl', 'Netflix ha annunciato e rilasciato contemporaneamente il film sulla propria piattaforma la notte stessa del Super Bowl LII, seguendo una strategia di marketing a sorpresa simile a quella adottata per ''10 Cloverfield Lane''.', 'Comunicato ufficiale Netflix / Super Bowl 2018', TRUE, 'IA (Daily Sync)', 'IA Verificata', 0, 2, '2026-11-02T14:45:53.791594+00:00'),
('9ca30f2b-6245-4c96-8d6f-0d50db9dcaa3', 113, 'Segreti di produzione', 'Le riprese aggiuntive sotto la direzione di J.J. Abrams', 'Nel 2016, a seguito di alcune proiezioni di prova non ottimali, la produzione ha effettuato sessioni di riprese aggiuntive supervisionate da J.J. Abrams e dalla Bad Robot per collegare esplicitamente la trama all''universo di Cloverfield.', 'Deadline Hollywood - Report di produzione', TRUE, 'IA (Daily Sync)', 'IA Verificata', 0, 3, '2026-11-02T14:45:53.791594+00:00'),
('1b832212-a889-4256-93af-10284724b51b', 113, 'Casting & Scelte', 'Il legame mancato con il franchise originale', 'Poiché il film è stato scritto e girato come un thriller fantascientifico indipendente, le connessioni con i precedenti capitoli della saga (mostri giganti e cospirazioni globali) sono state inserite quasi interamente in fase di post-produzione tramite dialoghi aggiuntivi e brevi scene esplicative.', 'Intervista al regista Julius Onah', TRUE, 'IA (Daily Sync)', 'IA Verificata', 0, 4, '2026-11-02T14:45:53.791594+00:00'),
('00227ec1-f14b-4105-8612-e8906cdc7dca', 113, 'Effetti speciali & Trucco', 'La costruzione dei set a gravità zero', 'Per simulare l''assenza di gravità all''interno della stazione spaziale Cloverfield, gli attori sono stati spesso sospesi a complessi sistemi di imbracature e cavi, richiedendo intense settimane di addestramento fisico prima dell''inizio delle riprese.', 'Making-of ufficiale del film', TRUE, 'IA (Daily Sync)', 'IA Verificata', 0, 5, '2026-11-02T14:45:53.791594+00:00');
INSERT INTO public.movie_trivia ("id", "film_id", "categoria", "titolo", "descrizione", "fonte", "approvato", "inserito_da", "provenienza", "likes", "ordine", "created_at") VALUES
('c3ab3819-8550-4e7c-a96c-64384db90eef', 181, 'Casting & Scelte', 'La scelta di John Huston per Gandalf', 'Il leggendario regista e attore John Huston fu fortemente voluto dai produttori Rankin e Bass per prestare la voce al mago Gandalf, conferendo al personaggio quella gravitas e autorevolezza shakespeariana che avrebbe definito l''immaginario animato di Tolkien prima della trilogia live-action di Peter Jackson.', 'Note di produzione ufficiali della Rankin/Bass Productions', TRUE, 'IA (Daily Sync)', 'IA Verificata', 0, 0, '2026-11-02T14:46:10.900856+00:00'),
('f3ad1d01-615f-4202-b2cf-51b22ec9dd34', 181, 'Segreti di produzione', 'Lo stile visivo ispirato agli acquerelli', 'Per la direzione artistica del film, i registi si affidarono alle illustrazioni classiche di Arthur Rackham e ai dipinti di J.R.R. Tolkien stesso, impiegando una tecnica di animazione che ricreava l''effetto visivo dei dipinti ad acquerello e dei libri di fiabe illustrati.', 'Artbook ufficiale e documentario retrospettivo sulla Rankin/Bass', TRUE, 'IA (Daily Sync)', 'IA Verificata', 0, 1, '2026-11-02T14:46:10.900856+00:00'),
('829f6e92-975c-487b-a0c9-c4f2bb78a0f2', 181, 'Casting & Scelte', 'Il doppiaggio di Orson Bean come Bilbo', 'L''attore e comico Orson Bean fu scelto per doppiare il protagonista Bilbo Baggins grazie alla sua capacità di trasmettere un tono casalingo, ingenuo ma capace di evolversi in un eroe coraggioso durante il viaggio verso la Montagna Solitaria.', 'Archivio storico del doppiaggio e interviste d''archivio', TRUE, 'IA (Daily Sync)', 'IA Verificata', 0, 2, '2026-11-02T14:46:10.900856+00:00'),
('30e2124f-6beb-4326-b9d0-83200d2e61f8', 181, 'Segreti di produzione', 'La produzione giapponese dello studio Topcraft', 'Sebbene il cartone animato fosse una produzione statunitense della Rankin/Bass, l''animazione effettiva fu affidata allo studio giapponese Topcraft, lo stesso nucleo di artisti che avrebbe successivamente fondato il celebre Studio Ghibli sotto la guida di Hayao Miyazaki e Isao Takahata.', 'Credits ufficiali del film e cronache storiche dell''animazione', TRUE, 'IA (Daily Sync)', 'IA Verificata', 0, 3, '2026-11-02T14:46:10.900856+00:00'),
('5b211626-726f-4707-ab8a-9e60c9c3475d', 181, 'Curiosità & Retroscena', 'L''adattamento musicale di Maury Laws e Jules Bass', 'Le canzoni presenti nel film, inclusi i testi tratti direttamente dai poemi originali di J.R.R. Tolkien come ''The Road Goes Ever On'', furono musicate dal compositore Maury Laws in collaborazione con lo stesso co-regista Jules Bass.', 'Colonna sonora originale in vinile e note di copertina', TRUE, 'IA (Daily Sync)', 'IA Verificata', 0, 4, '2026-11-02T14:46:10.900856+00:00'),
('accc3ded-c047-4746-8934-d68ca546aa1b', 284, 'Segreti di produzione', 'Il prezzo record della sceneggiatura', 'William Goldman vendette la sceneggiatura alla 20th Century Fox per 400.000 dollari, una cifra senza precedenti per l''epoca (1968). Il prezzo elevato scatenò una guerra d''asta tra i principali studi di Hollywood, consolidando la fama di Goldman come uno degli autori più pagati del settore.', 'Saggio ''Adventures in the Screen Trade'' di William Goldman', TRUE, 'IA (Daily Sync)', 'IA Verificata', 0, 0, '2026-11-02T10:28:36.347973+00:00'),
('548cf6a6-3278-4a8e-b887-be4101521cc1', 284, 'Segreti di produzione', 'L''inversione del titolo originale', 'Il titolo originale dello script era ''The Sundance Kid and Butch Cassidy''. Fu invertito in ''Butch Cassidy and the Sundance Kid'' solo dopo che Paul Newman accettò la parte, poiché Newman era la star principale e il suo personaggio doveva apparire per primo nel titolo.', 'Note di produzione della 20th Century Fox', TRUE, 'IA (Daily Sync)', 'IA Verificata', 0, 1, '2026-11-02T10:28:36.347973+00:00'),
('2fa7622a-dbe7-40a8-9789-616c174ea46d', 284, 'Aneddoti dal set', 'L''epidemia di ''Vendetta di Montezuma'' sul set', 'Durante le riprese in Messico, quasi l''intera troupe fu colpita da una grave forma di dissenteria. Paul Newman, Robert Redford e Katharine Ross furono tra i pochi a salvarsi perché si rifiutarono categoricamente di bere l''acqua locale, consumando esclusivamente bibite gassate e birra per tutta la durata della trasferta.', 'Biografia ''Robert Redford: The Biography'' di Michael Feeney Callan', TRUE, 'IA (Daily Sync)', 'IA Verificata', 0, 2, '2026-11-02T10:28:36.347973+00:00'),
('a031fec3-ee6a-4327-a613-856982e9e099', 284, 'Aneddoti dal set', 'Katharine Ross bandita dal set', 'L''attrice Katharine Ross fu bandita dal set dal regista George Roy Hill quando non era impegnata nelle sue scene. Il provvedimento fu preso dopo che Hill la sorprese a manovrare una delle cineprese Panavision, un gesto che il regista considerò un''interferenza imperdonabile nel lavoro tecnico.', 'Intervista a Katharine Ross nel documentario ''The Making of Butch Cassidy and the Sundance Kid''', TRUE, 'IA (Daily Sync)', 'IA Verificata', 0, 3, '2026-11-02T10:28:36.347973+00:00'),
('7a0d5da2-0cb9-429b-9d96-664cab864820', 284, 'Aneddoti dal set', 'Il trucco per far caricare il toro', 'Nella scena in cui Butch e Etta vengono inseguiti da un toro mentre sono in bicicletta, l''animale si rifiutava di correre. Per ottenere la carica desiderata, i tecnici dovettero spruzzare una sostanza irritante sui testicoli del toro, un metodo rudimentale che Paul Newman ricordò divertito in seguito.', 'Commento audio del DVD di George Roy Hill', TRUE, 'IA (Daily Sync)', 'IA Verificata', 0, 4, '2026-11-02T10:28:36.347973+00:00'),
('f9b4c912-3726-48a7-8f65-901ffe460d10', 284, 'Curiosità & Retroscena', 'La visita della vera sorella di Butch Cassidy', 'Lula Parker Betenson, la vera sorella di Butch Cassidy, visitò il set durante la produzione all''età di 84 anni. Durante le conversazioni con il cast, sostenne fermamente che suo fratello non era morto in Bolivia nel 1908, ma era tornato segretamente negli Stati Uniti vivendo sotto falso nome per anni.', 'Libro ''Butch Cassidy, My Brother'' di Lula Parker Betenson', TRUE, 'IA (Daily Sync)', 'IA Verificata', 0, 5, '2026-11-02T10:28:36.347973+00:00'),
('17d92711-cdc0-40eb-ba40-3f8ae730a27c', 284, 'Segreti di produzione', 'Il significato tecnico del viraggio seppia', 'La decisione di girare l''intero primo atto con un viraggio seppia non fu solo estetica, ma servì a mascherare le differenze di luce tra le varie location. Il direttore della fotografia Conrad Hall utilizzò questa tecnica per dare al film un aspetto da ''vecchio album fotografico'' prima del passaggio esplosivo al colore.', 'Intervista a Conrad Hall, American Cinematographer', TRUE, 'IA (Daily Sync)', 'IA Verificata', 0, 6, '2026-11-02T10:28:36.347973+00:00'),
('069f4b9f-3a6a-4921-93d7-d618d8eb252c', 284, 'Casting & Scelte', 'Il rifiuto di Dustin Hoffman', 'Prima che Paul Newman venisse confermato per il ruolo di Butch, la parte fu offerta a Dustin Hoffman. L''attore rifiutò per girare ''John e Mary'', poiché non si sentiva adatto a un ruolo fisicamente imponente, permettendo così la nascita della coppia Newman-Redford.', 'Archivi di casting della 20th Century Fox', TRUE, 'IA (Daily Sync)', 'IA Verificata', 0, 7, '2026-11-02T10:28:36.347973+00:00'),
('0ef01b76-be3f-4422-bda4-2d643e498c7b', 284, 'Curiosità & Retroscena', 'L''ostilità iniziale verso ''Raindrops Keep Fallin'' on My Head''', 'Dopo la prima proiezione di prova, i dirigenti della Fox detestarono la canzone di Burt Bacharach, ritenendola inadatta a un western. Robert Redford stesso inizialmente pensò che la sequenza della bicicletta con quella musica fosse ''un errore terribile'' che avrebbe rovinato il tono del film.', 'Autobiografia di Burt Bacharach ''Anyone Who Had a Heart''', TRUE, 'IA (Daily Sync)', 'IA Verificata', 0, 8, '2026-11-02T10:28:36.347973+00:00'),
('0e3be010-67fc-4692-8cc9-3646de595579', 284, 'Casting & Scelte', 'L''identità della ''Super-posse''', 'Il misterioso gruppo di inseguitori noto come ''Super-posse'' non era composto da attori, ma interamente da stuntmen professionisti. George Roy Hill scelse questa soluzione affinché potessero cavalcare a velocità folli su terreni impervi senza mai mostrare i volti, aumentando l''aura di minaccia inarrestabile.', 'Note di produzione ufficiali del 1969', TRUE, 'IA (Daily Sync)', 'IA Verificata', 0, 9, '2026-11-02T10:28:36.347973+00:00'),
('0267656c-dbc7-4d56-be79-3764e89d5d41', 151, 'Casting & Scelte', 'La trasformazione fisica di Austin Butler', 'Per interpretare il sadico Feyd-Rautha Harkonnen, Austin Butler si è sottoposto a un rigido allenamento di quattro mesi e ha adottato una voce ispirata a quella di Marlon Brando in Apocalypse Now unita a quella di animali feroci, rifiutandosi di rompere il personaggio anche fuori dalle riprese.', 'Note di produzione ufficiali Warner Bros. e interviste Vanity Fair', TRUE, 'IA (Daily Sync)', 'IA Verificata', 0, 0, '2026-11-02T14:46:02.318323+00:00'),
('416e01d8-ac05-4329-aa8f-c58aec3f6cbc', 151, 'Segreti di produzione', 'L''uso esclusivo di telecamere IMAX', 'Denis Villeneuve e il direttore della fotografia Greig Fraser hanno girato l''intero film utilizzando esclusivamente cineprese digitali certificate IMAX (Arri Alexa 65 con ottiche speciali), rifiutando l''uso di conversioni digitali in post-produzione per massimizzare l''immersività visiva.', 'American Cinematographer e dichiarazioni ufficiali di Greig Fraser', TRUE, 'IA (Daily Sync)', 'IA Verificata', 0, 1, '2026-11-02T14:46:02.318323+00:00'),
('8a9422b5-fcff-4687-9b32-223cb21fd0d3', 151, 'Aneddoti dal set', 'La sfida delle riprese nel deserto di Wadi Rum', 'La troupe ha girato per settimane nel deserto di Wadi Rum in Giordania con temperature che superavano i 40 gradi Celsius, costringendo il reparto tecnico a utilizzare tende di raffreddamento speciali e a proteggere costantemente le attrezzature dalla sabbia fine che rischiava di bloccare i meccanismi delle camere IMAX.', 'Making-of ufficiale ''Building the Planet'' e reportage di Empire Magazine', TRUE, 'IA (Daily Sync)', 'IA Verificata', 0, 2, '2026-11-02T14:46:02.318323+00:00'),
('cb0e3bfe-807a-45f6-99d1-9cd3b43a0e25', 151, 'Effetti speciali & Trucco', 'L''assenza di green screen tradizionali', 'Per ottenere un''illuminazione il più possibile realistica e naturale, Villeneuve ha quasi totalmente evitato i classici green screen, preferendo l''uso di enormi schermi a LED sui quali venivano proiettati i cieli e i panorami desertici durante le riprese in studio a Budapest.', 'Intervista tecnica a Paul Lambert, supervisore degli effetti visivi', TRUE, 'IA (Daily Sync)', 'IA Verificata', 0, 3, '2026-11-02T14:46:02.318323+00:00'),
('b4b06c7c-4ff2-4d9a-aa50-5de127b72cb8', 151, 'Citazioni & Easter Egg', 'Il cameo vocale di Stephen McKinley Henderson', 'Sebbene il suo personaggio Thufir Hawat non compaia fisicamente nella sceneggiatura di questa seconda parte a causa di tagli narrativi necessari per snellire la trama, l''attore appare in un piccolo omaggio visivo e la sua presenza narrativa è stata fortemente rimpianta dal regista.', 'Interviste ufficiali di Denis Villeneuve per Entertainment Weekly', TRUE, 'IA (Daily Sync)', 'IA Verificata', 0, 4, '2026-11-02T14:46:02.318323+00:00'),
('0c774635-205f-4a80-ab00-b0f35622399b', 285, 'Segreti di produzione', 'Le mani di John Scarne', 'Sebbene Paul Newman si fosse esercitato per settimane nel manipolare le carte, le mani che si vedono compiere i complessi trucchi e i mescolamenti acrobatici durante la partita a poker non sono le sue. Appartengono a John Scarne, uno dei più famosi esperti di gioco d''azzardo e prestigiatori del mondo, che fu assunto come consulente tecnico e controfigura per le mani.', 'Commento audio dell''edizione speciale DVD/Blu-ray', TRUE, 'IA (Daily Sync)', 'IA Verificata', 0, 0, '2026-11-02T10:29:44.584924+00:00'),
('db54b8dc-1f57-4267-99eb-2554866e251b', 285, 'Curiosità & Retroscena', 'L''ispirazione letteraria di David Maurer', 'La sceneggiatura di David S. Ward è basata sul saggio del 1940 ''The Big Con: The Story of the Confidence Man'' del linguista David Maurer. Il libro descriveva con precisione accademica il gergo e le tecniche dei truffatori degli anni ''30, inclusa la tecnica della ''finta agenzia'' (The Wire) utilizzata nel film.', 'Note di produzione Universal Pictures', TRUE, 'IA (Daily Sync)', 'IA Verificata', 0, 1, '2026-11-02T10:29:44.584924+00:00'),
('0663904b-aed2-4d66-8afa-bc471032a656', 285, 'Curiosità & Retroscena', 'L''ultimo Oscar di Edith Head', 'La leggendaria costumista Edith Head vinse il suo ottavo e ultimo Premio Oscar per questo film. Per valorizzare il fisico di Newman e Redford senza tradire l''epoca, scelse tessuti e tagli che richiamavano lo stile del 1936, ma con una vestibilità leggermente più moderna per renderli icone di stile senza tempo.', 'Archivi dell''Academy of Motion Picture Arts and Sciences', TRUE, 'IA (Daily Sync)', 'IA Verificata', 0, 2, '2026-11-02T10:29:44.584924+00:00'),
('2b5cbcbc-fb53-4b7c-b922-af8fab568841', 285, 'Casting & Scelte', 'La riscrittura del personaggio di Gondorff', 'Nella sceneggiatura originale, Henry Gondorff era descritto come un uomo anziano, trasandato e in forte sovrappeso. Quando Paul Newman espresse il desiderio di interpretarlo, il regista George Roy Hill accettò di riscrivere il personaggio per adattarlo al carisma e alla fisicità dell''attore, mantenendo però l''introduzione in cui viene trovato ubriaco.', 'Intervista a David S. Ward nel documentario ''The Art of The Sting''', TRUE, 'IA (Daily Sync)', 'IA Verificata', 0, 3, '2026-11-02T10:29:44.584924+00:00'),
('c860540b-e288-4aef-946e-566cbc21d722', 285, 'Aneddoti dal set', 'Il segreto del tocco sul naso', 'Il gesto di toccarsi il lato del naso per indicare che tutto sta procedendo secondo i piani non era un''invenzione cinematografica. Si trattava di un vero segnale in codice utilizzato dai truffatori di strada dell''epoca, scoperto dallo sceneggiatore durante le sue ricerche storiche sulla malavita di Chicago.', 'Making-of ufficiale ''The Sting: Special Edition''', TRUE, 'IA (Daily Sync)', 'IA Verificata', 0, 4, '2026-11-02T10:29:44.584924+00:00'),
('6fcbc07e-72d7-4371-9d6c-028b6f8019bd', 285, 'Curiosità & Retroscena', 'Il set condiviso con Ritorno al Futuro', 'Il ristorante ''Carousel'', dove Hooker incontra Gondorff per la prima volta, è un set situato nella Courthouse Square degli Universal Studios. Lo stesso identico edificio, con poche modifiche scenografiche, è stato utilizzato dodici anni dopo per diventare il ''Lou''s Cafe'' del 1955 nel film ''Ritorno al futuro''.', 'Universal Studios Hollywood Backlot Tour Records', TRUE, 'IA (Daily Sync)', 'IA Verificata', 0, 5, '2026-11-02T10:29:44.584924+00:00'),
('53350645-c183-49fa-be35-5ad94ce5baff', 285, 'Casting & Scelte', 'L''esitazione iniziale di Robert Redford', 'Robert Redford inizialmente rifiutò il ruolo di Johnny Hooker perché non voleva interpretare un altro personaggio che fosse solo la ''spalla'' di Newman. Cambiò idea solo dopo che George Roy Hill gli promise che il film sarebbe stato un pezzo d''insieme ritmato e che il suo personaggio avrebbe avuto un arco narrativo di crescita autonomo.', 'Biografia ufficiale ''Robert Redford: The Biography'' di Michael Feeney Callan', TRUE, 'IA (Daily Sync)', 'IA Verificata', 0, 6, '2026-11-02T10:29:44.584924+00:00'),
('6d5cc989-9696-4666-a2cd-b7e2e1206f90', 285, 'Curiosità & Retroscena', 'Il significato tecnico del titolo', 'Il termine ''The Sting'' (la stangata) ha un significato tecnico preciso nel gergo dei truffatori descritto nel film: non indica l''intera operazione, ma esclusivamente il momento finale in cui il truffatore convince la vittima a consegnare il denaro, prima che quest''ultima si renda conto di essere stata raggirata.', 'Glossario tecnico allegato alla sceneggiatura originale', TRUE, 'IA (Daily Sync)', 'IA Verificata', 0, 7, '2026-11-02T10:29:44.584924+00:00'),
('d008dbbd-bd43-430c-82d5-071c11bf78b3', 285, 'Segreti di produzione', 'La vendita record della sceneggiatura', 'David S. Ward vendette la sceneggiatura alla Universal per 250.000 dollari, una cifra astronomica per l''epoca, specialmente per uno sceneggiatore quasi esordiente. Il successo fu tale che lo studio diede il via libera immediato alla produzione non appena Newman e Redford confermarono la loro partecipazione.', 'Variety Archive, reportage sulle vendite di spec scripts (1972)', TRUE, 'IA (Daily Sync)', 'IA Verificata', 0, 8, '2026-11-02T10:29:44.584924+00:00'),
('1ddfd95d-9bb5-4243-a3bf-aa5176bf1364', 285, 'Effetti speciali & Trucco', 'L''uso dei filtri per l''effetto d''epoca', 'Per ottenere il look visivo che ricordasse le illustrazioni delle riviste degli anni ''30, il direttore della fotografia Robert Surtees utilizzò speciali filtri a bassa saturazione e una tecnica di illuminazione piatta. Questo serviva a minimizzare i contrasti moderni e a dare alla pellicola una tonalità seppia e pastello costante.', 'American Cinematographer Magazine, numero speciale 1974', TRUE, 'IA (Daily Sync)', 'IA Verificata', 0, 9, '2026-11-02T10:29:44.584924+00:00'),
('97a1f7b3-af7b-4a14-a2eb-ae8078c730f7', 151, 'Segreti di produzione', 'La progettazione della voce dei Bene Gesserit', 'Il celebre ''Modulo Vocale'' o ''Voce'' utilizzato dalle Bene Gesserit per controllare le persone è stato realizzato sovrapponendo in fase di missaggio audio le voci originali delle attrici con frequenze subsoniche impercettibili, progettate per generare una sottile inquietudine nello spettatore in sala.', 'Documentario audio sul sound design con Mark Mangini e Theo Green', TRUE, 'IA (Daily Sync)', 'IA Verificata', 0, 5, '2026-11-02T14:46:02.318323+00:00'),
('8969586c-4735-4c5e-ad64-cd7a63f0bee7', 341, 'Casting & Scelte', 'La scelta iniziale per Danny Witwer', 'Prima che il ruolo di Danny Witwer fosse affidato a Colin Farrell, Steven Spielberg aveva inizialmente pensato a Javier Bardem per la parte dell''agente del Dipartimento di Giustizia. Bardem rifiutò l''offerta, aprendo la strada all''ingaggio di Farrell dopo che il regista lo aveva visto in ''Thirteen Days''.', 'Note di produzione ufficiali e interviste al casting', TRUE, 'IA (Daily Sync)', 'IA Verificata', 0, 0, '2026-11-02T14:51:22.492045+00:00'),
('169fe9a5-02ee-40a3-8978-bab1242a16c2', 341, 'Casting & Scelte', 'Il rifiuto di Cate Blanchett e il ruolo di Agatha', 'Prima che Samantha Morton ottenesse l''acclamato ruolo della pre-cog Agatha, il personaggio fu offerto a Cate Blanchett, la quale dovette declinare l''offerta a causa di conflitti di programmazione con altri impegni cinematografici.', 'Archivio storico di casting di Hollywood', TRUE, 'IA (Daily Sync)', 'IA Verificata', 0, 1, '2026-11-02T14:51:22.492045+00:00'),
('5f84e979-a3cb-404e-9116-7a4931b50093', 341, 'Citazioni & Easter Egg', 'Il cameo di Jan de Bont e le riprese nel centro commerciale', 'Durante la sequenza in cui Anderton fugge all''interno del centro commerciale indossando un cappuccio e cercando di passare inosservato, si può notare il celebre regista e direttore della fotografia Jan de Bont tra le comparse che affollano la scena.', 'Commento audio del regista Steven Spielberg nel DVD speciale', TRUE, 'IA (Daily Sync)', 'IA Verificata', 0, 2, '2026-11-02T14:51:22.492045+00:00'),
('13edf0e4-6fe9-4373-821a-0e422b3cf068', 341, 'Segreti di produzione', 'L''ispirazione per il design dei veicoli gestiti da energia magnetica', 'Le automobili futuristiche guidate da levitazione magnetica e capaci di arrampicarsi sui palazzi furono progettate in collaborazione con i designer della Lexus. La casa automobilistica creò un prototipo a grandezza naturale specifico per il film intitolato ''Lexus 2054''.', 'Documentario ''The Making of Minority Report''', TRUE, 'IA (Daily Sync)', 'IA Verificata', 0, 3, '2026-11-02T14:51:22.492045+00:00'),
('96c783de-fb17-44c1-bada-eaf206118ecd', 286, 'Segreti di produzione', 'L''acquisto anonimo dei diritti del libro di Robert Bloch', 'Alfred Hitchcock acquistò i diritti del romanzo omonimo di Robert Bloch in forma strettamente anonima tramite il suo agente per soli 9.500 dollari. Subito dopo l''acquisizione, il regista ordinò alla sua segretaria Peggy Robertson di comprare quante più copie possibili del libro nelle librerie americane per impedire al pubblico di scoprire in anticipo il finale a sorpresa.', 'Documentario ''The Making of Psycho'' (Laurent Bouzereau, 1997)', TRUE, 'IA (Daily Sync)', 'IA Verificata', 0, 0, '2026-11-02T10:35:28.554842+00:00'),
('f188841a-508c-4572-af94-c0758bc8e54c', 286, 'Segreti di produzione', 'L''impiego della troupe televisiva di ''Alfred Hitchcock presenta''', 'Per ridurre drasticamente i costi e accelerare i ritmi di lavorazione, Hitchcock non ingaggiò una classica troupe cinematografica di Hollywood, ma si affidò ai tecnici della sua serie televisiva ''Alfred Hitchcock presenta''. Sotto la direzione della fotografia di John L. Russell, le riprese principali furono completate in tempi record tra novembre 1959 e febbraio 1960 presso i teatri di posa della Universal-International.', 'Note di produzione e libro ''Alfred Hitchcock and the Making of Psycho'' di Stephen Rebello', TRUE, 'IA (Daily Sync)', 'IA Verificata', 0, 1, '2026-11-02T10:35:28.554842+00:00'),
('cb867db8-6f5c-42e0-931a-9940b21a7043', 286, 'Aneddoti dal set', 'Il suono delle coltellate ottenuto affettando meloni casaba', 'Per riprodurre il rumore realistico della lama che penetra nella carne durante la scena della doccia, il rumorista cercò a lungo l''oggetto ideale testando diversi tipi di frutta e ortaggi. Hitchcock si sedette in sala di registrazione a occhi chiusi mentre il tecnico pugnalava angurie, meloni, pomodori e carni macellate, scegliendo infine all''unanimità il suono prodotto da un melone casaba.', 'Intervista al sound designer Jack Barron e documentario ''The Making of Psycho''', TRUE, 'IA (Daily Sync)', 'IA Verificata', 0, 2, '2026-11-02T10:35:28.554842+00:00'),
('c9ef3902-f18a-4048-8906-95cd61db858f', 286, 'Curiosità & Retroscena', 'Il simbolismo cromatico dell''intimo di Marion Crane', 'Nel prologo del film a Phoenix, prima di rubare la busta con i 40.000 dollari, Marion Crane indossa un reggiseno e una sottoveste bianchi che ne sottolineano l''innocenza morale. Nella sequenza successiva in camera da letto, subito dopo aver consumato il furto e prima di fuggire, la protagonista indossa biancheria intima interamente nera, simboleggiando visivamente la sua caduta nel crimine e nella colpa.', 'Commento audio di Stephen Rebello e Janet Leigh nell''edizione Home Video', TRUE, 'IA (Daily Sync)', 'IA Verificata', 0, 3, '2026-11-02T10:35:28.554842+00:00'),
('1d0bb8b8-aa6a-41b1-89ec-39bf0a107f55', 286, 'Casting & Scelte', 'La voce multipla della signora Bates', 'Per dare voce alla madre di Norman senza tradire il segreto dell''identità del killer, Hitchcock non utilizzò Anthony Perkins per i dialoghi urlati nella casa. Ingaggiò tre attori differenti: Virginia Gregg, Jeanette Nolan e Paul Jasmin, registrando le loro battute e mixandole sapientemente tra loro per rendere il timbro vocale instabile, inquietante e non riconducibile a un singolo interprete.', 'Archivi sonori Revue Studios / Shamley Productions', TRUE, 'IA (Daily Sync)', 'IA Verificata', 0, 4, '2026-11-02T10:35:28.554842+00:00'),
('52b287aa-a6f3-4460-8528-6cb921a040d1', 286, 'Segreti di produzione', 'Il montaggio millimetrico di George Tomasini e i layout di Saul Bass', 'La sequenza della doccia dura appena 45 secondi sullo schermo ma è composta da ben 78 diverse inquadrature e 52 stacchi di montaggio. L''incredibile ritmo visivo fu progettato graficamente dal celebre visual designer Saul Bass nei suoi storyboard e montato fotogramma per fotogramma dal montatore di fiducia di Hitchcock, George Tomasini, senza mostrare mai esplicitamente la lama che perfora la pelle.', 'Intervista a Saul Bass e documentario ''The Making of Psycho''', TRUE, 'IA (Daily Sync)', 'IA Verificata', 0, 5, '2026-11-02T10:35:28.554842+00:00'),
('f8d143fa-0b1d-432d-9e46-b83acf32d2fa', 286, 'Casting & Scelte', 'La controfigura di Janet Leigh: la coniglietta Marli Renfro', 'Sebbene Janet Leigh abbia girato personalmente quasi tutti i primi piani sotto il getto d''acqua, per le inquadrature più ampie e i dettagli del corpo fu assunta come ''stand-in'' e controfigura la modella di Playboy Marli Renfro. La Renfro fu pagata 500 dollari per trascorrere diversi giorni sul set, prestando il proprio corpo nudo anche per la scena in cui Marion viene avvolta nella tenda di plastica e trascinata sul pavimento.', 'Intervista a Marli Renfro e biografia ''Psycho: Behind the Scenes of the Classic Thriller''', TRUE, 'IA (Daily Sync)', 'IA Verificata', 0, 6, '2026-11-02T10:35:28.554842+00:00'),
('3a2fe939-e0b6-4821-b56e-911cb277b786', 286, 'Curiosità & Retroscena', 'L''ispirazione pittorica per la Bates House da Edward Hopper', 'La cupa villa vittoriana a due piani che sovrasta il Bates Motel venne concepita dagli art director Joseph Hurley e Robert Clatworthy ispirandosi a un celebre dipinto: ''House by the Railroad'' (1925) di Edward Hopper. L''architettura in stile Secondo Impero americano con il tetto a mansarda fu riprodotta minuziosamente sul lotto della Universal per creare un contrasto visivo angosciante con le linee piatte e moderne del motel sottostante.', 'Saggio ''Hitchcock and Art: Fatal Coincidences'', Centre Pompidou', TRUE, 'IA (Daily Sync)', 'IA Verificata', 0, 7, '2026-11-02T10:35:28.554842+00:00'),
('e2494d20-1a26-481c-ad8e-579f09569295', 286, 'Segreti di produzione', 'L''uso rigoroso dell''obiettivo da 50 mm', 'Per accentuare il senso di realismo e immedesimazione voyeuristica da parte dello spettatore, Hitchcock diede istruzioni al direttore della fotografia John L. Russell di girare quasi l''intero lungometraggio utilizzando una lente standard da 50 mm su pellicola 35 mm. Questa lunghezza focale riproduce la prospettiva visiva e le proporzioni più vicine all''occhio umano, evitando distorsioni grandangolari artificiose.', 'Interviste di François Truffaut nel libro ''Il cinema secondo Hitchcock''', TRUE, 'IA (Daily Sync)', 'IA Verificata', 0, 8, '2026-11-02T10:35:28.554842+00:00'),
('ed0fca4c-a473-4f89-bc03-e3fae8933f63', 286, 'Citazioni & Easter Egg', 'Il cameo di Hitchcock con il cappello da cowboy', 'Fedele alla sua tradizione di apparire nei propri film, Alfred Hitchcock compie il suo celebre cameo al sesto minuto della pellicola. Il regista appare all''esterno dell''ufficio immobiliare in cui lavora Marion Crane a Phoenix, vestito con un completo scuro e un vistoso cappello texano Stetson mentre sosta sul marciapiede proprio mentre la protagonista rientra dalla pausa pranzo.', 'Analisi ufficiale dei cameo registrata nell''archivio dell''American Film Institute (AFI)', TRUE, 'IA (Daily Sync)', 'IA Verificata', 0, 9, '2026-11-02T10:35:28.554842+00:00'),
('28464f59-bd4e-4b7c-bb7f-efef11ea20f0', 288, 'Curiosità & Retroscena', 'L''origine della storia basata su un fatto di cronaca reale', 'Il soggetto del film è tratto da un racconto breve omonimo di Daphne du Maurier, ma Alfred Hitchcock decise di adattarlo dopo aver letto un articolo di giornale del 18 agosto 1961 pubblicato sul ''Santa Cruz Sentinel''. La notizia riportava un misterioso attacco di massa di berte americane avvenuto nella cittadina costiera di Capitola, in California, che si schiantavano contro i tetti e le finestre delle case.', 'Archivi della produzione e biografie storiche di Alfred Hitchcock', TRUE, 'IA (Daily Sync)', 'IA Verificata', 0, 0, '2026-11-02T10:35:44.754203+00:00'),
('cbb0f70a-e853-4002-a10a-d491048c0bbb', 288, 'Segreti di produzione', 'Il budget record per la post-produzione e gli effetti sonori', 'Gran parte dell''ingente budget del film fu investito nel reparto sonoro e nella creazione degli effetti speciali visivi, superando persino i costi dedicati agli attori principali. Per generare i diversi versi e stridii degli uccelli, Hitchcock si affidò al pioniere del suono Oskar Sala, il quale utilizzò uno strumento elettronico sperimentale chiamato Trautonium per modulare frequenze sintetiche e rumori naturali.', 'Note di produzione Universal Pictures e documentari d''archivio', TRUE, 'IA (Daily Sync)', 'IA Verificata', 0, 1, '2026-11-02T10:35:44.754203+00:00'),
('9a1031f9-8a7d-4c2f-aa8c-00bcfc0f21f9', 287, 'Segreti di produzione', 'La censura sui dettagli del delitto', 'I dirigenti della censura del Production Code Office intimarono a Alfred Hitchcock di modificare la fase di preparazione dell''omicidio, ritenendo che il piano ideato da Tony Wendice fosse spiegato in modo fin troppo meticoloso e potesse fungere da ''manuale'' per aspiranti criminali.', 'Note di produzione e archivi della censura MPAA', TRUE, 'IA (Daily Sync)', 'IA Verificata', 0, 0, '2026-11-02T10:35:36.07743+00:00'),
('80053497-60b0-4ae9-af90-d6d44b259285', 287, 'Citazioni & Easter Egg', 'Il cameo personale del regista', 'Come da sua celebre consuetudine, Alfred Hitchcock appare brevemente nel film: lo si può notare intorno al tredicesimo minuto della pellicola mentre compare nella fotografia della classe di college riunita in un''immagine di repertorio mostrata da Ray Milland.', 'Documentario retrospettivo sul cinema di Hitchcock', TRUE, 'IA (Daily Sync)', 'IA Verificata', 0, 1, '2026-11-02T10:35:36.07743+00:00'),
('7f0a010b-6862-4c25-ba2a-586cba91bc92', 287, 'Effetti speciali & Trucco', 'L''inventiva per la giacca degli scacchi', 'Per rendere visivamente evidente il tempo trascorso durante la partita a scacchi tra Tony e il suo ospite prima del delitto, i costumisti modificarono leggermente i dettagli dell''illuminazione e delle inquadrature per mascherare i cambi di pellicola necessari.', 'Commento audio storico dell''edizione DVD', TRUE, 'IA (Daily Sync)', 'IA Verificata', 0, 2, '2026-11-02T10:35:36.07743+00:00'),
('8f350826-6dcd-4410-8020-1fca5508f31d', 287, 'Casting & Scelte', 'Il compenso ridotto di Grace Kelly', 'Grace Kelly girò ''Il delitto perfetto'' percependo uno stipendio relativamente modesto di circa 750 dollari a settimana, un compenso standard prima che il successivo successo planetario di ''La finestra sul cortile'' e ''Caccia al ladro'' ne ridiscutesse completamente il caché contrattuale.', 'Biografie ufficiali e contratti di produzione Warner Bros.', TRUE, 'IA (Daily Sync)', 'IA Verificata', 0, 3, '2026-11-02T10:35:36.07743+00:00'),
('d0277faa-e294-48e1-8d33-55bdabdd620a', 187, 'Aneddoti dal set', 'L''immersione totale di Han Hyo-joo nel personaggio non vedente', 'Per prepararsi al ruolo di Jung-hwa, l''attrice Han Hyo-joo ha trascorso molto tempo in una scuola per non vedenti, imparando a usare il bastone bianco e studiando il linguaggio del corpo e i movimenti oculari caratteristici di chi non ha la vista.', 'Intervista esclusiva su Elle Korea', TRUE, 'IA (Daily Sync)', 'IA Verificata', 0, 2, '2026-11-02T14:46:14.255744+00:00'),
('ff0103b8-294f-449c-9b82-59aab36155af', 187, 'Curiosità & Retroscena', 'Il remake turco autorizzato', 'Il successo emotivo della pellicola ha spinto alla produzione di un remake turco ufficiale uscito nel 2020 intitolato ''Sadece Sen'', dimostrando l''appeal internazionale della sceneggiatura originale di Song Il-gon.', 'Comunicato stampa della distribuzione internazionale', TRUE, 'IA (Daily Sync)', 'IA Verificata', 0, 3, '2026-11-02T14:46:14.255744+00:00'),
('4992e179-b0a4-46d9-add2-b8acbc4c191a', 294, 'Segreti di produzione', 'La costruzione totale della villa dei Park', 'La splendida villa della famiglia Park non esiste nella realtà: è stata interamente costruita da zero all''interno di un parcheggio all''aperto degli studi cinematografici di Jeonju, sfruttando la luce solare naturale calcolata con precisione millimetrica dal direttore della fotografia Hong Kyung-pyo per orientare le ombre.', 'Commento audio del regista Bong Joon-ho e note di produzione', TRUE, 'IA (Daily Sync)', 'IA Verificata', 0, 0, '2026-11-02T14:47:55.172169+00:00'),
('1560c7a6-24f9-46e4-b7ff-f727eec3ffcb', 294, 'Casting & Scelte', 'Il casting su misura per Choi Woo-shik', 'Il regista Bong Joon-ho ha scritto il ruolo di Ki-woo specificamente per l''attore Choi Woo-shik dopo aver lavorato con lui in ''Okja'' nel 2017, offrendogli la parte direttamente senza nemmeno fargli sostenere un provino.', 'Intervista ufficiale a Bong Joon-ho per The Hollywood Reporter', TRUE, 'IA (Daily Sync)', 'IA Verificata', 0, 1, '2026-11-02T14:47:55.172169+00:00'),
('f59449a6-8cb1-4466-bd62-6ca1a5b2dcf5', 294, 'Aneddoti dal set', 'La pesca della pesca come arma da contatto', 'L''attrice Lee Jung-eun, che interpreta la governatrice Moon-gwang, era terrorizzata dalle pesche nella realtà a causa di una forte allergia e di un''avversione personale; la troupe ha dovuto usare una pesca finta e una grande dose di recitazione per girare la celebre scena della reazione allergica.', 'Making-of ufficiale e interviste al cast', TRUE, 'IA (Daily Sync)', 'IA Verificata', 0, 2, '2026-11-02T14:47:55.172169+00:00'),
('7e5bda0a-4192-42ed-a8a8-5f82601456e2', 294, 'Segreti di produzione', 'Il dipinto regalato da un artista reale', 'Il quadro astratto realizzato dal piccolo Da-song e appeso nel soggiorno della villa è opera della celebre pittrice sudcoreana Seung-hyun Kim (nota come Zเก้), che lo ha dipinto appositamente per il film su richiesta della produzione.', 'Note di produzione e art department featurette', TRUE, 'IA (Daily Sync)', 'IA Verificata', 0, 3, '2026-11-02T14:47:55.172169+00:00'),
('4ae0bf50-7adc-4608-8d99-44d46df8eb02', 294, 'Segreti di produzione', 'La scala reale e la prospettiva forzata', 'La memorabile scalinata che collega il quartiere ricco dei Park al quartiere povero dei Kim non è un unico luogo continuo, ma è il risultato dell''unione in montaggio di set in studio, modellini in scala e riprese in diverse zone di Seul collegate con grande maestria.', 'Featurette sugli effetti visivi di VFX Supervisor Yang Jin-mo', TRUE, 'IA (Daily Sync)', 'IA Verificata', 0, 4, '2026-11-02T14:47:55.172169+00:00'),
('5a2b2a46-da7a-4c72-ac89-c8ec6e4e6270', 294, 'Citazioni & Easter Egg', 'L''omaggio a Kim Ki-young', 'Il personaggio di Ki-taek prende il nome dall''attore Kim Ki-taek ma è soprattutto un omaggio al leggendario regista sudcoreano Kim Ki-young, celebre per i suoi thriller domestici claustrofobici come ''The Housemaid'' del 1960.', 'Note di regia ufficiali del Festival di Cannes', TRUE, 'IA (Daily Sync)', 'IA Verificata', 0, 5, '2026-11-02T14:47:55.172169+00:00'),
('ef1e7dfd-132a-4285-b4f2-60997e4b5b53', 294, 'Aneddoti dal set', 'La finta pietra da giardino pesante', 'La famosa pietra miliare portafortuna regalata a Ki-woo era in realtà un oggetto di scena leggerissimo realizzato in gommapiuma e resina dipinta, che l''attore Choi Woo-shik ha comunque dovuto sollevare con attenzione per fingere la reale pesantezza.', 'Intervista al reparto scenografia e props master', TRUE, 'IA (Daily Sync)', 'IA Verificata', 0, 6, '2026-11-02T14:47:55.172169+00:00'),
('3ae3988a-c584-42b3-904e-a313ef1e7e3f', 294, 'Aneddoti dal set', 'Il brano rap improvvisato per l''intervista', 'La filastrocca con cui l''attrice Park So-dam (Ki-jung) memorizza il falso curriculum prima di entrare nella casa dei Park è stata ideata e ritmata dall''attrice stessa, che ha creato una melodia orecchiabile poi diventata virale online.', 'Dietro le quinte ufficiale di CJ Entertainment', TRUE, 'IA (Daily Sync)', 'IA Verificata', 0, 7, '2026-11-02T14:47:55.172169+00:00'),
('502e1d52-7645-4b51-812b-171741a622c8', 341, 'Curiosità & Retroscena', 'La colonna sonora originale rifiutata di James Horner', 'Inizialmente, Steven Spielberg aveva ingaggiato il compositore James Horner per scrivere la colonna sonora del film. Tuttavia, a causa di divergenze creative e tempi di lavorazione troppo stretti, Horner lasciò il progetto e fu sostituito da John Williams all''ultimo momento.', 'Archivio storico delle colonne sonore di Hollywood', TRUE, 'IA (Daily Sync)', 'IA Verificata', 0, 4, '2026-11-02T14:51:22.492045+00:00'),
('6a6dfa22-fbf1-4b00-8712-e4bff131cfeb', 341, 'Aneddoti dal set', 'L''infortunio di Tom Cruise sul set', 'Durante le riprese della complessa sequenza d''azione all''interno della fabbrica di automobili, Tom Cruise subì un infortunio minore a un ginocchio a causa dei movimenti rapidi richiesti dalle coreografie di lotta tra i robot in assemblaggio.', 'Report medico di produzione e interviste sul set', TRUE, 'IA (Daily Sync)', 'IA Verificata', 0, 5, '2026-11-02T14:51:22.492045+00:00'),
('9c79a10d-954d-43b2-945f-2fab8aeef07b', 108, 'Casting & Scelte', 'L''ingresso dei giovani coprotagonisti', 'Nel marzo 2024 il cast principale è stato completato con l''ingaggio di Christian Convery, reduce dal successo della serie Sweet Tooth, e dell''attrice Maisy Stella. I due giovani interpreti sono stati selezionati tramite audizioni riservate per formare il nucleo familiare al centro dei misteriosi eventi della trama.', 'Deadline Hollywood', TRUE, 'IA (Admin)', 'IA Verificata', 3, 4, '2026-11-02T18:13:56.94748+00:00'),
('a8f69fe2-4019-425c-850c-78d5ca9f862e', 288, 'Casting & Scelte', 'Il rifiuto del nome di battesimo nei crediti di esordio', 'Prima di ottenere il ruolo da protagonista, Tippi Hedren era una modella affermata e apparve sulla copertina della rivista ''Vogue''. Per la sua prima interpretazione cinematografica importante, Alfred Hitchcock volle che il suo nome apparisse nei titoli di testa preceduto dall''insolita dicitura ''Introducing Tippi Hedren'', sottolineando il totale controllo del regista sulla costruzione della nuova diva.', 'Crediti ufficiali del film e biografia di Tippi Hedren ''Tippi: A Memoir''', TRUE, 'IA (Daily Sync)', 'IA Verificata', 0, 2, '2026-11-02T10:35:44.754203+00:00'),
('e21a75b8-3473-4877-9574-440f0c95c88e', 288, 'Aneddoti dal set', 'I veri gabbiani legati con del filo di nylon', 'Durante le riprese della celebre sequenza in cui la popolazione di Bodega Bay viene assalita all''aperto, la troupe utilizzò centinaia di gabbiani vivi catturati con reti lungo la costa. Per evitare che i volatili volassero via, molti di essi vennero legati agli attori e alle strutture della piazza tramite sottili fili di nylon quasi invisibili alla macchina da presa.', 'Interviste al cast e documentario ''The Birds: Hitchcock''s Monster Movie''', TRUE, 'IA (Daily Sync)', 'IA Verificata', 0, 3, '2026-11-02T10:35:44.754203+00:00'),
('0ad8197a-0ac5-46fe-8335-8451d6fb5828', 288, 'Segreti di produzione', 'L''assenza di nomination agli Oscar nonostante l''innovazione tecnica', 'Nonostante l''enorme impatto visivo e l''uso pionieristico della composizione elettronica del suono e dei processi ottici di stampa della pellicola, ''Gli uccelli'' ricevette una sola nomination ai premi Oscar, precisamente nella categoria dei migliori effetti speciali, vinti poi dal kolossal ''Cleopatra''.', 'Database ufficiale dell''Academy of Motion Picture Arts and Sciences', TRUE, 'IA (Daily Sync)', 'IA Verificata', 0, 4, '2026-11-02T10:35:44.754203+00:00'),
('184ecbfb-f4d3-4884-b710-6d391b427848', 288, 'Curiosità & Retroscena', 'Il finale originariamente previsto e mai girato', 'Nelle prime fasi di sviluppo della sceneggiatura firmata da Evan Hunter, il finale del film avrebbe dovuto mostrare San Francisco completamente invasa e bloccata da milioni di uccelli neri posati su ogni edificio e monumento. L''idea fu tuttavia scartata a causa dei limiti tecnici insormontabili dell''epoca e dei costi proibitivi stimati per la realizzazione degli effetti visivi.', 'Sceneggiature preliminari conservate presso la Margaret Herrick Library', TRUE, 'IA (Daily Sync)', 'IA Verificata', 0, 5, '2026-11-02T10:35:44.754203+00:00'),
('6517fe32-def4-4afc-9743-24bf2ad57b07', 192, 'Casting & Scelte', 'Il legame mancato con la saga originale', 'Nonostante il titolo italiano lo presenti come un terzo capitolo, in Francia il film si intitola ''L''étudiante'' e non vede la partecipazione di Claude Brasseur o Brigitte Fossey, i genitori storici di Vic nei primi due film, rendendo di fatto questo lungometraggio uno spin-off incentrato esclusivamente sul personaggio di Valentine.', 'Note di produzione ufficiali Gaumont e stampa dell''epoca', TRUE, 'IA (Daily Sync)', 'IA Verificata', 0, 0, '2026-11-02T14:46:19.760631+00:00'),
('c105d022-e64f-4fa2-9823-d8a3f38299a6', 192, 'Aneddoti dal set', 'La preparazione musicale di Vincent Lindon', 'Per interpretare in modo credibile il musicista jazz Ned, l''attore Vincent Lindon ha dovuto sottoporsi a mesi di lezioni intensive di pianoforte e tromba, lavorando a stretto contatto con il compositore della colonna sonora Vladimir Cosma.', 'Intervista promozionale a Vincent Lindon per Antenne 2', TRUE, 'IA (Daily Sync)', 'IA Verificata', 0, 1, '2026-11-02T14:46:19.760631+00:00'),
('74f49ce4-fb00-4b88-8ffc-387df042e17f', 192, 'Curiosità & Retroscena', 'Il ritorno della voce storica di Vladimir Cosma', 'Il celebre compositore Vladimir Cosma è tornato a firmare la colonna sonora del film, riprendendo in parte le atmosfere romantiche che avevano decretato il successo planetario dei primi film con Sophie Marceau, pur virando verso sonorità più mature e vicine al jazz.', 'Archivio storico delle colonne sonore di Vladimir Cosma', TRUE, 'IA (Daily Sync)', 'IA Verificata', 0, 2, '2026-11-02T14:46:19.760631+00:00'),
('51a3c728-3c55-4741-9578-27b8c280ebcc', 192, 'Segreti di produzione', 'Le riprese nei luoghi simbolo della Sorbona', 'La produzione ha ottenuto permessi speciali per girare all''interno e nei dintorni dell''Università della Sorbona a Parigi, affrontando notevoli difficoltà logistiche dovute alla gestione delle comparse composte da veri studenti universitari in fermento alla fine degli anni ottanta.', 'Diario di lavorazione della troupe di Claude Pinoteau', TRUE, 'IA (Daily Sync)', 'IA Verificata', 0, 3, '2026-11-02T14:46:19.760631+00:00'),
('c545819e-36ae-4392-b46d-aeeb462c2e63', 269, 'Curiosità & Retroscena', 'L''origine teatrale e il salto al cinema', 'Il film nasce dal grande successo dei loro sketch teatrali e televisivi a ''Mai dire Gol''. La Medusa Film decise di puntare sul trio comico quasi al buio, affidando la regia agli stessi Aldo, Giovanni e Giacomo insieme a Marcello Cesena, sebbene nei titoli ufficiali la regia risulti accreditata ad Aldo, Giovanni e Giacomo e a Massimo Venier.', 'Interviste retrospettive del trio e note di produzione Medusa', TRUE, 'IA (Daily Sync)', 'IA Verificata', 0, 0, '2026-11-02T14:47:26.682469+00:00'),
('0227d4cd-7fb5-4f40-822b-360abb02c2dd', 269, 'Casting & Scelte', 'La scelta del titolo originale', 'Nelle prime fasi di sviluppo e scrittura della sceneggiatura con Giorgio Gherarducci e Graziano Graziani, il film era noto internamente con diversi titoli di lavorazione prima di optare per il definitivo ''Tre uomini e una gamba'', che omaggiava vagamente i titoli classici della commedia all''italiana.', 'Archivio storico della produzione Agidi', TRUE, 'IA (Daily Sync)', 'IA Verificata', 0, 1, '2026-11-02T14:47:26.682469+00:00'),
('9ac1e0fa-0adf-449b-ad71-d779e5e49fc4', 269, 'Segreti di produzione', 'La gamba di Allemand', 'La celebre scultura in legno dell''artista Allemand, fulcro comico e narrativo del viaggio, è stata realizzata materialmente da reparti di scenografia artigianale milanesi. Ne furono costruite diverse copie con differenti pesi e consistenze per le varie scene, inclusa una versione galleggiante per la celebre sequenza del fiume.', 'Making-of ufficiale e contenuti speciali del DVD Medusa', TRUE, 'IA (Daily Sync)', 'IA Verificata', 0, 2, '2026-11-02T14:47:26.682469+00:00'),
('29dfc6fa-4671-4d9f-b363-c931c20c7e32', 269, 'Aneddoti dal set', 'La partita a calcetto sulla spiaggia', 'La memorabile e citatissima sequenza della partita a calcetto sulla spiaggia (con la famosa battuta ''Ajeje Brazorf'' e le celebri punizioni) è stata girata in Puglia durante le ultime settimane di lavorazione, con temperature non proprio estive che costrinsero la troupe a pause frequenti per riscaldare gli attori.', 'Diario di bordo e interviste dal backstage del film', TRUE, 'IA (Daily Sync)', 'IA Verificata', 0, 3, '2026-11-02T14:47:26.682469+00:00'),
('d2763737-f5e9-421d-a15c-626e90440cb0', 269, 'Casting & Scelte', 'Il cameo di Marina Massironi e i ruoli multipli', 'Marina Massironi, all''epoca compagna di Giacomo Poretti nella vita, interpreta Chiara ma veste anche i panni di altre figure minori all''interno degli sketch onirici e teatrali inseriti nella narrazione cinematografica, consolidando la formula del quartetto comico.', 'Note di cast ufficiali del film', TRUE, 'IA (Daily Sync)', 'IA Verificata', 0, 4, '2026-11-02T14:47:26.682469+00:00'),
('e98f2c30-f414-4652-95f2-6d0ed73f6582', 269, 'Curiosità & Retroscena', 'Le riprese ininterrotte e il budget ridotto', 'Il film fu realizzato con un budget estremamente contenuto per gli standard cinematografici dell''epoca (circa 2 miliardi di lire). Questa ristrettezza economica impose ritmi di lavorazione serratissimi, costringendo la troupe a completare le riprese in meno di sei settimane tra Milano, Gallipoli e altre tappe intermedie.', 'Dichiarazioni di Massimo Venier e dei produttori in retrospettive sul film', TRUE, 'IA (Daily Sync)', 'IA Verificata', 0, 5, '2026-11-02T14:47:26.682469+00:00'),
('ff72ac2d-9b54-407a-be4e-07b8c393f6d8', 289, 'Curiosità & Retroscena', 'L''incredibile errore di battitura sulla statuetta dell''Oscar', 'Quando Spencer Tracy vinse il premio Oscar come miglior attore protagonista per il ruolo di Manuel, la statuetta consegnatagli dall''Academy riportava per errore l''incisione ''To Dick Tracy''. L''Academy si scusò tempestivamente per la clamorosa gaffe tipografica e sostituì il trofeo con uno recante la dicitura corretta.', 'Archivi ufficiali dell''Academy of Motion Picture Arts and Sciences (AMPAS)', TRUE, 'IA (Daily Sync)', 'IA Verificata', 0, 0, '2026-11-02T10:39:31.508209+00:00'),
('cfb85c4a-aa1b-4373-8ce0-6210162b11ea', 289, 'Segreti di produzione', 'L''acquisto e il viaggio transoceanico del veliero ''Mariner''', 'Per impersonare l''iconico peschereccio ''We''re Here'', la MGM non costruì una replica da studio ma acquistò un autentico schooner da pesca d''altura del New England, il ''Mariner'', varato a Gloucester nel 1923. Lo scafo affrontò un lungo viaggio attraverso il Canale di Panama per raggiungere le coste della California, dove venne appositamente riallestito per le riprese.', 'Gloucester Maritime Heritage Center / Note di produzione MGM', TRUE, 'IA (Daily Sync)', 'IA Verificata', 0, 1, '2026-11-02T10:39:31.508209+00:00'),
('40a199d2-e613-4ce2-a75a-3cac54cab0c3', 289, 'Aneddoti dal set', 'Il terrore del canto e la permanente odiata di Spencer Tracy', 'Spencer Tracy era convinto che il film gli avrebbe distrutto la carriera: si considerava completamente stonato e si rifiutava categoricamente di cantare davanti alla macchina da presa. Per convincerlo a registrare i brani di scena composti da Franz Waxman, la produzione dovette affiancargli un vocal coach a tempo pieno e il produttore Louis B. Mayer dovette rassicurarlo personalmente.', 'Biografie ''Spencer Tracy: A Biography'' di James Curtis', TRUE, 'IA (Daily Sync)', 'IA Verificata', 0, 2, '2026-11-02T10:39:31.508209+00:00'),
('f4f1f469-547d-4e1d-8d7c-d8e5e182a95d', 289, 'Curiosità & Retroscena', 'La battaglia legale per la custodia di Freddie Bartholomew', 'Durante le settimane più intense di riprese, la produzione rischiò la sospensione a causa della feroce battaglia legale per la custodia e i cospicui guadagni del dodicenne Freddie Bartholomew. I genitori naturali del ragazzo, che lo avevano abbandonato anni prima in Inghilterra, intentarono causa alla zia Mignon, costringendo il giovane attore a dividersi estenuantemente tra il set e le aule di tribunale di Los Angeles.', 'Archivi storici del Los Angeles Times (1936-1937)', TRUE, 'IA (Daily Sync)', 'IA Verificata', 0, 3, '2026-11-02T10:39:31.508209+00:00'),
('5b03708c-052b-491a-b224-49f78d804335', 289, 'Aneddoti dal set', 'La collisione reale tra le golette durante la regata finale', 'Nella drammatica sequenza della regata finale tra il ''We''re Here'' e la goletta rivale ''Jennie Cushman'', il vento teso al largo dell''isola di Santa Catalina spinse le due navi a una collisione imprevista. L''impatto spezzò parte del sartiame e mise a repentaglio i marinai a bordo, ma il regista Victor Fleming decise di non interrompere la scena, includendo l''incidente nel montaggio definitivo per massimizzare il realismo.', 'Making-of documentario ''Victor Fleming: An American Movie Master''', TRUE, 'IA (Daily Sync)', 'IA Verificata', 0, 4, '2026-11-02T10:39:31.508209+00:00'),
('a054500f-d22a-4f0c-a2d2-0d8f5ae012ef', 289, 'Curiosità & Retroscena', 'La scomparsa dell''autore Rudyard Kipling prima dell''uscita', 'Il film è l''adattamento dell''omonimo romanzo pubblicato nel 1897 dal premio Nobel Rudyard Kipling. Tuttavia, lo scrittore britannico non riuscì mai a vedere la trasposizione hollywoodiana della sua opera sul grande schermo: morì a Londra nel gennaio 1936, mentre la sceneggiatura era ancora in fase di riscrittura negli uffici della MGM.', 'Registri di produzione Metro-Goldwyn-Mayer', TRUE, 'IA (Daily Sync)', 'IA Verificata', 0, 5, '2026-11-02T10:39:31.508209+00:00'),
('86bde9e9-d49a-4a2c-97b2-4abe30859fa5', 197, 'Casting & Scelte', 'L''ingresso di Tina Turner nel franchise', 'George Miller ha scelto Tina Turner per il ruolo di Aunty Entity dopo averla vista nel film ''Quadrophenia'' (1979) e rimanendo folgorato dalla sua presenza scenica magnetica e dalla sua energia prorompente.', 'Intervista ufficiale a George Miller nei contenuti speciali del Blu-ray', TRUE, 'IA (Daily Sync)', 'IA Verificata', 0, 0, '2026-11-02T14:46:26.456804+00:00'),
('3e7869fe-8f5a-4f29-9729-34407006db35', 197, 'Curiosità & Retroscena', 'La morte improvvisa del co-regista Byron Kennedy', 'Il produttore e co-regista storico Byron Kennedy morì tragicamente in un incidente di elicottero mentre cercava le location per il film nel 1983; questo evento spinse George Miller a dedicare il film all''amico e a co-dirigerlo insieme a George Ogilvie.', 'Note di produzione ufficiali e biografia di George Miller', TRUE, 'IA (Daily Sync)', 'IA Verificata', 0, 1, '2026-11-02T14:46:26.456804+00:00'),
('28844a8c-774a-4b97-8074-50d8365c15c5', 197, 'Curiosità & Retroscena', 'Il brano musicale vincitore di Grammy', 'Tina Turner ha interpretato e co-scritto la celebre canzone portante del film, ''We Don''t Need Another Hero (Thunderdome)'', che ha ottenuto un enorme successo commerciale globale e una nomination ai Golden Globe.', 'Archivi ufficiali Billboard e crediti della colonna sonora', TRUE, 'IA (Daily Sync)', 'IA Verificata', 0, 2, '2026-11-02T14:46:26.456804+00:00'),
('b7c645a2-12dd-45b8-ab3e-d39ef6da72a0', 197, 'Aneddoti dal set', 'Gli infortuni di Mel Gibson sul set', 'Durante le riprese delle sequenze d''azione all''interno del Thunderdome, Mel Gibson ha riportato diversi lividi e piccoli infortuni a causa della durezza degli scontri fisici con il lottatore Nathan Jones / stuntmen professionisti, insistendo per girare gran parte dei combattimenti senza controfigura.', 'Documentario ''The Making of Mad Max Beyond Thunderdome''', TRUE, 'IA (Daily Sync)', 'IA Verificata', 0, 3, '2026-11-02T14:46:26.456804+00:00'),
('81c1f56c-6c5c-4979-bcdc-0811a66f0de8', 197, 'Effetti speciali & Trucco', 'Il costume pesante di Aunty Entity', 'Il celebre abito metallico e di maglia indossato da Tina Turner pesava oltre 50 chili, costringendo l''artista a sottoporsi a sedute di fisioterapia durante le pause delle riprese per alleviare i dolori alla schiena.', 'Intervista a Tina Turner per il press kit cinematografico del 1985', TRUE, 'IA (Daily Sync)', 'IA Verificata', 0, 4, '2026-11-02T14:46:26.456804+00:00'),
('8a42a728-bbca-43ef-90da-581b833b408a', 197, 'Casting & Scelte', 'La scelta del cast dei bambini', 'La tribù di bambini ferali guidata dal personaggio di Savannah Nix fu selezionata attingendo principalmente da scuole di recitazione e gruppi teatrali giovanili di Sydney, sottoposti a un rigido addestramento di sopravvivenza nel deserto.', 'Note di produzione Warner Bros.', TRUE, 'IA (Daily Sync)', 'IA Verificata', 0, 5, '2026-11-02T14:46:26.456804+00:00'),
('28519d28-51b3-43bf-9444-d7fc0cf40eff', 197, 'Segreti di produzione', 'I veicoli assemblati nel deserto', 'La scenografa Cynthia Whitaker e il supervisore ai veicoli Bob Murray hanno assemblato le bizzarre macchine post-apocalittiche utilizzando pezzi di ricambio recuperati da sfasciacarrozze australiani, unendo telai di camion militari e motori truccati.', 'Featurette ''The Vehicles of the Wasteland''', TRUE, 'IA (Daily Sync)', 'IA Verificata', 0, 6, '2026-11-02T14:46:26.456804+00:00'),
('3974351f-bbbb-4041-b615-f2c653f49bc4', 197, 'Aneddoti dal set', 'Le riprese nel deserto australiano', 'Gran parte delle sequenze esterne fu girata nelle remote saline di Coober Pedy, nell''Australia Meridionale, dove la troupe affrontò temperature estreme superiori ai 45 gradi Celsius e frequenti tempeste di sabbia che danneggiavano le macchine da presa.', 'Diario di lavorazione della troupe di produzione', TRUE, 'IA (Daily Sync)', 'IA Verificata', 0, 7, '2026-11-02T14:46:26.456804+00:00'),
('e5b27ca4-5773-4ea8-9575-fe48468d3295', 211, 'Curiosità & Retroscena', 'Il fenomeno virale di #GentleMinions', 'Durante l''uscita nelle sale nel 2022, il film è diventato il centro di un trend virale su TikTok noto come #GentleMinions, in cui gruppi di adolescenti si recavano al cinema indossando abiti eleganti e completi da sera per assistere alla proiezione, portando in alcuni casi a restrizioni o divieti da parte delle sale cinematografiche nel Regno Unito.', 'Comunicati stampa Universal Pictures e copertura mediatica BBC/Guardian', TRUE, 'IA (Daily Sync)', 'IA Verificata', 0, 0, '2026-11-02T14:46:38.460369+00:00'),
('6bbe9493-521c-4ff9-9270-25d225df8a4d', 290, 'Curiosità & Retroscena', 'La gestazione quindicennale di James Vanderbilt', 'Il regista e sceneggiatore James Vanderbilt ha lavorato alla sceneggiatura di ''Nuremberg'' per oltre 15 anni prima dell''inizio delle riprese. Dopo aver acquisito i diritti del saggio di Jack El-Hai, Vanderbilt ha riscritto il testo numerose volte per bilanciare accuratamente il dramma processuale con l''analisi psichiatrica dei detenuti.', 'Intervista a James Vanderbilt su Deadline Hollywood', TRUE, 'IA (Daily Sync)', 'IA Verificata', 0, 0, '2026-11-02T10:40:29.358474+00:00'),
('c64c190d-4bfb-47c1-8f9f-bc6d6ebfa0c6', 290, 'Segreti di produzione', 'Budapest come controfigura della Germania post-bellica', 'Le riprese principali, iniziate nel febbraio 2024, si sono svolte interamente in Ungheria, principalmente a Budapest. La città è stata scelta per la sua architettura neoclassica e i complessi industriali che hanno permesso di ricreare con estremo realismo sia gli esterni del Palazzo di Giustizia che le zone distrutte dai bombardamenti alleati.', 'Report di produzione di Variety', TRUE, 'IA (Daily Sync)', 'IA Verificata', 0, 1, '2026-11-02T10:40:29.358474+00:00'),
('7e332009-281e-4c0a-ad9d-d3fc330ad92e', 290, 'Segreti di produzione', 'La firma visiva di Dariusz Wolski', 'La direzione della fotografia è stata affidata a Dariusz Wolski, celebre collaboratore di Ridley Scott. Wolski ha scelto di utilizzare lenti di grande formato per creare una profondità di campo ridotta, isolando visivamente i volti di Malek e Crowe durante i loro serrati confronti verbali per enfatizzare l''aspetto claustrofobico della cella.', 'Note tecniche di produzione / British Cinematographer', TRUE, 'IA (Daily Sync)', 'IA Verificata', 0, 2, '2026-11-02T10:40:29.358474+00:00'),
('1ff8da9d-1f77-43ad-a6fd-1ba8d88dc486', 290, 'Casting & Scelte', 'Leo Woodall e il ruolo chiave di Howie Triest', 'L''attore Leo Woodall interpreta Howie Triest, un personaggio storico reale di fondamentale importanza: un ebreo tedesco fuggito negli Stati Uniti che tornò in Germania come interprete militare. Triest fu l''unico ponte linguistico e psicologico tra lo psichiatra Kelley e i gerarchi nazisti, vivendo un profondo conflitto interiore documentato nei suoi diari.', 'Comunicato stampa ufficiale del cast / The Hollywood Reporter', TRUE, 'IA (Daily Sync)', 'IA Verificata', 0, 3, '2026-11-02T10:40:29.358474+00:00'),
('167b61dc-f768-4477-8e0a-bc706458409b', 290, 'Casting & Scelte', 'John Slattery e l''ossessione del colonnello Andrus', 'John Slattery interpreta il colonnello Burton C. Andrus, il comandante del carcere di Norimberga noto per la sua estrema rigidità. Per prepararsi, Slattery ha studiato il rigido protocollo di sicurezza imposto da Andrus, che includeva l''ispezione costante delle celle ogni 30 secondi per prevenire i suicidi dei prigionieri, come quello di Robert Ley.', 'Intervista al cast su Deadline', TRUE, 'IA (Daily Sync)', 'IA Verificata', 0, 4, '2026-11-02T10:40:29.358474+00:00'),
('3f0b789f-a778-49a5-8622-fa7451f72e9c', 290, 'Casting & Scelte', 'Richard E. Grant e il duello legale con Göring', 'Richard E. Grant interpreta Sir David Maxwell Fyfe, il procuratore britannico che riuscì a mettere in difficoltà Göring durante il controinterrogatorio. Grant ha studiato i verbali originali del processo per replicare il tono calmo ma implacabile con cui Maxwell Fyfe smontò le giustificazioni del gerarca, un momento considerato la svolta del processo.', 'Annuncio ufficiale di produzione / Variety', TRUE, 'IA (Daily Sync)', 'IA Verificata', 0, 5, '2026-11-02T10:40:29.358474+00:00'),
('bb965d31-600e-4bdc-9f07-43df8a33b898', 290, 'Segreti di produzione', 'La ricostruzione dell''Ala Carceraria di Eve Stewart', 'La scenografa Eve Stewart, candidata all''Oscar, ha supervisionato la ricostruzione millimetrica delle celle del carcere di Norimberga. Le scenografie sono state realizzate rispettando le dimensioni originali di 2,5 per 4 metri, includendo i mobili spartani e le finestre oscurate, per trasmettere agli attori il senso di isolamento totale vissuto dai gerarchi.', 'Note di produzione ufficiali / Architectural Digest', TRUE, 'IA (Daily Sync)', 'IA Verificata', 0, 6, '2026-11-02T10:40:29.358474+00:00');
INSERT INTO public.movie_trivia ("id", "film_id", "categoria", "titolo", "descrizione", "fonte", "approvato", "inserito_da", "provenienza", "likes", "ordine", "created_at") VALUES
('524fa072-ef37-46bd-bc8d-6273419f29bd', 290, 'Casting & Scelte', 'Mark O''Brien e l''instabilità di Rudolf Hess', 'Mark O''Brien interpreta Rudolf Hess, il vice di Hitler noto per il suo comportamento erratico durante il processo. O''Brien ha lavorato specificamente sulla mimica facciale e sullo sguardo assente di Hess, basandosi sui filmati d''archivio che mostrano il gerarca mentre finge amnesia o legge romanzi durante le testimonianze sui crimini di guerra.', 'Intervista a Mark O''Brien / Collider', TRUE, 'IA (Daily Sync)', 'IA Verificata', 0, 7, '2026-11-02T10:40:29.358474+00:00'),
('40e9a19c-560a-41b3-906a-905dc5c558df', 290, 'Casting & Scelte', 'Lotte Verbeek nel ruolo di Emmy Göring', 'L''attrice Lotte Verbeek interpreta Emmy Göring, la moglie del gerarca. La sua presenza nel film serve a mostrare il lato privato e manipolatorio di Göring, evidenziando come l''uomo cercasse di mantenere un''immagine di dignità e potere anche di fronte alla propria famiglia mentre era in attesa di giudizio.', 'Casting news di The Hollywood Reporter', TRUE, 'IA (Daily Sync)', 'IA Verificata', 0, 8, '2026-11-02T10:40:29.358474+00:00'),
('a032953f-8048-4b00-94d4-dc676cf8fc1f', 290, 'Curiosità & Retroscena', 'Il coinvolgimento di Walden Media per l''accuratezza storica', 'La casa di produzione Walden Media è stata coinvolta nel progetto con l''obiettivo specifico di garantire che il film potesse servire come risorsa educativa. Hanno collaborato con storici dell''Olocausto per assicurarsi che ogni dettaglio del protocollo legale e delle prove presentate in aula fosse storicamente inattaccabile.', 'Sito ufficiale Walden Media / Note di produzione', TRUE, 'IA (Daily Sync)', 'IA Verificata', 0, 9, '2026-11-02T10:40:29.358474+00:00'),
('9e883399-b3f3-4d1c-ade5-443e37bfbc7b', 208, 'Casting & Scelte', 'Il doppiaggio di Lucy Wilde e le prove di Kristen Wiig', 'Kristen Wiig aveva già partecipato al primo film del franchise doppiando il personaggio minore di Miss Hattie, la direttrice dell''orfanotrofio. I registi ne rimasero così colpiti da richiamarla per il ruolo da co-protagonista di Lucy Wilde, agente della Lega Anti-Cattivi.', 'Commento audio del Blu-ray ufficiale', TRUE, 'IA (Daily Sync)', 'IA Verificata', 0, 2, '2026-11-02T14:46:30.619519+00:00'),
('672ff0f7-4f34-404a-b034-105e8c76ab58', 208, 'Curiosità & Retroscena', 'I camei vocali dei registi nei ruoli dei Minions', 'Il co-regista Pierre Coffin ha doppiato personalmente quasi tutti i Minions presenti nel film, registrando centinaia di battute in un linguaggio inventato noto come ''Minionese''. Il secondo regista Chris Renaud ha collaborato alla voce di alcuni Minions aggiuntivi.', 'Documentario dietro le quinte del DVD', TRUE, 'IA (Daily Sync)', 'IA Verificata', 0, 3, '2026-11-02T14:46:30.619519+00:00'),
('1ca3db18-9755-4c0a-8f4e-1aa053ce8fb2', 208, 'Citazioni & Easter Egg', 'L''omaggio a Stanley Kubrick nel laboratorio segreto', 'Il design del laboratorio sotterraneo segreto della Lega Anti-Cattivi e alcune inquadrature dei corridoi con pavimenti riflettenti contengono riferimenti visivi intenzionali all''estetica di ''2001: Odissea nello spazio'' di Stanley Kubrick.', 'Analisi visiva e note di regia nel libro d''arte del film', TRUE, 'IA (Daily Sync)', 'IA Verificata', 0, 4, '2026-11-02T14:46:30.619519+00:00'),
('82571eaf-cce0-442f-9726-a6d08a9c343d', 208, 'Segreti di produzione', 'La lingua dei Minions e le ispirazioni culinarie', 'Il ''Minionese'' parlato dai piccoli aiutanti gialli non è una lingua casuale ma un collage fonetico di parole reali prese in prestito da diverse lingue del mondo, tra cui l''italiano, il francese, lo spagnolo, il cinese e il russo, spesso inserendo termini legati al cibo come ''gelato'' o ''pomo d''oro''.', 'Intervista al sound designer e co-regista Pierre Coffin', TRUE, 'IA (Daily Sync)', 'IA Verificata', 0, 5, '2026-11-02T14:46:30.619519+00:00'),
('174ef8c1-43ee-4f6c-9921-0f24cf38d5f6', 291, 'Segreti di produzione', 'La sceneggiatura scritta in prima persona', 'Per enfatizzare la narrazione soggettiva del protagonista, Christopher Nolan ha scritto l''intera sceneggiatura delle scene a colori usando la prima persona singolare («Io entro nella stanza», «Io guardo»). Cillian Murphy e Robert Downey Jr. hanno confermato che si tratta di una scelta insolita e inedita per un copione hollywoodiano, pensata per chiarire che la cinepresa rappresentava la mente stessa di Oppenheimer.', 'Intervista a Christopher Nolan e Cillian Murphy su The Hollywood Reporter', TRUE, 'IA (Daily Sync)', 'IA Verificata', 0, 0, '2026-11-02T11:01:36.918224+00:00'),
('228a117a-6ffd-4c49-aaf4-1e6d653b476b', 341, 'Segreti di produzione', 'La collaborazione con John Underkoffler per l''interfaccia gestuale', 'L''interfaccia utente olografica basata sui movimenti delle mani non fu un''invenzione cinematografica casuale, ma fu sviluppata dal pioniere della computer grafica John Underkoffler, consulente scientifico del film, che anticipò tecnologie reali come il Microsoft Kinect.', 'Documentario scientifico sulla tecnologia di Minority Report', TRUE, 'IA (Daily Sync)', 'IA Verificata', 0, 6, '2026-11-02T14:51:22.492045+00:00'),
('c3fa737b-326f-4096-927a-3389581135aa', 291, 'Casting & Scelte', 'La promessa di Matt Damon durante la terapia di coppia', 'Durante una seduta di terapia di coppia con la moglie Luciana Barroso, Matt Damon aveva promesso di prendersi una lunga pausa recitativa a tempo indeterminato. L''attore aveva tuttavia posto un''unica clausola negoziale: avrebbe interrotto il congedo solo ed esclusivamente nel caso in cui Christopher Nolan lo avesse chiamato per un film, cosa puntualmente verificatasi poco tempo dopo per il ruolo del Generale Leslie Groves.', 'Intervista al cast su Entertainment Weekly ''Around the Table''', TRUE, 'IA (Daily Sync)', 'IA Verificata', 0, 2, '2026-11-02T11:01:36.918224+00:00'),
('44bc8fde-3ec3-4706-8536-ecadea521e9b', 291, 'Aneddoti dal set', 'Le riprese nella vera casa di Oppenheimer a Los Alamos', 'La produzione ha ottenuto il permesso straordinario di girare all''interno della residenza originale in cui J. Robert e Kitty Oppenheimer vissero durante gli anni del Progetto Manhattan a Los Alamos. Cillian Murphy ed Emily Blunt hanno recitato le scene domestiche tra le stesse identiche mura storiche, mentre per le sequenze accademiche è stato impiegato il vero ufficio occupato da Albert Einstein all''Institute for Advanced Study di Princeton.', 'Note di produzione ufficiali di Universal Pictures', TRUE, 'IA (Daily Sync)', 'IA Verificata', 0, 3, '2026-11-02T11:01:36.918224+00:00'),
('1a326e17-fa6e-4217-8fc2-b5eedb0802ae', 291, 'Segreti di produzione', 'Il taglio di 30 giorni di riprese per ricostruire la città', 'La scenografa Ruth De Jong aveva calcolato che ricostruire da zero la città segreta di Los Alamos a Ghost Ranch, nel New Mexico, avrebbe superato il budget assegnato. Per non rinunciare all''accuratezza storica, Nolan decise di tagliare il piano di lavorazione da circa 85 a soli 57 giorni di riprese complessive, dirottando i milioni di dollari risparmiati sulla costruzione dei set e sul design di produzione.', 'Intervista a Ruth De Jong nel podcast ''Team Deakins''', TRUE, 'IA (Daily Sync)', 'IA Verificata', 0, 4, '2026-11-02T11:01:36.918224+00:00'),
('41121c7d-63e4-40f7-a0e5-9ad0ff8ff51c', 129, 'Aneddoti dal set', 'La richiesta insolita di Robert De Niro per la cicatrice', 'Durante le riprese, Robert De Niro chiese personalmente ai truccatori di modificare leggermente una cicatrice finta sul suo viso per renderla storicamente e anatomicamente più simile a quelle che aveva visto sui veri gangster veterani che aveva studiato per la preparazione del personaggio.', 'Documentario di backstage e note di produzione', TRUE, 'IA (Daily Sync)', 'IA Verificata', 0, 0, '2026-11-02T10:04:37.173431+00:00'),
('e5befde1-ebfe-4375-99fc-1891e3f0bd9d', 291, 'Curiosità & Retroscena', 'La pellicola IMAX da record: 17 chilometri e 270 chili', 'La bobina fisica della versione cinematografica del film in formato IMAX 70mm ha raggiunto una lunghezza complessiva di circa 11 miglia (17,7 chilometri) per un peso di circa 272 chilogrammi. Le dimensioni erano tali da superare i limiti standard dei piatti di proiezione degli impianti IMAX, costringendo l''azienda a progettare e stampare su misura dei bracci estensori speciali per consentire lo scorrimento del film.', 'Dichiarazione ufficiale di IMAX Corporation e interviste tecniche ad Associated Press', TRUE, 'IA (Daily Sync)', 'IA Verificata', 0, 5, '2026-11-02T11:01:36.918224+00:00'),
('979d35ad-f155-4dbe-bfa4-b931053fa6be', 291, 'Aneddoti dal set', 'La battuta improvvisata sul viaggio di nozze a Kyoto', 'Durante la sequenza in cui i comandi militari e governativi scelgono le città giapponesi da bombardare, l''attore James Remar (nel ruolo del Segretario alla Guerra Henry Stimson) ha improvvisato la battuta in cui esclude Kyoto spiegando che lui e la moglie vi avevano trascorso la luna di miele. Si tratta di un aneddoto storico autentico scovato da Remar durante le sue ricerche personali e accolto con entusiasmo da Nolan durante il ciak.', 'Intervista a Christopher Nolan su The New York Times', TRUE, 'IA (Daily Sync)', 'IA Verificata', 0, 6, '2026-11-02T11:01:36.918224+00:00'),
('91994248-bd20-4e7c-822c-7b60d3323dbc', 291, 'Curiosità & Retroscena', 'La partitura musicale incentrata sul violino', 'Christopher Nolan ha espressamente chiesto al compositore Ludwig Göransson di strutturare l''intera colonna sonora attorno al violino. Essendo uno strumento privo di tasti sulla tastiera, il violino consente slittamenti microtonali che possono passare in una frazione di secondo da melodie liriche a stridori nevrotici, rispecchiando l''ansia e la frammentazione psicologica vissuta da Oppenheimer.', 'Intervista a Ludwig Göransson su Variety', TRUE, 'IA (Daily Sync)', 'IA Verificata', 0, 7, '2026-11-02T11:01:36.918224+00:00'),
('9506eb0b-482d-426c-b01c-47525a7a704d', 291, 'Segreti di produzione', 'I protocolli di massima sicurezza e la carta rossa anti-copia', 'Per scongiurare qualsiasi fuga di notizie o spoiler prima dell''uscita, Nolan ha fatto stampare le copie fisiche del copione con inchiostro nero su una speciale carta rossa opaca, impossibile da fotocopiare o scansionare nitidamente. Attori di primo piano come Robert Downey Jr. hanno dovuto leggere l''opera recandosi personalmente a casa del regista in California, senza poter portare via il documento.', 'Intervista a Robert Downey Jr. su Vanity Fair', TRUE, 'IA (Daily Sync)', 'IA Verificata', 0, 8, '2026-11-02T11:01:36.918224+00:00'),
('f93aa185-d4e2-4a44-9dfb-c6f287c5e9d3', 291, 'Citazioni & Easter Egg', 'L''udienza AEC recitata quasi parola per parola dai verbali segreti', 'Le drammatiche sequenze dell''udienza di sicurezza del 1954 in cui Oppenheimer viene interrogato per revocargli il nulla osta attingono quasi testualmente al documento ''In the Matter of J. Robert Oppenheimer'', la trascrizione declassificata di oltre 1.000 pagine redatta dalla Commissione per l''energia atomica. Nolan ha fatto ricostruire la stanza 2022 rispettando al millimetro le dimensioni claustrofobiche dell''ufficio originario.', 'Intervista a Christopher Nolan per il British Film Institute (BFI)', TRUE, 'IA (Daily Sync)', 'IA Verificata', 0, 9, '2026-11-02T11:01:36.918224+00:00'),
('011894d4-697a-45b0-b305-8bb5ddb3b168', 210, 'Casting & Scelte', 'L''ingaggio di Trey Parker per Balthazar Bratt', 'I registi e la produzione hanno scelto Trey Parker, co-creatore di South Park, per doppiare il cattivo Balthazar Bratt grazie alla sua unicità vocale e alla sua capacità di incarnare un ex bambino prodigio amareggiato degli anni ''80. La sua voce conferisce al personaggio un tono nostalgico ma al tempo stesso bizzarro e imprevedibile.', 'Note di produzione ufficiali Illumination Entertainment', TRUE, 'IA (Daily Sync)', 'IA Verificata', 0, 0, '2026-11-02T14:46:34.413093+00:00'),
('8f33b498-2776-4abf-b3a7-b0da97082e28', 341, 'Citazioni & Easter Egg', 'Il cameo del direttore della fotografia Janusz Kamiński', 'Il fedele direttore della fotografia di Steven Spielberg, Janusz Kamiński, appare brevemente in un cameo non accreditato come passeggero all''interno di un vagone della metropolitana durante le sequenze di fuga di John Anderton.', 'Special features e crediti nascosti del Blu-ray', TRUE, 'IA (Daily Sync)', 'IA Verificata', 0, 7, '2026-11-02T14:51:22.492045+00:00'),
('c0da0d0e-71d2-4b5b-8bbf-5caac8f12d23', 292, 'Casting & Scelte', 'Il ruolo di Chris Hemsworth nel coinvolgimento di Scarlett Johansson', 'Scarlett Johansson ha accettato di interpretare Rosie Betzler grazie all''intercessione del collega Chris Hemsworth. Durante le riprese di ''Thor: Ragnarok'', Taika Waititi aveva fatto leggere la sceneggiatura a Hemsworth, il quale ne rimase talmente entusiasta da girarla direttamente all''attrice, convincendola a incontrare il regista neozelandese.', 'Intervista a Scarlett Johansson e Taika Waititi per Variety', TRUE, 'IA (Daily Sync)', 'IA Verificata', 0, 0, '2026-11-02T11:22:34.825254+00:00'),
('d361f346-434f-4766-a324-99b5ebac1fed', 292, 'Aneddoti dal set', 'I veri gemelli del protagonista reclutati come cloni', 'I fratelli gemelli minori del protagonista Roman Griffin Davis, Gilby e Hardy Griffin Davis, appaiono nel film interpretando due dei piccoli membri della Gioventù Hitleriana durante il campo di addestramento. L''intera famiglia è attiva nel cinema: la madre è la regista Camille Griffin e il padre è il celebre direttore della fotografia Ben Davis.', 'Note di produzione ufficiali di Fox Searchlight', TRUE, 'IA (Daily Sync)', 'IA Verificata', 0, 1, '2026-11-02T11:22:34.825254+00:00'),
('24859e2f-87ea-4f3e-9da6-cbe0d477e5e6', 292, 'Segreti di produzione', 'La scelta di Žatec e Úštěk per ricreare la Germania d''epoca', 'Per ambientare la cittadina fittizia di Falkenheim, la produzione ha evitato i teatri di posa tedeschi girando nelle città ceche di Žatec e Úštěk, oltre che presso i leggendari studi Barrandov di Praga. Queste località storiche sono state scelte perché i loro centri urbani prebellici erano rimasti pressoché intatti dopo il secondo conflitto mondiale.', 'Making-of ufficiale ''Inside Jojo Rabbit''', TRUE, 'IA (Daily Sync)', 'IA Verificata', 0, 2, '2026-11-02T11:22:34.825254+00:00'),
('1dcee577-e5f6-4e4d-92b5-51dcc0b50d7e', 292, 'Curiosità & Retroscena', 'Il cappotto su misura per i due metri di Stephen Merchant', 'La costumista Mayes C. Rubeo ha dovuto realizzare interamente a mano il trench di pelle nera del capitano Deertz della Gestapo a causa dell''altezza imponente dell''attore Stephen Merchant, alto ben 2 metri e 1 centimetro. Il contrasto tra la sua statura gigantesca e la minuscola stanza di Jojo è stato calibrato per accentuare visivamente l''assurdità comica della scena.', 'Intervista alla costumista Mayes C. Rubeo su The Hollywood Reporter', TRUE, 'IA (Daily Sync)', 'IA Verificata', 0, 3, '2026-11-02T11:22:34.825254+00:00'),
('d7fd2cac-fce2-4e7f-9a95-f5f7fcf19fcb', 292, 'Curiosità & Retroscena', 'La satira dei 31 saluti nazisti a ripetizione', 'Nella celebre scena dell''ispezione della Gestapo a casa di Jojo, la formula di saluto ''Heil Hitler'' viene pronunciata convulsamente per ben 31 volte nell''arco di circa due minuti. Taika Waititi ha spiegato di aver orchestrato questa sequenza ripetitiva per esasperare al massimo la burocrazia cerimoniale e il ridicolo conformismo del regime nazista.', 'Commento audio del regista Taika Waititi nell''edizione Home Video', TRUE, 'IA (Daily Sync)', 'IA Verificata', 0, 4, '2026-11-02T11:22:34.825254+00:00'),
('787cbb8e-a6ea-49c3-a9fc-7f24e16d09a7', 292, 'Citazioni & Easter Egg', 'Il simbolismo queer nella divisa da battaglia di Klenzendorf', 'Nella battaglia finale, il capitano Klenzendorf (Sam Rockwell) indossa una sgargiante uniforme creata da lui stesso, dotata di mantello, spalline decorate e due vistosi triangoli rosa sul petto. Il triangolo rosa era il contrassegno imposto nei campi di concentramento agli omosessuali, confermando visivamente la relazione tra Klenzendorf e il suo vice Finkel (Alfie Allen).', 'Intervista al production designer Ra Vincent per IndieWire', TRUE, 'IA (Daily Sync)', 'IA Verificata', 0, 5, '2026-11-02T11:22:34.825254+00:00'),
('940119f7-55ef-4997-98d7-83e3d5b50406', 292, 'Curiosità & Retroscena', 'La chiusura liberatoria con ''Helden'' di David Bowie', 'La sequenza finale di ballo si chiude sulle note di ''Helden'', la rara versione in lingua tedesca del brano ''Heroes'' incisa da David Bowie a Berlino Ovest nel 1977. Waititi ha insistito per ottenerne i diritti musicali, ritenendo che il testo e l''energia rock del brano rappresentassero il riscatto emotivo e il ritorno alla vita dopo gli orrori della guerra.', 'Intervista a Taika Waititi per Entertainment Weekly', TRUE, 'IA (Daily Sync)', 'IA Verificata', 0, 6, '2026-11-02T11:22:34.825254+00:00'),
('835008b0-a33e-4c39-b05c-f450cfb25c20', 292, 'Curiosità & Retroscena', 'Il primato storico di Taika Waititi agli Academy Awards', 'Grazie a questo film, Taika Waititi è entrato nella storia dell''Academy diventando la prima persona di discendenza indigena Māori a vincere l''Oscar per la Miglior sceneggiatura non originale. Durante il discorso di ringraziamento, il regista ha dedicato il premio a tutti i bambini indigeni del mondo che desiderano fare arte.', 'Archivio ufficiale degli Academy Awards (Oscar 2020)', TRUE, 'IA (Daily Sync)', 'IA Verificata', 0, 7, '2026-11-02T11:22:34.825254+00:00'),
('358f8a19-1423-4b65-bef8-a328354a6c6b', 210, 'Casting & Scelte', 'La genesi del personaggio di Dru', 'L''idea di introdurre un fratello gemello per Gru, di nome Dru, nacque per esplorare nuove dinamiche familiari e mettere in discussione l''identità di Gru come cattivo pentito. La chioma bionda e fluente di Dru fu progettata appositamente come netto contrasto visivo rispetto all''aspetto calvo e spigoloso del fratello.', 'Commento audio del regista Pierre Coffin e Kyle Balda', TRUE, 'IA (Daily Sync)', 'IA Verificata', 0, 1, '2026-11-02T14:46:34.413093+00:00'),
('dce8d02e-29b7-417e-924d-54fd525113ce', 210, 'Aneddoti dal set', 'Il doppiaggio dei Minions da parte di Pierre Coffin', 'Il co-regista Pierre Coffin ha continuato a doppiare personalmente centinaia di Minions nel film, utilizzando un mix di parole inventate, idiomi reali presi da diverse lingue del mondo (incluso l''italiano, lo spagnolo e l''indonesiano) e alterazioni vocali in studio per mantenere l''inconfondibile timbro comico.', 'Special feature ''The Making of Despicable Me 3''', TRUE, 'IA (Daily Sync)', 'IA Verificata', 0, 2, '2026-11-02T14:46:34.413093+00:00'),
('f7a3d440-1063-4e16-b634-81e6eb8a57b9', 210, 'Curiosità & Retroscena', 'L''assenza dei Minions nella trama principale', 'Per la prima volta nella storia del franchise, gli scen Cinco Paul e Ken Daurio decisero di separare nettamente i Minions da Gru per gran parte del film, confinandoli in una sottotrama carceraria che culmina con la loro fuga, per dare maggiore spazio alla dinamica tra Gru e il nuovo arrivato Dru.', 'Intervista agli sceneggiatori per Animation Magazine', TRUE, 'IA (Daily Sync)', 'IA Verificata', 0, 3, '2026-11-02T14:46:34.413093+00:00'),
('1fc0212b-33f5-4ef8-bb7a-ee7dbb389d44', 210, 'Citazioni & Easter Egg', 'Il tributo a Charlie Chaplin e Buster Keaton', 'Le sequenze di slapstick che vedono protagonisti i Minions durante la loro permanenza in prigione e il successivo talent show contengono numerosi omaggi visivi alla comicità fisica del cinema muto, in particolare alle gag di Charlie Chaplin e Buster Keaton studiate dagli animatori.', 'Art of Despicable Me 3 - Book', TRUE, 'IA (Daily Sync)', 'IA Verificata', 0, 4, '2026-11-02T14:46:34.413093+00:00'),
('dff87d3f-8982-4f01-9c77-9ca96c47158a', 219, 'Segreti di produzione', 'La costruzione degli imponenti set a Villa Pacelli', 'Per ricostruire la Roma neroniana con un realismo mai visto prima, la produzione affittò un vasto terreno a Villa Pacelli sulla via Appia, dove vennero edificate scenografie monumentali in gesso e legno che riproducono fedelmente templi e vie dell''antichità.', 'Archivio storico della Cines e memorie di Enrico Guazzoni', TRUE, 'IA (Daily Sync)', 'IA Verificata', 0, 0, '2026-11-02T14:46:44.562644+00:00'),
('cb1ccfe1-e82e-45d5-9efe-085269dc07ae', 219, 'Casting & Scelte', 'La scelta di Bruto Castellani per Ursus', 'Il colossale Bruto Castellani fu fortemente voluto da Enrico Guazzoni per la sua straordinaria imponenza fisica, capace di incarnare perfettamente la forza erculea e la dedizione assoluta del fedele Ursus senza l''ausilio di controfigure.', 'Dizionario del Cinema Italiano - Gli attori', TRUE, 'IA (Daily Sync)', 'IA Verificata', 0, 1, '2026-11-02T14:46:44.562644+00:00'),
('900b6396-4922-4f49-bc75-56133be7e3ad', 211, 'Casting & Scelte', 'Il ritorno di Julie Andrews nei panni di Marlena', 'La leggendaria attrice Julie Andrews è tornata a prestare la voce a Marlena Gru, la madre trascurata e poco affettuosa del protagonista, un ruolo che aveva già ricoperto in Cattivissimo Me 3. La produzione ha sfruttato la sua disponibilità per approfondire la complessa dinamica familiare del giovane Gru negli anni ''75.', 'Note di produzione ufficiali Illumination Entertainment', TRUE, 'IA (Daily Sync)', 'IA Verificata', 0, 1, '2026-11-02T14:46:38.460369+00:00'),
('92b91336-bb08-4e97-af04-768868268e18', 211, 'Casting & Scelte', 'La scelta di Alan Arkin per Wild Knuckles', 'Per il ruolo del mentore invecchiato e tradito Wild Knuckles (Mano de Acero), il regista Kyle Balda e il produttore Chris Meledandri hanno scelto il veterano premio Oscar Alan Arkin, la cui voce roca e ruvida ha conferito al personaggio il perfetto timbro da leggenda decaduta del crimine.', 'Intervista ufficiale al cast e note di produzione', TRUE, 'IA (Daily Sync)', 'IA Verificata', 0, 2, '2026-11-02T14:46:38.460369+00:00'),
('50d6dbe7-2748-4102-962f-40eae6c3594c', 129, 'Casting & Scelte', 'Il rifiuto del ruolo di Deborah da parte di Karen Allen', 'Prima che la parte di Deborah venisse affidata a Elizabeth McGovern, Sergio Leone aveva offerto il ruolo da co-protagonista a Karen Allen, reduce dal successo di ''I predatori dell''arca perduta''. L''attrice dovette tuttavia rifiutare l''offerta a causa di conflitti di programmazione con altri progetti.', 'Archivi storici di casting e biografie del regista', TRUE, 'IA (Daily Sync)', 'IA Verificata', 0, 1, '2026-11-02T10:04:37.173431+00:00'),
('a8054799-eb38-401e-a0e3-dfa84f3b1c54', 129, 'Segreti di produzione', 'La censura della sequenza del furgone postale', 'Per la brutale sequenza della rapina al furgone postale nei sobborghi, la produzione dovette costruire appositamente un veicolo blindato d''epoca perfettamente funzionante e conforme alle rigide normative di sicurezza stradale vigenti in Canada, dove furono girate alcune esterne.', 'Bollettini di produzione e registri della troupe', TRUE, 'IA (Daily Sync)', 'IA Verificata', 0, 2, '2026-11-02T10:04:37.173431+00:00'),
('4dbfa261-fa91-444c-9cb7-2a7de40cc628', 129, 'Curiosità & Retroscena', 'L''ispirazione letteraria dal romanzo di Harry Grey', 'Il soggetto del film è tratto dal romanzo autobiografico ''The Hoods'', scritto da Harry Grey (pseudonimo dell''ex gangster Meyer Goldberg). Sergio Leone rimase così affascinato dal libro da inseguire i diritti d''autore per oltre dodici anni prima di riuscire ad avviare la produzione.', 'Interviste storiche a Sergio Leone', TRUE, 'IA (Daily Sync)', 'IA Verificata', 0, 3, '2026-11-02T10:04:37.173431+00:00'),
('b0ad89ac-3100-4bd8-8ac8-7aef4ef11fc9', 211, 'Segreti di produzione', 'La fusione tra Kung Fu e animazione slapstick', 'Per le sequenze di arti marziali che vedono protagonista il personaggio di Master Chow (doppiata da Michelle Yeoh), gli animatori della Illumination Mac Guff hanno studiato i classici del cinema di kung fu degli anni ''70 e i film di Bruce Lee, integrandoli con le tradizionali gag slapstick dei Minions.', 'Featurette ''The Making of Minions: The Rise of Gru''', TRUE, 'IA (Daily Sync)', 'IA Verificata', 0, 4, '2026-11-02T14:46:38.460369+00:00'),
('05073902-8835-4a46-b6ea-f5b9a567ff49', 211, 'Casting & Scelte', 'Il debutto vocale del piccolo Otto', 'Il personaggio di Otto, il nuovo Minion paffuto e con l''apparecchio per i denti che perde la preziosa pietra dello zodiaco, è stato doppiato da Frank Welker, storico doppiatore e leggenda degli effetti vocali di Hollywood, che ha ideato la sua caratteristica parlata e i versi unici.', 'Crediti ufficiali del film e interviste di produzione', TRUE, 'IA (Daily Sync)', 'IA Verificata', 0, 5, '2026-11-02T14:46:38.460369+00:00'),
('c470d506-df41-4912-a33f-421d22c6761f', 229, 'Casting & Scelte', 'Il debutto in un blockbuster per Scarlett Johansson', 'Prima di diventare una star internazionale e un''icona del Marvel Cinematic Universe, una giovanissima Scarlett Johansson ha ottenuto la parte di Molly Pruitt, la sorella maggiore del protagonista Alex, attraverso i tradizionali provini cinematografici a New York.', 'Note di produzione ufficiali 20th Century Fox', TRUE, 'IA (Daily Sync)', 'IA Verificata', 0, 0, '2026-11-02T14:46:54.748161+00:00'),
('3778bfc9-2e80-41e6-8e5d-0f871937330b', 229, 'Casting & Scelte', 'La transizione alla regia di Raja Gosnell', 'Il film segna il debutto alla regia cinematografica di Raja Gosnell, che in precedenza aveva lavorato come montatore professionista per importanti pellicole, tra cui i primi due capitoli della saga diretti da Chris Columbus.', 'Press kit ufficiale del film', TRUE, 'IA (Daily Sync)', 'IA Verificata', 0, 1, '2026-11-02T14:46:54.748161+00:00'),
('8d019200-f740-4475-8b95-b57eb7c24b56', 229, 'Aneddoti dal set', 'Le riprese principali a Chicago', 'Nonostante la storia sia ambientata a Chicago proprio come i primi due film, gran parte delle riprese esterne e delle sequenze d''azione con l''auto radiocomandata si sono svolte in realtà a Evanston, nell''Illinois, e in altre zone limitrofe della contea di Cook.', 'Archivio storico della Chicago Film Office', TRUE, 'IA (Daily Sync)', 'IA Verificata', 0, 2, '2026-11-02T14:46:54.748161+00:00'),
('e13eed46-903b-457a-bac5-2fd9c46dd91a', 229, 'Segreti di produzione', 'Il design dell''auto radiocomandata e le doppie versioni', 'Per girare le complesse acrobazie dell''auto con il microchip militare nascosto, la produzione ha dovuto costruire diversi modelli specializzati, inclusi esemplari rinforzati per gli impatti e versioni radiocomandate da professionisti fuori campo.', 'Documentario dietro le quinte ''The Making of Home Alone 3''', TRUE, 'IA (Daily Sync)', 'IA Verificata', 0, 3, '2026-11-02T14:46:54.748161+00:00'),
('380233e6-8621-497f-b964-18f8aa1d988f', 342, 'Casting & Scelte', 'La drastica trasformazione fisica di Adrien Brody', 'Per impersonare Wladyslaw Szpilman, Adrien Brody perse ben 14 chili in poche settimane seguendo una dieta ferrea e punitiva. L''attore vendette inoltre la sua auto e il suo appartamento a New York, isolandosi completamente per sei settimane prima delle riprese per sperimentare la solitudine e la fame.', 'Intervista ufficiale di Adrien Brody per il DVD del film', TRUE, 'IA (Daily Sync)', 'IA Verificata', 0, 0, '2026-11-02T14:51:26.512664+00:00'),
('f6af422e-478c-41fd-9f9a-9c7114c8dfdb', 342, 'Curiosità & Retroscena', 'Il rifiuto del set di Spielberg', 'A Roman Polanski fu originariamente offerto di dirigere ''Schindler''s List'' negli anni ''90, ma rifiutò il progetto perché il dolore legato al suo vissuto personale nel ghetto di Cracovia era ancora troppo vivo. Anni dopo decise invece di dirigere ''Il pianista'' proprio per elaborare quei ricordi d''infanzia.', 'Autobiografia di Roman Polanski e note di regia', TRUE, 'IA (Daily Sync)', 'IA Verificata', 0, 1, '2026-11-02T14:51:26.512664+00:00'),
('88a3576f-1118-4abf-961c-22d69c9238ca', 342, 'Aneddoti dal set', 'L''infortunio alla mano nascosto dalla regia', 'Durante le riprese, Adrien Brody si ruppe accidentalmente una mano sbattendola contro un muro in una scena di tensione. Polanski e la troupe dovettero riorganizzare temporaneamente il piano di lavorazione e le inquadrature per non mostrare l''infortunio, mentre Brody continuava a suonare il pianoforte fingendo che nulla fosse.', 'Making-of ufficiale ''A Story of Survival''', TRUE, 'IA (Daily Sync)', 'IA Verificata', 0, 2, '2026-11-02T14:51:26.512664+00:00'),
('7b56af68-018e-48ac-a8f2-d1291865e003', 342, 'Segreti di produzione', 'La ricostruzione della Varsavia distrutta a Babelsberg', 'Gran parte della Varsavia distrutta non è stata girata in Polonia, ma nei celebri studi cinematografici Babelsberg vicino a Berlino. La produzione ha ricostruito isolati interi di edifici in rovina su un terreno che in precedenza ospitava una caserma militare dell''Armata Rossa.', 'Reportage di produzione e note scenografiche di Allan Starski', TRUE, 'IA (Daily Sync)', 'IA Verificata', 0, 3, '2026-11-02T14:51:26.512664+00:00'),
('75b59b10-646f-49f8-9fa1-7ab1dae2b2f0', 212, 'Casting & Scelte', 'Il debutto di Will Ferrell nel franchise', 'Will Ferrell è stato ingaggiato per doppiare il supercriminale Maxime Le Mal, segnando la sua prima partecipazione principale nel franchise di Cattivissimo Me dopo aver lavorato in numerosi altri film d''animazione di successo. L''attore ha registrato gran parte dei suoi dialoghi in sessioni remote coordinate dal regista Chris Renaud.', 'Note di produzione ufficiali Illumination Entertainment', TRUE, 'IA (Daily Sync)', 'IA Verificata', 0, 0, '2026-11-02T14:46:41.329304+00:00'),
('91ca6d3d-4b1a-4e35-b155-e9cfc7520dd4', 212, 'Casting & Scelte', 'Il ritorno di Pierre Coffin per i Minions', 'Pierre Coffin, co-regista dei capitoli precedenti, è tornato a doppiare l''iconico e incomprensibile linguaggio dei Minions, prestando la voce a decine di migliaia di variazioni sonore per i piccoli aiutanti gialli, confermando la sua unicità nel mantenere intatta la comicità slapstick del gruppo.', 'Press Kit ufficiale Universal Pictures', TRUE, 'IA (Daily Sync)', 'IA Verificata', 0, 1, '2026-11-02T14:46:41.329304+00:00'),
('12d2b473-7636-4d7c-81b1-bc06891b5666', 212, 'Segreti di produzione', 'L''introduzione della tecnologia Mega Minions', 'Gli sceneggiatori Ken Daurio e Mike White hanno introdotto la variante dei ''Mega Minions'' ispirandosi esplicitamente ai classici tropi dei supereroi dei fumetti anni ''60, dotando cinque specifici Minions di superpoteri parodia dei Fantastici Quattro e di Superman.', 'Intervista agli sceneggiatori su Animation Magazine', TRUE, 'IA (Daily Sync)', 'IA Verificata', 0, 2, '2026-11-02T14:46:41.329304+00:00'),
('14bbe7a2-f6ee-4b4a-89ba-597faa7cc419', 212, 'Citazioni & Easter Egg', 'I riferimenti alla continuity della AVL', 'All''interno del quartier generale della Anti-Villain League (AVL), gli animatori hanno inserito numerosi oggetti di scena e gadget provenienti dai film precedenti, inclusi i veicoli modificati visti in Cattivissimo Me 2 e 3, per premiare i fan di lungo corso con dettagli nascosti.', 'Official Visual Companion del film', TRUE, 'IA (Daily Sync)', 'IA Verificata', 0, 3, '2026-11-02T14:46:41.329304+00:00'),
('66fd3363-441b-4732-b637-3452e56a85b6', 276, 'Curiosità & Retroscena', 'Il remake italiano di un successo transalpino', 'Il film è l''adattamento ufficiale della commedia francese ''Les Profs'' (2013), a sua volta basata sull''omonima serie a fumetti di Pica e Erroc, mantenendo l''idea di fondo dei peggiori professori per i peggiori studenti ma italianizzandone la satira scolastica.', 'Note di produzione ufficiali Wild Bunch e Good Films', TRUE, 'IA (Daily Sync)', 'IA Verificata', 0, 0, '2026-11-02T14:47:40.239035+00:00'),
('37ba3d56-597e-489b-b533-7450f8b956ed', 276, 'Casting & Scelte', 'La genesi del cast con Bisio e Guanciale', 'Claudio Bisio è stato scelto immediatamente per interpretare il preside del liceo Manzoni, affiancato da Lino Guanciale nel ruolo di un professore eccentrico, segnando un''inedita e fortunata accoppiata comica sul grande schermo.', 'Conferenza stampa di presentazione del film', TRUE, 'IA (Daily Sync)', 'IA Verificata', 0, 1, '2026-11-02T14:47:40.239035+00:00'),
('fec8e4a5-e8f2-43a5-9453-02ef2417a6d0', 276, 'Casting & Scelte', 'L''inserimento di Maurizio Nichetti tra i docenti', 'La produzione ha fortemente voluto Maurizio Nichetti nel cast dei bizzarri insegnanti, un omaggio alla grande tradizione della commedia d''autore e del cinema slapstick italiano di cui Nichetti è maestro riconosciuto.', 'Intervista al regista Ivan Silvestrini', TRUE, 'IA (Daily Sync)', 'IA Verificata', 0, 2, '2026-11-02T14:47:40.239035+00:00'),
('e9810ab2-766d-4299-8116-135a341be5f6', 276, 'Aneddoti dal set', 'L''atmosfera da fumetto sul set', 'Per richiamare visivamente le origini cartacee dell''opera francese, il regista Ivan Silvestrini ha incoraggiato gli attori a utilizzare una recitazione sopra le righe, fortemente caricaturale, per simulare la dinamica delle vignette stampate.', 'Making-of ufficiale dal set del film', TRUE, 'IA (Daily Sync)', 'IA Verificata', 0, 3, '2026-11-02T14:47:40.239035+00:00'),
('d36fbea9-7a6f-4431-b3e7-cb060d49362c', 342, 'Casting & Scelte', 'La scelta musicale di Janusz Olejniczak', 'Sebbene Adrien Brody avesse imparato a suonare il pianoforte per le scene in cui le sue mani sono inquadrate in primo piano, i brani di Chopin ascoltati nel film sono stati interamente eseguiti dal celebre pianista polacco Janusz Olejniczak.', 'Crediti ufficiali del film e intervista a Janusz Olejniczak', TRUE, 'IA (Daily Sync)', 'IA Verificata', 0, 4, '2026-11-02T14:51:26.512664+00:00'),
('eeb93536-6012-4bc6-b8c9-6a3077c2675a', 342, 'Citazioni & Easter Egg', 'Il cameo mancato e la connessione autobiografica', 'Il padre di Roman Polanski, Ryszard Polanski, riuscì a sopravvivere all''Olocausto in Polonia nascondendosi sotto falso nome. Molti dettagli visivi della vita nel ghetto e dei nascondigli nel film derivano direttamente dai racconti che il padre fece al regista durante la sua infanzia.', 'Documentario ''Roman Polanski: Odd Man Out''', TRUE, 'IA (Daily Sync)', 'IA Verificata', 0, 5, '2026-11-02T14:51:26.512664+00:00'),
('83779a27-dc8d-4f7a-9a5d-f330967214ac', 348, 'Casting & Scelte', 'La telefonata di Tom Cruise a Cameron Crowe', 'Fu lo stesso Tom Cruise a chiamare Cameron Crowe dopo aver visto l''originale ''Abre los ojos'', proponendogli non solo di produrre il remake con la sua Cruise/Wagner Productions, ma offrendogli anche la regia del progetto.', 'Commento audio del DVD di Cameron Crowe e Tom Cruise', TRUE, 'IA (Daily Sync)', 'IA Verificata', 0, 0, '2026-11-02T14:51:39.232885+00:00'),
('193c88b5-5d78-4a2e-a44a-126f4f6d969c', 348, 'Curiosità & Retroscena', 'La scelta della colonna sonora e il brano dei Radiohead', 'Il brano ''Talk Show Host'' dei Radiohead fu inserito nella sequenza della festa e scelto personalmente da Cameron Crowe per dare il giusto tono malinconico e alienante alla scena dell''incontro tra David e Sofia.', 'Note di produzione e tracklist ufficiale della colonna sonora', TRUE, 'IA (Daily Sync)', 'IA Verificata', 0, 1, '2026-11-02T14:51:39.232885+00:00'),
('cce608a6-7128-43d4-84ec-00090299fe2b', 348, 'Casting & Scelte', 'Il rifiuto del ruolo di Sofia da parte di altre star', 'Prima che Cameron Crowe sceglisse di mantenere Penélope Cruz nel ruolo che aveva già interpretato nel film di Amenábar, la produzione valutò diverse attrici di altissimo profilo a Hollywood per la parte di Sofia, tra cui Cameron Diaz prima che venisse poi riassegnata al personaggio di Julie.', 'Report di casting di Variety del 2000', TRUE, 'IA (Daily Sync)', 'IA Verificata', 0, 2, '2026-11-02T14:51:39.232885+00:00'),
('412a09ca-9b27-448a-90a9-473d8ed915bd', 348, 'Citazioni & Easter Egg', 'L''ispirazione visiva da Orson Welles', 'Cameron Crowe ha inserito numerosi omaggi visivi a ''Quarto potere'' (Citizen Kane) di Orson Welles, in particolare nella costruzione della sequenza iniziale e nella rappresentazione dell''immenso impero editoriale ereditato da David Aames.', 'Analisi visiva e interviste al regista nei contenuti speciali', TRUE, 'IA (Daily Sync)', 'IA Verificata', 0, 3, '2026-11-02T14:51:39.232885+00:00'),
('247626b2-fd2a-44a7-846c-123de74b8d3a', 348, 'Citazioni & Easter Egg', 'Il cameo di Robert Risk', 'Nel film compare in un piccolo ruolo anche l''attore e musicista Bob Dylan, omaggiato non solo nel poster ma anche attraverso la presenza di figure della scena musicale indipendente americana fortemente volute da Crowe.', 'Crediti ufficiali del film', TRUE, 'IA (Daily Sync)', 'IA Verificata', 0, 4, '2026-11-02T14:51:39.232885+00:00'),
('976e5fe2-4ea5-4a4c-8fc7-c33493dcc914', 348, 'Segreti di produzione', 'Le difficoltà legali per i dipinti di Monet', 'Per inserire le vere opere d''arte di artisti del calibro di Claude Monet e Jean-Michel Basquiat nell''appartamento di David, la produzione ha dovuto negoziare rigorosi permessi e utilizzare riproduzioni autorizzate di altissima qualità supervisionate da curatori museali.', 'Dietro le quinte del reparto scenografia', TRUE, 'IA (Daily Sync)', 'IA Verificata', 0, 5, '2026-11-02T14:51:39.232885+00:00'),
('53e7f28d-60a6-455c-845f-860f1a06f423', 348, 'Aneddoti dal set', 'La trasformazione della villa di Ryan Phillippe', 'Le scene della lussuosa festa iniziale di David Aames sono state girate in una residenza privata a Los Angeles precedentemente appartenuta a diverse celebrità, adattando gli spazi interni per ospitare oltre duecento comparse e troupe.', 'Production notes ufficiali della Paramount Pictures', TRUE, 'IA (Daily Sync)', 'IA Verificata', 0, 6, '2026-11-02T14:51:39.232885+00:00'),
('f535ae28-178e-480f-bb34-37a3d648714d', 219, 'Effetti speciali & Trucco', 'L''uso pionieristico delle comparse di massa', 'Enrico Guazzoni impiegò per la prima volta nel cinema italiano migliaia di comparse contemporaneamente sulla scena, coordinandole con precisione militare per le sequenze del circo massimo e delle persecuzioni cristiane.', 'Studi sulla storia del kolossal muto italiano', TRUE, 'IA (Daily Sync)', 'IA Verificata', 0, 2, '2026-11-02T14:46:44.562644+00:00'),
('bda79189-91c4-4b69-bbad-46f84c440e89', 219, 'Curiosità & Retroscena', 'Il trionfo internazionale e la proiezione a Londra', 'Il film ottenne un successo clamoroso oltre i confini italiani, venendo proiettato al Royal Albert Hall di Londra con un accompagnamento orchestrale dal vivo appositamente composto, stabilendo un nuovo standard per l''esportazione del cinema europeo.', 'The Bioscope - Cronache cinematografiche britanniche del 1913', TRUE, 'IA (Daily Sync)', 'IA Verificata', 0, 3, '2026-11-02T14:46:44.562644+00:00'),
('c857928b-8b16-4ef5-8efd-50abe80b38f7', 295, 'Curiosità & Retroscena', 'La consulenza del team ''Cultural Trust''', 'Per evitare stereotipi e rispettare profondamente la cultura messicana, Pixar ha istituito un apposito ''Cultural Trust'' composto da artisti e attivisti locali, tra cui l''autore Víctor Chávez e la fumettista Lalo Alcaraz, consultati regolarmente durante l''intero arco produttivo.', 'Note di produzione ufficiali Pixar', TRUE, 'IA (Daily Sync)', 'IA Verificata', 0, 0, '2026-11-02T14:47:58.990567+00:00'),
('e5f2d88d-76d9-4aa8-b2b0-bacce71fd159', 295, 'Segreti di produzione', 'La chitarra reale di Ernesto de la Cruz', 'Il liutaio professionista Harlan Hodge è stato ingaggiato per costruire una versione fisica reale della complessa chitarra a forma di teschio di Ernesto de la Cruz, utilizzata dagli animatori come riferimento visivo tangibile per catturare i riflessi della luce.', 'Art of Coco - The Making of the film', TRUE, 'IA (Daily Sync)', 'IA Verificata', 0, 1, '2026-11-02T14:47:58.990567+00:00'),
('4b13a6ce-60d2-4a27-9d5b-4d24f809072a', 295, 'Citazioni & Easter Egg', 'Le vere origini di Pepita', 'I colorati alebrijes come Pepita traggono ispirazione dalle sculture di carta pesta create dagli artigiani messicani Pedro e Lina Linares; nel film, il design di Pepita unisce tratti di giaguaro, aquila e ariete per rappresentare una guida spirituale regale.', 'Commento audio del regista Lee Unkrich', TRUE, 'IA (Daily Sync)', 'IA Verificata', 0, 2, '2026-11-02T14:47:58.990567+00:00'),
('2634f6d0-0776-4721-8b18-5bcdfc652a52', 295, 'Curiosità & Retroscena', 'L''ispirazione per Santa Cecilia', 'Il villaggio natale di Miguel, Santa Cecilia, è stato modellato visivamente sulle città coloniali reali di Guanajuato e Pátzcuaro, celebri per le loro stradine acciottolate e le facciate delle case dipinte con tonalità vivaci.', 'Documentario ''Welcome to Santa Cecilia''', TRUE, 'IA (Daily Sync)', 'IA Verificata', 0, 3, '2026-11-02T14:47:58.990567+00:00'),
('fa590585-1aa4-42d5-b8ff-b6ef7f7812d2', 295, 'Citazioni & Easter Egg', 'Il cameo della bambola Woody', 'Durante la sequenza in cui Miguel cammina per le strade affollate della Terra dei Morti, si può intravedere brevemente tra le bancarelle un''effigie di Woody tratto da ''Toy Story'' in versione scheletrica.', 'Easter Egg ufficiale Pixar Animation Studios', TRUE, 'IA (Daily Sync)', 'IA Verificata', 0, 4, '2026-11-02T14:47:58.990567+00:00'),
('9051004f-1470-463a-a5fd-ed06ccdeafd2', 346, 'Casting & Scelte', 'La scelta iniziale di William Hurt', 'Prima che la parte del detective William Somerset fosse affidata a Morgan Freeman, la produzione aveva offerto il ruolo a William Hurt, il quale declinò l''offerta, aprendo così la strada all''iconica interpretazione di Freeman.', 'Note di produzione ufficiali e commento audio del regista', TRUE, 'IA (Daily Sync)', 'IA Verificata', 0, 0, '2026-11-02T14:51:34.791438+00:00'),
('cfb6bfb8-c8d9-4112-837b-d114e58c005f', 346, 'Curiosità & Retroscena', 'La riscrittura del finale di Andrew Kevin Walker', 'Lo sceneggiatore Andrew Kevin Walker scrisse la sceneggiatura originale inserendo già il tragico epilogo con la scatola, ispirandosi al clima cupo e pessimistico della New York dei primi anni ''90 e ai romanzi noir.', 'Intervista retrospettiva ad Andrew Kevin Walker', TRUE, 'IA (Daily Sync)', 'IA Verificata', 0, 1, '2026-11-02T14:51:34.791438+00:00'),
('9d010aba-de24-4d5a-9d47-63651b1ea82f', 346, 'Segreti di produzione', 'La luce di Darius Khondji', 'Il direttore della fotografia Darius Khondji utilizzò un processo di stampa chimica chiamato Silver Retention (Bleach Bypass) per dare alla pellicola quell''aspetto visivo estremamente granuloso, desaturato e dai contrasti duri.', 'American Cinematographer Magazine', TRUE, 'IA (Daily Sync)', 'IA Verificata', 0, 2, '2026-11-02T14:51:34.791438+00:00'),
('c1154eb0-afd5-410a-99fd-4811b4a989f2', 346, 'Citazioni & Easter Egg', 'L''ispirazione letteraria di Somerset', 'Tra i testi che il detective Somerset consulta nella biblioteca della città figurano trattati storici e filosofici reali, tra cui la Divina Commedia di Dante e i saggi del marchese de Sade, per riflettere la natura enciclopedica della mente del killer.', 'Analisi visiva e di scenografia del film', TRUE, 'IA (Daily Sync)', 'IA Verificata', 0, 3, '2026-11-02T14:51:34.791438+00:00'),
('8a7945eb-d105-43cd-8980-105f9ee22b60', 346, 'Aneddoti dal set', 'La performance improvvisata di R. Lee Ermey', 'L''attore R. Lee Ermey, celebre per il suo ruolo in Full Metal Jacket, interpretò il capitano di polizia aggiungendo sfumature e battute ciniche non strettamente presenti nel copione originale, basandosi sulla sua esperienza precedente.', 'Speciali backstage del DVD', TRUE, 'IA (Daily Sync)', 'IA Verificata', 0, 4, '2026-11-02T14:51:34.791438+00:00'),
('73f57f6c-abcc-4550-af62-9a5d978f6940', 346, 'Casting & Scelte', 'Il cameo vocale di Leland Orser', 'L''attore Leland Orser, che interpreta l''uomo terrorizzato legato al letto nel motel per il peccato della Lussuria, dovette iperventilare intensamente e urlare per ore prima di girare la scena per ottenere quella voce rauca e disperata.', 'Making-of ufficiale di Seven', TRUE, 'IA (Daily Sync)', 'IA Verificata', 0, 5, '2026-11-02T14:51:34.791438+00:00'),
('7dd155bd-a59f-4f1b-b0dc-8d08def1a376', 346, 'Curiosità & Retroscena', 'La scelta del nome John Doe', 'Il nome fittizio usato dall''assassino, John Doe, è la classica denominazione legale statunitense per i cadaveri non identificati o per imputati anonimi, scelta per sottolineare l''efferatezza e l''universalità della sua missione nichilista.', 'Note di sceneggiatura e analisi critica', TRUE, 'IA (Daily Sync)', 'IA Verificata', 0, 7, '2026-11-02T14:51:34.791438+00:00'),
('bb5ee4ec-fa88-4f52-8893-f6659e4d07f3', 349, 'Curiosità & Retroscena', 'La consulenza di veri veterani di guerra', 'Per garantire l''accuratezza storica degli eventi del 7 dicembre 1941, la produzione ha ingaggiato diversi veterani sopravvissuti all''attacco di Pearl Harbor come consulenti sul set, tra cui il pilota Ken Taylor e il marinaio Joe George.', 'Documentario sul making-of del DVD ufficiale di Pearl Harbor', TRUE, 'IA (Daily Sync)', 'IA Verificata', 0, 0, '2026-11-02T14:51:44.152303+00:00'),
('b0994782-687a-4dcd-aa47-388fb60c06e6', 349, 'Casting & Scelte', 'Il rifiuto di Gwyneth Paltrow', 'Prima che il ruolo dell''infermiera Evelyn Johnson fosse assegnato a Kate Beckinsale, l''attrice Gwyneth Paltrow era stata fortemente considerata dalla produzione, ma rifiutò la parte per poter recitare nel film drammatico ''The Anniversary Party''.', 'Report di casting di Hollywood Reporter del 2000', TRUE, 'IA (Daily Sync)', 'IA Verificata', 0, 1, '2026-11-02T14:51:44.152303+00:00'),
('5328e2ef-52ba-4f1c-b7b8-41e1d70a68ad', 349, 'Aneddoti dal set', 'L''addestramento militare rigoroso', 'Ben Affleck, Josh Hartnett e gli altri attori che interpretavano i piloti dovettero sottoporsi a un addestramento militare intensivo di due settimane presso un campo d''addestramento dei Marine in California per apprendere la postura, la disciplina e i movimenti corretti.', 'Note di produzione ufficiali Touchstone Pictures', TRUE, 'IA (Daily Sync)', 'IA Verificata', 0, 2, '2026-11-02T14:51:44.152303+00:00'),
('a324c608-b0fa-4910-b7ea-e1c3ded9b2b2', 259, 'Casting & Scelte', 'La scelta naturale di Timothée Chalamet', 'Il regista Paul King ha offerto la parte di Willy Wonka a Timothée Chalamet senza alcun provino formale, dopo essere rimasto folgorato da alcuni video scolastici del liceo in cui l''attore cantava e rappava, pubblicati su YouTube.', 'Intervista ufficiale di Paul King a Rolling Stone', TRUE, 'IA (Daily Sync)', 'IA Verificata', 0, 0, '2026-11-02T14:47:08.662008+00:00'),
('06c08974-20ba-42e4-8255-4c07c9ced6a2', 259, 'Casting & Scelte', 'La genesi dell''Oompa Loompa di Hugh Grant', 'Paul King ha fortemente voluto Hugh Grant per il ruolo di Lofty l''Oompa Loompa pensando al libro originale di Roald Dahl, in cui questi personaggi hanno la pelle verde e i capelli bianchi, e trovando perfetta la natura caustica e sarcastica dell''attore britannico per interpretare la creatura.', 'Note di produzione ufficiali Warner Bros.', TRUE, 'IA (Daily Sync)', 'IA Verificata', 0, 1, '2026-11-02T14:47:08.662008+00:00'),
('3f9bb010-87ac-4747-a6a2-a0a2d18de14a', 259, 'Retroscena dal set', 'Il vero cioccolato sul set', 'Per garantire il massimo realismo e deliziare il cast, la produzione ha ingaggiato una cioccolatiera professionista, di nome Elizabeth Wrigley, che ha creato chili e chili di vero cioccolato commestibile e bevande al cioccolato utilizzate durante le riprese.', 'Dietro le quinte ufficiale del film', TRUE, 'IA (Daily Sync)', 'IA Verificata', 0, 2, '2026-11-02T14:47:08.662008+00:00'),
('b9048778-1824-4b14-8d21-4036784cca4d', 259, 'Effetti speciali & Trucco', 'Il tormento tecnologico di Hugh Grant', 'Per interpretare l''Oompa Loompa, Hugh Grant ha dovuto indossare uno scomodo visore per il motion capture e una cuffia con telecamere puntate sul viso, un''esperienza che l''attore ha definito ''orribile'' e frustrante poiché non amava recitare con l''attrezzatura tecnica addosso.', 'Intervista stampa di Hugh Grant per il press tour del film', TRUE, 'IA (Daily Sync)', 'IA Verificata', 0, 3, '2026-11-02T14:47:08.662008+00:00'),
('a044c3a8-919c-4586-8b75-54b9a7d9f061', 259, 'Citazioni & Easter Egg', 'L''omaggio musicale a Gene Wilder', 'Nel film è presente un chiaro omaggio musicale al film del 1971 ''Willy Wonka e la fabbrica di cioccolato'': la canzone ''Pure Imagination'' viene ripresa in momenti chiave della colonna sonora per creare un ponte emotivo diretto con l''interpretazione classica di Gene Wilder.', 'Analisi della colonna sonora ufficiale e note del compositore Joby Talbot', TRUE, 'IA (Daily Sync)', 'IA Verificata', 0, 4, '2026-11-02T14:47:08.662008+00:00'),
('bc7105ec-e698-42b1-a939-573af02d6f79', 259, 'Retroscena dal set', 'La dieta rigorosa di Timothée Chalamet', 'Nonostante le tonnellate di dolci presenti sul set, Timothée Chalamet ha rivelato di aver dovuto seguire una dieta ferrea e un intenso allenamento cardio a causa delle continue e faticose coreografie di ballo richieste dal regista Paul King.', 'Intervista a Timothée Chalamet nel talk show di Graham Norton', TRUE, 'IA (Daily Sync)', 'IA Verificata', 0, 5, '2026-11-02T14:47:08.662008+00:00'),
('a6d8b861-e1d8-4c71-8e22-dd3255f0e7f0', 259, 'Segreti di produzione', 'La costruzione delle scenografie a grandezza naturale', 'Lo scenografo Nathan Crowley ha scelto di costruire enormi set fisici reali a Lyme Regis e ai Warner Bros. Studios di Leavesden piuttosto che affidarsi totalmente al green screen, per ricreare l''atmosfera nostalgica e fiabesca della vecchia Europa.', 'Featurette di produzione e design del film', TRUE, 'IA (Daily Sync)', 'IA Verificata', 0, 6, '2026-11-02T14:47:08.662008+00:00'),
('fc351c74-2f06-46c8-b28e-01fe4d6bcf43', 259, 'Curiosità & Retroscena', 'Le coreografie ispirate a Fred Astaire', 'Il coreografo Christopher Gatelli ha strutturato i numeri musicali di Timothée Chalamet traendo forte ispirazione dai classici musical della MGM e dai movimenti eleganti e leggiadri di Fred Astaire e Gene Kelly.', 'Dietro le quinte ufficiale sulla realizzazione delle danze', TRUE, 'IA (Daily Sync)', 'IA Verificata', 0, 7, '2026-11-02T14:47:08.662008+00:00'),
('ecfe4e1e-166d-4f01-9b4c-9a3d1d4e5fa9', 271, 'Curiosità & Retroscena', 'La genesi del titolo e il legame con il tour teatrale', 'Il titolo del film riprende direttamente il nome dello spettacolo teatrale di grande successo ''Così è la vita'' che il trio Aldo, Giovanni e Giacomo portava in giro per l''Italia in quegli stessi anni, consolidando la transizione dal palcoscenico al grande schermo dopo il debutto con ''Tre uomini e una gamba''.', 'Note di produzione ufficiali Medusa Film', TRUE, 'IA (Daily Sync)', 'IA Verificata', 0, 0, '2026-11-02T14:47:32.961878+00:00'),
('d28ec6e8-7093-4338-adf9-3c67e6380881', 271, 'Segreti di produzione', 'La scelta delle location montane in Abruzzo', 'Nonostante la sceneggiatura preveda un viaggio che tocca diverse zone d''Italia partendo da Milano, gran parte delle celebri sequenze in montagna e nei boschi sono state girate realmente tra i paesaggi aspri e suggestivi del Parco Nazionale d''Abruzzo.', 'Backstage ufficiale e crediti di lavorazione del film', TRUE, 'IA (Daily Sync)', 'IA Verificata', 0, 1, '2026-11-02T14:47:32.961878+00:00'),
('f3c5dcca-a97a-49f2-928b-d057ba938ad2', 271, 'Casting & Scelte', 'L''evoluzione del sodalizio con Marina Massironi', 'Marina Massironi, dopo il trionfo corale e sentimentale in ''Tre uomini e una gamba'', viene confermata come co-protagonista femminile nel ruolo di Elisa, consolidando la sua presenza imprescindibile nel cinema del trio in quella fase aurea.', 'Archivio storico del casting cinematografico italiano', TRUE, 'IA (Daily Sync)', 'IA Verificata', 0, 2, '2026-11-02T14:47:32.961878+00:00'),
('4f544a63-63cd-4161-a6fa-935fadc8825c', 271, 'Casting & Scelte', 'L''ispirazione visiva per il personaggio di Aldo', 'Il look eccentrico e i capelli lunghi di Aldo nel film furono ideati per accentuare il suo status di falsificatore ''super partes'', ispirandosi liberamente a figure iconiche della malavita cinematografica anni ''70 ma rielaborate in chiave farsesca.', 'Commento audio del DVD ufficiale e note di regia', TRUE, 'IA (Daily Sync)', 'IA Verificata', 0, 3, '2026-11-02T14:47:32.961878+00:00'),
('2fea14dd-5b2a-4c79-9536-e3084369b144', 271, 'Aneddoti dal set', 'La sequenza della fuga in auto e le riprese notturne', 'Molte delle scene di guida notturna a Milano furono girate realmente per le strade cittadine con blocchi stradali autorizzati, generando non pochi disagi ai residenti che scambiavano Aldo, Giovanni e Giacomo per veri criminali in fuga.', 'Intervista d''archivio a Massimo Venier e troupe', TRUE, 'IA (Daily Sync)', 'IA Verificata', 0, 4, '2026-11-02T14:47:32.961878+00:00'),
('7edc9eae-2934-445b-b910-643854361bd8', 271, 'Casting & Scelte', 'Il cameo vocale di Francesco Pannofino', 'Francesco Pannofino, oltre a interpretare il commissario di polizia nel film, prestò la sua inconfondibile voce per alcuni raddoppi in presa quasi diretta e per battute aggiuntive registrate in post-produzione per potenziare la verve comica dei battibecchi con il trio.', 'Crediti di produzione e backstage cinematografico', TRUE, 'IA (Daily Sync)', 'IA Verificata', 0, 5, '2026-11-02T14:47:32.961878+00:00'),
('4734d56d-cb81-46a4-8683-92493d82904e', 286, 'Segreti di produzione', 'La censura della tazza del water', 'Psyco detiene il primato storico di essere stato il primo film nella storia del cinema americano a mostrare chiaramente lo scarico di una tazza del water sul grande schermo. I censori del Production Code dell''epoca si opposero strenuamente, ma Alfred Hitchcock insistette per mantenere la scena in cui Marion getta i pezzi di carta straccia, vincendo la battaglia.', 'Note di produzione della censura MPAA e biografie storiche su Hitchcock', TRUE, 'IA (Daily Sync)', 'IA Verificata', 0, 0, '2026-11-02T14:47:47.52999+00:00'),
('1d756026-2ad6-4fa8-b567-c887a22e2ea0', 286, 'Casting & Scelte', 'Il rifiuto iniziale della Paramount Pictures', 'I dirigenti della Paramount Pictures disprezzarono apertamente il progetto, definendolo ripugnante e inadatto a un regista del calibro di Alfred Hitchcock dopo il successo di ''Intrigo internazionale''. Rifiutarono di finanziare il film con il budget standard, costringendo Hitchcock a produrlo in proprio attraverso la sua casa di produzione Shamley Productions e a finanziarlo tasca propria.', 'Archivi storici della Paramount Pictures e corrispondenza di Hitchcock', TRUE, 'IA (Daily Sync)', 'IA Verificata', 0, 1, '2026-11-02T14:47:47.52999+00:00'),
('d9040c9b-bfa1-4d31-88bf-cf6401bd8de8', 260, 'Casting & Scelte', 'La preparazione fisica intensiva di Bob Odenkirk', 'Nonostante fosse noto principalmente per ruoli comici e drammatici come Saul Goodman in ''Better Call Saul'', Bob Odenkirk si è sottoposto a due anni di rigoroso allenamento di arti marziali e pugilato sotto la guida del coordinatore degli stunt Daniel Bernhardt prima di girare le scene d''azione.', 'Intervista ufficiale di Bob Odenkirk per Collider', TRUE, 'IA (Daily Sync)', 'IA Verificata', 0, 0, '2026-11-02T14:47:13.311768+00:00');
INSERT INTO public.movie_trivia ("id", "film_id", "categoria", "titolo", "descrizione", "fonte", "approvato", "inserito_da", "provenienza", "likes", "ordine", "created_at") VALUES
('9aa8be97-bdc8-4c2f-a212-63cf0a2487c5', 260, 'Curiosità & Retroscena', 'Il legame con il franchise di John Wick', 'Il film è stato scritto da Derek Kolstad, lo stesso sceneggiatore creatore di ''John Wick'', e originariamente concepito per esistere nello stesso universo narrativo, condividendo lo stesso approccio cinico e coreografato alla violenza urbana.', 'Note di produzione e interviste a Derek Kolstad', TRUE, 'IA (Daily Sync)', 'IA Verificata', 0, 1, '2026-11-02T14:47:13.311768+00:00'),
('10981465-17a0-4f58-92ac-4edce27d59fc', 260, 'Aneddoti dal set', 'L''infortunio alla mano durante la lotta sull''autobus', 'Durante la celebre e brutale sequenza di combattimento all''interno del bus, Bob Odenkirk si è fratturato le costole e ha subito vari tagli, ma ha insistito per continuare a girare le riprese senza ricorrere a controfigure per i campi medi.', 'Featurette ''Making of Nobody'' e commento audio del regista', TRUE, 'IA (Daily Sync)', 'IA Verificata', 0, 2, '2026-11-02T14:47:13.311768+00:00'),
('d310d9ee-bdef-41b4-8d6e-e999826c647b', 260, 'Casting & Scelte', 'Il coinvolgimento di Christopher Lloyd', 'L''iconico attore Christopher Lloyd, celebre per ''Ritorno al futuro'', ha accettato immediatamente il ruolo del padre anziano ex agente governativo David Mansell, dichiarando di essere entusiasta di poter interpretare un personaggio così fisicamente attivo e armato in età avanzata.', 'Note stampa ufficiali Universal Pictures', TRUE, 'IA (Daily Sync)', 'IA Verificata', 0, 3, '2026-11-02T14:47:13.311768+00:00'),
('3fd044c0-c0a6-4f61-9915-0c6ff3a75b8b', 260, 'Curiosità & Retroscena', 'L''ispirazione per il personaggio di Yulian Kuznetsov', 'Il cattivo principale, il boss russo interpretato da Aleksey Serebryakov, è stato modellato sui classici antagonisti dei film d''azione degli anni ''80, unendo la spietatezza criminale a una raffinata passione per il canto e i club di Mosca.', 'Intervista al regista Ilya Naishuller', TRUE, 'IA (Daily Sync)', 'IA Verificata', 0, 4, '2026-11-02T14:47:13.311768+00:00'),
('b6371873-b2f4-49d6-9ccc-6df990895876', 260, 'Segreti di produzione', 'La scelta della colonna sonora sovietica', 'Il regista Ilya Naishuller ha voluto inserire personalmente brani della tradizione musicale russa e sovietica, inclusa la canzone ''Blestyashchiye'' e classici interpretati da Muslim Magomayev, per creare un contrasto straniante con le sequenze d''azione ambientate negli Stati Uniti.', 'Note di regia e intervista su Billboard', TRUE, 'IA (Daily Sync)', 'IA Verificata', 0, 5, '2026-11-02T14:47:13.311768+00:00'),
('a26993ec-5487-42ab-8b4a-27254c2d83af', 260, 'Citazioni & Easter Egg', 'Il cameo vocale e le origini russe della troupe', 'Molti membri della troupe tecnica e degli stuntmen provenivano dal team russo con cui Naishuller aveva già lavorato nel suo film d''esordio ''Hardcore!'', inserendo diversi piccoli omaggi nascosti alla cultura russa nei dettagli delle scenografie.', 'Dietro le quinte ufficiale del film', TRUE, 'IA (Daily Sync)', 'IA Verificata', 0, 6, '2026-11-02T14:47:13.311768+00:00'),
('7c01962f-991c-46ee-aa70-0d3caa49e21c', 272, 'Curiosità & Retroscena', 'L''ispirazione teatrale reale del Cyrano', 'Il progetto di mettere in scena il Cyrano de Bergerac all''interno del film riflette la vera gavetta teatrale del trio Aldo, Giovanni e Giacomo, che prima del grande successo televisivo e cinematografico avevano lavorato a lungo sui palcoscenici di cabaret e teatro comico con compagnie storiche come il Teatro dell''Elfo.', 'Autobiografia e interviste retrospettive del trio', TRUE, 'IA (Daily Sync)', 'IA Verificata', 0, 0, '2026-11-02T14:47:36.138284+00:00'),
('cc5f223c-2e94-46bb-a195-d7c47f403140', 272, 'Casting & Scelte', 'La genesi del sodalizio con Marina Massironi', 'Marina Massironi, che nel film interpreta Silvana, era all''epoca sentimentalmente legata a Giacomo Poretti e faceva parte del sodalizio artistico fin dai tempi del cabaret milanese dello Zelig e degli spettacoli teatrali come ''Galline vecchie fan buon brodo''.', 'Note di produzione e pressbook ufficiale Medusa Film', TRUE, 'IA (Daily Sync)', 'IA Verificata', 0, 1, '2026-11-02T14:47:36.138284+00:00'),
('02af53fe-063f-45bf-a57f-e6af2dca38a9', 272, 'Aneddoti dal set', 'Le riprese nei luoghi simbolo di Milano', 'Molte delle sequenze urbane del film sono state girate in autentici luoghi simbolo di Milano, tra cui la zona dei Navigli e il Teatro alla Scala, dove Giovanni gira la scena iniziale come comparsa nell''opera lirica, sfruttando veri spazi istituzionali e comparse professioniste del teatro.', 'Diario di bordo e Making-of contenuto nel DVD ufficiale', TRUE, 'IA (Daily Sync)', 'IA Verificata', 0, 2, '2026-11-02T14:47:36.138284+00:00'),
('f8db5723-0cf0-42fe-a53c-20d31f9aa131', 272, 'Casting & Scelte', 'Il cameo di Silvana Fallisi', 'Silvana Fallisi, moglie di Aldo Baglio nella vita reale, ha ottenuto una parte di rilievo nella pellicola consolidando la tradizione del trio di coinvolgere i propri familiari e storici collaboratori del laboratorio comico nei loro progetti cinematografici.', 'Credits ufficiali e interviste promozionali del film', TRUE, 'IA (Daily Sync)', 'IA Verificata', 0, 3, '2026-11-02T14:47:36.138284+00:00'),
('c9bcc917-5844-40b9-bfa8-d45c92546d77', 349, 'Curiosità & Retroscena', 'Il cambio di titolo iniziale', 'Nelle prime fasi di sviluppo e durante la stesura iniziale della sceneggiatura scritta da Randall Wallace, il progetto cinematografico era noto con il titolo provvisorio di ''Tennessee'', prima di essere ribattezzato definitivamente ''Pearl Harbor''.', 'Archivio di sceneggiatura della Writers Guild of America', TRUE, 'IA (Daily Sync)', 'IA Verificata', 0, 3, '2026-11-02T14:51:44.152303+00:00'),
('f695c24d-eb9e-48d8-b717-52c80b5b0a3e', 349, 'Segreti di produzione', 'L''uso di modellini in scala combinati con l''acqua', 'Il supervisore degli effetti speciali Eric Brevig utilizzò enormi modellini in scala di navi da guerra posizionati all''interno di una piscina appositamente costruita a Rosarito, in Messico, combinandoli con miniature di aerei per le riprese dei siluramenti.', 'Intervista tecnica a Eric Brevig su American Cinematographer', TRUE, 'IA (Daily Sync)', 'IA Verificata', 0, 4, '2026-11-02T14:51:44.152303+00:00'),
('ba111b74-971e-45cb-a0b3-f9dfed3c507c', 349, 'Effetti speciali & Trucco', 'La cicatrice reale di Josh Hartnett', 'Durante una scena d''azione, l''attore Josh Hartnett subì un piccolo taglio al volto che la troupe e il reparto trucco decisero di integrare temporaneamente nel trucco di scena del suo personaggio, Danny Walker, per alcune sequenze successive.', 'Diario di bordo della produzione di Pearl Harbor', TRUE, 'IA (Daily Sync)', 'IA Verificata', 0, 5, '2026-11-02T14:51:44.152303+00:00'),
('064839f3-1ffc-4b74-883d-d93a3e803fbb', 349, 'Curiosità & Retroscena', 'La composizione della colonna sonora di Hans Zimmer', 'Il celebre compositore Hans Zimmer ha dovuto riscrivere alcune parti della colonna sonora principale poche settimane prima dell''uscita del film nelle sale, a causa dei continui tagli operati dal montatore sul ritmo delle sequenze belliche.', 'Intervista a Hans Zimmer per Soundtrack.net', TRUE, 'IA (Daily Sync)', 'IA Verificata', 0, 6, '2026-11-02T14:51:44.152303+00:00'),
('40af2a03-0651-44ad-9195-7bc60e7545c1', 351, 'Aneddoti dal set', 'L''infortunio sul set di Robbie Coltrane', 'Durante le riprese, l''attore Robbie Coltrane, che interpreta il sergente Peter Godley, subì un infortunio al ginocchio che costrinse la produzione a modificare temporaneamente i piani di ripresa, inserendo inquadrature che limitassero i suoi movimenti.', 'Note di produzione ufficiali del DVD', TRUE, 'IA (Daily Sync)', 'IA Verificata', 0, 0, '2026-11-02T14:51:54.930238+00:00'),
('fa12e449-8d6d-46fc-abef-8fdd155548f4', 269, 'Citazioni & Easter Egg', 'Omaggio a Fantozzi e alla commedia classica', 'Diverse gag visive e la struttura stessa del viaggio in macchina rappresentano un omaggio dichiarato ai road movie americani e alla comicità surreale della premiata ditta Villaggio-Salce, in particolare per la gestione dei tempi comici legati alle sfortune dei protagonisti.', 'Analisi critica della commedia italiana degli anni ''90', TRUE, 'IA (Daily Sync)', 'IA Verificata', 0, 6, '2026-11-02T14:47:26.682469+00:00'),
('43bbc598-1d73-4f61-89d8-93148fc976f7', 350, 'Casting & Scelte', 'Il rifiuto originale di Ann Miller', 'La leggendaria attrice di Hollywood Ann Miller, che nel film interpreta la padrona di casa Coco Lenoire, inizialmente rifiutò il ruolo offerto da David Lynch perché riteneva che la sceneggiatura fosse troppo oscura e incomprensibile. Fu convinta ad accettare solo dopo che il regista le spiegò personalmente la visione d''insieme del personaggio.', 'Intervista retrospettiva a David Lynch inclusa nei contenuti speciali del DVD', TRUE, 'IA (Daily Sync)', 'IA Verificata', 0, 0, '2026-11-02T14:51:51.40784+00:00'),
('c532f26f-cb3b-481d-baa1-29b98d11c42b', 350, 'Aneddoti dal set', 'La scena del provino di Justin Theroux', 'Durante la sequenza in cui il regista Adam Kesher (Justin Theroux) distrugge i vetri dell''auto dei produttori con una mazza da golf, David Lynch chiese all''attore di colpire realmente la vettura con tutta la forza possibile. La reazione di rabbia e frustrazione di Theroux sul set è del tutto autentica ed estratta da un unico ciak particolarmente violento.', 'Note di produzione e making-of ufficiale ''On the Road to Mulholland Drive''', TRUE, 'IA (Daily Sync)', 'IA Verificata', 0, 1, '2026-11-02T14:51:51.40784+00:00'),
('bff4faeb-65e1-40a4-9ec9-9b2cdf6dbd53', 350, 'Curiosità & Retroscena', 'L''improvvisazione della scena della masturbazione', 'La complessa e intensa sequenza in cui Betty scopre se stessa sul divano fu girata da Naomi Watts affidandosi quasi interamente all''istinto, con David Lynch che le sussurrava indicazioni emotive contrastanti tra l''innocenza e il risveglio sensuale. L''attrice ha dichiarato di aver dovuto attingere a profonde insicurezze personali per rendere credibile la vulnerabilità del personaggio.', 'Intervista a Naomi Watts per la rivista Film Comment', TRUE, 'IA (Daily Sync)', 'IA Verificata', 0, 2, '2026-11-02T14:51:51.40784+00:00'),
('094ec8b6-4b21-4cab-94ac-942e2a05a789', 350, 'Casting & Scelte', 'Il cameo di Billy Ray Cyrus', 'Il celebre cantante di musica country Billy Ray Cyrus appare brevemente nel film nei panni di Gene, l''amante del personaggio interpretato da Dan Hedaya. La sua partecipazione fu fortemente voluta da David Lynch, il quale era rimasto colpito dalla sua presenza scenica e cercava un volto immediatamente riconoscibile ma estraneo al circuito del cinema d''autore.', 'Credits ufficiali del film e registri di casting di Mulholland Drive', TRUE, 'IA (Daily Sync)', 'IA Verificata', 0, 3, '2026-11-02T14:51:51.40784+00:00'),
('8f87ffcd-b856-43f4-9c48-eba679caa828', 350, 'Segreti di produzione', 'L''uso della musica in presa diretta al Club Silencio', 'Per la toccante interpretazione del brano ''Llorando'' cantato da Rebekah Del Rio al Club Silencio, David Lynch decise di far riprodurre la voce registrata in studio ma chiese all''artista di modulare l''esibizione con un playback così perfetto e commosso da ingannare la percezione visiva del pubblico e degli attori presenti in sala.', 'Intervista a Rebekah Del Rio e note sonore del montaggio', TRUE, 'IA (Daily Sync)', 'IA Verificata', 0, 4, '2026-11-02T14:51:51.40784+00:00'),
('64eaf3f3-354e-4df4-9353-6b8d71422b04', 350, 'Segreti di produzione', 'Il montaggio del pilot televisivo trasformato in lungometraggio', 'Quando la ABC bloccò la serie TV, il materiale girato durava circa 90 minuti e possedeva una narrazione tronca. Per trasformarlo in un lungometraggio cinematografico, David Lynch ricevette un finanziamento di sette milioni di dollari dalla società francese StudioCanal, girando nuove scene a Los Angeles nel corso del 2000 per dare una conclusione surreale e circolare alla storia.', 'Documentario ''The Making of Mulholland Drive'' e comunicati stampa StudioCanal', TRUE, 'IA (Daily Sync)', 'IA Verificata', 0, 5, '2026-11-02T14:51:51.40784+00:00'),
('c2440f88-2816-467c-96b1-a9fe21272b6e', 350, 'Citazioni & Easter Egg', 'La scelta del nome Camilla Rhodes', 'Il personaggio di Camilla Rhodes prende il nome da un anagramma parziale e da un omaggio alla tradizione letteraria dei gialli classici, unendo suggestioni che richiamano le atmosfere di Raymond Chandler e i misteri legati a Hollywood. David Lynch inserì deliberatamente questo nome per confondere lo spettatore sulla vera identità delle protagoniste.', 'Analisi critico-cinematografica supervisionata dal co-produttore Neal Edelstein', TRUE, 'IA (Daily Sync)', 'IA Verificata', 0, 6, '2026-11-02T14:51:51.40784+00:00'),
('1fd39f11-5950-41a6-b347-1b26a41187ab', 350, 'Aneddoti dal set', 'Il malfunzionamento della parrucca di Laura Harring', 'Durante le riprese della scena in cui Rita indossa una parrucca bionda per travestirsi ed evitare di essere riconosciuta, la parrucca continuava a scivolare a causa del caldo umido dei teatri di posa di Los Angeles. David Lynch decise di mantenere questa sottile imperfezione visiva nel montaggio finale, ritenendo che aumentasse il senso di finzione e fragilità dell''identità del personaggio.', 'Commento audio del supervisore al montaggio Mary Sweeney', TRUE, 'IA (Daily Sync)', 'IA Verificata', 0, 7, '2026-11-02T14:51:51.40784+00:00'),
('84a50bf0-4198-4105-baae-ea635c8b0fd5', 350, 'Citazioni & Easter Egg', 'L''omaggio al film Viale del tramonto', 'L''inquadratura iniziale della limousine che percorre le curve notturne di Mulholland Drive è un diretto omaggio visivo alle sequenze d''apertura dei classici noir degli anni ''50 ambientati a Hollywood, in particolare a ''Viale del tramonto'' (Sunset Boulevard) di Billy Wilder, citato esplicitamente anche attraverso la struttura e la scelta dei toponimi.', 'Note di regia e recensioni storiche del festival di Cannes 2001', TRUE, 'IA (Daily Sync)', 'IA Verificata', 0, 8, '2026-11-02T14:51:51.40784+00:00'),
('53b9ae16-aefd-4e37-81b7-89e204bcfc56', 350, 'Segreti di produzione', 'Il set ricreato dopo la cancellazione della serie', 'Poiché gran parte delle scenografie originali del pilot televisivo erano state smantellate dopo il rifiuto della ABC, la troupe dovette ricostruire in studio quasi identici gli interni degli appartamenti e il corridoio dell''albergo mesi dopo, creando lievi discrepanze visive che accentuano l''atmosfera onirica della seconda parte del film.', 'Reportage di produzione della rivista American Cinematographer', TRUE, 'IA (Daily Sync)', 'IA Verificata', 0, 9, '2026-11-02T14:51:51.40784+00:00'),
('07d265b7-20a4-450c-a41c-78b7597d0515', 352, 'Curiosità & Retroscena', 'La nomination agli Oscar e il successo inatteso', 'Il film ottenne cinque nomination agli Oscar, tra cui Miglior Film e Miglior Attrice Protagonista per Juliette Binoche, un traguardo notevole per una pellicola sentimentale di stampo europeo distribuita da una major hollywoodiana come Miramax.', 'Archivio ufficiale Academy Awards e note di produzione Miramax', TRUE, 'IA (Daily Sync)', 'IA Verificata', 0, 0, '2026-11-02T14:52:00.296358+00:00'),
('3f113d3b-413d-4188-b0b8-22cc9101f31b', 352, 'Segreti di produzione', 'La preparazione artigianale del cioccolato', 'Per garantire l''autenticità visiva delle creazioni esposte nella bottega, la produzione si affidò al celebre maître chocolatier e pasticcere francese Norman Love, che creò personalmente tutte le sculture e i dolciumi artistici utilizzati nel film.', 'Making-of ufficiale e note della produzione esecutiva', TRUE, 'IA (Daily Sync)', 'IA Verificata', 0, 1, '2026-11-02T14:52:00.296358+00:00'),
('c32f9731-714f-4f8c-bace-46c937ecb9be', 352, 'Citazioni & Easter Egg', 'Il nome originale del villaggio e la geografia romanzesca', 'Il villaggio fittizio di Lansquenet-sous-Tannes nel romanzo e nel film trae ispirazione geografica dalla regione della Yonne, ma il borgo scelto per le riprese, Flavigny-sur-Ozerain, è celebre nella realtà per la produzione di storiche caramelle all''anice.', 'Guide turistiche ufficiali della Borgogna e note di regia di Lasse Hallström', TRUE, 'IA (Daily Sync)', 'IA Verificata', 0, 2, '2026-11-02T14:52:00.296358+00:00'),
('301aabbb-149b-4606-8f21-4c2ac4483032', 286, 'Curiosità & Retroscena', 'Il contratto di segretezza per il pubblico', 'Per preservare il colpo di scena finale e il destino di Marion Crane, Alfred Hitchcock impose una regola ferrea e inedita: nessuno, nemmeno i critici cinematografici durante le proiezioni stampa, poteva entrare in sala dopo l''inizio del film. Ordinò personalmente ai proprietari dei cinema di blindare le porte all''orario di inizio e fece firmare accordi di non divulgazione.', 'Comunicati stampa originali e linee guida per la distribuzione del 1960', TRUE, 'IA (Daily Sync)', 'IA Verificata', 0, 2, '2026-11-02T14:47:47.52999+00:00'),
('b40b76c0-bf9c-4e03-a12f-764c2052c48b', 286, 'Effetti speciali & Trucco', 'Il cioccolato Bosco come sangue nella doccia', 'Nella celebre sequenza della doccia, il liquido scuro utilizzato per simulare il sangue che scorreva nello scarico non era vernice o vero sangue finto, ma sciroppo di cioccolato della marca Bosco. Poiché il film era in bianco e nero, lo sciroppo offriva la densità visiva e la tonalità cromatica perfette sotto l''illuminazione delle luci di studio.', 'Interviste d''archivio al reparto trucco e make-up della Paramount', TRUE, 'IA (Daily Sync)', 'IA Verificata', 0, 3, '2026-11-02T14:47:47.52999+00:00'),
('3267c257-d8e2-4be1-b9ff-f6a9c2538901', 286, 'Aneddoti dal set', 'L''infortunio di Janet Leigh con la celluloide', 'Durante le estenuanti riprese della scena della doccia, che durarono sette giorni interi sotto un getto d''acqua fredda e calda alternata, Janet Leigh riportò lesioni superficiali e screpolature della pelle dovute alla prolungata esposizione. La troupe dovette riscaldare l''acqua nei giorni successivi per evitare che l''attrice contraesse l''ipotermia.', 'Memorie di Janet Leigh (''Psycho: Behind the Scenes'')', TRUE, 'IA (Daily Sync)', 'IA Verificata', 0, 4, '2026-11-02T14:47:47.52999+00:00'),
('824eed40-43fb-48cd-a8e9-d3b81731e24c', 286, 'Effetti speciali & Trucco', 'L''improvvisazione con i chicchi di mais', 'Per realizzare il suono raccapricciante del cadavere mummificato della signora Bates che viene ruotato bruscamente sulla sedia verso la fine del film, il fonico del suono non utilizzò ossa umane. Sfruttò invece il rumore secco e scricchiolante ottenuto stritolando chicchi di mais essiccati all''interno di una federa per cuscini.', 'Documentario ''The Making of Psycho'' e registri audio di post-produzione', TRUE, 'IA (Daily Sync)', 'IA Verificata', 0, 5, '2026-11-02T14:47:47.52999+00:00'),
('765603cc-18f1-40aa-973a-f06ec2792c12', 286, 'Casting & Scelte', 'La scelta di Anthony Perkins e il salario ridotto', 'Anthony Perkins accettò di interpretare il perturbante Norman Bates accettando un compenso relativamente basso, pari a circa 40.000 dollari, poiché rimase fulminato dalla sceneggiatura e dalla complessità psicologica del personaggio. La sua interpretazione divenne talmente iconica da legarlo indissolubilmente al ruolo per il resto della sua carriera.', 'Contratti di casting originali della Shamley Productions', TRUE, 'IA (Daily Sync)', 'IA Verificata', 0, 6, '2026-11-02T14:47:47.52999+00:00'),
('1ae8eb40-e13b-481b-b5fa-1373f756e49c', 286, 'Curiosità & Retroscena', 'La finta intervista promozionale di Hitchcock', 'Per la campagna promozionale del film, Alfred Hitchcock girò un insolito trailer cinematografico in cui guidava gli spettatori attraverso i luoghi del delitto all''interno del Bates Motel e della casa colonica. Il trailer terminava con una rivelazione shock vicino alla doccia, girato interamente senza attori principali per mantenere intatta la suspens.', 'Trailer cinematografico originale Universal-International del 1960', TRUE, 'IA (Daily Sync)', 'IA Verificata', 0, 7, '2026-11-02T14:47:47.52999+00:00'),
('313f6a4a-f614-4203-b014-9efb964e4a3e', 286, 'Casting & Scelte', 'La morte fittizia di Vera Miles', 'Per confondere la stampa e depistare i fan che si accalcavano fuori dagli studios di Universal, la produzione fece trapelare la falsa notizia che Vera Miles (che interpretava Lila Crane) fosse stata brutalmente uccisa a metà film durante le riprese. Questo stratagemma servì a proteggere la segretezza della struttura narrativa voluta da Hitchcock.', 'Note di produzione e bollettini stampa dell''epoca', TRUE, 'IA (Daily Sync)', 'IA Verificata', 0, 8, '2026-11-02T14:47:47.52999+00:00'),
('a7aad504-4581-4d3b-9a1e-b0fd9a894896', 286, 'Citazioni & Easter Egg', 'L''omaggio al romanzo di Robert Bloch sulla cronaca nera', 'Il romanzo originale di Robert Bloch e la conseguente trasposizione cinematografica traggono ispirazione dai crimini reali del famigerato serial killer del Wisconsin Ed Gein, arrestato nel 1957. Hitchcock e lo sceneggiatore Joseph Stefano incorporarono elementi legati alla profanazione di tombe e al rapporto morboso con la figura materna presenti nel caso di cronaca nera.', 'Archivi biografici di Robert Bloch e note di sceneggiatura di Joseph Stefano', TRUE, 'IA (Daily Sync)', 'IA Verificata', 0, 9, '2026-11-02T14:47:47.52999+00:00'),
('12765dab-d628-4e0d-b443-af1f47687fe7', 351, 'Segreti di produzione', 'Il doppiaggio in post-produzione per l''accento inglese', 'Sebbene Johnny Depp abbia lavorato duramente con un dialettcoach per perfezionare il suo accento britannico dell''epoca, alcune battute furono ridoppiate in studio in post-produzione per garantire la massima intelligibilità del dialogo da parte del pubblico internazionale.', 'Audio commento dei registi Albert e Allen Hughes', TRUE, 'IA (Daily Sync)', 'IA Verificata', 0, 1, '2026-11-02T14:51:54.930238+00:00'),
('0d6413a8-1443-4d64-bca0-59e9b9846a72', 351, 'Curiosità & Retroscena', 'La scelta della colonna sonora orchestrale e industriale', 'Il compositore Trevor Jones ha unito un''orchestra tradizionale a sonorità industrial e percussioni pesanti per sottolineare la follia e la modernità oscura dei delitti nella Londra vittoriana.', 'Note di copertina della colonna sonora ufficiale', TRUE, 'IA (Daily Sync)', 'IA Verificata', 0, 2, '2026-11-02T14:51:54.930238+00:00'),
('2c6b6388-1f8f-467a-9652-0931078e8889', 351, 'Casting & Scelte', 'Le ricerche storiche di Johnny Depp all''archivio Scotland Yard', 'Prima di iniziare le riprese, Johnny Depp si recò personalmente a Londra per consultare i registri storici originali e i rapporti di polizia conservati negli archivi legati ai casi di Jack lo Squartatore.', 'Intervista promozionale a Johnny Depp, 2001', TRUE, 'IA (Daily Sync)', 'IA Verificata', 0, 3, '2026-11-02T14:51:54.930238+00:00'),
('c85cb353-06dc-43c1-9d8f-1655e78fcbc9', 213, 'Aneddoti dal set', 'Il trauma cranico sul set di Tom Holland', 'Tom Holland, che interpreta il giovane mozzo Thomas Nickerson, rischiò un infortunio serio durante le riprese a causa di un''onda artificiale sul set dei Leavesden Studios. Fu travolto da una massa d''acqua mentre era legato a un congegno meccanico, sbattendo violentemente la testa contro una struttura di ferro e riportando una lieve commozione cerebrale.', 'Dietro le quinte e making-of ufficiale nel Blu-ray del film', TRUE, 'IA (Daily Sync)', 'IA Verificata', 0, 1, '2026-11-02T15:47:07.426596+00:00'),
('bc67b100-9b88-416b-8233-e27d04bcaa59', 213, 'Casting & Scelte', 'Il ruolo sfumato di Benedict Cumberbatch', 'Prima che Ron Howard salisse ufficialmente a bordo come regista e che il cast definitivo venisse assemblato, il progetto era stato associato per lungo tempo a diversi registi (come Barry Levinson e successivamente Edward Zwick) e attori. Tra i nomi circolati con insistenza nelle primissime fasi di sviluppo per il ruolo del capitano George Pollard Jr. vi era anche quello di Benedict Cumberbatch, poi non concretizzatosi.', 'Report di Deadline e Variety sulle fasi di pre-produzione del film (2012)', TRUE, 'IA (Daily Sync)', 'IA Verificata', 0, 2, '2026-11-02T15:47:07.426596+00:00'),
('694d8fca-98bb-4718-b1be-cbd5b688256b', 213, 'Segreti di produzione', 'La ricostruzione in scala reale della baleniera Essex', 'La produzione ha fatto costruire una replica in scala reale della baleniera Essex, posizionata su enormi giunti cardanici idraulici in grado di simulare con precisione chirurgica il beccheggio e il rollio delle onde oceaniche. Questo ha permesso agli attori di muoversi su un ponte autenticamente instabile, sebbene circondato dai green screen degli studi Warner Bros.', 'Note di produzione ufficiali della Warner Bros. Pictures', TRUE, 'IA (Daily Sync)', 'IA Verificata', 0, 3, '2026-11-02T15:47:07.426596+00:00'),
('95b29549-d1e1-4863-af5b-8dab3d7cac4e', 296, 'Curiosità & Retroscena', 'La censura evitata per un soffio dalla MPAA', 'Il film ha rischiato seriamente di ricevere un severo divieto ai minori (NC-17) a causa della combinazione di violenza e dei dialoghi spinti, in particolare nella sequenza della festa nella villa. Shane Black e il montatore Joel Negron hanno dovuto tagliare e rielaborare diverse inquadrature per ottenere il visto censura R-rated senza compromettere il tono irriverente della pellicola.', 'Intervista al regista Shane Black per Collider', TRUE, 'IA (Daily Sync)', 'IA Verificata', 0, 0, '2026-11-02T14:48:04.771913+00:00'),
('534ebb2f-ee0e-48c2-951a-7bda06a44d45', 296, 'Curiosità & Retroscena', 'L''ispirazione letteraria di Anthony Bagarozzi e Shane Black', 'Gli sceneggiatori si sono fortemente ispirati ai romanzi pulp di Brett Halliday incentrati sul detective Mike Shayne e ai libri di Robert B. Parker con protagonista Spenser. L''intento dichiarato era ricreare le dinamiche dei romanzi hard-boiled degli anni ''70, dove l''investigatore privato è spesso cinico, al verde e cronicamente nei guai.', 'Note di produzione ufficiali della Warner Bros.', TRUE, 'IA (Daily Sync)', 'IA Verificata', 0, 1, '2026-11-02T14:48:04.771913+00:00'),
('176b5605-63bc-499e-bbcb-124310101124', 296, 'Aneddoti dal set', 'La cicatrice reale di Russell Crowe incorporata nel personaggio', 'Durante le riprese, Russell Crowe si è procurato un infortunio al tendine d''achille che ha richiesto un piccolo intervento chirurgico. Shane Black ha abilmente mascherato la limitazione motoria dell''attore inserendo battute sulla scarsa forma fisica di Jackson Healy e sfruttando la camminata rigida del personaggio.', 'Audio commento del Blu-ray con Shane Black e gli sceneggiatori', TRUE, 'IA (Daily Sync)', 'IA Verificata', 0, 2, '2026-11-02T14:48:04.771913+00:00'),
('262c9835-ab99-4579-8215-6a7e74b2e481', 296, 'Aneddoti dal set', 'L''improvvisazione nella scena del vicolo buio', 'La sequenza in cui Holland March cade rovinosamente attraverso il tetto di vetro di un bagno pubblico mentre scappa dai sicari conteneva molte gag non previste dal copione. Ryan Gosling ha ideato sul momento il modo scomposto in cui grida e impreca, spingendo Russell Crowe a una reazione di autentico sconcerto non tagliata dal montaggio finale.', 'Making-of ufficiale ''Always Nice Guys: The Making of the Film''', TRUE, 'IA (Daily Sync)', 'IA Verificata', 0, 3, '2026-11-02T14:48:04.771913+00:00'),
('8b03fb7c-b94b-4d21-8402-96aebe22efe8', 296, 'Segreti di produzione', 'La scelta della colonna sonora originale a base di funk e soul', 'Il supervisore musicale Dave Jordan e il compositore John Ottman hanno evitato i cliché della disco music anni ''70, optando invece per un sound dominato da linee di basso funk grintose e sezioni fiati ispirate ai thriller blaxploitation dell''epoca. Hanno persino rintracciato strumenti analogici originali del 1977 per registrare la colonna sonora.', 'Intervista al compositore John Ottman per Film Music Magazine', TRUE, 'IA (Daily Sync)', 'IA Verificata', 0, 4, '2026-11-02T14:48:04.771913+00:00'),
('5c1735dc-8bfa-4082-83f5-07e66c6bcf5f', 296, 'Citazioni & Easter Egg', 'Il tributo ai vecchi film polizieschi televisivi', 'Il design del biglietto da visita di Holland March e la grafica dei titoli di testa sono un esplicito omaggio alla serie televisiva cult degli anni ''70 ''Agenzia Rockford'' (The Rockford Files). Shane Black ha ammesso di aver modellato il cinismo e la sfortuna cronica di March proprio sul personaggio di Jim Rockford interpretato da James Garner.', 'Q&A ufficiale con Shane Black al Los Angeles Film Festival', TRUE, 'IA (Daily Sync)', 'IA Verificata', 0, 5, '2026-11-02T14:48:04.771913+00:00'),
('91e7ab40-b4e9-43e8-98ed-163aa9258c2d', 296, 'Effetti speciali & Trucco', 'Le protesi dentarie e i dettagli estetici di Ryan Gosling', 'Per conferire a Holland March l''aspetto dimesso e trasandato di un investigatore di periferia che beve troppo, il reparto trucco ha lavorato a stretto contatto con Ryan Gosling per applicare lievi protesi dentarie che alterassero impercettibilmente la sua dizione durante le battute più comiche.', 'Featurette sul trucco e costumi del Blu-ray', TRUE, 'IA (Daily Sync)', 'IA Verificata', 0, 6, '2026-11-02T14:48:04.771913+00:00'),
('3abb3a3e-5753-437c-8a72-7b34c4a859ec', 352, 'Segreti di produzione', 'La consulenza del cioccolatiere Ernst Knam', 'Per rendere le sculture e le praline autentiche, la produzione ha ingaggiato il noto maître chocolatier Ernst Knam, il quale ha supervisionato personalmente la creazione delle opere d''arte in cacao esposte nella bottega di Vianne.', 'Note di produzione ufficiali Miramax', TRUE, 'IA (Daily Sync)', 'IA Verificata', 0, 3, '2026-11-02T14:52:00.296358+00:00'),
('7d470be9-413c-493d-b90a-f5f53be94d97', 352, 'Casting & Scelte', 'Il training di Juliette Binoche a Parigi', 'Prima delle riprese, Juliette Binoche ha trascorso diverse settimane a Parigi lavorando fianco a fianco con un cioccolatiere professionista per imparare i gesti tecnici corretti del tempersaggio e della manipolazione del cioccolato.', 'Intervista promozionale DVD con Juliette Binoche', TRUE, 'IA (Daily Sync)', 'IA Verificata', 0, 4, '2026-11-02T14:52:00.296358+00:00'),
('0f3397f4-b108-4e2a-856f-d8969e8cc51b', 352, 'Effetti speciali & Trucco', 'I costumi e la palette cromatica dei paesani', 'La costumista Goodman ha utilizzato abiti dai colori spenti e grigiastri per gli abitanti di Lansquenet nella prima parte del film, per poi introdurre tonalità calde e vivaci man mano che il villaggio subisce la liberazione emotiva portata da Vianne.', 'Making-of ufficiale e approfondimento sui costumi', TRUE, 'IA (Daily Sync)', 'IA Verificata', 0, 5, '2026-11-02T14:52:00.296358+00:00'),
('eabc5514-578e-40c9-8194-d66a836eac34', 352, 'Aneddoti dal set', 'Le difficoltà climatiche a Flavigny-sur-Ozerain', 'Nonostante l''ambientazione invernale e fredda richiesta dal copione, la troupe ha dovuto far fronte a temperature insolitamente calde durante i mesi di lavorazione in Borgogna, costringendo la produzione a utilizzare neve artificiale fatta di cellulosa.', 'Reportage dal set della troupe', TRUE, 'IA (Daily Sync)', 'IA Verificata', 0, 6, '2026-11-02T14:52:00.296358+00:00'),
('d222659c-ab0a-4849-8466-3f3a37b74540', 352, 'Citazioni & Easter Egg', 'Il cameo vocale di Joanne Harris', 'La scrittrice Joanne Harris, autrice del romanzo originale da cui è tratto il film, ha fatto una piccola apparizione non accreditata e ha lodato l''adattamento cinematografico curato da Robert Nelson Jacobs per la sceneggiatura.', 'Intervista all''autrice Joanne Harris', TRUE, 'IA (Daily Sync)', 'IA Verificata', 0, 7, '2026-11-02T14:52:00.296358+00:00'),
('f70941dc-cac9-4c2d-81b5-76c308b9a3e3', 213, 'Effetti speciali & Trucco', 'Gli effetti visivi della tempesta e il lavoro della DNeg', 'La complessa sequenza della tempesta che devasta la nave è stata realizzata combinando effetti pratici mastodontici — come tonnellate d''acqua gettate sugli attori e sul set cardanico — con l''esteso lavoro digitale dello studio Double Negative (DNeg). Gli animatori hanno dovuto simulare la fisica dell''acqua salata, la schiuma e la pioggia battente integrandole con i volti emaciati e digitalmente ritoccati degli attori.', 'Articolo tecnico di FXguide sugli effetti visivi di In the Heart of the Sea', TRUE, 'IA (Daily Sync)', 'IA Verificata', 0, 4, '2026-11-02T15:47:07.426596+00:00'),
('1c9a5783-e9a5-4d0c-856b-a5fbd057acf2', 213, 'Citazioni & Easter Egg', 'L''ispirazione visiva tratta da Moby Dick del 1956', 'Anche se l''adattamento cinematografico si basa rigorosamente sul saggio storico di Nathaniel Philbrick e non direttamente sul romanzo di Herman Melville, il regista Ron Howard ha inserito alcuni omaggi visivi e atmosferici al celebre film del 1956 diretto da John Huston, in particolare nella gestione della fotografia dai toni desaturati che richiama il cinema classico d''avventura marittima.', 'Commento audio del regista Ron Howard nell''edizione Home Video', TRUE, 'IA (Daily Sync)', 'IA Verificata', 0, 5, '2026-11-02T15:47:07.426596+00:00'),
('8b7705ef-4a45-4a61-a9ad-d21a859fa6ec', 297, 'Curiosità & Retroscena', 'L''esperienza personale di Taylor Sheridan con la natura selvaggia', 'Taylor Sheridan ha tratto ispirazione per molte dinamiche di sopravvivenza del film dalle sue reali esperienze di vita vissuta nel Wyoming e nel Montana prima di diventare un acclamato sceneggiatore.', 'Note di produzione ufficiali della Weinstein Company', TRUE, 'IA (Daily Sync)', 'IA Verificata', 0, 0, '2026-11-02T14:48:10.301145+00:00'),
('8f1bc2cf-7aba-4595-b6c1-6c855877a837', 297, 'Segreti di produzione', 'Il ritardo nella distribuzione cinematografica', 'Il film ha subito significativi slittamenti nella data di uscita a causa del fallimento della Weinstein Company avvenuto durante la fase di post-produzione e distribuzione iniziale nel 2017.', 'Documentazione stampa e cronaca cinematografica di Variety', TRUE, 'IA (Daily Sync)', 'IA Verificata', 0, 1, '2026-11-02T14:48:10.301145+00:00'),
('f41bf802-01a7-4a43-ad15-e3547e4e00a2', 297, 'Segreti di produzione', 'La scelta del formato di ripresa in widescreen', 'Il direttore della fotografia Ben Richardson ha utilizzato lenti anamorfiche per catturare l''immensità opprimente e isolata dei paesaggi innevati del Wyoming, esaltando il senso di vuoto e pericolo.', 'American Cinematographer, intervista tecnica', TRUE, 'IA (Daily Sync)', 'IA Verificata', 0, 2, '2026-11-02T14:48:10.301145+00:00'),
('efb04c92-bc45-4c22-88df-b9d4c695a543', 297, 'Casting & Scelte', 'L''ispirazione per il personaggio di Cory Lambert', 'Il personaggio interpretato da Jeremy Renner è stato modellato da Taylor Sheridan unendo le caratteristiche di vari veri cacciatori e guide locali che lavorano per il governo federale nelle riserve.', 'Commento audio del regista nel Blu-ray ufficiale', TRUE, 'IA (Daily Sync)', 'IA Verificata', 0, 3, '2026-11-02T14:48:10.301145+00:00'),
('6e5bd1d6-b1ff-4d26-a4e4-08f97c223430', 297, 'Segreti di produzione', 'Il lavoro di ricerca sul campo della costumista', 'La costumista Kari Perkins ha trascorso settimane a studiare l''abbigliamento reale degli abitanti locali e dei lavoratori delle riserve indiane per garantire che ogni giacca, stivale e cappello rispecchiasse l''esatta usura dovuta al clima artico.', 'Backstage featurette e interviste ai reparti tecnici', TRUE, 'IA (Daily Sync)', 'IA Verificata', 0, 4, '2026-11-02T14:48:10.301145+00:00'),
('99b8f013-aa7f-465f-873c-89d8cc5ce569', 297, 'Aneddoti dal set', 'L''accuratezza balistica delle armi', 'Jeremy Renner ha ricevuto una consulenza specifica sull''uso dei fucili a lunga distanza e sulle tecniche di appoggio in condizioni di forte vento e freddo estremo per rendere credibili le sequenze di caccia.', 'Special content del Making-of del film', TRUE, 'IA (Daily Sync)', 'IA Verificata', 0, 5, '2026-11-02T14:48:10.301145+00:00'),
('4c9b9099-c144-4871-ade8-6bc9a0f80b68', 308, 'Casting & Scelte', 'La scelta iniziale per il Dr. Grace Augustine', 'Prima che il ruolo della scienziata Grace Augustine andasse a Sigourney Weaver, James Cameron aveva pensato a un''altra icona del cinema fantascientifico: fu offerto inizialmente a Uma Thurman, ma l''accordo non andò in porto.', 'Report di produzione e casting ufficiali', TRUE, 'IA (Daily Sync)', 'IA Verificata', 0, 0, '2026-11-02T14:48:58.249888+00:00'),
('8075c1b1-18fa-4fac-9fee-37a2810320a5', 308, 'Segreti di produzione', 'Il budget energetico e i server della Weta', 'La mole di dati generata per il rendering di Pandora richiese la costruzione di un impianto apposito presso la Weta Digital in Nuova Zelanda, con server che occupavano un''intera stanza e consumavano enormi quantità di energia elettrica.', 'Documentario ''Capturing Avatar''', TRUE, 'IA (Daily Sync)', 'IA Verificata', 0, 1, '2026-11-02T14:48:58.249888+00:00'),
('5f95d353-1776-46d5-a843-7a89a29d3440', 308, 'Curiosità & Retroscena', 'L''ispirazione per le montagne fluttuanti', 'Le celebri montagne Hallelujah fluttuanti nel cielo di Pandora non sono totalmente frutto di fantasia: James Cameron si è ispirato alle formazioni rocciose dei pilastri di arenaria del Parco Nazionale Forestale di Zhangjiajie in Cina.', 'Note di produzione ufficiali e conferenze stampa', TRUE, 'IA (Daily Sync)', 'IA Verificata', 0, 2, '2026-11-02T14:48:58.249888+00:00'),
('024c4d10-e66b-4463-9a17-08d2aaf6e41f', 308, 'Effetti speciali & Trucco', 'Il sistema di ripresa simultanea live-action', 'La tecnologia sviluppata per il film permetteva a Cameron di vedere sul suo monitor non gli attori in tuta da motion capture, ma i loro avatar in tempo reale all''interno del mondo virtuale generato al computer.', 'Articolo tecnico di American Cinematographer', TRUE, 'IA (Daily Sync)', 'IA Verificata', 0, 3, '2026-11-02T14:48:58.249888+00:00'),
('23432708-37e7-47fd-a90c-45f9157df660', 308, 'Citazioni & Easter Egg', 'Il cameo vocale di James Cameron', 'Il regista James Cameron compare in un piccolo cameo vocale non accreditato all''inizio del film, quando interpreta uno dei tecnici umani che lavorano nella base di Hell''s Gate.', 'Commento audio del regista nel Blu-ray', TRUE, 'IA (Daily Sync)', 'IA Verificata', 0, 4, '2026-11-02T14:48:58.249888+00:00'),
('7d624b0d-ec1b-42a5-a473-fb8125d58617', 308, 'Aneddoti dal set', 'L''addestramento al tiro con l''arco di Zoe Saldaña', 'Per interpretare al meglio la guerriera Neytiri, l''attrice Zoe Saldaña ha dovuto sottoporsi a mesi di allenamento intensivo che comprendevano non solo la danza e le arti marziali, ma anche l''uso professionale del tiro con l''arco tradizionale.', 'Intervista dal set del cast principale', TRUE, 'IA (Daily Sync)', 'IA Verificata', 0, 5, '2026-11-02T14:48:58.249888+00:00'),
('0c68c835-7356-453c-ae18-b51e13bebc0f', 308, 'Curiosità & Retroscena', 'Il colore della pelle dei Na''vi', 'La scelta del caratteristico colore blu per la pelle dei Na''vi fu decisa da James Cameron perché il blu ha una forte risonanza spirituale nei suoi sogni e non era associato a nessun''altra creatura cinematografica o divinità induista che volesse replicare direttamente.', 'Intervista al regista su EW', TRUE, 'IA (Daily Sync)', 'IA Verificata', 0, 6, '2026-11-02T14:48:58.249888+00:00'),
('918ac9f4-16ad-4477-ac62-f60fb5df4fa8', 308, 'Segreti di produzione', 'La consulenza scientifica sulla gravità', 'Per mantenere una certa coerenza scientifica, la produzione ingaggiò fisici ed esperti per calcolare come la gravità inferiore di Pandora rispetto alla Terra avrebbe influenzato i movimenti dei corpi umani e alieni, oltre alla vegetazione.', 'Making-of ufficiale ''The Art of Avatar''', TRUE, 'IA (Daily Sync)', 'IA Verificata', 0, 7, '2026-11-02T14:48:58.249888+00:00'),
('a85adec9-f4f3-4678-b073-6df9f84335a8', 308, 'Effetti speciali & Trucco', 'Il provino con la telecamera facciale', 'Avatar ha segnato il debutto su larga scala del caschetto con telecamera miniaturizzata montata di fronte al viso degli attori, progettato specificamente per catturare ogni singolo movimento microscopico dei muscoli facciali.', 'Documentazione tecnica della Weta Digital', TRUE, 'IA (Daily Sync)', 'IA Verificata', 0, 8, '2026-11-02T14:48:58.249888+00:00'),
('99b0228b-c7f1-47f3-8bd7-3e2fae783f1e', 308, 'Curiosità & Retroscena', 'La vera origine del nome Neytiri', 'Il nome della principessa Na''vi, Neytiri, è stato parzialmente ispirato da una radice linguistica che il creatore della lingua Paul Frommer ha adattato per fonetica e sonorità per renderlo fluido e aggressivo al tempo stesso.', 'Archivio ufficiale della lingua Na''vi', TRUE, 'IA (Daily Sync)', 'IA Verificata', 0, 9, '2026-11-02T14:48:58.249888+00:00'),
('ff23f4d8-4a7a-4f3b-b113-9d0d13b1818a', 353, 'Curiosità & Retroscena', 'L''ispirazione iniziale di Tom Hanks dai dati statistici FedEx', 'L''idea originale del film nacque quando Tom Hanks lesse un articolo che evidenziava come la FedEx trasportasse quotidianamente oltre un milione di pacchi, portandolo a chiedersi cosa sarebbe accaduto se uno di quei voli fosse precipitato in pieno oceano.', 'Commento audio del regista Robert Zemeckis nell''edizione DVD', TRUE, 'IA (Daily Sync)', 'IA Verificata', 0, 0, '2026-11-02T14:52:05.662879+00:00'),
('8c922ca4-d370-45eb-8014-dfd1151778e7', 353, 'Aneddoti dal set', 'L''improvvisazione della battuta su Helen Hunt', 'Durante le riprese della cena di famiglia in cui Chuck Noland torna a casa e saluta i parenti, Tom Hanks improvvisò la battuta in cui chiede se sua moglie Kelly si sia risposata con un dentista, strappando risate genuine alla troupe.', 'Special TV Making of Cast Away - HBO', TRUE, 'IA (Daily Sync)', 'IA Verificata', 0, 1, '2026-11-02T14:52:05.662879+00:00'),
('cbdbcd65-acd2-4277-8f36-76956613ec81', 298, 'Casting & Scelte', 'La collaborazione iniziale con Christian Bale', 'Nelle primissime fasi di sviluppo del progetto, prima ancora che Leonardo DiCaprio si legasse al film, Alejandro G. Iñárritu aveva pensato a Christian Bale per il ruolo del protagonista Hugh Glass. L''attore ha tuttavia dovuto rinunciare a causa di conflitti di programmazione con altri impegni cinematografici.', 'Report di produzione e Hollywood Reporter', TRUE, 'IA (Daily Sync)', 'IA Verificata', 0, 0, '2026-11-02T14:48:14.761225+00:00'),
('06119743-9aed-406c-bd7d-e281d69f7dc6', 298, 'Aneddoti dal set', 'La controversia con la troupe e l''addio del direttore di produzione', 'Le condizioni estreme imposte dal regista e i ritardi accumulati hanno portato a forti tensioni sul set, culminate nell''abbandono o nel licenziamento di diversi membri della troupe, tra cui il celebre produttore esecutivo James J. Skotchdopole, a causa dei metodi di lavoro ritenuti insostenibili.', 'The Hollywood Reporter - In-depth set report', TRUE, 'IA (Daily Sync)', 'IA Verificata', 0, 1, '2026-11-02T14:48:14.761225+00:00'),
('45b49584-c167-4c80-9242-8d31ac81206b', 298, 'Curiosità & Retroscena', 'Il ruolo dei veri indigeni locali', 'Molti dei comparse e degli attori secondari che interpretano i nativi americani nel film appartengono realmente alle tribù locali canadesi e americane, in particolare delle First Nations, coinvolte direttamente dal casting director per assicurare un rispetto culturale assoluto.', 'Note di produzione ufficiali 20th Century Fox', TRUE, 'IA (Daily Sync)', 'IA Verificata', 0, 2, '2026-11-02T14:48:14.761225+00:00'),
('86584ad2-3aac-448c-ae42-539617a4f627', 298, 'Segreti di produzione', 'L''uso della sequenza in piano sequenza per l''attacco', 'La brutale sequenza dell''attacco dell''orso, pur sembrando un unico piano sequenza ininterrotto, è il risultato di un complesso montaggio digitale che unisce diverse riprese effettuate con cineprese Arri Alexa 65 e una complessa controfigura che indossava una tuta per motion capture.', 'American Cinematographer', TRUE, 'IA (Daily Sync)', 'IA Verificata', 0, 3, '2026-11-02T14:48:14.761225+00:00'),
('0e3d36c9-d28c-40c6-aa21-1fe3bbe86d7a', 298, 'Curiosità & Retroscena', 'La genesi del libro di Michael Punke', 'Il film è tratto dall''omonimo romanzo di Michael Punke, pubblicato nel 2002. L''autore, che all''epoca lavorava come avvocato e diplomatico per il governo degli Stati Uniti, ha impiegato anni a documentarsi sulla vera storia di Hugh Glass prima che i diritti venissero acquistati per il grande schermo.', 'Intervista all''autore Michael Punke', TRUE, 'IA (Daily Sync)', 'IA Verificata', 0, 4, '2026-11-02T14:48:14.761225+00:00'),
('f903f6e9-a10c-4230-a5ed-0436027797e5', 298, 'Aneddoti dal set', 'Le riprese in Argentina per la fine del film', 'Poiché l''inverno in Canada terminò bruscamente e la neve si sciolse del tutto prima di completare le ultime sequenze, la produzione fu costretta a trasferire l''intera troupe nell''estremo sud dell''Argentina, a Ushuaia, l''unica altra località al mondo che garantiva la presenza di paesaggi invernali incontaminati in quel periodo dell''anno.', 'Diario di bordo e interviste a Alejandro G. Iñárritu', TRUE, 'IA (Daily Sync)', 'IA Verificata', 0, 5, '2026-11-02T14:48:14.761225+00:00'),
('2c95a207-4b11-4fa7-84c8-8dc07cb7cf9e', 298, 'Aneddoti dal set', 'L''assenza di prove formali prima delle riprese', 'Per mantenere intatta la spontaneità e catturare il disagio reale degli attori, il regista Alejandro G. Iñárritu ha vietato le prove tradizionali in studio prima di girare le scene, preferendo far arrivare gli attori direttamente sul set innevato per reagire istintivamente agli elementi.', 'Making-of ufficiale ''A World Unseen''', TRUE, 'IA (Daily Sync)', 'IA Verificata', 0, 6, '2026-11-02T14:48:14.761225+00:00'),
('9d565677-b6bf-4ea8-aeb8-b9a8b784c859', 319, 'Citazioni & Easter Egg', 'Il cameo non accreditato di Edgar Wright nel supermercato', 'Il regista Edgar Wright appare brevemente nel film nei panni di uno dei clienti del supermercato, precisamente colui che viene spintonato da Nicholas Angel mentre attraversa i corridoi con il carrello.', 'Commento audio del DVD con Edgar Wright e Quentin Tarantino', TRUE, 'IA (Daily Sync)', 'IA Verificata', 0, 0, '2026-11-02T14:49:47.378181+00:00'),
('bf1f6917-1766-4e95-afdf-1da1a466a6de', 319, 'Curiosità & Retroscena', 'La consulenza della vera polizia di Londra', 'Durante le prime fasi di scrittura, Simon Pegg e Edgar Wright hanno affiancato veri ufficiali della Metropolitan Police di Londra per studiare il gergo tecnico, la compilazione dei moduli e le procedure standard d''arresto.', 'Documentario ufficiale ''The Man Who Would Be Fuzz''', TRUE, 'IA (Daily Sync)', 'IA Verificata', 0, 1, '2026-11-02T14:49:47.378181+00:00'),
('06ab5c36-96c5-4723-986f-7e5dc321c998', 319, 'Aneddoti dal set', 'L''infortunio sul set di Nick Frost', 'Durante le riprese della scena della sparatoria finale, Nick Frost si è accidentalmente slogato una caviglia correndo su un terreno sconnesso, costringendo la produzione a modificare temporaneamente le inquadrature per limitare i suoi movimenti.', 'Making-of ufficiale ''You''ve Got Love - The Making of Hot Fuzz''', TRUE, 'IA (Daily Sync)', 'IA Verificata', 0, 2, '2026-11-02T14:49:47.378181+00:00'),
('13e2f850-f236-4fae-a74e-936517d09bbd', 319, 'Casting & Scelte', 'Il vero padre di Edgar Wright in un cameo poliziesco', 'John Wright, il padre del regista, fa una breve apparizione nel film interpretando il sergente della polizia scientifica sulla scena del primo crimine a Sandford.', 'Note di produzione ufficiali della Universal Pictures', TRUE, 'IA (Daily Sync)', 'IA Verificata', 0, 3, '2026-11-02T14:49:47.378181+00:00'),
('075f76e2-7b0e-4272-b4ec-a4ac4a39a764', 319, 'Segreti di produzione', 'Il ritorno sul set della Citroën ZX', 'L''auto scassata guidata da Nick Frost nel film è una Citroën ZX che apparteneva realmente alla famiglia di Edgar Wright ed è stata acquistata dalla produzione appositamente per essere demolita e maltrattata durante le riprese.', 'Intervista al production designer Marcus Rowland', TRUE, 'IA (Daily Sync)', 'IA Verificata', 0, 4, '2026-11-02T14:49:47.378181+00:00'),
('7a40e803-7941-42e7-af2c-88eca50b691d', 319, 'Curiosità & Retroscena', 'Il finto villaggio ideale basato su un vero premio', 'Il concorso ''Villaggio Perfetto'' (The Village of the Year) che fa da sfondo alla trama è ispirato a una competizione reale molto sentita nelle campagne inglesi, a cui Wells e i paesi limitrofi partecipano regolarmente.', 'Curiosità dal commento audio del cast', TRUE, 'IA (Daily Sync)', 'IA Verificata', 0, 5, '2026-11-02T14:49:47.378181+00:00'),
('0fa0b2c6-2535-442a-9c31-3ddaf582995a', 319, 'Effetti speciali & Trucco', 'Le vere armi di gomma per la sequenza d''azione', 'Per ragioni di sicurezza e conformità con le leggi britanniche sulle armi da fuoco nei luoghi pubblici, tutte le pistole e i fucili branditi dai protagonisti nelle scene di massa nel villaggio erano repliche in gomma o fucili ad aria compressa modificati.', 'Featurette ''The Visual Effects of Hot Fuzz''', TRUE, 'IA (Daily Sync)', 'IA Verificata', 0, 6, '2026-11-02T14:49:47.378181+00:00'),
('d7e24d15-9131-4d44-ab9a-7bfc1db24969', 319, 'Citazioni & Easter Egg', 'Il poster di Point Break nella stanza di Danny', 'Nella camera da letto di Danny Butterman si nota chiaramente un poster originale di ''Point Break'' (1991), chiaro indizio della sua ossessione per i film d''azione che guiderà l''evoluzione del personaggio.', 'Analisi visiva e Easter Egg ufficiali del Blu-ray', TRUE, 'IA (Daily Sync)', 'IA Verificata', 0, 7, '2026-11-02T14:49:47.378181+00:00'),
('c7c05cb8-2797-4997-b5c8-e0f75c19f2f4', 319, 'Casting & Scelte', 'Il cameo vocale di Steve Coogan e Martin Freeman', 'Gli attori Steve Coogan, Martin Freeman e Bill Bailey compaiono nei panni dei superiori e colleghi londinesi che trasferiscono Nicholas Angel all''inizio del film, in un cameo organizzato grazie alle amicizie nel circuito della comedy britannica.', 'Crediti finali e interviste al cast', TRUE, 'IA (Daily Sync)', 'IA Verificata', 0, 8, '2026-11-02T14:49:47.378181+00:00'),
('e50b78e2-f6f5-421e-bac9-01cc6cb924a4', 319, 'Curiosità & Retroscena', 'La scena tagliata del cane di Nicholas Angel', 'Esisteva una sottotrama iniziale in cui Nicholas Angel possedeva un cane poliziotto che avrebbe dovuto seguirlo nel trasferimento a Sandford, ma fu tagliata nel montaggio preliminare per accelerare l''arrivo nel villaggio.', 'Scene eliminate del DVD', TRUE, 'IA (Daily Sync)', 'IA Verificata', 0, 9, '2026-11-02T14:49:47.378181+00:00'),
('678391dd-7e23-4f72-85eb-56b9d2d4bc52', 300, 'Casting & Scelte', 'La scelta iniziale di Warner Bros. e l''arrivo di Doug Liman', 'Prima che Doug Liman salisse a bordo come regista, la Warner Bros. aveva affidato il progetto a registi come Juan Carlos Fresnadillo. Fu l''arrivo di Liman a stravolgere l''impostazione visiva, trasformando un blocco sci-fi serioso in una commedia nera basata sul loop temporale.', 'Note di produzione ufficiali Warner Bros.', TRUE, 'IA (Daily Sync)', 'IA Verificata', 0, 0, '2026-11-02T14:48:20.081598+00:00'),
('27399af6-6756-4b38-9b40-59f860f9c224', 300, 'Segreti di produzione', 'L''ispirazione geografica della spiaggia di Trafalgar Square', 'Per ricreare la massiccia invasione della spiaggia nota come Operazione Downfall (chiaramente ispirata allo sbarco in Normandia), la produzione ha costruito un gigantesco set all''aperto a Leavesden e ha usato una sezione di Trafalgar Square a Londra per le riprese notturne delle strade deserte.', 'Documentario ''Operation Downfall'' - Extra Blu-ray', TRUE, 'IA (Daily Sync)', 'IA Verificata', 0, 1, '2026-11-02T14:48:20.081598+00:00'),
('f37f6792-016d-44a6-9a19-72344988c2fc', 300, 'Aneddoti dal set', 'Il fango autentico di Leavesden Studios', 'Le riprese delle sequenze nella fattoria di Omega e nei campi fangosi sono state rese particolarmente faticose dal tempo inglese. Il regista Doug Liman pretese di girare con fango vero e condizioni atmosferiche avverse, rifiutando i set in studio asciutti per mantenere il massimo realismo visivo.', 'Intervista al direttore della fotografia Dion Beebe', TRUE, 'IA (Daily Sync)', 'IA Verificata', 0, 2, '2026-11-02T14:48:20.081598+00:00'),
('aa492105-0ae1-45f9-a08f-5ffa23d35e19', 133, 'Segreti di produzione', 'La ricostruzione meticolosa del ristorante Mexican El Coyote', 'Per la scena in cui Rick Dalton e Cliff Booth cenano fuori prima della notte tragica, la produzione ha ricreato minuziosamente l''interno del celebre ristorante El Coyote così come appariva nel 1969, consultando i menu originali dell''epoca e le fotografie d''archivio per replicare persino le specifiche tonalità di colore delle luci al neon.', 'Intervista al direttore della fotografia Robert Richardson e alla scenografa Barbara Ling', TRUE, 'IA (Daily Sync)', 'IA Verificata', 0, 3, '2026-11-02T10:04:56.0012+00:00'),
('d55e4195-49fb-499a-a871-47b6889b2664', 133, 'Segreti di produzione', 'L''abbigliamento vintage originale fornito da Western Costume', 'La costumista Arianne Phillips ha attinto pesantemente agli archivi storici della Western Costume Company di Los Angeles, ripescando abiti originali degli anni Sessanta e facendo realizzare su misura i completi eccentrici di Rick Dalton utilizzando tessuti e metodi di sartia rigorosamente coevi.', 'Intervista alla costumista Arianne Phillips per Variety', TRUE, 'IA (Daily Sync)', 'IA Verificata', 0, 4, '2026-11-02T10:04:56.0012+00:00'),
('95d9311c-742f-4c2d-a034-c4e1fbeef6cc', 300, 'Curiosità & Retroscena', 'La modifica del finale cinematografico rispetto al romanzo', 'Nel romanzo originale ''All You Need Is Kill'' il finale è tragico e definitivo, con la morte di uno dei protagonisti. Doug Liman e i produttori decisero invece di optare per un epilogo agrodolce ma ottimista, ritenendo che il pubblico di un blockbuster estivo con Tom Cruise richiedesse una risoluzione più luminosa.', 'Confronto letterario e intervista allo sceneggiatore Christopher McQuarrie', TRUE, 'IA (Daily Sync)', 'IA Verificata', 0, 3, '2026-11-02T14:48:20.081598+00:00'),
('d284e55c-f1cf-4394-85e0-1cc2845cd1df', 300, 'Aneddoti dal set', 'L''approccio di Tom Cruise alle ripetute morti', 'Tom Cruise ha insistito per eseguire personalmente la maggior parte delle gag in cui il suo personaggio viene investito da camion o calpestato dai mecha-alieni ''Mimics'', coordinandosi attentamente con gli stunt coordinator per rendere ogni morte comicamente o drammaticamente unica.', 'Making-of ufficiale ''Creatures not of this Earth''', TRUE, 'IA (Daily Sync)', 'IA Verificata', 0, 4, '2026-11-02T14:48:20.081598+00:00'),
('fc488989-ef1a-465e-95fe-1d259381dfdb', 300, 'Effetti speciali & Trucco', 'Il design dei Mimics basato sui frattali', 'Gli alieni nemici, chiamati ''Mimics'', sono stati progettati dalla Framestore evitando la classica forma antropomorfa o insettoide. Hanno utilizzato algoritmi basati sulla geometria frattale e sui movimenti dei tentacoli di cefalopodi per dare l''impressione di una massa informe, fluida e letale.', 'Cinefex Magazine n. 138', TRUE, 'IA (Daily Sync)', 'IA Verificata', 0, 5, '2026-11-02T14:48:20.081598+00:00');
INSERT INTO public.movie_trivia ("id", "film_id", "categoria", "titolo", "descrizione", "fonte", "approvato", "inserito_da", "provenienza", "likes", "ordine", "created_at") VALUES
('eb1478c6-3a46-4a0d-8e4f-5f0074fbce9c', 300, 'Citazioni & Easter Egg', 'Il cameo vocale e le comparse dei soldati', 'Molti dei soldati che affiancano Tom Cruise nella squadra J Squad (interpretati da attori come Tony Way e Kick Gurry) hanno trascorso settimane di addestramento militare reale insieme all''attore per sviluppare una cameratismo autentica sullo schermo, visibile nelle loro battute improvvisate.', 'Audio commento del regista Doug Liman', TRUE, 'IA (Daily Sync)', 'IA Verificata', 0, 6, '2026-11-02T14:48:20.081598+00:00'),
('6b03a3d8-b077-400d-91af-2e9f3f4056cf', 302, 'Effetti speciali & Trucco', 'La cicatrice di Kerry Washington', 'I segni sulla schiena di Broomhilda, interpretata da Kerry Washington, derivanti dalle brutali fustigazioni subite nella piantagione, sono stati realizzati mediante un complesso processo di trucco protesico durato oltre tre ore per ogni applicazione sul set.', 'Note di produzione e reparti trucco ufficiali', TRUE, 'IA (Daily Sync)', 'IA Verificata', 0, 0, '2026-11-02T14:48:30.993184+00:00'),
('4a5b8d07-9996-4be6-8c36-1062971e26cc', 302, 'Casting & Scelte', 'La scelta di Kevin Costner per Ace Woody', 'L''attore Kevin Costner era stato originariamente scelto per interpretare il sadico addestratore di combattenti Ace Woody. Costner fu costretto a rinunciare alla parte a causa di conflitti di programmazione con le riprese della miniserie televisiva ''Hatfields & McCoys''.', 'Dichiarazioni ufficiali di casting e stampa di settore', TRUE, 'IA (Daily Sync)', 'IA Verificata', 0, 1, '2026-11-02T14:48:30.993184+00:00'),
('3d9ce407-093f-4c88-9a0b-0e4e6ed7e6b2', 302, 'Casting & Scelte', 'L''eredità di Kurt Russell', 'Dopo il forfait di Kevin Costner, il ruolo di Ace Woody fu affidato a Kurt Russell. Tuttavia, a poche settimane dall''inizio delle riprese, anche Russell abbandonò il progetto, costringendo Tarantino a riscrivere parzialmente il personaggio, che fu ribattezzato Billy Crash e assegnato a Walton Goggins.', 'Intervista a Kurt Russell per Entertainment Weekly', TRUE, 'IA (Daily Sync)', 'IA Verificata', 0, 2, '2026-11-02T14:48:30.993184+00:00'),
('a2341d38-18fb-4b12-bf70-d09b685ffc8b', 302, 'Segreti di produzione', 'Gli abiti di ispirazione storica', 'La costumista Sharen Davis ha lavorato a stretto contatto con Tarantino per riprodurre fedelmente la moda del Sud anteguerra, attingendo a cataloghi d''epoca e dipinti storici, sebbene abbia scelto di concedere a Jamie Foxx un completo da cavaliere blu ispirato esplicitamente al dipinto ''Il ragazzo in blu'' di Thomas Gainsborough.', 'Commento audio del costume designer e artbook ufficiale', TRUE, 'IA (Daily Sync)', 'IA Verificata', 0, 3, '2026-11-02T14:48:30.993184+00:00'),
('9cfb1145-5944-49be-ace3-10bafb1dd5ed', 302, 'Segreti di produzione', 'L''uso limitato della CGI', 'Fedele alla sua predilizione per il cinema analogico, Tarantino ha ridotto al minimo l''uso della grafica computerizzata. Gli schizzi di sangue durante le sparatorie sono stati realizzati quasi interamente con classici ''squib'' carichi di sangue finto e piccoli esplosivi nascosti nei costumi degli attori.', 'Making-of e documentario sul set del film', TRUE, 'IA (Daily Sync)', 'IA Verificata', 0, 4, '2026-11-02T14:48:30.993184+00:00'),
('4e239283-3e26-4cd8-aea0-ceecef31f038', 302, 'Segreti di produzione', 'La sedia da dentista mobile', 'Il carro e la poltrona da dentista itinerante del dottor Schultz sono stati costruiti da zero basandosi su brevetti americani originali del 1850, montando una vera sedia d''epoca pesante oltre cento chili su un telaio in legno appositamente rinforzato per resistere agli spostamenti sui terreni sterrati del set.', 'Reparto scenografia e note di produzione', TRUE, 'IA (Daily Sync)', 'IA Verificata', 0, 5, '2026-11-02T14:48:30.993184+00:00'),
('e62fc565-8853-46af-bb3b-972cf4c62528', 301, 'Segreti di produzione', 'La scelta del nome dello yacht', 'Lo yacht a vela di 14 metri protagonista della pellicola è stato battezzato ''Virginia Jean'' in omaggio alla madre del regista J.C. Chandor, Elizabeth Jean, e a sua nonna.', 'Note di produzione ufficiali Lionsgate', TRUE, 'IA (Daily Sync)', 'IA Verificata', 0, 0, '2026-11-02T14:48:24.311773+00:00'),
('89d03ac3-f5fe-4f9c-9360-e7bee17901dd', 301, 'Segreti di produzione', 'Il modello di barca reale usato', 'Il modello di imbarcazione scelto dalla produzione per rappresentare il ''Virginia Jean'' è un Cal 39, un cabinato a vela progettato da Cuthbertson & Cassian e prodotto a partire dagli anni ''70.', 'Speciali nautici e riviste di settore sulla produzione', TRUE, 'IA (Daily Sync)', 'IA Verificata', 0, 1, '2026-11-02T14:48:24.311773+00:00'),
('e685f354-3ca9-485b-b044-25fcf80fc86e', 301, 'Curiosità & Retroscena', 'La genesi del progetto senza finanziatori', 'J.C. Chandor ha concepito il film mentre cercava di far decollare un altro progetto più complesso; deciso a girare un film con un budget ridotto e totale controllo creativo, ha autofinanziato in parte lo sviluppo iniziale.', 'Intervista al regista su Filmmaker Magazine', TRUE, 'IA (Daily Sync)', 'IA Verificata', 0, 2, '2026-11-02T14:48:24.311773+00:00'),
('08637712-9174-40c6-b017-c95a25784b74', 301, 'Curiosità & Retroscena', 'L''assenza totale di musica diegetica e non', 'La colonna sonora composta da Alex Ebert (vincitrice di un Golden Globe) fa un uso estremamente parsimonioso della musica, lasciando che i suoni reali dell''oceano, del vento e dello scafo che cigola dominino l''intera durata del film.', 'Note di edizione della colonna sonora Milan Records', TRUE, 'IA (Daily Sync)', 'IA Verificata', 0, 3, '2026-11-02T14:48:24.311773+00:00'),
('20f2015b-4a94-421c-b276-6234a864e732', 301, 'Segreti di produzione', 'Il budget di produzione stimato', 'Il film è stato realizzato con un budget relativamente basso per gli standard hollywoodiani, stimato intorno ai 9 milioni di dollari, gran parte dei quali spesi per l''utilizzo delle strutture della Baja Studios.', 'The Hollywood Reporter - Dati finanziari di produzione', TRUE, 'IA (Daily Sync)', 'IA Verificata', 0, 4, '2026-11-02T14:48:24.311773+00:00'),
('f4f51425-fedc-4253-b436-16b5bb9a2b74', 301, 'Aneddoti dal set', 'La consulenza tecnica di marinai esperti', 'Per garantire la massima veridicità nelle procedure di riparazione dello scafo e nell''uso del sestante, la produzione ha ingaggiato navigatori professionisti che hanno supervisionato ogni mossa di Robert Redford sul set.', 'Making-of ufficiale incluso nel Blu-ray', TRUE, 'IA (Daily Sync)', 'IA Verificata', 0, 5, '2026-11-02T14:48:24.311773+00:00'),
('bacc7a46-5c49-4fd2-a229-3b648a4b582c', 301, 'Curiosità & Retroscena', 'Presentazione fuori concorso a Cannes', 'Il film è stato presentato in anteprima mondiale al Festival di Cannes 2013 nella sezione Fuori Concorso, ricevendo una lunghissima e calorosa accoglienza da parte del pubblico e della critica internazionale.', 'Archivio ufficiale del Festival di Cannes', TRUE, 'IA (Daily Sync)', 'IA Verificata', 0, 6, '2026-11-02T14:48:24.311773+00:00'),
('6ed0aea9-46dc-4e8e-837d-9ad05846d411', 303, 'Casting & Scelte', 'La scoperta casuale di Suraj Sharma', 'Suraj Sharma non aveva alcuna intenzione di recitare quando si presentò ai provini; aveva accompagnato suo fratello maggiore e fu notato dai direttori del casting che lo convinsero a partecipare, superando oltre 3.000 candidati per il ruolo di Pi adolescente.', 'Intervista ufficiale per il rilascio del film e note di produzione della 20th Century Fox', TRUE, 'IA (Daily Sync)', 'IA Verificata', 0, 0, '2026-11-02T14:48:36.41476+00:00'),
('f79432d0-37b7-49c8-9d7e-cb06412e7ab7', 303, 'Aneddoti dal set', 'Il rigoroso addestramento natatorio', 'Per prepararsi alle lunghe settimane di immersione nella piscina artificiale costruita a Taichung, in Taiwan, Suraj Sharma dovette imparare a nuotare da zero e seguire un rigido allenamento fisico che lo portò a ingrassare e poi perdere peso drasticamente per simulare la fame del naufrago.', 'Making-of ufficiale ''A Filmmaker''s Journey'' e featurette speciali del Blu-ray', TRUE, 'IA (Daily Sync)', 'IA Verificata', 0, 1, '2026-11-02T14:48:36.41476+00:00'),
('9fb70e3b-1d61-4fba-9347-370077524bdd', 303, 'Segreti di produzione', 'La piscina a onde di Taichung', 'La produzione ha convertito un vecchio aeroporto abbandonato a Taichung, in Taiwan, in una gigantesca piscina in grado di contenere 1,7 milioni di galloni d''acqua, dotata di complessi sistemi idraulici per generare onde artificiali controllate da computer.', 'Documentario sulla produzione e intervista al production designer David Gropman', TRUE, 'IA (Daily Sync)', 'IA Verificata', 0, 2, '2026-11-02T14:48:36.41476+00:00'),
('81ea4062-4288-4af7-9b90-ac51823a1b09', 303, 'Effetti speciali & Trucco', 'L''uso di tigri reali come riferimento visivo', 'Anche se la tigre Richard Parker è stata quasi interamente creata in CGI dalla Rhythm & Hues, la troupe ha utilizzato quattro tigri del Bengala reali (tra cui una di nome King) sul set per studiare i movimenti, le espressioni e il modo in cui nuotano, usandole come modello di riferimento.', 'Commento audio del regista Ang Lee e reportage tecnico della VFX Society', TRUE, 'IA (Daily Sync)', 'IA Verificata', 0, 3, '2026-11-02T14:48:36.41476+00:00'),
('33ce02d3-d5b9-40c0-bffa-990f3d46b9b3', 303, 'Curiosità & Retroscena', 'Il salvataggio finanziario della Rhythm & Hues', 'Ironia della sorte, nonostante abbia vinto l''Oscar per i migliori effetti speciali, la principale azienda responsabile della CGI del film, la Rhythm & Hues Studios, ha dichiarato bancarotta pochi giorni prima della cerimonia degli Academy Awards del 2013 a causa di margini di profitto estremamente ridotti.', 'Documentario ''Life After Pi'' e registri fallimentari della California', TRUE, 'IA (Daily Sync)', 'IA Verificata', 0, 4, '2026-11-02T14:48:36.41476+00:00'),
('31095a0f-00fa-4b09-b0be-c8b96083c7b8', 303, 'Casting & Scelte', 'La trasformazione di Tobey Maguire', 'Tobey Maguire aveva originariamente girato tutte le sue scene nel ruolo dello scrittore che intervista il Pi adulto. Tuttavia, il regista Ang Lee decise in seguito che la presenza di una star così celebre avrebbe distratto troppo il pubblico e decise di rigirare l''intero ruolo con l''attore britannico Rafe Spall.', 'Comunicato stampa ufficiale e interviste rilasciate da Ang Lee a Variety', TRUE, 'IA (Daily Sync)', 'IA Verificata', 0, 5, '2026-11-02T14:48:36.41476+00:00'),
('174a8710-6e8c-48ab-891a-4a226817fe0d', 303, 'Citazioni & Easter Egg', 'Il tributo al cinema muto e a Satyajit Ray', 'Il nome completo del protagonista, Piscine Molitor Patel, fa riferimento a una vera piscina parigina, ma l''intera atmosfera visiva e la sensibilità del film richiamano apertamente i capolavori del maestro indiano Satyajit Ray e i drammi marittimi classici.', 'Note di regia ufficiali e analisi critiche del festival di New York', TRUE, 'IA (Daily Sync)', 'IA Verificata', 0, 6, '2026-11-02T14:48:36.41476+00:00'),
('4ce3ff16-24d7-4d43-8d19-c8c249fbf19c', 303, 'Segreti di produzione', 'Il sistema di ripresa stereoscopica proprietario', 'Poiché non esistevano cineprese 3D abbastanza leggere e versatili per le complesse esigenze di Ang Lee, la troupe ha dovuto sviluppare e testare rig personalizzati per montare telecamere digitali Arri Alexa in configurazione stereoscopica.', 'Articolo tecnico della rivista American Cinematographer', TRUE, 'IA (Daily Sync)', 'IA Verificata', 0, 7, '2026-11-02T14:48:36.41476+00:00'),
('df18714a-96a3-43ba-867f-56fdc2dd7d91', 313, 'Segreti di produzione', 'La consulenza del CERN', 'Per garantire il massimo rigore scientifico nella rappresentazione del laboratorio europeo, la produzione ha assunto veri fisici del CERN come consulenti sul set e ha girato alcune sequenze all''interno delle vere strutture di Ginevra.', 'Note di produzione ufficiali Sony Pictures', TRUE, 'IA (Daily Sync)', 'IA Verificata', 0, 0, '2026-11-02T14:49:17.5795+00:00'),
('c710321b-cf14-4aaa-9526-96a455322081', 313, 'Effetti speciali & Trucco', 'La ricostruzione della Cappella Sistina', 'Poiché l''accesso al Vaticano era interdetto, gli scenografi diretti da Allan Cameron hanno ricostruito meticolosamente gli interni della Cappella Sistina e della Sala Regia nei soundstage dei Sony Pictures Studios, lavorando con pittori e scultori per replicare gli affreschi.', 'Featurette ''The Sets of Angels & Demons''', TRUE, 'IA (Daily Sync)', 'IA Verificata', 0, 1, '2026-11-02T14:49:17.5795+00:00'),
('d1031805-a6e5-4bae-8d5e-f92f618bead1', 302, 'Curiosità & Retroscena', 'Il brano rap scartato di Frank Ocean', 'Il cantautore R&B Frank Ocean era stato ingaggiato da Tarantino per comporre un brano originale da inserire nella colonna sonora del film. La canzone fu però scartata all''ultimo momento perché il regista ritenne che il brano non si adattasse cronologicamente e stilisticamente alle sequenze in cui era stato collocato.', 'Dichiarazione ufficiale di Frank Ocean via Twitter / Rolling Stone', TRUE, 'IA (Daily Sync)', 'IA Verificata', 0, 6, '2026-11-02T14:48:30.993184+00:00'),
('e4eb1a4b-a1bb-4d93-ae4a-79915490ac93', 302, 'Casting & Scelte', 'La cicatrice reale di Jonah Hill', 'Jonah Hill avrebbe dovuto interpretare uno dei membri della banda dei Regulators guidati da Don Johnson. A causa di ritardi nella produzione della commedia ''Vicini del terzo tipo'', Hill dovette ridimensionare la sua partecipazione a un piccolo cameo mascherato, interpretando uno dei membri del Ku Klux Klan.', 'Intervista a Jonah Hill per The Howard Stern Show', TRUE, 'IA (Daily Sync)', 'IA Verificata', 0, 7, '2026-11-02T14:48:30.993184+00:00'),
('bf60fd0e-f088-4c21-923f-80b09a2d269a', 302, 'Citazioni & Easter Egg', 'Il tributo musicale a Ennio Morricone', 'Sebenora gran parte della colonna sonora utilizzi tracce originali di vecchi spaghetti western, Tarantino ha inserito brani tratti da ''I giorni dell''ira'' (1967) e ''Il mercenario'' (1968), entrambi musicati dal celebre maestro Ennio Morricone, con cui il regista avrebbe poi collaborato direttamente per ''The Hateful Eight''.', 'Note di copertina della colonna sonora ufficiale', TRUE, 'IA (Daily Sync)', 'IA Verificata', 0, 8, '2026-11-02T14:48:30.993184+00:00'),
('8c5515ad-e1b0-47d4-8efb-23290b20b3f3', 302, 'Segreti di produzione', 'La precisione delle armi d''epoca', 'L''armiere del film, Harry Lu, ha fornito repliche fedeli e armi originali risalenti agli anni Sessanta del XIX secolo. Per la pistola a doppia canna utilizzata da Django sono stati impiegati veri fucili a canne mozze modificati per sparare cartucce a salve sicure ma scenograficamente d''impatto.', 'Intervista all''armiere principale del film', TRUE, 'IA (Daily Sync)', 'IA Verificata', 0, 9, '2026-11-02T14:48:30.993184+00:00'),
('839fe136-40d7-4062-b926-da86bbb67f03', 318, 'Curiosità & Retroscena', 'La casa di riposo storica come set', 'Molte delle sequenze ambientate nella sfarzosa villa di Daniel Plainview alla fine del film sono state girate nella Greystone Mansion a Beverly Hills, una storica residenza che in passato era stata teatro di un tragico fatto di cronaca nera realmente accaduto nel 1929.', 'Note di produzione ufficiali Paramount Pictures', TRUE, 'IA (Daily Sync)', 'IA Verificata', 0, 0, '2026-11-02T14:49:41.363047+00:00'),
('c4979332-b093-40f2-b72b-a069b0de2b51', 318, 'Citazioni & Easter Egg', 'L''ispirazione visiva da John Huston', 'Paul Thomas Anderson ha studiato approfonditamente i capolavori del passato per la messa in scena, in particolare ''Il tesoro di Sierra Madre'' (1948) diretto da John Huston, citando espressamente l''avidità e la paranoia del cercatore d''oro interpretato da Humphrey Bogart come modello diretto per la discesa agli inferi di Daniel Plainview.', 'Audio commento del regista e interviste stampa', TRUE, 'IA (Daily Sync)', 'IA Verificata', 0, 1, '2026-11-02T14:49:41.363047+00:00'),
('41dc586c-a13d-4f82-a690-266454be1ba1', 318, 'Effetti speciali & Trucco', 'Il trucco artigianale delle ustioni', 'Per realizzare le ustioni e le ferite sul volto di Daniel Day-Lewis dopo l''esplosione del pozzo petrolifero, il reparto trucco ha utilizzato protesi in silicone avanzate combinate con pigmenti minerali naturali, applicati quotidianamente con un processo che richiedeva oltre due ore di lavorazione prima di ogni ciak.', 'Intervista al reparto trucco e parrucco nei contenuti speciali del Blu-ray', TRUE, 'IA (Daily Sync)', 'IA Verificata', 0, 2, '2026-11-02T14:49:41.363047+00:00'),
('19a165dc-9819-45b4-ab87-047e104f419d', 318, 'Segreti di produzione', 'L''uso dei veri strumenti d''epoca', 'La troupe di scenografia ha cercato e impiegato autentici strumenti di trivellazione risalenti alla fine del XIX secolo, reperiti presso musei industriali e collezionisti privati del Texas, per garantire la totale autenticità meccanica delle operazioni estrattive mostrate sullo schermo.', 'Articolo di American Cinematographer sulla produzione del film', TRUE, 'IA (Daily Sync)', 'IA Verificata', 0, 3, '2026-11-02T14:49:41.363047+00:00'),
('62432191-62b6-4edf-8c7f-519e9c618fc7', 318, 'Segreti di produzione', 'La scelta della pellicola 35mm e Panavision', 'Il direttore della fotografia Robert Elswit ha girato interamente il film utilizzando cineprese Panavision e pellicola 35mm, rifiutando qualsiasi supporto digitale per catturare al meglio i paesaggi desertici del Texas e la luce naturale della Golden Hour.', 'Intervista tecnica a Robert Elswit per la rivista International Cinematographers Guild', TRUE, 'IA (Daily Sync)', 'IA Verificata', 0, 4, '2026-11-02T14:49:41.363047+00:00'),
('93b2003c-98fc-4bf5-9c71-f249c49788a4', 320, 'Curiosità & Retroscena', 'L''ispirazione iniziale dai documentari National Geographic', 'Mel Gibson ha concepito l''idea di Apocalypto mentre guardava un documentario sulla civiltà Maya e sul suo collasso improvviso, decidendo di voler realizzare un film d''azione che sembrasse un documentario ad alta velocità.', 'Commento audio ufficiale del regista nel DVD del film', TRUE, 'IA (Daily Sync)', 'IA Verificata', 0, 0, '2026-11-02T14:49:52.16647+00:00'),
('440d2117-d289-4b27-9287-968be9987bc7', 320, 'Segreti di produzione', 'La collaborazione con Richard D. Zanuck', 'Il leggendario produttore Richard D. Zanuck è stato coinvolto nel progetto dopo che Mel Gibson lo aveva già finanziato in gran parte in modo indipendente attraverso la sua Icon Productions, garantendo la distribuzione globale tramite la Touchstone Pictures.', 'Note di produzione ufficiali Touchstone Pictures', TRUE, 'IA (Daily Sync)', 'IA Verificata', 0, 1, '2026-11-02T14:49:52.16647+00:00'),
('ad2e2cdf-84d1-4182-86db-17413a323e8c', 320, 'Segreti di produzione', 'L''uso della pellicola Super 35', 'Il direttore della fotografia Dean Semler ha utilizzato cineprese Arriflex e formato Super 35 per catturare l''immensità della giungla e l''intimità delle sequenze di fuga, sfruttando la luce naturale e riflettori giganti nascosti tra gli alberi.', 'American Cinematographer Magazine, intervista a Dean Semler', TRUE, 'IA (Daily Sync)', 'IA Verificata', 0, 2, '2026-11-02T14:49:52.16647+00:00'),
('f8acccf3-5430-4b9c-bdfb-fd33526bad00', 320, 'Curiosità & Retroscena', 'Il supporto linguistico dell''università', 'Per la traduzione e la fonetica della lingua Maya yucateca, la produzione ha collaborato strettamente con esperti linguisti e accademici dell''Università del Texas ad Austin, guidati dalla professoressa Nora England.', 'Documentario ''The Making of Apocalypto''', TRUE, 'IA (Daily Sync)', 'IA Verificata', 0, 3, '2026-11-02T14:49:52.16647+00:00'),
('519debb6-d6d1-4b91-8ec3-e068070af766', 320, 'Casting & Scelte', 'Il casting itinerante nelle Americhe', 'Il direttore del casting Jeanne McCarthy ha organizzato audizioni non solo in Messico, ma anche in comunità indigene in Canada e negli Stati Uniti per trovare i volti più adatti a rappresentare la diversità etnica pre-colombiana.', 'Variety Casting Feature 2006', TRUE, 'IA (Daily Sync)', 'IA Verificata', 0, 4, '2026-11-02T14:49:52.16647+00:00'),
('7487b4cc-5b3f-48ac-9d8d-fef2405866d0', 320, 'Aneddoti dal set', 'La pioggia artificiale durante la sequenza dell''eclissi', 'Durante la complessa scena dell''eclissi solare e dei sacrifici sul tempio, la troupe ha dovuto impiegare decine di autobotti per creare una pioggia torrenziale artificiale che ha reso fangoso e scivoloso il set per giorni.', 'Diario di bordo della troupe, Making-of ufficiale', TRUE, 'IA (Daily Sync)', 'IA Verificata', 0, 5, '2026-11-02T14:49:52.16647+00:00'),
('0c7ae037-d660-4897-b375-94213107362e', 320, 'Segreti di produzione', 'Il sound design di Lon Bender', 'Il supervisore del montaggio del suono Lon Bender ha combinato vocalizzi di animali esotici, registrazioni di mercati messicani e strumenti musicali pre-colombiani ricostruiti per creare l''ambiente acustico unico della giungla.', 'Intervista audio a Lon Bender per SoundWorks Collection', TRUE, 'IA (Daily Sync)', 'IA Verificata', 0, 6, '2026-11-02T14:49:52.16647+00:00'),
('38bcf9f5-b962-4a99-a1f0-31f907684b7e', 305, 'Aneddoti dal set', 'La vera frattura alle costole di Natalie Portman', 'Durante le riprese della sequenza in cui Nina e Thomas Leroy lottano sul letto, Natalie Portman ha realmente subito la frattura di una costola a causa di un movimento non calcolato. Poiché la produzione aveva un budget limitato e tempi strettissimi, l''attrice ha continuato a girare senza fermarsi, indossando un corsetto ortopedico nascosto.', 'Intervista ufficiale di Natalie Portman al Tonight Show con David Letterman', TRUE, 'IA (Daily Sync)', 'IA Verificata', 0, 0, '2026-11-02T14:48:41.432757+00:00'),
('7d00dd27-4151-4010-ac35-8184267eb807', 305, 'Aneddoti dal set', 'Il grave infortunio alla caviglia nascosto', 'Poco prima dell''inizio della produzione, Natalie Portman si è lussata una costola e ha subito una grave distorsione alla caviglia che ha rischiato di compromettere la sua partecipazione. La troupe ha dovuto riorganizzare interamente il piano di lavorazione per girare prima le scene in primo piano, permettendole di guarire parzialmente.', 'Note di produzione ufficiali e commento audio del regista Darren Aronofsky', TRUE, 'IA (Daily Sync)', 'IA Verificata', 0, 1, '2026-11-02T14:48:41.432757+00:00'),
('f6fa2904-e81a-46c8-b36b-d7dd4c540d28', 305, 'Casting & Scelte', 'Il bacio improvvisato e la reazione autentica', 'La celebre e intensa sequenza della scena d''amore e bacio tra Natalie Portman e Mila Kunis è stata girata dopo che le due attrici avevano già stretto una forte amicizia fuori dal set. Per mantenere alta la tensione psicologica, Aronofsky ha chiesto loro di improvvisare alcune sfumature di imbarazzo e attrazione.', 'Making-of ufficiale ''Metamorphosis: The Making of Black Swan''', TRUE, 'IA (Daily Sync)', 'IA Verificata', 0, 2, '2026-11-02T14:48:41.432757+00:00'),
('7405bd05-aef4-4261-9a6e-bc26325fa2bb', 305, 'Segreti di produzione', 'L''uso strategico della cinepresa a mano 16mm', 'Per accentuare il senso di claustrofobia, paranoia e instabilità mentale della protagonista Nina, il direttore della fotografia Matthew Libatique ha girato tutte le scene dietro le quinte e domestiche utilizzando una macchina da presa analogica a 16mm, contrapponendola al digitale pulito delle sequenze sul palcoscenico.', 'American Cinematographer, intervista a Matthew Libatique', TRUE, 'IA (Daily Sync)', 'IA Verificata', 0, 3, '2026-11-02T14:48:41.432757+00:00'),
('fd6f1e77-babe-4cc4-9955-9edf0a0b1bd4', 305, 'Casting & Scelte', 'Il cameo di Tina Fey sfumato', 'Nelle primissime fasi di sviluppo della sceneggiatura, quando il progetto era intitolato ''The Understudy'' e prevedeva toni leggermente differenti legati al mondo teatrale off-Broadway, Darren Aronofsky aveva considerato l''attrice e comica Tina Fey per un ruolo di supporto, poi eliminato con la riscrittura incentrata sul balletto classico.', 'Archivio storico di produzione e prime stesure della sceneggiatura', TRUE, 'IA (Daily Sync)', 'IA Verificata', 0, 4, '2026-11-02T14:48:41.432757+00:00'),
('49780397-48a9-4cc1-80b9-084c495fc1db', 305, 'Citazioni & Easter Egg', 'L''ispirazione visiva da ''Repulsion'' di Polanski', 'Darren Aronofsky ha dichiarato apertamente di essersi ispirato ai thriller psicologici classici, in particolare a ''Repulsion'' di Roman Polanski e a ''Il inquilino del terzo piano'', oltre che al film d''animazione ''Perfect Blue'' di Satoshi Kon, per la rappresentazione visiva della progressiva perdita di senno della protagonista.', 'Intervista al regista pubblicata su Filmmaker Magazine', TRUE, 'IA (Daily Sync)', 'IA Verificata', 0, 5, '2026-11-02T14:48:41.432757+00:00'),
('f86b07ec-e3c6-426a-9c6e-d8a26d8beb72', 305, 'Effetti speciali & Trucco', 'La sovrapposizione dei doppi attraverso specchi reali', 'Gran parte dei complessi effetti visivi in cui Nina vede il suo riflesso muoversi in autonomia o assumere espressioni diverse non è stata fatta in post-produzione con il croma key. La troupe ha utilizzato elaborate coreografie di specchi mobili, doppi di corpo identici e movimenti di macchina sincronizzati.', 'Featurette sugli effetti visivi nel Blu-ray ufficiale', TRUE, 'IA (Daily Sync)', 'IA Verificata', 0, 6, '2026-11-02T14:48:41.432757+00:00'),
('5fa5277d-9d94-4c3e-98ce-408d2b5ba599', 307, 'Segreti di produzione', 'La scelta della location a Peddocks Island', 'Gran parte delle riprese esterne dell''istituto psichiatrico si sono svolte a Peddocks Island, nel porto di Boston, dove la produzione ha dovuto ristrutturare edifici militari abbandonati risalenti alla seconda guerra mondiale per adattarli all''ambientazione anni ''50.', 'Production Notes ufficiali della Paramount Pictures', TRUE, 'IA (Daily Sync)', 'IA Verificata', 0, 0, '2026-11-02T14:48:52.34122+00:00'),
('8e3fdfe8-f9a7-4b20-8330-e0913ca07e98', 307, 'Curiosità & Retroscena', 'La colonna sonora basata su brani preesistenti', 'Martin Scorsese non ha commissionato una colonna sonora orchestrale originale tradizionale, ma ha curato personalmente una compilation di brani avant-garde del XX secolo, tra cui composizioni di Krzysztof Penderecki, György Ligeti e John Cage, per amplificare il senso di disorientamento psicologico.', 'Note di regia e interviste al supervisore musicale Randall Poster', TRUE, 'IA (Daily Sync)', 'IA Verificata', 0, 1, '2026-11-02T14:48:52.34122+00:00'),
('9a5a2fad-8c12-4cb6-946f-725bec543e57', 307, 'Citazioni & Easter Egg', 'Ispirazione pittorica per le visioni', 'Le allucinazioni e i sogni di Teddy Daniels ispirati alla moglie morta traggono ispirazione visiva esplicita dai dipinti di Gustav Klimt e dai lavori del fotografo surrealista Man Ray, come confermato dal direttore della fotografia Robert Richardson.', 'American Cinematographer, intervista a Robert Richardson', TRUE, 'IA (Daily Sync)', 'IA Verificata', 0, 2, '2026-11-02T14:48:52.34122+00:00'),
('fa96e053-0fb1-475e-bdc0-eb7c015ed3f7', 307, 'Segreti di produzione', 'L''uso esteso della pellicola 35mm', 'Nonostante l''avanzata della tecnologia digitale nel 2009, Martin Scorsese e Robert Richardson hanno girato interamente il film in pellicola 35mm utilizzando cineprese Arriflex, puntando a una grana cinematografica densa che richiamasse i thriller technicolor e in bianco e nero della Warner Bros degli anni ''50.', 'Report tecnico di produzione della Paramount', TRUE, 'IA (Daily Sync)', 'IA Verificata', 0, 3, '2026-11-02T14:48:52.34122+00:00'),
('97f2aeb7-bfe5-40db-963e-5fa09f63ef07', 307, 'Casting & Scelte', 'Il cameo mancato di Dennis Lehane', 'Dennis Lehane, l''autore del romanzo omonimo da cui è tratto il film, avrebbe dovuto fare un piccolo cameo come comparsa all''interno dell''istituto Ashecliffe, ma l''idea è stata scartata all''ultimo minuto a causa di conflitti di programmazione durante le riprese a Boston.', 'Intervista audio extra nel Blu-ray ufficiale', TRUE, 'IA (Daily Sync)', 'IA Verificata', 0, 4, '2026-11-02T14:48:52.34122+00:00'),
('ed05e068-4b0f-4d7f-9633-a5705d087a67', 307, 'Aneddoti dal set', 'Le condizioni meteorologiche estreme sul set', 'Durante la sequenza dell''uragano, la troupe ha dovuto lavorare con enormi macchine del vento e idranti ad alta pressione che spruzzavano acqua gelida a temperature vicine allo zero, causando non poche difficoltà fisiche a Leonardo DiCaprio e Mark Ruffalo costretti a vestiti leggeri da agenti federali.', 'Making-of ufficiale ''Behind the Shutter''', TRUE, 'IA (Daily Sync)', 'IA Verificata', 0, 5, '2026-11-02T14:48:52.34122+00:00'),
('fcc0e1b0-fe82-4a94-89b1-c77d66f9c800', 307, 'Curiosità & Retroscena', 'La ricerca storica sull''ospedale di Pilgrim', 'Per prepararsi accuratamente ai loro ruoli e comprendere il clima dei manicomi criminali degli anni ''50, gli sceneggiatori e i produttori hanno esaminato i registri medici e le procedure di lobotomia transorbitale praticate in istituti reali come il Pilgrim State Hospital di New York.', 'Documentario sui retroscena storici del film', TRUE, 'IA (Daily Sync)', 'IA Verificata', 0, 6, '2026-11-02T14:48:52.34122+00:00'),
('c750155e-3f87-42c5-9e3d-ccd543770747', 307, 'Segreti di produzione', 'La ricostruzione in studio del padiglione C', 'Il claustrofobico padiglione C, dove sono custoditi i pazienti più pericolosi dell''isola, non è un vero edificio esistente, ma un set elaborato e chiuso ermeticamente costruito nei teatri di posa diadjustment a Boston, progettato dallo scenografo Dante Ferretti per aumentare il senso di oppressione.', 'Intervista allo scenografo Dante Ferretti', TRUE, 'IA (Daily Sync)', 'IA Verificata', 0, 7, '2026-11-02T14:48:52.34122+00:00'),
('851dd142-82d7-4715-9e1c-00533560e2de', 306, 'Casting & Scelte', 'Il provino e l''abbigliamento formale di Joseph Gordon-Levitt', 'Per convincere Christopher Nolan di essere la scelta giusta per il ruolo meticoloso e formale di Arthur, Joseph Gordon-Levitt si presentò a tutti i provini indossando un abito completo in stile dandy, nonostante il caldo estivo e la natura informale degli incontri iniziali.', 'Commento audio del regista e dietro le quinte ufficiale Blu-ray', TRUE, 'IA (Daily Sync)', 'IA Verificata', 0, 0, '2026-11-02T14:48:46.743997+00:00'),
('78697309-e7fb-4d2d-bc8f-174171b7c28e', 306, 'Casting & Scelte', 'La scelta iniziale di Leonardo DiCaprio', 'Christopher Nolan aveva puntato fortemente su Leonardo DiCaprio per il ruolo di Cobb già molto tempo prima dell''inizio delle riprese, incontrandolo ripetutamente per mesi per affinare la complessa struttura emotiva e la psicologia del personaggio principale.', 'The Hollywood Reporter - Retrospettiva sulla produzione di Inception', TRUE, 'IA (Daily Sync)', 'IA Verificata', 0, 1, '2026-11-02T14:48:46.743997+00:00'),
('2d047757-3748-4702-b28a-61423a9596c3', 306, 'Aneddoti dal set', 'La preparazione acrobatica di Joseph Gordon-Levitt', 'L''attore ha insistito per girare personalmente la maggior parte delle pericolose scene di lotta nel corridoio rotante a gravità zero, allenandosi duramente per due settimane con gli stuntmen della troupe guidati da Tom Struthers.', 'Making-of ''Inception: The Casting'' e interviste alla troupe', TRUE, 'IA (Daily Sync)', 'IA Verificata', 0, 2, '2026-11-02T14:48:46.743997+00:00'),
('875fab7d-397d-486f-aeb5-26c75f036e3c', 306, 'Segreti di produzione', 'Il set rotante a grandezza naturale', 'Per ricreare l''effetto della gravità variabile nell''hotel onirico, la produzione ha costruito un corridoio cilindrico reale lungo oltre trenta metri montato su enormi anelli d''acciaio rotanti, alimentati da otto motori elettrici capaci di girare a 360 gradi.', 'Documentario ''Building the Impossible'' nel Blu-ray ufficiale', TRUE, 'IA (Daily Sync)', 'IA Verificata', 0, 3, '2026-11-02T14:48:46.743997+00:00'),
('98bccf0a-19e8-41aa-b0dc-df635e3e7692', 306, 'Curiosità & Retroscena', 'La genesi del personaggio di Ariadne', 'Il nome del personaggio interpretato da Elliot Page fa esplicito riferimento alla mitologia greca: Arianna diede a Teseo il celebre filo per orientarsi e uscire dal labirinto del Minotauro, esattamente come l''architetto guida Cobb nei labirinti mentali.', 'Note di produzione ufficiali della Warner Bros.', TRUE, 'IA (Daily Sync)', 'IA Verificata', 0, 4, '2026-11-02T14:48:46.743997+00:00'),
('52171731-6e7c-402e-8bfa-b2d30cc64d6a', 306, 'Curiosità & Retroscena', 'La consulenza scientifica sui sogni', 'Durante la scrittura della sceneggiatura, Christopher Nolan si è consultato con esperti di lucidità onirica e neurologi per mantenere una plausibilità scientifica di fondo, soprattutto riguardo alla percezione dilatata del tempo all''interno dei sogni.', 'Intervista di Christopher Nolan a Entertainment Weekly', TRUE, 'IA (Daily Sync)', 'IA Verificata', 0, 5, '2026-11-02T14:48:46.743997+00:00'),
('b8eb07d5-ff9e-48b9-b99b-ee28357f050b', 306, 'Citazioni & Easter Egg', 'L''ispirazione visiva da Escher', 'La celebre sequenza in cui Arthur spiega ad Ariadne la fisica dei sogni alterati mostra esplicitamente le scale infinite ispirate alla celebre litografia ''Salita e discesa'' dell''artista olandese Maurits Cornelis Escher.', 'Libro ufficiale ''Inception: The Shooting Script''', TRUE, 'IA (Daily Sync)', 'IA Verificata', 0, 6, '2026-11-02T14:48:46.743997+00:00'),
('e7b3266e-3a2b-4c94-ac4b-1159f88c0197', 306, 'Citazioni & Easter Egg', 'Il costume di Marion Cotillard e l''omaggio a Hitchcock', 'I costumi indossati da Marion Cotillard nel ruolo di Mal, caratterizzati da abiti eleganti e classici, sono stati esplicitamente modellati da Nolan e dalla costumista Jeffrey Kurland sulle figure delle ''bionde glaciali'' dei film di Alfred Hitchcock.', 'Costume Design Featurette e note di produzione', TRUE, 'IA (Daily Sync)', 'IA Verificata', 0, 7, '2026-11-02T14:48:46.743997+00:00'),
('ead01a6b-88c4-40a9-8767-80f4a7538a8d', 310, 'Casting & Scelte', 'Il cameo nascosto di Edie Falco nei panni di General Ardmore', 'L''attrice Edie Falco, nota per i suoi ruoli televisivi in ''The Sopranos'', ha accettato di interpretare la spietata General Ardmore ma ha girato tutte le sue scene a Manhattan, separata dal resto del cast sul set a causa dei complessi impegni di produzione.', 'Note di produzione ufficiali 20th Century Studios', TRUE, 'IA (Daily Sync)', 'IA Verificata', 0, 0, '2026-11-02T14:49:03.057736+00:00'),
('72bb355b-1f2d-471f-a6bf-e45d9d945adf', 310, 'Casting & Scelte', 'Il ritorno di Sigourney Weaver come adolescente', 'Per interpretare Kiri, la figlia adolescente di Grace, la settantenne Sigourney Weaver ha frequentato le scuole superiori locali e ha studiato le voci degli adolescenti per risultare credibile in un ruolo così distante dalla sua età anagrafica.', 'Intervista ufficiale Empire Magazine', TRUE, 'IA (Daily Sync)', 'IA Verificata', 0, 1, '2026-11-02T14:49:03.057736+00:00'),
('f701e509-0694-4fff-9a20-ee47be1ed3d4', 310, 'Segreti di produzione', 'La genesi delle sceneggiature multiple', 'Prima di iniziare le riprese, James Cameron ha fatto scrivere ben quattro sceneggiature distinte per i diversi sequel da quattro team di sceneggiatori differenti, per poi fondere le idee migliori nella struttura narrativa finale.', 'Reportage di Variety sulla produzione di Avatar', TRUE, 'IA (Daily Sync)', 'IA Verificata', 0, 2, '2026-11-02T14:49:03.057736+00:00'),
('46fd5584-ee41-4ce3-8930-f537de3754a8', 310, 'Effetti speciali & Trucco', 'La simulazione delle onde oceaniche', 'La Wētā FX ha dovuto sviluppare un software proprietario denominato ''High-End Water Solver'' per simulare non solo l''acqua visibile, ma anche l''interazione della schiuma e degli spruzzi sui corpi bagnati dei Na''vi.', 'Documentario tecnico Siggraph 2022', TRUE, 'IA (Daily Sync)', 'IA Verificata', 0, 3, '2026-11-02T14:49:03.057736+00:00'),
('76e055ea-5a9c-40b2-9930-6a3a2a99fbd8', 310, 'Citazioni & Easter Egg', 'L''omaggio a Titanic nel design sottomarino', 'Il sommergibile pilotato dai RDA per catturare le creature marine di Pandora presenta codici numerici e dettagli strutturali che omaggiano direttamente i sommergibili utilizzati da James Cameron durante le sue reali esplorazioni del relitto del Titanic.', 'Commento audio del regista nel Blu-ray', TRUE, 'IA (Daily Sync)', 'IA Verificata', 0, 4, '2026-11-02T14:49:03.057736+00:00'),
('134ab929-b14a-44a0-90b4-c5b015964f0f', 311, 'Curiosità & Retroscena', 'La morte di Carl concepita in un finale alternativo', 'Nelle prime fasi di sviluppo della sceneggiatura, la storia prevedeva che Carl morisse nel sonno durante la prima notte passata nella sua casa atterrata in Sud America, lasciando Russell da solo ad affrontare la giungla.', 'Commento audio del regista Pete Docter e co-regista Bob Peterson', TRUE, 'IA (Daily Sync)', 'IA Verificata', 0, 0, '2026-11-02T14:49:08.220523+00:00'),
('b081e77d-9c21-40a4-8d8c-dc641e32e29d', 311, 'Casting & Scelte', 'L''ispirazione per il personaggio di Charles Muntz', 'Il villain Charles Muntz è stato modellato visivamente e caratterialmente unendo le figure di esploratori reali e divi del cinema d''avventura degli anni ''30 come Errol Flynn, Howard Hughes e Walt Disney.', 'Art of Up - The Art of Pixar', TRUE, 'IA (Daily Sync)', 'IA Verificata', 0, 1, '2026-11-02T14:49:08.220523+00:00'),
('b7410c3b-deb6-4079-a4eb-771ca0eb6d88', 311, 'Citazioni & Easter Egg', 'Il cane Dug e l''omaggio a Carl Sagan', 'Il dispositivo di traduzione indossato dal cane Dug per parlare con gli umani si ispira direttamente alle teorie sulla comunicazione interspecie e all''opera del celebre astronomo e divulgatore scientifico Carl Sagan.', 'Note di produzione ufficiali Pixar', TRUE, 'IA (Daily Sync)', 'IA Verificata', 0, 2, '2026-11-02T14:49:08.220523+00:00'),
('eaac2f98-6068-4e8c-a0fe-066306f6bdc7', 311, 'Aneddoti dal set', 'L''improvvisazione di Ed Asner sulle scale', 'Durante la sessione di registrazione vocale, Ed Asner si lamentò realmente e con grande trasporto fisico per la fatica di salire le scale con il pesante carrello, battute che Pete Docter decise di mantenere nel montaggio finale.', 'Speciali del making-of inclusi nel Blu-ray Disc', TRUE, 'IA (Daily Sync)', 'IA Verificata', 0, 3, '2026-11-02T14:49:08.220523+00:00'),
('1b07648f-d340-4237-8497-bf453ab15777', 311, 'Segreti di produzione', 'Il modello fisico della casa nel reparto sculture', 'Prima di renderizzare digitalmente il volo della casa, gli artisti del reparto sculture della Pixar hanno realizzato un modellino fisico in legno e centinaia di palloncini in miniatura per studiare i baricentri e le tensioni strutturali.', 'Documentario ''The Many Endings of Up'' - Home Video', TRUE, 'IA (Daily Sync)', 'IA Verificata', 0, 4, '2026-11-02T14:49:08.220523+00:00'),
('d7e57d83-b08d-4405-9225-0ec41cbc4fab', 311, 'Segreti di produzione', 'La carta geografica autentica della Venezuela', 'Per riprodurre fedelmente la topografia dei tepui venezuelani (in particolare il Monte Roraima e l''Auyan Tepui), il team di produzione ha consultato le mappe geologiche ufficiali fornite dall''ambasciata venezuelana e dai diari della spedizione di Jimmy Angel.', 'Diario di bordo della troupe in Sud America - Pixar Animation Studios', TRUE, 'IA (Daily Sync)', 'IA Verificata', 0, 5, '2026-11-02T14:49:08.220523+00:00'),
('bfed893c-c960-420e-a93f-6840bfc0187e', 312, 'Casting & Scelte', 'La scelta della parrucca per Robert Langdon', 'Tom Hanks ha indossato una parrucca specifica e molto discussa per interpretare Robert Langdon, una decisione stilistica voluta dal regista Ron Howard che ha scatenato non pochi dibattiti tra i fan del libro e i critici cinematografici.', 'Audio commento del regista Ron Howard nel DVD ufficiale', TRUE, 'IA (Daily Sync)', 'IA Verificata', 0, 0, '2026-11-02T14:49:13.447523+00:00'),
('e284595d-7188-414c-8ea4-5ba9c9803026', 214, 'Casting & Scelte', 'La sceneggiatura rimasta nella Black List per anni', 'La sceneggiatura scritta da Aaron Guzikowski era stata inserita nella celebre ''Black List'' di Hollywood già nel 2009, la lista dei migliori script non ancora prodotti, prima di trovare finalmente finanziamenti e interesse da parte dei produttori anni dopo.', 'Note di produzione ufficiali e archivi della Black List', TRUE, 'IA (Daily Sync)', 'IA Verificata', 0, 0, '2026-11-02T15:47:12.392412+00:00'),
('4b78aa0b-f718-46b2-b19c-f5cc5596a60a', 312, 'Curiosità & Retroscena', 'Il divieto di proiezione in alcune sale estere', 'Nonostante il grande successo commerciale, il film è stato bandito o fortemente censurato in diversi paesi nel mondo, tra cui la Bielorussia, la Thailandia e alcune regioni delle Filippine e dell''India, a causa dei temi religiosi ritenuti offensivi.', 'Archivio storico dei dati di distribuzione internazionale box office', TRUE, 'IA (Daily Sync)', 'IA Verificata', 0, 2, '2026-11-02T14:49:13.447523+00:00'),
('4690036d-d5e9-4bf1-9322-b8205e6ee270', 312, 'Casting & Scelte', 'La scelta del cast britannico per i ruoli chiave', 'Per conferire maggiore autenticità e profondità drammatica ai personaggi storici ed enigmatici, Ron Howard ha voluto fortemente attingere al panorama teatrale britannico, ingaggiando oltre a Ian McKellen anche attori del calibro di Paul Bettany e Alfred Molina.', 'Featurette di casting nel Blu-ray ufficiale del film', TRUE, 'IA (Daily Sync)', 'IA Verificata', 0, 3, '2026-11-02T14:49:13.447523+00:00'),
('a9eea297-b937-4b6a-a01b-0e58d7497ed6', 312, 'Aneddoti dal set', 'Le riprese all''interno di Saint-Sulpice', 'La produzione ha chiesto formalmente di poter girare alcune scene chiave all''interno della vera chiesa parigina di Saint-Sulpice, ma le autorità ecclesiastiche locali hanno negato categoricamente l''autorizzazione, costringendo la troupe a ricostruire parzialmente gli interni in teatro di posa.', 'Dichiarazioni ufficiali della diocesi di Parigi e reportage di produzione', TRUE, 'IA (Daily Sync)', 'IA Verificata', 0, 4, '2026-11-02T14:49:13.447523+00:00'),
('92fae885-fb34-4998-9895-fe83901243c0', 312, 'Segreti di produzione', 'L''uso estensivo di miniature digitali per gli esterni', 'Gran parte delle inquadrature aeree e dei complessi movimenti di macchina che mostrano i tetti di Parigi e la sequenza iniziale nei pressi del Louvre sono state realizzate combinando modellini fisici in scala ridotta con avanzati effetti visivi digitali supervisionati dalla Moving Picture Company (MPC).', 'Cinefex Magazine n. 106 - Speciale Effetti Visivi', TRUE, 'IA (Daily Sync)', 'IA Verificata', 0, 5, '2026-11-02T14:49:13.447523+00:00'),
('051c3942-e415-4f47-973e-6d7bed292901', 312, 'Citazioni & Easter Egg', 'Il cameo di Dan Brown nel prologo', 'Dan Brown, l''autore del romanzo bestseller da cui è tratto il film, e sua moglie Blythe compaiono brevemente come comparse nella primissima sequenza della conferenza stampa tenuta dal professor Robert Langdon all''inizio della pellicola.', 'Intervista speciale con Dan Brown inclusa nei contenuti extra dell''edizione home video', TRUE, 'IA (Daily Sync)', 'IA Verificata', 0, 6, '2026-11-02T14:49:13.447523+00:00'),
('2920f253-b1da-47be-b7fe-0999c534e1a1', 312, 'Segreti di produzione', 'La precisione storica nei codici e nei dipinti', 'Il dipinto della ''Vergine delle Rocce'' e le altre opere chiave di Leonardo da Vinci utilizzate come oggetti di scena non erano i dipinti originali trafugati o prestati, ma copie d''arte estremamente dettagliate e certificate realizzate appositamente da maestri falsari e pittori di scena sotto la supervisione del dipartimento artistico.', 'Production notes e intervista allo scenografo Allan Cameron', TRUE, 'IA (Daily Sync)', 'IA Verificata', 0, 7, '2026-11-02T14:49:13.447523+00:00'),
('346b4625-96b9-4850-ac7e-01abac8423f7', 321, 'Casting & Scelte', 'Il rifiuto di Sylvester Stallone', 'Prima di assegnare la parte di Stuntman Mike a Kurt Russell, Quentin Tarantino aveva pensato a Sylvester Stallone per il ruolo del killer motorizzato. L''attore declinò l''offerta a causa di conflitti di programmazione con la produzione di ''Rocky Balboa'' (2006).', 'Dichiarazioni ufficiali di Quentin Tarantino e note di casting della produzione', TRUE, 'IA (Daily Sync)', 'IA Verificata', 0, 0, '2026-11-02T14:49:57.268735+00:00'),
('748e199b-3644-4151-8566-2526e85ef7da', 321, 'Casting & Scelte', 'Rose McGowan e il provino per Planet Terror', 'Rose McGowan, che in ''Death Proof'' interpreta Pam, la sfortunata prima vittima di Stuntman Mike, era originariamente stata convocata per un provino per il film gemello ''Planet Terror'' diretto da Robert Rodriguez. Fu proprio Tarantino a volerla nel suo segmento dopo averla incontrata.', 'Audio-commentario del regista e interviste promozionali', TRUE, 'IA (Daily Sync)', 'IA Verificata', 0, 1, '2026-11-02T14:49:57.268735+00:00'),
('634f7b5c-ecea-47a3-a9b2-51f532f726dc', 321, 'Aneddoti dal set', 'La cicatrice reale di Zoë Bell', 'La vistosa cicatrice sulla gamba della stuntwoman Zoë Bell, visibile in diverse sequenze del film, non è un effetto speciale di trucco ma il risultato di un infortunio reale occorsole sul set di un precedente progetto cinematografico.', 'Making-of ufficiale e note di produzione di Grindhouse', TRUE, 'IA (Daily Sync)', 'IA Verificata', 0, 2, '2026-11-02T14:49:57.268735+00:00'),
('87c49f4b-9ef0-4971-ab3c-ac62cab4b6ea', 321, 'Citazioni & Easter Egg', 'L''ispirazione da Super Van', 'La scena in cui Stuntman Mike fissa intensamente le ragazze nel locale e la dinamica generale del suo pedinamento omicida traggono ispirazione diretta dal film di exploitation degli anni ''70 ''Super Van'' (1977) e da altri classici minori del genere car-sploitation.', 'Note di regia e interviste d''archivio di Tarantino sulla genesi del film', TRUE, 'IA (Daily Sync)', 'IA Verificata', 0, 3, '2026-11-02T14:49:57.268735+00:00'),
('7ee592d0-575d-4502-960d-ac09d58b424c', 321, 'Casting & Scelte', 'Il cameo del figlio di Kurt Russell', 'Nella scena del ristorante, tra i clienti presenti sullo sfondo compare anche Wyatt Russell, figlio di Kurt Russell, inserito nel cast in un piccolo ruolo non accreditato come comparsa.', 'Acccrediti minori e approfondimenti sul cast di produzione', TRUE, 'IA (Daily Sync)', 'IA Verificata', 0, 4, '2026-11-02T14:49:57.268735+00:00'),
('b7f6f641-948e-43b3-845c-7d0e154fbf2f', 321, 'Segreti di produzione', 'La finta scomparsa della pellicola', 'Per accentuare l''effetto di un film di seconda visione recuperato fortunosamente, Tarantino ha inserito intenzionalmente il celebre cartello ''Missing Reel'' (Bobina mancante) tra il primo e il secondo tempo, simulando l''usura fisica e la negligenza dei vecchi proiettori da drive-in.', 'Analisi tecnica della proiezione originale di Grindhouse', TRUE, 'IA (Daily Sync)', 'IA Verificata', 0, 5, '2026-11-02T14:49:57.268735+00:00'),
('dc3a8c3b-95e6-4745-ac09-20269b8d9ce0', 313, 'Casting & Scelte', 'Il taglio della barba di Tom Hanks', 'Ron Howard e Tom Hanks decisero di dare un taglio più moderno e dinamico al professor Robert Langdon rispetto al primo film, eliminando i capelli lunghi che avevano generato non poche ironie in ''Il codice Da Vinci''.', 'Intervista stampa a Ron Howard e Tom Hanks', TRUE, 'IA (Daily Sync)', 'IA Verificata', 0, 2, '2026-11-02T14:49:17.5795+00:00'),
('63304e06-967e-4ae3-93e8-cc709988a453', 313, 'Curiosità & Retroscena', 'Il divieto della CEI', 'La Conferenza Episcopale Italiana (CEI) espresse una ferma condanna preventiva definendo la pellicola un''operazione commerciale astuta e provocatoria, vietando di fatto qualsiasi supporto logistico ecclesiastico alle troupes.', 'Comunicato ufficiale CEI e rassegna stampa 2009', TRUE, 'IA (Daily Sync)', 'IA Verificata', 0, 3, '2026-11-02T14:49:17.5795+00:00'),
('cb112bc9-ed07-476c-a69f-cf05f6561b46', 313, 'Costumi & Scenografia', 'L''uso dei costumi reali per le comparse cardinalizie', 'La costumista Daniel Gropius ha dovuto attingere a storiche sartorie teatrali romane per realizzare gli abiti talari e le porpore cardinalizie, studiando i codici ecclesiastici per evitare errori grossolani nel Conclave.', 'Note di produzione e intervista a Daniel Gropius', TRUE, 'IA (Daily Sync)', 'IA Verificata', 0, 4, '2026-11-02T14:49:17.5795+00:00'),
('447aeda8-3e86-4d3f-8fcd-6c2c947b2027', 317, 'Aneddoti dal set', 'La preparazione acrobatica di Dash Mihok', 'L''attore Dash Mihok, che interpreta il leader dei Darkseekers, ha dovuto seguire un rigoroso allenamento di parkour e contorsionismo per muoversi in modo innaturale e bestiale, dato che i suoi movimenti dovevano risultare completamente slegati dalla biomeccanica umana tradizionale.', 'Special contenuto nel DVD ''Creating I Am Legend''', TRUE, 'IA (Daily Sync)', 'IA Verificata', 0, 0, '2026-11-02T14:49:36.457615+00:00'),
('3ebc9771-cd8d-49d4-ac6c-80814a544f6b', 317, 'Casting & Scelte', 'La cancellazione del look iniziale di Emma Thompson', 'Emma Thompson appare in un cameo non accreditato nei panni della scienziata che spiega l''origine del virus mutato nel prologo, una sequenza girata in gran segreto e aggiunta dopo che i test di screening richiesero una spiegazione più scientifica e immediata dell''apocalisse.', 'Note di produzione Warner Bros.', TRUE, 'IA (Daily Sync)', 'IA Verificata', 0, 1, '2026-11-02T14:49:36.457615+00:00'),
('b3f034e9-1b92-4aed-92be-cbf9663827f6', 317, 'Segreti di produzione', 'Il cane Abbey e l''addestramento speciale', 'La pastore tedesco Abbey fu scelta tra decine di cani non solo per la sua intelligenza, ma perché aveva un''incredibile capacità di rimanere immobile e concentrata in mezzo al caos dei set digitali, seguendo i comandi silenziosi del suo addestratore Steve Berens nascosto appena fuori campo.', 'Intervista all''addestratore Steve Berens per People Magazine', TRUE, 'IA (Daily Sync)', 'IA Verificata', 0, 2, '2026-11-02T14:49:36.457615+00:00'),
('c3aab10b-a1f0-4c58-b87a-38ba5ac865c3', 317, 'Curiosità & Retroscena', 'L''ispirazione visiva da The Last Man on Earth', 'Il regista Francis Lawrence e il direttore della fotografia Andrew Lesnie hanno studiato attentamente le inquadrature del primo adattamento cinematografico del romanzo, ''L''ultimo uomo sulla Terra'' (1964) con Vincent Price, per replicare il senso di claustrofobia e solitudine urbana.', 'Commento audio del regista Francis Lawrence', TRUE, 'IA (Daily Sync)', 'IA Verificata', 0, 3, '2026-11-02T14:49:36.457615+00:00'),
('599245c3-2c2e-46cf-9493-7a8ecf55e0f4', 214, 'Casting & Scelte', 'Christian Bale e Leonardo DiCaprio inizialmente considerati', 'Nelle prime fasi di sviluppo del progetto, quando il film doveva essere diretto da Bryan Singer e poi da Antoine Fuqua, erano stati associati i nomi di Christian Bale e Leonardo DiCaprio per i ruoli principali prima che la produzione passasse a Denis Villeneuve.', 'Report di Deadline e Variety sulle fasi di sviluppo del film', TRUE, 'IA (Daily Sync)', 'IA Verificata', 0, 1, '2026-11-02T15:47:12.392412+00:00'),
('f24ae030-5c3e-49a6-b0c3-eb923820417d', 317, 'Casting & Scelte', 'La sequenza del ponte di Brooklyn tagliata', 'La costosissima sequenza iniziale del flashback dell''evacuazione di Manhattan sul ponte di Brooklyn, costata diversi milioni di dollari e sei giorni di riprese notturne, fu quasi interamente rielaborata perché non trasmetteva la giusta scala di panico voluta dal regista.', 'Making-of ufficiale ''The Making of I Am Legend''', TRUE, 'IA (Daily Sync)', 'IA Verificata', 0, 5, '2026-11-02T14:49:36.457615+00:00'),
('62a6bad3-5680-464a-88f4-ccd4646207f1', 353, 'Segreti di produzione', 'Il supporto logistico reale della Federal Express', 'La vera Federal Express fornì non solo velivoli, furgoni e uniformi autentiche per le riprese, ma permise alla produzione di girare direttamente all''interno del vero hub centrale di Memphis, il SuperHub, durante le reali operazioni notturne.', 'Note di produzione ufficiali della 20th Century Fox e DreamWorks', TRUE, 'IA (Daily Sync)', 'IA Verificata', 0, 2, '2026-11-02T14:52:05.662879+00:00'),
('56a98bb0-b86f-4d36-95ee-77be5c978403', 214, 'Casting & Scelte', 'I tatuaggi e i manierismi scelti da Jake Gyllenhaal', 'Il detective Loki ha molti tatuaggi massonici e indossa anelli particolari: è stata un''idea specifica di Jake Gyllenhaal per dare un passato misterioso e un profilo psicologico insolito a un poliziotto di provincia dedito al lavoro.', 'Intervista audio al commento del regista e interviste promozionali all''attore', TRUE, 'IA (Daily Sync)', 'IA Verificata', 0, 2, '2026-11-02T15:47:12.392412+00:00'),
('fc66401e-f2f8-45f6-a844-053a9a5108da', 353, 'Citazioni & Easter Egg', 'Il cameo vocale nascosto di registi e produttori', 'Nella sequenza iniziale all''interno dell''hub FedEx di Memphis, alcune delle voci concitate degli operatori radio e dei controllori di volo che coordinano le spedizioni appartengono a membri minori della troupe e produttori esecutivi.', 'Trivia track dell''edizione speciale in DVD', TRUE, 'IA (Daily Sync)', 'IA Verificata', 0, 4, '2026-11-02T14:52:05.662879+00:00');
INSERT INTO public.movie_trivia ("id", "film_id", "categoria", "titolo", "descrizione", "fonte", "approvato", "inserito_da", "provenienza", "likes", "ordine", "created_at") VALUES
('a8a25f4b-e354-45c1-a5d7-859e001866d4', 353, 'Casting & Scelte', 'La scelta della location e l''assenza di fauna pericolosa', 'L''atollo di Monuriki fu scelto dalla produzione non solo per la sua bellezza incontaminata, ma anche perché privo di serpenti velenosi o grandi predatori, riducendo al minimo i rischi assicurativi per la troupe e per l''attore protagonista.', 'Intervista al location manager James M. Vance', TRUE, 'IA (Daily Sync)', 'IA Verificata', 0, 5, '2026-11-02T14:52:05.662879+00:00'),
('81c24eea-160d-4325-baa8-baf92fd37f1b', 353, 'Segreti di produzione', 'Il coordinamento dei movimenti con la troupe di animazione', 'Robert Zemeckis sfruttò la pausa di un anno delle riprese per dirigere la post-produzione di ''Le verità nascoste'', mantenendo tuttavia attivi alcuni reparti di grafica per simulare digitalmente l''avanzamento dei mesi sull''isola di Chuck.', 'Rivista cinematografica ''American Cinematographer''', TRUE, 'IA (Daily Sync)', 'IA Verificata', 0, 6, '2026-11-02T14:52:05.662879+00:00'),
('66ec3f6d-a85a-4189-a3bc-b8568198d8c1', 353, 'Citazioni & Easter Egg', 'Il tributo ai classici della sopravvivenza', 'La sequenza in cui Chuck accende il fuoco per la prima volta urlando trionfante ''I have made fire!'' è un esplicito omaggio ai tropi cinematografici dei film sui naufraghi degli anni ''30 e ''40, reinterpretato in chiave realistica.', 'Analisi critica di Roger Ebert sul film', TRUE, 'IA (Daily Sync)', 'IA Verificata', 0, 7, '2026-11-02T14:52:05.662879+00:00'),
('463485ee-c2ff-4b0e-bd2a-d9ee4c2b11fc', 214, 'Casting & Scelte', 'Il tic nervoso del battito di ciglia ideato da Gyllenhaal', 'Sempre Jake Gyllenhaal ha deciso che il suo personaggio dovesse avere un tic nervoso visivo, inserendo un frequente battito di ciglia e sguardi tesi per riflettere lo stress cronico e la mancanza di sonno del detective.', 'Intervista a Jake Gyllenhaal per la promozione del film', TRUE, 'IA (Daily Sync)', 'IA Verificata', 0, 3, '2026-11-02T15:47:12.392412+00:00'),
('4787a62f-55e5-4674-8c72-4e6839a8d988', 214, 'Aneddoti dal set', 'Il metodo di Paul Dano per l''isolamento sul set', 'Per mantenere la tensione e la giusta alienazione del suo personaggio Alex Jones, Paul Dano evitava spesso di socializzare con il resto del cast durante le pause tra una ripresa e l''altra, rimanendo concentrato nella sua roulotte.', 'Dietro le quinte e interviste al cast', TRUE, 'IA (Daily Sync)', 'IA Verificata', 0, 4, '2026-11-02T15:47:12.392412+00:00'),
('e7fa561a-5e04-4cf3-8ab4-16a05fe3fe09', 314, 'Curiosità & Retroscena', 'La genesi della sceneggiatura di Nick Schenk', 'Lo sceneggiatore Nick Schenk scrisse la storia ambientandola originariamente a Minneapolis, attingendo alla sua profonda conoscenza della comunità Hmong locale. Quando la sceneggiatura arrivò alla Malpaso Productions di Clint Eastwood, il regista decise di spostare l''ambientazione a Detroit per sfruttare lo sfondo industriale in declino.', 'Note di produzione ufficiali Warner Bros.', TRUE, 'IA (Daily Sync)', 'IA Verificata', 0, 0, '2026-11-02T14:49:21.855558+00:00'),
('628ff810-d4eb-4d2c-88f7-4f58321d2120', 314, 'Aneddoti dal set', 'Il doppiaggio originale e la parlata gergale', 'Clint Eastwood concesse ai giovani attori esordienti della comunità Hmong una notevole libertà nell''adattare i dialoghi della sceneggiatura per renderli più realistici e aderenti al modo di parlare dei veri adolescenti dei sobborghi di Detroit.', 'Intervista al cast nel documentario ''Gran Torino: More Than a Movie''', TRUE, 'IA (Daily Sync)', 'IA Verificata', 0, 1, '2026-11-02T14:49:21.855558+00:00'),
('7a63d06d-f42f-43c4-96e6-56f969e5e3bf', 314, 'Casting & Scelte', 'Il rifiuto iniziale di interpretare Walt', 'Inizialmente Clint Eastwood aveva dichiarato alla stampa di essere troppo anziano per interpretare il ruolo del reduce della guerra di Corea Walt Kowalski, ma riconsiderò la sua decisione quando si rese conto che nessun altro attore avrebbe potuto incarnare quel particolare tipo di mascolinità ferita.', 'Intervista di Clint Eastwood a Entertainment Weekly (2008)', TRUE, 'IA (Daily Sync)', 'IA Verificata', 0, 2, '2026-11-02T14:49:21.855558+00:00'),
('8dd87f8e-b1f5-462a-8984-4fb260c8da25', 314, 'Casting & Scelte', 'L''uso dei veri veterani di guerra', 'Per conferire maggiore autenticità alle scene del quartiere e della chiesa, la produzione ingaggiò diversi veri veterani della guerra di Corea come comparse e consulenti per il comportamento di Walt Kowalski.', 'Commento audio del regista all''edizione Blu-ray', TRUE, 'IA (Daily Sync)', 'IA Verificata', 0, 3, '2026-11-02T14:49:21.855558+00:00'),
('b88daacd-58ed-4fb4-9f80-b85debbedd02', 314, 'Aneddoti dal set', 'La scelta del barbiere locale', 'La celebre scena in cui Walt insegna al giovane Thao come insultare i propri amici usando il gergo da barbiere fu provata pochissime volte; Eastwood preferì mantenere il tono spontaneo e le reazioni genuine degli attori non professionisti.', 'Special ''The Eastwood Factor''', TRUE, 'IA (Daily Sync)', 'IA Verificata', 0, 4, '2026-11-02T14:49:21.855558+00:00'),
('a9d0afea-7f0e-4498-ba75-fe53cac390d7', 316, 'Curiosità & Retroscena', 'L''ispirazione reale dello sceneggiatore', 'Lo sceneggiatore Mark Boal ha trascorso due settimane nel 2004 in Iraq come giornalista embedded con una vera squadra EOD (Explosive Ordnance Disposal), basando direttamente il personaggio di William James sulle esperienze e sulla personalità del sergente Jeffrey Sarver.', 'Note di produzione e interviste ufficiali a Mark Boal', TRUE, 'IA (Daily Sync)', 'IA Verificata', 0, 0, '2026-11-02T14:49:31.911932+00:00'),
('bd9cb76d-09d8-4110-a430-9de7c90849dd', 316, 'Casting & Scelte', 'Il contenzioso legale con il vero sergente', 'Il sergente Jeffrey Sarver ha citato in giudizio i produttori del film sostenendo che il protagonista William James fosse chiaramente basato su di lui e che la pellicola lo avesse danneggiato, ma la causa è stata successivamente respinta dai tribunali.', 'Archivio legale e testate giornalistiche internazionali', TRUE, 'IA (Daily Sync)', 'IA Verificata', 0, 1, '2026-11-02T14:49:31.911932+00:00'),
('24d43e1c-75c6-4616-8054-f8506a02726b', 316, 'Curiosità & Retroscena', 'La causa per il merchandising degli Oscar', 'Uno dei produttori del film, Nicolas Chartier, è stato temporaneamente bandito dalla cerimonia degli Oscar del 2010 dall''Academy dopo aver inviato email ai membri votanti sollecitandoli a non votare per ''un film da 500 milioni di dollari'' (chiaro riferimento ad Avatar), violando le regole di lobbying.', 'Comunicato ufficiale dell''Academy Awards (AMPAS)', TRUE, 'IA (Daily Sync)', 'IA Verificata', 0, 2, '2026-11-02T14:49:31.911932+00:00'),
('ec8dd653-bd59-4a70-8c19-520a0901ab66', 316, 'Aneddoti dal set', 'La troupe in pericolo reale', 'Durante le riprese in Giordania, la troupe ha dovuto affrontare tensioni geopolitiche locali e la presenza di rifugiati iracheni, tanto che alcuni membri della produzione furono avvicinati e minacciati da gruppi di estremisti locali prima che la sicurezza venisse drasticamente rafforzata.', 'Special report e documentario sul backstage del DVD', TRUE, 'IA (Daily Sync)', 'IA Verificata', 0, 3, '2026-11-02T14:49:31.911932+00:00'),
('94abd431-bdf0-4964-af60-a6429660c8d7', 316, 'Segreti di produzione', 'L''addestramento militare intensivo', 'Prima dell''inizio delle riprese, Jeremy Renner, Anthony Mackie e Brian Geraghty sono stati sottoposti a un addestramento militare intensivo di due settimane a Fort Irwin, in California, sotto la supervisione di veri operatori delle forze speciali e veterani della guerra in Iraq.', 'Audio commento del regista e degli attori', TRUE, 'IA (Daily Sync)', 'IA Verificata', 0, 4, '2026-11-02T14:49:31.911932+00:00'),
('5bf6c8c8-a648-4826-816a-e42ee7f64b05', 316, 'Effetti speciali & Trucco', 'L''uso della pellicola Super 16mm', 'Il direttore della fotografia Barry Ackroyd ha girato gran parte del film in pellicola Super 16mm con cineprese a mano, una scelta tecnica voluta per conferire all''immagine una grana marcata e un''estetica cruda, simile a un reportage di guerra televisivo.', 'American Cinematographer Magazine', TRUE, 'IA (Daily Sync)', 'IA Verificata', 0, 5, '2026-11-02T14:49:31.911932+00:00'),
('522f21f8-6c74-4462-8cb7-84219968f209', 316, 'Segreti di produzione', 'Il budget ridotto e le difficoltà logistiche', 'Con un budget di soli 15 milioni di dollari, la produzione ha dovuto girare in location estremamente ostili vicino al confine siriano e iracheno, utilizzando generatori diesel spesso inaffidabili e affrontando frequenti interruzioni dovute a tempeste di sabbia.', 'Diario di produzione di Kathryn Bigelow', TRUE, 'IA (Daily Sync)', 'IA Verificata', 0, 6, '2026-11-02T14:49:31.911932+00:00'),
('0a0baa67-5b68-42e1-b327-8d9d239ec5b2', 316, 'Casting & Scelte', 'Il casting mancato di Willem Dafoe', 'Prima che il ruolo del colonnello Reed venisse affidato a David Morse e che altri attori di calibro entrassero nel cast di supporto, la produzione aveva valutato diversi interpreti di fama internazionale tra cui Willem Dafoe per piccoli ruoli di comando.', 'Report di casting preliminare della produzione', TRUE, 'IA (Daily Sync)', 'IA Verificata', 0, 7, '2026-11-02T14:49:31.911932+00:00'),
('78f53d78-6a46-4a1d-8166-4acaad2d778a', 316, 'Aneddoti dal set', 'La gestione del caldo estremo sul set', 'Durante le scene nel deserto giordano, le temperature superavano regolarmente i 45 gradi Celsius; gli attori indossavano tubi di raffreddamento ad acqua sotto le pesanti tute antinfortunistiche per evitare colpi di calore durante le riprese delle lunghe sequenze di disinnesco.', 'Interviste promozionali del cast principale', TRUE, 'IA (Daily Sync)', 'IA Verificata', 0, 8, '2026-11-02T14:49:31.911932+00:00'),
('5202f99d-5cb8-4d59-9628-a62d8560eb37', 355, 'Casting & Scelte', 'La coincidenza della chiamata di Bruce Willis', 'M. Night Shyamalan stava completando la stesura della sceneggiatura quando ricevette una telefonata inaspettata da Bruce Willis, il quale aveva appena visto ''The Sixth Sense'' e voleva assolutamente lavorare di nuovo con lui, portando il regista a offrirgli direttamente la parte di David Dunn.', 'Commento audio del regista nel DVD ufficiale', TRUE, 'IA (Daily Sync)', 'IA Verificata', 0, 0, '2026-11-02T14:52:12.398873+00:00'),
('324a881c-3374-4960-b228-aa13735d4c1f', 355, 'Citazioni & Easter Egg', 'Il cameo della figlia del regista', 'Saleka Shyamalan, la figlia maggiore di M. Night Shyamalan, fa una breve apparizione nel film interpretando la bambina allo stadio che chiede alla madre di far fare l''autunno al padre, una scena che riflette il tema familiare centrale del film.', 'Crediti del film e note di produzione', TRUE, 'IA (Daily Sync)', 'IA Verificata', 0, 1, '2026-11-02T14:52:12.398873+00:00'),
('361a71f6-f386-4e6c-b71a-bb308e5386bc', 315, 'Curiosità & Retroscena', 'La colonna sonora rifiutata di Eddie Van Halen', 'Il leggendario chitarrista Eddie Van Halen aveva composto e registrato gratuitamente una versione originale del tema principale del film per amicizia verso Mickey Rourke. Tuttavia, a causa di una complessa disputa legale tra la casa di distribuzione e la gestione dei diritti musicali di Van Halen, il brano fu scartato all''ultimo minuto.', 'Intervista ufficiale di Darren Aronofsky', TRUE, 'IA (Daily Sync)', 'IA Verificata', 0, 0, '2026-11-02T14:49:26.12126+00:00'),
('c5d9328f-d2c5-44a5-9a5c-b3b78cfdc455', 315, 'Curiosità & Retroscena', 'L''invenzione del brano dei Guns N'' Roses', 'Axl Rose e i Guns N'' Roses concessero eccezionalmente alla produzione l''uso della canzone inedita ''The Wrestler'' per i titoli di coda, dopo che Mickey Rourke in persona aveva supplicato il cantante (con cui aveva un rapporto di amicizia) di scrivere un pezzo appositamente per il film. La canzone ottenne anche una candidatura ai Golden Globe.', 'Note di produzione e interviste al cast', TRUE, 'IA (Daily Sync)', 'IA Verificata', 0, 1, '2026-11-02T14:49:26.12126+00:00'),
('0fefcabf-4261-4e3d-962a-15f0470438bb', 315, 'Segreti di produzione', 'L''ispirazione visiva dai documenti di Albert Maysles', 'Il regista Darren Aronofsky e la direttrice della fotografia Maryse Alberti hanno studiato a fondo i documentari di Albert e David Maysles, in particolare ''Salesman'', per catturare uno stile di ripresa grezzo, in stile cinema-verité, che seguisse costantemente Mickey Rourke da vicino con la macchina a spalla.', 'Commento audio del DVD e masterclass di regia', TRUE, 'IA (Daily Sync)', 'IA Verificata', 0, 2, '2026-11-02T14:49:26.12126+00:00'),
('c5fce9d1-1821-44e4-a351-df3e35b248af', 315, 'Casting & Scelte', 'Il cameo mancato di Hulk Hogan', 'Inizialmente la produzione aveva pensato di coinvolgere vere icone del wrestling degli anni Ottanta come Hulk Hogan o Roddy Piper per dei camei significativi all''interno del film. Tuttavia, i rifiuti dei lottatori storici spinsero Aronofsky a puntare su un cast di veri lottatori del circuito indipendente ed ex stelle minori come Ernest ''The Cat'' Miller.', 'The Hollywood Reporter - Retrospettiva sulla produzione', TRUE, 'IA (Daily Sync)', 'IA Verificata', 0, 3, '2026-11-02T14:49:26.12126+00:00'),
('aaa69a25-2d05-4026-a5ab-6d641985fc4e', 315, 'Aneddoti dal set', 'Il vero svenimento di Mickey Rourke sul ring', 'Durante le riprese del match hardcore contro il lottatore Necro Butcher, Mickey Rourke fu colpito accidentalmente con una sedia d''acciaio e riportò un principio di commozione cerebrale unito a un forte stato di disidratazione, svenendo temporaneamente dietro le quinte prima di riprendere le riprese.', 'Intervista a Necro Butcher e report dal set', TRUE, 'IA (Daily Sync)', 'IA Verificata', 0, 4, '2026-11-02T14:49:26.12126+00:00'),
('b01cba2d-4bad-466c-99a3-e770df366a78', 315, 'Aneddoti dal set', 'La scelta della sala giochi arcade', 'La sequenza in cui Randy lavora al bancone di un supermercato e gioca a un cabinato arcade retrò è stata girata in un vero negozio di alimentari nel New Jersey, e molti dei clienti presenti durante la scena erano ignari residenti locali e non comparse professioniste reclutate dalla produzione.', 'Diario di bordo della troupe e Making-of', TRUE, 'IA (Daily Sync)', 'IA Verificata', 0, 5, '2026-11-02T14:49:26.12126+00:00'),
('c0fd1009-934e-41a1-848f-f9e34c92845b', 355, 'Aneddoti dal set', 'L''infortunio di Samuel L. Jackson prima delle riprese', 'Poco prima dell''inizio delle riprese, Samuel L. Jackson subì un intervento chirurgico alla spalla che rese particolarmente complessa la gestione dei costumi e richiese l''uso di tutori nascosti per mantenere la postura rigida e fragile di Elijah Price.', 'Intervista promozionale a Samuel L. Jackson', TRUE, 'IA (Daily Sync)', 'IA Verificata', 0, 2, '2026-11-02T14:52:12.398873+00:00'),
('3591f7b1-2b92-45eb-a42d-ae126791afe0', 355, 'Segreti di produzione', 'L''ispirazione per la galleria d''arte di Elijah', 'La galleria di fumetti rari gestita da Elijah Price, la ''Limited Edition'', è stata interamente allestita utilizzando pezzi da collezione autentici e tavole originali fornite da celebri collezionisti di fumetti americani per garantire il massimo realismo visivo.', 'Special ''The Making of Unbreakable'' sul disco Blu-ray', TRUE, 'IA (Daily Sync)', 'IA Verificata', 0, 3, '2026-11-02T14:52:12.398873+00:00'),
('1c9a53b0-b734-4f81-aa49-4f59a5f54024', 355, 'Citazioni & Easter Egg', 'Il cameo del regista nei panni dello spacciatore', 'Come d''abitudine nei suoi film, M. Night Shyamalan appare in un cameo: in ''Unbreakable'' interpreta lo spettatore che viene perquisito da David Dunn ai controlli di sicurezza dello stadio e che si rivela essere uno spacciatore di droga.', 'Analisi visiva e cameo ufficiali di M. Night Shyamalan', TRUE, 'IA (Daily Sync)', 'IA Verificata', 0, 4, '2026-11-02T14:52:12.398873+00:00'),
('b238cc15-17ab-4033-9b1a-8d1fdaff81ce', 355, 'Aneddoti dal set', 'La scena dello stadio girata con veri tifosi', 'La sequenza in cui David Dunn cammina tra la folla nello stadio di football è stata girata dal vivo durante una vera partita dei Philadelphia Eagles, sfruttando la naturale confusione degli spettatori inconsapevoli della presenza delle telecamere nascoste.', 'Dietro le quinte e note di produzione della Touchstone Pictures', TRUE, 'IA (Daily Sync)', 'IA Verificata', 0, 5, '2026-11-02T14:52:12.398873+00:00'),
('9f89adb0-8d3f-41fb-8fc3-7a3621155a89', 355, 'Segreti di produzione', 'L''uso dei riflessi speculari per presagire il destino', 'Il direttore della fotografia Eduardo Serra ha fatto ampio uso di vetri, finestre e specchi per comporre le inquadrature, inserendo costantemente riflessi sovrapposti per simboleggiare la doppia identità segreta del protagonista prima ancora che ne prenda piena coscienza.', 'Articolo di American Cinematographer sulla fotografia del film', TRUE, 'IA (Daily Sync)', 'IA Verificata', 0, 6, '2026-11-02T14:52:12.398873+00:00'),
('225d3263-e646-4a35-84ea-693e4c92bc5f', 134, 'Aneddoti dal set', 'La morte sfiorata di Burgess Meredith', 'Durante la lavorazione del film, l''attore Burgess Meredith, all''epoca settantaquattrenne e gravemente malato di cancro ai polmoni (malattia tenuta nascosta al pubblico e alla produzione per gran parte delle riprese), ebbe un collasso sul set a causa dello sforzo fisico richiesto per le scene drammatiche con Stallone. Le sue condizioni di salute erano così precarie che le riprese delle sue sequenze dovettero essere concentrate nel minor tempo possibile.', 'Autobiografia di Sylvester Stallone e documentari d''archivio MGM', TRUE, 'IA (Daily Sync)', 'IA Verificata', 0, 0, '2026-11-02T10:05:03.284836+00:00'),
('8cb084f3-b2e0-47d0-b5b0-d9edeb329f27', 145, 'Casting & Scelte', 'Il provino di Steve Buscemi per Mr. Pink', 'Steve Buscemi lesse originariamente la parte di Mr. Pink, ma Quentin Tarantino lo aveva pensato inizialmente per interpretare Mr. Blonde o persino per se stesso nel ruolo di Mr. Pink. Fu solo dopo un''insistente richiesta di provino che Tarantino comprese che Buscemi era perfetto per il ruolo dello scettico criminale che rifiuta di lasciare la mancia.', 'Commento audio del regista e documentario retrospettivo del DVD', TRUE, 'IA (Daily Sync)', 'IA Verificata', 0, 0, '2026-11-02T14:53:30.834923+00:00'),
('9a39c2db-edce-4c8d-afe6-6d52c60ea30b', 145, 'Aneddoti dal set', 'La tensione reale tra Lawrence Tierney e Quentin Tarantino', 'Lawrence Tierney, veterano di Hollywood che interpretava Joe Cabot, aveva un carattere estremamente rissoso e difficile sul set, arrivando quasi alle mani con Quentin Tarantino dopo che il regista lo aveva paragonato a Marlon Brando. Tarantino ha spesso raccontato di aver temuto che la produzione deragliasse a causa dei continui scatti d''ira dell''anziano attore.', 'Interviste di produzione e documentario ''Playing with Fire''', TRUE, 'IA (Daily Sync)', 'IA Verificata', 0, 1, '2026-11-02T14:53:30.834923+00:00'),
('7d231a39-83e8-43e5-8b5a-3e71bc5aa2f1', 145, 'Curiosità & Retroscena', 'La voce fuori campo di Steven Wright come DJ', 'La voce del DJ radiofonico della stazione fittizia K-Billy ''Super Sounds of the Seventies'', che accompagna le sequenze musicali del film, appartiene al celebre comico e attore statunitense Steven Wright, noto per il suo umorismo surreale e monocorde.', 'Note di produzione ufficiali e crediti del film', TRUE, 'IA (Daily Sync)', 'IA Verificata', 0, 2, '2026-11-02T14:53:30.834923+00:00'),
('8e27690d-4095-4a0b-9fe7-89b8ebc821de', 320, 'Effetti speciali & Trucco', 'Le maschere funerarie autentiche', 'Gli oggetti di scena legati ai rituali religiosi e le grandi maschere indossate dai sacerdoti Maya sono stati scolpiti a mano da artigiani locali basandosi su reperti archeologici custoditi nei musei di Città del Messico.', 'Featurette sul reparto scenografia del DVD', TRUE, 'IA (Daily Sync)', 'IA Verificata', 0, 7, '2026-11-02T14:49:52.16647+00:00'),
('2b7865b3-324a-4aea-a497-08be5c568c6d', 356, 'Casting & Scelte', 'La scelta casuale di Carrie-Anne Moss', 'Carrie-Anne Moss ottenne la parte di Natalie quasi per caso grazie all''insistenza del suo agente, fresco del successo planetario di ''Matrix'' (1999). L''attrice completò tutte le sue scene in appena otto giorni di lavorazione a causa del budget estremamente ridotto.', 'Commento audio del regista nel DVD ufficiale di Memento', TRUE, 'IA (Daily Sync)', 'IA Verificata', 0, 0, '2026-11-02T14:52:16.743358+00:00'),
('3ad15e5d-042b-4c74-b9ba-c50eff669393', 356, 'Casting & Scelte', 'Il rifiuto di Aaron Eckhart', 'Prima che Guy Pearce fosse definitivamente ingaggiato per il ruolo principale, Christopher Nolan valutò concretamente anche Aaron Eckhart. L''attore declinò l''offerta o non si rese disponibile, spingendo la produzione a puntare su Pearce.', 'Note di produzione e casting ufficiali di Memento', TRUE, 'IA (Daily Sync)', 'IA Verificata', 0, 1, '2026-11-02T14:52:16.743358+00:00'),
('5c769d81-e5a2-440d-8e90-a96f495c19b6', 356, 'Curiosità & Retroscena', 'L''ispirazione letteraria del fratello del regista', 'La sceneggiatura del film si basa sul racconto breve ''Memento Mori'' scritto da Jonathan Nolan, fratello minore di Christopher. Jonathan ebbe l''intuizione di scrivere la storia mentre frequentava un corso di psicologia alla Georgetown University, riflettendo sui disturbi della memoria anterograda.', 'Articolo retrospettivo su The New York Times e Making-of', TRUE, 'IA (Daily Sync)', 'IA Verificata', 0, 2, '2026-11-02T14:52:16.743358+00:00'),
('81a2d5d9-950c-483b-a7c4-80523075bdd1', 356, 'Aneddoti dal set', 'La ripresa delle scene di sesso in un solo giorno', 'Le brevi e tese sequenze di intimità tra Guy Pearce e Carrie-Anne Moss vennero girate in una singola giornata di lavoro. Per mantenere il clima di tensione richiesto dal thriller, la troupe fu ridotta all''osso riducendo al minimo lo staff presente sul set.', 'Intervista al direttore della fotografia Wally Pfister', TRUE, 'IA (Daily Sync)', 'IA Verificata', 0, 3, '2026-11-02T14:52:16.743358+00:00'),
('dbdba8c3-84eb-47ca-834f-aba446f7ede7', 356, 'Segreti di produzione', 'L''uso dei Polaroid autentici', 'Le macchine fotografiche Polaroid utilizzate da Leonard nel film erano modelli d''epoca reali e funzionanti. La produzione dovette acquistare una scorta di pellicole istantanee ormai fuori produzione per garantire la continuità visiva delle foto scattate in scena.', 'Special content del Blu-ray ufficiale di Memento', TRUE, 'IA (Daily Sync)', 'IA Verificata', 0, 4, '2026-11-02T14:52:16.743358+00:00'),
('2a46da52-16c5-44f1-a4bc-7a8abae763f7', 356, 'Segreti di produzione', 'La sequenza d''apertura al contrario', 'La celebre sequenza iniziale in cui la Polaroid sbiadisce e ritorna nel caricatore fu realizzata senza l''ausilio di effetti digitali in CGI. La troupe utilizzò una combinazione di trucchi di montaggio ottico e negativi capovolti durante lo sviluppo della pellicola.', 'Diario di produzione di Christopher Nolan', TRUE, 'IA (Daily Sync)', 'IA Verificata', 0, 5, '2026-11-02T14:52:16.743358+00:00'),
('1c3ed936-2cd3-4f8c-b447-6085510c7b3d', 214, 'Aneddoti dal set', 'Le condizioni climatiche estreme in Georgia', 'Sebbene il film sia ambientato in Pennsylvania durante il Giorno del Ringraziamento, le riprese si sono svolte principalmente in Georgia all''inizio del 2013, affrontando temperature insolitamente fredde e piogge battenti che hanno reso le sequenze esterne particolarmente faticose.', 'Making-of ufficiale e note di produzione della Alcon Entertainment', TRUE, 'IA (Daily Sync)', 'IA Verificata', 0, 5, '2026-11-02T15:47:12.392412+00:00'),
('9bf53193-f990-4a84-a0b9-91a09ddd3bc7', 361, 'Segreti di produzione', 'Il costume di Leatherface impregnato di sangue finto', 'Gunnar Hansen indossò lo stesso costume per circa un mese intero di riprese senza che venisse mai lavato, a causa del budget limitato che prevedeva un solo cambio d''abito. Verso la fine delle riprese, l''odore della giacca, intrisa di sangue di bue e sudore, era diventato insopportabile per l''intero cast.', 'Intervista ufficiale a Gunnar Hansen', TRUE, 'IA (Daily Sync)', 'IA Verificata', 0, 1, '2026-11-02T14:52:35.555001+00:00'),
('ef3d0b52-3c07-4238-918b-2f08fcccbd4c', 361, 'Curiosità & Retroscena', 'La reazione scioccata della censura britannica', 'Il film fu bandito nel Regno Unito dal British Board of Film Censors (BBFC) nel 1975 e rimase nella lista dei ''video nasties'' per diversi anni, prima di ricevere un visto di censura integrale solo nel 1999.', 'Archivi ufficiali del BBFC', TRUE, 'IA (Daily Sync)', 'IA Verificata', 0, 2, '2026-11-02T14:52:35.555001+00:00'),
('87154036-a599-4fbc-a38c-c56d9e3dca12', 361, 'Effetti speciali & Trucco', 'L''uso di una vera motosega Husqvarna', 'Gunnar Hansen utilizzò una vera motosega Husqvarna modello 210 nelle scene in cui inseguiva le vittime, opportunamente modificata dalla troupe per motivi di sicurezza, sebbene il pericolo di lesioni fosse reale a causa della mancanza di controfigure.', 'Note di produzione e documentario sul set', TRUE, 'IA (Daily Sync)', 'IA Verificata', 0, 3, '2026-11-02T14:52:35.555001+00:00'),
('07ab511a-7d4d-4187-a3f7-de9a8eef9f4a', 361, 'Segreti di produzione', 'Il finanziamento tramite la Vortex, Inc.', 'Tobe Hooper, Kim Henkel e altri soci fondarono la casa di produzione Vortex, Inc. per mantenere il controllo creativo totale sul film, raccogliendo fondi personali e prestiti da piccoli investitori texani.', 'Registri di produzione della Vortex', TRUE, 'IA (Daily Sync)', 'IA Verificata', 0, 4, '2026-11-02T14:52:35.555001+00:00'),
('885b0311-a535-41e6-aab9-f83962b93b40', 361, 'Casting & Scelte', 'Il ruolo minore del co-sceneggiatore Kim Henkel come autostoppista', 'Kim Henkel, co-sceneggiatore del film insieme a Tobe Hooper, apparve anche in un piccolo cameo interpretando il ruolo di uno dei passanti alla stazione di servizio nelle prime sequenze del film.', 'Crediti del film e interviste al cast', TRUE, 'IA (Daily Sync)', 'IA Verificata', 0, 5, '2026-11-02T14:52:35.555001+00:00'),
('76e5329c-1805-44c1-885e-ee523a3074c2', 58, 'Effetti speciali & Trucco', 'La tuta per la motion capture di Bill Nighy', 'Bill Nighy non ha indossato un costume prostetico per interpretare Davy Jones, ma ha recitato con una tuta grigia per la motion capture dotata di piccoli indicatori riflettenti. L''attore ha dovuto indossare questo abito anche sul set reale insieme agli altri attori, mentre la CGI è stata interamente applicata in post-produzione dalla Industrial Light & Magic.', 'Documentario Behind the Scenes e commento audio del regista Gore Verbinski', TRUE, 'IA (Daily Sync)', 'IA Verificata', 0, 0, '2026-11-02T14:53:10.897795+00:00'),
('69516151-3bbc-4c88-a6fc-f0ba4a92780d', 58, 'Segreti di produzione', 'L''assenza dei tentacoli animatronici', 'Contrariamente alle aspettative del cast, i tentacoli facciali di Davy Jones non furono realizzati con marionette o elementi fisici sul volto di Bill Nighy. L''attore recitava con il proprio viso libero da ingombranti protesi, permettendo agli animatori della ILM di catturare fedelmente le sue micro-espressioni facciali per trasferirle digitalmente sulla creatura marina.', 'Note di produzione ufficiali della Industrial Light & Magic', TRUE, 'IA (Daily Sync)', 'IA Verificata', 0, 1, '2026-11-02T14:53:10.897795+00:00'),
('8758f7bf-b777-465e-92fd-7ef25c5aea03', 58, 'Casting & Scelte', 'Il rifiuto del ruolo di Lord Cutler Beckett da parte di Richard E. Grant', 'Prima che il ruolo di Lord Cutler Beckett fosse affidato a Tom Hollander, l''attore britannico Richard E. Grant fu preso seriamente in considerazione e contattato dai produttori per interpretare il malvagio rappresentante della Compagnia delle Indie Orientali.', 'Archivio storico dei casting Disney e di Jerry Bruckheimer', TRUE, 'IA (Daily Sync)', 'IA Verificata', 0, 2, '2026-11-02T14:53:10.897795+00:00'),
('2b7f6588-5a50-465a-a21a-878560193e88', 321, 'Citazioni & Easter Egg', 'Le targhe della morte come omaggio', 'Le targhe delle automobili guidate da Stuntman Mike (inclusa la targa ''JJZ-109'') sono un preciso omaggio cinematografico alla celebre Ford Mustang verde guidata da Steve McQueen nel cult poliziesco ''Bullitt'' del 1968.', 'Easter Egg ufficiali confermati dalla troupe e dal reparto scenografia', TRUE, 'IA (Daily Sync)', 'IA Verificata', 0, 6, '2026-11-02T14:49:57.268735+00:00'),
('6d2b5613-faea-4c5c-83f6-ef827da01b9d', 358, 'Aneddoti dal set', 'La cicatrice sul volto di Jude Law', 'Durante la brutale sequenza dell''omicidio sulla barca a remi tra Tom Ripley e Dickie Greenleaf, Jude Law fu realmente colpito inavvertitamente da Matt Damon con un remo, riportando una piccola ferita e un livido autentico che rimase visibile in alcune inquadrature successive.', 'Audio commento del regista Anthony Minghella nell''edizione DVD', TRUE, 'IA (Daily Sync)', 'IA Verificata', 0, 0, '2026-11-02T14:52:21.304326+00:00'),
('3ff135fd-f61b-46d3-a5b9-808ae04bec80', 358, 'Casting & Scelte', 'La preparazione musicale di Matt Damon al pianoforte', 'Sebbene sapesse già suonare un po'' il pianoforte, Matt Damon lavorò per mesi con un insegnante privato prima delle riprese per imparare la diteggiatura esatta del brano ''Tu vuo'' fa'' l''americano'', assicurandosi che le inquadrature ravvicinate sulle sue mani fossero perfettamente credibili.', 'Note di produzione e interviste sul set di Vanity Fair', TRUE, 'IA (Daily Sync)', 'IA Verificata', 0, 1, '2026-11-02T14:52:21.304326+00:00'),
('47450393-4a9a-44b3-b97a-2f156c9dffc4', 358, 'Casting & Scelte', 'Rosario Fiorello nel cast come cantante jazz', 'Il celebre showman italiano Rosario Fiorello fu scelto personalmente da Anthony Minghella per interpretare il ruolo del crooner e sassofonista jazz nel locale notturno, dopo che il regista lo aveva visto in televisione e ne era rimasto affascinato per la sua energia.', 'Intervista ufficiale a Rosario Fiorello per la promozione italiana del film', TRUE, 'IA (Daily Sync)', 'IA Verificata', 0, 2, '2026-11-02T14:52:21.304326+00:00'),
('09c9c2c6-bbf0-4f1b-9f6a-916ddedd16fe', 358, 'Citazioni & Easter Egg', 'L''omaggio al film originale del 1960', 'Maurice Ronet, che interpretava Dickie Greenleaf (rinominato Philippe Greenleaf) nell''adattamento cinematografico del 1960 ''Delitto in pieno sole'' (Plein soleil) con Alain Delon, fa un cameo nel film nel ruolo di un ospite anziano a teatro.', 'Curiosità ufficiali dai crediti e dall''archivio di produzione della Paramount Pictures', TRUE, 'IA (Daily Sync)', 'IA Verificata', 0, 3, '2026-11-02T14:52:21.304326+00:00'),
('87afdfa7-1299-4c4f-bedd-8e9bab9eb940', 358, 'Curiosità & Retroscena', 'La voce cantata di Matt Damon', 'Nelle sequenze in cui Tom Ripley canta accompagnandosi al piano, Matt Damon ha eseguito personalmente i brani vocali, registrando la sua parte dal vivo durante le riprese della scena anziché doppiarla in studio in un secondo momento.', 'Note tecniche del reparto sonoro nel making-of ufficiale', TRUE, 'IA (Daily Sync)', 'IA Verificata', 0, 4, '2026-11-02T14:52:21.304326+00:00'),
('08eaddd2-2198-456c-a215-fab5436c2937', 360, 'Casting & Scelte', 'L''ispirazione per il personaggio di Cole Sear', 'M. Night Shyamalan ha dichiarato in diverse interviste che la costruzione psicologica del giovane Cole Sear traeva ispirazione anche dalle proprie paure infantili e dalle storie di fantasmi che ascoltava da bambino a Filadelfia, unendo elementi biografici alla struttura del thriller psicologico.', 'Audio commento del regista e note di produzione ufficiali del DVD', TRUE, 'IA (Daily Sync)', 'IA Verificata', 0, 0, '2026-11-02T14:52:30.687684+00:00'),
('4030a78a-1168-4675-a036-1678b50bf292', 360, 'Segreti di produzione', 'Il rifiuto iniziale della Disney', 'Prima che la Touchstone Pictures (marchio Disney) distribuisse il film, la sceneggiatura fu inizialmente rifiutata da David Hoberman della Walt Disney Pictures, il quale considerava il testo troppo cupo e privo del potenziale commerciale necessario per un grande pubblico.', 'Documentario retrospettivo sulla produzione e biografia di M. Night Shyamalan', TRUE, 'IA (Daily Sync)', 'IA Verificata', 0, 1, '2026-11-02T14:52:30.687684+00:00'),
('fba2709d-4c78-4b28-a62f-3e640d8b46f4', 360, 'Citazioni & Easter Egg', 'Il nome della chiesa nel climax', 'La chiesa in cui si svolgono alcune scene chiave del film è intitolata a Sant''Agostino, un chiaro richiamo sotterraneo alle tematiche della fede, del perdono e della redenzione che pervadono l''intera opera di Shyamalan.', 'Analisi visiva e dizionario dei luoghi del set', TRUE, 'IA (Daily Sync)', 'IA Verificata', 0, 2, '2026-11-02T14:52:30.687684+00:00'),
('df5f4688-2e45-4db7-a6e2-82c07314e512', 360, 'Casting & Scelte', 'La scelta di Olivia Williams', 'Per il ruolo di Anna Crowe, la moglie trascurata del protagonista, M. Night Shyamalan scelse l''attrice britannica Olivia Williams dopo aver visionato centinaia di provini, colpito in particolare dalla sua capacità di esprimere una profonda malinconia senza pronunciare alcuna battuta.', 'Note di casting del produttore Frank Marshall', TRUE, 'IA (Daily Sync)', 'IA Verificata', 0, 3, '2026-11-02T14:52:30.687684+00:00'),
('8fd1a366-3b74-4550-9892-467e449f18ab', 360, 'Aneddoti dal set', 'Il ritardo della proiezione di prova', 'Durante le prime proiezioni di prova destinate al pubblico, i dirigenti dello studio erano così terrorizzati che il colpo di scena finale potesse essere intuito troppo presto che imposero piccoli tagli nel montaggio della sequenza iniziale all''interno della cantina.', 'Intervista al montatore Andrew Mondshein', TRUE, 'IA (Daily Sync)', 'IA Verificata', 0, 4, '2026-11-02T14:52:30.687684+00:00'),
('5ab44196-6fe7-45fc-8194-60ca7e8a301a', 360, 'Citazioni & Easter Egg', 'L''omaggio a L''esorcista', 'La celebre sequenza della cucina in cui i mobili si muovono e gli oggetti cadono misteriosamente rappresenta un esplicito omaggio visivo alle classiche scene di poltergeist de L''esorcista di William Friedkin, film molto amato da Shyamalan.', 'Special TV di approfondimento sugli effetti speciali', TRUE, 'IA (Daily Sync)', 'IA Verificata', 0, 5, '2026-11-02T14:52:30.687684+00:00'),
('32e2c8c6-5f5c-40d0-b574-3dcb12c31d2d', 360, 'Segreti di produzione', 'Il look di Bruce Willis', 'Per sottolineare visivamente lo stato di negazione e la routine stagnante del dottor Malcolm Crowe, la costumista Joanna Johnston decise di fargli indossare quasi esclusivamente abiti scuri e cappotti pesanti, persino nelle sequenze ambientate all''interno di ambienti riscaldati.', 'Intervista alla costumista Joanna Johnston nei contenuti speciali', TRUE, 'IA (Daily Sync)', 'IA Verificata', 0, 6, '2026-11-02T14:52:30.687684+00:00'),
('1403b2e2-30e2-438b-ac3d-e81ed5c1983a', 362, 'Casting & Scelte', 'La scelta iniziale di Paul Haggis come sceneggiatore', 'Inizialmente Paul Haggis era stato ingaggiato unicamente per scrivere la sceneggiatura del remake di ''Pour elle'', ma dopo aver completato lo script decise che voleva dirigere personalmente il film.', 'Note di produzione ufficiali Lionsgate', TRUE, 'IA (Daily Sync)', 'IA Verificata', 0, 0, '2026-11-02T14:52:39.105988+00:00'),
('5b51b260-1ecf-401d-9278-56a52f74c725', 362, 'Curiosità & Retroscena', 'La consulenza con un vero scassinatore', 'Per girare la scena in cui John Brennan impara a falsificare le chiavi e ad aprire le porte con i grimaldelli, la produzione assunse un ex ladro professionista che lavorò sul set come consulente tecnico per insegnare a Russell Crowe i movimenti corretti e realistici.', 'Commento audio del regista Paul Haggis nel Blu-ray', TRUE, 'IA (Daily Sync)', 'IA Verificata', 0, 1, '2026-11-02T14:52:39.105988+00:00'),
('764bdf38-1e2f-4f81-8bf1-b47ae7f83df8', 362, 'Aneddoti dal set', 'Le riprese nel vero penitenziario', 'Alcune sequenze esterne e di transito sono state girate nei pressi di veri istituti di pena della Pennsylvania, imponendo alla troupe rigidi protocolli di sicurezza e orari molto ristretti per non interferire con le normali attività carcerarie.', 'Reportage dal set di Pittsburgh Post-Gazette', TRUE, 'IA (Daily Sync)', 'IA Verificata', 0, 2, '2026-11-02T14:52:39.105988+00:00'),
('ddcf1f3b-3522-4676-874a-270103caecce', 362, 'Aneddoti dal set', 'Il rapporto sul set tra Russell Crowe e Paul Haggis', 'Durante la lavorazione, Russell Crowe e Paul Haggis hanno avuto numerosi e accesi confronti creativi sullo sviluppo emotivo del personaggio di John, arrivando spesso a discutere animatamente sulle singole battute prima di girare le scene chiave.', 'Intervista a Paul Haggis per Entertainment Weekly', TRUE, 'IA (Daily Sync)', 'IA Verificata', 0, 3, '2026-11-02T14:52:39.105988+00:00'),
('14b6d3ec-092a-4e0d-8c29-ec76db1be0e4', 322, 'Curiosità & Retroscena', 'La parentela segreta tra i co-sceneggiatori', 'Il film è stato scritto da Christopher Nolan insieme a suo fratello minore Jonathan Nolan. Durante la stesura della sceneggiatura, durata ben cinque anni, i due fratelli si sono confrontati costantemente per adattare il complesso romanzo di Christopher Priest.', 'Note di produzione ufficiali Warner Bros.', TRUE, 'IA (Daily Sync)', 'IA Verificata', 0, 0, '2026-11-02T14:50:01.999135+00:00'),
('4b5ed6d8-1745-4998-9be1-85852dc0efed', 322, 'Casting & Scelte', 'La scelta di Rebecca Hall ispirata dai legami familiari', 'L''attrice Rebecca Hall, che interpreta Sarah Borden nel film, fu scelta personalmente da Christopher Nolan anche grazie al legame di amicizia e stima professionale che legava il regista al defunto padre dell''attrice, il celebre regista teatrale Peter Hall.', 'Intervista ufficiale nel press kit del film', TRUE, 'IA (Daily Sync)', 'IA Verificata', 0, 1, '2026-11-02T14:50:01.999135+00:00'),
('461a8ce9-cc75-4b82-b570-9e83d2480f65', 322, 'Casting & Scelte', 'Il ritorno sul set di Caine e Bale dopo Gotham', 'Michael Caine e Christian Bale accettarono di recitare in ''The Prestige'' subito dopo aver completato le riprese di ''Batman Begins'' (2005) sempre diretti da Christopher Nolan, consolidando un sodalizio artistico che sarebbe continuato nella trilogia del Cavaliere Oscuro.', 'The Hollywood Reporter - Special Report', TRUE, 'IA (Daily Sync)', 'IA Verificata', 0, 2, '2026-11-02T14:50:01.999135+00:00'),
('0d6ada3f-497d-4323-baa2-048a7aa4332f', 322, 'Curiosità & Retroscena', 'Le vere origini letterarie e l''incontro con Christopher Priest', 'Il regista Christopher Nolan rimase così affascinato dal romanzo omonimo di Christopher Priest del 1995 da opzionarne i diritti cinematografici molto prima di girare ''Memento'', lavorando al progetto ininterrottamente per anni.', 'Commento audio del regista nel DVD ufficiale', TRUE, 'IA (Daily Sync)', 'IA Verificata', 0, 3, '2026-11-02T14:50:01.999135+00:00'),
('54e71878-6257-4420-af8e-eb7a6c26fae0', 322, 'Segreti di produzione', 'L''uso limitato della CGI e la predilezione per gli elementi pratici', 'Fedele al suo stile di regia, Christopher Nolan ha ridotto al minimo l''uso della grafica computerizzata (CGI), preferendo la costruzione di set reali, oggetti di scena funzionanti e trucchi di prestidigitazione eseguiti dal vivo sul set.', 'American Cinematographer Magazine', TRUE, 'IA (Daily Sync)', 'IA Verificata', 0, 4, '2026-11-02T14:50:01.999135+00:00'),
('985db1fa-7470-48c3-80ab-017533012f6e', 322, 'Segreti di produzione', 'La consulenza dei veri maghi professionisti', 'Per garantire l''assoluta autenticità dei numeri di magia mostrati nel film, la produzione ha ingaggiato il celebre illusionista Ricky Jay e il mago Michael Weber come consulenti tecnici e choreografi dei trucchi di scena.', 'Making-of ufficiale ''Magicians of the Prestige''', TRUE, 'IA (Daily Sync)', 'IA Verificata', 0, 5, '2026-11-02T14:50:01.999135+00:00'),
('405b3926-fa4a-49dd-a779-5065cb394863', 322, 'Effetti speciali & Trucco', 'Il trucco delle doppie identità e dei gemelli nella troupe', 'Per alcune scene in cui compaiono i gemelli Borden, la produzione ha fatto ricorso a veri attori gemelli per le controfigure, studiando nei minimi dettagli le angolazioni di ripresa per non svelare il trucco visivo.', 'Intervista al supervisore degli effetti visivi', TRUE, 'IA (Daily Sync)', 'IA Verificata', 0, 6, '2026-11-02T14:50:01.999135+00:00'),
('0fa18296-248f-4eb7-b340-4626dddf4fbc', 322, 'Citazioni & Easter Egg', 'I riferimenti storici alla Londra vittoriana', 'Molti dei teatri in cui si esibiscono i maghi nel film sono un omaggio ai veri luoghi di spettacolo della Londra di fine Ottocento, ricostruiti meticolosamente nei teatri di posa di Los Angeles dallo scenografo Nathan Crowley.', 'Production Design Featurette', TRUE, 'IA (Daily Sync)', 'IA Verificata', 0, 7, '2026-11-02T14:50:01.999135+00:00'),
('082b7bdc-138d-45c5-89ae-95f24bc7a107', 359, 'Effetti speciali & Trucco', 'La cicatrice strategica di Ichabod', 'Il truccatore premio Oscar Rick Baker ha ideato una cicatrice verticale sul collo di Johnny Depp, giustificata nella backstory del personaggio come trauma d''infanzia legato ai metodi di tortura inquisitori del padre.', 'Audio commento del DVD e documentario di produzione ufficiale', TRUE, 'IA (Daily Sync)', 'IA Verificata', 0, 0, '2026-11-02T14:52:25.890513+00:00'),
('223b13b0-1637-44bf-9440-88cae61740d1', 359, 'Casting & Scelte', 'Il rifiuto di Liam Neeson e la scelta di Walken', 'Prima che Christopher Walken ottenesse l''iconico ruolo del Cavaliere Senza Testa, la produzione aveva valutato diversi attori di spicco, tra cui Liam Neeson, per conferire una presenza fisica imponente e minacciosa.', 'Note di casting della Paramount Pictures e biografia di Tim Burton', TRUE, 'IA (Daily Sync)', 'IA Verificata', 0, 1, '2026-11-02T14:52:25.890513+00:00'),
('4adaf1e1-b0fd-401d-870b-11cf7ce80166', 359, 'Effetti speciali & Trucco', 'I denti protesici di Johnny Depp', 'Per alterare la dizione e l''espressività di Johnny Depp, Tim Burton gli impose di indossare delle protesi dentarie inclinate e irregolari che resero difficile la pronuncia dei dialoghi nelle prime giornate di riprese.', 'Intervista a Johnny Depp per Entertainment Weekly (1999)', TRUE, 'IA (Daily Sync)', 'IA Verificata', 0, 2, '2026-11-02T14:52:25.890513+00:00'),
('72897fa2-36b0-408f-96dd-94b06aa03143', 359, 'Segreti di produzione', 'Il sangue finto a base di sciroppo e colorante', 'Per le numerose e cruenti decollazioni del film, la troupe degli effetti speciali guidata da Kevin Yagher ha utilizzato oltre cinquecento litri di sangue finto composto principalmente da sciroppo di mais e colorante alimentare.', 'Making-of ufficiale ''The Making of Sleepy Hollow''', TRUE, 'IA (Daily Sync)', 'IA Verificata', 0, 3, '2026-11-02T14:52:25.890513+00:00'),
('515d33d8-4e04-407b-9b93-3c1cb71c7b41', 359, 'Aneddoti dal set', 'Le urla reali di Christina Ricci', 'Durante la sequenza in cui il Cavaliere Senza Testa irrompe nella chiesa di Sleepy Hollow, Christina Ricci eseguì personalmente le sue acrobazie e i suoi urli di terrore senza ricorrere a controfigure, impressionando la troupe.', 'Intervista sul set a Christina Ricci', TRUE, 'IA (Daily Sync)', 'IA Verificata', 0, 4, '2026-11-02T14:52:25.890513+00:00'),
('cb54ad6b-26f1-47b4-a21e-73f85c083ec7', 359, 'Citazioni & Easter Egg', 'L''ispirazione pittorica di Tim Burton', 'La celebre sequenza dei mulini a vento e le tonalità cromatiche cupe del film sono state direttamente ispirate dai dipinti gotici di Johann Heinrich Füssli e dalle atmosfere dei classici horror della Hammer Films degli anni Cinquanta.', 'Libro ''Burton on Burton''', TRUE, 'IA (Daily Sync)', 'IA Verificata', 0, 5, '2026-11-02T14:52:25.890513+00:00'),
('4a3f5277-b2b4-454c-93b2-678df8004822', 359, 'Casting & Scelte', 'Il casting last minute di Michael Gambon', 'Michael Gambon fu ingaggiato per il ruolo del patriarca Baltus Van Tassel quasi a ridosso dell''inizio delle riprese, sostituendo un precedente attore non rivelato che aveva dovuto abbandonare il progetto per conflitti di programmazione.', 'Note di produzione della Mandalay Entertainment', TRUE, 'IA (Daily Sync)', 'IA Verificata', 0, 6, '2026-11-02T14:52:25.890513+00:00'),
('d8499774-e144-4210-8afe-56fc8b13a7cf', 359, 'Segreti di produzione', 'Gli alberi meccanici della foresta maledetta', 'La sinistra foresta di Sleepy Hollow non è stata ricreata interamente in digitale: la scenografia includeva imponenti alberi artificiali snodati meccanicamente manovrati da operatori nascosti tra i rami.', 'Special TV ''Behind the Legend of Sleepy Hollow''', TRUE, 'IA (Daily Sync)', 'IA Verificata', 0, 7, '2026-11-02T14:52:25.890513+00:00'),
('2014ee54-178b-42be-8876-e4475f9c596c', 204, 'Curiosità & Retroscena', 'L''omaggio a Philip Seymour Hoffman tramite le riprese digitali', 'Dopo la tragica scomparsa di Philip Seymour Hoffman (Plutarch Heavensbee) durante la post-produzione, il regista Francis Lawrence ha scelto di non ricorrere alla CGI o a un volto digitale completo, ma di utilizzare le riprese già effettuate, riscrivendo le poche scene mancanti e facendo pronunciare le sue battute ad altri personaggi.', 'Dichiarazioni ufficiali del regista Francis Lawrence e note di produzione', TRUE, 'IA (Daily Sync)', 'IA Verificata', 0, 0, '2026-11-02T14:53:35.948081+00:00'),
('81d1ab0a-07c3-4e23-b461-c25434deb827', 323, 'Aneddoti dal set', 'La consulenza della vera polizia di Boston', 'Per garantire il massimo realismo nelle procedure di polizia e nel gergo della South Boston criminale, Martin Scorsese ha assunto come consulenti tecnici e attori non protagonisti veri agenti ed ex detective del dipartimento di polizia di Boston (BPD).', 'Special content del DVD e note di produzione', TRUE, 'IA (Daily Sync)', 'IA Verificata', 0, 0, '2026-11-02T14:50:06.641071+00:00'),
('f367b9fa-0129-49a5-98f6-15b4f66677bb', 323, 'Aneddoti dal set', 'L''origine della scena del dildo e l''improvvisazione di Nicholson', 'Nella famosa scena dell''interrogatorio nel peep show, Jack Nicholson tirò fuori improvvisamente un dildo nero di gomma per destabilizzare completamente Leonardo DiCaprio, la cui reazione di shock e repulsione sullo schermo è del tutto genuina.', 'Intervista audio di Leonardo DiCaprio nel commento speciale', TRUE, 'IA (Daily Sync)', 'IA Verificata', 0, 1, '2026-11-02T14:50:06.641071+00:00'),
('16247a84-d7c1-449c-aa6e-18d50f33600f', 323, 'Citazioni & Easter Egg', 'Il cameo della famiglia reale di Boston', 'Nel film compaiono in piccoli ruoli cameo vari membri della troupe locale e familiari di figure storiche della città, un tributo voluto da Scorsese per radicare il film nell''autentico tessuto urbano e culturale di Boston.', 'Crediti e documentario sul backstage del film', TRUE, 'IA (Daily Sync)', 'IA Verificata', 0, 2, '2026-11-02T14:50:06.641071+00:00'),
('92db0bbe-58d2-4b06-85a3-a007860fff40', 323, 'Segreti di produzione', 'Il budget e le riprese a New York', 'Nonostante la storia sia ambientata interamente a Boston, gran parte delle sequenze urbane e degli interni sono state girate nei quartieri di New York City per motivi di convenienza logistica e fiscale, ricostruendo accuratamente i luoghi simbolo della capitale del Massachusetts.', 'Production notes e report di ripresa ufficiali', TRUE, 'IA (Daily Sync)', 'IA Verificata', 0, 3, '2026-11-02T14:50:06.641071+00:00'),
('be6390e9-5653-4aa9-9685-2d9e33fd0d4f', 323, 'Casting & Scelte', 'La trasformazione fisica di Matt Damon', 'Per calarsi nel ruolo del corrotto detective Colin Sullivan, Matt Damon ha frequentato regolarmente per settimane l''accademia di polizia di Boston e ha lavorato fianco a fianco con veri investigatori della sezione omicidi per apprendere posture, linguaggio del corpo e tecniche di interrogatorio.', 'Intervista ufficiale a Matt Damon per Entertainment Weekly', TRUE, 'IA (Daily Sync)', 'IA Verificata', 0, 4, '2026-11-02T14:50:06.641071+00:00'),
('c065b4a6-3bf3-4d50-9959-aa24dd2e2279', 323, 'Citazioni & Easter Egg', 'L''omaggio al cinema gangster classico nelle inquadrature', 'Il direttore della fotografia Michael Ballhaus ha studiato attentamente le inquadrature di classici della Warner Bros. degli anni ''30 e ''40 per replicare l''atmosfera cupa e claustrofobica dei vecchi noir americani, adattandola però al ritmo frenetico del cinema moderno.', 'American Cinematographer Magazine', TRUE, 'IA (Daily Sync)', 'IA Verificata', 0, 5, '2026-11-02T14:50:06.641071+00:00'),
('4d7a615c-2e2f-40ba-b845-4636da1068be', 332, 'Casting & Scelte', 'La raccomandazione cruciale di Johnny Depp per Freddie Highmore', 'Fu proprio Johnny Depp a raccomandare caldamente Freddie Highmore a Tim Burton per ''La fabbrica di cioccolato'' dopo aver toccato con mano il suo straordinario talento sul set di ''Neverland''. Questa fortunata intuizione cambiò radicalmente la carriera del giovane attore britannico.', 'Interviste stampa ufficiali e documentario sul backstage di Neverland', TRUE, 'IA (Daily Sync)', 'IA Verificata', 0, 0, '2026-11-02T14:50:41.417399+00:00'),
('a9ef9db7-4a87-49b7-ab3f-83599c8c0827', 332, 'Casting & Scelte', 'La vera parentela dietro l''interpretazione di Julie Christie', 'Julie Christie interpreta la severa Emma Du Maurier, nonna dei ragazzi Llewelyn Davies. L''attrice accettò la parte in parte per il legame di amicizia e stima con il regista Marc Forster e per misurarsi con un ruolo di matriarca rigida ma complessa.', 'Note di produzione Miramax / The Weinstein Company', TRUE, 'IA (Daily Sync)', 'IA Verificata', 0, 1, '2026-11-02T14:50:41.417399+00:00'),
('de2b0bb0-5e39-4439-b988-943f79bca26e', 332, 'Citazioni & Easter Egg', 'Il tributo di Dustin Hoffman al vero Charles Frohman', 'Dustin Hoffman studiò approfonditamente la figura storica del produttore teatrale americano Charles Frohman, morto tragicamente nell''affondamento del transatlantico Lusitania nel 1915, per restituirne fedelmente il pragmatismo unito a un profondo affetto per J.M. Barrie.', 'Commento audio del regista Marc Forster nel DVD', TRUE, 'IA (Daily Sync)', 'IA Verificata', 0, 2, '2026-11-02T14:50:41.417399+00:00'),
('7d286075-d5f0-438f-bc47-d4eb5f4b31e6', 332, 'Segreti di produzione', 'La precisione storica nell''abbigliamento edoardiano', 'La costumista Alexandra Byrne ha realizzato gran parte degli abiti di scena ispirandosi direttamente alle fotografie d''epoca della vera famiglia Llewelyn Davies conservate negli archivi storici britannici, prestando maniacale attenzione alla consistenza dei tessuti dell''epoca.', 'Note di produzione ufficiali sul design dei costumi', TRUE, 'IA (Daily Sync)', 'IA Verificata', 0, 3, '2026-11-02T14:50:41.417399+00:00'),
('e7fab828-56be-4cb8-b46b-4407899472f3', 332, 'Effetti speciali & Trucco', 'L''uso di veri effetti ottici in camera per le sequenze oniriche', 'Per enfatizzare il passaggio dalla realtà grigia alla fervida immaginazione di Barrie, il direttore della fotografia Gyula Pados ha utilizzato filtri fotografici fisici e variazioni sottili nella temperatura colore invece di ricorrere eccessivamente alla CGI in post-produzione.', 'Intervista al direttore della fotografia in American Cinematographer', TRUE, 'IA (Daily Sync)', 'IA Verificata', 0, 4, '2026-11-02T14:50:41.417399+00:00'),
('cbd718fd-f839-4d11-8392-35b69282e4b3', 334, 'Aneddoti dal set', 'La finta cicatrice e il duello reale', 'Durante il celebre duello tra Achille ed Ettore, Brad Pitt ed Eric Bana si accordarono per non usare controfigure. Un colpo leggermente fuori misura di Bana colpì davvero la bocca di Pitt, lasciandogli un piccolo gonfiore visibile in alcune inquadrature successive.', 'Commento audio del regista Wolfgang Petersen nel DVD ufficiale', TRUE, 'IA (Daily Sync)', 'IA Verificata', 0, 0, '2026-11-02T14:50:49.772074+00:00'),
('90ad1524-a877-426f-a6d6-79a4b2010570', 334, 'Casting & Scelte', 'La dieta drastica di Brad Pitt', 'Per assumere la corporatura snella ma estremamente definita di un eroe omerico, Brad Pitt smise completamente di fumare e seguì una rigida dieta a base di pollo, broccoli e proteine, eliminando ogni carboidrato raffinato durante le riprese.', 'Note di produzione e interviste ai trainer ufficiali del film', TRUE, 'IA (Daily Sync)', 'IA Verificata', 0, 1, '2026-11-02T14:50:49.772074+00:00'),
('0bb70e6d-cd42-448e-83b9-8826da6ffd7d', 334, 'Segreti di produzione', 'Il caldo estremo nel deserto marocchino', 'Le scene ambientate sulle spiagge di Troia furono girate anche a Ouarzazate, in Marocco, dove le temperature superarono i 45 gradi Celsius. Diversi comparse e membri della troupe svennero a causa delle pesanti armature di metallo e cuoio.', 'Documentario ''In the Making of Troy'' contenuto nel Blu-ray', TRUE, 'IA (Daily Sync)', 'IA Verificata', 0, 2, '2026-11-02T14:50:49.772074+00:00');
INSERT INTO public.movie_trivia ("id", "film_id", "categoria", "titolo", "descrizione", "fonte", "approvato", "inserito_da", "provenienza", "likes", "ordine", "created_at") VALUES
('1464a2e3-191e-4ed0-900e-3fa3bad6c55d', 334, 'Casting & Scelte', 'Il rifiuto del ruolo di Achille', 'Prima che Brad Pitt accettasse la parte, il regista Wolfgang Petersen aveva pensato a diversi attori di prim''ordine, ma lo stesso Pitt fu il primo e principale obiettivo dello studio dopo il successo globale di ''Troy'' in fase di sviluppo.', 'Archivi storici di Variety e Hollywood Reporter', TRUE, 'IA (Daily Sync)', 'IA Verificata', 0, 3, '2026-11-02T14:50:49.772074+00:00'),
('e2e3fa1b-2b9b-464c-bed0-bd2370c9833a', 334, 'Effetti speciali & Trucco', 'La statua gigante di Apollo', 'La mastodontica statua di Apollo alta oltre dodici metri che domina la piazza di Troia non era interamente in CGI: fu costruita in polistirolo rinforzato e legno dagli scenografi guidati da Nigel Phelps direttamente sul set di Malta.', 'Featurette di scenografia del backstage di Troy', TRUE, 'IA (Daily Sync)', 'IA Verificata', 0, 4, '2026-11-02T14:50:49.772074+00:00'),
('9da3b85d-e758-4515-b730-a034891890f3', 327, 'Segreti di produzione', 'L''ispirazione visiva tratta da Il Conformista', 'Steven Spielberg e il direttore della fotografia Janusz Kamiński hanno studiato attentamente il capolavoro di Bernardo Bertolucci ''Il conformista'' (1970) per catturare l''estetica, la palette cromatica e le atmosfere opprimenti dell''Europa degli anni Settanta.', 'Note di produzione ufficiali e intervista a Janusz Kamiński per American Cinematographer', TRUE, 'IA (Daily Sync)', 'IA Verificata', 0, 0, '2026-11-02T14:50:20.160288+00:00'),
('a664766e-d923-46c6-8378-c1e94d471c6d', 327, 'Casting & Scelte', 'Il coinvolgimento di Tony Kushner su raccomandazione di Eric Roth', 'Eric Roth aveva scritto una prima stesura della sceneggiatura basata sul libro di George Jonas, ma Spielberg chiamò il drammaturgo premio Pulitzer Tony Kushner per riscrivere i dialoghi e approfondire la complessa psicologia morale dei personaggi.', 'Dichiarazioni ufficiali di Steven Spielberg nelle note stampa del film', TRUE, 'IA (Daily Sync)', 'IA Verificata', 0, 1, '2026-11-02T14:50:20.160288+00:00'),
('6de6ae45-bf9a-4ecd-9b31-c54b4dca5e68', 327, 'Aneddoti dal set', 'Le riprese in Ungheria per sostituire diverse nazioni', 'Gran parte dell''Europa occidentale degli anni ''70 è stata ricreata a Budapest, in Ungheria, sfruttando l''architettura sovietica e i vecchi edifici della capitale ungherese per simulare città come Parigi, Londra, Roma e Beirut.', 'Making-of ufficiale incluso nell''edizione home video di Munich', TRUE, 'IA (Daily Sync)', 'IA Verificata', 0, 2, '2026-11-02T14:50:20.160288+00:00'),
('ecb886e8-b32a-459c-bc8b-1b6aad98a7e0', 327, 'Casting & Scelte', 'La scelta di Daniel Craig prima di James Bond', 'Daniel Craig ottenne la parte del sudafricano Steve poco prima di essere ufficialmente annunciato come il nuovo James Bond in ''Casino Royale'', consolidando proprio grazie a questo ruolo drammatico la sua fama internazionale.', 'Interviste promozionali di Daniel Craig per l''uscita del film', TRUE, 'IA (Daily Sync)', 'IA Verificata', 0, 3, '2026-11-02T14:50:20.160288+00:00'),
('414e4ff9-9a40-4a37-84b0-09946433af6f', 327, 'Effetti speciali & Trucco', 'L''uso di cineprese e ottiche Panavision d''epoca', 'Per evitare che l''immagine avesse la nitidezza e la pulizia del digitale moderno, Kamiński ha utilizzato cineprese Arriflex e una combinazione di vecchie lenti anamorfiche per conferire al film la tipica granulosità dei thriller politici dei decenni passati.', 'Articolo tecnico su American Cinematographer, gennaio 2006', TRUE, 'IA (Daily Sync)', 'IA Verificata', 0, 4, '2026-11-02T14:50:20.160288+00:00'),
('bb477b95-e80a-483b-a97f-7546cee15fd9', 336, 'Casting & Scelte', 'La scelta della figlia reale per il ruolo di Katie', 'Il ruolo di Katie Marcus, la giovane la cui tragica morte dà il via alla trama, è stato affidato a Emmy Rossum, la quale ha ottenuto la parte dopo aver superato una rigorosa serie di provini superando numerose concorrenti grazie alla sua espressività drammatica.', 'Note di produzione ufficiali della Warner Bros.', TRUE, 'IA (Daily Sync)', 'IA Verificata', 0, 0, '2026-11-02T14:50:58.62639+00:00'),
('440cc1a0-b648-418d-964c-b125e862e254', 336, 'Curiosità & Retroscena', 'Il rifiuto iniziale del regista per la trasposizione', 'Inizialmente, prima che Clint Eastwood si legasse al progetto, i diritti cinematografici del romanzo di Dennis Lehane erano stati acquistati da altre case di produzione che avevano tentato senza successo di adattarlo, ritenendo la storia troppo cupa e difficile da trasporre sul grande schermo.', 'Intervista retrospettiva a Dennis Lehane', TRUE, 'IA (Daily Sync)', 'IA Verificata', 0, 1, '2026-11-02T14:50:58.62639+00:00'),
('71b77602-096c-4b8d-bb68-eab8aa6b7415', 336, 'Segreti di produzione', 'L''utilizzo della luce naturale nelle scene notturne', 'Il direttore della fotografia Tom Stern ha impiegato tecniche di illuminazione minimaliste, privilegiando la luce naturale e lampioni stradali reali per mantenere l''atmosfera cupa, cupa e realistica dei quartieri operai di Boston voluta da Clint Eastwood.', 'American Cinematographer, articolo tecnico su Mystic River', TRUE, 'IA (Daily Sync)', 'IA Verificata', 0, 2, '2026-11-02T14:50:58.62639+00:00'),
('38b1213b-0d23-4606-8646-bd6fe9abc564', 336, 'Aneddoti dal set', 'La consulenza con la polizia di Boston', 'Per garantire la massima autenticità nelle procedure investigative del personaggio di Kevin Bacon e del suo collega interpretato da Laurence Fishburne, la produzione ha assunto veri detective del dipartimento di polizia di Boston come consulenti fissi sul set.', 'Making-of ufficiale contenuto nel DVD speciale', TRUE, 'IA (Daily Sync)', 'IA Verificata', 0, 3, '2026-11-02T14:50:58.62639+00:00'),
('b3fc15ac-5f67-4a3e-8b07-065ce63948ef', 336, 'Aneddoti dal set', 'L''improvvisazione del finale sul fiume', 'Durante la drammatica sequenza della parata in cui Sean Penn e Kevin Bacon si scambiano uno sguardo intenso da una sponda all''altra del fiume, i gesti di intesa silenziosa non erano interamente scritti nel copione ma sono nati dalla forte intesa estemporanea tra i due attori.', 'Commento audio del regista Clint Eastwood', TRUE, 'IA (Daily Sync)', 'IA Verificata', 0, 4, '2026-11-02T14:50:58.62639+00:00'),
('0d91b7a0-7b74-4276-89fc-0450c76b31d6', 336, 'Effetti speciali & Trucco', 'La scelta del look anni ''70 per il flashback iniziale', 'Per la sequenza iniziale del 1975 in cui i tre protagonisti giocano a hockey su strada da bambini, la produzione ha rimosso digitalmente e con scenografie d''epoca tutti i moderni segnali stradali, automobili e antenne paraboliche presenti nelle strade di Somerville.', 'Cinefex Magazine / Note di produzione', TRUE, 'IA (Daily Sync)', 'IA Verificata', 0, 5, '2026-11-02T14:50:58.62639+00:00'),
('56705614-fd29-4440-baa4-0c06fc2ed3af', 362, 'Segreti di produzione', 'L''uso limitato della CGI', 'Il regista Paul Haggis ha preteso che la fuga finale e gli inseguimenti automobilistici fossero girati quasi interamente dal vivo con stuntmen professionisti, riducendo al minimo l''uso di effetti digitali in post-produzione per mantenere un impatto crudo e realistico.', 'Making-of ufficiale ''The Making of The Next Three Days''', TRUE, 'IA (Daily Sync)', 'IA Verificata', 0, 4, '2026-11-02T14:52:39.105988+00:00'),
('14081de7-7ca9-4d84-8f35-3696f0fb3fa5', 214, 'Effetti speciali & Trucco', 'La gestione del trucco per le scene di forte tensione', 'I reparti di trucco e parrucco hanno lavorato meticolosamente per mostrare il progressivo decadimento fisico ed emotivo di Keller Dover, dosando polvere, sudore e lievi ecchimosi che aumentano man mano che il protagonista perde il controllo.', 'Featurette sul reparto trucco e costumi', TRUE, 'IA (Daily Sync)', 'IA Verificata', 0, 6, '2026-11-02T15:47:12.392412+00:00'),
('e81e1e7e-142c-4263-a4c5-419fb2db01ca', 214, 'Segreti di produzione', 'I fischietti e la ricerca sonora del bosco', 'Per rendere l''atmosfera della Pennsylvania cupa e opprimente, il sound designer ha integrato suoni ambientali artificiali e ovattati, accentuando il silenzio della foresta e i rumori metallici per amplificare il senso di claustrofobia.', 'Intervista al sound designer nel documentario sul sonno del film', TRUE, 'IA (Daily Sync)', 'IA Verificata', 0, 7, '2026-11-02T15:47:12.392412+00:00'),
('670f0031-989e-4183-a943-609948365708', 239, 'Segreti di produzione', 'La scena iniziale in soggettiva girata con la Steadicam', 'La celebre sequenza d''apertura in soggettiva (POV) in cui il piccolo Michael Myers uccide la sorella Judith fu girata da John Carpenter utilizzando una delle prime Steadicam allora disponibili, manovrata dall''operatore cinematografico Garrett Brown. Per realizzare questo piano-sequenza continuo di quasi cinque minuti, Brown dovette muoversi agilmente attraverso la casa fingendosi il bambino di sei anni.', 'Documentario ''Halloween: Unmasked 2000'' e commento audio del Blu-ray', TRUE, 'IA (Daily Sync)', 'IA Verificata', 0, 0, '2026-11-02T15:48:03.212117+00:00'),
('bee9cd47-b427-46c5-b245-f5e1dc07a19b', 265, 'Aneddoti dal set', 'La finta gita in barca di Ana de Armas', 'Durante le riprese della scena in cui Marta si reca in barca per incontrare Fran, l''attrice Ana de Armas non sapeva che la barca fosse telecomandata. Rian Johnson e la troupe avevano nascosto il sistema di guida per catturare la sua reazione di smarrimento reale.', 'Commento audio del regista Rian Johnson nell''edizione Blu-ray', TRUE, 'IA (Daily Sync)', 'IA Verificata', 0, 0, '2026-11-02T15:48:22.685275+00:00'),
('f3f75ca4-6fac-4e64-8f98-47d9d3c8ea50', 328, 'Segreti di produzione', 'La scelta del furgone blindato e le modifiche meccaniche', 'Il minivan Dodge Windstar utilizzato nella fuga della famiglia Ferrier è stato modificato appositamente per le riprese, installando telecamere nascoste e rimuovendo i sedili per permettere agli operatori di riprendere Tom Cruise e i ragazzi da angolazioni impossibili durante la guida.', 'Note di produzione e DVD Bonus Features', TRUE, 'IA (Daily Sync)', 'IA Verificata', 0, 0, '2026-11-02T14:50:24.361521+00:00'),
('ea8fe82d-0cb6-4513-9510-a981c5426112', 328, 'Effetti speciali & Trucco', 'La polvere rossa e i materiali eco-compatibili', 'La terrificante sostanza rossa aliena che avvolge il paesaggio è stata realizzata utilizzando una combinazione di torba ecologica, segatura colorata e cellulosa, trattata digitalmente in post-produzione per dare l''effetto di una vegetazione aliena in rapida crescita.', 'Making-of ufficiale e interviste al reparto scenografia', TRUE, 'IA (Daily Sync)', 'IA Verificata', 0, 1, '2026-11-02T14:50:24.361521+00:00'),
('04f87723-eeb7-423c-ad5a-612b91ac78b3', 328, 'Curiosità & Retroscena', 'L''ispirazione per il clacson dei Tripodi', 'Il celebre e inquietante suono della tromba o clacson dei Tripodi alieni è stato ideato dal progettista del suono Gary Rydstrom, il quale ha dichiarato di essersi ispirato ai rumori metallici delle sirene antiaeree storiche mescolati a frequenze digitali distorte.', 'Intervista ufficiale a Gary Rydstrom per Sound & Vision', TRUE, 'IA (Daily Sync)', 'IA Verificata', 0, 2, '2026-11-02T14:50:24.361521+00:00'),
('5a3417df-d803-4b46-95d7-cf38c53e4c63', 328, 'Curiosità & Retroscena', 'La collaborazione segreta tra Spielberg e Lucas', 'George Lucas ha visitato spesso il set de ''La guerra dei mondi'' e ha offerto a Steven Spielberg preziosi consigli sull''utilizzo delle pre-visualizzazioni digitali in 3D per pianificare le complesse sequenze d''azione con i Tripodi, attingendo alla sua esperienza con i prequel di Star Wars.', 'Diario di produzione e interviste sul set', TRUE, 'IA (Daily Sync)', 'IA Verificata', 0, 3, '2026-11-02T14:50:24.361521+00:00'),
('5986d7f9-8338-4ec9-abf9-f688c87e6066', 328, 'Citazioni & Easter Egg', 'La partecipazione speciale di John Williams', 'Anche se non appare visibilmente sullo schermo, il celebre compositore John Williams ha lavorato a stretto contatto con Spielberg per inserire sottili richiami musicali alle partiture dei vecchi film di fantascienza degli anni ''50 all''interno della colonna sonora orchestrale.', 'Note di copertina della colonna sonora ufficiale', TRUE, 'IA (Daily Sync)', 'IA Verificata', 0, 4, '2026-11-02T14:50:24.361521+00:00'),
('fd885d40-aae9-4f9b-9559-50f60d2e5d32', 330, 'Curiosità & Retroscena', 'La genesi dal fumetto alla sceneggiatura di Josh Olson', 'La sceneggiatura di Josh Olson è un adattamento della graphic novel omonima di John Wagner e Vince Locke. Tuttavia, nel fumetto originale la storia aveva un''ambientazione apertamente mafiosa e criminale fin dall''inizio, mentre Cronenberg e Olson decisero di enfatizzare il contrasto radicale tra la quiete della provincia americana e il passato violento del protagonista.', 'Audio commento del regista David Cronenberg nel DVD ufficiale', TRUE, 'IA (Daily Sync)', 'IA Verificata', 0, 0, '2026-11-02T14:50:33.659594+00:00'),
('24d66395-268a-4beb-91ee-281c00b2055a', 330, 'Segreti di produzione', 'La scelta del Canada per simulare l''Indiana', 'Nonostante la storia sia ambientata nella cittadina fittizia di Millbrook nell''Indiana, l''intero film è stato girato ininterrottamente in Ontario, Canada, sfruttando le zone rurali intorno a Toronto e cittadine come Millbrook (Ontario) per replicare perfettamente l''estetica del Midwest americano.', 'Note di produzione e presskit ufficiale New Line Cinema', TRUE, 'IA (Daily Sync)', 'IA Verificata', 0, 1, '2026-11-02T14:50:33.659594+00:00'),
('6b98b8ac-942a-4fe2-80a4-082dba6544a2', 330, 'Aneddoti dal set', 'L''improvvisazione vocale di William Hurt', 'William Hurt ha ottenuto una candidatura all''Oscar come miglior attore non protagonista per la sua breve ma intensa interpretazione del boss Richie Cusack. Hurt ha lavorato a stretto contatto con Cronenberg per definire la voce sussurrata, melliflua e minacciosa del personaggio, improvvisando alcune sfumature verbali durante il confronto finale con Viggo Mortensen.', 'Documentario dietro le quinte ''Acts of Violence''', TRUE, 'IA (Daily Sync)', 'IA Verificata', 0, 2, '2026-11-02T14:50:33.659594+00:00'),
('8e2cd9d2-94dc-4179-8d00-6f0a25b3c881', 330, 'Segreti di produzione', 'Il rapporto di fiducia tra Cronenberg e Peter Suschitzky', 'Il direttore della fotografia Peter Suschitzky, storico collaboratore di David Cronenberg dai tempi di ''Dead Ringers'' (Inseparabili), ha scelto una palette di colori calda e rassicurante per la prima parte del film a Millbrook, per poi virare verso toni freddi, metallici e distaccati quando la violenza irrompe nella vita della famiglia Stall.', 'American Cinematographer, intervista a Peter Suschitzky', TRUE, 'IA (Daily Sync)', 'IA Verificata', 0, 3, '2026-11-02T14:50:33.659594+00:00'),
('9a39f23c-c433-4538-9671-6c43c762c76e', 330, 'Casting & Scelte', 'La preparazione atletica e marziale di Ashton Holmes', 'Ashton Holmes, che interpreta il figlio adolescente Jack Stall, ha dovuto sottoporsi a un intenso addestramento per le sequenze in cui il suo personaggio subisce atti di bullismo a scuola e viene preso in ostaggio, lavorando specificamente sulla postura fisica per rendere credibile la vulnerabilità e la successiva ribellione.', 'Intervista promozionale a Ashton Holmes nel presskit', TRUE, 'IA (Daily Sync)', 'IA Verificata', 0, 4, '2026-11-02T14:50:33.659594+00:00'),
('c335e0da-5f2f-4506-82d3-01317fc75e67', 330, 'Effetti speciali & Trucco', 'L''uso dei fucili d''epoca nella sparatoria iniziale', 'Per la brutale sequenza iniziale nella tavola calda, in cui i due criminali interpretati da Kyle Schmid e Stephen McHattie compiono una strage, la produzione ha utilizzato armi a salve modificate con cariche speciali supervisionate da esperti d''armi per garantire il massimo realismo visivo e sonoro all''interno di uno spazio chiuso.', 'Special feature ''The Making of A History of Violence''', TRUE, 'IA (Daily Sync)', 'IA Verificata', 0, 5, '2026-11-02T14:50:33.659594+00:00'),
('b5842171-8c26-4e62-b8d9-50d7774cb582', 330, 'Curiosità & Retroscena', 'Il rifiuto iniziale del tono da parte dei produttori', 'I dirigenti della New Line Cinema rimasero inizialmente spiazzati dalla natura estremamente grafica e ambigua della violenza nel film, temendo che il pubblico potesse empatizzare troppo con la doppia identità del protagonista. Cronenberg mantenne tuttavia il totale controllo creativo sul montaggio finale.', 'Biografia di David Cronenberg di Caelum Vatnsdal', TRUE, 'IA (Daily Sync)', 'IA Verificata', 0, 6, '2026-11-02T14:50:33.659594+00:00'),
('4743c1fd-3afb-4f4b-9d23-fd5cc47bb3f7', 299, 'Casting & Scelte', 'Il rifiuto iniziale di Bradley Cooper per la stazza fisica', 'Inizialmente la produzione nutriva forti dubbi sul fatto che Bradley Cooper, noto per ruoli da commedia e drammi romantici, potesse fisicamente impersonare un gigante muscoloso come Chris Kyle, alto oltre un metro e novanta. L''attore dovette convincere personalmente la Warner Bros. e Clint Eastwood sottoponendosi a mesi di prove prima di ottenere l''ingaggio definitivo.', 'Intervista ufficiale di Bradley Cooper per il press junket del film', TRUE, 'IA (Daily Sync)', 'IA Verificata', 0, 0, '2026-11-02T14:52:43.305105+00:00'),
('ce281b7e-cb33-4d06-83ff-d86551c41687', 299, 'Segreti di produzione', 'L''uso di veri fucili Mk 13', 'Per garantire la massima autenticità visiva e tecnica nelle scene da cecchino, la produzione ha fornito a Bradley Cooper autentiche armi militari, tra cui il fucile di precisione Mk 13 calibro .300 Winchester Magnum identico a quello utilizzato dal vero Chris Kyle durante i suoi turni di servizio in Iraq.', 'Note di produzione ufficiali della Warner Bros.', TRUE, 'IA (Daily Sync)', 'IA Verificata', 0, 1, '2026-11-02T14:52:43.305105+00:00'),
('00ddc44a-c061-4d11-b274-783109cd2c72', 299, 'Citazioni & Easter Egg', 'Il cameo del vero Kevin ''Dauber'' Lacz', 'Kevin Lacz, uno dei veri commilitoni di Chris Kyle che ha servito con lui nei Navy SEAL, non solo ha fatto da consulente tecnico sul set per Bradley Cooper, ma appare anche fisicamente nel film interpretando se stesso nelle sequenze finali della narrazione.', 'Special content e crediti del Blu-ray ufficiale', TRUE, 'IA (Daily Sync)', 'IA Verificata', 0, 2, '2026-11-02T14:52:43.305105+00:00'),
('9a418443-cfde-4780-8129-9de395bd6f65', 329, 'Aneddoti dal set', 'La spalla slogata di Russell Crowe', 'Durante le riprese dei combattimenti, Russell Crowe subì la slogatura della spalla destra a causa dell''intensità e della ripetizione dei colpi scambiati sul set, costringendo la produzione a rallentare temporaneamente i piani di lavorazione.', 'Note di produzione ufficiali e commento audio del DVD', TRUE, 'IA (Daily Sync)', 'IA Verificata', 0, 0, '2026-11-02T14:50:28.685057+00:00'),
('fabc718c-537b-444a-a711-b1bb76a105c0', 329, 'Casting & Scelte', 'La consulenza del figlio di Jim Braddock', 'Jay Braddock, il figlio minore del vero pugile, ha visitato regolarmente il set cinematografico e ha lavorato a stretto contatto con Russell Crowe per insegnargli le reali movenze e la postura del padre sul ring.', 'Intervista promozionale Universal Pictures e EPK ufficiale', TRUE, 'IA (Daily Sync)', 'IA Verificata', 0, 1, '2026-11-02T14:50:28.685057+00:00'),
('2385a568-0955-4351-97fe-f2267e6691ab', 329, 'Segreti di produzione', 'I veri pugili prestati al set', 'Per garantire la massima veridicità agli incontri, il coordinatore degli stuntman e coreografo dei combattimenti Angelo Dundee ingaggiò pugili professionisti ed ex sparring partner per recitare nei ruoli minori degli avversari di Braddock.', 'Featurette ''The Fight of Their Lives'' nel dietro le quinte', TRUE, 'IA (Daily Sync)', 'IA Verificata', 0, 2, '2026-11-02T14:50:28.685057+00:00'),
('190f8dd0-49ab-4b7a-b74d-5867380e5d38', 329, 'Effetti speciali & Trucco', 'La scelta della pellicola e della grana', 'Il direttore della fotografia Salvatore Totino ha utilizzato una specifica combinazione di lenti e trattamenti di post-produzione digitali per desaturare i colori, conferendo alla pellicola una patina polverosa che ricordasse le fotografie d''epoca della Farm Security Administration.', 'American Cinematographer Magazine, giugno 2005', TRUE, 'IA (Daily Sync)', 'IA Verificata', 0, 3, '2026-11-02T14:50:28.685057+00:00'),
('dc37229a-1eb7-4f1c-8b31-1763701cf8b6', 329, 'Citazioni & Easter Egg', 'Il cameo del pronipote di Max Baer', 'Un piccolo omaggio alla storia vera è nascosto tra le comparse: alcuni discendenti della famiglia Baer furono invitati sul set durante le scene del Madison Square Garden e inseriti tra il pubblico tifoso.', 'Curiosità dal backstage e note di regia di Ron Howard', TRUE, 'IA (Daily Sync)', 'IA Verificata', 0, 4, '2026-11-02T14:50:28.685057+00:00'),
('59429053-d4be-49b7-80eb-2f1f96d6df26', 329, 'Effetti speciali & Trucco', 'Le protesi dentali e nasali', 'Il reparto trucco guidato da David Atherton ha creato calchi speciali e protesi in silicone per il naso e l''arcata dentale di Russell Crowe, replicando fedelmente le cicatrici e i traumi facciali accumulati da Braddock in vent''anni di carriera.', 'Make-Up Artist Magazine, edizione speciale sul film', TRUE, 'IA (Daily Sync)', 'IA Verificata', 0, 5, '2026-11-02T14:50:28.685057+00:00'),
('c89fe98d-dbf5-4411-8966-b8406822b057', 331, 'Citazioni & Easter Egg', 'L''omaggio a ''Delitto e castigo'' di Dostoevskij', 'Il romanzo che Chris legge all''inizio del film è esplicitamente ''Delitto e castigo'' di Fëdor Dostoevskij, la cui trama sul senso di colpa e sulla superiorità morale del singolo trasgressore riflette l''intera struttura filosofica del film.', 'Analisi ufficiale della sceneggiatura e note di regia', TRUE, 'IA (Daily Sync)', 'IA Verificata', 0, 0, '2026-11-02T14:50:37.229148+00:00'),
('849bf214-c798-4a41-a477-5f0b537857bd', 331, 'Segreti di produzione', 'La scelta della pallina da tennis congelata', 'Nella celebre sequenza iniziale in cui la pallina da tennis colpisce il nastro e rimane sospesa prima di cadere da un lato o dall''altro, la produzione ha utilizzato una combinazione di effetti digitali e riprese in slow-motion con palline trattate per enfatizzare la metafora visiva del fattore fortuna.', 'Diario di produzione e intervista al direttore della fotografia Remi Adefarasin', TRUE, 'IA (Daily Sync)', 'IA Verificata', 0, 1, '2026-11-02T14:50:37.229148+00:00'),
('dc3ed73e-1c01-48be-b590-bcc4e3af5f93', 331, 'Casting & Scelte', 'Il doppiaggio in italiano di Brian Cox', 'Per il ruolo del milionario Alec Hewett, Woody Allen ha fortemente voluto Brian Cox dopo averne apprezzato la versatilità teatrale, imponendo l''attore scozzese senza effettuare ulteriori provini per la parte.', 'Note di casting ufficiali della produzione britannica', TRUE, 'IA (Daily Sync)', 'IA Verificata', 0, 2, '2026-11-02T14:50:37.229148+00:00'),
('ed3f226c-15e0-4ec7-8e39-2ea575991736', 331, 'Curiosità & Retroscena', 'La location reale della galleria d''arte', 'Le scene ambientate nella galleria d''arte dove lavora Chloe sono state girate nella prestigiosa Serpentine Gallery e in altri spazi espositivi realmente esistenti a Londra, concessi eccezionalmente per le riprese nei giorni di chiusura al pubblico.', 'Reportage dal set e permessi di location della città di Londra', TRUE, 'IA (Daily Sync)', 'IA Verificata', 0, 3, '2026-11-02T14:50:37.229148+00:00'),
('bbc6be93-5965-4dff-adfe-ecbf58d6a471', 299, 'Aneddoti dal set', 'Le riprese nei vecchi studi della Universal', 'Molte delle scene urbane e dei combattimenti tra le rovine delle città irachene non sono state girate solo in esterni californiani, ma anche sfruttando i celebri backlot della Universal Studios, modificati pesantemente con scenografie di macerie e detriti per replicare Fallujah e Ramadi.', 'Reportage dal set di American Cinematographer', TRUE, 'IA (Daily Sync)', 'IA Verificata', 0, 3, '2026-11-02T14:52:43.305105+00:00'),
('ba56e2a7-ef66-4d98-b20f-531bfddbfc5e', 299, 'Curiosità & Retroscena', 'La consulenza tecnica di Wayne Kyle', 'Il padre di Chris Kyle, Wayne Kyle, ha visitato più volte il set cinematografico durante la lavorazione, offrendo preziosi consigli a Clint Eastwood e allo stesso Bradley Cooper per catturare accuratamente la psicologia complessa del figlio e il suo codice etico militare.', 'Intervista al regista Clint Eastwood nel documentario ''The Making of American Sniper''', TRUE, 'IA (Daily Sync)', 'IA Verificata', 0, 4, '2026-11-02T14:52:43.305105+00:00'),
('6f52e421-894b-4ab9-88ad-678cc4ac2d94', 216, 'Casting & Scelte', 'Il rifiuto iniziale di Tim Roth', 'Prima di accettare la parte, Tim Roth rifiutò categoricamente il ruolo di Novecento per ben due volte. L''attore britannico non si sentiva adatto a interpretare un pianista e fu necessario un lungo lavoro di persuasione da parte di Giuseppe Tornatore per convincerlo a leggere attentamente la sceneggiatura.', 'Intervista ufficiale a Tim Roth nel making-of del DVD', TRUE, 'IA (Daily Sync)', 'IA Verificata', 0, 0, '2026-11-02T15:47:16.492485+00:00'),
('f426cf6b-fd1b-46bf-b79d-609458053253', 216, 'Curiosità & Retroscena', 'L''ispirazione letteraria dal monologo teatrale', 'Il film è liberamente tratto dal monologo teatrale ''Novecento'' scritto appositamente per gli attori da Alessandro Baricco nel 1994. Tornatore rimase folgorato dalla lettura del testo e decise di espanderlo cinematograficamente, trasformandolo in una grande epopea visiva e musicale.', 'Note di produzione ufficiali della Medusa Film', TRUE, 'IA (Daily Sync)', 'IA Verificata', 0, 1, '2026-11-02T15:47:16.492485+00:00'),
('52a6e0a2-c25d-4650-a885-769de895b919', 216, 'Aneddoti dal set', 'La difficoltà fisica della ''sfida a duello''', 'Durante la celebre sequenza del duello pianistico contro Jelly Roll Morton, Tim Roth dovette imparare a memoria la tastiera e i movimenti esatti delle dita a tempo di record. L''attore ha spesso ricordato quella sessione di riprese come una delle più estenuanti della sua carriera a causa della tensione fisica e della precisione richiesta.', 'Intervista retrospettiva a Tim Roth per riviste di cinema', TRUE, 'IA (Daily Sync)', 'IA Verificata', 0, 2, '2026-11-02T15:47:16.492485+00:00'),
('187a6572-364e-4622-b4b5-d895452de0ab', 216, 'Segreti di produzione', 'La costruzione dei modelli in scala del transatlantico', 'Per ricreare il maestoso transatlantico Virginian in alto mare e nelle sequenze in porto, la produzione si affidò agli esperti della Digital Image Associates e a complessi modelli fisici in miniatura combinati con scenografie parziali a grandezza naturale costruite negli stabilimenti di Cinecittà.', 'Reportage tecnico sulla produzione e sugli effetti speciali del film', TRUE, 'IA (Daily Sync)', 'IA Verificata', 0, 3, '2026-11-02T15:47:16.492485+00:00'),
('8b2cc638-db01-4879-a7c1-c86af1586319', 334, 'Segreti di produzione', 'I consigli dello storico dell''arte antica', 'Il regista Wolfgang Petersen ingaggiò il professor Donald Kagan dell''Università di Yale come consulente storico per garantire che le tattiche militari omeriche e la struttura sociale greca avessero un minimo di verosimiglianza cinematografica.', 'Note di produzione ufficiali della Warner Bros.', TRUE, 'IA (Daily Sync)', 'IA Verificata', 0, 5, '2026-11-02T14:50:49.772074+00:00'),
('314458bf-aa76-4ae2-a2d9-3bb2dbd5baa3', 335, 'Segreti di produzione', 'La scelta della cabina telefonica isolata', 'La cabina telefonica isolata utilizzata da Mort Rainey nel film è stata costruita appositamente dalla troupe su una strada di campagna a Lacolle, nel Québec, per accentuare il senso di totale isolamento del protagonista rispetto al resto del mondo.', 'Note di produzione ufficiali della Columbia Pictures', TRUE, 'IA (Daily Sync)', 'IA Verificata', 0, 0, '2026-11-02T14:50:54.053613+00:00'),
('718c54c8-9199-4154-b0d0-183f4f6e280f', 335, 'Curiosità & Retroscena', 'La casa sul lago di Tashmoo', 'Le riprese esterne ed interne della celebre casa sul lago di Mort si sono svolte a Lake Tashmoo, situato a Martha''s Vineyard, lo stesso luogo in cui fu girato gran parte di ''Lo squalo'' di Steven Spielberg trent''anni prima.', 'Documentario sul backstage nel DVD ufficiale', TRUE, 'IA (Daily Sync)', 'IA Verificata', 0, 1, '2026-11-02T14:50:54.053613+00:00'),
('a598f3d6-d61d-40a5-9892-ffb4ce20b41e', 335, 'Casting & Scelte', 'Il cane Moose nel ruolo di Chico', 'Il cane a tre zampe che interpreta il fedele animale domestico di Mort si chiama Moose, un famosissimo cane attore già noto al pubblico televisivo americano per aver interpretato Eddie nella celebre sitcom ''Frasier''.', 'Archivio ufficiale dei crediti animali di Hollywood', TRUE, 'IA (Daily Sync)', 'IA Verificata', 0, 2, '2026-11-02T14:50:54.053613+00:00'),
('ebc2fdab-88e4-41d4-9ce0-56a0ec683a93', 335, 'Citazioni & Easter Egg', 'Il nome della cittadina fittizia', 'Nel film, la cittadina in cui si trasferisce Mort si chiama Tashmore, un chiaro omaggio e un anagramma parziale della vera location delle riprese, Lake Tashmoo, scelto appositamente dal regista David Koepp per mantenere una connessione geografica interna.', 'Commento audio del regista David Koepp', TRUE, 'IA (Daily Sync)', 'IA Verificata', 0, 3, '2026-11-02T14:50:54.053613+00:00'),
('7272ec30-a433-42b0-bfd8-75df24e5e540', 335, 'Effetti speciali & Trucco', 'L''uso limitato della CGI', 'Il regista David Koepp ha voluto ridurre al minimo l''uso della grafica computerizzata, preferendo effetti pratici sul set come la costruzione di muri reali per la scena in cui la casa crolla parzialmente nel finale.', 'Intervista al supervisore degli effetti speciali sul set', TRUE, 'IA (Daily Sync)', 'IA Verificata', 0, 4, '2026-11-02T14:50:54.053613+00:00'),
('556e173c-7dd5-42bb-95e9-5897a5600094', 337, 'Casting & Scelte', 'La doppiatrice di Satana', 'Poiché la voce di Rosalinda Celentano (Satana) fu ritenuta troppo roca e profonda da Mel Gibson, in post-produzione si decise di doppiarla. La voce definitiva fu quella dell''attrice e doppiatrice Laura Boccanera.', 'Note di produzione e interviste ufficiali al doppiaggio italiano', TRUE, 'IA (Daily Sync)', 'IA Verificata', 0, 0, '2026-11-02T14:51:02.736239+00:00'),
('c457fd67-e311-4465-8ad5-e94f4d555c80', 337, 'Segreti di produzione', 'Il rifiuto di finanziamento e i fondi personali', 'Nessuna major di Hollywood volle finanziare il progetto per via della violenza e dell''uso delle lingue morte. Mel Gibson ha investito circa 30 milioni di dollari dei suoi risparmi personali attraverso la sua casa di produzione, la Icon Productions.', 'Documentario ''The Making of The Passion of the Christ''', TRUE, 'IA (Daily Sync)', 'IA Verificata', 0, 1, '2026-11-02T14:51:02.736239+00:00'),
('c01c4de6-456d-4661-b1eb-7dc7081f33f6', 337, 'Aneddoti dal set', 'La polmonite di Jim Caviezel', 'Durante le riprese della scena della crocifissione girate sul freddo altopiano di Matera, Jim Caviezel ha contratto la polmonite a causa delle temperature rigide e del vento sferzante, oltre a soffrire di ipotermia.', 'Intervista a Jim Caviezel per The Hollywood Reporter', TRUE, 'IA (Daily Sync)', 'IA Verificata', 0, 2, '2026-11-02T14:51:02.736239+00:00'),
('6b886b79-4aa0-44a4-a175-1baae602dc31', 337, 'Segreti di produzione', 'La scelta della pellicola e della fotografia', 'Il direttore della fotografia Caleb Deschanel e Mel Gibson si sono ispirati ai dipinti del Caravaggio, in particolare per l''uso marcato del chiaroscuro. Hanno utilizzato lenti Panavision e tecniche di desaturazione del colore per conferire alla pellicola un aspetto da antico manoscritto.', 'American Cinematographer Magazine, intervista a Caleb Deschanel', TRUE, 'IA (Daily Sync)', 'IA Verificata', 0, 3, '2026-11-02T14:51:02.736239+00:00'),
('bab16c5a-db4f-4df8-bf58-46f49a27c7aa', 337, 'Effetti speciali & Trucco', 'La finta ferita da taglio alla mano', 'Per la scena in cui Gesù viene inchiodato alla croce, gli addetti agli effetti speciali guidati da Keith VanderLaan hanno creato una finta mano in legno e silicone collegata a un tubo per il sangue finto, mentre Caviezel teneva la sua vera mano nascosta dietro il supporto.', 'Special Effects Featurette nel DVD ufficiale', TRUE, 'IA (Daily Sync)', 'IA Verificata', 0, 4, '2026-11-02T14:51:02.736239+00:00'),
('a4a395f6-fabe-4ad1-9355-bb99af483ece', 337, 'Citazioni & Easter Egg', 'Le mani del regista sulla croce', 'Le mani che appaiono in primo piano mentre piantano il primo chiodo nelle mani di Gesù durante la scena della crocifissione non sono quelle dell''attore che interpreta il soldato romano, bensì quelle dello stesso regista Mel Gibson.', 'Commento audio del regista nel Blu-ray del film', TRUE, 'IA (Daily Sync)', 'IA Verificata', 0, 5, '2026-11-02T14:51:02.736239+00:00'),
('0998832d-b049-47ee-b7b7-12da4cb9c9cf', 304, 'Casting & Scelte', 'La scelta di Marion Cotillard ispirata da La vie en rose', 'Woody Allen ha scritto specificamente il personaggio di Adriana pensando a Marion Cotillard, dopo essere rimasto folgorato dalla sua interpretazione premio Oscar in ''La vie en rose'' (2007). L''attrice francese ha accettato la parte senza esitazione, diventando il fulcro emotivo della nostalgia parigina del protagonista.', 'Note di produzione ufficiali del film', TRUE, 'IA (Daily Sync)', 'IA Verificata', 0, 0, '2026-11-02T14:52:48.015481+00:00'),
('619a9bc8-7627-4447-9946-c9a859261798', 304, 'Segreti di produzione', 'La cicogna portafortuna e l''eredità visiva di Darius Khondji', 'Il direttore della fotografia Darius Khondji ha ottenuto la straordinaria resa visiva dorata della Parigi notturna utilizzando una combinazione di pellicola tradizionale e cineprese digitali di ultima generazione. La celebre sequenza d''apertura, un vero e proprio montaggio di cartoline viventi della città, è stata girata interamente durante l''ora d''oro mattutina e serale per evitare l''uso di filtri artificiali in post-produzione.', 'Intervista tecnica a Darius Khondji su American Cinematographer', TRUE, 'IA (Daily Sync)', 'IA Verificata', 0, 1, '2026-11-02T14:52:48.015481+00:00'),
('a4ecef9c-4773-419a-b7d3-ced00d17e562', 304, 'Curiosità & Retroscena', 'La statuetta dell''Oscar come miglior sceneggiatura originale', 'Il film ha fruttato a Woody Allen il quarto Academy Award per la migliore sceneggiatura originale, stabilendo un record personale per il regista che tuttavia, come sua abitudine consolidata, non si è presentato alla cerimonia di premiazione a Los Angeles, preferendo rimanere a suonare il clarinetto in un locale jazz a New York.', 'Archivio ufficiale dell''Academy of Motion Picture Arts and Sciences', TRUE, 'IA (Daily Sync)', 'IA Verificata', 0, 2, '2026-11-02T14:52:48.015481+00:00'),
('30bbc145-a616-4745-b718-559e57a75192', 304, 'Aneddoti dal set', 'Il cameo mancato di Marion Cotillard al Festival di Cannes', 'La prima mondiale del film è avvenuta fuori concorso come film d''apertura del 64º Festival di Cannes nel maggio 2011. Durante la conferenza stampa, Marion Cotillard ha raccontato di come Woody Allen le avesse concesso totale libertà nell''interpretare le sfumature emotive di una donna divisa tra due epoche diverse.', 'Conferenza stampa ufficiale del Festival di Cannes 2011', TRUE, 'IA (Daily Sync)', 'IA Verificata', 0, 3, '2026-11-02T14:52:48.015481+00:00'),
('cc6a092f-620f-4520-a94c-807281a4257d', 304, 'Segreti di produzione', 'La sartoria d''epoca e i costumi di Sonia Grande', 'La costumista Sonia Grande ha dovuto realizzare o reperire centinaia di abiti d''epoca originali per ricreare con precisione filologica sia la moda borghese degli anni 2010 sia lo sfarzo bohémien degli anni ''20 e della Belle Époque. Molti dei vestiti indossati dalle comparse nelle scene nei locali notturni erano autentici capi vintage restaurati per l''occasione.', 'Making-of ufficiale e note della costumista', TRUE, 'IA (Daily Sync)', 'IA Verificata', 0, 4, '2026-11-02T14:52:48.015481+00:00'),
('00874a47-d8f7-45c9-80cb-33a802f67204', 216, 'Curiosità & Retroscena', 'L''ispirazione visiva per l''atmosfera degli anni ''10 e ''20', 'Il direttore della fotografia Lajos Koltai e Giuseppe Tornatore studiarono meticolosamente migliaia di fotografie d''archivio dei transatlantici d''epoca (come il Titanic e la classe Olympic) per definire una palette cromatica calda e dorata che simulasse la patina del tempo e la memoria dei ricordi di Max Tooney.', 'Intervista al direttore della fotografia Lajos Koltai', TRUE, 'IA (Daily Sync)', 'IA Verificata', 0, 4, '2026-11-02T15:47:16.492485+00:00'),
('bca47911-b8a9-44a6-86d2-7fb9f74cb503', 6, 'Effetti speciali & Trucco', 'Il trucco dei fazzoletti di carta per le guance di Marlon Brando', 'Per conferire a Don Vito Corleone l''aspetto di un bulldog con la mascella pesante, Marlon Brando non si affidò a pesanti protesi in lattice. Durante il provino utilizzò dei semplici batuffoli di cotone e fazzoletti di carta per riempire la bocca e spingere in fuori le guance, un accorgimento perfezionato successivamente dal truccatore Dick Smith con un apparecchio dentario in resina acrilica personalizzato.', 'Memorie del truccatore Dick Smith', TRUE, 'IA (Daily Sync)', 'IA Verificata', 0, 1, '2026-11-02T14:53:00.382327+00:00'),
('a6a0733e-e6e6-469a-aced-e69fe30e76a4', 6, 'Aneddoti dal set', 'La vera ferita da sparo a Carlo Rizzi', 'Nella sequenza in cui Michael Corleone strangola e uccide il cognato Carlo Rizzi (interpretato da Gianni Russo), per la scena della morte in cui Carlo sfonda il parabrezza di un''auto, lo stuntman e l''attore subirono piccoli infortuni a causa della violenza dell''azione. Gianni Russo riportò realmente alcune contusioni e un costola incrinata durante la lotta furibonda sul sedile posteriore.', 'Interviste retrospettive a Gianni Russo', TRUE, 'IA (Daily Sync)', 'IA Verificata', 0, 2, '2026-11-02T14:53:00.382327+00:00'),
('79ca3384-31a6-43ba-8c4e-b9b94f040e99', 6, 'Aneddoti dal set', 'Il gatto randagio trovato negli studi della Paramount', 'Il celebre micio grigio che Marlon Brando accarezza amorevolmente nella prima scena del film, mentre riceve le suppliche del becchino Bonasera, non faceva parte del copione né era un animale addestrato. Francis Ford Coppola trovò il gatto randagio aggirarsi tra i teatri di posa della Paramount a New York e lo mise direttamente tra le braccia di Brando all''ultimo momento.', 'Commento audio del regista Francis Ford Coppola (Edizione Blu-ray)', TRUE, 'IA (Daily Sync)', 'IA Verificata', 0, 3, '2026-11-02T14:53:00.382327+00:00'),
('ecd206f7-5b40-4e26-b9fd-0b28afd1fb22', 224, 'Casting & Scelte', 'Il licenziamento di Anthony Mann', 'Il regista Anthony Mann fu licenziato dal produttore e protagonista Kirk Douglas dopo appena una settimana di riprese, poiché Douglas riteneva che il regista mancasse del polso necessario per gestire una produzione kolossal di tale portata e non fosse all''altezza delle scene di battaglia iniziali.', 'Autobiografia di Kirk Douglas ''The Ragman''s Son''', TRUE, 'IA (Daily Sync)', 'IA Verificata', 0, 0, '2026-11-02T15:47:27.140716+00:00'),
('aaeda1ea-fd85-4292-9ae9-b0049aebb96d', 6, 'Effetti speciali & Trucco', 'Il sangue finto ricavato da sciroppo e colorante', 'Per la brutale scena dell''omicidio di Sonny Corleone al casello autostradale, in cui viene crivellato da decine di colpi d''arma da fuoco, la troupe utilizzò sacchetti di sangue finto collegati a microcariche esplosive applicate sul corpo di James Caan. Il sangue era una semplice miscela economica a base di sciroppo di mais e colorante alimentare rosso.', 'Making-of ufficiale ''The Godfather: A Look Inside''', TRUE, 'IA (Daily Sync)', 'IA Verificata', 0, 5, '2026-11-02T14:53:00.382327+00:00'),
('d91949d6-0b9e-42ca-a080-ba150426d970', 6, 'Casting & Scelte', 'Orson Welles scartato per il ruolo di Don Vito', 'Prima che Marlon Brando ottenesse la parte, e prima che la produzione si convincesse a puntare su di lui, Francis Ford Coppola e il produttore Al Ruddy presero seriamente in considerazione il leggendario regista e attore Orson Welles per il ruolo del patriarca Vito Corleone. La Paramount tuttavia oppose un veto deciso temendo il carattere imprevedibile di Welles.', 'Archivi storici della Paramount Pictures', TRUE, 'IA (Daily Sync)', 'IA Verificata', 0, 6, '2026-11-02T14:53:00.382327+00:00'),
('ed830b93-e017-483c-9fac-7e8e54714ea9', 6, 'Segreti di produzione', 'La scena del ristorante girata a Little Italy con veri mafiosi', 'La drammatica sequenza in cui Michael Corleone uccide il poliziotto corrotto McCluskey e il boss Sollozzo nel ristorante di Louis fu girata in un vero locale di Manhattan. Durante la lavorazione, la troupe notò la presenza costante di figure legate alla criminalità organizzata locale che osservavano rispettose le riprese, offrendo persino consigli non richiesti sulla naturalezza dei gesti mafiosi.', 'Libro ''The Godfather Notebook'' di Francis Ford Coppola', TRUE, 'IA (Daily Sync)', 'IA Verificata', 0, 7, '2026-11-02T14:53:00.382327+00:00'),
('bd0acf89-261c-40d3-b16d-1f96f91f664b', 6, 'Casting & Scelte', 'Il rifiuto iniziale di Al Pacino e il quasi licenziamento', 'Al Pacino era inizialmente impegnato sul set del film ''Panico a Needle Park'' e, non credendo che Coppola lo volesse veramente contro il volere dello studio, cercò in tutti i modi di ritirarsi dal progetto. Nelle prime due settimane di riprese de ''Il Padrino'', i dirigenti della Paramount visionarono i giornalieri e pretesero il licenziamento in tronco di Pacino, salvato solo in extremis da Coppola che montò in fretta la sequenza del ristorante girata a Brooklyn.', 'Interviste biografiche ad Al Pacino e Francis Ford Coppola', TRUE, 'IA (Daily Sync)', 'IA Verificata', 0, 8, '2026-11-02T14:53:00.382327+00:00'),
('fb0c9f2a-153f-49cf-83f2-88a340aa17a7', 97, 'Casting & Scelte', 'La scelta iniziale di George Walsh', 'Inizialmente la Goldwyn Pictures aveva scelto l''attore George Walsh per il ruolo di Judah Ben-Hur, ma quando Louis B. Mayer subentrò nella gestione della neonata Metro-Goldwyn-Mayer, decise che Walsh non aveva il carisma necessario e impose la sua sostituzione con Ramon Novarro.', 'Archivi storici MGM e biografie di Louis B. Mayer', TRUE, 'IA (Daily Sync)', 'IA Verificata', 0, 0, '2026-11-02T14:53:14.671865+00:00'),
('f5337a6f-2090-4205-956c-3f4149376b35', 97, 'Effetti speciali & Trucco', 'L''uso pionieristico del Technicolor a due colori', 'Il film fa uso di sequenze girate con il processo Technicolor a due colori, in particolare per la sequenza della Creazione e per la scena della Natività, offrendo agli spettatori dell''epoca uno dei primi impatti significativi con il cinema a colori.', 'Note di restauro della Turner Entertainment e registri di produzione', TRUE, 'IA (Daily Sync)', 'IA Verificata', 0, 1, '2026-11-02T14:53:14.671865+00:00'),
('96eecd8d-fb12-49d0-85f7-1cb43d46f616', 97, 'Aneddoti dal set', 'La troupe bloccata a Livorno per la battaglia navale', 'Le riprese della battaglia navale richiesero la costruzione di enormi repliche di galee romane al largo di Livorno, dove la troupe americana rimase bloccata per mesi a causa delle avverse condizioni meteorologiche del Mar Ligure.', 'Diari di produzione di 1925 e resoconti della stampa italiana dell''epoca', TRUE, 'IA (Daily Sync)', 'IA Verificata', 0, 2, '2026-11-02T14:53:14.671865+00:00'),
('c352e35c-d037-4a68-8d12-362310816474', 224, 'Curiosità & Retroscena', 'L''arrivo di Stanley Kubrick', 'Dopo il licenziamento di Anthony Mann, Kirk Douglas scelse il trentunenne Stanley Kubrick, con cui aveva già lavorato in ''Orizzonti di gloria'', per subentrare alla regia, sebbene Kubrick non avesse alcun controllo creativo sulla sceneggiatura o sulle decisioni produttive.', 'Note di produzione e biografie storiche di Stanley Kubrick', TRUE, 'IA (Daily Sync)', 'IA Verificata', 0, 1, '2026-11-02T15:47:27.140716+00:00'),
('fa2e0cda-4cb0-466e-844b-ab7497e8a2f2', 11, 'Aneddoti dal set', 'La scelta dei vestiti senza pantaloni di Sean Connery', 'Durante le riprese della scena nel dirigibile in cui Indiana Jones e suo padre discutono, faceva un calore soffocante sul set a causa delle luci. Sean Connery decise di girare l''intera sequenza seduto senza pantaloni, indossando solo la camicia e la giacca, per poi sorprendere la troupe alzandosi in piedi alla fine di un ciak.', 'Commento audio del regista Steven Spielberg e documentario ufficiale del film', TRUE, 'IA (Daily Sync)', 'IA Verificata', 0, 0, '2026-11-02T14:53:05.873782+00:00'),
('8c86f1fc-5bbc-4ce0-92b1-a870db14abe7', 11, 'Casting & Scelte', 'River Phoenix scelto direttamente da Harrison Ford', 'River Phoenix fu fortemente voluto da Harrison Ford per interpretare il giovane Indiana Jones nella sequenza iniziale del treno circense. I due avevano già lavorato insieme nel film ''Mosquito Coast'' (1986), e Ford rimase colpito dalla straordinaria somiglianza fisica e dalla capacità di Phoenix di replicare le sue stesse movenze.', 'Note di produzione e interviste d''archivio di Steven Spielberg', TRUE, 'IA (Daily Sync)', 'IA Verificata', 0, 1, '2026-11-02T14:53:05.873782+00:00'),
('ce20e1f1-e929-4466-b2a9-9ebaa7a72df2', 11, 'Aneddoti dal set', 'L''improvvisazione della battuta sui pantaloni di Elsa', 'La celebre battuta in cui Henry Jones Sr. (Sean Connery) esclama ''Ero convinto che fossi tu!'' dopo aver scoperto che Elsa (Alison Doody) è un''agente nazista, seguita dalla reazione imbarazzata di Indy che ricorda come anche lui sia stato con lei, fu in gran parte improvvisata sul set per accentuare il disagio comico tra padre e figlio.', 'Libro ''The Complete Making of Indiana Jones'' di J.W. Rinzler', TRUE, 'IA (Daily Sync)', 'IA Verificata', 0, 2, '2026-11-02T14:53:05.873782+00:00'),
('cf462433-7665-49b5-ad11-2d05b28bc7b8', 11, 'Effetti speciali & Trucco', 'I ratti di gomma per la sequenza nelle catacombe di Venezia', 'Per la scena nelle catacombe veneziane invase dai ratti, la produzione non poté usare animali veri in numero sufficiente per ragioni logistiche e di sicurezza. Vennero quindi realizzati migliaia di ratti di gomma e pelliccia sintetica, mescolati a un numero ristretto di ratti vivi addestrati.', 'Documentario ''The Making of Indiana Jones and the Last Crusade''', TRUE, 'IA (Daily Sync)', 'IA Verificata', 0, 3, '2026-11-02T14:53:05.873782+00:00'),
('25551861-e0da-437a-9d97-b67d10fce125', 11, 'Citazioni & Easter Egg', 'Il tributo a James Bond nella scelta di Sean Connery', 'George Lucas e Steven Spielberg vollero Sean Connery per il ruolo del padre di Indy specificamente perché il personaggio di James Bond era stato una delle principali fonti d''ispirazione per la creazione dello stesso Indiana Jones. Nella scena in cui Henry e Indy fuggono in auto dalla tenuta nazista, la sequenza in cui Connery spara all''aereo nemico con un ombrello richiama apertamente le atmosfere di 007.', 'Special TV ''Indiana Jones: Making the Trilogy''', TRUE, 'IA (Daily Sync)', 'IA Verificata', 0, 4, '2026-11-02T14:53:05.873782+00:00'),
('881baefe-1f4c-4b99-a519-af7e7969cb21', 11, 'Segreti di produzione', 'La cicatrice sul mento di Harrison Ford spiegata da River Phoenix', 'Nella sequenza iniziale del film, il giovane Indiana Jones si procura la celebre cicatrice sul mento usando una frusta e colpendosi accidentalmente. Questo fu un espediente ideato per spiegare sullo schermo la vera cicatrice che Harrison Ford si era procurato in un incidente d''auto in gioventù.', 'Archivio di produzione Lucasfilm e note del casting', TRUE, 'IA (Daily Sync)', 'IA Verificata', 0, 5, '2026-11-02T14:53:05.873782+00:00'),
('aa3341b5-bf2e-41ca-a1ba-b97916382b46', 11, 'Curiosità & Retroscena', 'Il vero nome del cane di George Lucas', 'Sebbene l''origine del nome del cane sia nota, la troupe sul set chiamava scherzosamente Harrison Ford con il nome del cane durante le pause delle riprese nelle location desertiche in Spagna e in Giordania, alimentando l''ilarità generale.', 'Diario di produzione e interviste al cast', TRUE, 'IA (Daily Sync)', 'IA Verificata', 0, 6, '2026-11-02T14:53:05.873782+00:00'),
('09ed5f4a-720b-4e04-8df0-68a7dbddf87a', 11, 'Casting & Scelte', 'La scelta rifiutata di Gregory Peck', 'Prima che Sean Connery accettasse la parte di Henry Jones Sr., Steven Spielberg aveva preso in seria considerazione il leggendario attore Gregory Peck per il ruolo, ma l''accordo non andò in porto.', 'Biografia ufficiale di Steven Spielberg', TRUE, 'IA (Daily Sync)', 'IA Verificata', 0, 7, '2026-11-02T14:53:05.873782+00:00'),
('a288728a-508e-4321-9f6e-842680d381f4', 114, 'Curiosità & Retroscena', 'La parolaccia più pronunciata della storia del cinema', 'Nel copione originale dei fratelli Coen, la parola ''fuck'' e le sue varianti venivano pronunciate esattamente 292 volte, stabilendo all''epoca un record per un film distribuito da una major hollywoodiana. Solo la parola ''Dude'' (Drugo) e i suoi derivati compaiono ancora più frequentemente nel dialogo, con circa 290 occorrenze totali.', 'Note di produzione ufficiali PolyGram Filmed Entertainment', TRUE, 'IA (Daily Sync)', 'IA Verificata', 0, 0, '2026-11-02T14:53:20.398053+00:00'),
('e1580f3a-abdb-4210-9faa-9e910f88e0a3', 114, 'Aneddoti dal set', 'Il maglione iconico trovato in un negozio dell''usato', 'Il celebre cardigan marrone con motivo geometrico indossato da Jeff Bridges per gran parte del film non proviene dal reparto costumi di Hollywood, ma è stato acquistato direttamente dalla costumista Mary Zophres in un negozio di abbigliamento usato a Los Angeles prima dell''inizio delle riprese.', 'Intervista alla costumista Mary Zophres per Entertainment Weekly', TRUE, 'IA (Daily Sync)', 'IA Verificata', 0, 1, '2026-11-02T14:53:20.398053+00:00'),
('3ecda390-1a99-4a84-b72d-a399093111fe', 114, 'Aneddoti dal set', 'Il vero passatempo dei nichilisti sul set', 'Gli attori Peter Stormare, Torsten Voges e Flea (bassista dei Red Hot Chili Peppers), che interpretano il trio di temibili nichilisti, trascorrevano gran parte dei momenti di pausa tra un ciak e l''altro esercitandosi a pronunciare barzellette in tedesco maccheronico e a imitare i versi delle anatre.', 'Dietro le quinte del DVD ufficiale Universal Pictures', TRUE, 'IA (Daily Sync)', 'IA Verificata', 0, 2, '2026-11-02T14:53:20.398053+00:00'),
('83cea33d-aa74-4494-af09-46bdcf09bf5b', 114, 'Casting & Scelte', 'La maglietta di Jeff Bridges apparteneva all''attore', 'La t-shirt grigia a maniche corte con la scritta della squadra di baseball ''Honolulu'' indossata da Jeff Bridges in diverse scene del film non era un capo di scena, bensì una maglietta personale che l''attore possedeva e utilizzava regolarmente nella vita reale fin dagli anni settanta.', 'Audio commento del cast all''edizione speciale Blu-ray', TRUE, 'IA (Daily Sync)', 'IA Verificata', 0, 3, '2026-11-02T14:53:20.398053+00:00'),
('eae6272b-0b09-44fb-938c-066969dc2e2b', 114, 'Effetti speciali & Trucco', 'La sequenza onirica del bowling e la sposa volante', 'La complessa sequenza del secondo sogno di Drugo, in cui questi vola sopra una pista da bowling gigante indossando una scarpa da bowling come mantello, è stata realizzata combinando riprese dal vero su schermo blu, modellini in scala ridotta costruiti artesanalmente e grafiche digitali all''avanguardia per l''epoca.', 'Documentario ''The Lebowski Saga: Making of''', TRUE, 'IA (Daily Sync)', 'IA Verificata', 0, 4, '2026-11-02T14:53:20.398053+00:00'),
('8bb8230f-a173-48af-9297-e3df06258d25', 114, 'Casting & Scelte', 'Il cameo tagliato di David Thewlis e la telefonata a Maude', 'L''attore britannico David Thewlis, che interpreta il misterioso videomaker e agente immobiliare Knox Harrington, ha girato una scena aggiuntiva in cui incontra Drugo in un caffè di Malibu, ma la sequenza fu tagliata in fase di montaggio finale per migliorare il ritmo narrativo della seconda metà del film.', 'Scene tagliate dell''edizione Criterion Collection', TRUE, 'IA (Daily Sync)', 'IA Verificata', 0, 5, '2026-11-02T14:53:20.398053+00:00'),
('a4ad5533-fcc5-41b9-a0b7-3d346f1e5379', 114, 'Aneddoti dal set', 'Le scarpe da bowling reali di John Goodman', 'John Goodman ha insistito per indossare le sue personali scarpe da bowling e per usare una palla da bowling personalizzata durante tutte le scene girate all''interno della sala da bowling, rifitandosi di utilizzare i modelli generici forniti dal reparto oggetti di scena.', 'Intervista a John Goodman per Rolling Stone', TRUE, 'IA (Daily Sync)', 'IA Verificata', 0, 6, '2026-11-02T14:53:20.398053+00:00'),
('d61a7270-5668-451a-9c5b-56f2d7035e99', 58, 'Segreti di produzione', 'Le riprese simultanee con il terzo capitolo', 'Per ottimizzare i costi e gestire gli impegni mastodontici del cast, ''Pirati dei Caraibi - La maledizione del forziere fantasma'' e il successivo ''Ai confini del mondo'' sono stati girati contemporaneamente, in un''unica imponente produzione continua iniziata nel febbraio 2005 e terminata nel settembre dello stesso anno.', 'Comunicato stampa ufficiale Walt Disney Pictures', TRUE, 'IA (Daily Sync)', 'IA Verificata', 0, 3, '2026-11-02T14:53:10.897795+00:00'),
('6e3353a6-ff13-46f1-868e-f3d9f7b62a7a', 58, 'Segreti di produzione', 'La costruzione fisica dell''Olandese Volante', 'La nave spettrale di Davy Jones, l''Olandese Volante, non è stata ricreata interamente in computer grafica. La produzione ha fatto costruire una struttura galleggiante semovente a grandezza naturale, posizionata in mare aperto e montata su una chiatta speciale per consentire le riprese delle scene navali.', 'Making-of ufficiale nel DVD edizione speciale', TRUE, 'IA (Daily Sync)', 'IA Verificata', 0, 4, '2026-11-02T14:53:10.897795+00:00'),
('e06df5b9-5d77-4ccf-93c9-46d5bf17a225', 58, 'Effetti speciali & Trucco', 'L''ispirazione culinaria per il Kraken', 'Per studiare i movimenti fluidi, scivolosi e realistici dei tentacoli del Kraken, gli animatori della ILM hanno analizzato ore di filmati documentari sui calamari giganti e persino studiato il comportamento di parti di polpo acquistate al mercato locale del pesce.', 'Featurette sugli effetti speciali della ILM', TRUE, 'IA (Daily Sync)', 'IA Verificata', 0, 5, '2026-11-02T14:53:10.897795+00:00'),
('06d8fb3d-c5ab-4f42-a0e3-6bb4e526320a', 58, 'Casting & Scelte', 'Il cameo tagliato di Keith Richards nel secondo film', 'Il leggendario chitarrista dei Rolling Stones Keith Richards, la cui iconica gestualità ha ispirato la creazione del personaggio di Jack Sparrow da parte di Johnny Depp, avrebbe dovuto fare un cameo in questo secondo capitolo nel ruolo del padre di Jack, Teague. Tuttavia, a causa di conflitti di programmazione con il tour mondiale della band, la sua apparizione fu rimandata al terzo film.', 'Intervista ufficiale a Gore Verbinski e Johnny Depp', TRUE, 'IA (Daily Sync)', 'IA Verificata', 0, 6, '2026-11-02T14:53:10.897795+00:00'),
('cfcf2837-9f4e-46f3-bedd-b76e0453d813', 58, 'Aneddoti dal set', 'Le riprese ininterrotte alle Bahamas e a Dominica', 'La troupe ha affrontato condizioni climatiche estremamente avverse durante le riprese nelle isole di Dominica e delle Bahamas, venendo colpita da violenti temporali tropicali che hanno danneggiato diverse scenografie e costretto la produzione a costanti ricalendarizzazioni del piano di lavorazione.', 'Diario di bordo della produzione e note di regia', TRUE, 'IA (Daily Sync)', 'IA Verificata', 0, 7, '2026-11-02T14:53:10.897795+00:00'),
('6560f35e-6ad7-4d69-9038-fdef5a876272', 217, 'Casting & Scelte', 'La genesi del cane cyborg e la partecipazione di Stephen "Twitch" Boss', 'Il compianto ballerino e attore Stephen "Twitch" Boss ha ottenuto il ruolo di uno dei membri della gang di cyborg a Mos Espa dopo che Robert Rodriguez lo aveva notato per il suo straordinario talento fisico, integrando le sue movenze uniche nella caratterizzazione del personaggio.', 'Note di produzione ufficiali di Disney+', TRUE, 'IA (Daily Sync)', 'IA Verificata', 0, 0, '2026-11-02T15:47:18.733982+00:00');
